package lower

import "github.com/system-inc/adamic/internal/ir"

// borrow marks which reference parameters are borrowed (docs/memory.md, "Borrowed parameters").
//
// The caller already keeps every argument alive to the end of its statement, and every place that
// keeps a reference past its statement takes a count of its own. So a parameter needs its own count
// only when something writes it, since a write releases the old value and that one is the caller's,
// or when it belongs to a closure: map's loop hands a callback its element unretained, and the
// callback may overwrite that element. Everything else is borrowed: a named function's or a
// method's reference parameters, this included, that no ir.Assign anywhere in the program writes.
//
// Parameters in a shared frame environment need owned treatment, even when read-only:
// initializing that owned slot is a store, and an escaping closure keeps it after the call.
// ir.Assign is the only statement that writes a local that already exists, and locals are numbered
// across the whole program, so a closure writing a parameter through its cell is found too.
func borrow(program *ir.Program) {
	assigned := map[int]bool{}
	for _, function := range program.Functions {
		findAssigned(function.Body, assigned)
	}
	findAssigned(program.Main, assigned)
	for _, function := range program.Functions {
		if function.Closure {
			continue
		}
		for _, parameter := range function.Parameters {
			local := &program.Locals[parameter]
			local.Borrowed = local.Type.IsReference() && !local.EnvironmentCell && !assigned[parameter]
		}
	}
}

// findAssigned adds every local an ir.Assign in statements writes, however deeply nested: walk goes
// into every statement that holds others (a try's body, catch and finally among them), so one added
// to the IR later isn't missed, as a hand-written list missed try.
func findAssigned(statements []ir.Statement, assigned map[int]bool) {
	walk(statements, func(node any) bool {
		if assign, ok := node.(ir.Assign); ok {
			assigned[assign.Local] = true
		}
		return true
	})
}

case_label.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// caseLabel uses an imported const's declared type, rather than a narrowing at this read. Its
// module has run before the importing module, and import cycles are refused, so folding the label
// preserves initialization and its effects. Other reads retain their ordinary runtime checks.
func (l *lowering) caseLabel(node *ast.Node) (ir.Expression, error) {
	name := ast.SkipParentheses(node)
	if name.Kind != ast.KindIdentifier {
		return l.expression(node)
	}
	symbol := l.checker.GetSymbolAtLocation(name)
	if symbol == nil || symbol.Flags&ast.SymbolFlagsAlias == 0 {
		return l.expression(node)
	}
	symbol = l.symbol(name)
	for _, declaration := range symbol.Declarations {
		if declaration.Kind != ast.KindVariableDeclaration || declaration.Parent == nil || declaration.Parent.Flags&ast.NodeFlagsConst == 0 || declaration.AsVariableDeclaration().Initializer == nil {
			continue
		}
		proven := l.checker.GetTypeOfSymbol(symbol)
		if proven.Flags()&(checker.TypeFlagsNumberLiteral|checker.TypeFlagsStringLiteral) != 0 {
			if constant, _, known := l.literalConstant(proven); known {
				return constant, nil
			}
		}
		return nil, l.notYet(name, "a case label using const "+declaration.Name().Text()+" with type "+l.checker.TypeToString(proven)+" (not a number or string literal type)")
	}
	return l.expression(node)
}

cast.go:
package lower

import (
	"reflect"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// cast lowers value as T. as const and a cast to a type the value already has (an upcast) are the
// value itself. A downcast to members of a discriminated union is checked at runtime: the tag is
// there to read. Any other cast is a type the compiler would have to trust, and 0.1 refuses it
// (adamic/no-unchecked-cast).
func (l *lowering) cast(node *ast.Node) (ir.Expression, error) {
	as := node.AsAsExpression()
	proof, err := l.castProof(node)
	if err != nil {
		return nil, err
	}
	source := l.concrete(l.checker.GetTypeAtLocation(as.Expression))
	target := l.concrete(l.checker.GetTypeAtLocation(node))
	if !l.sameKeeping(source, target, map[[2]*checker.Type]bool{}) {
		return nil, l.notYet(node, "a cast that changes the runtime representation or ownership of a reference")
	}
	value, err := l.expression(as.Expression)
	if err != nil {
		return nil, err
	}
	if proof.structuralView {
		return l.structuralViewCast(node, value, source, target)
	}
	if proof.interfaceView {
		return l.interfaceCast(node, value, l.concrete(l.checker.GetTypeAtLocation(as.Expression)), l.concrete(l.checker.GetTypeAtLocation(node)))
	}
	if len(proof.allowed) == 0 && len(proof.classes) == 0 {
		return value, nil
	}
	refused := &Refused{Where: l.program.Where(node), What: "a cast without an object tag representation", Fix: castRepair}
	if value.Type() != ir.Object {
		return nil, refused
	}
	message := "cast failed: this " + l.checker.TypeToString(source) + " is not a " + l.checker.TypeToString(target)
	if len(proof.classes) > 0 {
		return l.checkedClassCast(node, value, proof.classes, message)
	}
	cast := ir.CheckedCast{Value: value, Field: proof.field, Message: message}
	for _, literal := range proof.allowed {
		allowed, fieldType, constant := l.literalConstant(literal)
		if !constant || (cast.FieldType != 0 && cast.FieldType != fieldType) {
			return nil, refused
		}
		cast.Allowed = append(cast.Allowed, allowed)
		cast.FieldType = fieldType
	}
	if _, err := l.view(node, value, target); err != nil {
		return nil, err
	}
	cast.CheckedFields = true
	return cast, nil
}

// fieldLiteral is a member's type for a field when it's a single literal ('Circle', 1, true), the
// kind of field a runtime check can read the member from.
func (l *lowering) fieldLiteral(member *checker.Type, field string) *checker.Type {
	for _, property := range l.checker.GetPropertiesOfType(member) {
		if property.Name != field {
			continue
		}
		fieldType := l.checker.GetTypeOfSymbol(property)
		if fieldType.Flags()&(checker.TypeFlagsStringLiteral|checker.TypeFlagsNumberLiteral|checker.TypeFlagsBooleanLiteral) != 0 {
			return fieldType
		}
	}
	return nil
}

// literalConstant is a literal type as a constant to compare a field with.
func (l *lowering) literalConstant(literal *checker.Type) (ir.Expression, ir.Type, bool) {
	flags := literal.Flags()
	switch {
	case flags&checker.TypeFlagsStringLiteral != 0:
		text, isText := literal.AsLiteralType().Value().(string)
		return ir.StringConstant{Index: l.constant(text)}, ir.String, isText
	case flags&checker.TypeFlagsNumberLiteral != 0:
		value := reflect.ValueOf(literal.AsLiteralType().Value())
		if value.Kind() != reflect.Float64 {
			return nil, 0, false
		}
		return ir.NumberConstant{Value: value.Float()}, ir.Number, true
	case flags&checker.TypeFlagsBooleanLiteral != 0:
		return ir.BooleanConstant{Value: l.checker.TypeToString(literal) == "true"}, ir.Boolean, true
	}
	return nil, 0, false
}

cast_proof.go:
package lower

import (
	"reflect"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// The proof contains checker types only, so refusals precede representation lowering of unknown
// operands. Concrete generic instantiations are proved again when they are lowered.
type castProof struct {
	structuralView bool
	interfaceView  bool
	field          string
	allowed        []*checker.Type
	classes        []*checker.Type
}

const castRepair = "use a proven upcast, cast a discriminated object union with unique literal or enum tags to members or a sub-union, or downcast along nominal class ancestry (adamic/no-unchecked-cast)"

func (l *lowering) castAssignable(source, target *checker.Type) bool {
	return l.classAssignable(source, target) && l.enumAssignable(source, target) && l.widened(source, target, map[[2]*checker.Type]bool{}) == nil && l.castOptionalFields(source, target, map[[2]*checker.Type]bool{}) && l.optionalRelationFailure(source, target, nil, map[[2]*checker.Type]bool{}) == ""
}

// A structural view can hide an optional field of an incompatible type. Assignability permits
// adding that field back, but a cast cannot prove what the hidden field holds. Follow nested
// readonly views and callable results too; nominal class construction already proves its fields.
func (l *lowering) castOptionalFields(source, target *checker.Type, seen map[[2]*checker.Type]bool) bool {
	pair := [2]*checker.Type{source, target}
	if source == target || seen[pair] || isClassInstance(target) {
		return true
	}
	seen[pair] = true
	defer delete(seen, pair)
	if source.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range source.Types() {
			if !l.castOptionalFields(member, target, seen) {
				return false
			}
		}
		return true
	}
	if target.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range target.Types() {
			if l.checker.IsTypeAssignableTo(source, member) && l.castOptionalFields(source, member, seen) {
				return true
			}
		}
		return false
	}
	if !l.structured(source) || !l.structured(target) {
		return true
	}
	from, to := l.checker.GetSignaturesOfType(source, checker.SignatureKindCall), l.checker.GetSignaturesOfType(target, checker.SignatureKindCall)
	if len(from) == 1 && len(to) == 1 {
		if !l.castOptionalFields(l.checker.GetReturnTypeOfSignature(from[0]), l.checker.GetReturnTypeOfSignature(to[0]), seen) {
			return false
		}
		for index, parameter := range to[0].Parameters() {
			if index < len(from[0].Parameters()) && !l.castOptionalFields(l.checker.GetTypeOfSymbol(parameter), l.checker.GetTypeOfSymbol(from[0].Parameters()[index]), seen) {
				return false
			}
		}
		return true
	}
	if source.Flags()&checker.TypeFlagsObject != 0 && target.Flags()&checker.TypeFlagsObject != 0 && source.ObjectFlags()&checker.ObjectFlagsReference != 0 && target.ObjectFlags()&checker.ObjectFlagsReference != 0 {
		fromArguments, toArguments := l.checker.GetTypeArguments(source), l.checker.GetTypeArguments(target)
		for index, argument := range toArguments {
			if index < len(fromArguments) && !l.castOptionalFields(fromArguments[index], argument, seen) {
				return false
			}
		}
	}
	for _, property := range l.checker.GetPropertiesOfType(target) {
		inside := l.checker.GetPropertyOfType(source, property.Name)
		if inside == nil {
			if property.Flags&ast.SymbolFlagsOptional != 0 {
				return false
			}
			continue
		}
		if !l.castOptionalFields(l.checker.GetTypeOfSymbol(inside), l.checker.GetTypeOfSymbol(property), seen) {
			return false
		}
	}
	return true
}

func castMembers(proven *checker.Type) []*checker.Type {
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		return proven.Types()
	}
	return []*checker.Type{proven}
}

func (l *lowering) castProof(node *ast.Node) (castProof, error) {
	as := node.AsAsExpression()
	if as.Type.Kind == ast.KindTypeReference && ast.IsIdentifier(as.Type.AsTypeReferenceNode().TypeName) && as.Type.AsTypeReferenceNode().TypeName.Text() == "const" {
		return castProof{}, nil
	}
	source := l.concrete(l.checker.GetTypeAtLocation(as.Expression))
	target := l.concrete(l.checker.GetTypeAtLocation(node))
	refused := &Refused{Where: l.program.Where(node), What: "a cast the runtime can't check", Fix: castRepair}
	inner := ast.SkipParentheses(as.Expression)
	if inner.Kind == ast.KindAsExpression && l.checker.GetTypeAtLocation(inner).Flags()&checker.TypeFlagsUnknown != 0 {
		return castProof{}, refused
	}
	if source.Flags()&checker.TypeFlagsAny != 0 || target.Flags()&checker.TypeFlagsAny != 0 {
		return castProof{}, refused
	}
	members, targets := castMembers(source), castMembers(target)
	allClasses := true
	for _, member := range append(append([]*checker.Type{}, members...), targets...) {
		allClasses = allClasses && isClassInstance(member)
	}
	var upcastFailure error
	// A structural assignability result is only an upcast candidate. Nominal
	// downcasts may also look assignable, but still need their runtime identity check.
	if l.checker.IsTypeAssignableTo(source, target) || l.checker.IsTypeAssignableTo(l.checker.GetWidenedType(source), target) {
		err := l.provenRelation(node, as.Expression, l.checker.GetTypeAtLocation(node))
		if err == nil {
			return castProof{}, nil
		}
		rawSource, rawTarget := l.checker.GetTypeAtLocation(as.Expression), l.checker.GetTypeAtLocation(node)
		if !allClasses || l.optionalRelationFailure(rawSource, rawTarget, as.Expression, map[[2]*checker.Type]bool{}) != "" || l.freshOrWidened(as.Expression, rawSource, rawTarget) != nil {
			if reason, ok := err.(*Refused); ok {
				reason.Fix += "; " + castRepair
			}
			return castProof{}, err
		}
		if reason, ok := err.(*Refused); ok {
			reason.Fix += "; " + castRepair
		}
		upcastFailure = err
	}

	if !allClasses && l.checker.IsTypeAssignableTo(source, target) {
		if err := l.refuseWidening(node); err != nil {
			if reason, ok := err.(*Refused); ok {
				reason.Fix += "; " + castRepair
			}
			return castProof{}, err
		}
	}
	if allClasses {
		for _, wanted := range targets {
			related := false
			for _, member := range members {
				if l.castAssignable(wanted, member) && l.nominalAncestor(wanted, member, map[[2]*checker.Type]bool{}) {
					if !l.classCastArguments(member, wanted) {
						return castProof{}, refused
					}
					related = true
				}
				// An erased identity cannot distinguish incompatible arguments of the same
				// generic class, even if another source member provides a valid ancestor.
				if l.classView(member, l.classNodeFor(wanted)) != nil && !l.nominalAncestor(member, wanted, map[[2]*checker.Type]bool{}) {
					return castProof{}, refused
				}
			}
			if !related {
				if upcastFailure != nil {
					return castProof{}, upcastFailure
				}
				return castProof{}, refused
			}
		}
		return castProof{classes: targets}, nil
	}
	if source.Flags()&checker.TypeFlagsUnion == 0 {

		origins := len(l.result.ViewOrigins)
		defer func() { l.result.ViewOrigins = l.result.ViewOrigins[:origins] }()
		if checked, err := l.interfaceCast(node, ir.Read{Of: ir.Object}, source, target); checked != nil || err != nil {
			return castProof{interfaceView: checked != nil}, err
		}
		from, fromKnown := l.representation(source)
		to, toKnown := l.representation(target)
		if source.Flags()&checker.TypeFlagsObject != 0 && target.Flags()&checker.TypeFlagsObject != 0 && fromKnown && toKnown && from == ir.Object && to == ir.Object && !isClassInstance(target) && l.checker.IsTypeAssignableTo(target, source) && l.widened(target, source, map[[2]*checker.Type]bool{}) == nil && len(l.checker.GetIndexInfosOfType(target)) == 0 {
			return castProof{structuralView: true}, nil
		}

		return castProof{}, refused
	}
	if !l.castUnionWrites(source) {
		return castProof{}, refused
	}
	// Checking kind cannot prove a refinement of a member's payload or callback signature.
	for _, wanted := range targets {
		found := false
		for _, member := range members {
			if l.castAssignable(member, wanted) && l.castAssignable(wanted, member) {
				found = true
			}
		}
		if !found {
			return castProof{}, refused
		}
	}
	for _, property := range l.checker.GetPropertiesOfType(members[0]) {
		proof := castProof{field: property.Name}
		literals := []*checker.Type{}
		valid := true
		for _, member := range members {
			literal := l.fieldLiteral(member, proof.field)
			if literal == nil {
				valid = false
				break
			}
			// Enum aliases compare by runtime value, including aliases from different enums.
			for _, previous := range literals {
				mask := checker.TypeFlagsStringLiteral | checker.TypeFlagsNumberLiteral | checker.TypeFlagsBooleanLiteral
				if previous.Flags()&mask != literal.Flags()&mask || reflect.DeepEqual(previous.AsLiteralType().Value(), literal.AsLiteralType().Value()) {
					valid = false
				}
			}
			literals = append(literals, literal)
			if l.castAssignable(member, target) {
				proof.allowed = append(proof.allowed, literal)
			}
		}
		if valid && len(proof.allowed) > 0 {
			return proof, nil
		}
	}
	return castProof{}, refused
}

// Writing through a union view must not change a member's tag or narrow payload promise. A common
// mutable slot is safe only if everything the union can write fits every member that owns it.
func (l *lowering) castUnionWrites(source *checker.Type) bool {
	for _, property := range l.checker.GetPropertiesOfType(source) {
		if l.checker.IsReadonlySymbol(property) || property.Flags&ast.SymbolFlagsMethod != 0 {
			continue
		}
		written := l.checker.GetTypeOfSymbol(property)
		for _, member := range source.Types() {
			inside := l.checker.GetPropertyOfType(member, property.Name)
			if inside == nil || !l.castAssignable(written, l.checker.GetTypeOfSymbol(inside)) {
				return false
			}
		}
	}
	return true
}

// An erased identity proves no type arguments. Every target parameter must survive directly in
// the source ancestor's arguments, so that nominal invariance already fixes it. A Box<T> whose
// base is a nongeneric Animal is uncheckable; Box<number> and Box<string> have the same tag there.
func (l *lowering) classCastArguments(source, target *checker.Type) bool {
	declaration := l.classNodeFor(target)
	if declaration == nil || len(declaration.TypeParameters()) == 0 {
		return true
	}
	view := l.classView(l.checker.GetTypeAtLocation(declaration.Name()), l.classNodeFor(source))
	if view == nil {
		return false
	}
	arguments := l.checker.GetTypeArguments(view)
	for _, parameter := range declaration.TypeParameters() {
		proven := l.checker.GetTypeAtLocation(parameter.Name())
		found := false
		for _, argument := range arguments {
			if argument == proven {
				found = true
			}
		}
		if !found {
			return false
		}
	}
	return true
}

// Ordinary IR exposes the check to both backends and ownership analyses. The operand is one call
// argument; the helper only rereads its parameter, never the source expression.
func (l *lowering) checkedClassCast(node *ast.Node, value ir.Expression, targets []*checker.Type, message string) (ir.Expression, error) {
	identities := []int{}
	for _, target := range targets {
		declaration := l.classNodeFor(target)
		if declaration == nil || declaration.Kind != ast.KindClassDeclaration {
			return nil, &Refused{Where: l.program.Where(node), What: "a cast without a declared class identity", Fix: castRepair}
		}
		if len(declaration.TypeParameters()) > 0 {
			identities = append(identities, l.classIdentity(declaration))
		} else {
			instance, err := l.instantiate(declaration, target, node)
			if err != nil {
				return nil, err
			}
			identities = append(identities, instance.class)
		}
	}
	function := len(l.result.Functions)
	local := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "cast_value", Type: ir.Object, Function: function})
	read := ir.Read{Local: local, Of: ir.Object}
	var condition ir.Expression
	for _, identity := range identities {
		test := ir.InstanceOf{Value: read, Class: identity}
		if condition == nil {
			condition = test
		} else {
			condition = ir.Binary{Operator: ir.Or, Left: condition, Right: test}
		}
	}
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "checked_class_cast", Parameters: []int{local}, Returns: ir.Object, Body: []ir.Statement{
		ir.If{Condition: condition, Then: []ir.Statement{ir.Return{Value: read}}},
		ir.Panic{Message: ir.StringConstant{Index: l.constant(message)}},
	}})
	return ir.Call{Function: function, Arguments: []ir.Expression{value}, Returns: ir.Object}, nil
}

census_coercion.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
	"math"
)

// A coercion call must preserve its receiver and evaluate the original operand once.
// Only a statically promised primitive result can terminate OrdinaryToPrimitive.
func (l *lowering) censusNumberObject(node *ast.Node, value ir.Expression) (ir.Expression, error) {
	proven := l.checker.GetTypeAtLocation(node)
	if value.Type() == ir.Array {
		if !l.checker.IsArrayType(proven) {
			return nil, l.notYet(node, "numeric coercion of a non-array view")
		}
		for _, name := range []string{"valueOf", "toString", "join"} {
			property := l.checker.GetPropertyOfType(proven, name)
			if property != nil {
				for _, declaration := range property.Declarations {
					if !load.IsLibrary(ast.GetSourceFileOfNode(declaration)) {
						return nil, l.notYet(node, "numeric coercion of an array with a custom conversion")
					}
				}
			}
		}
		element, known := l.kept(l.checker.GetElementTypeOfArrayType(proven))
		if !known || (element != ir.Number && element != ir.String && element != ir.Boolean && element != ir.MaybeNumber) {
			return nil, l.notYet(node, "numeric coercion of an array with non-primitive elements")
		}
		joined := ir.ArrayJoin{Array: value, Separator: ir.StringConstant{Index: l.constant(",")}, Element: element}
		return ir.NumberCall{Function: "convert", Arguments: []ir.Expression{joined}}, nil
	}
	if value.Type() != ir.Object {
		return nil, l.notYet(node, "numeric coercion with an unrepresented object conversion")
	}
	index := len(l.result.Functions)
	local := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "coercion_operand", Type: ir.Object, Function: index})
	read := ir.Read{Local: local, Of: ir.Object}
	body := []ir.Statement{}
	for _, name := range []string{"valueOf", "toString"} {
		property := l.checker.GetPropertyOfType(proven, name)
		if property == nil || len(property.Declarations) == 0 || load.IsLibrary(ast.GetSourceFileOfNode(property.Declarations[0])) {
			continue
		}
		for _, declaration := range property.Declarations {
			if declaration.Kind == ast.KindGetAccessor {
				return nil, l.notYet(node, "numeric coercion through a conversion getter")
			}
		}
		signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeOfSymbol(property), checker.SignatureKindCall)
		if len(signatures) != 1 {
			return nil, l.notYet(node, "numeric coercion with a non-callable or overloaded conversion member")
		}
		for _, parameter := range signatures[0].Parameters() {
			takes := l.censusCallableParameterType(parameter)
			if !l.censusRelated(l.checker.GetUndefinedType(), takes) {
				return nil, l.notYet(node, "numeric coercion invoking a required conversion parameter")
			}
		}
		result := l.checker.GetReturnTypeOfSignature(signatures[0])
		returns, known := l.representation(result)
		if !known || censusCallableSlotless(returns) {
			return nil, l.notYet(node, "numeric coercion with an unrepresented conversion result")
		}
		call := ir.CallClosure{Closure: ir.Property{Object: read, Name: name, Of: ir.Closure, Method: true}, Returns: returns}
		if l.writable(result) {
			body = append(body, ir.Return{Value: ir.NumberCall{Function: "convert", Arguments: []ir.Expression{call}}})
			l.result.Functions = append(l.result.Functions, ir.Function{Name: "numeric_coercion", Parameters: []int{local}, Returns: ir.Number, Body: body})
			return ir.Call{Function: index, Arguments: []ir.Expression{value}, Returns: ir.Number}, nil
		}
		// A returned object is evaluated and released before trying toString.
		body = append(body, ir.Evaluate{Value: call})
	}
	// A fresh literal has no hidden conversion members. An erased structural view can,
	// so absence from its type is never interpreted as the absence of user code.
	if ast.SkipParentheses(node).Kind == ast.KindObjectLiteralExpression && len(body) == 0 {
		body = append(body, ir.Return{Value: ir.NumberConstant{Value: math.NaN()}})
		l.result.Functions = append(l.result.Functions, ir.Function{Name: "numeric_coercion", Parameters: []int{local}, Returns: ir.Number, Body: body})
		return ir.Call{Function: index, Arguments: []ir.Expression{value}, Returns: ir.Number}, nil
	}
	return nil, l.notYet(node, "numeric coercion requiring dynamic ToPrimitive")
}

census_overload_proof.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
)

func (l *lowering) censusHasUndefined(proven *checker.Type) bool {
	if proven.Flags()&checker.TypeFlagsUndefined != 0 {
		return true
	}
	if proven.Flags()&checker.TypeFlagsUnion == 0 {
		return false
	}
	for _, member := range proven.Types() {
		if member.Flags()&checker.TypeFlagsUndefined != 0 {
			return true
		}
	}
	return false
}

// Presence checks are sufficient only when all present members already satisfy
// the promise. They must not bless a brand or a mutable representation change.
func (l *lowering) censusNullableOverloadResult(produced, promised *checker.Type) bool {
	produced, promised = l.concrete(produced), l.concrete(promised)
	if !l.censusHasUndefined(produced) || l.censusHasUndefined(promised) {
		return false
	}
	for _, member := range produced.Types() {
		if member.Flags()&checker.TypeFlagsUndefined == 0 && !l.censusRelated(member, promised) {
			return false
		}
	}
	return produced.Flags()&checker.TypeFlagsUnion != 0
}

// Prove every reachable return under the overload's admitted parameter types.
// Only bare parameter tests supply flow facts. A write anywhere, including a
// captured write in a nested function, disables the proof. Unknown control flow
// keeps the call-site check rather than guessing that the annotation is true.
func (l *lowering) censusProveOverloadResult(implementation, overload *ast.Node) bool {
	return l.censusReturnProof(implementation, overload, nil, nil)
}

func (l *lowering) censusReturnProof(implementation, overload *ast.Node, admitted []*checker.Type, target *checker.Type) bool {
	outer := l.typeMapper
	defer func() { l.typeMapper = outer }()
	sources, targets := []*checker.Type{}, []*checker.Type{}
	for index, parameter := range implementation.TypeParameters() {
		if index >= len(overload.TypeParameters()) {
			return false
		}
		sources = append(sources, l.checker.GetTypeAtLocation(parameter.Name()))
		targets = append(targets, l.checker.GetTypeAtLocation(overload.TypeParameters()[index].Name()))
	}
	if len(sources) > 0 {
		l.typeMapper = newTypeMapper(sources, targets)
	}
	promised := l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(overload))
	if target != nil {
		promised = target
	}
	parameters := implementation.Parameters()
	initial := make([]*checker.Type, len(parameters))
	for index, parameter := range parameters {
		if !ast.IsIdentifier(parameter.Name()) || parameter.AsParameterDeclaration().Initializer != nil || parameter.AsParameterDeclaration().DotDotDotToken != nil {
			return false
		}
		given, _, rest, err := l.censusOverloadParameter(overload.Parameters(), index)
		if err != nil || rest {
			return false
		}
		if given == nil {
			given = l.checker.GetUndefinedType()
		}
		initial[index] = given
		if admitted != nil {
			initial[index] = l.checker.GetUndefinedType()
			if index < len(admitted) {
				initial[index] = admitted[index]
			}
		}
	}
	unchanged := true
	var scan ast.Visitor
	scan = func(node *ast.Node) bool {
		if node.Kind == ast.KindAsExpression || node.Kind == ast.KindTypeAssertionExpression || node.Kind == ast.KindNonNullExpression {
			unchanged = false
		}
		if ast.IsIdentifier(node) && ast.IsAssignmentTarget(node) {
			for _, parameter := range parameters {
				if l.symbol(node) == l.symbol(parameter.Name()) {
					unchanged = false
				}
			}
		}
		node.ForEachChild(scan)
		return false
	}
	implementation.Body().ForEachChild(scan)
	if !unchanged {
		return false
	}
	narrowed := func(index int, flow *ast.FlowNode) *checker.Type {
		parameter := parameters[index]
		declared := l.checker.GetTypeAtLocation(parameter.Name())
		return l.concrete(predicateFlowType(l.checker, parameter.Name(), declared, initial[index], implementation, flow))
	}
	reachable := func(flow *ast.FlowNode) bool {
		for index := range parameters {
			if narrowed(index, flow).Flags()&checker.TypeFlagsNever != 0 {
				return false
			}
		}
		return true
	}
	returned := func(expression *ast.Node, flow *ast.FlowNode) bool {
		if !reachable(flow) {
			return true
		}
		if expression == nil {
			return l.censusRelated(l.checker.GetUndefinedType(), promised)
		}
		expression = ast.SkipParentheses(expression)
		if ast.IsIdentifier(expression) {
			for index, parameter := range parameters {
				if l.symbol(expression) == l.symbol(parameter.Name()) {
					return l.censusRelated(narrowed(index, flow), promised)
				}
			}
			// Local aliases can be rebound by a call; they are not flow evidence.
			if l.symbol(expression) != l.checker.GetUndefinedSymbol() {
				return false
			}
		}
		if predicateEffects(expression) {
			return false
		}
		return l.censusRelated(l.checker.GetTypeAtLocation(expression), promised)
	}
	var statement func(*ast.Node, []*ast.FlowNode) ([]*ast.FlowNode, bool)
	statement = func(node *ast.Node, flows []*ast.FlowNode) ([]*ast.FlowNode, bool) {
		if len(flows) > 256 {
			return nil, false
		}
		switch node.Kind {
		case ast.KindBlock:
			for _, child := range node.AsBlock().Statements.Nodes {
				var ok bool
				flows, ok = statement(child, flows)
				if !ok {
					return nil, false
				}
			}
			return flows, true
		case ast.KindIfStatement:
			branch := node.AsIfStatement()
			check := ast.SkipParentheses(branch.Expression)
			trusted := false
			if check.Kind == ast.KindBinaryExpression {
				binary := check.AsBinaryExpression()
				if binary.OperatorToken.Kind == ast.KindEqualsEqualsEqualsToken || binary.OperatorToken.Kind == ast.KindExclamationEqualsEqualsToken {
					for _, parameter := range parameters {
						proof := predicateFlowProof{l: l, parameter: parameter}
						trusted = trusted || proof.reference(ast.SkipParentheses(binary.Left)) && proof.literal(binary.Right) || proof.reference(ast.SkipParentheses(binary.Right)) && proof.literal(binary.Left)
					}
				}
			}
			if !trusted {
				return nil, false
			}
			then, otherwise := []*ast.FlowNode{}, []*ast.FlowNode{}
			for _, flow := range flows {
				for _, truth := range []bool{true, false} {
					path := predicateBranch(predicateFlowPath{flow: flow}, branch.Expression, truth).flow
					if reachable(path) {
						if truth {
							then = append(then, path)
						} else {
							otherwise = append(otherwise, path)
						}
					}
				}
			}
			then, ok := statement(branch.ThenStatement, then)
			if !ok {
				return nil, false
			}
			if branch.ElseStatement != nil {
				otherwise, ok = statement(branch.ElseStatement, otherwise)
				if !ok {
					return nil, false
				}
			}
			return append(then, otherwise...), true
		case ast.KindReturnStatement:
			for _, flow := range flows {
				if !returned(node.AsReturnStatement().Expression, flow) {
					return nil, false
				}
			}
			return nil, true
		case ast.KindThrowStatement:
			return nil, true
		case ast.KindExpressionStatement, ast.KindVariableStatement, ast.KindEmptyStatement:
			return flows, true
		}
		return nil, false
	}
	remaining, ok := statement(implementation.Body(), []*ast.FlowNode{{Flags: ast.FlowFlagsStart}})
	if !ok {
		return false
	}
	for _, flow := range remaining {
		if !returned(nil, flow) {
			return false
		}
	}
	return true
}

// The checker retains the overload's declared result even when every admitted
// return is undefined. JSON needs no container metadata for that proven case,
// but still evaluates the original call, including its arguments and effects.
func (l *lowering) censusCallReturnsUndefined(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindCallExpression {
		return false
	}
	call := node.AsCallExpression()
	if !ast.IsIdentifier(ast.SkipParentheses(call.Expression)) {
		return false
	}
	resolved := l.checker.GetResolvedSignature(node)
	if resolved == nil || resolved.Declaration() == nil {
		return false
	}
	overload := resolved.Declaration()
	implementation := l.censusImplementation(overload)
	if implementation == nil {
		return false
	}
	admitted := make([]*checker.Type, len(call.Arguments.Nodes))
	for index, argument := range call.Arguments.Nodes {
		if argument.Kind == ast.KindSpreadElement {
			return false
		}
		admitted[index] = l.checker.GetTypeAtLocation(argument)
		if admitted[index].Flags()&checker.TypeFlagsUndefined == 0 {
			return false
		}
	}
	return l.censusReturnProof(implementation, overload, admitted, l.checker.GetUndefinedType())
}

census_predicate_marker.go:
package lower

import (
	_ "unsafe"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
)

// Like the instantiation bridge, use the pinned checker through its own relation
// metadata rather than guessing that a boolean-returning function is a predicate.
//
//go:linkname censusSignaturePredicate github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).getTypePredicateOfSignature
func censusSignaturePredicate(*checker.Checker, *checker.Signature) *checker.TypePredicate

func (l *lowering) censusDiscardedMarkerPredicate(source, target *checker.Signature) bool {
	return l.censusNeverRestSignature(target) &&
		l.checker.GetReturnTypeOfSignature(target).Flags()&checker.TypeFlagsVoid != 0 &&
		censusSignaturePredicate(l.checker, source) != nil
}

// A callback contract has no producer body to prove. For this narrowly erased
// use, its predicate cannot be observed: every reference passes the callback
// into a never-rest marker slot. Ordinary calls, escapes and writes keep the
// existing predicate refusal. Actual producer bodies still require their proof.
func (l *lowering) censusPredicateMarkerContract(annotation *ast.Node) bool {
	functionType := annotation.Parent
	if functionType == nil || functionType.Kind != ast.KindFunctionType {
		return false
	}
	parameter := functionType.Parent
	if parameter == nil || parameter.Kind != ast.KindParameter || parameter.Type() != functionType || !ast.IsIdentifier(parameter.Name()) {
		return false
	}
	function := parameter.Parent
	if function == nil || !ast.IsFunctionLike(function) || function.Body() == nil {
		return false
	}
	symbol := l.symbol(parameter.Name())
	if symbol == nil {
		return false
	}
	found, safe := false, true
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if ast.IsIdentifier(node) && !ast.IsPartOfTypeNode(node) && l.symbol(node) == symbol {
			found = true
			argument := node
			for argument.Parent != nil && argument.Parent.Kind == ast.KindParenthesizedExpression {
				argument = argument.Parent
			}
			call := argument.Parent
			accepted := false
			if call != nil && call.Kind == ast.KindCallExpression {
				resolved := l.checker.GetResolvedSignature(call)
				if resolved != nil {
					for index, given := range call.AsCallExpression().Arguments.Nodes {
						if given == argument && index < len(resolved.Parameters()) {
							signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeOfSymbol(resolved.Parameters()[index]), checker.SignatureKindCall)
							accepted = len(signatures) == 1 && l.censusNeverRestSignature(signatures[0])
						}
					}
				}
			}
			safe = safe && accepted
		}
		node.ForEachChild(visit)
		return false
	}
	function.Body().ForEachChild(visit)
	return found && safe
}

census_small.go:
package lower

import (
	"fmt"
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// censusRestParameter admits rest only where every call passes a freshly packed array.
// Function values and methods have a different calling convention and remain NotYet.
func (l *lowering) censusRestParameter(declaration, parameter *ast.Node) error {
	if declaration.Kind != ast.KindFunctionDeclaration || len(declaration.TypeParameters()) != 0 {
		return l.notYet(parameter, "a rest parameter outside a nongeneric named function")
	}
	if l.result.Functions[l.functionIndex].Closure {
		return l.notYet(parameter, "a rest parameter in a named closure")
	}
	parameters := declaration.Parameters()
	if parameters[len(parameters)-1] != parameter {
		return l.notYet(parameter, "a rest parameter before another parameter")
	}
	proven := l.checker.GetTypeAtLocation(parameter.Name())
	if !l.checker.IsArrayType(proven) {
		return l.notYet(parameter, "a rest parameter other than an array")
	}
	element, known := l.kept(l.checker.GetElementTypeOfArrayType(proven))
	if !known || slotless(element) {
		return l.notYet(parameter, "a rest array of "+l.checker.TypeToString(proven))
	}
	return nil
}

// censusRestDeclaration recovers the declaration without adding state to lower.go.
func (l *lowering) censusRestDeclaration(function int) *ast.Node {
	for symbol, index := range l.functions {
		if index != function {
			continue
		}
		for _, declaration := range symbol.Declarations {
			if declaration.Kind != ast.KindFunctionDeclaration || declaration.Body() == nil {
				continue
			}
			parameters := declaration.Parameters()
			if len(parameters) > 0 && parameters[len(parameters)-1].AsParameterDeclaration().DotDotDotToken != nil {
				return declaration
			}
		}
	}
	return nil
}

// censusRestCall evaluates fixed arguments before rest items, and copies each spread
// when encountered. The array is new even when the only item is a spread.
func (l *lowering) censusRestCall(call *ast.CallExpression, function int, declaration *ast.Node) (ir.Expression, error) {
	parameters := declaration.Parameters()
	fixed := len(parameters) - 1
	proven := l.checker.GetTypeAtLocation(parameters[fixed].Name())
	element, _ := l.kept(l.checker.GetElementTypeOfArrayType(proven))
	rest := ir.ArrayLiteral{Element: element}
	arguments := []ir.Expression{}
	for index, argument := range call.Arguments.Nodes {
		spread := argument.Kind == ast.KindSpreadElement
		valueNode := argument
		if spread {
			if index < fixed {
				return nil, l.notYet(argument, "a spread filling fixed parameters before a rest parameter")
			}
			valueNode = argument.AsSpreadElement().Expression
		}
		value, err := l.expression(valueNode)
		if err != nil {
			return nil, err
		}
		if index < fixed {
			arguments = append(arguments, value)
			continue
		}
		if spread {
			source := l.checker.GetTypeAtLocation(valueNode)
			if !l.checker.IsArrayType(source) {
				return nil, l.notYet(argument, "a rest spread other than an array")
			}
			held, known := l.kept(l.checker.GetElementTypeOfArrayType(source))
			if !known || held != element {
				return nil, l.notYet(argument, "a rest spread with differently held elements")
			}
		} else {
			value = fit(value, element)
			if value.Type() != element {
				return nil, l.notYet(argument, "a rest argument with another representation")
			}
		}
		rest.Elements = append(rest.Elements, value)
		rest.Spread = append(rest.Spread, spread)
	}
	// Missing fixed arguments must keep their positions before the rest array.
	for len(arguments) < fixed {
		of := l.result.Locals[l.result.Functions[function].Parameters[len(arguments)]].Type
		if !of.IsMaybe() && !of.IsReference() {
			return nil, l.notYet(parameters[len(arguments)], "a missing fixed argument before rest")
		}
		arguments = append(arguments, fit(ir.Undefined{}, of))
	}
	arguments = append(arguments, rest)
	return l.censusOverloadResult(call, ir.Call{Function: function, Arguments: arguments, Returns: l.result.Functions[function].Returns})
}

// Boolean fields have a tagged byte; other slotless representations remain refused.
func censusFieldSlotless(of ir.Type) bool {
	return slotless(of) && of != ir.MaybeBoolean && of != ir.Union
}

// Only the implementation of a named overload set has executable code.
func (l *lowering) censusImplementation(declaration *ast.Node) *ast.Node {
	if declaration.Kind != ast.KindFunctionDeclaration || declaration.Name() == nil {
		return nil
	}
	symbol := l.symbol(declaration.Name())
	if symbol == nil {
		return nil
	}
	for _, candidate := range symbol.Declarations {
		if candidate.Kind == ast.KindFunctionDeclaration && candidate.Body() != nil {
			return candidate
		}
	}
	return nil
}

// Use the same nominal, invariant and strictly contravariant relation as class overrides.
func (l *lowering) censusRelated(from, to *checker.Type) bool {
	from, to = l.concrete(from), l.concrete(to)
	return l.classAssignable(from, to) && l.widened(from, to, map[[2]*checker.Type]bool{}) == nil
}

func (l *lowering) censusOverloads(implementation *ast.Node) error {
	if implementation.Kind != ast.KindFunctionDeclaration || implementation.Body() == nil {
		return nil
	}
	symbol := l.symbol(implementation.Name())
	if symbol == nil {
		return nil
	}
	ordinal := 0
	for _, overload := range symbol.Declarations {
		if overload.Kind != ast.KindFunctionDeclaration || overload.Body() != nil {
			continue
		}
		ordinal++
		if err := l.censusOverload(implementation, overload, ordinal); err != nil {
			return err
		}
	}
	return nil
}

// Compare generic signatures under the same rigid type parameters, never under one
// lucky runtime instantiation. Mapping the implementation's binders is alpha-renaming.
func (l *lowering) censusOverload(implementation, overload *ast.Node, ordinal int) error {
	label := fmt.Sprintf("overload %d of %s", ordinal, implementation.Name().Text())
	declaredTypes, servedTypes := overload.TypeParameters(), implementation.TypeParameters()
	outerMapper := l.typeMapper
	defer func() { l.typeMapper = outerMapper }()
	if len(servedTypes) > 0 {
		sources, targets := []*checker.Type{}, []*checker.Type{}
		inferred := map[*checker.Type]*checker.Type{}
		if len(servedTypes) > len(declaredTypes) {
			// Extra binders need a witness from the entire signature, not positional
			// alpha-renaming: implementations may insert a binder before an old one.
			for index, parameter := range implementation.Parameters() {
				if index < len(overload.Parameters()) {
					l.inferTypes(l.checker.GetTypeAtLocation(parameter), l.checker.GetTypeAtLocation(overload.Parameters()[index]), inferred)
				}
			}
			l.inferTypes(l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(implementation)), l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(overload)), inferred)
		}
		for index, parameter := range servedTypes {
			source := l.checker.GetTypeAtLocation(parameter.Name())
			target := inferred[source]
			if len(servedTypes) <= len(declaredTypes) {
				target = l.checker.GetTypeAtLocation(declaredTypes[index].Name())
			} else if target == nil {
				// A binder with no evidence can use bottom as a candidate witness.
				// This is not permission to erase it: every constraint, incoming
				// parameter and outgoing result below must still hold for that witness.
				target = l.checker.GetNonNullableType(l.checker.GetUndefinedType())
			}
			sources = append(sources, source)
			targets = append(targets, target)
		}
		l.typeMapper = newTypeMapper(sources, targets)
		for index, parameter := range servedTypes {
			if constraint := l.checker.GetBaseConstraintOfType(sources[index]); constraint != nil && !l.censusRelated(targets[index], constraint) {
				where, name := overload, "type "+l.checker.TypeToString(targets[index])
				if len(servedTypes) <= len(declaredTypes) {
					where, name = declaredTypes[index], "type parameter "+declaredTypes[index].Name().Text()
				}
				return &Refused{Where: l.program.Where(where), What: label + " " + name + " cannot satisfy implementation parameter " + parameter.Name().Text(), Fix: "make implementation constraints accept every type admitted by the overload"}
			}
		}
	}
	declared, served := overload.Parameters(), implementation.Parameters()
	for index := 0; index <= max(len(declared), len(served)); index++ {
		given, parameter, givenRest, err := l.censusOverloadParameter(declared, index)
		if err != nil {
			return l.notYet(overload, label+" with a non-array rest parameter")
		}
		takes, actual, takesRest, err := l.censusOverloadParameter(served, index)
		if err != nil {
			return l.notYet(overload, label+" with a non-array implementation rest parameter")
		}
		if actual == nil {
			continue
		} // JavaScript evaluates and ignores extra arguments.
		if parameter == nil && takesRest {
			continue
		} // Missing rest items make an empty array.
		if parameter == nil {
			given = l.checker.GetUndefinedType()
			parameter = actual
		}
		if givenRest && !takesRest {
			given = l.checker.GetUnionType([]*checker.Type{given, l.checker.GetUndefinedType()})
		}
		if !l.censusRelated(given, takes) {
			name := func(node *ast.Node) string {
				if ast.IsIdentifier(node.Name()) {
					return node.Name().Text()
				}
				return fmt.Sprintf("%d", index+1)
			}
			return &Refused{Where: l.program.Where(parameter), What: label + " parameter " + name(parameter) + " cannot be served by implementation parameter " + name(actual), Fix: "make the implementation accept every value admitted by this overload, without mutable widening or bivariance"}
		}
	}
	promised := l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(overload))
	produced := l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(implementation))
	if !l.censusRelated(produced, promised) {
		if l.censusNullableOverloadResult(produced, promised) {
			return nil // Each resolved call proves the result or checks its presence.
		}
		return &Refused{Where: l.program.Where(overload), What: label + " result " + l.checker.TypeToString(promised) + " cannot be served by implementation result " + l.checker.TypeToString(produced), Fix: "make the implementation result covariant with every overload result"}
	}
	return nil
}

func (l *lowering) censusOverloadParameter(parameters []*ast.Node, index int) (*checker.Type, *ast.Node, bool, error) {
	if len(parameters) == 0 {
		return nil, nil, false, nil
	}
	parameter := parameters[min(index, len(parameters)-1)]
	rest := parameter.AsParameterDeclaration().DotDotDotToken != nil
	if index >= len(parameters) && !rest {
		return nil, nil, false, nil
	}
	proven := l.checker.GetTypeAtLocation(parameter)
	if ast.IsIdentifier(parameter.Name()) {
		proven = l.censusCallableParameterType(l.symbol(parameter.Name()))
	}
	proven = l.concrete(proven)
	if rest {
		if !l.checker.IsArrayType(proven) {
			return nil, parameter, true, l.notYet(parameter, "an overload rest other than an array")
		}
		proven = l.checker.GetElementTypeOfArrayType(proven)
	}
	return proven, parameter, rest, nil
}

// Calls use the resolved overload's result representation, even when the
// implementation proves a narrower result. A plain false must become a present
// boolean | undefined, and a scalar result must be boxed when the caller sees a union.
func (l *lowering) censusOverloadResult(call *ast.CallExpression, value ir.Expression) (ir.Expression, error) {
	symbol := l.symbol(ast.SkipParentheses(call.Expression))
	overloaded := false
	if symbol != nil {
		for _, declaration := range symbol.Declarations {
			if declaration.Kind == ast.KindFunctionDeclaration && declaration.Body() == nil && l.censusImplementation(declaration) != nil {
				overloaded = true
				break
			}
		}
	}
	if !overloaded {
		return value, nil
	}
	resolved := l.checker.GetResolvedSignature(call.AsNode())
	if resolved != nil && resolved.Declaration() != nil {
		overload := resolved.Declaration()
		implementation := l.censusImplementation(overload)
		if implementation != nil && overload.Body() == nil {
			if overload.Type() != nil && overload.Type().Kind == ast.KindTypePredicate {
				return l.predicateOverloadResult(call, value, implementation, overload)
			}
			ordinal := 0
			for _, declaration := range symbol.Declarations {
				if declaration.Kind == ast.KindFunctionDeclaration && declaration.Body() == nil {
					ordinal++
					if declaration == overload {
						break
					}
				}
			}
			if !l.censusProveOverloadResult(implementation, overload) {
				promised := l.checker.GetReturnTypeOfSignature(resolved)
				produced := l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(implementation))
				if l.censusHasUndefined(produced) && !l.censusHasUndefined(promised) {
					of, err := l.typeOf(call.AsNode())
					if err != nil {
						return nil, err
					}
					message := fmt.Sprintf("overload %d of %s result: expected %s, got undefined", ordinal, implementation.Name().Text(), l.checker.TypeToString(promised))
					return ir.Coalesce{Value: value, Of: of, Panic: ir.StringConstant{Index: l.constant(message)}}, nil
				}
			}
		}
	}
	if value.Type() == 0 {
		return value, nil
	}
	of, err := l.typeOf(call.AsNode())
	if err != nil {
		return nil, err
	}
	value = fit(value, of)
	if value.Type() != of {
		return nil, l.notYet(call.AsNode(), "an overload result requiring another representation")
	}
	return value, nil
}

// Callable slots use the same tagged boolean representation as fields.
func censusCallableSlotless(of ir.Type) bool {
	return slotless(of) && of != ir.MaybeBoolean && of != ir.Union
}

// A default's body-local type excludes undefined, but its incoming argument can be undefined.
func (l *lowering) censusCallableParameter(parameter *ast.Symbol) (ir.Type, bool) {
	of, known := l.representation(l.checker.GetTypeOfSymbol(parameter))
	for _, declaration := range parameter.Declarations {
		if declaration.Kind == ast.KindParameter && declaration.AsParameterDeclaration().Initializer != nil {
			of = ir.Maybe(of)
		}
	}
	return of, known
}

// Signature symbols describe the body-local type of a defaulted parameter. The
// callable contract also accepts undefined, which selects that parameter's default.
func (l *lowering) censusCallableParameterType(parameter *ast.Symbol) *checker.Type {
	of := l.checker.GetTypeOfSymbol(parameter)
	for _, declaration := range parameter.Declarations {
		if declaration.Kind == ast.KindParameter && declaration.AsParameterDeclaration().Initializer != nil {
			return l.checker.GetUnionType([]*checker.Type{of, l.checker.GetUndefinedType()})
		}
	}
	return of
}

// Only exactly true is truthy in boolean | undefined. Equality evaluates the value once.
func censusBooleanCondition(value ir.Expression) ir.Expression {
	if value.Type() == ir.MaybeBoolean {
		return ir.Binary{Operator: ir.Equal, Left: value, Right: fit(ir.BooleanConstant{Value: true}, ir.MaybeBoolean)}
	}
	return value
}

func (l *lowering) censusBooleanLogical(node *ast.Node, operator ast.Kind, left, right ir.Expression) (ir.Expression, bool) {
	if operator != ast.KindAmpersandAmpersandToken && operator != ast.KindBarBarToken {
		return nil, false
	}
	boolean := func(of ir.Type) bool { return of == ir.Boolean || of == ir.MaybeBoolean }
	if !boolean(left.Type()) || !boolean(right.Type()) {
		return nil, false
	}
	of, err := l.typeOf(node)
	if err != nil || !boolean(of) {
		// Two booleans give a boolean whatever the checker narrowed the whole to: a branch it
		// knows is dead types the expression never, and that branch must still lower.
		if left.Type() != ir.Boolean || right.Type() != ir.Boolean {
			return nil, false
		}
		of = ir.Boolean
	}
	lowered := ir.And
	if operator == ast.KindBarBarToken {
		lowered = ir.Or
	}
	if lowered == ir.And && left.Type() == ir.MaybeBoolean {
		of = ir.MaybeBoolean
	}
	if of == ir.MaybeBoolean {
		left, right = fit(left, of), fit(right, of)
	} else {
		left, right = censusBooleanCondition(left), censusBooleanCondition(right)
	}
	return ir.Binary{Operator: lowered, Left: left, Right: right}, true
}

// ToBoolean never calls user conversion methods. Every represented value can be tested.
// NumberCall already carries a single evaluated argument through both backends and analyses.
func censusCondition(value ir.Expression) ir.Expression {
	if value.Type() == ir.Boolean {
		return value
	}
	return ir.NumberCall{Function: "toBoolean", Arguments: []ir.Expression{value}}
}

// A never-rest signature is an erased callable marker. No ordinary argument can
// inhabit its rest element; storage compares results without pairing parameters.
func (l *lowering) censusNeverRestSignature(signature *checker.Signature) bool {
	parameters := signature.Parameters()
	if len(parameters) != 1 {
		return false
	}
	rest := false
	for _, declaration := range parameters[0].Declarations {
		if declaration.Kind == ast.KindParameter && declaration.AsParameterDeclaration().DotDotDotToken != nil {
			rest = true
		}
	}
	if !rest {
		return false
	}
	parameter := l.concrete(l.checker.GetTypeOfSymbol(parameters[0]))
	if l.checker.IsArrayType(parameter) {
		parameter = l.checker.GetElementTypeOfArrayType(parameter)
	}
	return parameter.Flags()&checker.TypeFlagsNever != 0
}

class.go:
package lower

import (
	"sort"
	"strings"
	_ "unsafe"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// instance is one instantiation of a class, lowered: its constructor, and its methods by name.
//
// Each instantiation has one nominal identity and one prefix layout. A virtual call keeps its
// static signature while selecting the implementation from the object's dynamic table.
type instance struct {
	static         bool
	constructor    int
	methods        map[string]int
	slots          map[string]int
	class          int
	base           *instance
	initializer    int
	superReady     int
	unreadyThis    map[*ast.Node]bool
	superStates    map[*ast.Node]uint8
	constructing   bool
	hasDescendants bool
	// staticMethods are the methods declared static, which no object of the class has.
	staticMethods map[string]bool

	// thisLocals are the this of its constructor and methods, which every instantiation sharing it
	// records at its call sites, for the cycle finder.
	thisLocals []int

	// templates are the instance's locals and function values with their types as the source writes
	// them, so an instantiation that shares the instance notes each as its own type makes it.
	templates []template
}

// methodList is this side's methods by name in order, so its named dispatch map is stable.
// Static instances keep a separate map; methods on the other side never enter it.
func (lowered *instance) methodList() []ir.Method {
	names := []string{}
	for name := range lowered.methods {
		if !lowered.staticMethods[name] {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	methods := []ir.Method{}
	for _, name := range names {
		methods = append(methods, ir.Method{Name: name, Function: lowered.methods[name]})
	}
	return methods
}

// template is a local, or a function value (closure set), and its type with type parameters left in.
type template struct {
	local, closure int
	proven         *checker.Type
	isClosure      bool
}

// instantiate lowers a class for the type arguments of a type of it, once per distinct set.
func (l *lowering) instantiate(declaration *ast.Node, classType *checker.Type, where *ast.Node) (*instance, error) {
	// Box<T> inside Maker<Node> is a Box<Node>: what it is, for the cycle finder.
	classType = l.concrete(classType)
	if view := l.classView(classType, declaration); view != nil {
		classType = view
	} else {
		return nil, l.notYet(where, "a method receiver without a nominal class view")
	}
	arguments := []ir.Type{}
	substitution := map[*checker.Type]ir.Type{}
	parameters := declaration.TypeParameters()
	var typeArguments []*checker.Type
	if len(parameters) > 0 {
		typeArguments = l.checker.GetTypeArguments(classType)
	}
	if len(parameters) != len(typeArguments) {
		return nil, l.notYet(where, "a class whose type arguments aren't known here")
	}
	for index, parameter := range parameters {
		representation, isKnown := l.representation(typeArguments[index])
		if !isKnown {
			return nil, l.notYet(where, "a class instantiated with "+l.checker.TypeToString(typeArguments[index]))
		}
		substitution[l.checker.GetTypeAtLocation(parameter.Name())] = representation
		arguments = append(arguments, representation)
	}
	key := l.classInstanceKey(declaration, typeArguments)
	mapper := l.typeMapperOf(declaration, classType)
	if err := l.nominalTypeArguments(declaration, typeArguments, mapper, where); err != nil {
		return nil, err
	}
	l.instantiated = append(l.instantiated, classType)
	if existing, isLowered := l.instances[key]; isLowered {
		for _, this := range existing.thisLocals {
			l.noteAlso(this, classType)
		}
		// The instance is shared, and so are its locals and function values: each is also what this
		// instantiation makes it.
		outerMapper := l.typeMapper
		l.typeMapper = mapper
		for _, shared := range existing.templates {
			if shared.isClosure {
				l.closureRecords = append(l.closureRecords, closureRecord{proven: l.concrete(shared.proven), function: shared.closure, node: l.closureNodeOf(shared.closure)})
			} else {
				l.noteAlso(shared.local, l.concrete(shared.proven))
			}
		}
		l.typeMapper = outerMapper
		return existing, nil
	}

	if len(parameters) > 0 {
		if l.genericDepth >= maximumGenericDepth {
			return nil, &Refused{Where: l.program.Where(where), What: "a generic class instantiated without end (polymorphic recursion)", Fix: "keep recursive type arguments unchanged, or write a class per type"}
		}
		l.genericDepth++
		defer func() { l.genericDepth-- }()
	}

	base, err := l.baseInstance(declaration, classType)
	if err != nil {
		return nil, err
	}
	if err := l.checkOverrides(declaration, classType); err != nil {
		return nil, err
	}

	// Register every function of the instantiation first, so methods can find each other.
	name := declaration.Name().Text()
	for _, argument := range arguments {
		name += "_" + typeName(argument)
	}
	lowered := &instance{constructor: len(l.result.Functions), methods: map[string]int{}, staticMethods: map[string]bool{}, slots: map[string]int{}, initializer: -1, superReady: -1}
	l.result.Functions = append(l.result.Functions, ir.Function{Name: name + "_new", Returns: ir.Object})
	lowered.hasDescendants = l.derivedAncestors[l.symbol(declaration.Name())]
	lowered.base = base
	lowered.class = len(l.result.Classes) + 1
	metadata := ir.Class{Name: name, Constructor: lowered.constructor, Definition: l.classDefinition(declaration)}
	if base != nil {
		metadata.Base = base.class
		metadata.Fields = append(metadata.Fields, l.result.Classes[base.class-1].Fields...)
		metadata.Methods = append(metadata.Methods, l.result.Classes[base.class-1].Methods...)
		for method, function := range base.methods {
			lowered.methods[method] = function
			lowered.staticMethods[method] = base.staticMethods[method]
		}
		for method, slot := range base.slots {
			lowered.slots[method] = slot
		}
	}
	metadata.OwnStart = len(metadata.Fields)
	l.result.Classes = append(l.result.Classes, metadata)
	members := declaration.Members()
	for _, member := range members {
		switch member.Kind {
		case ast.KindMethodDeclaration, ast.KindGetAccessor, ast.KindSetAccessor:
			if !ast.IsIdentifier(member.Name()) && member.Name().Kind != ast.KindPrivateIdentifier && !(member.Kind == ast.KindMethodDeclaration && member.Name().Kind == ast.KindComputedPropertyName && l.symbolIterator(member.Name().AsComputedPropertyName().Expression)) {
				return nil, l.notYet(member, "a method with a computed name")
			}
			if ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
				continue
			}
			methodName := l.methodKey(member, lowered.class)
			if accessorMember(member) {
				l.registerAccessor(lowered.class, member, len(l.result.Functions))
			}
			lowered.methods[methodName] = len(l.result.Functions)
			lowered.staticMethods[methodName] = ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic)
			if !lowered.staticMethods[methodName] {
				meta := &l.result.Classes[lowered.class-1]
				slot, exists := lowered.slots[methodName]
				if !exists {
					slot = len(meta.Methods)
					lowered.slots[methodName] = slot
					meta.Methods = append(meta.Methods, -1)
				}
				meta.Methods[slot] = len(l.result.Functions)
			}
			l.result.Functions = append(l.result.Functions, ir.Function{Name: name + "_" + methodName, MethodName: methodName})
		case ast.KindPropertyDeclaration, ast.KindConstructor, ast.KindClassStaticBlockDeclaration:
		default:
			return nil, l.notYet(member, describe(member)+" in a class")
		}
	}
	if l.instances == nil {
		l.instances = map[string]*instance{}
	}
	l.instances[key] = lowered

	// Lower with this instantiation's meaning of each type parameter, and locals of its own: the
	// same parameter is a string here and may be a number in another instantiation.
	outerSubstitution, outerLocals, outerInstance := l.substitution, l.locals, l.instance
	outerClassType, outerClassNode, outerMapper := l.classType, l.classNode, l.typeMapper
	l.substitution, l.instance = substitution, lowered
	l.classType, l.classNode, l.typeMapper = classType, declaration.Name(), mapper
	defer func() { l.classType, l.classNode, l.typeMapper = outerClassType, outerClassNode, outerMapper }()
	l.locals = map[*ast.Symbol]int{}
	for symbol, local := range outerLocals {
		if l.result.Locals[local].Global {
			l.locals[symbol] = local
		}
	}
	defer func() { l.substitution, l.locals, l.instance = outerSubstitution, outerLocals, outerInstance }()

	// Every method's signature is written before any body is lowered, the constructor's included, so a
	// method can call one declared below it, and two can call each other.
	for _, member := range members {
		if !classFunction(member) || ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			continue
		}
		method := lowered.methods[l.methodKey(member, lowered.class)]
		if err := l.signature(method, member, l.thisLocal(method)); err != nil {
			return nil, err
		}
		if err := l.validateAccessorSignature(member, method); err != nil {
			return nil, err
		}
	}
	if err := l.constructor(lowered.constructor, declaration); err != nil {
		return nil, err
	}
	for _, member := range members {
		if !classFunction(member) || ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			continue
		}
		method := lowered.methods[l.methodKey(member, lowered.class)]
		if member.Body() == nil {
			continue
		}
		if err := l.lowerFunction(method, member, -1); err != nil {
			return nil, err
		}
	}
	return lowered, nil
}

// thisLocal makes a fresh local for the this of the method or constructor at owner.
func (l *lowering) thisLocal(owner int) int {
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "this", Type: ir.Object, Function: owner})
	l.noteLocal(len(l.result.Locals)-1, l.classType, l.classNode)
	l.instance.thisLocals = append(l.instance.thisLocals, len(l.result.Locals)-1)
	return len(l.result.Locals) - 1
}

// constructor lowers a class's construction: an object with the class's fields, each from its
// initializer (or its type's zero until the constructor body assigns it, which the checker requires),
// then the constructor's body, which returns the object.
func (l *lowering) constructor(index int, declaration *ast.Node) error {
	return l.inheritanceConstructor(index, declaration)
}

// zeroValue is a field's value before its constructor assigns it.
func zeroValue(of ir.Type) ir.Expression {
	switch of {
	case ir.Number:
		return ir.NumberConstant{}
	case ir.Boolean:
		return ir.BooleanConstant{}
	case ir.MaybeNumber:
		// A field of number | undefined left without a value is undefined, as JavaScript leaves it.
		return ir.MaybeOf{Of: ir.MaybeNumber}
	}
	return ir.Undefined{}
}

func containsThis(node *ast.Node) bool {
	found := false
	var visit ast.Visitor
	visit = func(child *ast.Node) bool {
		if child.Kind == ast.KindThisKeyword {
			found = true
			return true
		}
		return child.ForEachChild(visit)
	}
	if node.Kind == ast.KindThisKeyword {
		return true
	}
	node.ForEachChild(visit)
	return found
}

// construct lowers new Class(...).
func (l *lowering) construct(node *ast.Node, declaration *ast.Node) (ir.Expression, error) {
	if ast.HasSyntacticModifier(declaration, ast.ModifierFlagsAbstract) {
		return nil, &Refused{Where: l.program.Where(node), What: "new of an abstract class", Fix: "construct a concrete subclass that implements its abstract methods"}
	}
	lowered, err := l.instantiate(declaration, l.checker.GetTypeAtLocation(node), node)
	if err != nil {
		return nil, err
	}
	arguments := []ir.Expression{}
	if node.AsNewExpression().Arguments != nil {
		for _, argument := range node.AsNewExpression().Arguments.Nodes {
			value, err := l.expression(argument)
			if err != nil {
				return nil, err
			}
			arguments = append(arguments, value)
		}
	}
	return l.staticConstruct(node, declaration, lowered.constructor, arguments), nil
}

// callOrMethod lowers a call to one of the module's functions, or to a method of one of its classes.
func (l *lowering) callOrMethod(node *ast.Node) (ir.Expression, error) {
	if value, handled, err := l.classGenericCall(node); handled {
		return value, err
	}
	callee := ast.SkipParentheses(node.AsCallExpression().Expression)
	if callee.Kind == ast.KindSuperKeyword {
		return l.superCall(node)
	}
	if callee.Kind != ast.KindPropertyAccessExpression {
		return l.call(node)
	}
	receiver := callee.AsPropertyAccessExpression().Expression
	receiverType := l.concrete(l.checker.GetTypeAtLocation(receiver))
	method := l.checker.GetSymbolAtLocation(callee)
	if isClassInstance(receiverType) {
		if actual := l.checker.GetPropertyOfType(receiverType, callee.Name().Text()); actual != nil {
			method = actual
		}
	}
	// A structural signature identifies neither the static side nor an instance.
	// Leave it to callClosure's receiver lookup, using that object's named method map.
	if method == nil || len(method.Declarations) == 0 || method.Declarations[0].Kind != ast.KindMethodDeclaration {
		return l.call(node)
	}
	class := method.Declarations[0].Parent
	declaration, isClass := l.classes[l.symbol(class.Name())]
	if !isClass {
		return nil, l.notYet(node, "a method of a class stage 0 doesn't have")
	}
	if len(l.definedMembers(receiverType)) > 1 {
		return nil, l.notYet(receiver, "a method call through a union of class types; narrow with instanceof first")
	}
	if callee.AsPropertyAccessExpression().QuestionDotToken != nil {
		// object?.method(...), the object perhaps undefined: the class is instantiated for what the
		// object is when it's there, and the call is made through the object's methods, which stops
		// at undefined as JavaScript's chain does (ir.Property's Method).
		if _, err := l.instantiate(declaration, l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(receiver)), callee); err != nil {
			return nil, err
		}
		return l.callClosure(node)
	}
	// this.method() is the instantiation being lowered: this is the polymorphic this type there,
	// which carries no type arguments of its own.
	lowered := l.instance
	if ast.HasSyntacticModifier(method.Declarations[0], ast.ModifierFlagsStatic) {
		var err error
		if lowered == nil || !lowered.static || (ast.SkipParentheses(receiver).Kind != ast.KindThisKeyword && ast.SkipParentheses(receiver).Kind != ast.KindSuperKeyword) {
			lowered, err = l.staticInstance(l.staticClass(receiverType, declaration))
			if err != nil {
				return nil, err
			}
		}
	} else if (ast.SkipParentheses(receiver).Kind != ast.KindThisKeyword && ast.SkipParentheses(receiver).Kind != ast.KindSuperKeyword) || lowered == nil {
		var err error
		if lowered, err = l.instantiate(declaration, receiverType, callee); err != nil {
			return nil, err
		}
	}
	if ast.SkipParentheses(receiver).Kind == ast.KindSuperKeyword {
		if l.instance == nil || l.instance.base == nil {
			return nil, l.notYet(node, "super outside a derived class")
		}
		lowered = l.instance.base
	}
	var object ir.Expression
	var err error
	if ast.SkipParentheses(receiver).Kind == ast.KindSuperKeyword {
		if err := l.useOfThis(receiver); err != nil {
			return nil, err
		}
		// super.method() reads this as this.method() does, and inside an arrow that's a capture.
		l.touch(l.this)
		object = ir.Read{Local: l.this, Of: ir.Object}
	} else {
		object, err = l.expression(receiver)
	}
	if err != nil {
		return nil, err
	}
	object = l.privateStaticReceiver(callee.Name(), object, false)
	values, spread, err := l.callArguments(node.AsCallExpression().Arguments.Nodes)
	if err != nil {
		return nil, err
	}
	arguments := append([]ir.Expression{object}, values...)
	if len(spread) > 0 {
		spread = append([]bool{false}, spread...)
	}
	function := lowered.methods[l.fieldName(callee.Name())]
	l.fitCallArguments(function, arguments, spread)
	virtual := lowered.slots[l.fieldName(callee.Name())] + 1
	if ast.SkipParentheses(receiver).Kind == ast.KindSuperKeyword {
		virtual = 0
	}
	return ir.Call{Function: function, Arguments: arguments, Spread: spread, Returns: l.result.Functions[function].Returns, Virtual: virtual}, nil
}

// setProperty lowers object.name = value, as a statement.
func (l *lowering) setProperty(target *ast.Node, valueNode *ast.Node) ([]ir.Statement, error) {
	if call, handled, err := l.superAccessor(target, valueNode); handled {
		if err != nil {
			return nil, err
		}
		return []ir.Statement{ir.Evaluate{Value: call}}, nil
	}
	if member := l.checker.GetSymbolAtLocation(target); member != nil && member.Flags&ast.SymbolFlagsMethod != 0 {
		return nil, l.notYet(target, "replacing a represented method at runtime")
	}
	if err := l.absentOptionalWrite(target); err != nil {
		return nil, err
	}
	object, err := l.expression(target.AsPropertyAccessExpression().Expression)
	if err != nil {
		return nil, err
	}
	if object.Type() != ir.Object {
		return nil, l.notYet(target, "assigning a field of a "+typeName(object.Type()))
	}
	value, err := l.expression(valueNode)
	if err != nil {
		return nil, err
	}
	of, err := l.typeOf(target)
	if field := l.checker.GetSymbolAtLocation(target.Name()); field != nil {
		// What the field is declared to keep, not what the checker narrowed this write to.
		of, err = l.typeOfSymbol(target, field)
	}
	if err != nil || censusFieldSlotless(of) || censusFieldSlotless(value.Type()) {
		return nil, l.notYet(target, "storing "+l.checker.TypeToString(l.checker.GetTypeAtLocation(target))+" in a field")
	}
	// A field of number | undefined is given a packed word, whatever it's assigned.
	value = fit(value, of)
	if call, handled := l.privateStaticStore(target, object, value); handled {
		return []ir.Statement{ir.Evaluate{Value: call}}, nil
	}
	// A #private field is stored under its name, # and all, which nothing else can spell.
	return []ir.Statement{ir.SetProperty{Object: object, Name: l.fieldName(target.Name()), Value: value, Class: l.classOf(target), Site: l.writeSite(target.AsPropertyAccessExpression().Expression)}}, nil
}

// absentOptionalWrite refuses a write to an optional own field of a plain object when some literal left
// that field out: the literal's object has no slot for it, and the write would find none ('a field the
// checker proved is there is missing'), whatever the field's representation. A field held in a Union is
// refused wherever it's written, as before. A class instance declares every field, so it has the slot.
// Optional presence lifts this (#r3chqza).
func (l *lowering) absentOptionalWrite(target *ast.Node) error {
	member := l.checker.GetSymbolAtLocation(target)
	if member == nil || member.Flags&ast.SymbolFlagsOptional == 0 || isClassInstance(l.checker.GetTypeAtLocation(target.AsPropertyAccessExpression().Expression)) {
		return nil
	}
	if stored, _ := l.representation(l.checker.GetTypeOfSymbol(member)); stored == ir.Union {
		return l.notYet(target, "writing a possibly absent optional own field")
	}
	if l.omittedOptionals[member] && !presentBeforeWrite(target) && !l.literalGivesField(target) {
		return l.notYet(target, "writing a possibly absent optional own field")
	}
	return nil
}

// presentBeforeWrite is a write to object.name inside the then branch of an if that tested
// object.name !== undefined (or != null), the same spelling, directly or as a term of &&: a value was
// there, so the object has the slot.
func presentBeforeWrite(target *ast.Node) bool {
	spelled := accessPath(target)
	if spelled == "" {
		return false
	}
	for child, parent := target, target.Parent; parent != nil; child, parent = parent, parent.Parent {
		if parent.Kind == ast.KindFunctionDeclaration || parent.Kind == ast.KindArrowFunction || parent.Kind == ast.KindFunctionExpression || parent.Kind == ast.KindMethodDeclaration {
			return false
		}
		if parent.Kind != ast.KindIfStatement || parent.AsIfStatement().ThenStatement != child {
			continue
		}
		if testsPresence(parent.AsIfStatement().Expression, spelled) {
			return true
		}
	}
	return false
}

func testsPresence(condition *ast.Node, spelled string) bool {
	condition = ast.SkipParentheses(condition)
	if condition.Kind != ast.KindBinaryExpression {
		return false
	}
	binary := condition.AsBinaryExpression()
	switch binary.OperatorToken.Kind {
	case ast.KindAmpersandAmpersandToken:
		return testsPresence(binary.Left, spelled) || testsPresence(binary.Right, spelled)
	case ast.KindExclamationEqualsEqualsToken, ast.KindExclamationEqualsToken:
		left, right := ast.SkipParentheses(binary.Left), ast.SkipParentheses(binary.Right)
		absent := right.Kind == ast.KindUndefinedKeyword || right.Kind == ast.KindNullKeyword || (right.Kind == ast.KindIdentifier && right.Text() == "undefined")
		return absent && accessPath(left) == spelled
	}
	return false
}

// plainPropertyName is a literal member's name when it's spelled as an identifier, a string or a
// number, and "" for a computed name, which gives no field this can see.
func plainPropertyName(property *ast.Node) string {
	name := property.Name()
	if name == nil {
		return ""
	}
	switch name.Kind {
	case ast.KindIdentifier, ast.KindStringLiteral, ast.KindNumericLiteral:
		return name.Text()
	}
	return ""
}

// accessPath spells a chain of names (this.a.b, node.flow), and gives "" for anything else, which
// matches nothing.
func accessPath(node *ast.Node) string {
	node = ast.SkipParentheses(node)
	switch node.Kind {
	case ast.KindIdentifier:
		return node.Text()
	case ast.KindThisKeyword:
		return "this"
	case ast.KindPropertyAccessExpression:
		if inner := accessPath(node.AsPropertyAccessExpression().Expression); inner != "" {
			return inner + "." + node.AsPropertyAccessExpression().Name().Text()
		}
	}
	return ""
}

// literalGivesField is a write through a const whose initializer is an object literal naming the field.
func (l *lowering) literalGivesField(target *ast.Node) bool {
	receiver := ast.SkipParentheses(target.AsPropertyAccessExpression().Expression)
	if receiver.Kind != ast.KindIdentifier {
		return false
	}
	symbol := l.checker.GetSymbolAtLocation(receiver)
	if symbol == nil || symbol.ValueDeclaration == nil || symbol.ValueDeclaration.Kind != ast.KindVariableDeclaration {
		return false
	}
	declaration := symbol.ValueDeclaration
	if declaration.Parent == nil || declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
		return false
	}
	initializer := declaration.AsVariableDeclaration().Initializer
	if initializer == nil || ast.SkipParentheses(initializer).Kind != ast.KindObjectLiteralExpression {
		return false
	}
	name := target.AsPropertyAccessExpression().Name().Text()
	for _, property := range ast.SkipParentheses(initializer).AsObjectLiteralExpression().Properties.Nodes {
		if property.Kind != ast.KindSpreadAssignment && plainPropertyName(property) == name {
			return true
		}
	}
	return false
}

// noteOmittedOptionals finds every object literal whose context types it and records the optional
// properties of that type it leaves out. A spread counts as giving a property its source declares
// required.
func (l *lowering) noteOmittedOptionals(modules []*ast.SourceFile) {
	l.omittedOptionals = map[*ast.Symbol]bool{}
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if node.Kind == ast.KindObjectLiteralExpression {
			l.noteOmittedOptionalsOf(node)
		}
		return node.ForEachChild(visit)
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
}

func (l *lowering) noteOmittedOptionalsOf(literal *ast.Node) {
	contextual := l.checker.GetContextualType(literal, checker.ContextFlagsNone)
	if contextual == nil {
		return
	}
	given := map[string]bool{}
	var spreads []*checker.Type
	for _, property := range literal.AsObjectLiteralExpression().Properties.Nodes {
		if property.Kind == ast.KindSpreadAssignment {
			spreads = append(spreads, l.checker.GetTypeAtLocation(property.AsSpreadAssignment().Expression))
			continue
		}
		if name := plainPropertyName(property); name != "" {
			given[name] = true
		}
	}
	members := []*checker.Type{contextual}
	if contextual.Flags()&checker.TypeFlagsUnion != 0 {
		members = contextual.Types()
	}
	for _, member := range members {
		if member.Flags()&checker.TypeFlagsObject == 0 {
			continue
		}
		for _, property := range l.checker.GetPropertiesOfType(member) {
			if property.Flags&ast.SymbolFlagsOptional == 0 || given[property.Name] {
				continue
			}
			spread := false
			for _, source := range spreads {
				if inside := l.checker.GetPropertyOfType(source, property.Name); inside != nil && inside.Flags&ast.SymbolFlagsOptional == 0 {
					spread = true
				}
			}
			if !spread {
				l.omittedOptionals[property] = true
			}
		}
	}
}

// updateProperty lowers object.name op= value, and object.name++ and -- (a nil value, a step of 1).
// JavaScript evaluates the object once, reads the field, then evaluates the value: a variable may be
// read twice, since nothing runs between the two reads, and anything else is held in a local of its
// own for the statement, so make().count++ makes one object.
func (l *lowering) updateProperty(node *ast.Node, target *ast.Node, operator ast.Kind, valueNode *ast.Node) ([]ir.Statement, error) {
	if err := l.absentOptionalWrite(target); err != nil {
		return nil, err
	}
	object, err := l.expression(target.AsPropertyAccessExpression().Expression)
	if err != nil {
		return nil, err
	}
	if object.Type() != ir.Object {
		return nil, l.notYet(target, "assigning a field of a "+typeName(object.Type()))
	}
	of, err := l.typeOf(target)
	if err != nil {
		return nil, err
	}
	object = l.privateStaticReceiver(target.Name(), object, false)
	statements := []ir.Statement{}
	field := l.checker.GetSymbolAtLocation(target.Name())
	_, isRead := object.(ir.Read)
	if !isRead || (field != nil && accessorSymbol(field)) {
		held := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: "object", Type: ir.Object, Function: l.functionIndex})
		l.noteLocal(held, l.concrete(l.checker.GetTypeAtLocation(target.AsPropertyAccessExpression().Expression)), target)
		statements = append(statements, ir.Declare{Local: held, Value: object})
		object = ir.Read{Local: held, Of: ir.Object}
	}
	value := ir.Expression(ir.NumberConstant{Value: 1})
	if valueNode != nil {
		if value, err = l.expression(valueNode); err != nil {
			return nil, err
		}
	}
	name := l.fieldName(target.Name())
	current := l.readObjectField(target, ir.Property{Object: object, Name: name, Of: of, Class: l.classOf(target)})
	if operator == ast.KindPlusToken && valueNode != nil {
		current, value = l.spelled(target, current), l.spelled(valueNode, value)
	}
	updated, err := l.combine(node, operator, current, value)
	if err != nil {
		return nil, err
	}
	statements = append(statements, ir.SetProperty{Object: object, Name: name, Value: updated, Class: l.classOf(target), Site: l.writeSite(target.AsPropertyAccessExpression().Expression)})
	if len(statements) == 1 {
		return statements, nil
	}
	return []ir.Statement{ir.Block{Body: statements}}, nil
}

// classOf is, for an access to a class's field, that class's constructor plus one, and 0 for any other
// access, so the emitter can find the field where the class's layout puts it. Only a class without
// type parameters, already lowered, is looked up: one with them has a layout per instantiation, and
// looking up never lowers a class, so a program that compiled before can't stop compiling here.
func (l *lowering) classOf(access *ast.Node) int {
	field := l.checker.GetSymbolAtLocation(access.Name())
	if field == nil || len(field.Declarations) != 1 || (field.Declarations[0].Kind != ast.KindPropertyDeclaration && !parameterProperty(field.Declarations[0])) {
		return 0
	}
	if ast.HasSyntacticModifier(field.Declarations[0], ast.ModifierFlagsStatic) {
		return 0
	}
	class := field.Declarations[0].Parent
	if parameterProperty(field.Declarations[0]) {
		class = class.Parent
	}
	if class == nil || class.Kind != ast.KindClassDeclaration || len(class.TypeParameters()) > 0 {
		return 0
	}
	if lowered, isLowered := l.instances[l.classInstanceKey(class, nil)]; isLowered {
		return lowered.constructor + 1
	}
	return 0
}

func nodesOf(list *ast.NodeList) []*ast.Node {
	if list == nil {
		return nil
	}
	return list.Nodes
}

// lastFieldAssignment is where, in the constructor body, every field without an initializer has
// been assigned: the end of the latest of their first assignments, each a statement of the body
// itself, which run in order and unconditionally. A field first assigned anywhere else (in a branch,
// a loop or a closure) is set by no point the body can be sure of, so it's the body's end; 0 when
// there are no such fields. Before that point, JavaScript reads an unset field as undefined, which a
// field of number or string can't hold: the checker proves the constructor itself never reads one,
// but not a method it calls, nor anything it hands this to (useOfThis).
func lastFieldAssignment(declaration *ast.Node, constructor *ast.Node) int {
	unset := map[string]bool{}
	for _, member := range declaration.Members() {
		if member.Kind == ast.KindPropertyDeclaration && member.AsPropertyDeclaration().Initializer == nil && !(member.PostfixToken() != nil && member.PostfixToken().Kind == ast.KindExclamationToken) && !ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			unset[member.Name().Text()] = true
		}
	}
	if len(unset) == 0 || constructor.Body() == nil {
		return 0
	}
	last := 0
	for _, statement := range constructor.Body().AsBlock().Statements.Nodes {
		if len(unset) == 0 {
			break
		}
		if statement.Kind != ast.KindExpressionStatement {
			continue
		}
		assignment := ast.SkipParentheses(statement.AsExpressionStatement().Expression)
		if assignment.Kind != ast.KindBinaryExpression || assignment.AsBinaryExpression().OperatorToken.Kind != ast.KindEqualsToken {
			continue
		}
		target := ast.SkipParentheses(assignment.AsBinaryExpression().Left)
		if target.Kind == ast.KindPropertyAccessExpression && ast.SkipParentheses(target.AsPropertyAccessExpression().Expression).Kind == ast.KindThisKeyword && unset[target.Name().Text()] {
			delete(unset, target.Name().Text())
			last = statement.End()
		}
	}
	if len(unset) > 0 {
		return constructor.Body().End()
	}
	return last
}

// useOfThis refuses this, in a constructor before its last field is assigned, anywhere but as the
// object of a field it reads or writes: a method it calls, or a function it's handed to, could read a
// field not set yet.
func (l *lowering) useOfThis(node *ast.Node) error {
	if l.instance != nil && l.instance.unreadyThis[node] {
		return &Refused{Where: l.program.Where(node), What: "this before super returns", Fix: "call super(...) before using this"}
	}
	if l.instance != nil && l.instance.constructing && l.instance.hasDescendants {
		if parent := node.Parent; parent != nil && parent.Kind == ast.KindPropertyAccessExpression {
			if field := l.checker.GetSymbolAtLocation(parent.Name()); field != nil && field.Flags&ast.SymbolFlagsProperty != 0 {
				return nil
			}
		}
		return &Refused{Where: l.program.Where(node), What: "this escaping a base constructor before derived fields are initialized", Fix: "use this only to read or write initialized base fields; call methods and publish the object after construction"}
	}
	if l.unsetUntil == 0 || node.Pos() >= l.unsetUntil {
		return nil
	}
	if parent := node.Parent; parent != nil && parent.Kind == ast.KindPropertyAccessExpression && parent.AsPropertyAccessExpression().Expression == node {
		if field := l.checker.GetSymbolAtLocation(parent.Name()); field != nil && len(field.Declarations) > 0 && (field.Declarations[0].Kind == ast.KindPropertyDeclaration || parameterProperty(field.Declarations[0])) {
			return nil
		}
	}
	return &Refused{Where: l.program.Where(node), What: "this escaping a constructor before every field is set (stored, passed, or a method called on it, which could read a field that holds undefined while its type says otherwise)", Fix: "assign every field first, then use this"}
}

// The checker owns type identity, including recursive structural types. Reuse the
// first representative's key rather than treating a fresh checker object as a new type.
//
//go:linkname identicalTypes github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).isTypeIdenticalTo
func identicalTypes(checker *checker.Checker, source, target *checker.Type) bool

func (l *lowering) classKeyPrefix(declaration *ast.Node) string {
	return l.program.Where(declaration) + ":" + declaration.Name().Text()
}

func (l *lowering) sameClassArguments(from, to []*checker.Type) bool {
	if len(from) != len(to) {
		return false
	}
	for index := range from {
		if !identicalTypes(l.checker, from[index], to[index]) {
			return false
		}
	}
	return true
}

func (l *lowering) classInstanceKey(declaration *ast.Node, arguments []*checker.Type) string {
	prefix := l.classKeyPrefix(declaration)
	key := prefix
	for _, argument := range arguments {
		key += "," + l.genericTypeKey(argument)
	}
	return key
}

func (l *lowering) classKeyMatches(key string, declaration *ast.Node) bool {
	prefix := l.classKeyPrefix(declaration)
	return key == prefix || strings.HasPrefix(key, prefix+",")
}

class_accessors.go:
package lower

import (
	"fmt"
	"reflect"
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

func accessorMember(node *ast.Node) bool {
	return node.Kind == ast.KindGetAccessor || node.Kind == ast.KindSetAccessor
}
func classFunction(node *ast.Node) bool {
	return node.Kind == ast.KindMethodDeclaration || accessorMember(node)
}
func (l *lowering) methodKey(node *ast.Node, class int) string {
	if node.Name().Kind == ast.KindComputedPropertyName {
		return iteratorSlot
	}
	name := l.memberKey(node.Name(), class)
	if node.Kind == ast.KindGetAccessor {
		return "$get:" + name
	}
	if node.Kind == ast.KindSetAccessor {
		return "$set:" + name
	}
	return name
}

func (l *lowering) registerAccessor(class int, node *ast.Node, function int) {
	name := l.memberKey(node.Name(), class)
	metadata := &l.result.Classes[class-1]
	index := -1
	for i, accessor := range metadata.Accessors {
		if accessor.Name == name {
			index = i
		}
	}
	if index < 0 {
		index = len(metadata.Accessors)
		metadata.Accessors = append(metadata.Accessors, ir.Accessor{Name: name, Getter: -1, Setter: -1})
	}
	if node.Kind == ast.KindGetAccessor {
		metadata.Accessors[index].Getter = function
	} else {
		metadata.Accessors[index].Setter = function
	}
}

func (l *lowering) superAccessor(target *ast.Node, valueNode *ast.Node) (ir.Expression, bool, error) {
	receiver := ast.SkipParentheses(target.AsPropertyAccessExpression().Expression)
	if receiver.Kind != ast.KindSuperKeyword {
		return nil, false, nil
	}
	if l.instance == nil || l.instance.base == nil {
		return nil, true, l.notYet(target, "super outside a derived accessor or method")
	}
	if err := l.useOfThis(receiver); err != nil {
		return nil, true, err
	}
	prefix := "$get:"
	if valueNode != nil {
		prefix = "$set:"
	}
	index, exists := l.instance.base.methods[prefix+l.fieldName(target.Name())]
	if !exists {
		if l.instance.static {
			symbol := l.checker.GetSymbolAtLocation(target.Name())
			if symbol != nil && len(symbol.Declarations) > 0 && symbol.Declarations[0].Kind == ast.KindPropertyDeclaration {
				of, err := l.typeOfSymbol(target, symbol)
				if err != nil {
					return nil, true, err
				}
				if valueNode == nil {
					parent := l.staticBase(l.classNode.Parent)
					return ir.Property{Object: ir.Read{Local: l.staticGlobals[l.symbol(parent.Name())], Of: ir.Object, Checked: true}, Name: l.fieldName(target.Name()), Of: of}, true, nil
				}
				value, err := l.expression(valueNode)
				if err != nil {
					return nil, true, err
				}
				index := len(l.result.Functions)
				self := len(l.result.Locals)
				l.result.Locals = append(l.result.Locals, ir.Local{Name: "this", Type: ir.Object, Function: index}, ir.Local{Name: "value", Type: of, Function: index})
				l.result.Functions = append(l.result.Functions, ir.Function{Name: "super_static_set", Parameters: []int{self, self + 1}, Body: []ir.Statement{ir.SetProperty{Object: ir.Read{Local: self, Of: ir.Object}, Name: l.fieldName(target.Name()), Value: ir.Read{Local: self + 1, Of: of}, Site: l.staticWriteSite(target)}}})
				return ir.Call{Function: index, Arguments: []ir.Expression{ir.Read{Local: l.this, Of: ir.Object}, fit(value, of)}}, true, nil
			}
		}
		return nil, true, l.notYet(target, "super of a member without the requested accessor")
	}
	arguments := []ir.Expression{ir.Read{Local: l.this, Of: ir.Object}}
	if valueNode != nil {
		value, err := l.expression(valueNode)
		if err != nil {
			return nil, true, err
		}
		value = fit(value, l.result.Locals[l.result.Functions[index].Parameters[1]].Type)
		arguments = append(arguments, value)
	}
	return ir.Call{Function: index, Arguments: arguments, Returns: l.result.Functions[index].Returns}, true, nil
}

// Literal accessors are closures with an explicit receiver. The receiver is never captured by the
// accessor itself, so storing the closure in its object introduces no implicit self-cycle.
func (l *lowering) literalAccessor(owner, declaration *ast.Node) (ir.Expression, int, error) {
	index := len(l.result.Functions)
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "accessor", Closure: true})
	self := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "this", Type: ir.Object, Function: index})
	l.noteLocal(self, l.concrete(l.checker.GetTypeAtLocation(owner)), owner)
	l.accessorCaptures = append(l.accessorCaptures, accessorCapture{holder: l.concrete(l.checker.GetTypeAtLocation(owner)), function: index})
	outerInstance, outerUnset := l.instance, l.unsetUntil
	l.instance, l.unsetUntil = nil, 0
	l.closures = append(l.closures, index)
	err := l.lowerFunction(index, declaration, self)
	l.closures = l.closures[:len(l.closures)-1]
	l.instance, l.unsetUntil = outerInstance, outerUnset
	if err != nil {
		return nil, 0, err
	}
	return ir.MakeClosure{Function: index}, index, nil
}

type accessorCapture struct {
	holder   *checker.Type
	function int
}

func (l *lowering) accessorLiteral(node *ast.Node) (ir.Expression, bool, error) {
	properties := node.AsObjectLiteralExpression().Properties.Nodes
	found := false
	for _, property := range properties {
		found = found || accessorMember(property)
	}
	if !found {
		return nil, false, nil
	}
	class := len(l.result.Classes) + 1
	l.result.Classes = append(l.result.Classes, ir.Class{Name: "literal_accessors", Constructor: -1, Literal: true})
	literal := ir.ObjectLiteral{Class: class}
	keys := map[string]bool{}
	for _, property := range properties {
		if property.Kind == ast.KindSpreadAssignment {
			return nil, true, l.notYet(property, "an accessor literal with a spread")
		}
		name := property.Name()
		if name == nil || (!ast.IsIdentifier(name) && name.Kind != ast.KindStringLiteral) {
			return nil, true, l.notYet(property, "a computed accessor literal name")
		}
		if strings.HasPrefix(name.Text(), "#accessor:") {
			return nil, true, l.notYet(name, "an accessor literal property name reserved for closure storage; rename the property")
		}
		var value ir.Expression
		var err error
		if accessorMember(property) {
			var function int
			value, function, err = l.literalAccessor(node, property)
			if err != nil {
				return nil, true, err
			}
			l.registerAccessor(class, property, function)
			storage := fmt.Sprintf("#accessor:%d", function)
			literal.Fields = append(literal.Fields, ir.Field{Name: storage, Value: value, Private: true})
			if !keys[name.Text()] {
				of, err := l.typeOf(name)
				if err != nil || slotless(of) {
					return nil, true, l.notYet(property, "an accessor without a native property representation")
				}
				l.result.Classes[class-1].PublicFields = append(l.result.Classes[class-1].PublicFields, ir.Field{Name: name.Text(), Value: zeroValue(of)})
				keys[name.Text()] = true
			}
			continue
		}
		switch property.Kind {
		case ast.KindPropertyAssignment:
			value, err = l.expression(property.AsPropertyAssignment().Initializer)
		case ast.KindShorthandPropertyAssignment:
			value, err = l.shorthand(property)
		default:
			return nil, true, l.notYet(property, "a non-accessor method in an accessor literal")
		}
		if err != nil {
			return nil, true, err
		}
		if of := l.declaredField(node, name.Text()); of != 0 {
			value = fit(value, of)
		}
		if slotless(value.Type()) {
			return nil, true, l.notYet(property, "an accessor literal's field without a native slot")
		}
		field := ir.Field{Name: name.Text(), Value: value}
		literal.Fields = append(literal.Fields, field)
		if !keys[name.Text()] {
			l.result.Classes[class-1].PublicFields = append(l.result.Classes[class-1].PublicFields, field)
			keys[name.Text()] = true
		}
	}
	l.result.Classes[class-1].Fields = literal.Fields
	return literal, true, nil
}

// Property reads and writes become dispatch functions only for names for which this program has
// accessors. A structural view still invokes the actual descriptor; plain fields keep their load.
func (l *lowering) finishAccessors() error {
	names := map[string]bool{}
	for _, class := range l.result.Classes {
		for _, accessor := range class.Accessors {
			names[accessor.Name] = true
		}
	}
	if len(names) == 0 {
		return nil
	}
	groups := map[string][]int{}
	for _, class := range l.result.Classes {
		for _, accessor := range class.Accessors {
			if accessor.Getter >= 0 {
				groups["get:"+accessor.Name] = append(groups["get:"+accessor.Name], accessor.Getter)
			}
			if accessor.Setter >= 0 {
				groups["set:"+accessor.Name] = append(groups["set:"+accessor.Name], accessor.Setter)
			}
		}
	}
	dispatchers := map[string]int{}
	var failure error
	dispatch := func(name string, of ir.Type, setter bool, site int) int {
		kind := "get:"
		if setter {
			kind = "set:"
		}
		key := fmt.Sprintf("%s%s:%d:%d", kind, name, of, site)
		if index, exists := dispatchers[key]; exists {
			return index
		}
		for _, class := range l.result.Classes {
			for _, accessor := range class.Accessors {
				if accessor.Name == name && ((setter && accessor.Setter < 0) || (!setter && accessor.Getter < 0)) {
					failure = &NotYet{Where: l.result.Source, What: "a property name shared with a descriptor missing the requested getter or setter"}
					return 0
				}
			}
		}
		targets := groups[kind+name]
		if len(targets) == 0 {
			failure = &NotYet{Where: l.result.Source, What: "reading a setter-only property or writing a getter-only property"}
			return 0
		}
		for _, target := range targets {
			actual := l.result.Functions[target].Returns
			if setter {
				actual = l.result.Locals[l.result.Functions[target].Parameters[1]].Type
			}
			if actual != of {
				failure = &NotYet{Where: l.result.Source, What: "accessors sharing a name with different native representations"}
				return 0
			}
		}
		index := len(l.result.Functions)
		dispatchers[key] = index
		function := ir.Function{Name: "property_" + kind + name, Returns: of}
		self := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: "object", Type: ir.Object, Function: index})
		function.Parameters = []int{self}
		object := ir.Read{Local: self, Of: ir.Object}
		call := ir.Call{Function: targets[0], Arguments: []ir.Expression{object}, Returns: of, Virtual: -1, Accessor: name}
		l.result.MethodTargets[targets[0]] = targets
		if setter {
			function.Returns, call.Returns, call.Setter = 0, 0, true
			incoming := len(l.result.Locals)
			l.result.Locals = append(l.result.Locals, ir.Local{Name: "value", Type: of, Function: index})
			function.Parameters = append(function.Parameters, incoming)
			value := ir.Read{Local: incoming, Of: of}
			call.Arguments = append(call.Arguments, value)
			function.Body = []ir.Statement{ir.If{Condition: ir.HasAccessor{Object: object, Name: name}, Then: []ir.Statement{ir.Evaluate{Value: call}}, Else: []ir.Statement{ir.SetProperty{Object: object, Name: name, Value: value, Site: site}}}}
		} else {
			function.Body = []ir.Statement{ir.If{Condition: ir.HasAccessor{Object: object, Name: name}, Then: []ir.Statement{ir.Return{Value: call}}}, ir.Return{Value: ir.Property{Object: object, Name: name, Of: of}}}
		}
		l.result.Functions = append(l.result.Functions, function)
		return index
	}
	var transform func(reflect.Value) reflect.Value
	transform = func(value reflect.Value) reflect.Value {
		if !value.IsValid() {
			return value
		}
		if value.Kind() == reflect.Interface {
			if value.IsNil() {
				return value
			}
			mapped := transform(value.Elem())
			node := mapped.Interface()
			switch expression := node.(type) {
			case ir.ObjectLiteral:
				if expression.Spread != nil {
					expression.NoReuse = true
					node = expression
				}
			case ir.Property:
				if names[expression.Name] {
					if expression.Optional {
						failure = &NotYet{Where: l.result.Source, What: "an optional accessor read"}
						return value
					}
					index := dispatch(expression.Name, expression.Of, false, 0)
					node = ir.Call{Function: index, Arguments: []ir.Expression{expression.Object}, Returns: expression.Of}
				}
			case ir.SetProperty:
				if names[expression.Name] && !expression.Define {
					index := dispatch(expression.Name, expression.Value.Type(), true, expression.Site)
					node = ir.Evaluate{Value: ir.Call{Function: index, Arguments: []ir.Expression{expression.Object, expression.Value}}}
				}
			}
			result := reflect.New(value.Type()).Elem()
			result.Set(reflect.ValueOf(node))
			return result
		}
		switch value.Kind() {
		case reflect.Struct:
			result := reflect.New(value.Type()).Elem()
			for i := 0; i < value.NumField(); i++ {
				result.Field(i).Set(transform(value.Field(i)))
			}
			return result
		case reflect.Slice:
			if value.IsNil() {
				return value
			}
			result := reflect.MakeSlice(value.Type(), value.Len(), value.Len())
			for i := 0; i < value.Len(); i++ {
				result.Index(i).Set(transform(value.Index(i)))
			}
			return result
		}
		return value
	}
	// Generated fallback loads must not be rewritten into their own dispatchers.
	count := len(l.result.Functions)
	l.result.Main = transform(reflect.ValueOf(l.result.Main)).Interface().([]ir.Statement)
	for index := 0; index < count; index++ {
		l.result.Functions[index].Body = transform(reflect.ValueOf(l.result.Functions[index].Body)).Interface().([]ir.Statement)
	}
	return failure
}

func accessorSymbol(symbol *ast.Symbol) bool {
	for _, declaration := range symbol.Declarations {
		if accessorMember(declaration) {
			return true
		}
	}
	return false
}
func (l *lowering) hasAccessorStorage(proven *checker.Type) bool {
	for _, property := range l.checker.GetPropertiesOfType(l.concrete(proven)) {
		if accessorSymbol(property) {
			return true
		}
	}
	return false
}

// Until spread callbacks are explicit calls in the flow graph, their exception edges must not be lost.
func (l *lowering) checkAccessorSpreads() error {
	setterOnly := false
	for _, class := range l.result.Classes {
		for _, accessor := range class.Accessors {
			setterOnly = setterOnly || (class.Literal && accessor.Getter < 0)
		}
	}
	throwing := false
	for _, class := range l.result.Classes {
		for _, accessor := range class.Accessors {
			if class.Literal && accessor.Getter >= 0 && (l.result.Functions[accessor.Getter].MayThrow || l.libraryFailure(l.result.Functions[accessor.Getter].Body, map[int]bool{}) != "") {
				throwing = true
			}
		}
	}
	if !throwing && !setterOnly && len(l.staticGlobals) == 0 {
		return nil
	}
	spread := false
	check := func(node any) bool {
		if literal, ok := node.(ir.ObjectLiteral); ok && literal.Spread != nil {
			spread = true
		}
		return true
	}
	walk(l.result.Main, check)
	for _, function := range l.result.Functions {
		walk(function.Body, check)
	}
	if spread && len(l.staticGlobals) > 0 {
		return &NotYet{Where: l.result.Source, What: "spreading in a program with static constructor objects"}
	}
	if spread && setterOnly {
		return &NotYet{Where: l.result.Source, What: "spreading a setter-only property, whose read value is undefined"}
	}
	if spread {
		return &NotYet{Where: l.result.Source, What: "spreading an accessor literal whose getter may throw"}
	}
	return nil
}

func (l *lowering) noteAccessorNames(modules []*ast.SourceFile) {
	l.accessorNames = map[string]bool{}
	for _, module := range modules {
		var visit ast.Visitor
		visit = func(node *ast.Node) bool {
			if node.Kind == ast.KindGetAccessor && node.Name() != nil {
				l.accessorNames[node.Name().Text()] = true
			}
			return node.ForEachChild(visit)
		}
		module.AsNode().ForEachChild(visit)
	}
}

func (l *lowering) validateAccessorSignature(member *ast.Node, function int) error {
	signature := l.result.Functions[function]
	if member.Kind == ast.KindGetAccessor && (signature.Returns == 0 || signature.Returns == ir.MaybeBoolean) {
		return l.notYet(member, "a getter without a native adamic_value representation")
	}
	if member.Kind == ast.KindSetAccessor && l.result.Locals[signature.Parameters[1]].Type == ir.MaybeBoolean {
		return l.notYet(member, "a setter whose input needs two native words")
	}
	return nil
}

class_features.go:
package lower

import (
	"strconv"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// memberKey is a class member's slot or method name. A private name is qualified by the class that
// declares it (privateName), the same spelling fieldName gives every read and write of it, so a
// definition and its uses always agree, whichever instantiation or static object holds it.
func (l *lowering) memberKey(name *ast.Node, class int) string {
	if name.Kind == ast.KindPrivateIdentifier {
		if declaring := l.declaringClass(name); declaring != nil {
			return l.privateName(name.Text(), declaring)
		}
		return name.Text() + "@" + strconv.Itoa(class)
	}
	return name.Text()
}

// declaringClass is the class declaration a private name belongs to, or nil.
func (l *lowering) declaringClass(name *ast.Node) *ast.Node {
	if symbol := l.checker.GetSymbolAtLocation(name); symbol != nil && len(symbol.Declarations) > 0 {
		if class := symbol.Declarations[0].Parent; class != nil && class.Kind == ast.KindClassDeclaration {
			return class
		}
	}
	if name.Parent != nil && name.Parent.Parent != nil && name.Parent.Parent.Kind == ast.KindClassDeclaration {
		return name.Parent.Parent
	}
	return nil
}

// privateName is a private name's field name: its spelling qualified by the class declaring it, numbered
// in the order classes are first met. By the declaration, not an instantiation: inside Box<number>,
// other.#label with other a Box<string> is Box<string>'s slot, and every instantiation holds its private
// members under the same names; a class chain holds each declaration once, so names never collide.
func (l *lowering) privateName(spelling string, class *ast.Node) string {
	if l.privateOwners == nil {
		l.privateOwners = map[*ast.Node]int{}
	}
	owner, isKnown := l.privateOwners[class]
	if !isKnown {
		owner = len(l.privateOwners) + 1
		l.privateOwners[class] = owner
	}
	return spelling + "@" + strconv.Itoa(owner)
}

func (l *lowering) hasPrivateStorage(proven *checker.Type) bool {
	proven = l.concrete(proven)
	for _, property := range l.checker.GetPropertiesOfType(proven) {
		for _, declaration := range property.Declarations {
			if declaration.Kind == ast.KindPropertyDeclaration && declaration.Name().Kind == ast.KindPrivateIdentifier {
				return true
			}
		}
	}
	return false
}

func (l *lowering) objectKeys(node *ast.Node) (ir.Expression, bool, error) {
	callee := ast.SkipParentheses(node.AsCallExpression().Expression)
	if callee.Kind != ast.KindPropertyAccessExpression || callee.Name().Text() != "keys" || !l.isLibraryGlobal(callee.AsPropertyAccessExpression().Expression, "Object") {
		return nil, false, nil
	}
	arguments := nodesOf(node.AsCallExpression().Arguments)
	if len(arguments) != 1 {
		return nil, true, l.notYet(node, "Object.keys without exactly one argument")
	}
	// A spread of a possibly absent plain object has synthetic optional slots, not real keys.
	// Class and accessor descriptors provide the public shape for their stored fields.
	proven := l.checker.GetTypeAtLocation(arguments[0])
	if !isClassInstance(proven) && l.iteratorMember(proven) != nil {
		return nil, true, l.notYet(node, "Object.keys on a literal with symbol-key storage")
	}
	// A structural view does not remove the iterable literal's hidden symbol slot.
	// Fresh explicit string-keyed literals cannot carry storage erased by a view.
	argument := ast.SkipParentheses(arguments[0])
	fresh := argument.Kind == ast.KindObjectLiteralExpression
	if fresh {
		for _, property := range argument.AsObjectLiteralExpression().Properties.Nodes {
			fresh = fresh && property.Kind != ast.KindSpreadAssignment
		}
	}
	if !fresh && !isClassInstance(proven) && !l.isStaticType(proven) && l.iteratorMember(proven) == nil {
		modules, err := l.moduleOrder(l.program.Files()[0])
		if err != nil {
			return nil, true, err
		}
		var hazard error
		var visit ast.Visitor
		visit = func(candidate *ast.Node) bool {
			if candidate.Kind == ast.KindObjectLiteralExpression {
				shape := l.checker.GetTypeAtLocation(candidate)
				if l.iteratorMember(shape) != nil && l.iterationShapeFits(shape, proven) {
					hazard = &Refused{Where: l.program.Where(node), What: "a structural Object.keys view that can hide an iterable literal's symbol-key storage (adamic/symbol-key-view)", Fix: "pass a new plain object containing only the desired string-keyed fields to Object.keys"}
					return true
				}
			}
			return candidate.ForEachChild(visit)
		}
		for _, module := range modules {
			module.AsNode().ForEachChild(visit)
		}
		if hazard != nil {
			return nil, true, hazard
		}
	}
	if !isClassInstance(proven) && !l.isStaticType(proven) && !l.hasAccessorStorage(proven) {
		if l.isLibraryType(proven, "RegExp", "Error") || l.includesUndefined(proven) {
			return l.objectCall(node, "keys")
		}
		for _, property := range l.checker.GetPropertiesOfType(proven) {
			if property.Flags&ast.SymbolFlagsOptional != 0 {
				return l.objectCall(node, "keys")
			}
		}
	}
	value, err := l.expression(arguments[0])
	if err != nil {
		return nil, true, err
	}
	if value.Type() != ir.Object {
		return nil, true, l.notYet(node, "Object.keys on a non-object")
	}
	return ir.ObjectKeys{Object: value}, true, nil
}

class_generic_calls.go:
package lower

import (
	"reflect"
	"strconv"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// Class layouts need concrete checker types, not just a generic function's native
// representations. Keep these functions' caches separate for each actual type vector.
func (l *lowering) classGenericCall(node *ast.Node) (ir.Expression, bool, error) {
	symbol := l.symbol(ast.SkipParentheses(node.AsCallExpression().Expression))
	if symbol == nil || len(symbol.Declarations) != 1 {
		return nil, false, nil
	}
	declaration := symbol.Declarations[0]
	if declaration.Kind != ast.KindFunctionDeclaration || len(declaration.TypeParameters()) == 0 {
		return nil, false, nil
	}
	needsTypes := l.genericUsesClasses(declaration, map[*ast.Node]bool{})
	constrained := false
	for _, parameter := range declaration.TypeParameters() {
		constrained = constrained || parameter.AsTypeParameterDeclaration().Constraint != nil
	}
	if !needsTypes && !constrained {
		return nil, false, nil
	}
	resolved := l.checker.GetResolvedSignature(node)
	if resolved == nil {
		return nil, true, l.notYet(node, "a generic call whose concrete signature isn't known")
	}
	// Like instantiate.go's shim bridge, this belongs in the checker shim. Reflection
	// checks the field's existence instead of depending on the private struct's offsets.
	field := reflect.ValueOf(resolved).Elem().FieldByName("mapper")
	if !field.IsValid() || field.Kind() != reflect.Pointer || field.IsNil() {
		return nil, true, l.notYet(node, "a generic call whose checker type mapper isn't exposed")
	}
	resolvedMapper := (*typeMapper)(field.UnsafePointer())
	sources, targets := []*checker.Type{}, []*checker.Type{}
	key := l.program.Where(declaration)
	for _, parameter := range declaration.TypeParameters() {
		source := l.checker.GetTypeAtLocation(parameter.Name())
		target := l.concrete(instantiateType(l.checker, source, resolvedMapper))
		sources = append(sources, source)
		targets = append(targets, target)
		key += "," + strconv.Itoa(int(target.Id()))
	}
	mapper := newTypeMapper(sources, targets)
	if err := l.nominalTypeArguments(declaration, targets, mapper, node); err != nil {
		return nil, true, err
	}
	if !needsTypes {
		return nil, false, nil
	}
	if l.classGenericInstances == nil {
		l.classGenericInstances = map[string]map[string]int{}
	}
	bucket := l.classGenericInstances[key]
	if bucket == nil {
		bucket = map[string]int{}
		l.classGenericInstances[key] = bucket
	}
	outerMapper, outerInstances := l.typeMapper, l.genericInstances
	l.typeMapper, l.genericInstances = mapper, bucket
	defer func() { l.typeMapper, l.genericInstances = outerMapper, outerInstances }()
	value, err := l.call(node)
	return value, true, err
}

func (l *lowering) genericUsesClasses(declaration *ast.Node, seen map[*ast.Node]bool) bool {
	if seen[declaration] {
		return false
	}
	seen[declaration] = true
	needed := false
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if ast.IsIdentifier(node) {
			symbol := l.symbol(node)
			if symbol != nil && len(symbol.Declarations) == 1 {
				target := symbol.Declarations[0]
				if target.Kind == ast.KindClassDeclaration && len(target.TypeParameters()) > 0 {
					needed = true
					return true
				}
				if node.Parent != nil && node.Parent.Kind == ast.KindCallExpression && target.Kind == ast.KindFunctionDeclaration && len(target.TypeParameters()) > 0 && l.genericUsesClasses(target, seen) {
					needed = true
					return true
				}
			}
		}
		return node.ForEachChild(visit)
	}
	declaration.ForEachChild(visit)
	return needed
}

// A structural fake cannot satisfy a nominal bound, including a dependent bound
// such as U extends Box<T>. The concrete mapper preserves both parameters' meanings.
func (l *lowering) nominalTypeArguments(declaration *ast.Node, arguments []*checker.Type, mapper *typeMapper, where *ast.Node) error {
	for index, parameter := range declaration.TypeParameters() {
		node := parameter.AsTypeParameterDeclaration().Constraint
		if node == nil {
			continue
		}
		constraint := l.checker.GetTypeAtLocation(node)
		if mapper != nil {
			constraint = instantiateType(l.checker, constraint, mapper)
		}
		if mismatch := l.nominalMismatch(arguments[index], constraint, map[[2]*checker.Type]bool{}); mismatch != nil {
			return &Refused{Where: l.program.Where(where), What: "a generic argument without nominal ancestry seen as " + l.checker.TypeToString(mismatch), Fix: "use that class or a subclass as the argument; use an interface for structural constraints (adamic/nominal-class)"}
		}
	}
	return nil
}

class_inheritance.go:
package lower

import (
	"slices"
	"strconv"
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
)

func (l *lowering) baseInstance(declaration *ast.Node, classType *checker.Type) (*instance, error) {
	for _, clause := range nodesOf(declaration.AsClassDeclaration().HeritageClauses) {
		if clause.AsHeritageClause().Token != ast.KindExtendsKeyword {
			continue
		}
		types := clause.AsHeritageClause().Types.Nodes
		if len(types) != 1 || !ast.IsIdentifier(ast.SkipParentheses(types[0].AsExpressionWithTypeArguments().Expression)) {
			return nil, l.notYet(clause, "a computed class base; name the base class directly")
		}
		bases := l.classBases(classType)
		if len(bases) != 1 {
			return nil, l.notYet(clause, "a class base whose type isn't known")
		}
		baseType := bases[0]
		symbol := baseType.Symbol()
		if symbol == nil || len(symbol.Declarations) != 1 || symbol.Declarations[0].Kind != ast.KindClassDeclaration {
			return nil, l.notYet(clause, "a base that isn't a declared class")
		}
		base := symbol.Declarations[0]
		return l.instantiate(base, baseType, clause)
	}
	return nil, nil
}

// TypeScript compares methods bivariantly and mutable properties covariantly. Neither is safe
// through a base reference: arguments flow into the override, and fields can be written through it.
func (l *lowering) checkOverrides(declaration *ast.Node, classType *checker.Type) error {
	bases := l.classBases(classType)
	if len(bases) == 0 {
		return nil
	}
	return l.checkMemberOverrides(declaration, classType, bases[0], false)
}

func (l *lowering) checkMemberOverrides(declaration *ast.Node, classType, base *checker.Type, static bool) error {
	checkABI := static || len(declaration.TypeParameters()) == 0 || classType != l.checker.GetTypeAtLocation(declaration.Name())
	for _, member := range classMembersWithParameters(declaration) {
		if member.Name() == nil || ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) != static {
			continue
		}
		inherited := l.checker.GetPropertyOfType(base, member.Name().Text())
		if inherited == nil {
			continue
		}
		own := l.checker.GetTypeAtLocation(member.Name())
		if property := l.checker.GetPropertyOfType(classType, member.Name().Text()); property != nil {
			own = l.checker.GetTypeOfSymbol(property)
		}
		previous := l.checker.GetTypeOfSymbol(inherited)
		refuse := func(what, fix string) error { return &Refused{Where: l.program.Where(member), What: what, Fix: fix} }
		if (member.Kind == ast.KindMethodDeclaration) != (inherited.Flags&ast.SymbolFlagsMethod != 0) {
			return refuse("an inherited method replaced by a field, or a field replaced by a method", "keep the inherited member kind; use a different name for the new member")
		}
		if accessorMember(member) != accessorSymbol(inherited) {
			return refuse("an inherited data property replaced by an accessor, or an accessor replaced by data", "keep the inherited member kind; use another name for the new property")
		}
		if accessorMember(member) {
			ownGet, ownSet, baseGet, baseSet := false, false, false, false
			for _, candidate := range declaration.Members() {
				if candidate.Name() != nil && candidate.Name().Text() == member.Name().Text() && ast.HasSyntacticModifier(candidate, ast.ModifierFlagsStatic) == static {
					ownGet = ownGet || candidate.Kind == ast.KindGetAccessor
					ownSet = ownSet || candidate.Kind == ast.KindSetAccessor
				}
			}
			for _, candidate := range inherited.Declarations {
				baseGet = baseGet || candidate.Kind == ast.KindGetAccessor
				baseSet = baseSet || candidate.Kind == ast.KindSetAccessor
			}
			if (baseGet && !ownGet) || (baseSet && !ownSet) {
				return refuse("an accessor override that hides the inherited getter or setter", "override both halves of the inherited descriptor; delegate an unchanged half to super")
			}
			if member.Kind == ast.KindSetAccessor {
				for _, candidate := range inherited.Declarations {
					if candidate.Kind != ast.KindSetAccessor {
						continue
					}
					old := l.checker.GetSignatureFromDeclaration(candidate)
					next := l.checker.GetSignatureFromDeclaration(member)
					accepts := l.checker.GetTypeOfSymbol(old.Parameters()[0])
					override := l.checker.GetTypeOfSymbol(next.Parameters()[0])
					if !static {
						accepts = instantiateType(l.checker, accepts, l.typeMapperOf(candidate.Parent, base))
						override = instantiateType(l.checker, override, l.typeMapperOf(declaration, classType))
					}
					if !l.classAssignable(accepts, override) || l.widened(accepts, override, map[[2]*checker.Type]bool{}) != nil {
						return refuse("an accessor override that narrows a setter parameter (adamic/contravariant-override)", "accept the base setter's parameter type or a wider type; narrow it inside the setter")
					}
				}
			}
			if ownGet && (!l.classAssignable(own, previous) || l.widened(own, previous, map[[2]*checker.Type]bool{}) != nil) {
				return refuse("an accessor override with an unsafe read or write type (adamic/invariant-mutable)", "keep the inherited accessor type; narrow values inside the accessor")
			}
		}
		if member.Kind == ast.KindPropertyDeclaration || parameterProperty(member) {
			if !l.checker.IsReadonlySymbol(inherited) && (!l.classAssignable(previous, own) || !l.classAssignable(own, previous) || l.widened(previous, own, map[[2]*checker.Type]bool{}) != nil || l.widened(own, previous, map[[2]*checker.Type]bool{}) != nil) {
				return refuse("a mutable inherited field redeclared with a different type (adamic/invariant-mutable)", "keep the base field's type; narrow a local after reading it, or make the field readonly in the base")
			}
			if l.checker.IsReadonlySymbol(inherited) && (l.widened(own, previous, map[[2]*checker.Type]bool{}) != nil || !l.classAssignable(own, previous)) {
				return refuse("an inherited readonly field whose mutable contents are narrowed (adamic/invariant-mutable)", "keep mutable contents at the base type, or make the contents readonly in the base too")
			}
			if l.checker.IsReadonlySymbol(inherited) && !ast.HasSyntacticModifier(member, ast.ModifierFlagsReadonly) {
				return refuse("a readonly inherited field redeclared mutable", "keep the inherited field readonly")
			}
			from, okFrom := l.representation(previous)
			to, okTo := l.representation(own)
			if checkABI && (!okFrom || !okTo || from != to) {
				return l.notYet(member, "an inherited field override with a different native representation")
			}
		}
		if member.Kind != ast.KindMethodDeclaration {
			continue
		}
		oldSignatures := l.checker.GetSignaturesOfType(previous, checker.SignatureKindCall)
		newSignatures := l.checker.GetSignaturesOfType(own, checker.SignatureKindCall)
		if len(oldSignatures) != 1 || len(newSignatures) != 1 {
			return l.notYet(member, "an overloaded override")
		}
		old, next := oldSignatures[0], newSignatures[0]
		if len(old.Parameters()) != len(next.Parameters()) {
			return l.notYet(member, "an override with a different parameter count; keep the base method's parameter count")
		}
		for index, parameter := range old.Parameters() {
			accepts := l.checker.GetTypeOfSymbol(parameter)
			override := l.checker.GetTypeOfSymbol(next.Parameters()[index])
			a, knownA := l.overrideParameterRepresentation(parameter)
			b, knownB := l.overrideParameterRepresentation(next.Parameters()[index])
			if checkABI && (!knownA || !knownB || a != b) {
				return l.notYet(member, "an override with a different native representation for parameter "+strconv.Quote(next.Parameters()[index].Name)+"; keep the base method's parameter form")
			}
			if !l.classAssignable(accepts, override) || l.widened(accepts, override, map[[2]*checker.Type]bool{}) != nil {
				return refuse("an override that narrows a method parameter (adamic/contravariant-override)", "accept the base method's parameter type or a wider type; narrow it inside the method")
			}
		}
		oldResult := l.checker.GetReturnTypeOfSignature(old)
		newResult := l.checker.GetReturnTypeOfSignature(next)
		a, knownA := l.overrideResultRepresentation(oldResult)
		b, knownB := l.overrideResultRepresentation(newResult)
		if checkABI && (!knownA || !knownB || a != b) {
			return l.notYet(member, "an override with a different native result representation; keep the base method's result form")
		}
		if !l.classAssignable(newResult, oldResult) || l.widened(newResult, oldResult, map[[2]*checker.Type]bool{}) != nil {
			return refuse("an override that widens its return type", "return the base method's result type or a subtype")
		}
	}
	return nil
}

// Match signature lowering, including the incoming optional form of a defaulted parameter.
// The signature's symbol carries the instantiated type; its declaration carries the default.
func (l *lowering) overrideParameterRepresentation(parameter *ast.Symbol) (ir.Type, bool) {
	if len(parameter.Declarations) != 1 || parameter.Declarations[0].Kind != ast.KindParameter {
		return 0, false
	}
	declaration := parameter.Declarations[0]
	declared := declaration.AsParameterDeclaration()
	if declared.DotDotDotToken != nil {
		return 0, false
	}
	name := declaration.Name()
	if name.Kind == ast.KindArrayBindingPattern || name.Kind == ast.KindObjectBindingPattern {
		return ir.Object, declared.Initializer == nil && declared.QuestionToken == nil
	}
	representation, known := l.representation(l.checker.GetTypeOfSymbol(parameter))
	if declared.Initializer != nil || declared.QuestionToken != nil {
		representation = ir.Maybe(representation)
	}
	return representation, known
}

// Named methods returning void or never have no C result, as signature lowering does.
func (l *lowering) overrideResultRepresentation(result *checker.Type) (ir.Type, bool) {
	if result.Flags()&(checker.TypeFlagsVoid|checker.TypeFlagsNever) != 0 {
		return 0, true
	}
	return l.representation(result)
}

// Constructors initialize an already allocated object. A separate allocator fixes its dynamic
// identity before even the base constructor runs, so base method calls can dispatch dynamically.
func (l *lowering) inheritanceConstructor(index int, declaration *ast.Node) error {
	instance := l.instance
	var constructor *ast.Node
	for _, member := range declaration.Members() {
		if member.Kind == ast.KindConstructor {
			constructor = member
		}
	}
	instance.initializer = len(l.result.Functions)
	initializer := instance.initializer
	l.result.Functions = append(l.result.Functions, ir.Function{Name: l.result.Functions[index].Name + "_initialize"})
	this := l.thisLocal(initializer)
	outerThis, outerIndex, outerFunction := l.this, l.functionIndex, l.function
	context := l.result.Functions[initializer]
	l.this, l.functionIndex, l.function = this, initializer, &context
	defer func() { l.this, l.functionIndex, l.function = outerThis, outerIndex, outerFunction }()
	if constructor != nil {
		if err := l.signature(initializer, constructor, this); err != nil {
			return err
		}
		l.result.Functions[initializer].Parameters = append([]int{this}, l.result.Functions[initializer].Parameters...)
	} else {
		l.result.Functions[initializer].Parameters = []int{this}
		if instance.base != nil {
			for _, parameter := range l.result.Functions[instance.base.initializer].Parameters[1:] {
				local := len(l.result.Locals)
				incoming := l.result.Locals[parameter]
				incoming.Function, incoming.Captured, incoming.Borrowed = initializer, false, false
				l.result.Locals = append(l.result.Locals, incoming)
				l.result.Functions[initializer].Parameters = append(l.result.Functions[initializer].Parameters, local)
			}
		}
	}
	l.result.Functions[initializer].Receiver = true
	if constructor == nil && instance.base != nil {
		l.result.Functions[initializer].RestElement = l.result.Functions[instance.base.initializer].RestElement
		l.result.Functions[initializer].ForwardsArguments = instance.base.initializer + 1
	}
	// The layout contains inherited fields first, but only this class's initializers run here.
	fields := append([]ir.Field{}, l.result.Classes[instance.class-1].Fields...)
	for _, member := range classMembersWithParameters(declaration) {
		if member.Kind != ast.KindPropertyDeclaration && !parameterProperty(member) {
			continue
		}
		if ast.HasSyntacticModifier(member, ast.ModifierFlagsAmbient|ast.ModifierFlagsAbstract) {
			return l.notYet(member, "a declare or abstract class field")
		}
		if ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			continue
		}
		if !ast.IsIdentifier(member.Name()) && member.Name().Kind != ast.KindPrivateIdentifier {
			return l.notYet(member, "a field with a computed name")
		}
		of, err := l.typeOf(member.Name())
		if err != nil {
			return err
		}
		if slotless(of) {
			return l.notYet(member, "a field of type "+l.checker.TypeToString(l.checker.GetTypeAtLocation(member.Name())))
		}
		field := ir.Field{Name: l.fieldName(member.Name()), Value: zeroValue(of), Private: member.Name().Kind == ast.KindPrivateIdentifier, Uninitialized: l.uninitializedDeclaration(member) || (member.Kind == ast.KindPropertyDeclaration && l.lazyAssertionInitializer(member.AsPropertyDeclaration().Initializer))}
		// An uninitialized reference still has its declared representation for the shape bitmap.
		if of.IsReference() {
			field.Value = ir.Undefined{Of: of}
		}
		found := false
		for i := range fields {
			if fields[i].Name == field.Name {
				fields[i] = field
				found = true
				break
			}
		}
		if !found {
			fields = append(fields, field)
		}
	}
	l.result.Classes[instance.class-1].Fields = fields
	if instance.base == nil {
		initialized, err := l.fieldInitializers(declaration, this)
		if err != nil {
			return err
		}
		l.result.Functions[initializer].Body = initialized
	}
	if constructor != nil {
		instance.constructing = true
		defer func() { instance.constructing = false }()
		var returnValue *ast.Node
		var returns ast.Visitor
		returns = func(node *ast.Node) bool {
			if ast.IsFunctionLike(node) {
				return false
			}
			if node.Kind == ast.KindReturnStatement && node.AsReturnStatement().Expression != nil {
				returnValue = node
				return true
			}
			return node.ForEachChild(returns)
		}
		constructor.Body().ForEachChild(returns)
		if returnValue != nil {
			return l.notYet(returnValue, "a constructor returning a replacement value")
		}
		state := uint8(0)
		if instance.base != nil {
			var err error
			state, err = l.prepareSuper(constructor, initializer)
			if err != nil {
				return err
			}
		}

		outerUnset := l.unsetUntil
		l.unsetUntil = lastFieldAssignment(declaration, constructor)
		err := l.lowerFunction(initializer, constructor, this)
		l.unsetUntil = outerUnset
		if err != nil {
			return err
		}
		if state&superUninitialized != 0 {
			l.result.Functions[initializer].Body = append(l.result.Functions[initializer].Body, l.superEnd())
		}
	} else if instance.base != nil {
		arguments := []ir.Expression{}
		for _, parameter := range l.result.Functions[initializer].Parameters {
			arguments = append(arguments, ir.Read{Local: parameter, Of: l.result.Locals[parameter].Type})
		}
		l.result.Functions[initializer].Body = []ir.Statement{ir.Evaluate{Value: ir.Call{Function: instance.base.initializer, Arguments: arguments, ForwardCount: true, RestPacked: true}}}
		initialized, err := l.fieldInitializers(declaration, this)
		if err != nil {
			return err
		}
		l.result.Functions[initializer].Body = append(l.result.Functions[initializer].Body, initialized...)
	}
	if instance.base == nil && !instance.hasDescendants {
		// Keep creation and writes in one function when no derived constructor needs this
		// initializer. Freshness then knows this is new at each write, not just at return.
		body := l.result.Functions[initializer]
		for local := range l.result.Locals {
			if l.result.Locals[local].Function == initializer {
				l.result.Locals[local].Function = index
			}
		}
		wrapper := l.result.Functions[index]
		wrapper.Parameters = append([]int{}, body.Parameters[1:]...)
		wrapper.ArgumentsCount = body.ArgumentsCount
		wrapper.ForwardsArguments = body.ForwardsArguments
		wrapper.RestElement = body.RestElement
		wrapper.Body = append([]ir.Statement{ir.Declare{Local: this, Value: ir.ObjectLiteral{Fields: fields, Class: instance.class, Methods: instance.methodList()}}}, body.Body...)
		wrapper.Body = append(wrapper.Body, ir.Return{Value: ir.Read{Local: this, Of: ir.Object}})
		l.result.Functions[index] = wrapper
		l.result.Functions[initializer] = ir.Function{Name: body.Name}
		return nil
	}
	// The public constructor owns its object, including when an initializer throws.
	wrapper := l.result.Functions[index]
	wrapper.ForwardsArguments = initializer + 1
	wrapper.RestElement = l.result.Functions[initializer].RestElement
	arguments := []ir.Expression{}
	object := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "this", Type: ir.Object, Function: index})
	l.noteLocal(object, l.classType, declaration.Name())
	arguments = append(arguments, ir.Read{Local: object, Of: ir.Object})
	for _, parameter := range l.result.Functions[initializer].Parameters[1:] {
		incoming := l.result.Locals[parameter]
		incoming.Function, incoming.Captured, incoming.Borrowed = index, false, false
		local := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, incoming)
		wrapper.Parameters = append(wrapper.Parameters, local)
		arguments = append(arguments, ir.Read{Local: local, Of: incoming.Type})
	}
	wrapper.Body = []ir.Statement{
		ir.Declare{Local: object, Value: ir.ObjectLiteral{Fields: fields, Class: instance.class, Methods: instance.methodList()}},
		ir.Evaluate{Value: ir.Call{Function: initializer, Arguments: arguments, ForwardCount: true, RestPacked: true}},
		ir.Return{Value: ir.Read{Local: object, Of: ir.Object}},
	}
	l.result.Functions[index] = wrapper
	return nil
}

func (l *lowering) fieldInitializers(declaration *ast.Node, this int) ([]ir.Statement, error) {
	statements := []ir.Statement{}
	available := map[string]bool{}
	if l.instance.base != nil {
		for _, field := range l.result.Classes[l.instance.base.class-1].Fields {
			available[field.Name] = true
		}
	}
	resets, err := l.parameterPropertyResets(declaration, this, available)
	if err != nil {
		return nil, err
	}
	statements = append(statements, resets...)
	for _, member := range declaration.Members() {
		if member.Kind != ast.KindPropertyDeclaration || ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			continue
		}
		of, err := l.typeOf(member.Name())
		if err != nil {
			return nil, err
		}
		if l.uninitializedDeclaration(member) {
			value := zeroValue(of)
			if of.IsReference() {
				value = ir.Undefined{Of: of}
			}
			statements = append(statements, ir.SetProperty{Object: ir.Read{Local: this, Of: ir.Object}, Name: l.fieldName(member.Name()), Value: value, Uninitialized: true, Site: l.writeSite(declaration.Name())})
			available[l.fieldName(member.Name())] = true
			continue
		}

		if initializer := member.AsPropertyDeclaration().Initializer; l.lazyAssertionInitializer(initializer) {
			if err := l.initializerReads(initializer, available); err != nil {
				return nil, err
			}
			prefix, present, value, err := l.lazyAssertion(initializer, of)
			if err != nil {
				return nil, err
			}
			empty := ir.Expression(zeroValue(of))
			if of.IsReference() {
				empty = ir.Undefined{Of: of}
			}
			statements = append(statements, prefix...)
			statements = append(statements, ir.SetProperty{Object: ir.Read{Local: this, Of: ir.Object}, Name: l.fieldName(member.Name()), Value: empty, Uninitialized: true, Site: l.writeSite(declaration.Name())}, ir.If{Condition: present, Then: []ir.Statement{ir.SetProperty{Object: ir.Read{Local: this, Of: ir.Object}, Name: l.fieldName(member.Name()), Value: value, Site: l.writeSite(declaration.Name())}}})
			available[l.fieldName(member.Name())] = true
			continue
		}
		value := zeroValue(of)
		if member.AsPropertyDeclaration().Initializer != nil {
			if err := l.initializerReads(member.AsPropertyDeclaration().Initializer, available); err != nil {
				return nil, err
			}
			value, err = l.expression(member.AsPropertyDeclaration().Initializer)
			if err != nil {
				return nil, err
			}
			value = fit(value, of)
		} else if of.IsReference() {
			value = ir.Undefined{Of: of}
		}
		statements = append(statements, ir.SetProperty{Object: ir.Read{Local: this, Of: ir.Object}, Name: l.fieldName(member.Name()), Value: value, Site: l.writeSite(declaration.Name())})
		available[l.fieldName(member.Name())] = true
	}
	return statements, nil
}

func (l *lowering) superCall(node *ast.Node) (ir.Expression, error) {
	if l.instance == nil || l.instance.base == nil || l.this < 0 {
		return nil, l.notYet(node, "super outside a derived constructor")
	}
	arguments := []ir.Expression{ir.Read{Local: l.this, Of: ir.Object}}
	for _, argument := range nodesOf(node.AsCallExpression().Arguments) {
		value, err := l.expression(argument)
		if err != nil {
			return nil, err
		}
		arguments = append(arguments, value)
	}
	return ir.Call{Function: l.instance.base.initializer, Arguments: arguments}, nil
}

func (l *lowering) superStatement(node *ast.Node) ([]ir.Statement, error) {
	call, err := l.superCall(node)
	if err != nil {
		return nil, err
	}
	statements := []ir.Statement{}
	if l.instance.superStates[node]&superInitialized != 0 {
		// JavaScript constructs another base object before rejecting a second binding.
		// Do not overwrite the already initialized object's fields on this path.
		base := call.(ir.Call)
		second := ir.Call{Function: l.instance.base.constructor, Arguments: base.Arguments[1:], Returns: ir.Object}
		statements = append(statements, ir.If{Condition: ir.Read{Local: l.instance.superReady, Of: ir.Boolean}, Then: []ir.Statement{ir.Evaluate{Value: second}, l.superError("Super constructor may only be called once")}})
	}
	statements = append(statements, ir.Evaluate{Value: call}, ir.Assign{Local: l.instance.superReady, Value: ir.BooleanConstant{Value: true}})
	// Fields run only once super has returned, and before the next derived-body statement.
	declaration := l.classNode.Parent
	initialized, err := l.fieldInitializers(declaration, l.this)
	if err != nil {
		return nil, err
	}
	statements = append(statements, initialized...)
	assigned, err := l.parameterPropertyStores(declaration, l.this)
	return append(statements, assigned...), err
}

func (l *lowering) classInstanceOf(node *ast.Node) (ir.Expression, error) {
	binary := node.AsBinaryExpression()
	declaration := l.classes[l.symbol(ast.SkipParentheses(binary.Right))]
	if declaration == nil {
		return nil, l.notYet(node, "instanceof against a value that isn't a declared class")
	}
	identity := 0
	if len(declaration.TypeParameters()) > 0 {
		// JavaScript erases type arguments for instanceof, even when native layouts differ.
		identity = l.classIdentity(declaration)
	} else {
		instance, err := l.instantiate(declaration, l.checker.GetTypeAtLocation(declaration.Name()), node)
		if err != nil {
			return nil, err
		}
		identity = instance.class
	}
	value, err := l.expression(binary.Left)
	if err != nil {
		return nil, err
	}
	return ir.InstanceOf{Value: value, Class: identity}, nil
}

// Finish calls after lowering discovers every instantiated descendant. The analyses see all
// implementations; code generation still uses the receiver's single dynamic method table.
func (l *lowering) finishClassCalls() {
	l.result.MethodTargets = map[int][]int{}
	for _, class := range l.result.Classes {
		for slot, implementation := range class.Methods {
			for parent := &class; parent != nil; {
				if slot < len(parent.Methods) {
					function := parent.Methods[slot]
					if !slices.Contains(l.result.MethodTargets[function], implementation) {
						l.result.MethodTargets[function] = append(l.result.MethodTargets[function], implementation)
					}
				}
				if parent.Base == 0 {
					break
				}
				parent = &l.result.Classes[parent.Base-1]
			}
		}
	}
}

func (l *lowering) noteInheritance(modules []*ast.SourceFile) {
	l.derivedAncestors = map[*ast.Symbol]bool{}
	for _, module := range modules {
		var visit ast.Visitor
		visit = func(node *ast.Node) bool {
			if node.Kind == ast.KindClassDeclaration && node.Name() != nil {
				typ := l.checker.GetTypeAtLocation(node.Name())
				for _, base := range l.checker.GetBaseTypes(typ) {
					l.derivedAncestors[base.Symbol()] = true
				}
			}
			return node.ForEachChild(visit)
		}
		module.AsNode().ForEachChild(visit)
	}
}

// A class view needs nominal ancestry, even when TypeScript's structural relation accepts two
// unrelated classes or a plain object. Otherwise a virtual call would trust a table that isn't there.
func (l *lowering) classViewRefusal(node *ast.Node) error {
	if !viewSite(node) || node.Kind == ast.KindParenthesizedExpression {
		return nil
	}
	if parent := node.Parent; parent != nil && parent.Kind == ast.KindVariableDeclaration && parent.Name().Kind == ast.KindArrayBindingPattern {
		return l.classDestructuredView(node, parent.Name())
	}
	target := l.checker.GetContextualType(node, checker.ContextFlagsNone)
	if target == nil {
		return nil
	}
	// Fresh literals are built as their contextual type; their explicit values are
	// checked at their own sites. Spreads still need the whole inherited shape checked.
	if node.Kind == ast.KindObjectLiteralExpression || node.Kind == ast.KindArrayLiteralExpression {
		spread := false
		for _, child := range literalParts(node) {
			if child.Kind == ast.KindSpreadAssignment || child.Kind == ast.KindSpreadElement {
				spread = true
			}
		}
		if !spread && !l.nominalLiteralTarget(target) {
			return nil
		}
	}
	source := l.checker.GetTypeAtLocation(node)
	mismatch := l.nominalMismatch(source, target, map[[2]*checker.Type]bool{})
	if mismatch == nil {
		return nil
	}
	target = mismatch
	return &Refused{Where: l.program.Where(node), What: "a value without nominal ancestry seen as " + l.checker.TypeToString(target), Fix: "construct that class or a subclass; use an interface for structural values (adamic/nominal-class)"}
}

func (l *lowering) nominalAncestor(source, target *checker.Type, seen map[[2]*checker.Type]bool) bool {
	if source.Flags()&checker.TypeFlagsTypeParameter != 0 {
		if constraint := l.checker.GetBaseConstraintOfType(source); constraint != nil {
			source = constraint
		}
	}
	if weak := l.weakTarget(source); weak != nil {
		source = weak
	}
	if !isClassInstance(source) {
		return false
	}
	if source.Symbol() == target.Symbol() {
		from, to := l.checker.GetTypeArguments(source), l.checker.GetTypeArguments(target)
		if !l.sameClassArguments(from, to) {
			return false
		}
		for index := range from {
			if !l.enumAssignable(from[index], to[index]) || !l.enumAssignable(to[index], from[index]) || l.nominalMismatch(from[index], to[index], seen) != nil || l.nominalMismatch(to[index], from[index], seen) != nil {
				return false
			}
		}
		return true
	}
	for _, base := range l.classBases(source) {
		if l.nominalAncestor(base, target, seen) {
			return true
		}
	}
	return false
}

// Initializers may read fields already initialized, including the base's after super. A future
// field would hold undefined despite its declared type; a method may read future derived fields.
func (l *lowering) initializerReads(node *ast.Node, available map[string]bool) error {
	seen := map[*ast.Node]bool{}
	var examine func(*ast.Node, []string) error
	examine = func(body *ast.Node, path []string) error {
		if body == nil || seen[body] {
			return nil
		}
		seen[body] = true
		var refused error
		var visit ast.Visitor
		visit = func(child *ast.Node) bool {
			if refused != nil {
				return true
			}
			if ast.IsPartOfTypeNode(child) {
				return false
			}
			if child.Kind == ast.KindPropertyAccessExpression {
				object := ast.SkipParentheses(child.AsPropertyAccessExpression().Expression)
				if object.Kind == ast.KindThisKeyword || object.Kind == ast.KindSuperKeyword {
					symbol := l.checker.GetSymbolAtLocation(child.Name())
					if object.Kind == ast.KindThisKeyword && child.Name().Kind != ast.KindPrivateIdentifier {
						symbol = l.checker.GetPropertyOfType(l.classType, child.Name().Text())
					}
					if symbol != nil {
						for _, member := range symbol.Declarations {
							step := child.Name().Text()
							if member.Parent != nil && member.Parent.Name() != nil {
								step = member.Parent.Name().Text() + "." + step
							}
							next := append(append([]string{}, path...), step)
							if member.Kind == ast.KindMethodDeclaration || member.Kind == ast.KindGetAccessor {
								refused = examine(member.Body(), next)
							} else if (member.Kind == ast.KindPropertyDeclaration || parameterProperty(member)) && !available[l.fieldName(child.Name())] {
								refused = &Refused{Where: l.program.Where(child), What: "a field initializer reading an uninitialized field through " + strings.Join(next, " -> "), Fix: "declare the field it reads earlier, or initialize it in the constructor after super and all required fields are set"}
							}
							if refused != nil {
								return true
							}
						}
						return false
					}
				}
			}
			if child.Kind == ast.KindThisKeyword || child.Kind == ast.KindSuperKeyword {
				refused = &Refused{Where: l.program.Where(child), What: "this in a field initializer before the fields it reads are initialized", Fix: "declare the field it reads earlier, or initialize it in the constructor after super and all required fields are set"}
				return true
			}
			return child.ForEachChild(visit)
		}
		visit(body)
		return refused
	}
	return examine(node, nil)
}

// Private names with the same spelling in a base and a derived class are separate JavaScript slots,
// so each is qualified by the class that declares it (privateName), the same spelling memberKey gives
// its definition, for fields, methods, accessors and statics alike.
func (l *lowering) fieldName(name *ast.Node) string {
	if name.Kind != ast.KindPrivateIdentifier {
		return name.Text()
	}
	if declaring := l.declaringClass(name); declaring != nil {
		return l.privateName(name.Text(), declaring)
	}
	return name.Text()
}

// Assignment to a nominal class also requires ancestry; structural compatibility alone cannot
// provide the dynamic table an override's caller expects.
func (l *lowering) classAssignable(from, to *checker.Type) bool {
	return l.checker.IsTypeAssignableTo(from, to) && l.nominalMismatch(from, to, map[[2]*checker.Type]bool{}) == nil
}

// Follow nominal class slots inside structural containers too. A plain object inside A[] lacks
// the same method table as a plain object assigned directly to A. Mutable slots need both views.
func (l *lowering) nominalMismatch(from, to *checker.Type, seen map[[2]*checker.Type]bool) *checker.Type {
	if from == nil || to == nil || from == to || from.Flags()&(checker.TypeFlagsNever|checker.TypeFlagsUndefined) != 0 || seen[[2]*checker.Type{from, to}] {
		return nil
	}
	seen[[2]*checker.Type{from, to}] = true
	if from.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range from.Types() {
			if found := l.nominalMismatch(member, to, seen); found != nil {
				return found
			}
		}
		return nil
	}
	if to.Flags()&checker.TypeFlagsUnion != 0 {
		var failure *checker.Type
		for _, member := range to.Types() {
			if !l.checker.IsTypeAssignableTo(from, member) {
				continue
			}
			if found := l.nominalMismatch(from, member, seen); found != nil {
				failure = found
			} else {
				return nil
			}
		}
		return failure
	}
	if weak := l.weakTarget(from); weak != nil {
		from = weak
	}
	if weak := l.weakTarget(to); weak != nil {
		to = weak
	}
	if from.Flags()&checker.TypeFlagsTypeParameter != 0 {
		if constraint := l.checker.GetBaseConstraintOfType(from); constraint != nil {
			return l.nominalMismatch(constraint, to, seen)
		}
		return nil
	}
	if l.isStaticType(to) {
		wanted := l.staticClass(to, nil)
		actual := l.staticClass(from, nil)
		for actual != nil {
			if actual == wanted {
				return nil
			}
			actual = l.staticBase(actual)
		}
		return to
	}
	if isClassInstance(to) {
		if symbol := to.Symbol(); symbol != nil && len(symbol.Declarations) > 0 && load.IsPrelude(ast.GetSourceFileOfNode(symbol.Declarations[0])) {
			return nil
		}
		if !l.nominalAncestor(from, to, seen) {
			return to
		}
		return nil
	}
	if !l.structured(from) || !l.structured(to) {
		return nil
	}
	fromSignatures := l.checker.GetSignaturesOfType(from, checker.SignatureKindCall)
	toSignatures := l.checker.GetSignaturesOfType(to, checker.SignatureKindCall)
	if len(fromSignatures) > 0 && len(toSignatures) > 0 {
		parameters := toSignatures[0].Parameters()
		if l.censusNeverRestSignature(toSignatures[0]) {
			parameters = nil
		}
		for index, parameter := range parameters {
			if index >= len(fromSignatures[0].Parameters()) {
				break
			}
			if found := l.nominalMismatch(l.checker.GetTypeOfSymbol(parameter), l.checker.GetTypeOfSymbol(fromSignatures[0].Parameters()[index]), seen); found != nil {
				return found
			}
		}
		return l.nominalMismatch(l.checker.GetReturnTypeOfSignature(fromSignatures[0]), l.checker.GetReturnTypeOfSignature(toSignatures[0]), seen)
	}
	for _, target := range l.containers(to) {
		for _, source := range l.containers(from) {
			if !l.sameContainer(source, target) {
				continue
			}
			fromArguments, toArguments := l.checker.GetTypeArguments(source), l.checker.GetTypeArguments(target)
			mutable := !l.isLibraryType(target, "ReadonlyArray", "ReadonlyMap", "ReadonlySet") && !(checker.IsTupleType(target) && target.TargetTupleType().IsReadonly())
			for index := 0; index < len(fromArguments) && index < len(toArguments); index++ {
				if found := l.nominalMismatch(fromArguments[index], toArguments[index], seen); found != nil {
					return found
				}
				if mutable {
					if found := l.nominalMismatch(toArguments[index], fromArguments[index], seen); found != nil {
						return found
					}
				}
			}
		}
	}
	if len(l.containers(to)) > 0 {
		return nil
	}
	for _, property := range l.checker.GetPropertiesOfType(to) {
		if property.Flags&ast.SymbolFlagsMethod != 0 {
			continue
		}
		inside := l.checker.GetPropertyOfType(from, property.Name)
		if inside == nil {
			continue
		}
		source, target := l.checker.GetTypeOfSymbol(inside), l.checker.GetTypeOfSymbol(property)
		if found := l.nominalMismatch(source, target, seen); found != nil {
			return found
		}
		if !l.checker.IsReadonlySymbol(property) {
			if found := l.nominalMismatch(target, source, seen); found != nil {
				return found
			}
		}
	}
	return nil
}

// An inferred destructuring context can be the union of the tuple's elements. Compare the
// positional values with their bound names instead of treating that union as a writable array.
func (l *lowering) classDestructuredView(node, pattern *ast.Node) error {
	own := l.checker.GetTypeAtLocation(node)
	elements := l.checker.GetTypeArguments(own)
	tuple := checker.IsTupleType(own)
	for index, binding := range pattern.AsBindingPattern().Elements.Nodes {
		if binding.Kind == ast.KindOmittedExpression || binding.Name() == nil {
			continue
		}
		if !tuple {
			index = 0
		}
		if index >= len(elements) {
			continue
		}
		target := l.checker.GetTypeAtLocation(binding.Name())
		if mismatch := l.nominalMismatch(elements[index], target, map[[2]*checker.Type]bool{}); mismatch != nil {
			return &Refused{Where: l.program.Where(binding), What: "a destructured value without nominal ancestry seen as " + l.checker.TypeToString(mismatch), Fix: "construct that class or a subclass; use an interface for structural values (adamic/nominal-class)"}
		}
	}
	return nil
}

// The checker mangles private symbol names; the IR qualifies them by class ID. Cycle proofs
// must match the same declaration in both names, including inherited and generic private slots.
func (l *lowering) cycleFieldMatches(holder *checker.Type, field, written string) bool {
	if field == written {
		return true
	}
	property := l.checker.GetPropertyOfType(holder, field)
	if property == nil || len(property.Declarations) != 1 {
		return false
	}
	name := property.Declarations[0].Name()
	if name == nil || name.Kind != ast.KindPrivateIdentifier {
		return false
	}
	if class := property.Declarations[0].Parent; class != nil && class.Kind == ast.KindClassDeclaration {
		return written == l.privateName(name.Text(), class)
	}
	return written == name.Text()
}

func (l *lowering) cycleFieldName(field *ast.Symbol) string {
	if len(field.Declarations) == 1 {
		if name := field.Declarations[0].Name(); name != nil && name.Kind == ast.KindPrivateIdentifier {
			return name.Text()
		}
	}
	return field.Name
}

// All monomorphizations of a source class have one erased identity. An identity-only
// descriptor lets instanceof name a generic class before any concrete instance is made.
func (l *lowering) classDefinition(declaration *ast.Node) int {
	for key, instance := range l.instances {
		if l.classKeyMatches(key, declaration) {
			return l.result.Classes[instance.class-1].Definition
		}
	}
	return len(l.result.Classes) + 1
}

func (l *lowering) classIdentity(declaration *ast.Node) int {
	definition := l.classDefinition(declaration)
	for index, class := range l.result.Classes {
		if class.Definition == definition {
			return index + 1
		}
	}
	identity := len(l.result.Classes) + 1
	l.result.Classes = append(l.result.Classes, ir.Class{Name: declaration.Name().Text() + "_identity", Definition: definition, Constructor: -1})
	if l.instances == nil {
		l.instances = map[string]*instance{}
	}
	key := l.classKeyPrefix(declaration) + ",identity"
	l.instances[key] = &instance{class: identity, constructor: -1, initializer: -1}
	return identity
}

// An inherited method's receiver can be a descendant with different type arguments.
// Find the declaration's actual instantiated view instead of substituting by position.
func (l *lowering) classView(proven *checker.Type, declaration *ast.Node) *checker.Type {
	if proven.Flags()&checker.TypeFlagsTypeParameter != 0 {
		if constraint := l.checker.GetBaseConstraintOfType(proven); constraint != nil {
			proven = constraint
		}
	}
	if weak := l.weakTarget(proven); weak != nil {
		proven = weak
	}
	if proven.Symbol() == l.symbol(declaration.Name()) {
		return proven
	}
	for _, base := range l.classBases(proven) {
		if found := l.classView(base, declaration); found != nil {
			return found
		}
	}
	return nil
}

// The checker exposes generic bases on the declaration. Substitute the receiver's
// actual arguments before choosing a native base layout or proving nominal ancestry.
func (l *lowering) classBases(proven *checker.Type) []*checker.Type {
	target := proven
	if proven.ObjectFlags()&checker.ObjectFlagsReference != 0 && proven.Target() != nil {
		target = proven.Target()
	}
	bases := l.checker.GetBaseTypes(target)
	declaration := l.classNodeFor(proven)
	if declaration == nil || declaration.Kind != ast.KindClassDeclaration {
		return bases
	}
	mapper := l.typeMapperOf(declaration, proven)
	if mapper == nil {
		return bases
	}
	concrete := make([]*checker.Type, len(bases))
	for index, base := range bases {
		concrete[index] = instantiateType(l.checker, base, mapper)
	}
	return concrete
}

func literalParts(node *ast.Node) []*ast.Node {
	if node.Kind == ast.KindObjectLiteralExpression {
		return node.AsObjectLiteralExpression().Properties.Nodes
	}
	return node.AsArrayLiteralExpression().Elements.Nodes
}

func (l *lowering) nominalLiteralTarget(proven *checker.Type) bool {
	if weak := l.weakTarget(proven); weak != nil {
		proven = weak
	}
	if isClassInstance(proven) {
		return true
	}
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range proven.Types() {
			if l.nominalLiteralTarget(member) {
				return true
			}
		}
	}
	return false
}

class_static.go:
package lower

import (
	"strconv"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
)

func (l *lowering) staticBase(declaration *ast.Node) *ast.Node {
	for _, clause := range nodesOf(declaration.AsClassDeclaration().HeritageClauses) {
		if clause.AsHeritageClause().Token != ast.KindExtendsKeyword {
			continue
		}
		for _, node := range clause.AsHeritageClause().Types.Nodes {
			symbol := l.symbol(ast.SkipParentheses(node.AsExpressionWithTypeArguments().Expression))
			if symbol != nil && len(symbol.Declarations) == 1 && symbol.Declarations[0].Kind == ast.KindClassDeclaration {
				return symbol.Declarations[0]
			}
		}
	}
	return nil
}
func (l *lowering) needsStatics(declaration *ast.Node) bool {
	// A class is in the temporal dead zone even when it has no static members.
	// Cyclic graphs and namespace classes need the same ready storage for
	// construction and extends, including classes without static members.
	if l.cyclicModules || declaration.Parent != nil && declaration.Parent.Kind == ast.KindModuleBlock {
		return true
	}
	for _, member := range declaration.Members() {
		if member.Kind == ast.KindClassStaticBlockDeclaration || ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			return true
		}
	}
	base := l.staticBase(declaration)
	return base != nil && l.needsStatics(base)
}
func (l *lowering) staticClass(proven *checker.Type, fallback *ast.Node) *ast.Node {
	symbol := proven.Symbol()
	if symbol != nil {
		for _, declaration := range symbol.Declarations {
			if declaration.Kind == ast.KindClassDeclaration {
				return declaration
			}
		}
	}
	return fallback
}

// Static layouts belong to source classes, independent of instance type arguments.
func (l *lowering) staticInstance(declaration *ast.Node) (*instance, error) {
	if err := l.staticClassDeclaration(declaration); err != nil {
		return nil, err
	}
	symbol := l.symbol(declaration.Name())
	if existing := l.statics[symbol]; existing != nil {
		return existing, nil
	}
	if l.statics == nil {
		l.statics = map[*ast.Symbol]*instance{}
	}
	if l.staticGlobals == nil {
		l.staticGlobals = map[*ast.Symbol]int{}
	}
	if _, exists := l.staticGlobals[symbol]; !exists {
		local, err := l.declareLocal(declaration.Name())
		if err != nil {
			return nil, err
		}
		l.result.Locals[local].Global = true
		l.staticStorage(declaration)
	}
	var base *instance
	if parent := l.staticBase(declaration); parent != nil {
		var err error
		base, err = l.staticInstance(parent)
		if err != nil {
			return nil, err
		}
	}
	if base != nil {
		if err := l.checkMemberOverrides(declaration, l.checker.GetTypeOfSymbol(symbol), l.checker.GetTypeOfSymbol(l.symbol(l.staticBase(declaration).Name())), true); err != nil {
			return nil, err
		}
	}
	lowered := &instance{static: true, constructor: -1, initializer: -1, superReady: -1, class: len(l.result.Classes) + 1, base: base, methods: map[string]int{}, slots: map[string]int{}}
	metadata := ir.Class{Name: declaration.Name().Text() + "_static", Constructor: -1, Static: true}
	if base != nil {
		parent := l.result.Classes[base.class-1]
		metadata.Base = base.class
		metadata.Fields = append(metadata.Fields, parent.Fields...)
		metadata.Methods = append(metadata.Methods, parent.Methods...)
		metadata.StaticFlags = append(metadata.StaticFlags, parent.StaticFlags...)
		for name, function := range base.methods {
			lowered.methods[name] = function
		}
		for name, slot := range base.slots {
			lowered.slots[name] = slot
		}
	}
	metadata.OwnStart = len(metadata.Fields)
	if base != nil {
		metadata.Fields = append(metadata.Fields, ir.Field{Name: "#static-parent:" + strconv.Itoa(lowered.class), Value: ir.Undefined{Of: ir.Object}, Private: true})
		metadata.StaticFlags = append(metadata.StaticFlags, 0)
		metadata.StaticParent = len(metadata.Fields)
	}
	for _, member := range declaration.Members() {
		if !ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			continue
		}
		if member.Name() == nil || (!ast.IsIdentifier(member.Name()) && member.Name().Kind != ast.KindPrivateIdentifier) {
			return nil, l.notYet(member, "a static member without an identifier name")
		}
		if member.Kind == ast.KindPropertyDeclaration {
			if ast.HasSyntacticModifier(member, ast.ModifierFlagsAmbient|ast.ModifierFlagsAbstract) {
				return nil, l.notYet(member, "a declare or abstract static field")
			}
			of, err := l.typeOf(member.Name())
			if err != nil {
				return nil, err
			}
			if slotless(of) {
				return nil, l.notYet(member, "a static field without a native slot")
			}
			if member.AsPropertyDeclaration().Initializer == nil && !l.uninitializedDeclaration(member) && !l.includesUndefined(l.checker.GetTypeAtLocation(member.Name())) {
				return nil, l.notYet(member, "an uninitialized nonnullable static field; initialize it at its declaration")
			}
			value := zeroValue(of)
			if of.IsReference() {
				value = ir.Undefined{Of: of}
			}
			field := ir.Field{Name: l.memberKey(member.Name(), lowered.class), Value: value, Private: member.Name().Kind == ast.KindPrivateIdentifier, Uninitialized: l.uninitializedDeclaration(member) || l.lazyAssertionInitializer(member.AsPropertyDeclaration().Initializer)}
			slot := -1
			for i, previous := range metadata.Fields {
				if previous.Name == field.Name {
					slot = i
					if previous.Value.Type() != of {
						return nil, l.notYet(member, "a static field override with a different native representation")
					}
					break
				}
			}
			if slot < 0 {
				slot = len(metadata.Fields)
				metadata.Fields = append(metadata.Fields, field)
				metadata.StaticFlags = append(metadata.StaticFlags, 0)
				metadata.Fields = append(metadata.Fields, ir.Field{Name: "#static-present:" + field.Name, Value: ir.NumberConstant{}, Private: true})
				metadata.StaticFlags = append(metadata.StaticFlags, 0)
				if !field.Private {
					metadata.StaticFlags[slot] = len(metadata.Fields)
				}
			}
			if !field.Private {
				metadata.PublicFields = append(metadata.PublicFields, field)
			}
		}
	}
	l.result.Classes = append(l.result.Classes, metadata)
	l.statics[symbol] = lowered
	for _, member := range declaration.Members() {
		if !classFunction(member) || !ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			continue
		}
		key := l.methodKey(member, lowered.class)
		function := len(l.result.Functions)
		lowered.methods[key] = function
		meta := &l.result.Classes[lowered.class-1]
		slot, exists := lowered.slots[key]
		if !exists {
			slot = len(meta.Methods)
			lowered.slots[key] = slot
			meta.Methods = append(meta.Methods, -1)
		}
		meta.Methods[slot] = function
		if accessorMember(member) {
			l.registerAccessor(lowered.class, member, function)
		}
		l.result.Functions = append(l.result.Functions, ir.Function{Name: metadata.Name + "_" + key})
	}
	outerInstance, outerType, outerNode, outerLocals := l.instance, l.classType, l.classNode, l.locals
	outerSubstitution, outerMapper := l.substitution, l.typeMapper
	l.instance, l.classType, l.classNode = lowered, l.checker.GetTypeOfSymbol(symbol), declaration.Name()
	l.substitution, l.typeMapper = nil, nil
	l.locals = map[*ast.Symbol]int{}
	for name, local := range outerLocals {
		if l.result.Locals[local].Global {
			l.locals[name] = local
		}
	}
	defer func() {
		l.instance, l.classType, l.classNode, l.locals = outerInstance, outerType, outerNode, outerLocals
		l.substitution, l.typeMapper = outerSubstitution, outerMapper
	}()
	for _, member := range declaration.Members() {
		if !classFunction(member) || !ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			continue
		}
		function := lowered.methods[l.methodKey(member, lowered.class)]
		if err := l.signature(function, member, l.thisLocal(function)); err != nil {
			return nil, err
		}
		if err := l.validateAccessorSignature(member, function); err != nil {
			return nil, err
		}
	}
	for _, member := range declaration.Members() {
		if !classFunction(member) || !ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			continue
		}
		if err := l.lowerFunction(lowered.methods[l.methodKey(member, lowered.class)], member, -1); err != nil {
			return nil, err
		}
	}
	return lowered, nil
}

// Allocation installs methods and accessors before the ordered field and block initializers run.
// The named map uses this static side's implementations, including inherited ones, while
// the class's virtual slots still serve nominal calls. Both keep the actual receiver as this.
func (l *lowering) staticDeclaration(declaration *ast.Node) ([]ir.Statement, error) {
	if err := l.staticClassDeclaration(declaration); err != nil {
		return nil, err
	}
	if !l.needsStatics(declaration) && l.statics[l.symbol(declaration.Name())] == nil {
		return nil, nil
	}
	lowered, err := l.staticInstance(declaration)
	if err != nil {
		return nil, err
	}
	fields := append([]ir.Field{}, l.result.Classes[lowered.class-1].Fields...)
	if lowered.base != nil {
		parent := l.staticBase(declaration)
		slot := l.result.Classes[lowered.class-1].StaticParent - 1
		// Extends reads the public binding, whose name and ready point belong to
		// the source class, rather than the internal storage initialized earlier.
		checked := true
		for _, clause := range nodesOf(declaration.AsClassDeclaration().HeritageClauses) {
			if clause.AsHeritageClause().Token != ast.KindExtendsKeyword {
				continue
			}
			for _, element := range clause.AsHeritageClause().Types.Nodes {
				expression := ast.SkipParentheses(element.AsExpressionWithTypeArguments().Expression)
				if l.symbol(expression) == l.symbol(parent.Name()) {
					checked = !l.provenModuleReads[expression]
				}
			}
		}
		fields[slot].Value = ir.Read{Local: l.locals[l.symbol(parent.Name())], Of: ir.Object, Checked: checked}
	}
	object := ir.Read{Local: l.staticGlobals[l.symbol(declaration.Name())], Of: ir.Object}
	statements := []ir.Statement{ir.Declare{Local: object.Local, Value: ir.ObjectLiteral{Fields: fields, Class: lowered.class, Methods: lowered.methodList()}}}
	outerInstance, outerType, outerNode := l.instance, l.classType, l.classNode
	l.instance, l.classType, l.classNode = lowered, l.checker.GetTypeOfSymbol(l.symbol(declaration.Name())), declaration.Name()
	defer func() { l.instance, l.classType, l.classNode = outerInstance, outerType, outerNode }()
	available := map[string]bool{}
	if lowered.base != nil {
		for _, field := range l.result.Classes[lowered.base.class-1].Fields {
			available[field.Name] = true
		}
	}
	for _, member := range declaration.Members() {
		if member.Kind != ast.KindClassStaticBlockDeclaration && !(member.Kind == ast.KindPropertyDeclaration && ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic)) {
			continue
		}
		{
			var body *ast.Node
			if member.Kind == ast.KindClassStaticBlockDeclaration {
				body = member.AsClassStaticBlockDeclaration().Body
			} else {
				body = member.AsPropertyDeclaration().Initializer
			}
			if err := l.staticInitializationReads(body, declaration, available, map[*ast.Node]uint8{}, true); err != nil {
				return nil, err
			}
		}
		index := len(l.result.Functions)
		l.result.Functions = append(l.result.Functions, ir.Function{Name: declaration.Name().Text() + "_static_initialize"})
		self := l.thisLocal(index)
		l.result.Functions[index].Parameters = []int{self}
		outerThis, outerFunction, outerIndex, outerLocals := l.this, l.function, l.functionIndex, l.locals
		function := l.result.Functions[index]
		l.this, l.function, l.functionIndex = self, &function, index
		l.locals = map[*ast.Symbol]int{}
		for symbol, local := range outerLocals {
			if l.result.Locals[local].Global {
				l.locals[symbol] = local
			}
		}
		if member.Kind == ast.KindClassStaticBlockDeclaration {
			function.Body, err = l.statements(member.AsClassStaticBlockDeclaration().Body.AsBlock().Statements.Nodes)
		} else {
			of, _ := l.typeOf(member.Name())
			value := zeroValue(of)
			initializer := member.AsPropertyDeclaration().Initializer

			if l.lazyAssertionInitializer(initializer) && !l.uninitializedInitializer(initializer) {
				prefix, present, assigned, lazyErr := l.lazyAssertion(initializer, of)
				err = lazyErr
				if of.IsReference() {
					value = ir.Undefined{Of: of}
				}
				if err == nil {
					function.Body = append(prefix, ir.SetProperty{Object: ir.Read{Local: self, Of: ir.Object}, Name: l.memberKey(member.Name(), lowered.class), Value: value, Define: true, Uninitialized: true, Site: l.staticWriteSite(declaration.Name())}, ir.If{Condition: present, Then: []ir.Statement{ir.SetProperty{Object: ir.Read{Local: self, Of: ir.Object}, Name: l.memberKey(member.Name(), lowered.class), Value: assigned, Define: true, Site: l.staticWriteSite(declaration.Name())}}})
				}
			} else {
				if l.uninitializedDeclaration(member) {
					if of.IsReference() {
						value = ir.Undefined{Of: of}
					}
				} else if initializer != nil {
					value, err = l.expression(initializer)
					value = fit(value, of)
				} else if of.IsReference() {
					value = ir.Undefined{Of: of}
				}
				if err == nil {
					function.Body = []ir.Statement{ir.SetProperty{Object: ir.Read{Local: self, Of: ir.Object}, Name: l.memberKey(member.Name(), lowered.class), Value: value, Define: true, Uninitialized: l.uninitializedDeclaration(member), Site: l.staticWriteSite(declaration.Name())}}
				}
			}
			available[member.Name().Text()] = true
		}
		l.this, l.function, l.functionIndex, l.locals = outerThis, outerFunction, outerIndex, outerLocals
		if err != nil {
			return nil, err
		}
		l.result.Functions[index] = function
		statements = append(statements, ir.Evaluate{Value: ir.Call{Function: index, Arguments: []ir.Expression{object}}})
	}
	statements = append(statements, ir.Declare{Local: l.locals[l.symbol(declaration.Name())], Value: object})
	return statements, nil
}

func (l *lowering) isStaticType(proven *checker.Type) bool {
	return proven != nil && len(l.checker.GetSignaturesOfType(proven, checker.SignatureKindConstruct)) > 0 && l.staticClass(proven, nil) != nil
}
func (l *lowering) staticWriteSite(node *ast.Node) int {
	l.writeSites = append(l.writeSites, writeSite{holder: l.classType, node: node})
	return len(l.writeSites)
}

// JavaScript leaves future fields undefined. A nonnullable native slot cannot pretend that
// value is its declared type, including when an initializer calls a helper that reads it.
func (l *lowering) staticInitializationReads(node, declaration *ast.Node, available map[string]bool, seen map[*ast.Node]uint8, receiver bool) error {
	pending := false
	for _, member := range declaration.Members() {
		if member.Kind == ast.KindPropertyDeclaration && ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) && !available[member.Name().Text()] {
			pending = true
		}
	}
	state := uint8(1)
	if receiver {
		state = 2
	}
	if node == nil || seen[node]&state != 0 {
		return nil
	}
	seen[node] |= state
	var failure error
	var visit ast.Visitor
	visit = func(child *ast.Node) bool {
		if failure != nil {
			return true
		}
		if ast.IsPartOfTypeNode(child) {
			return false
		}
		if child.Kind == ast.KindPropertyAccessExpression {
			access := child.AsPropertyAccessExpression()
			object := ast.SkipParentheses(access.Expression)
			current := receiver && object.Kind == ast.KindThisKeyword
			if ast.IsIdentifier(object) {
				current = l.symbol(object) == l.symbol(declaration.Name())
			}
			if current {
				symbol := l.checker.GetSymbolAtLocation(child.Name())
				if symbol != nil && len(symbol.Declarations) > 0 {
					member := symbol.Declarations[0]
					if member.Kind == ast.KindPropertyDeclaration && !available[member.Name().Text()] {
						failure = &Refused{Where: l.program.Where(child), What: "a static field read before its initializer has run", Fix: "declare the field earlier, or move the read after that field's initialization"}
						return true
					}
					if accessorMember(member) {
						for _, candidate := range symbol.Declarations {
							if accessorMember(candidate) {
								failure = l.staticInitializationReads(candidate.Body(), declaration, available, seen, true)
								if failure != nil {
									break
								}
							}
						}
						if failure != nil {
							return true
						}
					}
				}
			}
		}
		if ast.IsIdentifier(child) && l.symbol(child) == l.symbol(declaration.Name()) && !ast.IsDeclarationName(child) {
			if !insideClass(child, declaration) {
				failure = &Refused{Where: l.program.Where(child), What: "an outside helper reading a class during its declaration (the temporal dead zone)", Fix: "run the helper after the class declaration, or read this inside a static method"}
				return true
			}
			parent := child.Parent
			if pending && (parent == nil || parent.Kind != ast.KindPropertyAccessExpression || parent.AsPropertyAccessExpression().Expression != child) {
				failure = &Refused{Where: l.program.Where(child), What: "a constructor object escaping before static fields are initialized", Fix: "publish the class value after the last static field initializer"}
				return true
			}
		}
		if child.Kind == ast.KindThisKeyword && receiver {
			parent := child.Parent
			if pending && (parent == nil || parent.Kind != ast.KindPropertyAccessExpression || parent.AsPropertyAccessExpression().Expression != child) {
				failure = &Refused{Where: l.program.Where(child), What: "a constructor object escaping before static fields are initialized", Fix: "publish this after the last static field initializer"}
				return true
			}
		}
		if child.Kind == ast.KindCallExpression {
			callee := ast.SkipParentheses(child.AsCallExpression().Expression)
			symbol := l.checker.GetSymbolAtLocation(callee)
			if ast.IsIdentifier(callee) {
				symbol = l.symbol(callee)
			}
			known := false
			if symbol != nil && len(symbol.Declarations) > 0 {
				target := symbol.Declarations[0]
				known = load.IsLibrary(ast.GetSourceFileOfNode(target)) || load.IsPrelude(ast.GetSourceFileOfNode(target))
				if target.Kind == ast.KindFunctionDeclaration {
					known = true
					failure = l.staticInitializationReads(target.Body(), declaration, available, seen, false)
				}
				if target.Kind == ast.KindMethodDeclaration && ast.HasSyntacticModifier(target, ast.ModifierFlagsStatic) {
					known = true
					current := false
					if callee.Kind == ast.KindPropertyAccessExpression {
						object := ast.SkipParentheses(callee.AsPropertyAccessExpression().Expression)
						current = (receiver && (object.Kind == ast.KindThisKeyword || object.Kind == ast.KindSuperKeyword)) || (ast.IsIdentifier(object) && l.symbol(object) == l.symbol(declaration.Name()))
					}
					failure = l.staticInitializationReads(target.Body(), declaration, available, seen, current)
				}
			}
			if known && symbol != nil && len(symbol.Declarations) > 0 && (load.IsLibrary(ast.GetSourceFileOfNode(symbol.Declarations[0])) || load.IsPrelude(ast.GetSourceFileOfNode(symbol.Declarations[0]))) {
				for _, argument := range nodesOf(child.AsCallExpression().Arguments) {
					if len(l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(argument), checker.SignatureKindCall)) == 0 {
						continue
					}
					if ast.IsFunctionLike(ast.SkipParentheses(argument)) {
						continue
					}
					target := l.symbol(ast.SkipParentheses(argument))
					if target != nil && len(target.Declarations) == 1 && target.Declarations[0].Kind == ast.KindFunctionDeclaration {
						failure = l.staticInitializationReads(target.Declarations[0].Body(), declaration, available, seen, false)
					} else {
						failure = l.notYet(argument, "an indirect callback before static fields are initialized; move it after the field initializers")
					}
					if failure != nil {
						break
					}
				}
			}
			if !known && failure == nil {
				failure = l.notYet(child, "an indirect call before static fields are initialized; move it after the field initializers")
			}
			if failure != nil {
				return true
			}
		}
		return child.ForEachChild(visit)
	}
	visit(node)
	return failure
}

// Constructor built-ins have function semantics, not ordinary class storage.
func (l *lowering) staticProperty(node *ast.Node) error {
	receiver := node.AsPropertyAccessExpression().Expression
	if !l.isStaticType(l.checker.GetTypeAtLocation(receiver)) && !(l.instance != nil && l.instance.static && ast.SkipParentheses(receiver).Kind == ast.KindThisKeyword) {
		return nil
	}
	symbol := l.checker.GetSymbolAtLocation(node.Name())
	if symbol != nil {
		for _, member := range symbol.Declarations {
			if member.Parent != nil && member.Parent.Kind == ast.KindClassDeclaration && ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
				return nil
			}
		}
	}
	return l.notYet(node, "an implicit constructor property such as prototype, name or length")
}

func (l *lowering) staticClassDeclaration(declaration *ast.Node) error {
	if ast.HasSyntacticModifier(declaration, ast.ModifierFlagsAmbient) {
		return l.notYet(declaration, "a declare class without a runtime definition")
	}
	for _, clause := range nodesOf(declaration.AsClassDeclaration().HeritageClauses) {
		if clause.AsHeritageClause().Token == ast.KindExtendsKeyword && l.staticBase(declaration) == nil {
			return l.notYet(clause, "a computed class base; name the base class directly")
		}
	}
	// Instance-private names belong to instance storage, even in the declaring class.
	// Diagnose this shape before registering static bodies: the wrong method key can
	// otherwise reach call-target analysis as an internal compiler error.
	for _, member := range declaration.Members() {
		if member.Kind != ast.KindClassStaticBlockDeclaration && !ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			continue
		}
		var failure error
		var visit ast.Visitor
		visit = func(node *ast.Node) bool {
			if node.Kind == ast.KindPropertyAccessExpression && node.Name().Kind == ast.KindPrivateIdentifier {
				symbol := l.checker.GetSymbolAtLocation(node.Name())
				if symbol != nil && len(symbol.Declarations) > 0 {
					target := symbol.Declarations[0]
					if target.Parent == declaration && !ast.HasSyntacticModifier(target, ast.ModifierFlagsStatic) {
						failure = &Refused{Where: l.program.Where(node), What: "instance private storage reached from a static member: " + declaration.Name().Text() + "." + node.Name().Text() + " (adamic/private-instance-from-static)", Fix: "move the private access into an instance method; call that instance method from the static member"}
						return true
					}
				}
			}
			return node.ForEachChild(visit)
		}
		member.ForEachChild(visit)
		if failure != nil {
			return failure
		}
	}
	return nil
}

func (l *lowering) staticStorage(declaration *ast.Node) {
	symbol := l.symbol(declaration.Name())
	if _, exists := l.staticGlobals[symbol]; exists {
		return
	}
	local := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: declaration.Name().Text() + "_class", Type: ir.Object, Function: -1, Global: true})
	l.staticGlobals[symbol] = local
	l.noteLocal(local, l.checker.GetTypeOfSymbol(symbol), declaration.Name())
}
func insideClass(node, declaration *ast.Node) bool {
	for parent := node.Parent; parent != nil; parent = parent.Parent {
		if parent.Kind == ast.KindClassDeclaration {
			return parent == declaration
		}
	}
	return false
}
func (l *lowering) staticClassRead(node *ast.Node) (ir.Expression, bool) {
	symbol := l.symbol(node)
	declaration := l.classes[symbol]
	local, exists := l.staticGlobals[symbol]
	if !exists || !insideClass(node, declaration) {
		return nil, false
	}
	return ir.Read{Local: local, Of: ir.Object, Checked: !l.provenModuleReads[node]}, true
}

// Looking up the constructor precedes evaluating new's arguments. Instance allocators
// remain independent functions, so make that declaration-readiness check explicit here.
func (l *lowering) staticConstruct(node, declaration *ast.Node, constructor int, arguments []ir.Expression) ir.Expression {
	symbol := l.symbol(declaration.Name())
	_, hasStorage := l.staticGlobals[symbol]
	if !hasStorage {
		return ir.Call{Function: constructor, Arguments: arguments, Returns: ir.Object}
	}
	expression := ast.SkipParentheses(node.AsNewExpression().Expression)
	receiver := ir.Expression(ir.Read{Local: l.locals[symbol], Of: ir.Object, Checked: !l.provenModuleReads[expression]})
	if inner, handled := l.staticClassRead(ast.SkipParentheses(node.AsNewExpression().Expression)); handled {
		receiver = inner
	}
	index := len(l.result.Functions)
	self := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "class", Type: ir.Object, Function: index})
	function := ir.Function{Name: "class_ready_new", Parameters: []int{self}, Returns: ir.Object, Receiver: true, ForwardsArguments: constructor + 1, RestElement: l.result.Functions[constructor].RestElement}
	forwarded := []ir.Expression{}
	for _, parameter := range l.result.Functions[constructor].Parameters {
		local := len(l.result.Locals)
		incoming := l.result.Locals[parameter]
		incoming.Function, incoming.Global, incoming.Captured, incoming.Borrowed = index, false, false, false
		l.result.Locals = append(l.result.Locals, incoming)
		function.Parameters = append(function.Parameters, local)
		forwarded = append(forwarded, ir.Read{Local: local, Of: incoming.Type})
	}
	function.Body = []ir.Statement{ir.Return{Value: ir.Call{Function: constructor, Arguments: forwarded, Returns: ir.Object, ForwardCount: true, RestPacked: true}}}
	l.result.Functions = append(l.result.Functions, function)
	return ir.Call{Function: index, Arguments: append([]ir.Expression{receiver}, arguments...), Returns: ir.Object}
}

class_static_private.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

func (l *lowering) privateStaticMember(name *ast.Node) *ast.Node {
	if name.Kind != ast.KindPrivateIdentifier {
		return nil
	}
	symbol := l.checker.GetSymbolAtLocation(name)
	if symbol == nil || len(symbol.Declarations) == 0 || !ast.HasSyntacticModifier(symbol.Declarations[0], ast.ModifierFlagsStatic) {
		return nil
	}
	return symbol.Declarations[0]
}

// A static private brand is exact, rather than inherited. Keep the check as a call so
// exception, ownership and reuse analyses see the throw and the receiver's lifetime.
func (l *lowering) privateStaticReceiver(name *ast.Node, object ir.Expression, write bool) ir.Expression {
	member := l.privateStaticMember(name)
	if member == nil {
		return object
	}
	class := l.statics[l.symbol(member.Parent.Name())]
	message := "Receiver must be class " + member.Parent.Name().Text()
	if member.Kind == ast.KindPropertyDeclaration {
		message = "Cannot read private member " + name.Text() + " from an object whose class did not declare it"
		if write {
			message = "Cannot write private member " + name.Text() + " to an object whose class did not declare it"
		}
	}
	index := len(l.result.Functions)
	self := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "this", Type: ir.Object, Function: index})
	value := ir.Read{Local: self, Of: ir.Object}
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "static_private_brand", Parameters: []int{self}, Returns: ir.Object, Body: []ir.Statement{
		ir.If{Condition: ir.InstanceOf{Value: value, Class: class.class, Exact: true}, Then: []ir.Statement{ir.Return{Value: value}}},
		ir.Throw{Value: ir.MakeError{Message: ir.StringConstant{Index: l.constant(message)}, Name: ir.StringConstant{Index: l.constant("TypeError")}}},
	}})
	return ir.Call{Function: index, Arguments: []ir.Expression{object}, Returns: ir.Object}
}

// A private assignment checks its brand after the RHS has executed, as JavaScript does.
func (l *lowering) privateStaticStore(target *ast.Node, object, value ir.Expression) (ir.Expression, bool) {
	if l.privateStaticMember(target.Name()) == nil {
		return nil, false
	}
	index := len(l.result.Functions)
	self := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "this", Type: ir.Object, Function: index}, ir.Local{Name: "value", Type: value.Type(), Function: index})
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "static_private_write", Parameters: []int{self, self + 1}})
	receiver := l.privateStaticReceiver(target.Name(), ir.Read{Local: self, Of: ir.Object}, true)
	l.result.Functions[index].Body = []ir.Statement{ir.SetProperty{Object: receiver, Name: l.fieldName(target.Name()), Value: ir.Read{Local: self + 1, Of: value.Type()}, Site: l.writeSite(target.AsPropertyAccessExpression().Expression)}}
	return ir.Call{Function: index, Arguments: []ir.Expression{object, value}}, true
}

class_super.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

const (
	superUninitialized uint8 = 1
	superInitialized   uint8 = 2
)

// constructorSuperFlow follows normal paths. A this use must have an initialized binding
// on every path reaching it; a deferred capture before initialization stays conservative.
type constructorSuperFlow struct {
	l         *lowering
	instance  *instance
	breaks    []uint8
	continues []uint8
}

func (flow *constructorSuperFlow) reads(node *ast.Node, state uint8) error {
	if node == nil {
		return nil
	}
	var failed error
	var visit ast.Visitor
	visit = func(child *ast.Node) bool {
		if (child.Kind == ast.KindThisKeyword || (child.Kind == ast.KindSuperKeyword && child.Parent != nil && child.Parent.Kind == ast.KindPropertyAccessExpression)) && state&superUninitialized != 0 {
			flow.instance.unreadyThis[child] = true
		}
		if child.Kind == ast.KindCallExpression && ast.SkipParentheses(child.AsCallExpression().Expression).Kind == ast.KindSuperKeyword {
			failed = flow.l.notYet(child, "super used as a value or in a deferred function; call it as a statement in each branch")
			return true
		}
		return child.ForEachChild(visit)
	}
	visit(node)
	return failed
}

func (flow *constructorSuperFlow) list(nodes []*ast.Node, state uint8) (uint8, error) {
	for _, node := range nodes {
		next, err := flow.statement(node, state)
		if err != nil {
			return 0, err
		}
		state = next
	}
	return state, nil
}

func (flow *constructorSuperFlow) expression(node *ast.Node, state uint8) (uint8, error) {
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindCallExpression && ast.SkipParentheses(node.AsCallExpression().Expression).Kind == ast.KindSuperKeyword {
		for _, argument := range nodesOf(node.AsCallExpression().Arguments) {
			if err := flow.reads(argument, state); err != nil {
				return 0, err
			}
		}
		flow.instance.superStates[node] |= state
		if state == 0 {
			return 0, nil
		}
		// A second call throws after the base runs; it has no normal continuation.
		if state&superUninitialized == 0 {
			return 0, nil
		}
		return superInitialized, nil
	}
	if node.Kind == ast.KindConditionalExpression {
		expression := node.AsConditionalExpression()
		if err := flow.reads(expression.Condition, state); err != nil {
			return 0, err
		}
		left, err := flow.expression(expression.WhenTrue, state)
		if err != nil {
			return 0, err
		}
		right, err := flow.expression(expression.WhenFalse, state)
		return left | right, err
	}
	return state, flow.reads(node, state)
}

func (flow *constructorSuperFlow) statement(node *ast.Node, state uint8) (uint8, error) {
	if node == nil {
		return state, nil
	}
	switch node.Kind {
	case ast.KindBlock:
		return flow.list(node.AsBlock().Statements.Nodes, state)
	case ast.KindExpressionStatement:
		return flow.expression(node.AsExpressionStatement().Expression, state)
	case ast.KindIfStatement:
		branch := node.AsIfStatement()
		if err := flow.reads(branch.Expression, state); err != nil {
			return 0, err
		}
		left, err := flow.statement(branch.ThenStatement, state)
		if err != nil {
			return 0, err
		}
		right, err := flow.statement(branch.ElseStatement, state)
		return left | right, err
	case ast.KindThrowStatement:
		return 0, flow.reads(node.AsThrowStatement().Expression, state)
	case ast.KindReturnStatement:
		return 0, flow.l.notYet(node, "an explicit return from a derived constructor")
	case ast.KindTryStatement:
		tried := node.AsTryStatement()
		normal, err := flow.statement(tried.TryBlock, state)
		if err != nil {
			return 0, err
		}
		if tried.CatchClause != nil {
			// A failure may occur on either side of super returning. The runtime flag
			// distinguishes a retry from a second successful initialization.
			caught, err := flow.statement(tried.CatchClause.AsCatchClause().Block, state|superInitialized)
			if err != nil {
				return 0, err
			}
			normal |= caught
		}
		if tried.FinallyBlock != nil {
			// Finally also runs on exceptional exits, before this might be initialized.
			if _, err := flow.statement(tried.FinallyBlock, state|normal); err != nil {
				return 0, err
			}
			normal, err = flow.statement(tried.FinallyBlock, normal)
		}
		return normal, err
	case ast.KindBreakStatement:
		if len(flow.breaks) > 0 {
			flow.breaks[len(flow.breaks)-1] |= state
		}
		return 0, nil
	case ast.KindContinueStatement:
		if len(flow.continues) > 0 {
			flow.continues[len(flow.continues)-1] |= state
		}
		return 0, nil
	case ast.KindForStatement, ast.KindWhileStatement, ast.KindDoStatement, ast.KindForOfStatement:
		return flow.loop(node, state)
	case ast.KindSwitchStatement:
		return flow.switchCases(node, state)
	}
	return state, flow.reads(node, state)
}

func (l *lowering) prepareSuper(constructor *ast.Node, initializer int) (uint8, error) {
	instance := l.instance
	instance.unreadyThis = map[*ast.Node]bool{}
	instance.superStates = map[*ast.Node]uint8{}
	flow := constructorSuperFlow{l: l, instance: instance}
	for _, parameter := range constructor.Parameters() {
		if err := flow.reads(parameter, superUninitialized); err != nil {
			return 0, err
		}
	}
	state, err := flow.statement(constructor.Body(), superUninitialized)
	if err != nil {
		return 0, err
	}
	instance.superReady = len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "superReady", Type: ir.Boolean, Function: initializer})
	l.result.Functions[initializer].Body = append(l.result.Functions[initializer].Body, ir.Declare{Local: instance.superReady, Value: ir.BooleanConstant{}})
	return state, nil
}

func (l *lowering) superError(message string) ir.Statement {
	return ir.Throw{Value: ir.MakeError{Message: ir.StringConstant{Index: l.constant(message)}, Name: ir.StringConstant{Index: l.constant("ReferenceError")}}}
}

func (l *lowering) superEnd() ir.Statement {
	return ir.If{Condition: ir.Unary{Operator: ir.Not, Operand: ir.Read{Local: l.instance.superReady, Of: ir.Boolean}}, Then: []ir.Statement{l.superError("Must call super constructor in derived class before accessing 'this' or returning from derived constructor")}}
}

// Conditional super used for effects has the same branch and field-initializer order as if.
func (l *lowering) conditionalSuper(node *ast.Node) ([]ir.Statement, bool, error) {
	if l.instance == nil || l.instance.base == nil || node.Kind != ast.KindConditionalExpression {
		return nil, false, nil
	}
	conditional := node.AsConditionalExpression()
	hasSuper := false
	var visit ast.Visitor
	visit = func(child *ast.Node) bool {
		if ast.IsFunctionLike(child) {
			return false
		}
		if child.Kind == ast.KindCallExpression && ast.SkipParentheses(child.AsCallExpression().Expression).Kind == ast.KindSuperKeyword {
			hasSuper = true
			return true
		}
		return child.ForEachChild(visit)
	}
	visit(node)
	if !hasSuper {
		return nil, false, nil
	}
	condition, err := l.condition(conditional.Condition)
	if err != nil {
		return nil, true, err
	}
	yes, err := l.expressionStatement(conditional.WhenTrue)
	if err != nil {
		return nil, true, err
	}
	no, err := l.expressionStatement(conditional.WhenFalse)
	if err != nil {
		return nil, true, err
	}
	return []ir.Statement{ir.If{Condition: condition, Then: yes, Else: no}}, true, nil
}

// Backedges may arrive with an initialized binding. Preserve zero-iteration and
// break paths too; the flag checks missing or repeated initialization at runtime.
func (flow *constructorSuperFlow) loop(node *ast.Node, state uint8) (uint8, error) {
	var body, condition, increment *ast.Node
	switch node.Kind {
	case ast.KindForStatement:
		loop := node.AsForStatement()
		body, condition, increment = loop.Statement, loop.Condition, loop.Incrementor
		if loop.Initializer != nil {
			var err error
			if loop.Initializer.Kind == ast.KindVariableDeclarationList {
				err = flow.reads(loop.Initializer, state)
			} else {
				state, err = flow.expression(loop.Initializer, state)
			}
			if err != nil {
				return 0, err
			}
		}
	case ast.KindWhileStatement:
		body, condition = node.AsWhileStatement().Statement, node.AsWhileStatement().Expression
	case ast.KindDoStatement:
		body, condition = node.AsDoStatement().Statement, node.AsDoStatement().Expression
	case ast.KindForOfStatement:
		loop := node.AsForInOrOfStatement()
		body = loop.Statement
		if err := flow.reads(loop.Expression, state); err != nil {
			return 0, err
		}
	}
	entry := state | superInitialized
	if state == 0 {
		entry = 0
	}
	if node.Kind != ast.KindDoStatement {
		if err := flow.reads(condition, entry); err != nil {
			return 0, err
		}
	}
	flow.breaks = append(flow.breaks, 0)
	flow.continues = append(flow.continues, 0)
	normal, err := flow.statement(body, entry)
	broken := flow.breaks[len(flow.breaks)-1]
	continued := flow.continues[len(flow.continues)-1]
	flow.breaks = flow.breaks[:len(flow.breaks)-1]
	flow.continues = flow.continues[:len(flow.continues)-1]
	if err != nil {
		return 0, err
	}
	normal |= continued
	if increment != nil {
		normal, err = flow.expression(increment, normal)
		if err != nil {
			return 0, err
		}
	}
	if node.Kind == ast.KindDoStatement {
		if err := flow.reads(condition, normal); err != nil {
			return 0, err
		}
	}
	result := normal | broken
	if node.Kind != ast.KindDoStatement {
		result |= state
	}
	return result, nil
}

func (flow *constructorSuperFlow) switchCases(node *ast.Node, state uint8) (uint8, error) {
	switched := node.AsSwitchStatement()
	if err := flow.reads(switched.Expression, state); err != nil {
		return 0, err
	}
	flow.breaks = append(flow.breaks, 0)
	fallback, fallthroughState := false, uint8(0)
	clauses := switched.CaseBlock.AsCaseBlock().Clauses.Nodes
	for _, clause := range clauses {
		branch := clause.AsCaseOrDefaultClause()
		if clause.Kind == ast.KindDefaultClause {
			fallback = true
		}
		if err := flow.reads(branch.Expression, state); err != nil {
			flow.breaks = flow.breaks[:len(flow.breaks)-1]
			return 0, err
		}
		normal, err := flow.list(branch.Statements.Nodes, state|fallthroughState)
		if err != nil {
			flow.breaks = flow.breaks[:len(flow.breaks)-1]
			return 0, err
		}
		fallthroughState = normal
	}
	result := fallthroughState | flow.breaks[len(flow.breaks)-1]
	flow.breaks = flow.breaks[:len(flow.breaks)-1]
	if !fallback {
		result |= state
	}
	return result, nil
}

clock_generic_returns_t_01.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
)

// clockGenericReturnsT01 proves only an optional plain-object intersection. The
// checker retains every field (including refinements and readonly declarations);
// no constituent or type argument is erased to choose the pointer representation.
// Undefined uses the existing missing object pointer; null is never admitted.
func (l *lowering) clockGenericReturnsT01(result *checker.Type) (ir.Type, bool) {
	result = l.concrete(result)
	if result.Flags()&checker.TypeFlagsUnion == 0 || len(result.Types()) != 2 {
		return 0, false
	}
	var object *checker.Type
	missing := false
	for _, member := range result.Types() {
		member = l.concrete(member)
		if member.Flags()&checker.TypeFlagsUndefined != 0 {
			missing = true
		} else {
			object = member
		}
	}
	if !missing || object == nil || object.Flags()&checker.TypeFlagsIntersection == 0 {
		return 0, false
	}
	// This hand-off owns the generic object plus refinement signature, not the
	// other optional nongeneric intersection briefs.
	if len(object.Types()) != 2 {
		return 0, false
	}
	generic := false
	for _, part := range object.Types() {
		// Only a type reference has type arguments; the checker dereferences nil for anything
		// else, such as the string in a branded string & { __brand: void }.
		part = l.concrete(part)
		generic = generic || part.Flags()&checker.TypeFlagsObject != 0 && part.ObjectFlags()&checker.ObjectFlagsReference != 0 && len(l.checker.GetTypeArguments(part)) != 0
	}
	if !generic {
		return 0, false
	}
	if !l.clockGenericReturnsT01Shape(object, map[*checker.Type]bool{}) {
		return 0, false
	}
	return ir.Object, true
}

func (l *lowering) clockGenericReturnsT01Shape(proven *checker.Type, active map[*checker.Type]bool) bool {
	proven = l.concrete(proven)
	if proven == nil || active[proven] {
		return false
	}
	flags := proven.Flags()
	if flags&(checker.TypeFlagsStringLike|checker.TypeFlagsNumberLike|checker.TypeFlagsBooleanLike) != 0 {
		return true
	}
	if flags&(checker.TypeFlagsObject|checker.TypeFlagsIntersection) == 0 {
		return false
	}
	active[proven] = true
	defer delete(active, proven)
	// Arrays are admitted only as nested string fields, using the existing string
	// array representation. Intersections of containers never pass this check.
	if l.checker.IsArrayType(proven) {
		arguments := l.checker.GetTypeArguments(proven)
		return len(arguments) == 1 && l.concrete(arguments[0]).Flags()&checker.TypeFlagsStringLike != 0
	}
	if checker.IsTupleType(proven) || isClassInstance(proven) ||
		len(l.checker.GetSignaturesOfType(proven, checker.SignatureKindCall)) != 0 ||
		len(l.checker.GetSignaturesOfType(proven, checker.SignatureKindConstruct)) != 0 ||
		len(l.checker.GetIndexInfosOfType(proven)) != 0 {
		return false
	}
	if symbol := proven.Symbol(); symbol != nil {
		for _, declaration := range symbol.Declarations {
			if load.IsLibrary(ast.GetSourceFileOfNode(declaration)) {
				return false
			}
		}
	}
	if flags&checker.TypeFlagsIntersection != 0 {
		for _, part := range proven.Types() {
			part = l.concrete(part)
			if part.Flags()&checker.TypeFlagsObject == 0 || l.checker.IsArrayType(part) || !l.clockGenericReturnsT01Shape(part, active) {
				return false
			}
		}
	}
	fields := l.checker.GetPropertiesOfType(proven)
	if len(fields) == 0 {
		return false
	}
	for _, field := range fields {
		if !l.clockGenericReturnsT01Shape(l.checker.GetTypeOfSymbol(field), active) {
			return false
		}
	}
	return true
}

closed_frame_inputs.go:
package lower

import (
	"github.com/system-inc/adamic/internal/ir"
	"slices"
)

// closedFrameInput proves a narrow exception to type-based capture cycles.
// Every call supplies a literal of scalars and capture-free closures, the
// parameter is never replaced, and no operation can rewrite an object field.
// This is a closed input graph proof, not freshness of arbitrary captured cells.
func (l *lowering) closedFrameInput(local int) bool {
	owner := l.result.Locals[local].Function
	if owner < 0 || l.result.Functions[owner].Closure {
		return false
	}
	position := slices.Index(l.result.Functions[owner].Parameters, local)
	if position < 0 {
		return false
	}
	safe, called := true, false
	inspect := func(node any) bool {
		switch value := node.(type) {
		case ir.Assign:
			if value.Local == local {
				safe = false
			}
		case ir.MakeClosure:
			if value.Function == owner {
				safe = false
			}
		case ir.Call:
			if !slices.Contains(l.result.CallTargets(value), owner) {
				break
			}
			called = true
			if value.Virtual != 0 || position >= len(value.Arguments) || !l.closedInputLiteral(value.Arguments[position]) {
				safe = false
			}
		}
		if expression, ok := node.(ir.Expression); ok {
			switch expression.(type) {
			case ir.NumberConstant, ir.BooleanConstant, ir.StringConstant, ir.Undefined, ir.Read,
				ir.Binary, ir.Unary, ir.Conditional, ir.Coalesce, ir.Box, ir.Narrow, ir.Unwrap,
				ir.MaybeOf, ir.Defined, ir.IsUndefined, ir.NumberToString, ir.BooleanToString,
				ir.Concat, ir.Length, ir.Property, ir.ArrayIndex, ir.ArrayLiteral, ir.ObjectLiteral,
				ir.Call, ir.CallClosure, ir.MakeClosure, ir.ClosureSelf:
			default:
				safe = false
			}
		}
		if statement, ok := node.(ir.Statement); ok {
			switch statement.(type) {
			case ir.AllocateEnvironment, ir.Declare, ir.Assign, ir.Evaluate, ir.Return, ir.WriteLine,
				ir.If, ir.Block, ir.Loop, ir.ForOf, ir.Switch, ir.Break, ir.Continue:
			default:
				safe = false
			}
		}
		return true
	}
	for _, function := range l.result.Functions {
		walk(function.Body, inspect)
	}
	walk(l.result.Main, inspect)
	return safe && called
}

func (l *lowering) closedInputLiteral(value ir.Expression) bool {
	literal, ok := value.(ir.ObjectLiteral)
	if !ok || literal.Spread != nil || literal.Class != 0 {
		return false
	}
	for _, field := range literal.Fields {
		switch value := field.Value.(type) {
		case ir.NumberConstant, ir.BooleanConstant, ir.StringConstant, ir.Undefined:
		case ir.MakeClosure:
			if len(l.result.Functions[value.Function].Environment) != 0 {
				return false
			}
		default:
			return false
		}
	}
	return true
}

collections.go:
package lower

import (
	"strconv"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
)

// keyable reports whether values of a type can be a Map's keys or a Set's elements: strings, numbers
// and booleans, plus packed number | undefined, compared as === compares them (numbers by
// SameValueZero), and objects, arrays, maps
// and functions, each its own key, compared by identity.
func keyable(valueType ir.Type) bool {
	switch valueType {
	case ir.String, ir.Number, ir.Boolean, ir.MaybeNumber, ir.Object, ir.Array, ir.Map, ir.Closure:
		return true
	}
	return false
}

// iterated lowers something a for...of or a spread walks as the array of what it gives, with that
// array's element type: an array, a string's code points, a Set's elements, a Map's [key, value]
// entries, and map.keys(), map.values(), map.entries(), set.keys() and set.values().
func (l *lowering) iterated(node *ast.Node) (ir.Expression, ir.Type, error) {
	node = ast.SkipParentheses(node)
	if element, iterator := l.libraryIteratorElement(node); iterator {
		value, err := l.expression(node)
		if err != nil {
			return nil, 0, err
		}
		return l.libraryIteratorArray(node, value, element), element, nil
	}
	if plan, err := l.planIteration(node); err != nil {
		return nil, 0, err
	} else if plan != nil {
		value, err := l.collectIteration(node, node, nil, plan, plan.element)
		return value, plan.element, err
	}
	if node.Kind == ast.KindCallExpression && len(node.AsCallExpression().Arguments.Nodes) == 0 {
		if callee := ast.SkipParentheses(node.AsCallExpression().Expression); callee.Kind == ast.KindPropertyAccessExpression {
			receiver := callee.AsPropertyAccessExpression().Expression
			part := callee.Name().Text()
			receiverType, _ := l.representation(l.checker.GetTypeAtLocation(receiver))
			if receiverType == ir.Map && (part == "keys" || part == "values" || part == "entries") {
				return l.collectionPart(node, receiver, part)
			}
		}
	}
	if l.checker.IsArrayType(l.checker.GetTypeAtLocation(node)) {
		element, err := l.elementType(node)
		if err != nil {
			return nil, 0, err
		}
		array, err := l.expression(node)
		return array, element, err
	}
	value, err := l.expression(node)
	if err != nil {
		return nil, 0, err
	}
	switch value.Type() {
	case ir.String:
		return ir.CodePoints{Value: value}, ir.String, nil
	case ir.Map:
		if l.isSet(node) {
			element, err := l.setElement(node)
			if err != nil {
				return nil, 0, err
			}
			return ir.SetValues{Set: value, Element: element}, element, nil
		}
		key, mapped, err := l.mapTypes(node)
		if err != nil {
			return nil, 0, err
		}
		return ir.MapEntries{Map: value, KeyType: key, ValueType: mapped}, ir.Object, nil
	}
	return nil, 0, l.notYet(node, "iterating a "+typeName(value.Type()))
}

// collectionPart lowers map.keys(), map.values() and map.entries(), and set.keys() and set.values(),
// where they're walked whole: each is a new array of what it gives.
func (l *lowering) collectionPart(node *ast.Node, receiver *ast.Node, part string) (ir.Expression, ir.Type, error) {
	if l.isSet(receiver) {
		if part == "entries" {
			iterator, _, err := l.libraryCollectionIterator(node, receiver, part)
			if err != nil {
				return nil, 0, err
			}
			return l.libraryIteratorArray(node, iterator, ir.Object), ir.Object, nil
		}
		element, err := l.setElement(receiver)
		if err != nil {
			return nil, 0, err
		}
		set, err := l.expression(receiver)
		if err != nil {
			return nil, 0, err
		}
		return ir.SetValues{Set: set, Element: element}, element, nil
	}
	key, value, err := l.mapTypes(receiver)
	if err != nil {
		return nil, 0, err
	}
	collection, err := l.expression(receiver)
	if err != nil {
		return nil, 0, err
	}
	switch part {
	case "keys":
		return ir.MapKeys{Map: collection, Key: key}, key, nil
	case "values":
		return ir.MapValues{Map: collection, Value: value}, value, nil
	}
	return ir.MapEntries{Map: collection, KeyType: key, ValueType: value}, ir.Object, nil
}

// newMapFrom lowers new Map(pairs) from anything that gives [key, value] pairs: an array of tuples,
// another Map, or map.entries(). Each pair's key and value must be held as the Map holds its own, or
// a number would land where number | undefined goes without becoming the pair, so they're checked.
func (l *lowering) newMapFrom(node *ast.Node, source *ast.Node, key ir.Type, value ir.Type) (ir.Expression, error) {
	pairKey, pairValue, isKnown := l.pairTypes(source)
	if !isKnown {
		return nil, l.notYet(source, "new Map from something that isn't [key, value] pairs")
	}
	if pairKey != key || pairValue != value {
		return nil, l.notYet(source, "new Map from pairs held otherwise than the Map's keys and values")
	}
	pairs, element, err := l.iterated(source)
	if err != nil {
		return nil, err
	}
	if element != ir.Object {
		return nil, l.notYet(source, "new Map from something that isn't [key, value] pairs")
	}
	return ir.MapNew{Key: key, Value: value, Pairs: pairs}, nil
}

// pairTypes is how a source of [key, value] pairs holds its keys and values: an array of tuples by its
// tuple's types, a Map (and its entries()) by its own.
func (l *lowering) pairTypes(source *ast.Node) (ir.Type, ir.Type, bool) {
	source = ast.SkipParentheses(source)
	sourceType := l.checker.GetTypeAtLocation(source)
	if l.checker.IsArrayType(sourceType) || l.isLibraryType(sourceType, "MapIterator", "SetIterator", "Set", "ReadonlySet") {
		element := l.checker.GetElementTypeOfArrayType(sourceType)
		if element == nil {
			arguments := l.typeArguments(sourceType)
			if len(arguments) != 1 {
				return 0, 0, false
			}
			element = arguments[0]
		}
		if !checker.IsTupleType(element) {
			return 0, 0, false
		}
		arguments := l.checker.GetTypeArguments(element)
		if len(arguments) != 2 {
			return 0, 0, false
		}
		key, keyKnown := l.representation(arguments[0])
		value, valueKnown := l.representation(arguments[1])
		return key, value, keyKnown && valueKnown
	}
	if source.Kind == ast.KindCallExpression {
		callee := ast.SkipParentheses(source.AsCallExpression().Expression)
		if callee.Kind != ast.KindPropertyAccessExpression || callee.Name().Text() != "entries" {
			return 0, 0, false
		}
		source = callee.AsPropertyAccessExpression().Expression
	}
	if representation, _ := l.representation(l.checker.GetTypeAtLocation(source)); representation != ir.Map {
		return 0, 0, false
	}
	if l.isSet(source) {
		element, err := l.setElement(source)
		return element, element, err == nil
	}
	key, value, err := l.mapTypes(source)
	return key, value, err == nil
}

// clearOrVisit lowers clear() and forEach(callback) on a Map or a Set.
func (l *lowering) clearOrVisit(node *ast.Node, receiver *ast.Node, name string, set bool) (ir.Expression, bool, error) {
	var key, value ir.Type
	var err error
	if set {
		key, err = l.setElement(receiver)
		value = key
	} else {
		key, value, err = l.mapTypes(receiver)
	}
	if err != nil {
		return nil, true, err
	}
	collection, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	arguments := node.AsCallExpression().Arguments.Nodes
	if name == "clear" {
		if len(arguments) != 0 {
			return nil, true, l.notYet(node, "clear with arguments")
		}
		return ir.MapClear{Map: collection}, true, nil
	}
	if len(arguments) == 2 {
		return l.libraryForEachThisArg(node, receiver, set)
	}
	if len(arguments) != 1 {
		return nil, true, l.notYet(node, "forEach with other than one callback")
	}
	callback, err := l.expression(arguments[0])
	if err != nil {
		return nil, true, err
	}
	if callback.Type() != ir.Closure {
		return nil, true, l.notYet(arguments[0], "forEach with a callback that isn't a function")
	}
	signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(arguments[0]), checker.SignatureKindCall)
	if len(signatures) != 1 {
		return nil, true, l.notYet(arguments[0], "forEach with an overloaded callback")
	}
	var returns ir.Type
	if result := l.checker.GetReturnTypeOfSignature(signatures[0]); result.Flags()&checker.TypeFlagsVoid == 0 {
		var isKnown bool
		if returns, isKnown = l.representation(result); !isKnown || slotless(returns) {
			return nil, true, l.notYet(arguments[0], "forEach with a callback returning "+l.checker.TypeToString(result))
		}
	}
	return ir.MapForEach{Map: collection, Callback: callback, Key: key, Value: value, Set: set, Returns: returns, CallbackType: int(l.concrete(l.checker.GetTypeAtLocation(arguments[0])).Id())}, true, nil
}

// tupleLength is tuple.length for a tuple of fixed length: its type's count, which the checker gives
// as the type of the read. The tuple is a plain variable, so not reading it changes nothing, unless
// it's a global read from a function, which may throw for the temporal dead zone, as JavaScript does.
func (l *lowering) tupleLength(node *ast.Node, tuple *ast.Node) (ir.Expression, error) {
	tuple = ast.SkipParentheses(tuple)
	local, isLocal := l.local(tuple)
	if !ast.IsIdentifier(tuple) || !isLocal || l.checked(local) {
		return nil, l.notYet(node, "the length of a tuple that isn't a plain local")
	}
	if l.checker.GetTypeAtLocation(node).Flags()&checker.TypeFlagsNumberLiteral == 0 {
		return nil, l.notYet(node, "the length of a tuple with optional or rest elements")
	}
	return l.numericLiteral(node)
}

// destructure lowers const [a, b] = tuple and const { x, y } = object, and let: what's destructured
// is held in a local of its own, made here, and each name is declared from its field, in order, as
// JavaScript reads them.
func (l *lowering) destructure(pattern *ast.Node, initializer *ast.Node) ([]ir.Statement, error) {
	if initializer == nil {
		return nil, l.notYet(pattern, "a destructuring declaration without a value")
	}
	if pattern.Kind == ast.KindArrayBindingPattern {
		if plan, err := l.planIteration(initializer); err != nil {
			return nil, err
		} else if plan != nil {
			return l.destructureIterator(pattern, initializer, plan)
		}
	}
	value, err := l.expression(initializer)
	if err != nil {
		return nil, err
	}
	held := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "destructured", Type: ir.Object, Function: l.functionIndex})
	declared, err := l.destructureFrom(pattern, l.checker.GetTypeAtLocation(initializer), value.Type(), held)
	if err != nil {
		return nil, err
	}
	return append([]ir.Statement{ir.Declare{Local: held, Value: value}}, declared...), nil
}

// destructureFrom declares a pattern's names from the local held, which holds a value of type
// destructured (held as heldAs): a tuple's elements by position, an object's fields by name.
func (l *lowering) destructureFrom(pattern *ast.Node, destructured *checker.Type, heldAs ir.Type, held int) ([]ir.Statement, error) {
	tuple := pattern.Kind == ast.KindArrayBindingPattern
	if tuple && !checker.IsTupleType(destructured) {
		return nil, l.notYet(pattern, "destructuring anything but a tuple into [names]")
	}
	if heldAs != ir.Object {
		return nil, l.notYet(pattern, "destructuring a "+typeName(heldAs))
	}
	var elementTypes []*checker.Type
	if tuple {
		elementTypes = l.checker.GetTypeArguments(destructured)
	}
	statements := []ir.Statement{}
	for index, binding := range pattern.AsBindingPattern().Elements.Nodes {
		// A hole, [, second], is a binding element with no name.
		if binding.Kind == ast.KindOmittedExpression || binding.Name() == nil {
			continue
		}
		declared := binding.AsBindingElement()
		if !ast.IsIdentifier(binding.Name()) || declared.Initializer != nil || declared.DotDotDotToken != nil {
			return nil, l.notYet(binding, "a destructured name that isn't plain")
		}
		var field string
		var fieldType *checker.Type
		absent := false
		if tuple {
			if index >= len(elementTypes) {
				return nil, l.notYet(binding, "destructuring past a tuple's end")
			}
			field, fieldType = strconv.Itoa(index), elementTypes[index]
		} else {
			// { x } reads x, and { x: other } reads x into other.
			field = binding.Name().Text()
			if declared.PropertyName != nil {
				if !ast.IsIdentifier(declared.PropertyName) && declared.PropertyName.Kind != ast.KindStringLiteral {
					return nil, l.notYet(declared.PropertyName, "a computed field name")
				}
				field = declared.PropertyName.Text()
			}
			property := l.checker.GetPropertyOfType(destructured, field)
			if property == nil {
				return nil, l.notYet(binding, "destructuring a field the type doesn't name")
			}
			if l.inheritedLibrarySymbol(property) {
				return nil, l.prototypeRead(binding, field)
			}
			if property.Flags&ast.SymbolFlagsMethod != 0 {
				return nil, &Refused{Where: l.program.Where(binding), What: "a method in object destructuring", Fix: "call it on its receiver or wrap that call in an arrow; destructuring would lose this"}
			}
			for _, root := range l.checker.GetRootSymbols(property) {
				for _, declaration := range root.Declarations {
					if load.IsLibrary(ast.GetSourceFileOfNode(declaration)) {
						return nil, l.notYet(binding, "an inherited library member in object destructuring, which is not an own field")
					}
				}
			}
			if err := l.erasedMethodField(binding, destructured, field); err != nil {
				return nil, err
			}
			fieldType = l.checker.GetTypeOfSymbol(property)
			absent = property.Flags&ast.SymbolFlagsOptional != 0
		}
		local, err := l.declareLocal(binding.Name())
		if err != nil {
			return nil, err
		}
		of := l.result.Locals[local].Type
		if element, isKnown := l.representation(fieldType); !isKnown || element != of || (slotless(of) && !(of == ir.Union && l.writable(fieldType))) {
			return nil, l.notYet(binding, "a destructured name held otherwise than its field")
		}
		value := ir.Property{Object: ir.Read{Local: held, Of: ir.Object}, Name: field, Of: of, Absent: absent}
		value.View = sourceExpression(binding) + " (field " + field + ")"
		value.ViewType = l.checker.TypeToString(fieldType)
		value.ViewAllowed = l.viewLiterals(fieldType)
		statements = append(statements, l.initializeLocal(local, value)...)
	}
	return statements, nil
}

// optionalTupleElement is tuple?.[index], a tuple that may be missing: its field when it's there, and
// undefined when it isn't, which a number field gives as number | undefined and a reference field as
// a null one. Fields held any other way stay not yet, as for ?. on a field (object.go's property).
func (l *lowering) optionalTupleElement(node *ast.Node, object ir.Expression, index *ast.Node) (ir.Expression, error) {
	access := node.AsElementAccessExpression()
	tuple := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(access.Expression))
	if index.Kind != ast.KindNumericLiteral || !checker.IsTupleType(tuple) {
		return nil, l.notYet(node, "?.[] on anything but a tuple, at a position written out")
	}
	elements := l.checker.GetTypeArguments(tuple)
	position, err := strconv.Atoi(index.Text())
	if err != nil || position >= len(elements) {
		return nil, l.notYet(node, "?.[] past a tuple's end")
	}
	held, isKnown := l.representation(elements[position])
	if !isKnown || (held != ir.Number && !held.IsReference()) || held == ir.Weak {
		return nil, l.notYet(node, "?.[] to a tuple element of type "+l.checker.TypeToString(elements[position]))
	}
	return ir.Property{Object: object, Name: strconv.Itoa(position), Of: held, Optional: true}, nil
}

// everyKnown reports whether every type has a representation.
func (l *lowering) everyKnown(types []*checker.Type) bool {
	for _, each := range types {
		if _, isKnown := l.representation(each); !isKnown {
			return false
		}
	}
	return true
}

comma.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

func (l *lowering) comma(node *ast.Node) (ir.Expression, error) {
	binary := node.AsBinaryExpression()
	left, err := l.discardedValue(binary.Left)
	if err != nil {
		return nil, err
	}
	right, err := l.expression(binary.Right)
	if err != nil {
		return nil, err
	}
	return ir.Comma{Left: left, Right: right}, nil
}

// discardedValue accepts the effects already lowered as statements too: writes, increments,
// console calls and void calls. The discarded value never needs storage.
func (l *lowering) discardedValue(node *ast.Node) (ir.Expression, error) {
	value, err := l.expression(node)
	if err == nil {
		return value, nil
	}
	statements, statementErr := l.expressionStatement(node)
	if statementErr != nil {
		return nil, err
	}
	walk(statements, func(node any) bool {
		if assign, ok := node.(ir.Assign); ok {
			l.result.Locals[assign.Local].ExpressionAssigned = true
		}
		if declare, ok := node.(ir.Declare); ok {
			l.result.Locals[declare.Local].ExpressionAssigned = true
		}
		return true
	})
	return ir.Effects{Body: statements, Result: ir.Undefined{}}, nil
}

