// Functions and declarations moved unchanged from lower.go.
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

func (l *lowering) ifStatement(node *ast.Node) ([]ir.Statement, error) {
	statement := node.AsIfStatement()
	condition, err := l.condition(statement.Expression)
	if err != nil {
		return nil, err
	}
	then, err := l.statement(statement.ThenStatement)
	if err != nil {
		return nil, err
	}
	lowered := ir.If{Condition: condition, Then: then}
	if statement.ElseStatement != nil {
		if lowered.Else, err = l.statement(statement.ElseStatement); err != nil {
			return nil, err
		}
	}
	return []ir.Statement{lowered}, nil
}

// forStatement lowers for (initializer; condition; incrementor) to a loop inside a block, so the
// loop's own declarations are scoped to it.
func (l *lowering) forStatement(node *ast.Node) ([]ir.Statement, error) {
	statement := node.AsForStatement()
	block := ir.Block{}
	if initializer := statement.Initializer; initializer != nil {
		var err error
		var initial []ir.Statement
		if initializer.Kind == ast.KindVariableDeclarationList {
			initial, err = l.variables(initializer)
		} else {
			initial, err = l.expressionStatement(initializer)
		}
		if err != nil {
			return nil, err
		}
		block.Body = append(block.Body, initial...)
	}
	loop := ir.Loop{Condition: ir.BooleanConstant{Value: true}}
	for _, statement := range block.Body {
		if declared, isDeclare := statement.(ir.Declare); isDeclare && initializerIsLet(statement, node) {
			loop.PerIteration = append(loop.PerIteration, declared.Local)
		}
	}
	if statement.Condition != nil {
		condition, err := l.condition(statement.Condition)
		if err != nil {
			return nil, err
		}
		loop.Condition = condition
	}
	if statement.Incrementor != nil {
		update, err := l.expressionStatement(statement.Incrementor)
		if err != nil {
			return nil, err
		}
		loop.Update = update
	}
	body, err := l.statement(statement.Statement)
	if err != nil {
		return nil, err
	}
	loop.Body = body
	block.Body = append(block.Body, loop)
	return []ir.Statement{block}, nil
}

// whileStatement lowers while and do...while.
func (l *lowering) whileStatement(node *ast.Node) ([]ir.Statement, error) {
	var expression, body *ast.Node
	checkAfter := node.Kind == ast.KindDoStatement
	if checkAfter {
		expression, body = node.AsDoStatement().Expression, node.AsDoStatement().Statement
	} else {
		expression, body = node.AsWhileStatement().Expression, node.AsWhileStatement().Statement
	}
	condition, err := l.condition(expression)
	if err != nil {
		return nil, err
	}
	loweredBody, err := l.statement(body)
	if err != nil {
		return nil, err
	}
	return []ir.Statement{ir.Loop{Condition: condition, Body: loweredBody, CheckAfter: checkAfter}}, nil
}

// condition applies JavaScript ToBoolean to one evaluation of its operand.
func (l *lowering) condition(node *ast.Node) (ir.Expression, error) {
	value, err := l.expression(node)
	if err != nil {
		return nil, err
	}
	return censusCondition(value), nil
}

// initializerIsLet reports whether a for loop declares its variables with let, which JavaScript gives
// a fresh binding each iteration (const can't change, so a copy would be the same).
func initializerIsLet(_ ir.Statement, node *ast.Node) bool {
	initializer := node.AsForStatement().Initializer
	return initializer != nil && initializer.Kind == ast.KindVariableDeclarationList && initializer.Flags&ast.NodeFlagsLet != 0
}

counters.go:
package lower

import (
	"math"

	"github.com/system-inc/adamic/internal/ir"
)

// counters marks the loop counters the native backend may keep in an integer (ir.Local.Counter).
//
// A number in JavaScript is a double, and a loop counter is one too. But a counter that starts at a
// whole number, steps by a whole number, and stops at a bound that's a whole number in a range known
// at compile time can only ever hold the whole numbers between its start and one step past its
// bound. When every one of those is no larger than 2^53 in size, each is a double exactly, and every
// step on the way is exact too, so an integer holds the same values, and read as a double it's the
// same number: the same answers, for an integer's step and an integer index into an array. The loop
// has to be one this can see whole:
//
//		for (let counter = start; counter < bound; counter += step)    (or <=, counter++, = counter + step)
//		for (let counter = start; counter > bound; counter -= step)    (or >=, counter--, = counter - step)
//
//	  - start is a whole number within 2^53, of the kind a bound is (below), that can't be -0, since
//	    an integer has no -0 and 1 / counter would tell; step is a whole-number constant, 1 or more;
//	  - nothing but the update writes the counter, and no closure captures it (a cell holds a double);
//	  - bound is, every time the condition reads it, a whole number in a known range: an array's, a
//	    string's or a map's size (from 0 to 2^32), a constant, a variable nothing writes but its
//	    declaration, the counter of a loop it's in the body of (in the range it holds there), or any
//	    of those negated, added, subtracted or multiplied, which keep whole numbers whole while they
//	    stay within 2^53. Division and remainder don't, and NaN, infinities and
//	    fractions aren't whole; their loops keep a double, as does anything else;
//	  - and the last value the counter can take, one step past the largest bound below which it still
//	    runs (or the smallest, counting down), is within 2^53: past it, JavaScript's counter + step is
//	    rounded, and the loop can stop moving, where an integer would go on.
//
// Counting up runs with < or <=, and down with > or >=; a counter that moves away from its bound
// keeps a double, since nothing bounds where it goes. A global counter keeps a double too, since a
// function may run before its loop has.
func counters(program *ir.Program) {
	known := facts{assigned: map[int]bool{}, declared: map[int]ir.Expression{}, counters: map[int]span{}}
	for _, function := range program.Functions {
		findAssigned(function.Body, known.assigned)
		findDeclared(function.Body, known.declared)
	}
	findAssigned(program.Main, known.assigned)
	findDeclared(program.Main, known.declared)
	// Blocks are visited outside in, so a loop's counter is marked, and its range known, before the
	// loops in its body are looked at.
	mark := func(statements []ir.Statement) {
		eachBlock(statements, func(block ir.Block) {
			markCounter(program, block, known)
		})
	}
	for _, function := range program.Functions {
		mark(function.Body)
	}
	mark(program.Main)
}

// facts is what the pass knows of a program's locals: which are written after their declaration,
// what each was declared with, and the range each counter it has marked holds in its loop's body.
type facts struct {
	assigned map[int]bool
	declared map[int]ir.Expression
	counters map[int]span
}

// span is the least and the most a counter can be.
type span struct {
	low, high float64
}

// exact is 2^53: every whole number no larger than it in size is a double exactly.
var exact = math.Ldexp(1, 53)

// markCounter marks the counter of a for loop's block, if it has one this can keep in an integer.
func markCounter(program *ir.Program, block ir.Block, known facts) {
	if len(block.Body) == 0 {
		return
	}
	loop, isLoop := block.Body[len(block.Body)-1].(ir.Loop)
	if !isLoop || loop.CheckAfter || len(loop.Update) != 1 {
		return
	}
	condition, isBinary := loop.Condition.(ir.Binary)
	if !isBinary {
		return
	}
	counterRead, isRead := condition.Left.(ir.Read)
	if !isRead {
		return
	}
	counter := counterRead.Local
	local := program.Locals[counter]
	if local.Type != ir.Number || local.Global || local.Captured || local.ExpressionAssigned || !perIteration(loop, counter) {
		return
	}
	// Its start: a declaration in this block, of a whole number within 2^53, as a bound is, that
	// can't be -0.
	start, isDeclared := declaredIn(block, counter)
	if !isDeclared || start == nil {
		return
	}
	startLow, startHigh, isWhole := boundRange(start, known, 0)
	if !isWhole || !neverNegativeZero(start, known, 0) {
		return
	}
	// Its update, a whole step toward the bound, and nothing in the body that writes it.
	step, isStep := stepOf(loop.Update[0], counter)
	if !isStep {
		return
	}
	written := map[int]bool{}
	findAssigned(loop.Body, written)
	if written[counter] {
		return
	}
	low, high, isWhole := boundRange(condition.Right, known, 0)
	if !isWhole {
		return
	}
	// The furthest the counter can go, one step past the last value the condition lets through, must
	// be within 2^53. It's checked as a limit on the bound, since high + step, done in doubles, would
	// round: 2^53 + 1 is the double 2^53. Each limit is exact, the step being whole and within 2^53.
	// Where the limit is met, the range the counter holds in the body follows: from its start to the
	// last value the condition lets through.
	size := math.Abs(step)
	var inBody span
	switch {
	case step > 0 && condition.Operator == ir.Less:
		// high - 1 + step <= 2^53
		isWhole = high <= exact-(size-1)
		inBody = span{startLow, high - 1}
	case step > 0 && condition.Operator == ir.LessOrEqual:
		// high + step <= 2^53
		isWhole = high <= exact-size
		inBody = span{startLow, high}
	case step < 0 && condition.Operator == ir.Greater:
		// low + 1 - size >= -2^53
		isWhole = low >= -exact+(size-1)
		inBody = span{low + 1, startHigh}
	case step < 0 && condition.Operator == ir.GreaterOrEqual:
		// low - size >= -2^53
		isWhole = low >= -exact+size
		inBody = span{low, startHigh}
	default:
		// A counter moving away from its bound, or a comparison that isn't one of these.
		isWhole = false
	}
	if !isWhole {
		return
	}
	program.Locals[counter].Counter = true
	// A loop in the body that reads the counter, as for (let j = i + 1; ...) does, reads a value in
	// this range: the body never writes the counter, and runs only while the condition holds. A body
	// that never runs has a range whose ends cross, which boundRange refuses.
	known.counters[counter] = inBody
}

// boundRange is the least and the most a bound can be, every time it's read, when it's always a whole
// number within 2^53, and false otherwise.
func boundRange(bound ir.Expression, known facts, depth int) (float64, float64, bool) {
	if depth > 8 {
		return 0, 0, false
	}
	var low, high float64
	switch bound := bound.(type) {
	case ir.Length, ir.StringLength, ir.MapSize:
		// An array's length is below 2^32, and a string's and a map's size far below.
		low, high = 0, math.Ldexp(1, 32)
	case ir.NumberConstant:
		low, high = bound.Value, bound.Value
	case ir.Read:
		// The counter of a loop this is in the body of, in the range it holds there.
		if counter, isCounter := known.counters[bound.Local]; isCounter {
			low, high = counter.low, counter.high
			break
		}
		// A variable nothing writes but its declaration: in effect a const, of its declared bound.
		value, isDeclared := known.declared[bound.Local]
		if bound.Of != ir.Number || known.assigned[bound.Local] || !isDeclared || value == nil {
			return 0, 0, false
		}
		return boundRange(value, known, depth+1)
	case ir.Unary:
		operandLow, operandHigh, isWhole := boundRange(bound.Operand, known, depth+1)
		switch {
		case !isWhole:
			return 0, 0, false
		case bound.Operator == ir.Negate:
			low, high = -operandHigh, -operandLow
		case bound.Operator == ir.Plus:
			low, high = operandLow, operandHigh
		default:
			return 0, 0, false
		}
	case ir.Binary:
		leftLow, leftHigh, isLeft := boundRange(bound.Left, known, depth+1)
		rightLow, rightHigh, isRight := boundRange(bound.Right, known, depth+1)
		if !isLeft || !isRight {
			return 0, 0, false
		}
		switch bound.Operator {
		case ir.Add:
			low, high = leftLow+rightLow, leftHigh+rightHigh
		case ir.Subtract:
			low, high = leftLow-rightHigh, leftHigh-rightLow
		case ir.Multiply:
			products := []float64{leftLow * rightLow, leftLow * rightHigh, leftHigh * rightLow, leftHigh * rightHigh}
			low, high = products[0], products[0]
			for _, product := range products[1:] {
				low, high = math.Min(low, product), math.Max(high, product)
			}
		default:
			// Division and remainder needn't give a whole number, and ** is V8's pow, not Go's.
			return 0, 0, false
		}
	default:
		return 0, 0, false
	}
	// Whole numbers within 2^53, at both ends, so every value between, and every sum and product on
	// the way to them, is a whole number a double holds exactly.
	if !whole(low, exact) || !whole(high, exact) || low > high {
		return 0, 0, false
	}
	return low, high, true
}

// neverNegativeZero reports whether an expression boundRange accepts can never be -0: a sum or a
// difference is -0 only when one side is, while a negation or a product of a zero is -0 when its
// signs say so, so those are refused rather than followed.
func neverNegativeZero(expression ir.Expression, known facts, depth int) bool {
	if depth > 8 {
		return false
	}
	switch expression := expression.(type) {
	case ir.Length, ir.StringLength, ir.MapSize:
		return true
	case ir.NumberConstant:
		return !(expression.Value == 0 && math.Signbit(expression.Value))
	case ir.Read:
		// A counter is never -0: it starts as something that isn't, and x + step and x - step are -0
		// only when x is.
		if _, isCounter := known.counters[expression.Local]; isCounter {
			return true
		}
		value, isDeclared := known.declared[expression.Local]
		if expression.Of != ir.Number || known.assigned[expression.Local] || !isDeclared || value == nil {
			return false
		}
		return neverNegativeZero(value, known, depth+1)
	case ir.Unary:
		if expression.Operator == ir.Negate {
			// A constant negated is a constant, and says what it is.
			value, isConstant := constantOf(expression)
			return isConstant && !(value == 0 && math.Signbit(value))
		}
		return expression.Operator == ir.Plus && neverNegativeZero(expression.Operand, known, depth+1)
	case ir.Binary:
		switch expression.Operator {
		case ir.Add, ir.Subtract:
			return neverNegativeZero(expression.Left, known, depth+1) && neverNegativeZero(expression.Right, known, depth+1)
		case ir.Multiply:
			value, isConstant := constantOf(expression)
			return isConstant && !(value == 0 && math.Signbit(value))
		}
	}
	return false
}

// constantOf is a constant expression's value: a number, negated or not, or two of those added,
// subtracted or multiplied, which Go's doubles and C's (built with -ffp-contract=off) round the same.
// ** isn't, since V8's pow, which the runtime carries, can differ from Go's in the last bit.
func constantOf(expression ir.Expression) (float64, bool) {
	switch expression := expression.(type) {
	case ir.NumberConstant:
		return expression.Value, true
	case ir.Unary:
		operand, isConstant := constantOf(expression.Operand)
		switch {
		case !isConstant:
			return 0, false
		case expression.Operator == ir.Negate:
			return -operand, true
		case expression.Operator == ir.Plus:
			return operand, true
		}
	case ir.Binary:
		left, isLeft := constantOf(expression.Left)
		right, isRight := constantOf(expression.Right)
		if !isLeft || !isRight {
			return 0, false
		}
		switch expression.Operator {
		case ir.Add:
			return left + right, true
		case ir.Subtract:
			return left - right, true
		case ir.Multiply:
			return left * right, true
		}
	}
	return 0, false
}

// whole reports whether a value is a whole number of magnitude no larger than limit: not NaN, not
// infinite, not a fraction.
func whole(value float64, limit float64) bool {
	return value == math.Trunc(value) && math.Abs(value) <= limit
}

// stepOf is how far a counter's update moves it: counter = counter + step or counter - step, which
// counter++, counter--, counter += step and counter -= step lower to, for a whole constant step of 1
// or more (negative counting down), and false for any other update.
func stepOf(statement ir.Statement, counter int) (float64, bool) {
	assign, isAssign := statement.(ir.Assign)
	if !isAssign || assign.Local != counter || assign.Checked {
		return 0, false
	}
	sum, isBinary := assign.Value.(ir.Binary)
	if !isBinary || (sum.Operator != ir.Add && sum.Operator != ir.Subtract) {
		return 0, false
	}
	read, isRead := sum.Left.(ir.Read)
	step, isConstant := constantOf(sum.Right)
	if !isRead || read.Local != counter || !isConstant || !whole(step, exact) || step < 1 {
		return 0, false
	}
	if sum.Operator == ir.Subtract {
		step = -step
	}
	return step, true
}

func perIteration(loop ir.Loop, local int) bool {
	for _, each := range loop.PerIteration {
		if each == local {
			return true
		}
	}
	return false
}

func declaredIn(block ir.Block, local int) (ir.Expression, bool) {
	for _, statement := range block.Body {
		if declare, isDeclare := statement.(ir.Declare); isDeclare && declare.Local == local {
			return declare.Value, true
		}
	}
	return nil, false
}

// findDeclared records every local's declared value, however deeply nested.
func findDeclared(statements []ir.Statement, declared map[int]ir.Expression) {
	for _, statement := range statements {
		if declare, isDeclare := statement.(ir.Declare); isDeclare {
			declared[declare.Local] = declare.Value
		}
		eachNested(statement, func(nested []ir.Statement) { findDeclared(nested, declared) })
	}
}

// eachBlock calls visit with every block in statements, however deeply nested.
func eachBlock(statements []ir.Statement, visit func(ir.Block)) {
	for _, statement := range statements {
		if block, isBlock := statement.(ir.Block); isBlock {
			visit(block)
		}
		eachNested(statement, func(nested []ir.Statement) { eachBlock(nested, visit) })
	}
}

// eachNested calls visit with each list of statements a statement holds.
func eachNested(statement ir.Statement, visit func([]ir.Statement)) {
	switch statement := statement.(type) {
	case ir.If:
		visit(statement.Then)
		visit(statement.Else)
	case ir.Loop:
		visit(statement.Body)
		visit(statement.Update)
	case ir.Labeled:
		visit(statement.Body)
	case ir.Block:
		visit(statement.Body)
	case ir.ForOf:
		visit(statement.Body)
	case ir.Switch:
		for _, switchCase := range statement.Cases {
			visit(switchCase.Body)
		}
		visit(statement.Default)
	case ir.Try:
		visit(statement.Body)
		visit(statement.Catch)
		visit(statement.Finally)
	}
}

cycles.go:
package lower

import (
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/fresh"
	"github.com/system-inc/adamic/internal/ir"
)

// The cycle finder (docs/memory.md). Reference counting can't free a cycle, and Adamic has no
// collector, so a cycle must not be able to form. One forms only when a slot (a field, readonly or
// not, since a constructor writes a readonly one, an element of an array that isn't readonly, a map's
// value, a variable a function value captures) is set to something that can reach back to what
// holds the slot. Whether it can is visible in the types, so every such slot is found here, from the
// whole program, and each one is refused unless it's declared Weak<Target>, which doesn't count. A
// map's key and a set's element are slots too, now that they may be objects; neither can be declared
// weak, so one that can reach back is refused with the fix of a ReadonlyMap or ReadonlySet.
//
// Reaching is followed through everything the checker knows a value can hold: an object's fields,
// including the fields of every object type in the program that can be seen as it (a Dog seen as an
// Animal brings its owner along), an array's elements, a map's keys and values, and through a
// function type, the variables captured by every function value in the program that can be seen as
// it, since a type doesn't say what a function captured. A Weak isn't followed: it holds nothing.
//
// It runs after lowering, when the variables each function value captures are known.

// closureRecord is a function value the program makes: its type, and the function lowered for it.
type closureRecord struct {
	proven   *checker.Type
	function int
	node     *ast.Node
}

// cycleNode is one thing reaching is followed through: a type, or the cell of a captured local.
type cycleNode struct {
	proven *checker.Type
	cell   int
}

type cycleFinder struct {
	l *lowering

	// seen is every type the program uses, in the order first met, with where it was met.
	seen  []*checker.Type
	where map[*checker.Type]*ast.Node

	// shapes is every seen object type that isn't an array, a map or a function: what a value seen as
	// some object type may really be. shaped are the literals' own types among them.
	shapes []*checker.Type
	shaped map[*checker.Type]bool

	// writes is every write in the program, judged by the relaxation for fresh writes (fresh.go),
	// worked out the first time a slot needs it.
	writes []fresh.Write

	libraryIterators []libraryIteratorCapture
}

// findCycles refuses the first cycle-capable slot that isn't declared Weak and has a write that isn't
// proven not to close a cycle (fresh.go), or returns nil.
func (l *lowering) findCycles(modules []*ast.SourceFile) error {
	finder := &cycleFinder{l: l, where: map[*checker.Type]*ast.Node{}}
	for _, module := range modules {
		var visit ast.Visitor
		visit = func(node *ast.Node) bool {
			if ast.IsPartOfTypeNode(node) {
				return false
			}
			finder.libraryIteratorMade(node)
			switch {
			case node.Kind == ast.KindObjectLiteralExpression:
				// A literal is what a value may really be, and nothing is written through its own
				// type: it's seen as the type it's written into, or kept in a variable whose type
				// is used where it's declared.
				finder.shape(l.checker.GetTypeAtLocation(node), node)
			case node.Kind == ast.KindArrayLiteralExpression || node.Kind == ast.KindCallExpression || node.Kind == ast.KindNewExpression:
				// A value just made, by a literal, a call or new, is written through only once it's
				// kept somewhere, and where it's kept has a type of its own, used there. Until then
				// it's what a value may really be.
				finder.made(l.checker.GetTypeAtLocation(node), node)
			case ast.IsIdentifier(node) || node.Kind == ast.KindThisKeyword || node.Kind == ast.KindPropertyAccessExpression || node.Kind == ast.KindElementAccessExpression:
				// Where a value is named or reached, and so where a write can go through its type.
				if ast.IsIdentifier(node) && !ast.IsDeclarationName(node) && !ast.IsExpressionNode(node) {
					break
				}
				finder.use(l.checker.GetTypeAtLocation(node), node)
			}
			return node.ForEachChild(visit)
		}
		module.AsNode().ForEachChild(visit)
	}
	// Every instantiation lowering made, Box<Node> inside Maker<Node> included, which the source may
	// never write.
	for _, proven := range l.instantiated {
		finder.use(proven, l.classNodeFor(proven))
	}
	for _, proven := range finder.seen {
		if err := finder.slotsOf(proven); err != nil {
			return err
		}
	}
	for local, declared := range l.result.Locals {
		if !declared.Captured || declared.Global {
			continue
		}
		proven, node := l.localTypes[local], l.localNodes[local]
		if proven == nil || node == nil || finder.weak(proven) {
			continue
		}
		if finder.reaches(proven, cycleNode{cell: local + 1}) && !l.closedFrameInput(local) {
			return &Refused{
				Where: l.program.Where(node),
				What:  "'" + declared.Name + "', a variable a function value captures and can be reached from what it holds, so the function holds the variable and the variable holds the function: a cycle reference counting can't free",
				Fix:   "remove the captured strong back-reference, use a module function declaration that captures nothing, or declare the variable Weak<...> and keep the function somewhere strong (adamic/cycle-capable)",
			}
		}
	}
	l.resolveCountTypes(modules)
	return l.checkLazyViewReads()
}

// made notes the type of a value just made: an object type as a shape, and what anything else is
// made of as used.
func (f *cycleFinder) made(proven *checker.Type, where *ast.Node) {
	switch {
	case proven == nil:
	case proven.Flags()&(checker.TypeFlagsUnion|checker.TypeFlagsIntersection) != 0:
		for _, member := range proven.Types() {
			f.made(member, where)
		}
	case proven.Flags()&checker.TypeFlagsObject == 0 || f.isFunction(proven):
		f.use(proven, where)
	case f.l.checker.IsArrayType(proven) || checker.IsTupleType(proven) || f.l.isLibraryType(proven, "Map", "ReadonlyMap", "Set", "ReadonlySet"):
		for _, argument := range f.l.checker.GetTypeArguments(proven) {
			f.use(argument, where)
		}
	default:
		f.shape(proven, where)
	}
}

// shape notes an object type as one a value may really be, without examining its slots, and uses
// the types of its fields.
func (f *cycleFinder) shape(proven *checker.Type, where *ast.Node) {
	if f.shaped[proven] {
		return
	}
	if f.shaped == nil {
		f.shaped = map[*checker.Type]bool{}
	}
	f.shaped[proven] = true
	f.shapes = append(f.shapes, proven)
	for _, field := range f.fields(proven) {
		f.use(f.l.checker.GetTypeOfSymbol(field), declaredAt(field, where))
	}
}

// use notes a type the program uses, and every type it's made of.
func (f *cycleFinder) use(proven *checker.Type, where *ast.Node) {
	if proven == nil {
		return
	}
	if _, isSeen := f.where[proven]; isSeen || f.template(proven) {
		return
	}
	f.where[proven] = where
	if proven.Flags()&checker.TypeFlagsObject != 0 && proven.ObjectFlags()&checker.ObjectFlagsFreshLiteral != 0 {
		// An object literal's own type, as the literal expression has it. Nothing is written through
		// it: written into a declared type, the object is seen only as that, and kept in a variable
		// of its own, the variable's type is the literal's regular type, which is used where it's
		// declared. It's still what a value may really be.
		f.shape(proven, where)
		return
	}
	f.seen = append(f.seen, proven)
	flags := proven.Flags()
	if flags&(checker.TypeFlagsUnion|checker.TypeFlagsIntersection) != 0 {
		for _, member := range proven.Types() {
			f.use(member, where)
		}
		return
	}
	if flags&checker.TypeFlagsObject == 0 {
		return
	}
	if f.isFunction(proven) {
		return
	}
	if f.l.checker.IsArrayType(proven) || checker.IsTupleType(proven) || f.l.isLibraryType(proven, "Map", "ReadonlyMap", "Set", "ReadonlySet") {
		for _, argument := range f.l.checker.GetTypeArguments(proven) {
			f.use(argument, where)
		}
		return
	}
	if !f.shaped[proven] {
		f.shapes = append(f.shapes, proven)
	}
	for _, field := range f.fields(proven) {
		f.use(f.l.checker.GetTypeOfSymbol(field), declaredAt(field, where))
	}
}

// declaredAt is where a field is declared, to point at what its type is made of, or otherwise.
func declaredAt(field *ast.Symbol, otherwise *ast.Node) *ast.Node {
	if len(field.Declarations) > 0 {
		return field.Declarations[0]
	}
	return otherwise
}

// template reports whether a type is a generic one not yet instantiated, or instantiated with any (a
// class seen from its own declaration): no value has it, and any relates to everything, so it would
// make every slot look cycle-capable.
func (f *cycleFinder) template(proven *checker.Type) bool {
	if proven.Flags()&(checker.TypeFlagsAny|checker.TypeFlagsTypeParameter) != 0 {
		return true
	}
	if proven.Flags()&checker.TypeFlagsObject == 0 || proven.ObjectFlags()&checker.ObjectFlagsReference == 0 {
		return false
	}
	for _, argument := range f.l.checker.GetTypeArguments(proven) {
		if argument.Flags()&(checker.TypeFlagsAny|checker.TypeFlagsTypeParameter) != 0 {
			return true
		}
	}
	return false
}

// fields includes literal methods, which own closures. Class prototype methods hold no instance data.
func (f *cycleFinder) fields(proven *checker.Type) []*ast.Symbol {
	fields := []*ast.Symbol{}
	for _, property := range f.l.checker.GetPropertiesOfType(proven) {
		if (property.Flags&ast.SymbolFlagsMethod == 0 || literalMethod(property)) && !accessorSymbol(property) && !(f.l.isStaticType(proven) && property.Name == "prototype") {
			fields = append(fields, property)
		}
	}
	return fields
}

// isFunction reports whether a type is a function's, or a class's own (typeof Tag, which new calls).
// A class value holds its static fields, readonly in 0.1, and its prototype, which the checker shows
// as a field of the instance type and isn't one a program can set; seen as an object, that prototype
// read as a mutable field reaching back, and every class made with new was refused.
func (f *cycleFinder) isFunction(proven *checker.Type) bool {
	return len(f.l.checker.GetSignaturesOfType(proven, checker.SignatureKindCall)) > 0 || (len(f.l.checker.GetSignaturesOfType(proven, checker.SignatureKindConstruct)) > 0 && (!f.l.isStaticType(proven) || len(f.l.staticGlobals) == 0))
}

// weak reports whether a slot's type is a Weak<Target>, which holds nothing.
func (f *cycleFinder) weak(proven *checker.Type) bool {
	representation, _ := f.l.representation(proven)
	return representation == ir.Weak
}

// slotsOf refuses the first of a type's mutable slots that can close a cycle, unless every write
// into it is proven not to (fresh.go): then it stands, and a refusal names the write that isn't.
func (f *cycleFinder) slotsOf(holder *checker.Type) error {
	l := f.l
	if holder.Flags()&checker.TypeFlagsObject == 0 || f.isFunction(holder) {
		return nil
	}
	name := l.checker.TypeToString(holder)
	switch {
	case l.checker.IsArrayType(holder) || checker.IsTupleType(holder):
		if l.isLibraryType(holder, "ReadonlyArray") || (checker.IsTupleType(holder) && holder.TargetTupleType().IsReadonly()) {
			return nil
		}
		for _, element := range l.checker.GetTypeArguments(holder) {
			if f.weak(element) || !f.reaches(element, cycleNode{proven: holder}) {
				continue
			}
			write := f.unproven(fresh.WriteElement, holder, "")
			if write == nil {
				continue
			}
			target := f.present(element)
			return &Refused{
				Where: l.program.Where(f.where[holder]),
				What:  name + ", an array whose elements can reach back to an array like it: a cycle reference counting can't free, and " + f.writtenAt(write) + " may close one (" + write.Why + ")",
				Fix:   "declare the elements weak, Weak<" + target + ">[] (import type { Weak } from 'adamic'), which don't count and read undefined once what they point to is freed; or make it readonly " + target + "[]; or write into such an array only values this function made, or only into one it made (adamic/cycle-capable)",
			}
		}
	case l.isLibraryType(holder, "ReadonlyMap"), l.isLibraryType(holder, "ReadonlySet"):
	case l.isLibraryType(holder, "Set"):
		arguments := l.checker.GetTypeArguments(holder)
		if len(arguments) == 1 && f.reaches(arguments[0], cycleNode{proven: holder}) {
			if write := f.unproven(fresh.WriteSetElement, holder, ""); write != nil {
				return &Refused{
					Where: l.program.Where(f.where[holder]),
					What:  name + ", a set whose elements can reach back to a set like it: a cycle reference counting can't free, and " + f.writtenAt(write) + " may close one (" + write.Why + ")",
					Fix:   "make it a ReadonlySet, built whole when it's made; or add to such a set only values this function made, or only to one it made (adamic/cycle-capable)",
				}
			}
		}
	case l.isLibraryType(holder, "Map"):
		arguments := l.checker.GetTypeArguments(holder)
		if len(arguments) == 2 && f.reaches(arguments[0], cycleNode{proven: holder}) {
			if write := f.unproven(fresh.WriteMapEntry, holder, ""); write != nil {
				return &Refused{
					Where: l.program.Where(f.where[holder]),
					What:  name + ", a map whose keys can reach back to a map like it: a cycle reference counting can't free, and " + f.writtenAt(write) + " may close one (" + write.Why + ")",
					Fix:   "make it a ReadonlyMap, built whole when it's made; or set in such a map only keys this function made, or only in one it made (adamic/cycle-capable)",
				}
			}
		}
		if len(arguments) == 2 && !f.weak(arguments[1]) && f.reaches(arguments[1], cycleNode{proven: holder}) {
			if write := f.unproven(fresh.WriteMapEntry, holder, ""); write != nil {
				return &Refused{
					Where: l.program.Where(f.where[holder]),
					What:  name + ", a map whose values can reach back to a map like it: a cycle reference counting can't free, and " + f.writtenAt(write) + " may close one (" + write.Why + ")",
					Fix:   "declare the values weak, Map<" + l.checker.TypeToString(arguments[0]) + ", Weak<" + f.present(arguments[1]) + ">> (import type { Weak } from 'adamic'), or make it a ReadonlyMap; or set in such a map only values this function made, or only in one it made (adamic/cycle-capable)",
				}
			}
		}
	default:
		for _, field := range f.fields(holder) {
			// A readonly field is a slot too: a constructor writes it, after this may have been put
			// somewhere (parent.kids.push(this)), and then that write can close a cycle. Every other
			// way a readonly field gets its value (a literal, an initializer) makes the holder with it,
			// and is no write at all.
			readonly := l.checker.IsReadonlySymbol(field)
			proven := l.checker.GetTypeOfSymbol(field)
			if f.weak(proven) || !f.reaches(proven, cycleNode{proven: holder}) {
				continue
			}
			write := f.unproven(fresh.WriteField, holder, field.Name)
			if write == nil {
				continue
			}
			where := f.where[holder]
			if len(field.Declarations) > 0 {
				where = field.Declarations[0]
			}
			target := l.checker.TypeToString(proven)
			kind, orReadonly := "a mutable field", "; or make it readonly"
			if readonly {
				kind, orReadonly = "a readonly field, which its constructor writes,", ""
			}
			return &Refused{
				Where: l.program.Where(where),
				What:  name + "." + l.cycleFieldName(field) + ", " + kind + " of type " + target + ", which can reach back to the " + name + " holding it: a cycle reference counting can't free, and " + f.writtenAt(write) + " may close one (" + write.Why + ")",
				Fix:   "declare it " + l.cycleFieldName(field) + ": Weak<" + f.present(proven) + "> (import type { Weak } from 'adamic'), which doesn't count and reads undefined once what it points to is freed" + orReadonly + "; or write into it only values this function made, or only into what it made (adamic/cycle-capable)",
			}
		}
	}
	return nil
}

// reaches reports whether a value of type from can reach target: a value seen as target's type
// (either way round, since either may be what the value really is), or target's cell.
func (f *cycleFinder) reaches(from *checker.Type, target cycleNode) bool {
	visited := map[cycleNode]bool{}
	queue := []cycleNode{{proven: from}}
	for len(queue) > 0 {
		node := queue[0]
		queue = queue[1:]
		if visited[node] {
			continue
		}
		visited[node] = true
		if node.cell != 0 {
			if node == target {
				return true
			}
			if proven := f.l.localTypes[node.cell-1]; proven != nil {
				queue = append(queue, cycleNode{proven: proven})
			}
			// A this shared by every instantiation of a class held the same way is each of them.
			for _, proven := range f.l.localAlso[node.cell-1] {
				queue = append(queue, cycleNode{proven: proven})
			}
			continue
		}
		proven := node.proven
		flags := proven.Flags()
		if f.weak(proven) || f.template(proven) {
			// A Weak holds nothing.
			continue
		}
		if flags&(checker.TypeFlagsUnion|checker.TypeFlagsIntersection) != 0 {
			for _, member := range proven.Types() {
				queue = append(queue, cycleNode{proven: member})
			}
			continue
		}
		if flags&checker.TypeFlagsObject == 0 {
			continue
		}
		if target.proven != nil && f.related(proven, target.proven) {
			return true
		}
		switch {
		case f.l.isLibraryType(proven, "MapIterator", "SetIterator"):
			queue = append(queue, f.libraryIteratorCaptures(proven)...)
		case f.isFunction(proven):
			// Construct signatures can hide constructor objects behind an interface.
			if len(f.l.checker.GetSignaturesOfType(proven, checker.SignatureKindConstruct)) > 0 {
				for symbol := range f.l.statics {
					actual := f.l.checker.GetTypeOfSymbol(symbol)
					if f.l.checker.IsTypeAssignableTo(actual, proven) {
						queue = append(queue, cycleNode{proven: actual})
					}
				}
			}
			// What a function value holds is what it captured: the cells of every function value the
			// program makes that can be seen as this type.
			for _, closure := range f.l.closureRecords {
				if !f.l.checker.IsTypeAssignableTo(closure.proven, proven) {
					continue
				}
				for _, local := range f.l.result.Functions[closure.function].Environment {
					queue = append(queue, cycleNode{cell: local + 1})
				}
			}
		case f.l.checker.IsArrayType(proven) || checker.IsTupleType(proven) || f.l.isLibraryType(proven, "Map", "ReadonlyMap", "Set", "ReadonlySet"):
			for _, argument := range f.l.checker.GetTypeArguments(proven) {
				queue = append(queue, cycleNode{proven: argument})
			}
		default:
			if f.l.isStaticType(proven) {
				if parent := f.l.staticBase(f.l.staticClass(proven, nil)); parent != nil {
					queue = append(queue, cycleNode{proven: f.l.checker.GetTypeOfSymbol(f.l.symbol(parent.Name()))})
				}
			}
			for _, accessor := range f.l.accessorCaptures {
				if f.l.checker.IsTypeAssignableTo(accessor.holder, proven) {
					for _, local := range f.l.result.Functions[accessor.function].Environment {
						queue = append(queue, cycleNode{cell: local + 1})
					}
				}
			}
			for _, field := range f.fields(proven) {
				queue = append(queue, cycleNode{proven: f.l.checker.GetTypeOfSymbol(field)})
			}
			// A value seen as this type may be any object type the program has that can be seen as
			// it, with fields this type doesn't show.
			for _, shape := range f.shapes {
				if shape != proven && f.l.checker.IsTypeAssignableTo(shape, proven) {
					queue = append(queue, cycleNode{proven: shape})
				}
			}
		}
	}
	return false
}

// present is a type as written without undefined, as Weak<Target> wants its Target.
func (f *cycleFinder) present(proven *checker.Type) string {
	if proven.Flags()&checker.TypeFlagsUnion == 0 {
		return f.l.checker.TypeToString(proven)
	}
	members := []string{}
	for _, member := range proven.Types() {
		if member.Flags()&checker.TypeFlagsUndefined == 0 {
			members = append(members, f.l.checker.TypeToString(member))
		}
	}
	return strings.Join(members, " | ")
}

// related reports whether one value could be seen as both types: one is assignable to the other.
func (f *cycleFinder) related(one *checker.Type, other *checker.Type) bool {
	if one == other {
		return true
	}
	if f.isFunction(one) || f.isFunction(other) {
		return false
	}
	return f.l.checker.IsTypeAssignableTo(one, other) || f.l.checker.IsTypeAssignableTo(other, one)
}

func literalMethod(property *ast.Symbol) bool {
	for _, declaration := range property.Declarations {
		if declaration.Kind == ast.KindMethodDeclaration && declaration.Parent.Kind == ast.KindObjectLiteralExpression {
			return true
		}
	}
	return false
}

