// Functions and declarations moved unchanged from lower.go.
package lower

import (
	"fmt"
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"strings"
)

// NotYet is a construct stage 0 can't lower yet, with where it is.
type NotYet struct {
	Where string
	What  string
}

func (n *NotYet) Error() string {
	return fmt.Sprintf("%s: stage 0 can't lower %s yet", n.Where, n.What)
}

// Refused is something Adamic 0.1 doesn't allow at all (docs/0.1.md), as opposed to something stage 0
// hasn't learned yet. The difference is a promise, so the message keeps them apart.
type Refused struct {
	Where string
	What  string
	Fix   string
}

func (r *Refused) Error() string {
	return fmt.Sprintf("%s: Adamic 0.1 refuses %s; %s", r.Where, r.What, r.Fix)
}

func (l *lowering) notYet(node *ast.Node, what string) error {
	return &NotYet{Where: l.program.Where(node), What: what}
}

// describe names a node's kind for a person: "a VariableStatement", "an ImportDeclaration".
func describe(node *ast.Node) string {
	name := strings.TrimPrefix(node.Kind.String(), "Kind")
	if strings.ContainsAny(name[:1], "AEIOU") {
		return "an " + name
	}
	return "a " + name
}

element_access_fields.go:
package lower

import (
	"math"
	"reflect"
	"strconv"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
)

// A finite key reads the same own data slots as named access. Ordinary IR calls
// hold the receiver before evaluating the key, including a key that replaces it.
func (l *lowering) finiteElementRead(node *ast.Node, object ir.Expression) (ir.Expression, error) {
	access := node.AsElementAccessExpression()
	receiver := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(access.Expression))
	keyType := l.checker.GetTypeAtLocation(access.ArgumentExpression)
	members := []*checker.Type{keyType}
	if keyType.Flags()&checker.TypeFlagsUnion != 0 {
		members = keyType.Types()
	}
	names := []string{}
	tests := []ir.Expression{}
	fields := []*ast.Symbol{}
	for _, member := range members {
		var name string
		var test ir.Expression
		switch {
		case member.Flags()&checker.TypeFlagsStringLiteral != 0:
			name = member.AsLiteralType().Value().(string)
			test = ir.StringConstant{Index: l.constant(name)}
		case member.Flags()&checker.TypeFlagsNumberLiteral != 0:
			number := reflect.ValueOf(member.AsLiteralType().Value()).Float()
			if math.Trunc(number) != number || math.Abs(number) > 9007199254740991 {
				return nil, l.notYet(node, "a computed numeric key outside exact integer names")
			}
			if number == 0 {
				number = 0
			}
			name = strconv.FormatFloat(number, 'f', -1, 64)
			test = ir.NumberConstant{Value: number}
		default:
			return nil, l.notYet(node, describe(node))
		}
		field := l.checker.GetPropertyOfType(receiver, name)
		if field == nil || accessorSymbol(field) || (l.accessorNames[name] && field.Flags&ast.SymbolFlagsOptional != 0) || name == "__proto__" {
			return nil, l.notYet(node, "a computed key without an own data field")
		}
		for _, declaration := range field.Declarations {
			if load.IsLibrary(ast.GetSourceFileOfNode(declaration)) || declaration.Kind == ast.KindMethodDeclaration {
				return nil, l.notYet(node, "a computed prototype or method read")
			}
		}
		stored, known := l.representation(l.checker.GetTypeOfSymbol(field))
		if !known || censusFieldSlotless(stored) || stored == ir.Weak || l.includesNull(l.checker.GetTypeOfSymbol(field)) {
			return nil, l.notYet(node, "a computed field with an unsupported representation")
		}
		if receiver.Flags()&checker.TypeFlagsUnion != 0 {
			for _, alternative := range receiver.Types() {
				own := l.checker.GetPropertyOfType(alternative, name)
				if own == nil {
					return nil, l.notYet(node, "a computed field absent from a receiver alternative")
				}
				held, known := l.representation(l.checker.GetTypeOfSymbol(own))
				if !known || held != stored {
					return nil, l.notYet(node, "a computed field stored differently across receiver alternatives")
				}
			}
		}
		names = append(names, name)
		tests = append(tests, test)
		fields = append(fields, field)
	}
	if len(names) == 0 {
		return nil, l.notYet(node, "a computed key without finite alternatives")
	}
	result, err := l.typeOf(node)
	if err != nil {
		return nil, err
	}
	key, err := l.expression(access.ArgumentExpression)
	if err != nil {
		return nil, err
	}
	b := l.libraryArrayBuilder([]ir.Expression{object, key})
	heldObject, heldKey := b.read(b.parameters[0]), b.read(b.parameters[1])
	var read ir.Expression
	for index, name := range names {
		stored, _ := l.representation(l.checker.GetTypeOfSymbol(fields[index]))
		read = ir.Property{Object: heldObject, Name: name, Of: stored, Absent: fields[index].Flags&ast.SymbolFlagsOptional != 0}
		read = fit(read, result)
		if read.Type() != result {
			return nil, l.notYet(node, "a computed field with differently represented alternatives")
		}
		b.body = append(b.body, ir.If{Condition: ir.Binary{Operator: ir.Equal, Left: heldKey, Right: tests[index]}, Then: []ir.Statement{ir.Return{Value: read}}})
	}
	b.body = append(b.body, ir.Panic{Message: ir.StringConstant{Index: l.constant("computed object key outside its proven finite union")}})
	value := b.finish("element_access_fields", read)
	if result.IsReference() && result != ir.Union && !l.includesUndefined(l.checker.GetTypeAtLocation(node)) && !l.acceptsUndefined(node) {
		for _, field := range fields {
			if l.includesUndefined(l.checker.GetTypeOfSymbol(field)) {
				return l.computedFieldPresence(node, value), nil
			}
		}
	}
	return l.defined(node, value), nil
}

// Indexed narrowing needs the declared field types: a computed access does not
// necessarily have the symbol that the named-read presence helper uses.
func (l *lowering) computedFieldPresence(node *ast.Node, value ir.Expression) ir.Expression {
	message := "undefined where the checker narrowed it away: a call since the narrowing put it back"
	at := node
	for at.Parent != nil && at.Parent.Kind == ast.KindParenthesizedExpression {
		at = at.Parent
	}
	if parent := at.Parent; parent != nil && parent.Kind == ast.KindPropertyAccessExpression && parent.AsPropertyAccessExpression().Expression == at {
		if written := parent.Parent; written != nil && written.Kind == ast.KindBinaryExpression && written.AsBinaryExpression().Left == parent && written.AsBinaryExpression().OperatorToken.Kind == ast.KindEqualsToken {
			return value
		}
		message = "TypeError: Cannot read properties of undefined (reading '" + parent.Name().Text() + "')"
	}
	if parent := at.Parent; parent != nil && parent.Kind == ast.KindElementAccessExpression && parent.AsElementAccessExpression().Expression == at {
		key := ast.SkipParentheses(parent.AsElementAccessExpression().ArgumentExpression)
		if key.Kind == ast.KindNumericLiteral || key.Kind == ast.KindStringLiteral {
			message = "TypeError: Cannot read properties of undefined (reading '" + key.Text() + "')"
		}
	}
	return ir.Defined{Value: value, Message: message}
}

element_access_tuples.go:
package lower

import (
	"strconv"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// A fixed tuple is already held as named slots. Numeric dispatch preserves that
// layout, and a shorter member of a tuple union has no slot past its own end.
func (l *lowering) indexedTupleRead(node *ast.Node, object ir.Expression) (ir.Expression, bool, error) {
	access := node.AsElementAccessExpression()
	receiver := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(access.Expression))
	members := []*checker.Type{receiver}
	if receiver.Flags()&checker.TypeFlagsUnion != 0 {
		members = receiver.Types()
	}
	for _, member := range members {
		if !checker.IsTupleType(member) {
			return nil, false, nil
		}
	}
	if access.QuestionDotToken != nil {
		return nil, false, nil
	}
	if checker.IsTupleType(receiver) && ast.SkipParentheses(access.ArgumentExpression).Kind == ast.KindNumericLiteral {
		return nil, false, nil
	}
	stored := []ir.Type{}
	for _, member := range members {
		if checker.TupleType_combinedFlags(member.TargetTupleType())&checker.ElementFlagsVariable != 0 {
			return nil, true, l.notYet(node, "numeric indexing of a tuple with variable elements")
		}
		elements := l.checker.GetTypeArguments(member)
		for index, element := range elements {
			of, known := l.representation(element)
			if !known || censusFieldSlotless(of) || of == ir.Weak || l.includesNull(element) {
				return nil, true, l.notYet(node, "numeric indexing of an unrepresented tuple element")
			}
			if index == len(stored) {
				stored = append(stored, of)
			} else if stored[index] != of {
				return nil, true, l.notYet(node, "a tuple union storing an index in different representations")
			}
		}
	}
	result, err := l.typeOf(node)
	if err != nil {
		return nil, true, err
	}
	// The unmatched numeric keys (including negative, fractional and NaN) read
	// undefined. Do not manufacture a value when the result cannot hold it.
	missing := fit(ir.Undefined{}, result)
	if missing.Type() != result || (!result.IsReference() && !result.IsMaybe()) {
		return nil, true, l.notYet(node, "a dynamic tuple read without an undefined representation")
	}
	key, err := l.expression(access.ArgumentExpression)
	if err != nil {
		return nil, true, err
	}
	if key.Type() != ir.Number {
		return nil, true, l.notYet(node, "a tuple index that is not a number")
	}
	b := l.libraryArrayBuilder([]ir.Expression{object, key})
	heldObject, heldKey := b.read(b.parameters[0]), b.read(b.parameters[1])
	for index, of := range stored {
		absent := false
		for _, member := range members {
			if index >= len(l.checker.GetTypeArguments(member)) {
				absent = true
			}
		}
		if absent {
			of = ir.Maybe(of)
		}
		read := fit(ir.Property{Object: heldObject, Name: strconv.Itoa(index), Of: of, Absent: absent}, result)
		if read.Type() != result {
			return nil, true, l.notYet(node, "a dynamic tuple result with an incompatible element representation")
		}
		b.body = append(b.body, ir.If{Condition: ir.Binary{Operator: ir.Equal, Left: heldKey, Right: ir.NumberConstant{Value: float64(index)}}, Then: []ir.Statement{ir.Return{Value: read}}})
	}
	return b.finish("element_access_tuple", missing), true, nil
}

empty_literal.go:
package lower

import "github.com/microsoft/TypeScript/tsc/shim/checker"

// literalArrayElement finds the element destination of a fresh empty literal.
// A union contributes only array members: do not invent slots for a mixed
// array/object context, or turn a tuple into an array.
func (l *lowering) literalArrayElement(proven *checker.Type) *checker.Type {
	if proven == nil {
		return nil
	}
	proven = l.concrete(proven)
	if l.checker.IsArrayType(proven) {
		return l.checker.GetElementTypeOfArrayType(proven)
	}
	if proven.Flags()&checker.TypeFlagsUnion == 0 {
		return nil
	}
	elements := []*checker.Type{}
	for _, member := range proven.Types() {
		if member.Flags()&checker.TypeFlagsUndefined != 0 {
			continue
		}
		element := l.literalArrayElement(member)
		if element == nil {
			return nil
		}
		elements = append(elements, element)
	}
	if len(elements) == 0 {
		return nil
	}
	// [] satisfies every array member. Choose a concrete member layout, not
	// a union element layout: array unions do not mean arrays of unions.
	for _, element := range elements {
		if held, known := l.kept(element); known && !slotless(held) {
			return element
		}
	}
	return nil
}

entries_provenance.go:
package lower

import (
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
)

// A binding freezes its origin only when no write in the closed program replaces it.
// Indexed shape mutations select record storage and invalidate this allocation proof.
// Follow imported symbols and annotated aliases, but do not infer origins for parameters or calls.
func (l *lowering) enumerationProven(node *ast.Node, element *checker.Type, depth int) bool {
	if node == nil || depth > 32 {
		return false
	}
	node = ast.SkipParentheses(node)
	if l.enumObject(node) != nil {
		return true
	}
	if node.Kind == ast.KindAsExpression && ast.IsConstTypeReference(node.AsAsExpression().Type) {
		return l.enumerationProven(node.AsAsExpression().Expression, element, depth+1)
	}
	if node.Kind == ast.KindObjectLiteralExpression {
		if l.entriesRecordLiteral(node) {
			return false
		}
		for _, property := range node.AsObjectLiteralExpression().Properties.Nodes {
			if property.Kind != ast.KindPropertyAssignment && property.Kind != ast.KindShorthandPropertyAssignment {
				return false
			}
			if property.Kind == ast.KindPropertyAssignment && l.uninitializedInitializer(property.AsPropertyAssignment().Initializer) {
				return false
			}
			name, known := l.methodName(property)
			if !known || name == "__proto__" {
				return false
			}
		}
		for _, field := range l.checker.GetPropertiesOfType(l.checker.GetTypeAtLocation(node)) {
			if field.Flags&ast.SymbolFlagsOptional != 0 || (!l.enumAssignable(l.checker.GetTypeOfSymbol(field), element) || !l.checker.IsTypeAssignableTo(l.checker.GetTypeOfSymbol(field), element)) {
				return false
			}
		}
		return true
	}
	if !ast.IsIdentifier(node) {
		return false
	}
	symbol := l.symbol(node)
	if symbol == nil || len(symbol.Declarations) != 1 {
		return false
	}
	declaration := symbol.Declarations[0]
	if declaration.Kind != ast.KindVariableDeclaration {
		return false
	}
	if l.enumerationBindingWritten(symbol) {
		return false
	}
	return l.enumerationProven(declaration.AsVariableDeclaration().Initializer, element, depth+1)
}

func (l *lowering) enumerationBindingWritten(symbol *ast.Symbol) bool {
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return true
	}
	written := false
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		var target *ast.Node
		if node.Kind == ast.KindBinaryExpression && ast.IsAssignmentOperator(node.AsBinaryExpression().OperatorToken.Kind) {
			target = node.AsBinaryExpression().Left
		}
		if node.Kind == ast.KindPrefixUnaryExpression {
			target = node.AsPrefixUnaryExpression().Operand
		}
		if node.Kind == ast.KindPostfixUnaryExpression {
			target = node.AsPostfixUnaryExpression().Operand
		}
		if node.Kind == ast.KindForOfStatement {
			target = node.AsForInOrOfStatement().Initializer
		}
		if target != nil {
			var inspect ast.Visitor
			inspect = func(part *ast.Node) bool {
				if ast.IsIdentifier(part) && l.symbol(part) == symbol {
					written = true
				}
				return part.ForEachChild(inspect)
			}
			inspect(target)
		}
		return node.ForEachChild(visit)
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return written
}

// Native reflection currently represents own data descriptors only. Do not let an
// erased accessor origin become a slot read; accessor and symbol layouts are refused.
func (l *lowering) enumerationDescriptors(where *ast.Node, checked bool) error {
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return err
	}
	var failure error
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if node.Kind == ast.KindGetAccessor || node.Kind == ast.KindSetAccessor {
			failure = &Refused{Where: l.program.Where(where), What: "Object enumeration with getter or accessor descriptors", Fix: "use own data properties for this first reflection implementation"}
		}
		if node.Kind == ast.KindObjectLiteralExpression {
			for _, property := range node.AsObjectLiteralExpression().Properties.Nodes {
				if property.Name() != nil && property.Name().Kind == ast.KindComputedPropertyName && l.checker.GetTypeAtLocation(property.Name().AsComputedPropertyName().Expression).Flags()&checker.TypeFlagsESSymbolLike != 0 {
					failure = &Refused{Where: l.program.Where(where), What: "Object enumeration with symbol keys", Fix: "use string-keyed own data properties for this first reflection implementation"}
				}
				name, known := l.methodName(property)
				if known && (strings.ContainsRune(name, 0) || strings.HasPrefix(name, "#") || name == iteratorSlot) {
					failure = l.notYet(where, "Object enumeration of a literal with reserved or symbol key storage")
				}
				if property.Kind == ast.KindSpreadAssignment && l.includesUndefined(l.checker.GetTypeAtLocation(property.AsSpreadAssignment().Expression)) {
					failure = l.notYet(where, "Object enumeration of a nullable spread with synthetic absent slots")
				}
			}
		}
		return node.ForEachChild(visit)
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return failure
}

entries_records.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"strings"
)

// Fold only effect-free strings; a runtime computed key is not a shape proof.
func constantStringKey(node *ast.Node) (string, bool) {
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindStringLiteral {
		return node.Text(), true
	}
	if node.Kind == ast.KindBinaryExpression && node.AsBinaryExpression().OperatorToken.Kind == ast.KindPlusToken {
		left, a := constantStringKey(node.AsBinaryExpression().Left)
		right, b := constantStringKey(node.AsBinaryExpression().Right)
		return left + right, a && b
	}
	return "", false
}

func (l *lowering) enumerationInModule(module *ast.SourceFile) bool {
	return l.enumerationMethodsInModule(module, false)
}

func (l *lowering) enumerationMethodsInModule(module *ast.SourceFile, valuesOnly bool) bool {
	found := false
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if node.Kind == ast.KindCallExpression {
			callee := ast.SkipParentheses(node.AsCallExpression().Expression)
			if callee.Kind == ast.KindPropertyAccessExpression && l.isLibraryGlobal(callee.AsPropertyAccessExpression().Expression, "Object") {
				name := callee.Name().Text()
				found = found || name == "entries" || name == "values" || !valuesOnly && name == "keys"
			}
		}
		return node.ForEachChild(visit)
	}
	module.AsNode().ForEachChild(visit)
	return found
}

// The declaration alone does not promise a runtime dictionary. Ordinary closed
// literal origins stay fixed; indexed writes below explicitly select record storage.
func (l *lowering) enumerationIndexSignature(node *ast.Node) bool {
	if !l.enumerationInModule(ast.GetSourceFileOfNode(node).AsSourceFile()) {
		return false
	}
	signature := node.AsIndexSignatureDeclaration()
	return len(signature.Parameters.Nodes) == 1 && signature.Parameters.Nodes[0].AsParameterDeclaration().Type != nil && signature.Parameters.Nodes[0].AsParameterDeclaration().Type.Kind == ast.KindStringKeyword
}

// Reassigned origins are never guessed. Const aliases can still mutate their
// object: those writes select record storage and invalidate unchecked enumeration.
func (l *lowering) entriesLiteralOrigin(node *ast.Node, depth int) *ast.Node {
	if node == nil || depth > 32 {
		return nil
	}
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindObjectLiteralExpression {
		return node
	}
	if node.Kind == ast.KindAsExpression && ast.IsConstTypeReference(node.AsAsExpression().Type) {
		return l.entriesLiteralOrigin(node.AsAsExpression().Expression, depth+1)
	}
	if !ast.IsIdentifier(node) {
		return nil
	}
	symbol := l.symbol(node)
	if symbol == nil || len(symbol.Declarations) != 1 {
		return nil
	}
	declaration := symbol.Declarations[0]
	if declaration.Kind != ast.KindVariableDeclaration || declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
		return nil
	}
	return l.entriesLiteralOrigin(declaration.AsVariableDeclaration().Initializer, depth+1)
}

func (l *lowering) entriesRecordLiteral(literal *ast.Node) bool {
	parent := literal.Parent
	for parent != nil && (parent.Kind == ast.KindAsExpression || parent.Kind == ast.KindParenthesizedExpression) {
		parent = parent.Parent
	}
	if parent == nil || parent.Kind != ast.KindVariableDeclaration || parent.Parent.Flags&ast.NodeFlagsConst == 0 {
		return false
	}
	contextual := l.checker.GetContextualType(literal, checker.ContextFlagsNone)
	indexed := contextual != nil && len(l.checker.GetIndexInfosOfType(contextual)) != 0
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return false
	}
	written := false
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if node.Kind == ast.KindBinaryExpression && ast.IsAssignmentOperator(node.AsBinaryExpression().OperatorToken.Kind) {
			target := ast.SkipParentheses(node.AsBinaryExpression().Left)
			var receiver *ast.Node
			if target.Kind == ast.KindElementAccessExpression {
				receiver = target.AsElementAccessExpression().Expression
			}
			if target.Kind == ast.KindPropertyAccessExpression {
				receiver = target.AsPropertyAccessExpression().Expression
			}
			if receiver != nil && l.entriesLiteralOrigin(receiver, 0) == literal && (indexed || l.entriesStringIndexed(receiver)) {
				written = true
			}
		}
		return node.ForEachChild(visit)
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return written
}

func (l *lowering) entriesRecordWrite(target, valueNode *ast.Node) ([]ir.Statement, bool, error) {
	var receiver, keyNode *ast.Node
	key, known := "", false
	if target.Kind == ast.KindElementAccessExpression {
		access := target.AsElementAccessExpression()
		receiver, keyNode = access.Expression, access.ArgumentExpression
		key, known = constantStringKey(keyNode)
	} else {
		receiver = target.AsPropertyAccessExpression().Expression
		key, known = target.Name().Text(), true
	}
	origin := l.entriesLiteralOrigin(receiver, 0)
	if origin == nil || !l.entriesRecordLiteral(origin) {
		return nil, false, nil
	}
	if !known || key == "__proto__" || strings.ContainsRune(key, 0) || strings.HasPrefix(key, "#") || key == iteratorSlot {
		return nil, true, l.notYet(target, "an indexed record write without a plain constant data key")
	}
	object, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	value, err := l.expression(valueNode)
	if err != nil {
		return nil, true, err
	}
	if value.Type() != ir.Number && value.Type() != ir.String && value.Type() != ir.Boolean && value.Type() != ir.Union {
		return nil, true, l.notYet(target, "a record write outside scalar storage")
	}
	return []ir.Statement{ir.SetProperty{Object: object, Name: key, Value: fit(value, ir.Union), Define: true, Record: true, Site: l.writeSite(receiver)}}, true, nil
}

func (l *lowering) enumerationDescriptorRefusal(node *ast.Node) error {
	if node.Kind != ast.KindGetAccessor && node.Kind != ast.KindSetAccessor && node.Kind != ast.KindComputedPropertyName {
		return nil
	}
	if !l.enumerationMethodsInModule(ast.GetSourceFileOfNode(node).AsSourceFile(), true) {
		return nil
	}
	if node.Kind == ast.KindComputedPropertyName {
		if l.checker.GetTypeAtLocation(node.AsComputedPropertyName().Expression).Flags()&checker.TypeFlagsESSymbolLike == 0 {
			return nil
		}
		return &Refused{Where: l.program.Where(node), What: "Object enumeration with symbol keys", Fix: "use own string-keyed data properties"}
	}
	return &Refused{Where: l.program.Where(node), What: "Object enumeration with a getter or accessor", Fix: "use own data properties"}
}

func (l *lowering) entriesProgramHasRecords() bool {
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return true
	}
	found := false
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if node.Kind == ast.KindObjectLiteralExpression && l.entriesRecordLiteral(node) {
			found = true
		}
		return node.ForEachChild(visit)
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return found
}

func (l *lowering) entriesStringIndexed(receiver *ast.Node) bool {
	for _, info := range l.checker.GetIndexInfosOfType(l.checker.GetTypeAtLocation(receiver)) {
		if info.KeyType().Flags()&checker.TypeFlagsStringLike != 0 {
			return true
		}
	}
	return false
}

// A parameter or replaced binding cannot establish which allocation must grow.
// Keep those writes outside this first record-origin implementation.
func (l *lowering) enumerationIndexedWriteRefusal(node *ast.Node) error {
	if node.Kind != ast.KindBinaryExpression || !ast.IsAssignmentOperator(node.AsBinaryExpression().OperatorToken.Kind) {
		return nil
	}
	target := ast.SkipParentheses(node.AsBinaryExpression().Left)
	var receiver *ast.Node
	if target.Kind == ast.KindPropertyAccessExpression {
		receiver = target.AsPropertyAccessExpression().Expression
	}
	if target.Kind == ast.KindElementAccessExpression {
		receiver = target.AsElementAccessExpression().Expression
	}
	if receiver == nil || !l.entriesStringIndexed(receiver) || l.entriesLiteralOrigin(receiver, 0) != nil {
		return nil
	}
	return l.notYet(node, "an indexed mutation without a closed const literal origin")
}

enum_flags.go:
package lower

import (
	"math"
	"reflect"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
)

// Shape is the opt-in. Numerically identical implicit or arithmetic initializers stay closed.
func (l *lowering) flagEnum(symbol *ast.Symbol) bool {
	if symbol == nil || symbol.ValueDeclaration == nil || symbol.ValueDeclaration.Kind != ast.KindEnumDeclaration {
		return false
	}
	declaration := symbol.ValueDeclaration
	members := declaration.AsEnumDeclaration().Members.Nodes
	if len(members) == 0 {
		return false
	}
	for _, member := range members {
		initializer := member.AsEnumMember().Initializer
		if initializer == nil || !l.flagInitializer(initializer, declaration, false) {
			return false
		}
		constant := l.checker.GetConstantValue(member)
		if constant == nil || reflect.TypeOf(constant).Kind() != reflect.Float64 {
			return false
		}
		value := reflect.ValueOf(constant).Float()
		if value < 0 || value > math.MaxInt32 || value != math.Trunc(value) {
			return false
		}
	}
	return true
}

func (l *lowering) flagLiteral(node *ast.Node, value float64) bool {
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindNumericLiteral {
		return false
	}
	literal := l.checker.GetTypeAtLocation(node)
	if literal.Flags()&checker.TypeFlagsNumberLiteral == 0 {
		return false
	}
	number := reflect.ValueOf(literal.AsLiteralType().Value())
	return number.Kind() == reflect.Float64 && number.Float() == value
}

func (l *lowering) flagInitializer(node, declaration *ast.Node, memberAllowed bool) bool {
	node = ast.SkipParentheses(node)
	if member := l.enumMember(node); member != nil {
		return member.Parent == declaration
	}
	if l.flagLiteral(node, 0) && !memberAllowed {
		return true
	}
	if node.Kind != ast.KindBinaryExpression {
		return false
	}
	binary := node.AsBinaryExpression()
	switch binary.OperatorToken.Kind {
	case ast.KindLessThanLessThanToken:
		if memberAllowed || !l.flagLiteral(binary.Left, 1) {
			return false
		}
		for bit := 0; bit <= 30; bit++ {
			if l.flagLiteral(binary.Right, float64(bit)) {
				return true
			}
		}
	case ast.KindBarToken:
		return l.flagInitializer(binary.Left, declaration, true) && l.flagInitializer(binary.Right, declaration, true)
	}
	return false
}

// A member slot still denotes that member. Only the complete enum type accepts combinations.
func (l *lowering) flagTarget(proven *checker.Type) *ast.Symbol {
	if proven == nil {
		return nil
	}
	proven = l.checker.GetNonNullableType(proven)
	if proven == nil || proven.Flags()&checker.TypeFlagsEnumLike == 0 {
		return nil
	}
	symbol := l.enumIdentity(proven)
	if !l.flagEnum(symbol) || proven != l.checker.GetTypeAtLocation(symbol.ValueDeclaration.Name()) {
		return nil
	}
	return symbol
}

// No runtime validation is needed: AND cannot add bits, while OR and XOR need both proofs.
// Complement, arithmetic and shifts never gain a proof, even if their current value fits.
func (l *lowering) flagDomain(node *ast.Node, target *ast.Symbol) bool {
	return l.flagDomainSeen(node, target, map[*ast.Node]bool{})
}

func (l *lowering) flagDomainSeen(node *ast.Node, target *ast.Symbol, seen map[*ast.Node]bool) bool {
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindBinaryExpression {
		binary := node.AsBinaryExpression()
		switch binary.OperatorToken.Kind {
		case ast.KindAmpersandToken:
			return l.flagDomainSeen(binary.Left, target, seen) || l.flagDomainSeen(binary.Right, target, seen)
		case ast.KindBarToken:
			return l.flagDomainSeen(binary.Left, target, seen) && l.flagDomainSeen(binary.Right, target, seen)
		case ast.KindCaretToken:
			return l.flagDomainSeen(binary.Left, target, seen) && l.flagDomainSeen(binary.Right, target, seen)
		default:
			proven := l.checker.GetTypeAtLocation(node)
			return proven.Flags()&checker.TypeFlagsEnumLike != 0 && l.enumIdentity(proven) == target
		}
	}
	if node.Kind == ast.KindPrefixUnaryExpression || node.Kind == ast.KindPostfixUnaryExpression {
		return false
	}
	if node.Kind == ast.KindConditionalExpression {
		conditional := node.AsConditionalExpression()
		return l.flagDomainSeen(conditional.WhenTrue, target, seen) && l.flagDomainSeen(conditional.WhenFalse, target, seen)
	}
	proven := l.checker.GetTypeAtLocation(node)
	if proven.Flags()&checker.TypeFlagsEnumLike == 0 && ast.IsIdentifier(node) {
		symbol := l.flagValueSymbol(node)
		if symbol != nil && symbol.ValueDeclaration != nil {
			declaration := symbol.ValueDeclaration
			if declaration.Kind == ast.KindVariableDeclaration && declaration.Parent.Flags&ast.NodeFlagsConst != 0 && !seen[declaration] {
				// A fresh inline iterable of primitives has no alias that can replace an element.
				// The const binding receives only those proven values, even if tsc infers number[].
				if loop := declaration.Parent.Parent; loop != nil && loop.Kind == ast.KindForOfStatement {
					iterable := ast.SkipParentheses(loop.AsForInOrOfStatement().Expression)
					if iterable.Kind == ast.KindArrayLiteralExpression {
						seen[declaration] = true
						defer delete(seen, declaration)
						for _, element := range iterable.AsArrayLiteralExpression().Elements.Nodes {
							if !l.flagDomainSeen(element, target, seen) {
								return false
							}
						}
						return true
					}
				}
				if initializer := declaration.AsVariableDeclaration().Initializer; initializer != nil {
					seen[declaration] = true
					result := l.flagDomainSeen(initializer, target, seen)
					delete(seen, declaration)
					return result
				}
			}
		}
	}
	return proven.Flags()&checker.TypeFlagsEnumLike != 0 && l.enumIdentity(proven) == target
}

func (l *lowering) flagWriteRefusal(node *ast.Node, target *checker.Type) error {
	return &Refused{Where: l.program.Where(node), What: "a number outside the proven flag domain assigned to " + l.checker.TypeToString(target) + "; its domain is a closed union of non-negative int32 bit subsets", Fix: "use this enum's members with | or ^ on two proven flags, or & with one proven flag; keep complement, arithmetic and shifts in a number (adamic/enum-flags)"}
}

// A literal shift through the sign bit is explicitly refused rather than silently opting out.
func (l *lowering) flagInitializerBound(node *ast.Node) error {
	if node == nil {
		return nil
	}
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindBinaryExpression {
		return nil
	}
	binary := node.AsBinaryExpression()
	if binary.OperatorToken.Kind == ast.KindBarToken {
		if err := l.flagInitializerBound(binary.Left); err != nil {
			return err
		}
		return l.flagInitializerBound(binary.Right)
	}
	if binary.OperatorToken.Kind == ast.KindLessThanLessThanToken && l.flagLiteral(binary.Left, 1) {
		right := ast.SkipParentheses(binary.Right)
		if right.Kind == ast.KindNumericLiteral {
			literal := l.checker.GetTypeAtLocation(right)
			value := reflect.ValueOf(literal.AsLiteralType().Value()).Float()
			if value < 0 || value > 30 || value != math.Trunc(value) {
				return &Refused{Where: l.program.Where(node), What: "a flag initializer outside the non-negative int32 bound", Fix: "use 1 << n with a literal n from 0 to 30 (adamic/enum-flags)"}
			}
		}
	}
	return nil
}

func (l *lowering) flagUpdate(node, updated *ast.Node) bool {
	if node.Kind != ast.KindBinaryExpression {
		return false
	}
	symbol := l.symbol(updated)
	if symbol == nil {
		return false
	}
	target := l.flagTarget(l.checker.GetTypeOfSymbol(symbol))
	if target == nil {
		return false
	}
	binary := node.AsBinaryExpression()
	switch binary.OperatorToken.Kind {
	case ast.KindAmpersandEqualsToken:
		return true
	case ast.KindBarEqualsToken, ast.KindCaretEqualsToken:
		return l.flagDomain(binary.Right, target)
	}
	return false
}

// Excluding declared members does not prove a flag is one remaining member: it may be a mask.
func (l *lowering) flagMemberWidened(node *ast.Node, contextual *checker.Type) *widening {
	target := l.checker.GetNonNullableType(contextual)
	if target.Flags()&checker.TypeFlagsEnumLike == 0 || !l.flagEnum(l.enumIdentity(target)) || l.flagTarget(target) != nil {
		return nil
	}
	if symbol := l.flagValueSymbol(node); symbol != nil {
		declared := l.checker.GetTypeOfSymbol(symbol)
		if l.flagTarget(declared) != nil {
			return &widening{source: declared, target: target, enum: true}
		}
	}
	return nil
}

// Shorthand names denote a field symbol at the syntax node, but the proof belongs to its value.
func (l *lowering) flagValueSymbol(node *ast.Node) *ast.Symbol {
	if node.Parent != nil && node.Parent.Kind == ast.KindShorthandPropertyAssignment {
		symbol := l.checker.GetShorthandAssignmentValueSymbol(node.Parent)
		if symbol != nil && symbol.Flags&ast.SymbolFlagsAlias != 0 {
			symbol = l.checker.GetAliasedSymbol(symbol)
		}
		if symbol != nil {
			return l.checker.GetExportSymbolOfSymbol(symbol)
		}
		return nil
	}
	return l.symbol(node)
}

enum_initialization.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
)

// Enum declarations are validated before registration. Initialization reachability
// is shared with namespaces in namespaceInitialization, which runs once afterward.
func (l *lowering) enumInitialization(modules []*ast.SourceFile) error {
	for _, module := range modules {
		for _, statement := range namespaceDeclarations(module.Statements.Nodes) {
			if statement.Kind == ast.KindEnumDeclaration {
				if _, err := l.enumFields(statement); err != nil {
					return err
				}
			}
		}
	}
	return nil
}

enum_never.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// Array reads have no field symbol. Recover their stored element type before flow narrowing.
func (l *lowering) enumStoredType(node *ast.Node) *checker.Type {
	node = ast.SkipParentheses(node)
	if symbol := l.flagValueSymbol(node); symbol != nil {
		return l.checker.GetTypeOfSymbol(symbol)
	}
	if node.Kind == ast.KindElementAccessExpression {
		stored := l.checker.GetTypeAtLocation(node.AsElementAccessExpression().Expression)
		if l.checker.IsArrayType(stored) {
			if arguments := l.checker.GetTypeArguments(stored); len(arguments) == 1 {
				return arguments[0]
			}
		}
	}
	return nil
}

// Follow the declared type, not the flow type that has already become never. A never alias
// keeps its initializer's enum identity, but never acquires a runtime member proof.
func (l *lowering) enumNeverIdentity(node *ast.Node, seen map[*ast.Node]bool) *ast.Symbol {
	node = ast.SkipParentheses(node)
	if l.checker.GetTypeAtLocation(node).Flags()&checker.TypeFlagsNever == 0 || seen[node] {
		return nil
	}
	seen[node] = true
	symbol := l.flagValueSymbol(node)
	stored := l.enumStoredType(node)
	if stored == nil {
		return nil
	}
	declared := l.concrete(stored)
	for _, member := range l.definedMembers(declared) {
		identity := l.enumIdentity(member)
		if l.numericEnum(identity) {
			return identity
		}
	}
	if symbol != nil {
		if declaration := symbol.ValueDeclaration; declaration != nil && declaration.Kind == ast.KindVariableDeclaration {
			if initializer := declaration.AsVariableDeclaration().Initializer; initializer != nil {
				identity := l.enumIdentity(l.checker.GetTypeAtLocation(initializer))
				if l.numericEnum(identity) {
					return identity
				}
				return l.enumNeverIdentity(initializer, seen)
			}
		}
	}
	return nil
}

// Only immutable aliases of actual members prove membership. Parameters, mutable slots,
// numeric literals, casts, arithmetic and flag-domain proofs do not prove a declared member.
func (l *lowering) enumMemberOrigin(node *ast.Node, identity *ast.Symbol, seen map[*ast.Node]bool) bool {
	node = ast.SkipParentheses(node)
	if member := l.enumMember(node); member != nil {
		return l.symbol(member.Parent.Name()) == identity
	}
	if !ast.IsIdentifier(node) || seen[node] {
		return false
	}
	seen[node] = true
	if symbol := l.symbol(node); symbol != nil && symbol.ValueDeclaration != nil {
		declaration := symbol.ValueDeclaration
		if declaration.Kind == ast.KindVariableDeclaration && declaration.Parent.Flags&ast.NodeFlagsConst != 0 {
			if initializer := declaration.AsVariableDeclaration().Initializer; initializer != nil {
				return l.enumMemberOrigin(initializer, identity, seen)
			}
		}
	}
	return false
}

// An ordinary IR helper preserves evaluation order and reads the operand exactly once. Its
// panic is shared by both backends; never itself does not need a new machine representation.
func (l *lowering) enumNeverCheck(node *ast.Node, value ir.Expression, identity *ast.Symbol) ir.Expression {
	of := ir.Number
	if contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone); contextual != nil {
		if representation, known := l.representation(contextual); known && !slotless(representation) {
			of = representation
		}
	}
	if node.Parent != nil && node.Parent.Kind == ast.KindReturnStatement && l.function != nil {
		of = l.function.Returns
	}
	function := len(l.result.Functions)
	local := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "enum_never_value", Type: value.Type(), Function: function})
	read := ir.Read{Local: local, Of: value.Type()}
	var printed ir.Expression = ir.NumberToString{Value: read}
	if value.Type().IsMaybe() {
		printed = ir.MaybeToString{Value: read}
	} else if value.Type() == ir.Union {
		printed = ir.UnionToString{Value: read}
	}
	message := ir.Concat{Parts: []ir.Expression{
		ir.StringConstant{Index: l.constant("unreachable value ")},
		printed,
		ir.StringConstant{Index: l.constant(" for numeric enum " + identity.Name)},
	}}
	l.result.Functions = append(l.result.Functions, ir.Function{
		Name: "enum_never", Parameters: []int{local}, Returns: of,
		Body: []ir.Statement{ir.Panic{Message: message}},
	})
	return ir.Call{Function: function, Arguments: []ir.Expression{value}, Returns: of}
}

enums.go:
package lower

import (
	"math"
	"reflect"
	"strconv"
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// Numeric enums are numbers with named constants. String enums retain declaration identity.
func (l *lowering) enumAssignable(from, to *checker.Type) bool {
	if target := enumObjectSymbol(to); target != nil && from.Flags()&(checker.TypeFlagsUndefined|checker.TypeFlagsNull|checker.TypeFlagsNever) == 0 {
		return enumObjectSymbol(from) == target
	}
	if to.Flags()&checker.TypeFlagsNumberLiteral != 0 && l.openNumericEnumType(from) && !l.openNumericEnumType(to) {
		return false
	}
	if to.Flags()&checker.TypeFlagsEnumLike == 0 {
		return true
	}
	if from.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range from.Types() {
			if !l.enumAssignable(member, to) {
				return false
			}
		}
		return true
	}
	if l.numericEnum(l.enumIdentity(to)) {
		if !l.openNumericEnumType(to) {
			return !l.openNumericEnumType(from) && from.Flags()&checker.TypeFlagsNumberLiteral != 0 && l.checker.IsTypeAssignableTo(from, to)
		}
		return from.Flags()&(checker.TypeFlagsNumberLike|checker.TypeFlagsNever) != 0
	}
	return from.Flags()&checker.TypeFlagsEnumLike != 0 && l.enumIdentity(from) == l.enumIdentity(to) && l.checker.IsTypeAssignableTo(from, to)
}

// The whole declaration is open; a member-specific literal is a smaller promise.
func (l *lowering) openNumericEnumType(proven *checker.Type) bool {
	proven = l.checker.GetNonNullableType(proven)
	identity := l.enumIdentity(proven)
	if !l.numericEnum(identity) {
		return false
	}
	whole := l.checker.GetTypeAtLocation(identity.ValueDeclaration.Name())
	if proven == whole {
		return true
	}
	if proven.Flags()&checker.TypeFlagsUnion == 0 || whole.Flags()&checker.TypeFlagsUnion == 0 || len(proven.Types()) != len(whole.Types()) {
		return false
	}
	for _, member := range whole.Types() {
		found := false
		for _, part := range proven.Types() {
			if part == member {
				found = true
			}
		}
		if !found {
			return false
		}
	}
	return true
}

func (l *lowering) numericEnum(symbol *ast.Symbol) bool {
	if symbol == nil || symbol.ValueDeclaration == nil || symbol.ValueDeclaration.Kind != ast.KindEnumDeclaration {
		return false
	}
	for _, member := range symbol.ValueDeclaration.AsEnumDeclaration().Members.Nodes {
		constant := l.checker.GetConstantValue(member)
		if constant == nil || reflect.TypeOf(constant).Kind() != reflect.Float64 {
			return false
		}
	}
	return true
}

// typeof E names the actual enum object and its aliases. Structural copies can omit reverse
// properties or carry hidden heterogeneous fields, so they cannot inherit that exact shape proof.
func enumObjectSymbol(proven *checker.Type) *ast.Symbol {
	if proven.Flags()&checker.TypeFlagsObject == 0 {
		return nil
	}
	if symbol := proven.Symbol(); symbol != nil && symbol.Flags&ast.SymbolFlagsEnum != 0 {
		return symbol
	}
	return nil
}

func (l *lowering) enumObjectView(node *ast.Node) error {
	if !l.isExpression(node) || node.Kind == ast.KindParenthesizedExpression {
		return nil
	}
	target := l.checker.GetContextualType(node, checker.ContextFlagsNone)
	source := l.checker.GetTypeAtLocation(node)
	if node.Kind == ast.KindAsExpression {
		target = l.checker.GetTypeAtLocation(node)
		source = l.checker.GetTypeAtLocation(node.AsAsExpression().Expression)
	}
	if target == nil {
		return nil
	}
	target = l.checker.GetNonNullableType(target)
	if enumObjectSymbol(target) != nil && !l.enumAssignable(source, target) {
		return &Refused{Where: l.program.Where(node), What: "a structural object used as " + l.checker.TypeToString(target) + "; reverse properties and the complete enum shape are unproven", Fix: "use the enum's runtime object or its typeof alias; give an ordinary object an explicit interface"}
	}
	return nil
}

func (l *lowering) enumIdentity(proven *checker.Type) *ast.Symbol {
	symbol := proven.Symbol()
	if symbol != nil && symbol.Flags&ast.SymbolFlagsEnumMember != 0 && symbol.ValueDeclaration != nil {
		return l.symbol(symbol.ValueDeclaration.Parent.Name())
	}
	if symbol != nil && symbol.Flags&ast.SymbolFlagsEnum != 0 {
		return symbol
	}
	if proven.Flags()&checker.TypeFlagsUnion != 0 && len(proven.Types()) > 0 {
		return l.enumIdentity(proven.Types()[0])
	}
	return nil
}

func (l *lowering) enumMember(node *ast.Node) *ast.Node {
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindPropertyAccessExpression && node.Kind != ast.KindElementAccessExpression && node.Kind != ast.KindIdentifier {
		return nil
	}
	symbol := l.symbol(node)
	if symbol != nil && symbol.Flags&ast.SymbolFlagsEnumMember != 0 {
		return symbol.ValueDeclaration
	}
	return nil
}

func (l *lowering) enumObject(node *ast.Node) *ast.Node {
	proven := l.checker.GetTypeAtLocation(node)
	if proven.Flags()&checker.TypeFlagsObject == 0 {
		return nil
	}
	symbol := proven.Symbol()
	if symbol == nil || symbol.Flags&ast.SymbolFlagsEnum == 0 {
		return nil
	}
	return symbol.ValueDeclaration
}

func (l *lowering) enumConstant(member *ast.Node) (ir.Expression, error) {
	constant := l.checker.GetConstantValue(member)
	if constant != nil && reflect.TypeOf(constant).Kind() == reflect.Float64 {
		value := reflect.ValueOf(constant).Float()
		if math.IsNaN(value) || math.IsInf(value, 0) {
			return nil, l.notYet(member, "a non-finite enum member")
		}
		return ir.NumberConstant{Value: value}, nil
	}
	if value, ok := constant.(string); ok {
		return ir.StringConstant{Index: l.constant(value)}, nil
	}
	return nil, l.notYet(member, "a computed enum member; use a constant number or string initializer")
}

// Build the same forward and reverse assignments as JavaScript, with the last numeric alias
// winning. A string member adds only its forward property. No runtime operation can mutate an
// enum's member slots through a structural writable view (the invariance pass checks those).
func (l *lowering) enumFields(node *ast.Node) ([]ir.Field, error) {
	fields := []ir.Field{}
	positions := map[string]int{}
	set := func(name string, value ir.Expression) {
		if position, exists := positions[name]; exists {
			fields[position].Value = value
			return
		}
		positions[name] = len(fields)
		fields = append(fields, ir.Field{Name: name, Value: value})
	}
	for _, member := range node.AsEnumDeclaration().Members.Nodes {
		if member.Name().Text() == "__proto__" || strings.ContainsRune(member.Name().Text(), 0) {
			return nil, &Refused{Where: l.program.Where(member), What: "an enum member name that changes the prototype or contains NUL", Fix: "rename the member; enum properties must be ordinary fixed slots"}
		}
		value, err := l.enumConstant(member)
		if err != nil {
			return nil, err
		}
		if value.Type() == ir.Number && (member.Name().Text() == "NaN" || member.Name().Text() == "Infinity" || member.Name().Text() == "-Infinity") {
			return nil, &Refused{Where: l.program.Where(member), What: "a numeric enum member named like a non-finite number; numeric indexing could read a number where tsc promises a string", Fix: "rename the member so numeric reverse mapping stays string-valued"}
		}
		set(member.Name().Text(), value)
		if number, numeric := value.(ir.NumberConstant); numeric {
			key := strconv.FormatFloat(number.Value, 'f', -1, 64)
			if printed, ok := l.checker.GetConstantValue(member).(interface{ String() string }); ok {
				key = printed.String()
			}
			if number.Value == 0 {
				key = "0"
			}
			set(key, ir.StringConstant{Index: l.constant(member.Name().Text())})
		}
	}
	return fields, nil
}

// In a declaration the enum name denotes its member type; in value position it denotes the
// runtime object. Declare the latter explicitly instead of using the name node's number type.
func (l *lowering) enumLocal(node *ast.Node) (int, error) {
	local, err := l.declareLocal(node.Name())
	if err != nil {
		return 0, err
	}
	l.result.Locals[local].Type = ir.Object
	l.noteLocal(local, l.checker.GetTypeOfSymbol(l.symbol(node.Name())), node.Name())
	return local, nil
}

func (l *lowering) enumDeclaration(node *ast.Node) ([]ir.Statement, error) {
	if ast.HasSyntacticModifier(node, ast.ModifierFlagsConst) {
		return nil, nil
	}
	fields, err := l.enumFields(node)
	if err != nil {
		return nil, err
	}
	local, err := l.enumLocal(node)
	if err != nil {
		return nil, err
	}
	return []ir.Statement{ir.Declare{Local: local, Value: ir.ObjectLiteral{Fields: fields}}}, nil
}

func (l *lowering) enumExpression(node *ast.Node) (ir.Expression, bool, error) {
	member := l.enumMember(node)
	if member != nil && node.Kind == ast.KindElementAccessExpression && !ast.HasSyntacticModifier(member.Parent, ast.ModifierFlagsConst) {
		index := ast.SkipParentheses(node.AsElementAccessExpression().ArgumentExpression)
		if index.Kind != ast.KindStringLiteral && index.Kind != ast.KindNoSubstitutionTemplateLiteral {
			member = nil
		}
	}
	if member != nil {
		declaration := member.Parent
		if ast.HasSyntacticModifier(declaration, ast.ModifierFlagsConst) {
			value, err := l.enumConstant(member)
			if err == nil {
				value = l.namespaceReadyValue(node, value)
			}
			return value, true, err
		}
		var receiver *ast.Node
		switch node.Kind {
		case ast.KindPropertyAccessExpression:
			receiver = node.AsPropertyAccessExpression().Expression
		case ast.KindElementAccessExpression:
			receiver = node.AsElementAccessExpression().Expression
		default:
			return nil, true, l.notYet(node, "an unqualified enum member outside its initializer")
		}
		object, err := l.expression(receiver)
		if err != nil {
			return nil, true, err
		}
		of, err := l.typeOf(member.Name())
		optional := false
		if node.Kind == ast.KindPropertyAccessExpression {
			optional = node.AsPropertyAccessExpression().QuestionDotToken != nil
		}
		if node.Kind == ast.KindElementAccessExpression {
			optional = node.AsElementAccessExpression().QuestionDotToken != nil
		}
		if !optional && node.Flags&ast.NodeFlagsOptionalChain != 0 {
			return nil, true, l.notYet(node, "an optional enum chain longer than one step")
		}
		return ir.Property{Object: object, Name: member.Name().Text(), Of: of, Optional: optional}, true, err
	}
	if node.Kind != ast.KindElementAccessExpression {
		return nil, false, nil
	}
	access := node.AsElementAccessExpression()
	declaration := l.enumObject(access.Expression)
	if declaration == nil {
		return nil, false, nil
	}
	fields, err := l.enumFields(declaration)
	if err != nil {
		return nil, true, err
	}
	object, err := l.expression(access.Expression)
	if err != nil {
		return nil, true, err
	}
	key, err := l.expression(access.ArgumentExpression)
	if err != nil {
		return nil, true, err
	}
	if key.Type() != ir.Number && key.Type() != ir.String {
		return nil, true, l.notYet(node, "an enum index other than number or string")
	}
	of, err := l.typeOf(node)
	if err != nil {
		return nil, true, err
	}
	// A helper evaluates receiver and key exactly once, including a key with side effects. It
	// uses ordinary IR so flow, ownership, regions and reuse all see its reads and returns.
	index := len(l.result.Functions)
	objectLocal := len(l.result.Locals)
	keyLocal := objectLocal + 1
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "enum_object", Type: ir.Object, Function: index}, ir.Local{Name: "enum_key", Type: key.Type(), Function: index})
	readObject := ir.Read{Local: objectLocal, Of: ir.Object}
	readKey := ir.Read{Local: keyLocal, Of: key.Type()}
	var tested ir.Expression = readKey
	if key.Type() == ir.Number {
		tested = ir.NumberToString{Value: readKey}
	}
	function := ir.Function{Name: "enum_lookup", Parameters: []int{objectLocal, keyLocal}, Returns: of}
	for _, field := range fields {
		if field.Value.Type() != of.Present() {
			continue
		}
		function.Body = append(function.Body, ir.If{Condition: ir.Binary{Operator: ir.Equal, Left: tested, Right: ir.StringConstant{Index: l.constant(field.Name)}}, Then: []ir.Statement{ir.Return{Value: fit(ir.Property{Object: readObject, Name: field.Name, Of: field.Value.Type()}, of)}}})
	}
	if !of.IsReference() && !of.IsMaybe() {
		keys := l.checker.GetTypeAtLocation(access.ArgumentExpression)
		members := []*checker.Type{keys}
		if keys.Flags()&checker.TypeFlagsUnion != 0 {
			members = keys.Types()
		}
		for _, member := range members {
			if member.Flags()&checker.TypeFlagsStringLiteral == 0 {
				return nil, true, l.notYet(node, "an enum lookup without a proven member name")
			}
			name, ok := member.AsLiteralType().Value().(string)
			found := false
			for _, field := range fields {
				if ok && field.Name == name && field.Value.Type() == of {
					found = true
				}
			}
			if !found {
				return nil, true, l.notYet(node, "an enum lookup without a proven member name")
			}
		}
		function.Body = append(function.Body, ir.Panic{Message: ir.StringConstant{Index: l.constant("enum member name outside its proven union")}})
	} else {
		function.Body = append(function.Body, ir.Return{Value: ir.Undefined{Of: of}})
	}
	l.result.Functions = append(l.result.Functions, function)
	return ir.Call{Function: index, Arguments: []ir.Expression{object, key}, Returns: of}, true, nil
}

func (l *lowering) enumRefusal(node *ast.Node) error {
	if l.isExpression(node) {
		if symbol := l.flagValueSymbol(node); symbol != nil {
			declared := l.checker.GetTypeOfSymbol(symbol)
			observed := l.checker.GetTypeAtLocation(node)
			objectMembers := 0
			if declared.Flags()&checker.TypeFlagsUnion != 0 {
				for _, member := range declared.Types() {
					if member.Flags()&checker.TypeFlagsObject != 0 {
						objectMembers++
					}
				}
			}
			if objectMembers > 1 && declared.Flags()&checker.TypeFlagsUnion != 0 && observed != declared && observed.Flags()&checker.TypeFlagsObject != 0 {
				for _, member := range declared.Types() {
					for _, field := range l.checker.GetPropertiesOfType(member) {
						tag := l.checker.GetTypeOfSymbol(field)
						if l.openNumericEnumType(tag) {
							return &Refused{Where: l.program.Where(node), What: "an object refinement using an open numeric enum as a literal tag", Fix: "use a member-specific tag from a multi-member enum, a string enum, or a plain literal tag (adamic/enum-tag)"}
						}
					}
				}
			}
		}
	}

	if err := l.enumObjectView(node); err != nil {
		return err
	}
	if node.Kind == ast.KindCallExpression {
		call := node.AsCallExpression()
		callee := ast.SkipParentheses(call.Expression)
		if callee.Kind == ast.KindPropertyAccessExpression && len(call.Arguments.Nodes) > 0 {
			access := callee.AsPropertyAccessExpression()
			if access.Name().Text() == "assign" && l.isLibraryGlobal(access.Expression, "Object") && l.enumObject(call.Arguments.Nodes[0]) != nil {
				return &Refused{Where: l.program.Where(node), What: "a write into an enum runtime object; named constants and reverse lookup must stay consistent", Fix: "copy the enum into an ordinary object before writing it (adamic/enum-object)"}
			}
		}
	}
	if node.Kind == ast.KindEnumDeclaration {
		if node.Parent.Kind != ast.KindSourceFile && node.Parent.Kind != ast.KindModuleBlock {
			return l.notYet(node, "an enum inside a function or block; declare it at module scope")
		}
		symbol := l.symbol(node.Name())
		if symbol != nil && len(symbol.Declarations) != 1 {
			return l.notYet(node, "merged enum declarations; put the members in one declaration")
		}
		if ast.HasSyntacticModifier(node, ast.ModifierFlagsAmbient) {
			return l.notYet(node, "an ambient enum without a runtime definition")
		}
		// Signed masks, including 1 << 31, are ordinary numeric enum constants.
		_, err := l.enumFields(node)
		return err
	}
	var updated *ast.Node
	switch node.Kind {
	case ast.KindPrefixUnaryExpression:
		unary := node.AsPrefixUnaryExpression()
		if unary.Operator == ast.KindPlusPlusToken || unary.Operator == ast.KindMinusMinusToken {
			updated = unary.Operand
		}
	case ast.KindPostfixUnaryExpression:
		updated = node.AsPostfixUnaryExpression().Operand
	case ast.KindBinaryExpression:
		binary := node.AsBinaryExpression()
		if ast.IsAssignmentOperator(binary.OperatorToken.Kind) && binary.OperatorToken.Kind != ast.KindEqualsToken {
			updated = binary.Left
		}
	}
	if updated != nil && l.checker.GetTypeAtLocation(updated).Flags()&checker.TypeFlagsEnumLike != 0 && !l.numericEnum(l.enumIdentity(l.checker.GetTypeAtLocation(updated))) {
		if l.flagUpdate(node, updated) {
			return nil
		}
		if l.flagEnum(l.enumIdentity(l.checker.GetTypeAtLocation(updated))) {
			return l.flagWriteRefusal(node, l.checker.GetTypeAtLocation(updated))
		}
		return &Refused{Where: l.program.Where(node), What: "arithmetic assigned back into an enum; the result need not be one of its members", Fix: "assign a declared member, or keep arithmetic results in a number (adamic/enum-members)"}
	}
	return nil
}

// Compare runtime values, not spellings: numeric aliases denote the same union member. A default
// handles all remaining values. A void switch still needs coverage, even when tsc accepts it.
func (l *lowering) enumSwitch(node *ast.Node) error {
	statement := node.AsSwitchStatement()
	proven := l.checker.GetTypeAtLocation(statement.Expression)
	if proven.Flags()&checker.TypeFlagsEnumLike == 0 || l.numericEnum(l.enumIdentity(proven)) {
		return nil
	}
	covered := map[any]bool{}
	for _, clause := range statement.CaseBlock.AsCaseBlock().Clauses.Nodes {
		if clause.Kind == ast.KindDefaultClause {
			return nil
		}
		test := clause.AsCaseOrDefaultClause().Expression
		if member := l.enumMember(test); member != nil {
			covered[l.checker.GetConstantValue(member)] = true
		} else if value := l.checker.GetTypeAtLocation(test); value.Flags()&checker.TypeFlagsLiteral != 0 {
			covered[value.AsLiteralType().Value()] = true
		}
	}
	if l.flagEnum(l.enumIdentity(proven)) {
		return &Refused{Where: l.program.Where(node), What: "a flag-enum switch without a default", Fix: "add a default for combinations and zero (adamic/enum-flags)"}
	}
	members := []*checker.Type{proven}
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		members = proven.Types()
	}
	for _, member := range members {
		if member.Flags()&checker.TypeFlagsLiteral == 0 {
			return l.notYet(node, "a switch on a computed enum member")
		}
		if !covered[member.AsLiteralType().Value()] {
			return &Refused{Where: l.program.Where(node), What: "a non-exhaustive enum switch; missing " + l.checker.TypeToString(member), Fix: "add the missing member's case or a default"}
		}
	}
	return nil
}

// A numeric enum default is unreachable only with a member origin proof and full coverage.
// This permits the never-default idiom without inventing a machine representation for never.
func (l *lowering) enumDefaultUnreachable(node *ast.Node) bool {
	statement := node.AsSwitchStatement()
	proven := l.checker.GetTypeAtLocation(statement.Expression)
	return l.enumSwitchCovered(node) && (!l.numericEnum(l.enumIdentity(proven)) || l.enumMemberOrigin(statement.Expression, l.enumIdentity(proven), map[*ast.Node]bool{}))
}

func (l *lowering) enumSwitchCovered(node *ast.Node) bool {
	statement := node.AsSwitchStatement()
	proven := l.checker.GetTypeAtLocation(statement.Expression)
	if proven.Flags()&checker.TypeFlagsEnumLike == 0 {
		return false
	}
	covered := map[any]bool{}
	for _, clause := range statement.CaseBlock.AsCaseBlock().Clauses.Nodes {
		if clause.Kind == ast.KindDefaultClause {
			continue
		}
		test := clause.AsCaseOrDefaultClause().Expression
		if member := l.enumMember(test); member != nil {
			covered[l.checker.GetConstantValue(member)] = true
		} else if value := l.checker.GetTypeAtLocation(test); value.Flags()&checker.TypeFlagsLiteral != 0 {
			covered[value.AsLiteralType().Value()] = true
		}
	}
	members := []*checker.Type{proven}
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		members = proven.Types()
	}
	for _, member := range members {
		if member.Flags()&checker.TypeFlagsLiteral == 0 || !covered[member.AsLiteralType().Value()] {
			return false
		}
	}
	return true
}

evolving_local.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// evolvingObject finds a storage type for an unannotated, uninitialized local
// whose assignments all have proven object types. Explicit any and any-valued
// reads remain unsupported; the checker's flow types still decide every use.
func (l *lowering) evolvingObject(name *ast.Node) *checker.Type {
	if name.Parent == nil || name.Parent.Kind != ast.KindVariableDeclaration {
		return nil
	}
	declaration := name.Parent.AsVariableDeclaration()
	if declaration.Type != nil || declaration.Initializer != nil || l.checker.GetTypeAtLocation(name).Flags()&checker.TypeFlagsAny == 0 {
		return nil
	}
	root := name.Parent
	for root.Parent != nil && !ast.IsFunctionLike(root) {
		root = root.Parent
	}
	symbol := l.symbol(name)
	var inferred *checker.Type
	valid := true
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if node.Kind == ast.KindBinaryExpression {
			binary := node.AsBinaryExpression()
			target := ast.SkipParentheses(binary.Left)
			if ast.IsIdentifier(target) && l.symbol(target) == symbol {
				_, compound := compoundAssignments[binary.OperatorToken.Kind]
				if binary.OperatorToken.Kind == ast.KindEqualsToken || compound || logicalAssignment(binary.OperatorToken.Kind) {
					proven := l.checker.GetTypeAtLocation(binary.Right)
					of, known := l.representation(proven)
					if binary.OperatorToken.Kind != ast.KindEqualsToken || !known || of != ir.Object {
						valid = false
					} else if inferred == nil {
						inferred = proven
					} else if inferred != proven {
						valid = false
					}
				}
			}
		}
		if node.Kind == ast.KindIdentifier && node != name && l.symbol(node) == symbol && l.checker.GetTypeAtLocation(node).Flags()&checker.TypeFlagsAny != 0 {
			// A write target can still have auto/any before its first assignment.
			if node.Parent == nil || node.Parent.Kind != ast.KindBinaryExpression || node.Parent.AsBinaryExpression().Left != node || node.Parent.AsBinaryExpression().OperatorToken.Kind != ast.KindEqualsToken {
				valid = false
			}
		}
		node.ForEachChild(visit)
		return false
	}
	root.ForEachChild(visit)
	if !valid {
		return nil
	}
	return inferred
}

exceptions.go:
package lower

import (
	"math"
	"reflect"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// Exceptions (docs/memory.md, "Exceptions, designed into counting"): throw new Error(message), a
// caught error thrown again, and try with catch, finally or both. What's thrown is only ever an
// Error, made by new Error or caught, since a catch binds unknown and 0.2 has no value of every kind.

// tryRecord is a try statement lowered, for the checks made once every function is: where it is,
// and its body.
type tryRecord struct {
	node *ast.Node
	body []ir.Statement
}

// throwStatement lowers throw.
func (l *lowering) throwStatement(node *ast.Node) ([]ir.Statement, error) {
	thrown := ast.SkipParentheses(node.AsThrowStatement().Expression)
	isNewError := thrown.Kind == ast.KindNewExpression && l.isLibraryGlobal(thrown.AsNewExpression().Expression, "Error")
	isCaught := ast.IsIdentifier(thrown) && l.caught[l.symbol(thrown)]
	// Error is structurally typed: { name, message, stack } can satisfy it without
	// being an Error on Node. Follow only immutable bindings to a real allocation.
	seen := map[*ast.Symbol]bool{}
	var madeError func(*ast.Node) bool
	madeError = func(value *ast.Node) bool {
		if value == nil {
			return false
		}
		value = ast.SkipParentheses(value)
		if value.Kind == ast.KindNewExpression {
			return l.isLibraryGlobal(value.AsNewExpression().Expression, "Error")
		}
		if !ast.IsIdentifier(value) {
			return false
		}
		symbol := l.symbol(value)
		if symbol == nil || seen[symbol] || len(symbol.Declarations) != 1 {
			return false
		}
		seen[symbol] = true
		declaration := symbol.Declarations[0]
		if declaration.Kind != ast.KindVariableDeclaration || declaration.Parent == nil || declaration.Parent.Kind != ast.KindVariableDeclarationList || declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
			return false
		}
		return madeError(declaration.AsVariableDeclaration().Initializer)
	}
	isStoredError := !isNewError && !isCaught && l.isLibraryType(l.checker.GetTypeAtLocation(thrown), "Error") && madeError(thrown)
	if !isNewError && !isCaught && !isStoredError {
		if l.isLibraryType(l.checker.GetTypeAtLocation(thrown), "Error") {
			return nil, l.notYet(thrown, "throwing an Error that isn't made where it's thrown or caught by the catch around it")
		}
		return nil, &Refused{Where: l.program.Where(thrown), What: "throwing a " + l.checker.TypeToString(l.checker.GetTypeAtLocation(thrown)), Fix: "throw an Error: throw new Error(String(value)); what a catch takes is unknown, and an Error is what it can be sure of"}
	}
	value, err := l.expression(thrown)
	if err != nil {
		return nil, err
	}
	return []ir.Statement{ir.Throw{Value: value}}, nil
}

// newError lowers new Error(message), and new Error().
func (l *lowering) newError(node *ast.Node) (ir.Expression, error) {
	created := node.AsNewExpression()
	message := ir.Expression(ir.StringConstant{Index: l.constant("")})
	if created.Arguments != nil && len(created.Arguments.Nodes) > 0 {
		if len(created.Arguments.Nodes) > 1 {
			return nil, l.notYet(node, "new Error with options")
		}
		var err error
		if message, err = l.expression(created.Arguments.Nodes[0]); err != nil {
			return nil, err
		}
		if message.Type() != ir.String {
			return nil, l.notYet(node, "new Error with a message that isn't a string")
		}
	}
	return ir.MakeError{Message: message}, nil
}

// tryStatement lowers try, with catch, finally or both.
func (l *lowering) tryStatement(node *ast.Node) ([]ir.Statement, error) {
	statement := node.AsTryStatement()
	lowered := ir.Try{CatchLocal: -1}
	var err error
	if lowered.Body, err = l.statements(statement.TryBlock.AsBlock().Statements.Nodes); err != nil {
		return nil, err
	}
	l.tries = append(l.tries, tryRecord{node: node, body: lowered.Body})
	if clause := statement.CatchClause; clause != nil {
		lowered.HasCatch = true
		if declaration := clause.AsCatchClause().VariableDeclaration; declaration != nil {
			name := declaration.Name()
			if !ast.IsIdentifier(name) {
				return nil, l.notYet(name, "a catch that destructures what it caught")
			}
			if l.caught == nil {
				l.caught = map[*ast.Symbol]bool{}
			}
			l.caught[l.symbol(name)] = true
			if lowered.CatchLocal, err = l.declareLocal(name); err != nil {
				return nil, err
			}
		}
		if lowered.Catch, err = l.statements(clause.AsCatchClause().Block.AsBlock().Statements.Nodes); err != nil {
			return nil, err
		}
	}
	if block := statement.FinallyBlock; block != nil {
		lowered.HasFinally = true
		// A return, break or continue out of the finally overrides whatever the try was doing, a
		// throw or a return included: the emitter lets go of the pending error or the held result on
		// the way out, as the scopes they wait in are left.
		if lowered.Finally, err = l.statements(block.AsBlock().Statements.Nodes); err != nil {
			return nil, err
		}
	}
	return []ir.Statement{lowered}, nil
}

// caughtInstanceOfError lowers error instanceof Error on what a catch took, which is always an Error.
func (l *lowering) caughtInstanceOfError(node *ast.Node) (ir.Expression, bool) {
	binary := node.AsBinaryExpression()
	left := ast.SkipParentheses(binary.Left)
	if binary.OperatorToken.Kind != ast.KindInstanceOfKeyword || !ast.IsIdentifier(left) || !l.caught[l.symbol(left)] || !l.isLibraryGlobal(binary.Right, "Error") {
		return nil, false
	}
	l.local(left)
	return ir.BooleanConstant{Value: true}, true
}

// exceptions works out which functions a throw can leave, once every function is lowered, and
// refuses what can't be done yet: a try that can reach a library call whose failure is a panic
// natively but a throw on Node.
func (l *lowering) exceptions() error {
	functions := l.result.Functions
	// A class's methods are reached through function values too: a call through an interface the
	// class implements calls one where it would call the object's own function value (ir.Property's
	// Method), so a method that can throw makes every such call one that can.
	dispatched := map[int]bool{}
	for _, lowered := range l.instances {
		for _, method := range lowered.methodList() {
			dispatched[method.Function] = true
		}
	}
	// Whether any function value can throw, and so every call through one, grows with what can, so
	// the two are worked out together until neither changes.
	for changed := true; changed; {
		changed = false
		for index := range functions {
			if (functions[index].Closure || dispatched[index]) && functions[index].MayThrow && !l.result.ClosuresMayThrow {
				l.result.ClosuresMayThrow = true
				changed = true
			}
			if !functions[index].MayThrow && l.throwsOut(functions[index].Body) {
				functions[index].MayThrow = true
				changed = true
			}
		}
	}
	for _, record := range l.tries {
		if failing := l.libraryFailure(record.body, map[int]bool{}); failing != "" {
			return l.notYet(record.node, "a try around "+failing+", whose failure is a panic natively but a throw a catch can take on Node (docs/memory.md)")
		}
	}
	return nil
}

// throwsOut reports whether a throw can leave statements: a throw, or a call to a function that can
// throw (through a function value too, a sort's comparator among them), that isn't inside a try's
// body with a catch.
func (l *lowering) throwsOut(statements []ir.Statement) bool {
	found := false
	walk(statements, func(node any) bool {
		switch node := node.(type) {
		case ir.Try:
			if node.HasCatch {
				// The body's throws are caught; the catch's and the finally's aren't.
				found = found || l.throwsOut(node.Catch) || l.throwsOut(node.Finally)
				return false
			}
		case ir.NodeFSFile:
			found = found || node.MayThrow()
		case ir.Throw:
			found = true
		case ir.Call:
			if l.result.CallMayThrow(node) {
				found = true
			}
		case ir.RegExpCall:
			if node.Replacement != nil && l.result.ClosuresMayThrow {
				found = true
			}
		case ir.CallClosure, ir.ArrayMap, ir.ArrayVisit, ir.ArrayReduce, ir.ArrayFrom, ir.MapForEach:
			// A call through a function value, written out or made by the runtime's loop.
			if l.result.ClosuresMayThrow {
				found = true
			}
		case ir.ArraySort:
			if (node.Callback != nil && l.result.ClosuresMayThrow) || (node.Callback == nil && l.result.Functions[node.Comparator].MayThrow) {
				found = true
			}
		}
		return !found
	})
	return found
}

// libraryFailure names the first library call statements can reach, directly or through the
// functions they call, that throws in JavaScript for some argument and isn't given a constant that
// can't fail, or returns "".
func (l *lowering) libraryFailure(statements []ir.Statement, visited map[int]bool) string {
	failing := ""
	callsClosures := false
	walk(statements, func(node any) bool {
		switch node := node.(type) {
		case ir.Call:
			for _, target := range l.result.CallTargets(node) {
				if !visited[target] {
					visited[target] = true
					failing = l.libraryFailure(l.result.Functions[target].Body, visited)
					if failing != "" {
						break
					}
				}
			}
		case ir.CallClosure, ir.ArrayMap, ir.ArrayVisit, ir.ArrayReduce, ir.MapForEach:
			callsClosures = true
		case ir.ArraySort:
			if node.Callback != nil {
				callsClosures = true
			} else if !visited[node.Comparator] {
				visited[node.Comparator] = true
				failing = l.libraryFailure(l.result.Functions[node.Comparator].Body, visited)
			}
		case ir.SetProperty:
			if l.objectCanFreeze() {
				failing = "a write to a potentially frozen object"
			}
		case ir.NodeBufferCall:
			if node.Function == "hash_update" || node.Function == "hash_digest" {
				failing = "Hash finalization, whose catchable .code contract is not supported yet"
			}
		case ir.ObjectCall:
			if node.Method == "assign" && l.objectCanFreeze() {
				failing = "Object.assign into a potentially frozen object"
			}
		case ir.RegExpCall:
			if node.Replacement != nil {
				callsClosures = true
			}
			if node.Method == "replaceAll" || node.Method == "matchAll" {
				failing = "RegExp global-flag validation"
			}
		case ir.StringCall:
			switch {
			case node.Method == "repeat" && !constantWithin(node.Arguments[0], 0, math.MaxFloat64):
				failing = "repeat"
			case node.Method == "normalize" && len(node.Arguments) > 0 && !isNormalizationForm(node.Arguments[0], l.result.Strings):
				failing = "normalize"
			}
		case ir.ToFixed:
			if !constantWithin(node.Digits, 0, 100) {
				failing = "toFixed"
			}
		case ir.NumberFormat:
			if bounds := formatArguments[node.Method]; node.Argument != nil && !constantWithin(node.Argument, bounds[0], bounds[1]) {
				failing = node.Method
			}
		case ir.TypedArrayNew:
			if !node.FromArray && !constantWithin(node.Source, 0, 9007199254740991) {
				failing = "typed array length conversion"
			}
		case ir.TypedArraySet:
			failing = "typed array set range validation"
		case ir.ArrayFill:
			if node.Array == nil && !constantWithin(node.Length, 0, 4294967295) {
				failing = "new Array(length)"
			}
		case ir.ArrayFrom:
			callsClosures = true
			if !constantWithin(node.Length, math.Inf(-1), 4294967295) {
				failing = "Array.from({ length })"
			}
		}
		return failing == ""
	})
	if failing == "" && callsClosures {
		// What a function value does is any function value's: each of them is reached.
		for _, closure := range l.closureRecords {
			if !visited[closure.function] {
				visited[closure.function] = true
				if failing = l.libraryFailure(l.result.Functions[closure.function].Body, visited); failing != "" {
					break
				}
			}
		}
	}
	return failing
}

// formatArguments are the arguments each number format takes without throwing.
var formatArguments = map[string][2]float64{"toExponential": {0, 100}, "toPrecision": {1, 100}, "toString": {2, 36}}

// constantWithin reports whether a value is a constant integer from low to high, which a call taking
// it can't fail on.
func constantWithin(value ir.Expression, low float64, high float64) bool {
	constant, isConstant := value.(ir.NumberConstant)
	return isConstant && constant.Value >= low && constant.Value <= high && (high == math.MaxFloat64 || constant.Value == math.Trunc(constant.Value)) && !math.IsInf(constant.Value, 0)
}

func isNormalizationForm(value ir.Expression, strings []string) bool {
	constant, isConstant := value.(ir.StringConstant)
	if !isConstant {
		return false
	}
	switch strings[constant.Index] {
	case "NFC", "NFD", "NFKC", "NFKD":
		return true
	}
	return false
}

// walk visits every IR statement and expression in a value, depth first, while visit says to go on
// into each. It doesn't go into a function's body: a call is visited as a call.
func walk(value any, visit func(node any) bool) {
	walkValue(reflect.ValueOf(value), visit)
}

var (
	expressionType = reflect.TypeOf((*ir.Expression)(nil)).Elem()
	statementType  = reflect.TypeOf((*ir.Statement)(nil)).Elem()
)

func walkValue(value reflect.Value, visit func(node any) bool) {
	switch value.Kind() {
	case reflect.Interface:
		if !value.IsNil() {
			walkValue(value.Elem(), visit)
		}
	case reflect.Slice:
		for index := 0; index < value.Len(); index++ {
			walkValue(value.Index(index), visit)
		}
	case reflect.Array:
		for index := 0; index < value.Len(); index++ {
			walkValue(value.Index(index), visit)
		}
	case reflect.Struct:
		if value.Type().Implements(expressionType) || value.Type().Implements(statementType) {
			if !visit(value.Interface()) {
				return
			}
		}
		for index := 0; index < value.NumField(); index++ {
			walkValue(value.Field(index), visit)
		}
	}
}

expression.go:
package lower

import (
	"errors"
	"reflect"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
)

// typeOf is what's left at runtime of the type the checker proved for a node: a number, a boolean or
// a string. A union counts when every member is the same one ('Fizz' | 'Buzz' is a string).
func (l *lowering) typeOf(node *ast.Node) (ir.Type, error) {
	if l.enumNeverIdentity(node, map[*ast.Node]bool{}) != nil {
		if symbol := l.flagValueSymbol(ast.SkipParentheses(node)); symbol != nil {
			if stored, known := l.representation(l.checker.GetTypeOfSymbol(symbol)); known {
				return stored, nil
			}
		}
		return ir.Number, nil
	}
	if ast.IsIdentifier(node) && l.exactPlainObject(node) {
		return ir.Object, nil
	}
	if node.Kind == ast.KindPropertyAccessExpression && l.checker.GetTypeAtLocation(node).Flags()&checker.TypeFlagsUndefined != 0 {
		// A field narrowed to undefined still occupies its declared slot, which may hold a packed
		// optional number or a different reference kind. Read that representation, not an object.
		if field := l.checker.GetSymbolAtLocation(node.Name()); field != nil {
			return l.typeOfSymbol(node, field)
		}
	}
	if l.checker.GetTypeAtLocation(node).Flags()&checker.TypeFlagsUndefined != 0 && (node.Kind == ast.KindVoidExpression || voidInitializer(node)) {
		return ir.Object, nil
	}
	if valueType, isKnown := l.representation(l.arrayPredicateObservedType(node)); isKnown {
		return valueType, nil
	}
	return 0, l.notYet(node, "a value of type "+l.checker.TypeToString(l.checker.GetTypeAtLocation(node)))
}

func (l *lowering) representation(proven *checker.Type) (ir.Type, bool) {
	proven = l.concrete(proven)
	if kind := l.typedArrayKind(proven); kind != 0 {
		return kind, true
	}
	flags := proven.Flags()
	if flags&(checker.TypeFlagsUnknown|checker.TypeFlagsNonPrimitive) != 0 {
		return ir.Union, true
	}
	if flags&checker.TypeFlagsIntersection != 0 {
		for _, part := range proven.Types() {
			if part.Flags()&checker.TypeFlagsNonPrimitive != 0 {
				return ir.Union, true
			}
		}
	}
	if l.nodeBufferType(proven, "Buffer") {
		return ir.Array, true
	}
	if flags&checker.TypeFlagsTypeParameter != 0 {
		// Inside a generic class, a type parameter is what this instantiation made it.
		substituted, isKnown := l.substitution[proven]
		return substituted, isKnown
	}
	if flags&checker.TypeFlagsIntersection != 0 {
		// Target & WeakBrand is what a Weak<Target> reads as where it's present: the target.
		if target := l.weakTarget(proven); target != nil {
			return l.representation(target)
		}
		return l.objectIntersection(proven)
	}
	switch {
	case flags&(checker.TypeFlagsNull|checker.TypeFlagsUndefined|checker.TypeFlagsVoid) != 0:
		return ir.Object, true
	case flags&checker.TypeFlagsNumberLike != 0:
		return ir.Number, true
	case flags&checker.TypeFlagsStringLike != 0:
		return ir.String, true
	case flags&checker.TypeFlagsBooleanLike != 0:
		return ir.Boolean, true
	case flags&checker.TypeFlagsObject != 0 && (l.checker.IsArrayType(proven) || l.isLibraryType(proven, "RegExpExecArray", "RegExpMatchArray", "RegExpIndicesArray")):
		return ir.Array, true
	case flags&checker.TypeFlagsObject != 0 && l.isLibraryType(proven, "Map", "ReadonlyMap", "Set", "ReadonlySet"):
		// A Set is held as a Map whose values aren't used (set.go).
		return ir.Map, true
	case flags&checker.TypeFlagsObject != 0 && !isClassInstance(proven) && (l.checker.IsTypeAssignableTo(l.checker.GetNumberType(), proven) || l.checker.IsTypeAssignableTo(l.checker.GetStringType(), proven) || l.checker.IsTypeAssignableTo(l.checker.GetBooleanType(), proven)):
		// Structural types such as {} admit primitives. Their slots must preserve
		// the runtime brand with the same boxes used for scalar/reference unions.
		return ir.Union, true
	case flags&checker.TypeFlagsObject != 0 && len(l.checker.GetSignaturesOfType(proven, checker.SignatureKindCall)) == 0:
		return ir.Object, true
	case flags&checker.TypeFlagsObject != 0:
		// An object with call signatures is a function, held as a closure.
		return ir.Closure, true
	case flags&checker.TypeFlagsUnion != 0:
		if l.includesNull(proven) && !dynamicObjectType(proven) {
			// Preserve the area's nullable reference and RegExp protocols. Only
			// differently stored members need the boxed union representation.
			boxed := l.includesUndefined(proven)
			for _, member := range proven.Types() {
				if member.Flags()&(checker.TypeFlagsNull|checker.TypeFlagsUndefined) != 0 {
					continue
				}
				of, known := l.representation(member)
				if !known {
					return 0, false
				}
				boxed = boxed || !of.IsReference() || of == ir.String || of == ir.Union
			}
			if boxed {
				return ir.Union, true
			}
		}
		var shared ir.Type
		mixed, weak := false, false
		for _, member := range proven.Types() {
			if member.Flags()&(checker.TypeFlagsUndefined|checker.TypeFlagsNull) != 0 {
				// undefined joins a union of references as a null pointer; it's checked below that
				// the rest are references.
				continue
			}
			if l.weakTarget(member) != nil {
				// Weak<Target> is (Target & WeakBrand) | undefined: kept weakly.
				weak = true
				continue
			}
			memberType, isKnown := l.representation(member)
			if !isKnown {
				return 0, false
			}
			if shared != 0 && memberType != shared {
				mixed = true
			}
			shared = memberType
		}
		if weak {
			return ir.Weak, shared == 0
		}
		if mixed {
			// Members held differently (string | number) are one Union, which holds undefined too.
			return ir.Union, true
		}
		if shared != 0 && !shared.IsReference() && l.includesUndefined(proven) {
			// number | undefined and boolean | undefined are each a present-and-value pair.
			if maybe := ir.Maybe(shared); maybe.IsMaybe() {
				return maybe, true
			}
			return 0, false
		}
		return shared, shared != 0
	}
	return 0, false
}

// isLibraryType reports whether a type is one of the library's, by name: Map, not a program's own
// interface that happens to be called Map.
func (l *lowering) isLibraryType(proven *checker.Type, names ...string) bool {
	symbol := proven.Symbol()
	if symbol == nil || len(symbol.Declarations) == 0 || !load.IsLibrary(ast.GetSourceFileOfNode(symbol.Declarations[0])) {
		return false
	}
	for _, name := range names {
		if symbol.Name == name {
			return true
		}
	}
	return false
}

func (l *lowering) includesUndefined(proven *checker.Type) bool {
	if proven.Flags()&checker.TypeFlagsUnion == 0 {
		return proven.Flags()&checker.TypeFlagsUndefined != 0
	}
	for _, member := range proven.Types() {
		if member.Flags()&checker.TypeFlagsUndefined != 0 {
			return true
		}
	}
	return false
}

func (l *lowering) includesNull(proven *checker.Type) bool {
	if proven.Flags()&checker.TypeFlagsUnion == 0 {
		return proven.Flags()&checker.TypeFlagsNull != 0
	}
	for _, member := range proven.Types() {
		if l.includesNull(member) {
			return true
		}
	}
	return false
}

// expression lowers a value. What's kept weakly (a Weak<Target> variable, field, element or map value)
// is read here as its target, so no value of a Weak type goes further; keeping one is fit's WeakOf.
func (l *lowering) expression(node *ast.Node) (ir.Expression, error) {
	if err := l.libraryIteratorUnsupportedUse(node); err != nil {
		return nil, err
	}
	if err := l.nodeBufferUnsupportedUse(node); err != nil {
		return nil, err
	}
	if err := l.regexUnsupportedUse(node); err != nil {
		return nil, err
	}
	value, err := l.value(node)
	if err == nil {
		if contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone); contextual != nil {
			if err := l.unknownView(node, l.checker.GetTypeAtLocation(node), contextual); err != nil {
				return nil, err
			}
		}
	}
	if err == nil && value.Type() != ir.Weak && l.checker.GetTypeAtLocation(node).Flags()&checker.TypeFlagsUndefined != 0 {
		if _, constant := value.(ir.Undefined); !constant {
			if contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone); contextual != nil {
				if to, known := l.representation(contextual); known && to != value.Type() && to != ir.Union && (to.IsMaybe() || to.IsReference()) {
					// Keep the read or call's effects when converting its only possible value.
					value = ir.Narrow{Value: ir.Box{Value: value}, To: to}
				}
			}
		}
	}
	if literal := ast.SkipParentheses(node).Kind; err == nil && value.Type().IsReference() && literal != ast.KindArrayLiteralExpression && literal != ast.KindObjectLiteralExpression {
		// The checker lets { v: Box } be seen as { v: Weak<Box> } and back, an array of Box as one of
		// Weak<Box>, and (x: Weak<Box>) => ... as (x: Box) => ...; but one keeps a handle where the
		// other keeps the target, so the same object, array or function can't be both. A tuple is held
		// as an object, so it can't be seen as an array either, here or anywhere inside. A literal is
		// made as the type it's written into, so it never differs.
		if contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone); contextual != nil {
			if own := l.checker.GetTypeAtLocation(node); !l.nodeBufferView(l.present(own), l.present(contextual)) && !l.nodeBufferReadArgument(node) && !l.nodeFSFileBufferArgument(node) {
				return nil, l.notYet(node, "Buffer or Hash viewed as another object type (native host internal slots)")
			}
			if own := l.checker.GetTypeAtLocation(node); !l.typedArraySetArgument(node) && !l.nodeBufferReadArgument(node) && !l.nodeFSFileBufferArgument(node) && !l.sameKeeping(own, contextual, map[[2]*checker.Type]bool{}) {
				if l.typedArrayKind(l.checker.GetNonNullableType(own)) != 0 {
					return nil, l.notYet(node, "a typed array seen through a structural view that loses its buffer representation")
				}
				return nil, l.notYet(node, "a "+l.checker.TypeToString(own)+" seen as a "+l.checker.TypeToString(contextual)+" (one keeps something weakly that the other keeps strongly)")
			} else if tuple, array := l.tupleSeenAsArray(own, contextual, map[[2]*checker.Type]bool{}); tuple != nil {
				return nil, l.notYet(node, "a "+l.checker.TypeToString(tuple)+" seen as a "+l.checker.TypeToString(array)+" (a tuple is held as an object, not an array, so far; write it as an array where it's made, or copy it into one: [pair[0], pair[1]])")
			}
		}
	}
	// Anything the check above doesn't see (a tuple inside a literal, or a union around it) is still
	// not yet: wherever a tuple flows into an array slot, at any depth.
	if skipped := ast.SkipParentheses(node); err == nil && skipped.Kind != ast.KindSpreadElement {
		if contextual := l.checker.GetContextualType(skipped, checker.ContextFlagsNone); contextual != nil && l.tupleWhereArrayGoes(l.checker.GetTypeAtLocation(skipped), contextual, 0) {
			return nil, l.notYet(skipped, "a tuple where an array goes (as "+l.checker.TypeToString(contextual)+")")
		}
	}
	if err != nil || value.Type() != ir.Weak {
		return value, err
	}
	read := l.checker.GetTypeAtLocation(node)
	to, present := ir.Object, false
	if target, isKnown := l.representation(read); isKnown && target != ir.Weak && read.Flags()&checker.TypeFlagsUndefined == 0 {
		// The checker narrowed it to present (Target & WeakBrand).
		to, present = target, true
	} else if read.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range read.Types() {
			if target := l.weakTarget(member); target != nil {
				if to, isKnown = l.representation(target); !isKnown {
					return nil, l.notYet(node, "a Weak of "+l.checker.TypeToString(target))
				}
			}
		}
	}
	if !to.IsReference() {
		return nil, l.notYet(node, "a Weak of "+l.checker.TypeToString(read))
	}
	return ir.WeakTarget{Value: value, To: to, Present: present}, nil
}

// sameKeeping reports whether a value of type from, seen as type to, keeps everything inside it the
// same way through both: every field to has, every element, map key and value, and every parameter
// and result of a function, Weak in both or in neither, all the way down.
func (l *lowering) sameKeeping(from *checker.Type, to *checker.Type, visited map[[2]*checker.Type]bool) bool {
	from, to = l.present(from), l.present(to)
	if from == nil || to == nil || from == to || visited[[2]*checker.Type{from, to}] {
		return true
	}
	visited[[2]*checker.Type{from, to}] = true
	if fromKind, toKind := l.typedArrayKind(from), l.typedArrayKind(to); fromKind != 0 || toKind != 0 {
		return fromKind != 0 && fromKind == toKind
	}
	if !l.nodeBufferView(from, to) {
		return false
	}
	same := func(inside, viewed *checker.Type) bool {
		fromKept, _ := l.kept(inside)
		toKept, _ := l.kept(viewed)
		return (fromKept == ir.Weak) == (toKept == ir.Weak) && l.sameKeeping(inside, viewed, visited)
	}
	fromSignatures := l.checker.GetSignaturesOfType(from, checker.SignatureKindCall)
	toSignatures := l.checker.GetSignaturesOfType(to, checker.SignatureKindCall)
	switch {
	case len(fromSignatures) > 0 && len(toSignatures) > 0:
		// A closure's slots have no dynamic type descriptor. A view changing a boxed union
		// to an unboxed scalar (or back) needs an adapter. References share the union pointer ABI.
		sameCallable := func(inside, viewed *checker.Type) bool {
			fromKept, _ := l.kept(inside)
			toKept, _ := l.kept(viewed)
			return !(fromKept == ir.Union && !toKept.IsReference() || toKept == ir.Union && !fromKept.IsReference()) && same(inside, viewed)
		}
		// Intrinsic callback adapters call the source signature, not the library's wider view.
		if declaration := toSignatures[0].Declaration(); declaration != nil && load.IsLibrary(ast.GetSourceFileOfNode(declaration)) {
			sameCallable = same
		}
		fromParameters, toParameters := fromSignatures[0].Parameters(), toSignatures[0].Parameters()
		if l.censusNeverRestSignature(toSignatures[0]) {
			toParameters = nil
		}
		for index := 0; index < len(fromParameters) && index < len(toParameters); index++ {
			if !sameCallable(l.checker.GetTypeOfSymbol(fromParameters[index]), l.checker.GetTypeOfSymbol(toParameters[index])) {
				return false
			}
		}
		return sameCallable(l.checker.GetReturnTypeOfSignature(fromSignatures[0]), l.checker.GetReturnTypeOfSignature(toSignatures[0]))
	case from.ObjectFlags()&checker.ObjectFlagsReference != 0 && to.ObjectFlags()&checker.ObjectFlagsReference != 0 && (l.checker.IsArrayType(from) || checker.IsTupleType(from) || l.isLibraryType(from, "Map", "ReadonlyMap", "Set", "ReadonlySet")):
		fromArguments, toArguments := l.typeArguments(from), l.typeArguments(to)
		for index := 0; index < len(fromArguments) && index < len(toArguments); index++ {
			if !same(fromArguments[index], toArguments[index]) {
				return false
			}
		}
	default:
		for _, viewed := range l.checker.GetPropertiesOfType(to) {
			if viewed.Flags&ast.SymbolFlagsMethod != 0 {
				continue
			}
			if inside := l.checker.GetPropertyOfType(from, viewed.Name); inside != nil && !same(l.checker.GetTypeOfSymbol(inside), l.checker.GetTypeOfSymbol(viewed)) {
				return false
			}
		}
	}
	return true
}

// tupleSeenAsArray finds, in a value of type from seen as type to, the first tuple seen as an array:
// at the top, or as an element, field, map key or value, parameter or result, all the way down as
// sameKeeping walks. It returns the tuple's type and the array's, or nils.
func (l *lowering) tupleSeenAsArray(from *checker.Type, to *checker.Type, visited map[[2]*checker.Type]bool) (*checker.Type, *checker.Type) {
	from, to = l.present(from), l.present(to)
	if from == nil || to == nil || from == to || visited[[2]*checker.Type{from, to}] {
		return nil, nil
	}
	visited[[2]*checker.Type{from, to}] = true
	if checker.IsTupleType(from) && !checker.IsTupleType(to) {
		return from, to
	}
	fromSignatures := l.checker.GetSignaturesOfType(from, checker.SignatureKindCall)
	toSignatures := l.checker.GetSignaturesOfType(to, checker.SignatureKindCall)
	switch {
	case len(fromSignatures) > 0 && len(toSignatures) > 0:
		// A function is handed the other's arguments, and its results are seen as the other's.
		fromParameters, toParameters := fromSignatures[0].Parameters(), toSignatures[0].Parameters()
		if l.censusNeverRestSignature(toSignatures[0]) {
			toParameters = nil
		}
		for index := 0; index < len(fromParameters) && index < len(toParameters); index++ {
			if tuple, array := l.tupleSeenAsArray(l.checker.GetTypeOfSymbol(toParameters[index]), l.checker.GetTypeOfSymbol(fromParameters[index]), visited); tuple != nil {
				return tuple, array
			}
		}
		return l.tupleSeenAsArray(l.checker.GetReturnTypeOfSignature(fromSignatures[0]), l.checker.GetReturnTypeOfSignature(toSignatures[0]), visited)
	case from.ObjectFlags()&checker.ObjectFlagsReference != 0 && to.ObjectFlags()&checker.ObjectFlagsReference != 0 && (l.checker.IsArrayType(from) || checker.IsTupleType(from) || l.isLibraryType(from, "Map", "ReadonlyMap", "Set", "ReadonlySet")):
		fromArguments, toArguments := l.typeArguments(from), l.typeArguments(to)
		if checker.IsTupleType(from) && l.checker.IsArrayType(to) {
			return from, to
		}
		for index := 0; index < len(fromArguments) && index < len(toArguments); index++ {
			if tuple, array := l.tupleSeenAsArray(fromArguments[index], toArguments[index], visited); tuple != nil {
				return tuple, array
			}
		}
	default:
		for _, viewed := range l.checker.GetPropertiesOfType(to) {
			if viewed.Flags&ast.SymbolFlagsMethod != 0 {
				continue
			}
			if inside := l.checker.GetPropertyOfType(from, viewed.Name); inside != nil {
				if tuple, array := l.tupleSeenAsArray(l.checker.GetTypeOfSymbol(inside), l.checker.GetTypeOfSymbol(viewed), visited); tuple != nil {
					return tuple, array
				}
			}
		}
	}
	return nil, nil
}

// present is a type without undefined, and a Weak's narrowing without its brand: the one object,
// array, map or function type it is, or nil when it's none or several.
func (l *lowering) present(proven *checker.Type) *checker.Type {
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		var only *checker.Type
		for _, member := range proven.Types() {
			if member.Flags()&(checker.TypeFlagsUndefined|checker.TypeFlagsNull) != 0 {
				continue
			}
			if only != nil {
				return nil
			}
			only = member
		}
		if only == nil {
			return nil
		}
		proven = only
	}
	if target := l.weakTarget(proven); target != nil {
		proven = target
	}
	if proven.Flags()&checker.TypeFlagsObject == 0 {
		return nil
	}
	return proven
}

// kept is how an element or a map's value of a type is kept: as its representation, except that one
// narrowed from a Weak (Node & WeakBrand, as filter(x => x !== undefined) or every leaves an array of
// Weak<Node>) is still a Weak, a handle, since that's what the array holds.
func (l *lowering) kept(proven *checker.Type) (ir.Type, bool) {
	if l.weakTarget(proven) != nil {
		return ir.Weak, true
	}
	return l.representation(proven)
}

// typeArguments is a generic type's arguments, Map<K, V>'s K and V, through a Weak's narrowing
// (Map<K, V> & WeakBrand), or nil for a type that has none.
func (l *lowering) typeArguments(proven *checker.Type) []*checker.Type {
	if target := l.weakTarget(proven); target != nil {
		proven = target
	}
	if proven.Flags()&checker.TypeFlagsObject == 0 || proven.ObjectFlags()&checker.ObjectFlagsReference == 0 {
		return nil
	}
	return l.checker.GetTypeArguments(proven)
}

// weakTarget is the Target of Target & WeakBrand, the present half of a Weak<Target>, or nil for
// any other type.
func (l *lowering) weakTarget(proven *checker.Type) *checker.Type {
	if proven.Flags()&checker.TypeFlagsIntersection == 0 {
		return nil
	}
	var target *checker.Type
	branded := false
	for _, member := range proven.Types() {
		if symbol := member.Symbol(); symbol != nil && symbol.Name == "WeakBrand" && len(symbol.Declarations) > 0 && load.IsPrelude(ast.GetSourceFileOfNode(symbol.Declarations[0])) {
			branded = true
		} else if target == nil {
			target = member
		} else {
			return nil
		}
	}
	if !branded {
		return nil
	}
	return target
}

// value lowers a value, as expression does, but leaves a Weak as it's kept.
func (l *lowering) value(node *ast.Node) (ir.Expression, error) {
	if identity := l.enumNeverIdentity(node, map[*ast.Node]bool{}); identity != nil {
		value, err := l.enumNeverValue(node)
		if err != nil {
			return nil, err
		}
		return l.enumNeverCheck(node, value, identity), nil
	}
	return l.enumNeverValue(node)
}

func (l *lowering) enumNeverValue(node *ast.Node) (ir.Expression, error) {
	node = ast.SkipParentheses(node)
	if value, handled, err := l.typedArrayExpression(node); handled {
		return value, err
	}
	if value, known, err := l.namespaceExpression(node); known {
		return value, err
	}
	if value, known, err := l.libraryMethodValue(node); known {
		return value, err
	}
	if l.isArgumentsLength(node) {
		return l.readArgumentsCount(), nil
	}
	if value, known, err := l.enumExpression(node); known {
		return value, err
	}
	if observed, known := l.libraryArrayObservation(node); known {
		return observed, nil
	}
	switch node.Kind {
	case ast.KindNullKeyword:
		return ir.Null{}, nil
	case ast.KindRegularExpressionLiteral:
		return l.regexConstant(node)
	case ast.KindNumericLiteral:
		return l.numericLiteral(node)
	case ast.KindStringLiteral, ast.KindNoSubstitutionTemplateLiteral:
		return ir.StringConstant{Index: l.constant(node.Text())}, nil
	case ast.KindTrueKeyword, ast.KindFalseKeyword:
		return ir.BooleanConstant{Value: node.Kind == ast.KindTrueKeyword}, nil
	case ast.KindIdentifier:
		if value, known, err := l.libraryGlobalValue(node); known {
			return value, err
		}
		if value, handled := l.staticClassRead(node); handled {
			return value, nil
		}
		if value, handled, err := l.nestedReference(node); handled {
			return value, err
		}
		local, isLocal := l.local(node)
		if !isLocal && node.Text() == "undefined" {
			return ir.Undefined{}, nil
		}
		if !isLocal && (l.isLibraryGlobal(node, "NaN") || l.isLibraryGlobal(node, "Infinity")) {
			return ir.NumberConstant{Value: numberConstants[node.Text()]}, nil
		}
		if function, isFunction := l.functions[l.symbol(node)]; !isLocal && isFunction {
			return l.functionValue(node, function)
		}
		if _, isGeneric := l.generics[l.symbol(node)]; !isLocal && isGeneric {
			return nil, l.notYet(node, "a generic function as a value")
		}
		if !isLocal && l.isLibraryGlobal(node, "String") {
			return nil, l.notYet(node, "reading String as a first-class constructor (its any-typed call signature, construction and static members need an intrinsic value representation)")
		}
		if !isLocal {
			return nil, l.notYet(node, "reading "+node.Text())
		}
		return l.localRead(node, local)
	case ast.KindVoidExpression:
		operand, err := l.discardedValue(node.AsVoidExpression().Expression)
		if err != nil {
			return nil, err
		}
		return ir.Void{Value: operand}, nil
	case ast.KindPrefixUnaryExpression:
		return l.prefix(node)
	case ast.KindTypeOfExpression:
		if l.isLibraryGlobal(node.AsTypeOfExpression().Expression, "Number") {
			return ir.StringConstant{Index: l.constant("function")}, nil
		}
		if value, intrinsic := l.stringTypeOf(node); intrinsic {
			return value, nil
		}
		operand, err := l.expression(node.AsTypeOfExpression().Expression)
		if err != nil {
			return nil, err
		}
		written := node.AsTypeOfExpression().Expression
		null := l.typeOfNull(written)
		if null && l.includesUndefined(l.concrete(l.checker.GetTypeAtLocation(written))) {
			switch operand.(type) {
			case ir.ArrayIndex, ir.MapGet, ir.ArrayPop:
				// The lookup still has a presence slot, so typeof can distinguish null from undefined.
			default:
				return nil, l.notYet(node, "typeof a value holding both null and undefined without a presence slot")
			}
		}
		return ir.TypeOf{Value: operand, Null: null}, nil
	case ast.KindBinaryExpression:
		binary := node.AsBinaryExpression()
		if _, compound := compoundAssignments[binary.OperatorToken.Kind]; compound || binary.OperatorToken.Kind == ast.KindEqualsToken {
			return l.assignmentValue(node)
		}
		if binary.OperatorToken.Kind == ast.KindCommaToken {
			return l.comma(node)
		}
		if logicalAssignment(binary.OperatorToken.Kind) {
			return l.logicalAssignment(node)
		}
		if binary.OperatorToken.Kind == ast.KindInKeyword {
			return l.inProperty(node)
		}
		if binary.OperatorToken.Kind == ast.KindQuestionQuestionToken {
			return l.coalesce(node)
		}
		if binary.OperatorToken.Kind == ast.KindInstanceOfKeyword {
			if lowered, isCaught := l.caughtInstanceOfError(node); isCaught {
				return lowered, nil
			}
			return l.classInstanceOf(node)
		}
		// A flow-narrowed never expression still reads its declared boolean slots.
		// Only a live result needs a placeholder for a non-returning arm.
		if (binary.OperatorToken.Kind == ast.KindBarBarToken || binary.OperatorToken.Kind == ast.KindAmpersandAmpersandToken) && l.isNever(binary.Right) && !l.isNever(node) {
			return l.logicalNever(node)
		}
		left, err := l.expression(binary.Left)
		if err != nil {
			return nil, err
		}
		right, err := l.expression(binary.Right)
		if err != nil {
			return nil, err
		}
		if binary.OperatorToken.Kind == ast.KindPlusToken {
			left, right = l.spelled(binary.Left, left), l.spelled(binary.Right, right)
		}
		return l.combine(node, binary.OperatorToken.Kind, left, right)
	case ast.KindTaggedTemplateExpression:
		return l.stringRawTemplate(node)
	case ast.KindTemplateExpression:
		return l.template(node)
	case ast.KindConditionalExpression:
		return l.conditional(node)
	case ast.KindObjectLiteralExpression:
		return l.objectLiteral(node)
	case ast.KindArrayLiteralExpression:
		return l.arrayLiteral(node)
	case ast.KindPropertyAccessExpression:
		return l.property(node)
	case ast.KindElementAccessExpression:
		return l.elementAccess(node)
	case ast.KindNewExpression:
		return l.newExpression(node)
	case ast.KindThisKeyword:
		if l.this < 0 {
			return nil, l.notYet(node, "this outside a method")
		}
		if err := l.useOfThis(node); err != nil {
			return nil, err
		}
		l.touch(l.this)
		return ir.Read{Local: l.this, Of: ir.Object}, nil
	case ast.KindArrowFunction:
		return l.closure(node)
	case ast.KindNonNullExpression:
		return l.nonNull(node)
	case ast.KindAsExpression:
		return l.cast(node)
	case ast.KindSatisfiesExpression:
		satisfies := node.AsSatisfiesExpression()
		if err := l.provenRelation(node, satisfies.Expression, l.checker.GetTypeAtLocation(satisfies.Type)); err != nil {
			return nil, err
		}
		return l.expression(satisfies.Expression)
	case ast.KindFunctionExpression:
		return l.functionExpression(node)
	case ast.KindCallExpression:
		if value, known, err := l.optionalIntrinsic(node); known {
			return value, err
		}
		if err := l.optionalCall(node); err != nil {
			return nil, err
		}
		if lowered, isBuiltin, err := l.builtin(node); isBuiltin {
			if err == nil && lowered.Type() == 0 {
				return ir.Effects{Body: []ir.Statement{ir.Evaluate{Value: lowered}}, Result: ir.Undefined{}}, nil
			}
			return lowered, err
		}
		call, err := l.callOrMethod(node)
		if err != nil {
			return nil, err
		}
		if call.Type() == 0 {
			return ir.Effects{Body: []ir.Statement{ir.Evaluate{Value: call}}, Result: ir.Undefined{}}, nil
		}
		return call, nil
	}
	return nil, l.notYet(node, describe(node))
}

// fit makes a value fit where a value of type to goes: a number or a boolean, or undefined, where
// number | undefined or boolean | undefined goes, since that is two words and they are one. It also
// unwraps a maybe value the checker narrowed to its present type. Anything else is left as it is.
func fit(value ir.Expression, to ir.Type) ir.Expression {
	if discarded, ok := value.(ir.Void); ok && (to.IsMaybe() || to.IsReference()) {
		discarded.Of = to
		return discarded
	}
	if to == ir.Weak && value != nil && value.Type() != ir.Weak {
		return ir.WeakOf{Value: value}
	}
	if to == ir.Union && value != nil && value.Type() != ir.Union {
		return ir.Box{Value: value}
	}
	if _, isNull := value.(ir.Null); isNull && to.IsReference() && to != ir.Union {
		return ir.Null{Of: to}
	}
	if _, isUndefined := value.(ir.Undefined); isUndefined && to.IsReference() && to != ir.Union {
		// undefined going where a string, an array or a function may be missing is that reference,
		// missing: typed as it, so the C holding it is.
		return ir.Undefined{Of: to}
	}
	if !to.IsMaybe() || value == nil {
		if value != nil && value.Type().IsMaybe() && value.Type().Present() == to {
			return ir.Unwrap{Value: value}
		}
		return value
	}
	if value.Type() == to.Present() {
		return ir.MaybeOf{Value: value, Of: to}
	}
	if _, isUndefined := value.(ir.Undefined); isUndefined {
		return ir.MaybeOf{Of: to}
	}
	return value
}

// numericLiteral is the value the checker read from the literal, so 0x1F, 1_000 and 1e3 all mean
// what JavaScript says they mean without a second parser here.
func (l *lowering) numericLiteral(node *ast.Node) (ir.Expression, error) {
	literal := l.checker.GetTypeAtLocation(node)
	if literal.Flags()&checker.TypeFlagsNumberLiteral == 0 {
		return nil, errors.New("lower: " + l.program.Where(node) + ": the checker gave a numeric literal a type that isn't a number literal")
	}
	value := reflect.ValueOf(literal.AsLiteralType().Value())
	if value.Kind() != reflect.Float64 {
		return nil, errors.New("lower: " + l.program.Where(node) + ": a numeric literal's value isn't a float64")
	}
	return ir.NumberConstant{Value: value.Float()}, nil
}

func (l *lowering) prefix(node *ast.Node) (ir.Expression, error) {
	prefix := node.AsPrefixUnaryExpression()
	if prefix.Operator == ast.KindPlusPlusToken || prefix.Operator == ast.KindMinusMinusToken {
		operand := ast.SkipParentheses(prefix.Operand)
		if !ast.IsIdentifier(operand) {
			return nil, l.notYet(node, "a prefix update value whose target is not a plain name")
		}
		local, known := l.local(operand)
		if !known || l.result.Locals[local].Type != ir.Number {
			return nil, l.notYet(node, "a prefix update value whose name is not stored as a number")
		}
		// An immediately called helper makes the write and resulting read one expression.
		// Capturing a local carries its existing cell, so the caller observes the write.
		index := len(l.result.Functions)
		l.result.Functions = append(l.result.Functions, ir.Function{Name: "prefix_update", Closure: true, Returns: ir.Number})
		outerIndex := l.functionIndex
		l.functionIndex = index
		l.closures = append(l.closures, index)
		body, err := l.increment(node)
		var value ir.Expression
		if err == nil {
			value, err = l.expression(operand)
		}
		l.closures = l.closures[:len(l.closures)-1]
		l.functionIndex = outerIndex
		if err != nil {
			return nil, err
		}
		if value.Type() != ir.Number {
			return nil, l.notYet(node, "a prefix update of a non-number")
		}
		l.result.Functions[index].Body = append(body, ir.Return{Value: value})
		return ir.CallClosure{Closure: ir.MakeClosure{Function: index}, Returns: ir.Number}, nil
	}
	if prefix.Operator == ast.KindPlusToken || prefix.Operator == ast.KindMinusToken || prefix.Operator == ast.KindTildeToken {
		operand, err := l.libraryNumber(prefix.Operand)
		if err != nil {
			return nil, err
		}
		operator := ir.Plus
		if prefix.Operator == ast.KindMinusToken {
			operator = ir.Negate
		}
		if prefix.Operator == ast.KindTildeToken {
			operator = ir.BitNot
		}
		return ir.Unary{Operator: operator, Operand: operand}, nil
	}
	operand, err := l.expression(prefix.Operand)
	if err != nil {
		return nil, err
	}
	if prefix.Operator == ast.KindExclamationToken {
		return ir.Unary{Operator: ir.Not, Operand: censusCondition(operand)}, nil
	}
	return nil, l.notYet(node, describe(node)+" on a "+typeName(operand.Type()))
}

var arithmetic = map[ast.Kind]ir.Operator{
	ast.KindPlusToken:             ir.Add,
	ast.KindMinusToken:            ir.Subtract,
	ast.KindAsteriskToken:         ir.Multiply,
	ast.KindSlashToken:            ir.Divide,
	ast.KindPercentToken:          ir.Remainder,
	ast.KindAsteriskAsteriskToken: ir.Power,
}

// bitwise are the binary bitwise operators, on two numbers.
var bitwise = map[ast.Kind]ir.Operator{
	ast.KindAmpersandToken:                         ir.BitAnd,
	ast.KindBarToken:                               ir.BitOr,
	ast.KindCaretToken:                             ir.BitXor,
	ast.KindLessThanLessThanToken:                  ir.ShiftLeft,
	ast.KindGreaterThanGreaterThanToken:            ir.ShiftRight,
	ast.KindGreaterThanGreaterThanGreaterThanToken: ir.ShiftRightUnsigned,
}

var comparisons = map[ast.Kind]ir.Operator{
	ast.KindLessThanToken:          ir.Less,
	ast.KindLessThanEqualsToken:    ir.LessOrEqual,
	ast.KindGreaterThanToken:       ir.Greater,
	ast.KindGreaterThanEqualsToken: ir.GreaterOrEqual,
}

// combine lowers a binary operator on two lowered operands.
func (l *lowering) combine(node *ast.Node, operator ast.Kind, left ir.Expression, right ir.Expression) (ir.Expression, error) {
	both := func(want ir.Type) bool { return left.Type() == want && right.Type() == want }
	if operator == ast.KindPlusToken && (left.Type() == ir.String || right.Type() == ir.String) {
		spell := func(value ir.Expression) ir.Expression {
			switch value.Type() {
			case ir.Number:
				return ir.NumberToString{Value: value}
			case ir.Boolean:
				return ir.BooleanToString{Value: value}
			}
			return value
		}
		left, right = spell(left), spell(right)
	}
	if operator == ast.KindPlusToken && both(ir.String) {
		return ir.Concat{Parts: []ir.Expression{left, right}}, nil
	}
	if lowered, isArithmetic := arithmetic[operator]; isArithmetic && both(ir.Number) {
		return ir.Binary{Operator: lowered, Left: left, Right: right}, nil
	}
	if lowered, isBitwise := bitwise[operator]; isBitwise && both(ir.Number) {
		return ir.Binary{Operator: lowered, Left: left, Right: right}, nil
	}
	if lowered, isComparison := comparisons[operator]; isComparison && (both(ir.Number) || both(ir.String)) {
		// Strings compare in UTF-16 code unit order, as JavaScript's do.
		return ir.Binary{Operator: lowered, Left: left, Right: right}, nil
	}
	if operator == ast.KindEqualsEqualsEqualsToken || operator == ast.KindExclamationEqualsEqualsToken {
		_, leftNull := left.(ir.Null)
		_, rightNull := right.(ir.Null)
		if leftNull != rightNull {
			value := left
			if leftNull {
				value = right
			}
			if !value.Type().IsReference() {
				return nil, l.notYet(node, "null comparison with a scalar")
			}
			operand := node.AsBinaryExpression().Left
			if leftNull {
				operand = node.AsBinaryExpression().Right
			}
			test := ir.Expression(ir.IsNull{Value: value, AlwaysFalse: value.Type() != ir.Union && !l.includesNull(l.checker.GetTypeAtLocation(operand))})
			if operator == ast.KindExclamationEqualsEqualsToken {
				test = ir.Unary{Operator: ir.Not, Operand: test}
			}
			return test, nil
		}
		// x === undefined tests for a missing reference, whatever x's type.
		_, leftUndefined := left.(ir.Undefined)
		_, rightUndefined := right.(ir.Undefined)
		if leftUndefined != rightUndefined {
			value := left
			if leftUndefined {
				value = right
			}
			if pair := ir.Maybe(value.Type()); pair.IsMaybe() {
				// A number or a boolean the checker narrowed to present: still evaluated, and never
				// undefined.
				value = fit(value, pair)
			}
			if !value.Type().IsReference() && !value.Type().IsMaybe() {
				return nil, l.notYet(node, "comparing a "+typeName(value.Type())+" with undefined")
			}
			test := ir.Expression(ir.IsUndefined{Value: value})
			operand := node.AsBinaryExpression().Left
			if leftUndefined {
				operand = node.AsBinaryExpression().Right
			}
			if value.Type() != ir.Union && l.includesNull(l.checker.GetTypeAtLocation(operand)) {
				test = ir.IsNull{Value: value, AlwaysFalse: true}
			}
			if operator == ast.KindExclamationEqualsEqualsToken {
				test = ir.Unary{Operator: ir.Not, Operand: test}
			}
			return test, nil
		}
	}
	if (operator == ast.KindEqualsEqualsEqualsToken || operator == ast.KindExclamationEqualsEqualsToken) && left.Type() != right.Type() {
		// A pair against what it holds, or against another pair: each made a pair, and compared as one.
		if pair := left.Type(); pair.IsMaybe() && right.Type() == pair.Present() {
			right = fit(right, pair)
		} else if pair := right.Type(); pair.IsMaybe() && left.Type() == pair.Present() {
			left = fit(left, pair)
		} else if left.Type() == ir.Union || right.Type() == ir.Union {
			// A union against anything: both as unions, compared by member and value.
			left, right = fit(left, ir.Union), fit(right, ir.Union)
		}
	}
	if (operator == ast.KindEqualsEqualsEqualsToken || operator == ast.KindExclamationEqualsEqualsToken) && left.Type() == right.Type() {
		lowered := ir.Equal
		if operator == ast.KindExclamationEqualsEqualsToken {
			lowered = ir.NotEqual
		}
		return ir.Binary{Operator: lowered, Left: left, Right: right}, nil
	}
	if value, known := l.censusBooleanLogical(node, operator, left, right); known {
		return value, nil
	}
	if operator == ast.KindAmpersandAmpersandToken || operator == ast.KindBarBarToken {
		if !both(ir.Boolean) {
			of, err := l.typeOf(node)
			if err != nil {
				return nil, err
			}
			return ir.Logical{Left: left, Right: fit(right, of), Of: of, KeepTruthy: operator == ast.KindBarBarToken}, nil
		}
		lowered := ir.And
		if operator == ast.KindBarBarToken {
			lowered = ir.Or
		}
		return ir.Binary{Operator: lowered, Left: left, Right: right}, nil
	}

	return nil, l.notYet(node, describe(node)+" with a "+typeName(left.Type())+" and a "+typeName(right.Type()))
}

// spelled is a string as + and a template write it: one that may be missing (a null reference) is
// written "undefined", as JavaScript writes it.
func (l *lowering) spelled(node *ast.Node, value ir.Expression) ir.Expression {
	if value.Type() != ir.String || !(l.includesUndefined(l.checker.GetTypeAtLocation(node)) || l.narrowedAway(ast.SkipParentheses(node))) {
		return value
	}
	return ir.Coalesce{Value: value, Fallback: ir.StringConstant{Index: l.constant("undefined")}, Of: ir.String}
}

// template lowers a template literal to a Concat, writing each value as String() would.
func (l *lowering) template(node *ast.Node) (ir.Expression, error) {
	template := node.AsTemplateExpression()
	parts := []ir.Expression{}
	if head := template.Head.Text(); head != "" {
		parts = append(parts, ir.StringConstant{Index: l.constant(head)})
	}
	for _, span := range template.TemplateSpans.Nodes {
		value, err := l.expression(span.AsTemplateSpan().Expression)
		if err != nil {
			return nil, err
		}
		switch value.Type() {
		case ir.Number:
			value = ir.NumberToString{Value: value}
		case ir.Boolean:
			value = ir.BooleanToString{Value: value}
		case ir.MaybeNumber, ir.MaybeBoolean:
			value = ir.MaybeToString{Value: value}
		case ir.Union:
			if !l.writable(l.arrayPredicateObservedType(span.AsTemplateSpan().Expression)) {
				return nil, l.notYet(span, "a template interpolating a union with an object, an array, a map or a function in it")
			}
			value = ir.UnionToString{Value: value}
		case ir.String:
			value = l.spelled(span.AsTemplateSpan().Expression, value)
		default:
			// JavaScript writes an object as "[object Object]", an array as its join, and a function as
			// its source; 0.1 has no use for any of it.
			return nil, l.notYet(span, "a template interpolating an object, an array, a map, a function or undefined")
		}
		parts = append(parts, value)
		if literal := span.AsTemplateSpan().Literal.Text(); literal != "" {
			parts = append(parts, ir.StringConstant{Index: l.constant(literal)})
		}
	}
	return ir.Concat{Parts: parts}, nil
}

func (l *lowering) conditional(node *ast.Node) (ir.Expression, error) {
	if branch := l.literalCallableBranch(node); branch != nil {
		return l.expression(branch)
	}
	conditional := node.AsConditionalExpression()
	condition, err := l.condition(conditional.Condition)
	if err != nil {
		return nil, err
	}
	if l.isNever(conditional.WhenTrue) || l.isNever(conditional.WhenFalse) {
		return l.conditionalNever(node, condition)
	}
	whenTrue, err := l.expression(conditional.WhenTrue)
	if err != nil {
		return nil, err
	}
	whenNot, err := l.expression(conditional.WhenFalse)
	if err != nil {
		return nil, err
	}
	if whenTrue.Type() != whenNot.Type() && l.acceptsUndefined(node) {
		// A stale narrowing in either branch may still hold undefined. Keep that representation
		// when the whole conditional is observed or written into a slot that accepts it.
		if pair := whenTrue.Type(); pair.IsMaybe() && whenNot.Type() == pair.Present() {
			whenNot = fit(whenNot, pair)
		} else if pair := whenNot.Type(); pair.IsMaybe() && whenTrue.Type() == pair.Present() {
			whenTrue = fit(whenTrue, pair)
		}
	}
	if whenTrue.Type() != whenNot.Type() {
		// flag ? 1 : undefined is number | undefined, and flag ? 1 : 'one' a union: each branch made
		// one.
		if of, err := l.typeOf(node); err == nil && (of.IsMaybe() || of == ir.Union || of.IsReference()) {
			whenTrue, whenNot = fit(whenTrue, of), fit(whenNot, of)
		}
	}
	if whenTrue.Type() != whenNot.Type() {
		// flag ? text : undefined is a reference that may be missing, held as text is, with undefined
		// the null one: the checker's type for the whole says which.
		_, trueUndefined := whenTrue.(ir.Undefined)
		_, notUndefined := whenNot.(ir.Undefined)
		present := whenTrue
		if trueUndefined {
			present = whenNot
		}
		if of, err := l.typeOf(node); err == nil && trueUndefined != notUndefined && present.Type().IsReference() && of == present.Type() {
			return ir.Conditional{Condition: condition, WhenTrue: whenTrue, WhenNot: whenNot, Of: of}, nil
		}
		return nil, l.notYet(node, "a conditional whose branches have different types")
	}
	return ir.Conditional{Condition: condition, WhenTrue: whenTrue, WhenNot: whenNot}, nil
}

func typeName(valueType ir.Type) string {
	if valueType.IsTypedArray() {
		return typedArrayName(valueType)
	}
	switch valueType {
	case ir.Number:
		return "number"
	case ir.Boolean:
		return "boolean"
	case ir.String:
		return "string"
	case ir.MaybeNumber:
		return "number | undefined"
	case ir.MaybeBoolean:
		return "boolean | undefined"
	case ir.Union:
		return "union of differently held members"
	}
	return "value"
}

// writable reports whether every member of a union is one a template writes: a number, a boolean, a
// string or undefined.
func (l *lowering) writable(proven *checker.Type) bool {
	// Judge the members this instantiation stores, rather than the generic binder.
	proven = l.concrete(proven)
	members := []*checker.Type{proven}
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		members = proven.Types()
	}
	for _, member := range members {
		if member.Flags()&checker.TypeFlagsUndefined != 0 {
			continue
		}
		memberType, isKnown := l.representation(member)
		if !isKnown || (memberType != ir.Number && memberType != ir.Boolean && memberType != ir.String) {
			return false
		}
	}
	return true
}

// slotless reports whether a value of the type can't yet be held in one word: a field, an element, a
// map's value, a cell, or a function value's argument or result. number | undefined is packed into
// one (a reserved NaN is undefined); boolean | undefined has a tagged byte for object fields
// (censusFieldSlotless), but remains unsupported in the other slot contexts, and a
// Union has to be boxed on its way in, which stage 0 does only where a variable, a parameter or a
// result takes one.
func slotless(valueType ir.Type) bool {
	return valueType == ir.MaybeBoolean || valueType == ir.Union
}

// call lowers a call to one of the module's functions, or to a function value.
func (l *lowering) call(node *ast.Node) (ir.Expression, error) {
	call := node.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	if direct := l.nestedSibling(callee); direct >= 0 {
		arguments := []ir.Expression{}
		for _, argument := range call.Arguments.Nodes {
			value, err := l.expression(argument)
			if err != nil {
				return nil, err
			}
			position := len(arguments)
			if position < len(l.result.Functions[direct].Parameters) {
				value = fit(value, l.result.Locals[l.result.Functions[direct].Parameters[position]].Type)
			}
			arguments = append(arguments, value)
		}
		carrier := ir.Expression(ir.ClosureSelf{})
		if l.function.NestedParent != l.result.Functions[direct].NestedParent {
			// Anonymous captures have their own layout. Materialize a temporary carrier
			// for the target layout; do not capture a sibling's canonical function value.
			carrier = ir.MakeClosure{Function: direct}
		}
		return ir.CallClosure{Closure: carrier, Direct: direct + 1, Arguments: arguments, Returns: l.result.Functions[direct].Returns}, nil
	}
	qualified := l.namespaceMember(callee)
	if declaration, isGeneric := l.generics[l.symbol(callee)]; (ast.IsIdentifier(callee) || qualified) && isGeneric {
		instance, err := l.instantiateFunction(node, declaration)
		if err != nil {
			return nil, err
		}
		if l.result.Functions[instance].Closure {
			arguments := []ir.Expression{}
			for position, argument := range call.Arguments.Nodes {
				value, err := l.expression(argument)
				if err != nil {
					return nil, err
				}
				if position < len(l.result.Functions[instance].Parameters) {
					value = fit(value, l.result.Locals[l.result.Functions[instance].Parameters[position]].Type)
				}
				arguments = append(arguments, value)
			}
			value := ir.CallClosure{Closure: ir.MakeClosure{Function: instance}, Arguments: arguments, Returns: l.result.Functions[instance].Returns}
			return l.namespaceReadyCall(callee, value), nil
		}
		value, err := l.callFunction(call, instance)
		if err == nil {
			value = l.namespaceReadyCall(callee, value)
		}
		return value, err
	}
	function, isFunction := l.functions[l.symbol(callee)]
	if (!ast.IsIdentifier(callee) && !qualified) || !isFunction {
		if calleeType, _ := l.representation(l.checker.GetTypeAtLocation(callee)); calleeType == ir.Closure {
			return l.callClosure(node)
		}
		return nil, l.notYet(node, "a call to "+describe(callee))
	}
	value, err := l.callFunction(call, function)
	if err == nil {
		value = l.namespaceReadyCall(callee, value)
	}
	return value, err
}

// callFunction lowers a call's arguments, in order, and the call to function.
func (l *lowering) callFunction(call *ast.CallExpression, function int) (ir.Expression, error) {
	arguments, spread, err := l.callArguments(call.Arguments.Nodes)
	if err != nil {
		return nil, err
	}
	l.fitCallArguments(function, arguments, spread)
	return l.censusOverloadResult(call, ir.Call{Function: function, Arguments: arguments, Spread: spread, Returns: l.result.Functions[function].Returns})
}

// coalesce lowers value ?? fallback, and value ?? panic('why'), evaluating the right side only when
// the left is missing.
func (l *lowering) coalesce(node *ast.Node) (ir.Expression, error) {
	binary := node.AsBinaryExpression()
	value, err := l.expression(binary.Left)
	if err != nil {
		return nil, err
	}
	// What ?? makes is the checker's: the left side's present members and the right side's, which
	// may be held differently (text ?? count is string | number, a Union).
	of, err := l.typeOf(node)
	if err != nil {
		return nil, err
	}
	if present := value.Type(); !present.IsMaybe() && !present.IsReference() {
		// A value that can't be missing: ?? never runs its right side.
		return fit(value, of), nil
	}
	right := ast.SkipParentheses(binary.Right)
	if right.Kind == ast.KindCallExpression && l.isPreludeFunction(right.AsCallExpression().Expression, "panic") && len(right.AsCallExpression().Arguments.Nodes) == 1 {
		message, err := l.expression(right.AsCallExpression().Arguments.Nodes[0])
		if err != nil {
			return nil, err
		}
		return ir.Coalesce{Value: value, Panic: message, Of: of}, nil
	}
	if l.isNever(binary.Right) {
		fallback, err := l.neverValue(binary.Right, of)
		if err != nil {
			return nil, err
		}
		return ir.Coalesce{Value: value, Fallback: fallback, Of: of}, nil
	}
	fallback, err := l.expression(binary.Right)
	if err != nil {
		return nil, err
	}
	fallback = fit(fallback, of)
	if _, isUndefined := fallback.(ir.Undefined); fallback.Type() != of && !(isUndefined && of.IsReference()) {
		return nil, l.notYet(node, "?? whose sides have different types")
	}
	return ir.Coalesce{Value: value, Fallback: fallback, Of: of}, nil
}

// closure lowers an arrow function to a function of its own and the closure that captures it.
func (l *lowering) closure(node *ast.Node) (ir.Expression, error) {
	index := len(l.result.Functions)
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "closure", Closure: true})
	l.closureRecords = append(l.closureRecords, closureRecord{proven: l.concrete(l.checker.GetTypeAtLocation(node)), function: index, node: node})
	if l.instance != nil {
		l.instance.templates = append(l.instance.templates, template{closure: index, proven: l.checker.GetTypeAtLocation(node), isClosure: true})
	}
	l.closures = append(l.closures, index)
	err := l.lowerFunction(index, node, -1)
	l.closures = l.closures[:len(l.closures)-1]
	if err != nil {
		return nil, err
	}
	return ir.MakeClosure{Function: index}, nil
}

// functionValue makes one stable adapter per named function. It binds optional
// and rest parameters and forwards the original count, even though its ordinary
// parameters have been padded or collected before reaching the target.
func (l *lowering) functionValue(node *ast.Node, target int) (ir.Expression, error) {
	symbol := l.symbol(node)
	if node.Kind == ast.KindShorthandPropertyAssignment {
		symbol = l.checker.GetShorthandAssignmentValueSymbol(node)
		if symbol != nil && symbol.Flags&ast.SymbolFlagsAlias != 0 {
			symbol = l.checker.GetAliasedSymbol(symbol)
		}
		symbol = l.checker.GetExportSymbolOfSymbol(symbol)
	}
	if symbol != nil {
		for _, declaration := range symbol.Declarations {
			if declaration.Kind == ast.KindFunctionDeclaration && declaration.Body() == nil && l.censusImplementation(declaration) != nil {
				return nil, l.notYet(node, "an overloaded function as a value")
			}
		}
	}
	if held, isMade := l.forwarders[target]; isMade {
		return ir.Read{Local: held, Of: ir.Closure}, nil
	}
	for _, parameter := range symbol.Declarations[0].Parameters() {
		if parameter.Name().Text() == "this" {
			return nil, l.notYet(parameter, "a function with a this parameter used as a value; pass the receiver explicitly or use an arrow")
		}
	}
	callee := l.result.Functions[target]
	if censusCallableSlotless(callee.Returns) {
		return nil, l.notYet(node, "a function value returning "+typeName(callee.Returns))
	}
	index := len(l.result.Functions)
	forwarder := ir.Function{Name: callee.Name + "_value", Closure: true, Returns: callee.Returns, RestElement: callee.RestElement, ForwardsArguments: target + 1}
	arguments := []ir.Expression{}
	for _, parameter := range callee.Parameters {
		declared := l.result.Locals[parameter]
		if censusCallableSlotless(declared.Type) {
			return nil, l.notYet(node, "a function value taking "+typeName(declared.Type))
		}
		local := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: declared.Name, Type: declared.Type, Function: index})
		forwarder.Parameters = append(forwarder.Parameters, local)
		arguments = append(arguments, ir.Read{Local: local, Of: declared.Type})
	}
	call := ir.Call{Function: target, Arguments: arguments, Returns: callee.Returns, ForwardCount: true, RestPacked: true}
	if callee.Returns == 0 {
		forwarder.Body = []ir.Statement{ir.Evaluate{Value: call}}
	} else {
		forwarder.Body = []ir.Statement{ir.Return{Value: call}}
	}
	l.result.Functions = append(l.result.Functions, forwarder)
	l.closureRecords = append(l.closureRecords, closureRecord{proven: l.concrete(l.checker.GetTypeAtLocation(node)), function: index, node: node})
	// One function value for the function, made before anything runs and held by a global of its
	// own, so reading the function twice gives the same value, === as JavaScript's.
	held := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: callee.Name + "_value", Type: ir.Closure, Global: true, Function: -1})
	l.forwarderValues = append(l.forwarderValues, ir.Declare{Local: held, Value: ir.MakeClosure{Function: index}})
	if l.forwarders == nil {
		l.forwarders = map[int]int{}
	}
	l.forwarders[target] = held
	return ir.Read{Local: held, Of: ir.Closure}, nil
}

// optionalCall refuses a call in an optional chain, text?.toUpperCase() or run?.(): the receiver has
// to be evaluated once and tested before the call, which stage 0 doesn't lower yet for the library's
// methods or a function value called directly. Lowered as a plain call, it ran the method on
// undefined. The one form lowered is object?.method(...) on a method the program declares (a
// class's, an interface's, or a function value in a field): the call goes through the object's
// methods, which stops at undefined as JavaScript's chain does (ir.Property's Method).
func (l *lowering) optionalCall(call *ast.Node) error {
	if call.Flags&ast.NodeFlagsOptionalChain == 0 || l.isOptionalJoin(call) {
		return nil
	}
	callee := ast.SkipParentheses(call.AsCallExpression().Expression)
	if callee.Kind == ast.KindPropertyAccessExpression && callee.AsPropertyAccessExpression().QuestionDotToken != nil && call.AsCallExpression().QuestionDotToken == nil {
		if method := l.checker.GetSymbolAtLocation(callee); method != nil && len(method.Declarations) > 0 && !load.IsLibrary(ast.GetSourceFileOfNode(method.Declarations[0])) {
			return nil
		}
	}
	return l.notYet(call, "a call through ?. (an optional call)")
}

// callClosure lowers a call through a function value.
func (l *lowering) callClosure(node *ast.Node) (ir.Expression, error) {
	signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(node.AsCallExpression().Expression), checker.SignatureKindCall)
	if len(signatures) == 1 && l.censusNeverRestSignature(signatures[0]) {
		// never[] admits a zero-argument call in TypeScript. The erased slot does
		// not retain a source signature to prove its required arguments or ABI.
		return nil, l.notYet(node, "a call through an erased never-rest callable marker")
	}
	closure, err := l.expression(node.AsCallExpression().Expression)
	if err != nil {
		return nil, err
	}
	if property, isProperty := closure.(ir.Property); isProperty {
		// object.name(...) through an interface: the object may be a class's, whose methods aren't
		// fields (ir.Property's Method).
		property.Method = true
		closure = property
	}
	arguments, spread, err := l.callArguments(node.AsCallExpression().Arguments.Nodes)
	if err != nil {
		return nil, err
	}
	var returns ir.Type
	if result := l.concrete(l.checker.GetTypeAtLocation(node)); result.Flags()&(checker.TypeFlagsVoid|checker.TypeFlagsNever) == 0 {
		var isKnown bool
		if returns, isKnown = l.representation(result); !isKnown {
			return nil, l.notYet(node, "a call returning "+l.checker.TypeToString(result))
		}
	}
	// Each argument is made what the function value takes: a number or undefined where it takes
	// number | undefined is packed as one.
	if signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(node.AsCallExpression().Expression), checker.SignatureKindCall); len(signatures) == 1 {
		parameters := signatures[0].Parameters()
		position := 0
		expanded := false
		for index := range arguments {
			if len(spread) > index && spread[index] {
				expanded = true
				continue
			}
			if len(parameters) == 0 {
				break
			}
			parameter := parameters[min(position, len(parameters)-1)]
			rest := len(parameter.Declarations) > 0 && parameter.Declarations[0].Kind == ast.KindParameter && parameter.Declarations[0].AsParameterDeclaration().DotDotDotToken != nil
			proven := l.checker.GetTypeOfSymbol(parameter)
			if rest {
				elements := l.checker.GetTypeArguments(proven)
				if len(elements) == 1 {
					proven = elements[0]
				}
			} else if expanded || position >= len(parameters) {
				position++
				continue
			}
			if takes, known := l.representation(proven); known {
				// The checker describes a defaulted parameter by its present type,
				// but its incoming slot must preserve undefined until the body runs.
				if !rest && len(parameter.Declarations) > 0 && parameter.Declarations[0].Kind == ast.KindParameter && parameter.Declarations[0].AsParameterDeclaration().Initializer != nil {
					takes = ir.Maybe(takes)
				}
				arguments[index] = fit(arguments[index], takes)
			}
			position++
		}
	}
	for _, argument := range arguments {
		if censusCallableSlotless(argument.Type()) {
			return nil, l.notYet(node, "passing "+typeName(argument.Type())+" to a function value")
		}
	}
	if censusCallableSlotless(returns) {
		return nil, l.notYet(node, "a function value returning "+typeName(returns))
	}
	return ir.CallClosure{Closure: closure, Arguments: arguments, Spread: spread, FunctionType: int(l.concrete(l.checker.GetTypeAtLocation(node.AsCallExpression().Expression)).Id()), Returns: returns}, nil
}

// Optional booleans have a three-state byte in the function-call ABI.
// General union arguments still need a representation adapter.
func argumentSlotless(valueType ir.Type) bool { return valueType == ir.Union }

fresh.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/fresh"
)

// The cycle finder's relaxation for fresh writes (docs/memory.md). The finder refuses every mutable
// slot whose type can reach back to its holder; a slot stands undeclared when every write into it in
// the whole program is proven not to close a cycle (fresh.ProveWrites). Lowering records, for each
// write it makes, the type of what it writes into, so a write the proof can't vouch for keeps every
// slot it could be writing refused, through any view of the holder, as the finder's related matches
// views.

// writeSite is one write lowering made: the type of what it writes into, as the instantiation being
// lowered sees it, and where.
type writeSite struct {
	holder *checker.Type
	node   *ast.Node
}

// writeSite records a write into receiver's slots, and is the IR node's Site.
func (l *lowering) writeSite(receiver *ast.Node) int {
	holder := l.concrete(l.checker.GetTypeAtLocation(receiver))
	if ast.SkipParentheses(receiver).Kind == ast.KindThisKeyword && l.classType != nil {
		// this is the polymorphic this type, a type parameter; the instantiation being lowered is what
		// it stands for here.
		holder = l.classType
	}
	l.writeSites = append(l.writeSites, writeSite{holder: holder, node: receiver})
	return len(l.writeSites)
}

// unproven is the first write in the program that may write a slot of kind in holder (a field by
// its name) and isn't proven not to close a cycle, or nil when every such write is.
func (f *cycleFinder) unproven(kind fresh.WriteKind, holder *checker.Type, name string) *fresh.Write {
	if f.writes == nil {
		f.writes = fresh.ProveWrites(f.l.result)
	}
	for index := range f.writes {
		write := &f.writes[index]
		if write.Proven {
			continue
		}
		if write.Kind == fresh.WriteUnknown {
			return write
		}
		if write.Kind != kind || (kind == fresh.WriteField && !f.l.cycleFieldMatches(holder, name, write.Name)) {
			continue
		}
		if write.Site == 0 {
			// A write lowering didn't record: it may be into anything of its kind.
			return write
		}
		written := f.l.writeSites[write.Site-1].holder
		if written == nil || f.template(written) || f.related(holder, written) {
			return write
		}
	}
	return nil
}

// writtenAt names an unproven write: where it is, or, for one lowering didn't record, what it is.
func (f *cycleFinder) writtenAt(write *fresh.Write) string {
	if write.Site == 0 {
		return "a write in " + f.l.functionName(write.Function)
	}
	return "the write at " + f.l.program.Where(f.l.writeSites[write.Site-1].node)
}

// functionName is an IR function's name, or the top level's.
func (l *lowering) functionName(function int) string {
	if function < 0 {
		return "the top level"
	}
	return l.result.Functions[function].Name
}

from.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// arrayFrom lowers Array.from({ length }, (_, index) => ...), the one form of Array.from 0.1 has
// (docs/0.1.md): a new array of length elements, each what the callback returns for its index.
//
// The object is never made. It has no elements, so what the callback receives first is always
// undefined; the checker types that parameter unknown, and it's lowered as a reference that's always
// missing (alwaysUndefined), which is exactly what it holds.
func (l *lowering) arrayFrom(node *ast.Node) (ir.Expression, bool, error) {
	arguments := node.AsCallExpression().Arguments.Nodes
	if len(arguments) > 0 {
		if plan, err := l.planIteration(arguments[0]); err != nil {
			return nil, true, err
		} else if plan != nil {
			if len(arguments) > 2 {
				return nil, true, l.notYet(node, "Array.from with thisArg")
			}
			element, err := l.elementType(node)
			if err != nil {
				return nil, true, err
			}
			var callback *ast.Node
			if len(arguments) == 2 {
				callback = arguments[1]
			}
			value, err := l.collectIteration(node, arguments[0], callback, plan, element)
			return value, true, err
		}
	}
	if len(arguments) != 2 {
		return nil, true, l.notYet(node, "Array.from with other than { length } and a callback")
	}
	source := ast.SkipParentheses(arguments[0])
	if source.Kind != ast.KindObjectLiteralExpression || len(source.AsObjectLiteralExpression().Properties.Nodes) != 1 {
		return nil, true, l.notYet(arguments[0], "Array.from of anything but { length }")
	}
	property := source.AsObjectLiteralExpression().Properties.Nodes[0]
	if (property.Kind != ast.KindPropertyAssignment && property.Kind != ast.KindShorthandPropertyAssignment) || !ast.IsIdentifier(property.Name()) || property.Name().Text() != "length" {
		return nil, true, l.notYet(arguments[0], "Array.from of anything but { length }")
	}
	element, err := l.elementType(node)
	if err != nil {
		return nil, true, err
	}
	var length ir.Expression
	if property.Kind == ast.KindPropertyAssignment {
		length, err = l.expression(property.AsPropertyAssignment().Initializer)
	} else {
		length, err = l.shorthand(property)
	}
	if err != nil {
		return nil, true, err
	}
	if length.Type() != ir.Number {
		return nil, true, l.notYet(property, "Array.from with a length that isn't a number")
	}
	callback := ast.SkipParentheses(arguments[1])
	if callback.Kind != ast.KindArrowFunction && callback.Kind != ast.KindFunctionExpression {
		// A function value from elsewhere would be typed (value: unknown, index: number), and an
		// unknown parameter isn't something stage 0 holds.
		return nil, true, l.notYet(arguments[1], "Array.from with a callback that isn't an arrow function written in place")
	}
	if parameters := callback.Parameters(); len(parameters) > 0 && ast.IsIdentifier(parameters[0].Name()) {
		received := l.checker.GetTypeAtLocation(parameters[0].Name())
		switch {
		case parameters[0].AsParameterDeclaration().Initializer != nil:
			// The incoming undefined selects the default before the body reads this parameter.
		case received.Flags()&(checker.TypeFlagsUnknown|checker.TypeFlagsUndefined) != 0:
			if l.alwaysUndefined == nil {
				l.alwaysUndefined = map[*ast.Symbol]bool{}
			}
			l.alwaysUndefined[l.symbol(parameters[0].Name())] = true
		case !l.includesUndefined(received):
			// The checker reads { length } as an array-like of whatever the parameter says, but
			// it has no elements: the parameter is undefined every time, whatever its type claims.
			return nil, true, &Refused{Where: l.program.Where(parameters[0]), What: "a first Array.from parameter typed " + l.checker.TypeToString(received) + ", which is undefined every time", Fix: "name it _ and leave it untyped, (_, index) => ..., or type it undefined (the type would be a lie the checker can't see)"}
		}
	}
	mapped, err := l.expression(callback)
	if err != nil {
		return nil, true, err
	}
	// What the callback receives first is undefined, held as its first parameter holds undefined: a
	// null reference, or a maybe scalar's packed word.
	var first ir.Type
	if closure, isClosure := mapped.(ir.MakeClosure); isClosure {
		if parameters := l.result.Functions[closure.Function].Parameters; len(parameters) > 0 {
			first = l.result.Locals[parameters[0]].Type
		}
	}
	return ir.ArrayFrom{Length: length, Callback: mapped, Element: element, First: first, CallbackType: int(l.concrete(l.checker.GetTypeAtLocation(callback)).Id())}, true, nil
}

functions.go:
// Functions and declarations moved unchanged from lower.go.
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// functionBody lowers a module function declaration's parameters and body.
func (l *lowering) functionBody(declaration *ast.Node) error {
	return l.lowerFunction(l.functions[l.symbol(declaration.Name())], declaration, -1)
}

// defaulted is a parameter with a default: the local the body declares, the one the argument arrives
// in, and the default.
type defaulted struct {
	local, incoming int
	initializer     *ast.Node
}

// signed is what a function whose signature is written still needs to lower its body: the local its
// this is, or -1, its parameters' defaults, and its destructured parameters.
type signed struct {
	this     int
	defaults []defaulted
	patterns []patterned
}

// patterned is a destructured parameter, ([key, value]) or ({ x, y }): the pattern, the parameter,
// and the local it arrives in whole.
type patterned struct {
	pattern   *ast.Node
	parameter *ast.Node
	incoming  int
}

// lowerFunction lowers a function-like declaration into the function at index: its signature, unless
// signature has written it already, then its body. this, when not -1, is the local a method's or
// constructor's this is, passed first.
//
// It works on a copy and writes it back by index: lowering a body can instantiate a class, which
// appends functions, and a pointer into the slice would be left pointing at the old one.
func (l *lowering) lowerFunction(index int, declaration *ast.Node, this int) error {
	if implementation := l.censusImplementation(declaration); implementation != nil {
		declaration = implementation
	}
	if _, isSigned := l.signed[index]; !isSigned {
		if err := l.signature(index, declaration, this); err != nil {
			return err
		}
	}
	pending := l.signed[index]
	delete(l.signed, index)
	return l.lowerBody(index, declaration, pending.this, pending.defaults, pending.patterns)
}

// signature writes the function at index's parameters and result, from the checker, without lowering
// its body, so a call to it lowers whether or not its body has been. this is as for lowerFunction.
func (l *lowering) signature(index int, declaration *ast.Node, this int) error {
	if implementation := l.censusImplementation(declaration); implementation != nil {
		declaration = implementation
	}
	if err := l.censusOverloads(declaration); err != nil {
		return err
	}
	function := l.result.Functions[index]
	if this >= 0 && declaration.Kind != ast.KindConstructor {
		// A method receives this; a constructor makes it.
		function.Parameters = append(function.Parameters, this)
		function.Receiver = true
	}
	if declaration.Kind != ast.KindConstructor {
		signature := l.checker.GetSignatureFromDeclaration(declaration)
		returns := l.concrete(l.checker.GetReturnTypeOfSignature(signature))
		// A function that never returns (it panics on every path, as (why) => panic(why) does) has no
		// result to hold, as one returning void hasn't. An arrow whose expression is never for another
		// reason, a variable the checker narrowed to nothing, isn't one.
		neverArrow := returns.Flags()&checker.TypeFlagsNever != 0 && declaration.Body() != nil && declaration.Body().Kind != ast.KindBlock && declaration.Body().Kind != ast.KindCallExpression && !l.isPanicCall(declaration.Body())
		if returns.Flags()&(checker.TypeFlagsVoid|checker.TypeFlagsNever) == 0 || neverArrow {
			valueType, isKnown := l.representation(returns)
			if returns.Flags()&checker.TypeFlagsUndefined != 0 {
				valueType, isKnown = ir.Object, true
			}
			if function.Closure && l.regexReplacementArgument(declaration) {
				if returns.Flags()&checker.TypeFlagsUndefined != 0 {
					valueType, isKnown = ir.String, true
				}
				if returns.Flags()&checker.TypeFlagsNull != 0 {
					valueType, isKnown = ir.Object, true
				}
			}
			if !isKnown {
				valueType, isKnown = l.clockGenericReturnsT01(returns)
			}
			if !isKnown {
				// An arrow function has no name to point at, so it's pointed at whole.
				where := declaration.Name()
				if where == nil {
					where = declaration
				}
				return l.notYet(where, "a function returning "+l.checker.TypeToString(returns))
			}
			function.Returns = valueType
		}
	}
	outerIndexForParameters := l.functionIndex
	l.functionIndex = index
	defer func() { l.functionIndex = outerIndexForParameters }()
	// A parameter with a default arrives as what may be missing, and the body begins by declaring the
	// parameter itself: the argument, or the default when it's undefined, as JavaScript decides.
	defaults := []defaulted{}
	// A destructured parameter, ([key, value]) or ({ x, y }), arrives whole in a parameter of its own,
	// and its names are declared from it before the body runs.
	patterns := []patterned{}
	for position, parameter := range declaration.Parameters() {
		declared := parameter.AsParameterDeclaration()
		if name := parameter.Name(); (name.Kind == ast.KindArrayBindingPattern || name.Kind == ast.KindObjectBindingPattern) && declared.DotDotDotToken == nil && declared.Initializer == nil && declared.QuestionToken == nil {
			incoming := len(l.result.Locals)
			l.result.Locals = append(l.result.Locals, ir.Local{Name: "destructured", Type: ir.Object, Function: index})
			function.Parameters = append(function.Parameters, incoming)
			patterns = append(patterns, patterned{pattern: name, parameter: parameter, incoming: incoming})
			continue
		}
		if !ast.IsIdentifier(parameter.Name()) {
			return l.notYet(parameter, "a parameter that isn't a plain name")
		}
		local, err := l.declareLocal(parameter.Name())
		if err != nil {
			return err
		}
		if parameterProperty(parameter) {
			// The binder gives a parameter property both a field symbol and a lexical parameter
			// symbol. Reads and assignments in the body refer to the latter.
			parameters := l.checker.GetSignatureFromDeclaration(declaration).Parameters()
			l.locals[parameters[position]] = local
		}
		if declared.DotDotDotToken != nil {
			proven := l.concrete(l.checker.GetTypeAtLocation(parameter.Name()))
			elements := l.checker.GetTypeArguments(proven)
			if !l.checker.IsArrayType(proven) || len(elements) != 1 {
				return l.notYet(parameter, "a rest parameter that isn't an array")
			}
			element, known := l.representation(elements[0])
			if !known || slotless(element) && element != ir.Union {
				return l.notYet(parameter, "a rest parameter whose elements cannot be packed")
			}
			function.RestElement = element
		}
		if function.Closure && censusCallableSlotless(l.result.Locals[local].Type) && !(l.result.Locals[local].Type == ir.Union && l.regexReplacementArgument(declaration)) {
			// Its arguments are each one adamic_value.
			return l.notYet(parameter, "a function value taking "+l.checker.TypeToString(l.checker.GetTypeAtLocation(parameter.Name())))
		}
		if declared.Initializer == nil {
			function.Parameters = append(function.Parameters, local)
			continue
		}
		missing := ir.Maybe(l.result.Locals[local].Type)
		if !missing.IsMaybe() && !missing.IsReference() {
			return l.notYet(parameter, "a default for a "+typeName(missing)+" parameter")
		}
		incoming := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: parameter.Name().Text(), Type: missing, Function: index})
		function.Parameters = append(function.Parameters, incoming)
		defaults = append(defaults, defaulted{local: local, incoming: incoming, initializer: declared.Initializer})
	}
	if function.Closure && censusCallableSlotless(function.Returns) && !(function.Returns == ir.Union && l.regexReplacementArgument(declaration)) {
		// A function value's arguments and result must each fit one adamic_value.
		return l.notYet(declaration, "a function value returning "+typeName(function.Returns))
	}
	if declaration.Body() == nil && !ast.HasSyntacticModifier(declaration, ast.ModifierFlagsAbstract) {
		return l.notYet(declaration, "a function without a body")
	}
	function.OptionalParameters = map[int]bool{}
	offset := 0
	if function.Receiver {
		offset = 1
	}
	for i, node := range declaration.Parameters() {
		parameter := node.AsParameterDeclaration()
		if parameter.QuestionToken != nil || parameter.Initializer != nil {
			function.OptionalParameters[function.Parameters[i+offset]] = true
		}
	}
	l.result.Functions[index] = function
	if !function.Closure && declaration.Kind != ast.KindConstructor && declaration.Name() != nil {
		l.closureRecords = append(l.closureRecords, closureRecord{proven: l.concrete(l.checker.GetTypeAtLocation(declaration.Name())), function: index, node: declaration})
	}
	if l.signed == nil {
		l.signed = map[int]signed{}
	}
	l.signed[index] = signed{this: this, defaults: defaults, patterns: patterns}
	return nil
}

// lowerBody lowers the body of the function at index, whose signature is written.
func (l *lowering) lowerBody(index int, declaration *ast.Node, this int, defaults []defaulted, patterns []patterned) error {
	if declaration.Body() == nil {
		return l.notYet(declaration, "a function without a body")
	}
	function := l.result.Functions[index]
	if !function.Closure {
		// A function declaration, a method or a constructor has its body lowered where a use of it is first met,
		// a closure's body included, but it's declared at the top level and captures nothing from
		// the closures being lowered there: a local of its own read in a closure of its own must not
		// land in their environments.
		outerClosures := l.closures
		l.closures = nil
		defer func() { l.closures = outerClosures }()
	}
	body := declaration.Body()
	outer, outerThis, outerIndex := l.function, l.this, l.functionIndex
	l.function, l.functionIndex = &function, index
	if this >= 0 {
		l.this = this
	}
	// Defaults run before the body, in order, after a constructor's fields, as JavaScript runs them.
	var prologue, lowered []ir.Statement
	var err error
	// Signature allocates incoming locals in source parameter order. Merge the two
	// prologues by that order: a default can read an earlier destructured name,
	// and a later destructuring must observe any mutation made by a default.
	for patternIndex, defaultIndex := 0, 0; patternIndex < len(patterns) || defaultIndex < len(defaults); {
		if err != nil {
			break
		}
		if patternIndex < len(patterns) && (defaultIndex == len(defaults) || patterns[patternIndex].incoming < defaults[defaultIndex].incoming) {
			parameter := patterns[patternIndex]
			patternIndex++
			patternType := l.checker.GetTypeAtLocation(parameter.parameter)
			heldAs, _ := l.representation(patternType)
			var destructured []ir.Statement
			destructured, err = l.destructureFrom(parameter.pattern, patternType, heldAs, parameter.incoming)
			prologue = append(prologue, destructured...)
			continue
		}
		parameter := defaults[defaultIndex]
		defaultIndex++
		if declaration.Kind == ast.KindConstructor {
			if err = l.parameterPropertyDefault(declaration, parameter.initializer); err != nil {
				break
			}
		}
		if l.uninitializedInitializer(parameter.initializer) {
			l.result.Locals[parameter.local].Uninitialized = true
			incoming := ir.Read{Local: parameter.incoming, Of: l.result.Locals[parameter.incoming].Type}
			prologue = append(prologue, ir.Declare{Local: parameter.local, Uninitialized: true}, ir.If{Condition: ir.Unary{Operator: ir.Not, Operand: ir.IsUndefined{Value: incoming}}, Then: []ir.Statement{ir.Assign{Local: parameter.local, Value: fit(incoming, l.result.Locals[parameter.local].Type)}}})
			continue
		}

		if l.lazyAssertionInitializer(parameter.initializer) {
			prefix, present, value, lazyErr := l.lazyAssertion(parameter.initializer, l.result.Locals[parameter.local].Type)
			if lazyErr != nil {
				err = lazyErr
				break
			}
			l.result.Locals[parameter.local].Uninitialized = true
			l.result.Locals[parameter.local].InitializerExpression = sourceExpression(parameter.initializer)
			incoming := ir.Read{Local: parameter.incoming, Of: l.result.Locals[parameter.incoming].Type}
			fallback := append(prefix, ir.If{Condition: present, Then: []ir.Statement{ir.Assign{Local: parameter.local, Value: value}}})
			prologue = append(prologue, ir.Declare{Local: parameter.local, Uninitialized: true}, ir.If{Condition: ir.IsUndefined{Value: incoming}, Then: fallback, Else: []ir.Statement{ir.Assign{Local: parameter.local, Value: fit(incoming, l.result.Locals[parameter.local].Type)}}})
			continue
		}
		var fallback ir.Expression
		if fallback, err = l.expression(parameter.initializer); err != nil {
			break
		}
		of := l.result.Locals[parameter.local].Type
		if fallback = fit(fallback, of); fallback.Type() != of {
			err = l.notYet(parameter.initializer, "a default of another type than its parameter")
			break
		}
		incoming := ir.Read{Local: parameter.incoming, Of: l.result.Locals[parameter.incoming].Type}
		prologue = append(prologue, ir.Declare{Local: parameter.local, Value: ir.Coalesce{Value: incoming, Fallback: fallback, Of: of}})
	}
	if err != nil {
		l.function, l.this, l.functionIndex = outer, outerThis, outerIndex
		return err
	}
	if declaration.Kind == ast.KindConstructor && l.instance.base == nil {
		assigned, assignErr := l.parameterPropertyStores(declaration.Parent, this)
		if assignErr != nil {
			l.function, l.this, l.functionIndex = outer, outerThis, outerIndex
			return assignErr
		}
		prologue = append(prologue, assigned...)
	}
	if body.Kind == ast.KindBlock {
		lowered, err = l.statements(body.AsBlock().Statements.Nodes)
	} else if function.Returns == 0 || l.isPanicCall(body) {
		// An arrow function's expression body, when it returns nothing or never returns (() =>
		// panic('why')), is a statement.
		lowered, err = l.expressionStatement(body)
	} else {
		// Otherwise its value is what it returns.
		var value ir.Expression
		if value, err = l.expression(body); err == nil {
			lowered = []ir.Statement{ir.Return{Value: fit(value, function.Returns)}}
		}
	}
	l.function, l.this, l.functionIndex = outer, outerThis, outerIndex
	if err != nil {
		return err
	}
	if body.Kind == ast.KindBlock && declaration.Kind != ast.KindConstructor && declaration.Flags&ast.NodeFlagsHasImplicitReturn != 0 && l.permitsImplicitReturn(declaration) {
		// The checker permits an end that is reachable only when the result can be undefined
		// (or void). Put that exit in the IR so every backend and ownership pass sees it.
		returned := ir.Return{}
		if function.Returns != 0 {
			returned.Value = fit(ir.Undefined{}, function.Returns)
		}
		lowered = append(lowered, returned)
	}
	// The environment may have grown while the body was lowered (captures are found as they're
	// read), so it's taken from what's recorded, not from this copy.
	function.Environment = l.result.Functions[index].Environment
	function.ForwardedNestedParent = l.result.Functions[index].ForwardedNestedParent
	function.ReferenceParents = l.result.Functions[index].ReferenceParents
	function.Body = append(function.Body, prologue...)
	function.Body = append(function.Body, lowered...)
	l.finishNestedEnvironment(&function, index)
	l.result.Functions[index] = function
	return nil
}

// The binder marks a syntactic end even for a switch the checker proved exhaustive. Only the
// checker's result type can authorize returning undefined at that end.
func (l *lowering) permitsImplicitReturn(declaration *ast.Node) bool {
	result := l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(declaration))
	return result.Flags()&checker.TypeFlagsVoid != 0 || l.includesUndefined(result)
}

generic.go:
package lower

import (
	"strconv"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// maximumGenericDepth is how many instantiations of generic functions may be lowered inside one
// another. Ordinary programs nest a few; a function that calls itself with an ever larger type
// (polymorphic recursion) would instantiate without end, and 0.1 refuses it (docs/0.1.md).
const maximumGenericDepth = 32

// instantiateFunction lowers a generic module function for the type arguments of one call, once per
// distinct set of checker type identities, as a generic class is (instantiate). Within it,
// each type parameter is what this call made it.
//
// The checker resolves the call's signature with its type arguments substituted, but doesn't export
// the mapping itself, so it's read back the way it was made: each declared parameter's type, and the
// result's, against the resolved signature's, through arrays and tuples. A type parameter that can't
// be read back that way is left unmapped, and the body says not yet wherever it needs to know it.
func (l *lowering) instantiateFunction(call *ast.Node, declaration *ast.Node) (int, error) {
	resolved := l.checker.GetResolvedSignature(call)
	target := l.checker.GetSignatureFromDeclaration(declaration)
	if resolved == nil || target == nil {
		return 0, l.notYet(call, "a call to a generic function whose signature the checker didn't resolve")
	}
	concreteTypes := map[*checker.Type]*checker.Type{}
	// Class-generic calls supply this callee's resolved mapper. Ordinary recursive
	// calls must infer their own arguments: the outer mapper can still describe the
	// same declaration's previous instantiation, as nest<T>([item], depth - 1) does.
	if l.genericUsesClasses(declaration, map[*ast.Node]bool{}) {
		for _, parameter := range declaration.TypeParameters() {
			declaredType := l.checker.GetTypeAtLocation(parameter.Name())
			concrete := l.concrete(declaredType)
			if concrete != declaredType && concrete.Flags()&checker.TypeFlagsTypeParameter == 0 {
				concreteTypes[declaredType] = concrete
			}
		}
	}
	declared, given := target.Parameters(), resolved.Parameters()
	for index := range declared {
		if index < len(given) {
			l.inferTypes(l.checker.GetTypeOfSymbol(declared[index]), l.checker.GetTypeOfSymbol(given[index]), concreteTypes)
		}
	}
	l.inferTypes(l.checker.GetReturnTypeOfSignature(target), l.checker.GetReturnTypeOfSignature(resolved), concreteTypes)

	// An explicit type argument can make tsc view a mutable argument through a wider type without
	// giving the argument that contextual type. Judge the instantiated parameter directly: the
	// ordinary refusal walk cannot see this view at the argument node.
	if call.AsCallExpression().TypeArguments != nil && len(call.AsCallExpression().TypeArguments.Nodes) > 0 {
		for index, argument := range call.AsCallExpression().Arguments.Nodes {
			if index >= len(given) || argument.Kind == ast.KindObjectLiteralExpression || argument.Kind == ast.KindArrayLiteralExpression {
				continue
			}
			from, to := l.checker.GetTypeAtLocation(argument), l.checker.GetTypeOfSymbol(given[index])
			if found := l.widened(from, to, map[[2]*checker.Type]bool{}); found != nil {
				return 0, &Refused{Where: l.program.Where(argument), What: "a type argument makes a value of type " + l.checker.TypeToString(from) + " seen as " + l.checker.TypeToString(to) + ", which can write " + l.checker.TypeToString(found.target) + " where " + l.checker.TypeToString(found.source) + " is read", Fix: "use the value's invariant type argument, or make the parameter readonly (adamic/invariant-mutable)"}
			}
		}
	}

	substitution := map[*checker.Type]ir.Type{}

	owner := -1
	if local, ok := l.locals[l.symbol(declaration.Name())]; ok && l.result.Locals[local].NestedFunction < 0 {
		owner = l.result.Locals[local].Function
	}
	key := l.program.Where(declaration)
	name := declaration.Name().Text()
	if owner >= 0 {
		key += ",frame:" + strconv.Itoa(owner)
	}
	for _, parameter := range declaration.TypeParameters() {
		parameterType := l.checker.GetTypeAtLocation(parameter.Name())
		concrete, isKnown := concreteTypes[parameterType]
		if !isKnown {
			// Not read back (it stands only inside a union or an object, Result<Value>): left
			// unmapped, so whatever in the body needs to know how it's held says not yet, there.
			key += ",unread"
			name += "_unread"
			continue
		}
		held, hasRepresentation := l.representation(concrete)
		if !hasRepresentation {
			key += ",unread"
			name += "_unread"
			continue
		}
		substitution[parameterType] = held
		key += "," + l.genericTypeKey(concrete)
	}
	if existing, isLowered := l.genericInstances[key]; isLowered {
		return existing, nil
	}
	if l.genericDepth >= maximumGenericDepth {
		return 0, &Refused{Where: l.program.Where(call), What: "a generic function instantiated without end (polymorphic recursion)", Fix: "call it with the same type arguments it was called with, or write a function per type"}
	}

	index := len(l.result.Functions)
	name += "_" + strconv.Itoa(index)
	l.result.Functions = append(l.result.Functions, ir.Function{Name: name, Closure: owner >= 0, NestedParent: owner + 1})
	if l.genericInstances == nil {
		l.genericInstances = map[string]int{}
	}
	l.genericInstances[key] = index

	// Lower with this instantiation's meaning of each type parameter, and locals of its own, outside
	// whatever function or closure called it.
	outerSubstitution, outerLocals, outerClosures, outerTypeMapper := l.substitution, l.locals, l.closures, l.typeMapper
	l.substitution, l.closures = substitution, nil
	if owner >= 0 {
		for proven, held := range outerSubstitution {
			if _, ok := substitution[proven]; !ok {
				substitution[proven] = held
			}
		}
		l.closures = append(append([]int{}, outerClosures...), index)
	}
	sources, targets := []*checker.Type{}, []*checker.Type{}
	for _, parameter := range declaration.TypeParameters() {
		parameterType := l.checker.GetTypeAtLocation(parameter.Name())
		if concrete, ok := concreteTypes[parameterType]; ok {
			sources, targets = append(sources, parameterType), append(targets, concrete)
		}
	}
	if len(sources) > 0 {
		l.typeMapper = newTypeMapper(sources, targets)
	}
	if err := l.refuseInstantiatedMutation(declaration); err != nil {
		return 0, err
	}
	l.locals = map[*ast.Symbol]int{}
	for symbol, local := range outerLocals {
		if l.result.Locals[local].Global || owner >= 0 {
			l.locals[symbol] = local
		}
	}
	l.genericDepth++
	defer func() {
		l.substitution, l.locals, l.closures, l.typeMapper = outerSubstitution, outerLocals, outerClosures, outerTypeMapper
		l.genericDepth--
	}()
	if owner >= 0 {
		l.closureRecords = append(l.closureRecords, closureRecord{proven: l.concrete(l.checker.GetTypeAtLocation(declaration.Name())), function: index, node: declaration})
	}
	if err := l.lowerFunction(index, declaration, -1); err != nil {
		return 0, err
	}
	return index, nil
}

// genericTypeKey is the shared identity key for class and function type arguments.
// Keep the concrete representatives in instantiated, the type universe the cycle
// finder already visits. Checker identity includes union members, nested containers,
// signatures and structural fields; a native representation alone loses those facts.
// This is also where nullable representations can extend the key.
func (l *lowering) genericTypeKey(proven *checker.Type) string {
	held, known := l.representation(proven)
	if !known {
		return "unread"
	}
	for index, representative := range l.instantiated {
		if identicalTypes(l.checker, proven, representative) {
			return typeName(held) + ":" + strconv.Itoa(index)
		}
	}
	index := len(l.instantiated)
	l.instantiated = append(l.instantiated, proven)
	return typeName(held) + ":" + strconv.Itoa(index)
}

// refuseInstantiatedMutation checks writes whose safety depends on a type parameter's constraint.
// TypeScript checks the generic body against the constraint, so Pack extends Animal[] permits a Cat
// to be pushed. An instantiation with Pack = Dog[] would then put that Cat in a Dog[]; monomorphizing
// the body must recheck that write against Dog rather than trusting the wider constraint.
// JSON inputs also need their concrete schemas checked before lowering can erase their types.
func (l *lowering) refuseInstantiatedMutation(declaration *ast.Node) error {
	var refused error
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if refused != nil {
			return true
		}
		if node.Kind == ast.KindCallExpression {
			call := node.AsCallExpression()
			callee := ast.SkipParentheses(call.Expression)
			if callee.Kind == ast.KindPropertyAccessExpression && callee.Name().Text() == "stringify" && l.isLibraryGlobal(callee.AsPropertyAccessExpression().Expression, "JSON") {
				for _, argument := range call.Arguments.Nodes {
					if err := l.checkInstantiatedJSONInput(argument); err != nil {
						refused = err
						return true
					}
				}
			}
			if callee.Kind == ast.KindPropertyAccessExpression {
				receiver := callee.AsPropertyAccessExpression().Expression
				argumentIndex, typeIndex := -1, -1
				switch callee.Name().Text() {
				case "push", "add":
					argumentIndex, typeIndex = 0, 0
				case "set":
					argumentIndex, typeIndex = 1, 1
				}
				concrete := l.concrete(l.checker.GetTypeAtLocation(receiver))
				if argumentIndex < 0 || concrete.Flags()&checker.TypeFlagsObject == 0 || concrete.ObjectFlags()&checker.ObjectFlagsReference == 0 {
					return node.ForEachChild(visit)
				}
				arguments := l.checker.GetTypeArguments(concrete)
				if argumentIndex >= 0 && argumentIndex < len(call.Arguments.Nodes) && typeIndex < len(arguments) {
					argument := call.Arguments.Nodes[argumentIndex]
					from, to := l.concrete(l.checker.GetTypeAtLocation(argument)), arguments[typeIndex]
					if !l.checker.IsTypeAssignableTo(from, to) {
						refused = &Refused{Where: l.program.Where(argument), What: "instantiating a generic function makes a value of type " + l.checker.TypeToString(from) + " written where " + l.checker.TypeToString(to) + " is read", Fix: "make the collection readonly, or use a type parameter for the value being written (adamic/invariant-mutable)"}
						return true
					}
				}
			}
		}
		return node.ForEachChild(visit)
	}
	declaration.ForEachChild(visit)
	return refused
}

// inferTypes records what each type parameter in declared stands for, by where it stands in
// instantiated: the type itself, a referenced type's arguments, or a function's parameters and
// result. The caller's type mapper makes an outer function's parameter concrete before it is saved,
// so a generic function calling another with its own type parameter passes the concrete type on.
func (l *lowering) inferTypes(declared *checker.Type, instantiated *checker.Type, into map[*checker.Type]*checker.Type) {
	if declared == nil || instantiated == nil {
		return
	}
	// Optional implementation parameters and results can wrap the same generic
	// binder that the resolved overload exposes directly. Infer from the present
	// member; an absent argument supplies no evidence about that binder.
	if declared.Flags()&checker.TypeFlagsUnion != 0 && l.censusHasUndefined(declared) {
		present := []*checker.Type{}
		for _, member := range declared.Types() {
			if member.Flags()&checker.TypeFlagsUndefined == 0 {
				present = append(present, member)
			}
		}
		given := instantiated
		if l.censusHasUndefined(given) && given.Flags()&checker.TypeFlagsUnion != 0 {
			members := []*checker.Type{}
			for _, member := range given.Types() {
				if member.Flags()&checker.TypeFlagsUndefined == 0 {
					members = append(members, member)
				}
			}
			given = l.checker.GetUnionType(members)
		}
		// GetNonNullableType also turns a rigid T into T & {}. Removing only
		// the optional member preserves the binder we are trying to infer.
		if len(present) == 1 && given.Flags()&checker.TypeFlagsUndefined == 0 {
			l.inferTypes(present[0], given, into)
		}
		return
	}
	if declared.Flags()&checker.TypeFlagsUnion != 0 {
		var missing *checker.Type
		for _, member := range declared.Types() {
			known, found := into[member]
			if !found && member.Flags()&checker.TypeFlagsTypeParameter != 0 {
				if missing != nil {
					return // More than one unknown binder has no unique witness.
				}
				missing = member
				continue
			}
			if !found {
				known = l.concrete(member)
			}
			if !l.checker.IsTypeAssignableTo(known, l.concrete(instantiated)) {
				return
			}
		}
		if missing != nil {
			into[missing] = l.concrete(instantiated)
		}
		return
	}
	if declared.Flags()&checker.TypeFlagsTypeParameter != 0 {
		if _, isSet := into[declared]; !isSet {
			into[declared] = l.concrete(instantiated)
		}
		return
	}
	if declared.Flags()&checker.TypeFlagsObject != 0 && instantiated.Flags()&checker.TypeFlagsObject != 0 {
		if declared.ObjectFlags()&checker.ObjectFlagsReference != 0 && instantiated.ObjectFlags()&checker.ObjectFlagsReference != 0 {
			declaredArguments, instantiatedArguments := l.checker.GetTypeArguments(declared), l.checker.GetTypeArguments(instantiated)
			for index := range declaredArguments {
				if index < len(instantiatedArguments) {
					l.inferTypes(declaredArguments[index], instantiatedArguments[index], into)
				}
			}
		}
		declaredSignatures, instantiatedSignatures := l.checker.GetSignaturesOfType(declared, checker.SignatureKindCall), l.checker.GetSignaturesOfType(instantiated, checker.SignatureKindCall)
		if len(declaredSignatures) > 0 && len(instantiatedSignatures) > 0 {
			declaredParameters, instantiatedParameters := declaredSignatures[0].Parameters(), instantiatedSignatures[0].Parameters()
			for index := range declaredParameters {
				if index < len(instantiatedParameters) {
					l.inferTypes(l.checker.GetTypeOfSymbol(declaredParameters[index]), l.checker.GetTypeOfSymbol(instantiatedParameters[index]), into)
				}
			}
			l.inferTypes(l.checker.GetReturnTypeOfSignature(declaredSignatures[0]), l.checker.GetReturnTypeOfSignature(instantiatedSignatures[0]), into)
		}
	}
}

// JSON descriptors must be checked against the actual type arguments too. Without
// this check a type parameter can hide a container inside the scalar union schema.
func (l *lowering) checkInstantiatedJSONInput(node *ast.Node) error {
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindNullKeyword {
		return nil
	}
	if node.Kind == ast.KindArrayLiteralExpression {
		for _, element := range node.AsArrayLiteralExpression().Elements.Nodes {
			if element.Kind == ast.KindSpreadElement || element.Kind == ast.KindOmittedExpression {
				continue
			}
			if err := l.checkInstantiatedJSONInput(element); err != nil {
				return err
			}
		}
		return nil
	}
	if node.Kind == ast.KindObjectLiteralExpression {
		for _, field := range node.AsObjectLiteralExpression().Properties.Nodes {
			if field.Kind == ast.KindPropertyAssignment {
				if err := l.checkInstantiatedJSONInput(field.AsPropertyAssignment().Initializer); err != nil {
					return err
				}
			}
		}
		return nil
	}
	concrete := l.concrete(l.checker.GetTypeAtLocation(node))
	if concrete.Flags()&checker.TypeFlagsUnion != 0 {
		held, known := l.representation(concrete)
		if known && held == ir.Union {
			for _, member := range concrete.Types() {
				if l.checker.IsArrayType(member) {
					return l.notYet(node, "JSON.stringify unions containing arrays (adamic/json-union-array)")
				}
			}
		}
	}
	_, err := l.jsonType(node, concrete, 0)
	return err
}

input.go:
package lower

import (
	"errors"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// inputFunctions are the prelude functions input lowers.
var inputFunctions = []string{"readTextFile", "writeTextFile", "utf8Length", "utf8At", "readDirectory", "fileStatus", "programArguments"}

// input lowers the program's doors in from outside, opened in 0.2: readTextFile(path) and
// programArguments() from 'adamic', the door out, writeTextFile(path, text), and what a walk of the
// file system needs, readDirectory(path) and fileStatus(path). isInput is false for any other call.
func (l *lowering) input(node *ast.Node) (ir.Expression, bool, error) {
	if value, found, err := l.nodeHost(node); found {
		return value, true, err
	}
	if value, found, err := l.nodeFSFile(node); found {
		return value, true, err
	}
	if value, found, err := l.tsgo(node); found {
		return value, true, err
	}
	callee := node.AsCallExpression().Expression
	arguments := node.AsCallExpression().Arguments.Nodes
	// A spread of a tuple is a count the checker accepts and the cases below can't see, so it is
	// refused here, before any of them reads it as a checker bug.
	for _, name := range inputFunctions {
		if !l.isPreludeFunction(callee, name) {
			continue
		}
		for _, argument := range arguments {
			if argument.Kind == ast.KindSpreadElement {
				return nil, true, l.notYet(argument, "a spread argument to "+name)
			}
		}
	}
	switch {
	case l.isPreludeFunction(callee, "readTextFile"):
		if len(arguments) != 1 {
			return nil, true, errors.New("lower: " + l.program.Where(node) + ": readTextFile takes one path, and the checker let another count through")
		}
		path, err := l.expression(arguments[0])
		if err != nil {
			return nil, true, err
		}
		if path.Type() != ir.String {
			return nil, true, errors.New("lower: " + l.program.Where(arguments[0]) + ": readTextFile's path isn't a string, and the checker let it through")
		}
		return ir.ReadTextFile{Path: path}, true, nil
	case l.isPreludeFunction(callee, "writeTextFile"):
		if len(arguments) != 2 {
			return nil, true, errors.New("lower: " + l.program.Where(node) + ": writeTextFile takes a path and a text, and the checker let another count through")
		}
		path, err := l.expression(arguments[0])
		if err != nil {
			return nil, true, err
		}
		text, err := l.expression(arguments[1])
		if err != nil {
			return nil, true, err
		}
		if path.Type() != ir.String || text.Type() != ir.String {
			return nil, true, errors.New("lower: " + l.program.Where(node) + ": writeTextFile's path or text isn't a string, and the checker let it through")
		}
		return ir.WriteTextFile{Path: path, Text: text}, true, nil
	case l.isPreludeFunction(callee, "utf8Length") || l.isPreludeFunction(callee, "utf8At"):
		lowered := []ir.Expression{}
		for _, argument := range arguments {
			value, err := l.expression(argument)
			if err != nil {
				return nil, true, err
			}
			lowered = append(lowered, value)
		}
		if l.isPreludeFunction(callee, "utf8Length") {
			if len(lowered) != 1 || lowered[0].Type() != ir.String {
				return nil, true, errors.New("lower: " + l.program.Where(node) + ": utf8Length takes one string, and the checker let something else through")
			}
			return ir.Utf8Length{Text: lowered[0]}, true, nil
		}
		if len(lowered) != 2 || lowered[0].Type() != ir.String || lowered[1].Type() != ir.Number {
			return nil, true, errors.New("lower: " + l.program.Where(node) + ": utf8At takes a string and a number, and the checker let something else through")
		}
		return ir.Utf8At{Text: lowered[0], Index: lowered[1]}, true, nil
	case l.isPreludeFunction(callee, "readDirectory"), l.isPreludeFunction(callee, "fileStatus"):
		// By what it is, not what it's called here: an import may name it anything.
		name := "fileStatus"
		if l.isPreludeFunction(callee, "readDirectory") {
			name = "readDirectory"
		}
		if len(arguments) != 1 {
			return nil, true, errors.New("lower: " + l.program.Where(node) + ": " + name + " takes one path, and the checker let another count through")
		}
		path, err := l.expression(arguments[0])
		if err != nil {
			return nil, true, err
		}
		if path.Type() != ir.String {
			return nil, true, errors.New("lower: " + l.program.Where(arguments[0]) + ": " + name + "'s path isn't a string, and the checker let it through")
		}
		if name == "readDirectory" {
			return ir.ReadDirectory{Path: path}, true, nil
		}
		return ir.FileStatus{Path: path}, true, nil
	case l.isPreludeFunction(callee, "programArguments"):
		if len(arguments) != 0 {
			return nil, true, errors.New("lower: " + l.program.Where(node) + ": programArguments takes nothing, and the checker let arguments through")
		}
		return ir.ProgramArguments{}, true, nil
	}
	return nil, false, nil
}

instantiate.go:
package lower

import (
	_ "unsafe"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
)

// The cycle finder judges every instantiation of a generic class by its own types (cycles.go). Inside
// Maker<Node>, a new Box<T>() is a Box<Node>, though the source only ever writes Box<T>; the checker
// knows how to make that type, but its shim doesn't export the way. These two pull it from the
// checker's own package, as the shim's generated code does for what it exports. They belong in
// cohere's shim (extra-shim.json); until they're there, this is where they are.

// typeMapper is the checker's TypeMapper, held only by pointer here.
type typeMapper struct{}

//go:linkname newTypeMapper github.com/microsoft/TypeScript/tsc/internal/checker.newTypeMapper
func newTypeMapper(sources []*checker.Type, targets []*checker.Type) *typeMapper

//go:linkname instantiateType github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).instantiateType
func instantiateType(receiver *checker.Checker, proven *checker.Type, mapper *typeMapper) *checker.Type

// typeMapperOf is what a class's type parameters stand for in a type of it, as a mapper the checker
// instantiates with, or the one in force when the class has none.
func (l *lowering) typeMapperOf(declaration *ast.Node, classType *checker.Type) *typeMapper {
	parameters := declaration.TypeParameters()
	arguments := l.checker.GetTypeArguments(classType)
	if len(parameters) == 0 || len(parameters) != len(arguments) {
		return l.typeMapper
	}
	sources := []*checker.Type{}
	for _, parameter := range parameters {
		sources = append(sources, l.checker.GetTypeAtLocation(parameter.Name()))
	}
	return newTypeMapper(sources, arguments)
}

// closureNodeOf is where a function value is written.
func (l *lowering) closureNodeOf(function int) *ast.Node {
	for _, closure := range l.closureRecords {
		if closure.function == function {
			return closure.node
		}
	}
	return nil
}

// concrete is a type as the instantiation being lowered makes it: its type parameters, and those of
// every instantiation it's inside, replaced by what they stand for.
func (l *lowering) concrete(proven *checker.Type) *checker.Type {
	if l.typeMapper == nil || proven == nil {
		return proven
	}
	return instantiateType(l.checker, proven, l.typeMapper)
}

// classNodeFor is where a class type's class is declared, to point at.
func (l *lowering) classNodeFor(proven *checker.Type) *ast.Node {
	if symbol := proven.Symbol(); symbol != nil && len(symbol.Declarations) > 0 {
		return symbol.Declarations[0]
	}
	return nil
}

interface_cast.go:
package lower

import (
	"fmt"
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// A tag chooses the interface; its fields remain checked at every read.
func (l *lowering) interfaceCast(node *ast.Node, value ir.Expression, source, target *checker.Type) (ir.Expression, error) {
	if source.Flags()&checker.TypeFlagsObject == 0 || target.Flags()&checker.TypeFlagsObject == 0 || value.Type() != ir.Object || isClassInstance(target) {
		return nil, nil
	}
	for _, property := range l.checker.GetPropertiesOfType(source) {
		field := property.Name
		literal := l.fieldLiteral(target, field)
		if literal == nil || !l.checker.IsTypeAssignableTo(target, source) || l.widened(target, source, map[[2]*checker.Type]bool{}) != nil {
			continue
		}
		allowed, fieldType, constant := l.literalConstant(literal)
		if !constant {
			continue
		}
		if _, err := l.view(node, value, target); err != nil {
			return nil, err
		}
		return ir.CheckedCast{Value: value, Field: field, FieldType: fieldType, Allowed: []ir.Expression{allowed}, CheckedFields: true, Message: "cast failed: this " + l.checker.TypeToString(source) + " is not a " + l.checker.TypeToString(target)}, nil
	}
	return nil, nil
}

// view is the shared entry point. Checking by field name throughout the program is
// conservative: aliases and function boundaries cannot lose a checked read.
// More precise view propagation and erasure can reduce that set without trusting casts.
func (l *lowering) view(node *ast.Node, value ir.Expression, target *checker.Type) (ir.Expression, error) {
	if target.Flags()&checker.TypeFlagsUnion != 0 {
		return l.legacyView(node, value, target)
	}
	fields, err := l.viewSchema(node, target)
	if err != nil {
		return nil, err
	}
	if l.result.CheckedFields == nil {
		l.result.CheckedFields = map[string]bool{}
	}
	for field := range fields {
		l.result.CheckedFields[field] = true
	}

	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return nil, err
	}
	var refused error
	var visit ast.Visitor
	visit = func(part *ast.Node) bool {
		if refused != nil {
			return true
		}
		// Optional receivers and optional/accessor slots still need a representation
		// conversion that the V1 checked read boundary cannot emit.
		if part.Kind == ast.KindPropertyAccessExpression && fields[part.Name().Text()] {
			access := part.AsPropertyAccessExpression()
			if base, _ := l.representation(l.checker.GetTypeAtLocation(access.Expression)); base == ir.Object {
				field := l.checker.GetSymbolAtLocation(part.Name())
				if field != nil && len(l.checker.GetSignaturesOfType(l.checker.GetTypeOfSymbol(field), checker.SignatureKindCall)) == 0 && (field.Flags&ast.SymbolFlagsOptional != 0 || access.QuestionDotToken != nil || accessorSymbol(field)) {
					refused = l.notYet(part, "a checked field alias requiring an optional, accessor, or representation conversion")
				}
			}
		}
		if part.Kind == ast.KindPropertyAccessExpression && fields[part.Name().Text()] && ast.IsAssignmentTarget(part) {
			if symbol := l.checker.GetSymbolAtLocation(part.Name()); symbol != nil {
				of, _ := l.representation(l.checker.GetTypeOfSymbol(symbol))
				if of == ir.Object {
					refused = l.notYet(part, "writing a checked object field without its source-slot type certificate")
				}
			}
		}
		if part.Kind == ast.KindGetAccessor && part.Name() != nil && fields[part.Name().Text()] {
			refused = l.notYet(part, "a getter in a checked field contract")
		}
		if refused == nil {
			part.ForEachChild(visit)
		}
		return refused != nil
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	if refused != nil {
		return nil, refused
	}
	l.result.ViewOrigins = append(l.result.ViewOrigins, value)
	return value, nil
}

func interfaceScalar(proven *checker.Type) bool {
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range proven.Types() {
			if !interfaceScalar(member) {
				return false
			}
		}
		return true
	}
	return proven.Flags()&(checker.TypeFlagsString|checker.TypeFlagsStringLiteral|checker.TypeFlagsNumber|checker.TypeFlagsNumberLiteral|checker.TypeFlagsBoolean|checker.TypeFlagsBooleanLiteral) != 0 && proven.Flags()&(checker.TypeFlagsAny|checker.TypeFlagsUnknown|checker.TypeFlagsIntersection|checker.TypeFlagsTypeParameter) == 0
}

func (l *lowering) interfaceScalarShape(proven *checker.Type) bool {
	if isClassInstance(proven) || len(l.checker.GetSignaturesOfType(proven, checker.SignatureKindCall)) != 0 {
		return false
	}
	for _, property := range l.checker.GetPropertiesOfType(proven) {
		if property.Flags&ast.SymbolFlagsOptional != 0 || !l.checker.IsReadonlySymbol(property) || !interfaceScalar(l.checker.GetTypeOfSymbol(property)) {
			return false
		}
	}
	return len(l.checker.GetPropertiesOfType(proven)) > 0
}

// Look at initializer types, never an asserted/contextual interface as evidence of payload.
func interfaceLiteralFields(node *ast.Node) (map[string]*ast.Node, bool) {
	fields := map[string]*ast.Node{}
	for _, property := range node.AsObjectLiteralExpression().Properties.Nodes {
		if property.Kind != ast.KindPropertyAssignment && property.Kind != ast.KindShorthandPropertyAssignment {
			return nil, false
		}
		name := property.Name()
		if name == nil || (name.Kind != ast.KindIdentifier && name.Kind != ast.KindStringLiteral) {
			return nil, false
		}
		value := name
		if property.Kind == ast.KindPropertyAssignment {
			value = property.AsPropertyAssignment().Initializer
		}
		fields[name.Text()] = value
	}
	return fields, true
}

func (l *lowering) interfaceConstructions(cast *ast.Node, target *checker.Type, field string, literal *checker.Type) error {
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return err
	}
	checked := map[string]*checker.Type{}
	for _, property := range l.checker.GetPropertiesOfType(target) {
		checked[property.Name] = l.checker.GetTypeOfSymbol(property)
	}
	var found error
	fail := func(node *ast.Node, reason string) {
		found = &Refused{Where: l.program.Where(cast), What: "an unproven base interface construction", Fix: fmt.Sprintf("%s at %s; build the complete target in an immutable literal and preserve its fields (adamic/interface-construction)", reason, l.program.Where(node))}
	}
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if found != nil {
			return true
		}
		if ast.HasSyntacticModifier(node, ast.ModifierFlagsAmbient) {
			fail(node, "an ambient value has no construction body")
			return true
		}
		switch node.Kind {
		case ast.KindAnyKeyword, ast.KindTypeAssertionExpression:
			fail(node, "an unproven type could forge a construction")
		case ast.KindIdentifier:
			if node.Text() == "Object" || node.Text() == "Reflect" || node.Text() == "JSON" {
				fail(node, "reflection or host construction is outside the prototype")
			}
		case ast.KindClassDeclaration, ast.KindNewExpression, ast.KindSpreadAssignment, ast.KindGetAccessor, ast.KindSetAccessor:
			fail(node, "opaque, staged or spread construction is outside the prototype")
		case ast.KindFunctionDeclaration, ast.KindFunctionExpression, ast.KindArrowFunction, ast.KindMethodDeclaration:
			if len(node.TypeParameters()) > 0 || node.Body() == nil {
				fail(node, "a generic or bodyless factory is outside the prototype")
			}
		case ast.KindImportDeclaration, ast.KindExportDeclaration:
			if specifier := node.ModuleSpecifier(); specifier != nil && !strings.HasPrefix(specifier.Text(), ".") {
				fail(node, "an external module has no closed construction proof")
			}
		case ast.KindCallExpression:
			callee := ast.SkipParentheses(node.AsCallExpression().Expression)
			if callee.Kind == ast.KindPropertyAccessExpression {
				base := callee.AsPropertyAccessExpression().Expression
				if ast.IsIdentifier(base) && (base.Text() == "Object" || base.Text() == "Reflect" || base.Text() == "JSON") {
					fail(node, "reflection or host construction is outside the prototype")
				}
			}
		case ast.KindBinaryExpression:
			binary := node.AsBinaryExpression()
			if ast.IsAssignmentOperator(binary.OperatorToken.Kind) {
				l.interfaceWrite(binary.Left, checked, fail)
			}
		case ast.KindPrefixUnaryExpression:
			unary := node.AsPrefixUnaryExpression()
			if unary.Operator == ast.KindPlusPlusToken || unary.Operator == ast.KindMinusMinusToken {
				l.interfaceWrite(unary.Operand, checked, fail)
			}
		case ast.KindPostfixUnaryExpression:
			l.interfaceWrite(node.AsPostfixUnaryExpression().Operand, checked, fail)
		case ast.KindAsExpression:
			as := node.AsAsExpression()
			if as.Type.Kind == ast.KindTypeReference && as.Type.AsTypeReferenceNode().TypeName.Text() == "const" {
				break
			}
			from, to := l.checker.GetTypeAtLocation(as.Expression), l.checker.GetTypeAtLocation(node)
			// Another base cast is checked by this same pass at its own lowering site.
			baseCast := l.interfaceScalarShape(from) && l.interfaceScalarShape(to) && l.fieldLiteral(to, field) != nil && l.checker.IsTypeAssignableTo(to, from)
			scalarUpcast := interfaceScalar(from) && interfaceScalar(to) && l.checker.IsTypeAssignableTo(from, to)
			objectUpcast := l.interfaceScalarShape(to) && l.checker.IsTypeAssignableTo(from, to) && l.widened(from, to, map[[2]*checker.Type]bool{}) == nil
			if !baseCast && !scalarUpcast && !objectUpcast {
				fail(node, "an assertion could forge a construction or scalar payload")
			}
		case ast.KindObjectLiteralExpression:
			fields, complete := interfaceLiteralFields(node)
			if !complete {
				fail(node, "a literal has unproven field names or behavior")
				break
			}
			kind := fields[field]
			if kind == nil {
				break // No write or spread can add a tag later in an admitted program.
			}
			kindType := l.checker.GetTypeAtLocation(kind)
			if !interfaceScalar(kindType) {
				fail(kind, "a tag has an unproven scalar type")
				break
			}
			if !l.checker.IsTypeAssignableTo(literal, kindType) {
				break // A precise different tag cannot select this target.
			}
			for name, wanted := range checked {
				value := fields[name]
				if value == nil {
					fail(node, "matching kind lacks required field "+name)
					break
				}
				actual := l.checker.GetTypeAtLocation(value)
				// A broad tag needs the runtime comparison, so it need not be a target literal.
				if !interfaceScalar(actual) || (name != field && !l.checker.IsTypeAssignableTo(actual, wanted)) {
					fail(value, "matching kind has incompatible field "+name)
					break
				}
			}
		}
		if found == nil {
			node.ForEachChild(visit)
		}
		return found != nil
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
		if found != nil {
			return found
		}
	}
	return nil
}

// Field names are deliberately global, including writes through wider or unrelated views.
// Destructuring and computed destinations fail closed rather than guess their alias effects.
func (l *lowering) interfaceWrite(node *ast.Node, checked map[string]*checker.Type, fail func(*ast.Node, string)) {
	node = ast.SkipParentheses(node)
	if ast.IsIdentifier(node) {
		return
	}
	if node.Kind == ast.KindPropertyAccessExpression {
		if _, needed := checked[node.AsPropertyAccessExpression().Name().Text()]; !needed {
			return
		}
	}
	fail(node, "a write may invalidate the kind-to-shape invariant")
}

// A finite literal contract is checked as well as its primitive representation.
func (l *lowering) viewLiterals(declared *checker.Type) []ir.Expression {
	if declared.Flags()&checker.TypeFlagsUnion != 0 {
		var allowed []ir.Expression
		for _, member := range declared.Types() {
			values := l.viewLiterals(member)
			if len(values) == 0 {
				return nil
			}
			allowed = append(allowed, values...)
		}
		return allowed
	}
	value, _, known := l.literalConstant(declared)
	if known {
		return []ir.Expression{value}
	}
	return nil
}

func (l *lowering) callableViewContract(proven *checker.Type) bool {
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range proven.Types() {
			if l.callableViewContract(member) {
				return true
			}
		}
	}
	return len(l.checker.GetSignaturesOfType(proven, checker.SignatureKindCall)) != 0 || len(l.checker.GetSignaturesOfType(proven, checker.SignatureKindConstruct)) != 0
}

func (l *lowering) viewSchema(node *ast.Node, target *checker.Type) (map[string]bool, error) {
	id, err := l.viewContract(node, target)
	if err != nil {
		return nil, err
	}
	fields := map[string]bool{}
	seen := map[ir.ViewContractID]bool{}
	var visit func(ir.ViewContractID)
	visit = func(id ir.ViewContractID) {
		if id == 0 || seen[id] {
			return
		}
		seen[id] = true
		contract := l.result.ViewContracts[id-1]
		for _, field := range contract.Fields {
			fields[field.Name] = true
			visit(field.Contract)
		}
		for _, member := range contract.Members {
			visit(member)
		}
	}
	visit(id)
	return fields, nil
}

func (l *lowering) legacyView(node *ast.Node, value ir.Expression, target *checker.Type) (ir.Expression, error) {
	if l.callableViewContract(target) {
		return nil, &Refused{Where: l.program.Where(node), What: "a checked view with a callable contract", Fix: "prove the callable body rather than asserting its signature"}
	}
	// Diagnose unreifiable contracts before temporary backend limitations.
	for _, property := range l.checker.GetPropertiesOfType(target) {
		declared := l.checker.GetTypeOfSymbol(property)
		if l.callableViewContract(declared) {
			return nil, &Refused{Where: l.program.Where(node), What: "a checked view with callable field " + property.Name, Fix: "prove the callable body rather than asserting its signature"}
		}
	}
	fields := map[string]bool{}
	for _, property := range l.checker.GetPropertiesOfType(target) {
		declared := l.checker.GetTypeOfSymbol(property)
		if l.callableViewContract(declared) {
			return nil, &Refused{Where: l.program.Where(node), What: "a checked view with callable field " + property.Name, Fix: "prove the callable body rather than asserting its signature"}
		}
		of, known := l.representation(declared)
		if property.Flags&ast.SymbolFlagsOptional != 0 || !interfaceScalar(declared) || !known || of < ir.Number || of > ir.String {
			return nil, l.notYet(node, "checked view field "+property.Name+" of type "+l.checker.TypeToString(declared))
		}
		fields[property.Name] = true
	}
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return nil, err
	}
	var found error
	var visit ast.Visitor
	visit = func(part *ast.Node) bool {
		if found != nil {
			return true
		}
		if part.Kind == ast.KindGetAccessor && part.Name() != nil && fields[part.Name().Text()] {
			found = l.notYet(part, "a getter in a checked field contract")
		}
		if part.Kind == ast.KindObjectBindingPattern {
			for _, binding := range part.AsBindingPattern().Elements.Nodes {
				name := binding.Name()
				if binding.AsBindingElement().PropertyName != nil {
					name = binding.AsBindingElement().PropertyName
				}
				if name != nil && fields[name.Text()] {
					declared := l.checker.GetTypeAtLocation(binding.Name())
					of, known := l.representation(declared)
					if !known || of < ir.Number || of > ir.String || !interfaceScalar(declared) {
						found = l.notYet(binding, "a checked destructured alias requiring a representation conversion")
					}
				}
			}
		}
		if part.Kind == ast.KindPropertyAccessExpression && fields[part.Name().Text()] {
			access := part.AsPropertyAccessExpression()
			if base, _ := l.representation(l.checker.GetTypeAtLocation(access.Expression)); base == ir.Object {
				field := l.checker.GetSymbolAtLocation(part.Name())
				if field != nil && len(l.checker.GetSignaturesOfType(l.checker.GetTypeOfSymbol(field), checker.SignatureKindCall)) == 0 {
					of, known := l.representation(l.checker.GetTypeOfSymbol(field))
					if !interfaceScalar(l.checker.GetTypeOfSymbol(field)) || !known || of < ir.Number || of > ir.String || field.Flags&ast.SymbolFlagsOptional != 0 || access.QuestionDotToken != nil || accessorSymbol(field) {
						found = l.notYet(part, "a checked field alias requiring an optional, accessor, or representation conversion")
					}
				}
			}
		}
		if found == nil {
			part.ForEachChild(visit)
		}
		return found != nil
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	if found != nil {
		return nil, found
	}
	if l.result.CheckedFields == nil {
		l.result.CheckedFields = map[string]bool{}
	}
	for field := range fields {
		l.result.CheckedFields[field] = true
	}
	return value, nil
}

invariance.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/load"
)

// Mutable locations are invariant in 0.1 (docs/0.1.md, adamic/invariant-mutable): tsc relates an
// array's elements, a property and a map's values covariantly, so a Dog[] is accepted as an Animal[],
// and the wider name can then write a cat where the dogs are read. Stage 0 doesn't run cohere's lint,
// so it refuses the same views itself, before lowering: every place a value goes into a typed slot
// (an initializer, an assignment, an argument, a return, a literal's property or element), the value's
// type is walked against the slot's, all the way down, as the Weak view check walks them.
//
// At each mutable slot the wider side can write, what it writes must be something the narrower side
// can read: the slot's type in the target must be assignable to its type in the source. tsc proved
// the other direction when it accepted the site, so together the slot is invariant. A readonly slot
// only reads, and stays covariant.
//
// Two shapes reach a mutable array where tsc's relation can't be walked part by part, and each is
// judged as cohere's rule judges it (cohere 838c6516):
//   - A type parameter target (const pack: Pack = narrow, Narrow extends Pack extends Animal[]): what
//     Pack holds is no type to compare against until it's instantiated, so a type parameter whose
//     constraint can be written is one mutable slot, and only the parameter itself (or it narrowed,
//     as T & {}) fills it.
//   - An intersection with an array (Dog[] & { tag } into Animal[] & { tag }): its array, tuple and
//     container members are paired member by member, as well as its properties.

// widening is a view refused: the parts of the source and the target at the slot where the target can
// write what the source can't read.
type widening struct {
	source, target *checker.Type

	// readonlyField names a readonly field seen as a writable one, when that's the slot.
	readonlyField string
	enum          bool

	// parameter is a function's parameter of type source seen as taking target, which it can't.
	parameter bool
}

// widened finds the first mutable slot at which a value of type from, seen as type to, could be
// written something it can't hold, or returns nil.
func (l *lowering) widened(from *checker.Type, to *checker.Type, visited map[[2]*checker.Type]bool) *widening {
	from, to = l.withoutUndefined(from), l.withoutUndefined(to)
	if from == to || visited[[2]*checker.Type{from, to}] {
		return nil
	}
	visited[[2]*checker.Type{from, to}] = true
	if l.openNumericEnumType(to) {
		for _, member := range l.definedMembers(from) {
			if !l.enumAssignable(member, to) {
				return &widening{source: from, target: to, enum: true}
			}
		}
		return nil
	}
	if to.Flags()&checker.TypeFlagsNumberLiteral != 0 && l.openNumericEnumType(from) {
		return &widening{source: from, target: to, enum: true}
	}
	if members := l.definedMembers(from); len(members) > 1 {
		// A union is any one of its members, each seen as the target.
		for _, member := range members {
			if found := l.widened(member, to, visited); found != nil {
				return found
			}
		}
		return nil
	}
	if members := l.definedMembers(to); len(members) > 1 {
		// Seen as a union, a value is seen as each member it can be, and narrowing picks any of them
		// to write through.
		for _, member := range members {
			if !l.checker.IsTypeAssignableTo(from, member) {
				continue
			}
			if found := l.widened(from, member, visited); found != nil {
				return found
			}
		}
		return nil
	}
	if to.Flags()&checker.TypeFlagsTypeParameter != 0 {
		if l.narrowedFrom(from, to) {
			return nil
		}
		if constraint := l.checker.GetBaseConstraintOfType(to); constraint != nil && l.canWrite(constraint, map[*checker.Type]bool{}) {
			return &widening{source: from, target: to}
		}
		return nil
	}
	if from.Flags()&checker.TypeFlagsTypeParameter != 0 {
		// What it can be is what its constraint allows: seen as anything wider, it's that seen so.
		constraint := l.checker.GetBaseConstraintOfType(from)
		if constraint == nil {
			return nil
		}
		return l.widened(constraint, to, visited)
	}
	if !l.enumAssignable(from, to) {
		return &widening{source: from, target: to, enum: true}
	}
	if !l.structured(from) || !l.structured(to) {
		// A class instance target is walked as any object is: its fields are slots as a literal's
		// are, so Box<Dog> seen as Box<Animal>, or a plain object seen as a class, is judged by them.
		return nil
	}
	fromSignatures := l.checker.GetSignaturesOfType(from, checker.SignatureKindCall)
	toSignatures := l.checker.GetSignaturesOfType(to, checker.SignatureKindCall)
	if len(fromSignatures) > 0 && len(toSignatures) > 0 {
		// A function seen as another is handed the other's arguments, and its results are seen as
		// the other's: each a view of its own.
		if l.censusNeverRestSignature(toSignatures[0]) {
			if l.censusDiscardedMarkerPredicate(fromSignatures[0], toSignatures[0]) {
				return nil
			}
			source := l.checker.GetReturnTypeOfSignature(fromSignatures[0])
			target := l.checker.GetReturnTypeOfSignature(toSignatures[0])
			if !l.checker.IsTypeAssignableTo(source, target) {
				return &widening{source: source, target: target}
			}
			return l.widened(source, target, visited)
		}
		fromParameters, toParameters := fromSignatures[0].Parameters(), toSignatures[0].Parameters()
		for index := 0; index < len(fromParameters) && index < len(toParameters); index++ {
			takes, given := l.censusCallableParameterType(fromParameters[index]), l.censusCallableParameterType(toParameters[index])
			if !l.enumAssignable(given, takes) || !l.checker.IsTypeAssignableTo(given, takes) {
				// tsc relates a method's parameters both ways (method bivariance), so a method taking
				// a Dog can be seen as one taking any Animal, and handed a Cat.
				return &widening{source: takes, target: given, parameter: true}
			}
			if found := l.widened(given, takes, visited); found != nil {
				return found
			}
		}
		return l.widened(l.checker.GetReturnTypeOfSignature(fromSignatures[0]), l.checker.GetReturnTypeOfSignature(toSignatures[0]), visited)
	}
	fromContainers := l.containers(from)
	for _, viewed := range l.containers(to) {
		for _, inside := range fromContainers {
			if !l.sameContainer(inside, viewed) {
				continue
			}
			if found := l.widenedElements(inside, viewed, visited); found != nil {
				return found
			}
			break
		}
	}
	if to.Flags()&checker.TypeFlagsObject != 0 && len(l.containers(to)) > 0 {
		// An array, tuple, map or set: its elements are its slots, and its own properties (length,
		// size) are numbers on both sides.
		return nil
	}
	return l.widenedProperties(from, to, nil, false, visited)
}

// widenedProperties walks to's properties against from's, but those skip names: each field a slot
// to can write unless it's readonly, and each method a function view of its own. A copy's fields
// (fresh) are slots of their own, which nothing else writes, so only what they hold is walked.
func (l *lowering) widenedProperties(from *checker.Type, to *checker.Type, skip map[string]bool, fresh bool, visited map[[2]*checker.Type]bool) *widening {
	for _, viewed := range l.checker.GetPropertiesOfType(to) {
		inside := l.checker.GetPropertyOfType(from, viewed.Name)
		if inside == nil || skip[viewed.Name] {
			continue
		}
		source, target := l.checker.GetTypeOfSymbol(inside), l.checker.GetTypeOfSymbol(viewed)
		if viewed.Flags&ast.SymbolFlagsMethod != 0 || inside.Flags&ast.SymbolFlagsMethod != 0 {
			// A method isn't a slot anything writes, but what it returns and takes are views: the
			// program's own methods. The library's (an Iterable's, an array's own) are left to the
			// rules for the library's types, and a generic one has no one type to compare.
			if len(viewed.Declarations) == 0 || load.IsLibrary(ast.GetSourceFileOfNode(viewed.Declarations[0])) || l.generic(target) || l.generic(source) {
				continue
			}
			if found := l.widened(source, target, visited); found != nil {
				return found
			}
			continue
		}
		if !fresh && !l.checker.IsReadonlySymbol(viewed) && l.checker.IsReadonlySymbol(inside) {
			// tsc ignores readonly when it relates properties, so a readonly field, which may hold
			// something narrower than its type says (it's covariant), can be seen as a writable one,
			// and the wider type written into it. Only the identical type, which this walk never
			// enters, is the same field.
			return &widening{source: source, target: target, readonlyField: viewed.Name}
		}
		if !fresh && !l.checker.IsReadonlySymbol(viewed) && (!l.enumAssignable(target, source) || !l.checker.IsTypeAssignableTo(target, source)) {
			return &widening{source: source, target: target}
		}
		if found := l.widened(source, target, visited); found != nil {
			return found
		}
	}
	return nil
}

// generic reports whether a function type has a type parameter of its own.
func (l *lowering) generic(proven *checker.Type) bool {
	for _, signature := range l.checker.GetSignaturesOfType(proven, checker.SignatureKindCall) {
		if len(signature.TypeParameters()) > 0 {
			return true
		}
	}
	return false
}

// widenedElements walks an array's, a tuple's, a map's or a set's type arguments in from against
// to's, each a slot to can write unless it's read only.
func (l *lowering) widenedElements(from *checker.Type, to *checker.Type, visited map[[2]*checker.Type]bool) *widening {
	mutable := !l.isLibraryType(to, "ReadonlyArray", "ReadonlyMap", "ReadonlySet") && !(checker.IsTupleType(to) && to.TargetTupleType().IsReadonly())
	return l.widenedArguments(from, to, mutable, visited)
}

// widenedArguments is widenedElements with whether to's own slots can be written given: a fresh
// container's can't be written through anything else (freshValue).
func (l *lowering) widenedArguments(from *checker.Type, to *checker.Type, mutable bool, visited map[[2]*checker.Type]bool) *widening {
	fromArguments, toArguments := l.checker.GetTypeArguments(from), l.checker.GetTypeArguments(to)
	if checker.IsTupleType(from) && !checker.IsTupleType(to) && len(toArguments) == 1 {
		// A tuple seen as an array: every element of it is seen as the array's element.
		widenedTo := make([]*checker.Type, len(fromArguments))
		for index := range widenedTo {
			widenedTo[index] = toArguments[0]
		}
		toArguments = widenedTo
	}
	for index := 0; index < len(fromArguments) && index < len(toArguments); index++ {
		source, target := fromArguments[index], toArguments[index]
		if mutable && (!l.enumAssignable(target, source) || !l.checker.IsTypeAssignableTo(target, source)) {
			return &widening{source: source, target: target}
		}
		if found := l.widened(source, target, visited); found != nil {
			return found
		}
	}
	return nil
}

// containers is a type's arrays, tuples, maps and sets: itself, or its members that are, when it's an
// intersection.
func (l *lowering) containers(proven *checker.Type) []*checker.Type {
	members := []*checker.Type{proven}
	if proven.Flags()&checker.TypeFlagsIntersection != 0 {
		members = proven.Types()
	}
	var found []*checker.Type
	for _, member := range members {
		if member.Flags()&checker.TypeFlagsObject != 0 && member.ObjectFlags()&checker.ObjectFlagsReference != 0 &&
			(l.checker.IsArrayType(member) || checker.IsTupleType(member) || l.isLibraryType(member, "Map", "ReadonlyMap", "Set", "ReadonlySet")) {
			found = append(found, member)
		}
	}
	return found
}

// sameContainer reports whether two containers are the same kind, whose type arguments pair up: two
// arrays or tuples (readonly or not), two maps, or two sets.
func (l *lowering) sameContainer(from *checker.Type, to *checker.Type) bool {
	switch {
	case l.checker.IsArrayType(to) || checker.IsTupleType(to):
		return l.checker.IsArrayType(from) || checker.IsTupleType(from)
	case l.isLibraryType(to, "Map", "ReadonlyMap"):
		return l.isLibraryType(from, "Map", "ReadonlyMap")
	default:
		return l.isLibraryType(from, "Set", "ReadonlySet")
	}
}

// canWrite reports whether something can be written through a value of a type, at any depth: an
// array, tuple, map or set that isn't read only, or a property that isn't readonly, or one inside a
// readonly one.
func (l *lowering) canWrite(proven *checker.Type, visited map[*checker.Type]bool) bool {
	proven = l.withoutUndefined(proven)
	if proven == nil || visited[proven] || !l.structured(proven) || len(l.checker.GetSignaturesOfType(proven, checker.SignatureKindCall)) > 0 {
		return false
	}
	visited[proven] = true
	containers := l.containers(proven)
	for _, container := range containers {
		if !l.isLibraryType(container, "ReadonlyArray", "ReadonlyMap", "ReadonlySet") && !(checker.IsTupleType(container) && container.TargetTupleType().IsReadonly()) {
			return true
		}
		for _, element := range l.checker.GetTypeArguments(container) {
			if l.canWrite(element, visited) {
				return true
			}
		}
	}
	if proven.Flags()&checker.TypeFlagsObject != 0 && len(containers) > 0 {
		return false
	}
	for _, property := range l.checker.GetPropertiesOfType(proven) {
		if property.Flags&ast.SymbolFlagsMethod != 0 {
			continue
		}
		if !l.checker.IsReadonlySymbol(property) || l.canWrite(l.checker.GetTypeOfSymbol(property), visited) {
			return true
		}
	}
	return false
}

// narrowedFrom reports whether from is the type parameter to itself, or it narrowed: an intersection
// with it among its members (T & {}, what a check against undefined leaves).
func (l *lowering) narrowedFrom(from *checker.Type, to *checker.Type) bool {
	if from == to {
		return true
	}
	if from.Flags()&checker.TypeFlagsIntersection != 0 {
		for _, member := range from.Types() {
			if member == to {
				return true
			}
		}
	}
	return false
}

// structured reports whether a type has parts to walk: an object or an intersection.
func (l *lowering) structured(proven *checker.Type) bool {
	return proven.Flags()&(checker.TypeFlagsObject|checker.TypeFlagsIntersection) != 0
}

// withoutUndefined is a type with undefined taken out of it: the one type left, or the union itself
// when several are, whose members widened walks one by one (definedMembers).
func (l *lowering) withoutUndefined(proven *checker.Type) *checker.Type {
	if members := l.definedMembers(proven); len(members) == 1 {
		return members[0]
	}
	return proven
}

// definedMembers is a union's members but undefined, or the type itself when it isn't a union.
func (l *lowering) definedMembers(proven *checker.Type) []*checker.Type {
	if proven == nil {
		return nil
	}
	if proven.Flags()&checker.TypeFlagsUnion == 0 {
		return []*checker.Type{proven}
	}
	var members []*checker.Type
	for _, member := range proven.Types() {
		if member.Flags()&checker.TypeFlagsUndefined == 0 {
			members = append(members, member)
		}
	}
	return members
}

// isClassInstance is the instance side of a class, generic or not.
func isClassInstance(proven *checker.Type) bool {
	if proven.Flags()&checker.TypeFlagsObject == 0 {
		return false
	}
	if proven.ObjectFlags()&checker.ObjectFlagsClass != 0 {
		return true
	}
	return proven.ObjectFlags()&checker.ObjectFlagsReference != 0 && proven.Target() != nil && proven.Target().ObjectFlags()&checker.ObjectFlagsClass != 0
}

// viewSite reports whether an expression is a value going into a typed slot: an initializer (a
// variable's, a parameter's default, a class field's), the right of an assignment, an argument, a
// returned value, a literal's property (shorthand too) or element, or an arrow's expression body.
// Parentheses around it are the same site.
func viewSite(node *ast.Node) bool {
	for node.Parent != nil && node.Parent.Kind == ast.KindParenthesizedExpression {
		node = node.Parent
	}
	parent := node.Parent
	if parent == nil {
		return false
	}
	switch parent.Kind {
	case ast.KindVariableDeclaration:
		// A destructuring declaration without a type keeps nothing of the value: its names take the
		// types of its parts, and the pattern's own type (its fields any) is no view of it.
		declaration := parent.AsVariableDeclaration()
		if ast.IsBindingPattern(declaration.Name()) && declaration.Type == nil {
			return false
		}
		return declaration.Initializer == node
	case ast.KindBinaryExpression:
		binary := parent.AsBinaryExpression()
		return binary.OperatorToken.Kind == ast.KindEqualsToken && binary.Right == node
	case ast.KindCallExpression:
		return parent.AsCallExpression().Expression != node
	case ast.KindNewExpression:
		return parent.AsNewExpression().Expression != node
	case ast.KindReturnStatement, ast.KindArrayLiteralExpression:
		return true
	case ast.KindPropertyAssignment:
		return parent.AsPropertyAssignment().Initializer == node
	case ast.KindParameter:
		return parent.AsParameterDeclaration().Initializer == node
	case ast.KindPropertyDeclaration:
		return parent.AsPropertyDeclaration().Initializer == node
	case ast.KindArrowFunction:
		return parent.AsArrowFunction().Body == node
	}
	return false
}

// refuseWidening refuses a value seen through a type that can write what it can't hold.
func (l *lowering) refuseWidening(node *ast.Node) error {
	if l.nodeFSFileReadOnlyArgument(node) || l.regexCallbackIntrinsicView(node) {
		return nil
	}
	var own, contextual *checker.Type
	var found *widening
	switch {
	case node.Kind == ast.KindAsExpression:
		as := node.AsAsExpression()
		if as.Type.Kind == ast.KindTypeReference && ast.IsIdentifier(as.Type.AsTypeReferenceNode().TypeName) && as.Type.AsTypeReferenceNode().TypeName.Text() == "const" {
			return nil
		}
		source, target := l.checker.GetTypeAtLocation(as.Expression), l.checker.GetTypeAtLocation(node)
		if l.checker.IsTypeAssignableTo(source, target) || l.checker.IsTypeAssignableTo(l.checker.GetWidenedType(source), target) {
			return l.provenRelation(node, as.Expression, target)
		}
		// Preserve the existing checks on downcasts; their lowering belongs to cast.go.
		own, contextual = source, target
		found = l.freshOrWidened(as.Expression, own, contextual)
	case node.Kind == ast.KindSatisfiesExpression:
		satisfies := node.AsSatisfiesExpression()
		return l.provenRelation(node, satisfies.Expression, l.checker.GetTypeAtLocation(satisfies.Type))
	case node.Kind == ast.KindShorthandPropertyAssignment:
		// { pets } is { pets: pets }: the variable seen as the literal's property.
		literal := l.checker.GetContextualType(node.Parent, checker.ContextFlagsNone)
		if literal == nil {
			return nil
		}
		property := l.checker.GetPropertyOfType(literal, node.Name().Text())
		if property == nil {
			return nil
		}
		own, contextual = l.checker.GetTypeAtLocation(node.Name()), l.checker.GetTypeOfSymbol(property)
		found = l.freshOrWidened(node.Name(), own, contextual)
	case node.Kind == ast.KindSpreadAssignment:
		// { ...kennel } copies kennel's fields, not what they hold: each field not written again after
		// it is kennel's value seen as the literal's field.
		literal := l.checker.GetContextualType(node.Parent, checker.ContextFlagsNone)
		if literal == nil {
			return nil
		}
		skip := map[string]bool{}
		after := false
		for _, property := range node.Parent.AsObjectLiteralExpression().Properties.Nodes {
			if property == node {
				after = true
			} else if after && property.Name() != nil {
				skip[property.Name().Text()] = true
			}
		}
		own, contextual = l.checker.GetTypeAtLocation(node.AsSpreadAssignment().Expression), literal
		found = l.widenedProperties(own, literal, skip, true, map[[2]*checker.Type]bool{})
	default:
		if node.Kind == ast.KindParenthesizedExpression || !l.isExpression(node) {
			return nil
		}
		if l.genericFunction(node) {
			// same<Item> written where a (value: number) => number goes is instantiated to exactly
			// that type, Item = number, so there's no wider view of it to judge.
			return nil
		}
		if pattern := destructuringTarget(node); pattern != nil {
			// [a, b] = tuple keeps nothing of the pattern: each element is read out and stored into
			// its name, so each element is the view, seen as its name's type, and the pattern isn't one.
			return l.refuseElementWidening(node, pattern)
		}
		if viewSite(node) {
			contextual = l.checker.GetContextualType(node, checker.ContextFlagsNone)
		}
		if contextual == nil {
			// With no type written for it, a value can still be taken into a wider one tsc made: the
			// union of a conditional's branches reduced to the wider (flag ? dogs : animals is an
			// Animal[]), a literal's elements likewise, a function's returns likewise.
			contextual = l.impliedTarget(node)
		}
		if contextual == nil {
			return nil
		}
		own = l.checker.GetTypeAtLocation(node)
		found = l.freshOrWidened(node, own, contextual)
	}
	if found == nil {
		return nil
	}
	return l.wideningRefusal(node, own, contextual, found)
}

func (l *lowering) wideningRefusal(node *ast.Node, own, contextual *checker.Type, found *widening) error {
	if found.enum {
		if enumObjectSymbol(found.target) != nil {
			return &Refused{Where: l.program.Where(node), What: "a structural object seen as " + l.checker.TypeToString(found.target) + "; the complete enum shape is unproven", Fix: "use the enum's runtime object or a typeof alias, or give the ordinary object an explicit interface"}
		}
		if l.flagEnum(l.enumIdentity(found.target)) && !l.numericEnum(l.enumIdentity(found.target)) {
			return l.flagWriteRefusal(node, found.target)
		}
		if l.numericEnum(l.enumIdentity(found.target)) || l.numericEnum(l.enumIdentity(found.source)) {
			return &Refused{Where: l.program.Where(node), What: "an unproven value assigned to a numeric literal or enum member slot " + l.checker.TypeToString(found.target), Fix: "compare with this literal and return that constant, or widen the slot to the whole numeric enum or number (adamic/enum-literal)"}
		}
		return &Refused{Where: l.program.Where(node), What: "an arbitrary number or a value from another enum assigned to " + l.checker.TypeToString(found.target) + "; its members are a closed union", Fix: "use a declared member of this enum, or compare the number with its members and return the matching member (adamic/enum-members)"}
	}
	what := "a value of type " + l.checker.TypeToString(own) + " seen as " + l.checker.TypeToString(contextual) + ", which can write " + l.checker.TypeToString(found.target) + " where " + l.checker.TypeToString(found.source) + " is read"
	fix := "make the wider type readonly (readonly T[], ReadonlyMap, readonly fields), which can't write; or copy the value ([...items], { ...item }) (adamic/invariant-mutable)"
	if found.parameter {
		what = "a function taking " + l.checker.TypeToString(found.source) + " seen as one taking " + l.checker.TypeToString(found.target) + " (tsc relates a method's parameters both ways), so it can be handed what it can't take"
		fix = "write the method as a property holding a function (handle: (animal: Animal) => void), which tsc checks one way, or take the wider type in the method (method-signature-style)"
	}
	if found.readonlyField != "" {
		what = "a value of type " + l.checker.TypeToString(own) + " seen as " + l.checker.TypeToString(contextual) + ", whose readonly field " + found.readonlyField + " becomes writable: a readonly field may hold something narrower than " + l.checker.TypeToString(found.source) + ", which a write of " + l.checker.TypeToString(found.target) + " would replace"
		fix = "keep " + found.readonlyField + " readonly in the type it's seen as, or copy the value ({ ...value }) (adamic/invariant-mutable)"
	}
	if found.target.Flags()&checker.TypeFlagsTypeParameter != 0 {
		what = "a value of type " + l.checker.TypeToString(found.source) + " seen as " + l.checker.TypeToString(found.target) + ", a type parameter whose constraint " + l.checker.TypeToString(l.checker.GetBaseConstraintOfType(found.target)) + " can be written, so it can write what " + l.checker.TypeToString(found.source) + " can't hold"
		fix = "take it as " + l.checker.TypeToString(found.source) + ", or constrain " + l.checker.TypeToString(found.target) + " to something readonly, which can't write (adamic/invariant-mutable)"
	}
	return &Refused{Where: l.program.Where(node), What: what, Fix: fix}
}

// freshOrWidened is widened for a value at a site, but a fresh one: a container made right there and
// held by nothing else (freshValue) can't be written through another name, so its own slots are
// covariant, and only what's inside it, held elsewhere too, is walked as a view.
func (l *lowering) freshOrWidened(node *ast.Node, own *checker.Type, contextual *checker.Type) *widening {
	node = ast.SkipParentheses(node)
	// A numeric enum read narrowed to never has a non-returning IR check at this exact site.
	// It cannot write a value into the contextual slot, including a closed string-enum slot.
	if own.Flags()&checker.TypeFlagsNever != 0 && l.enumNeverIdentity(node, map[*ast.Node]bool{}) != nil {
		return nil
	}
	targetLiteral := (contextual.Flags()&checker.TypeFlagsNumberLiteral != 0 || l.numericEnum(l.enumIdentity(contextual))) && !l.openNumericEnumType(contextual)
	if targetLiteral {
		if declared := l.enumStoredType(node); declared != nil {
			if l.openNumericEnumType(declared) && !l.enumMemberOrigin(node, l.enumIdentity(declared), map[*ast.Node]bool{}) {
				return &widening{source: declared, target: contextual, enum: true}
			}
		}
	}
	if found := l.flagMemberWidened(node, contextual); found != nil && !l.numericEnum(l.enumIdentity(found.target)) {
		return found
	}
	if target := l.flagTarget(contextual); target != nil && l.flagDomain(node, target) {
		return nil
	}
	switch node.Kind {
	case ast.KindObjectLiteralExpression, ast.KindArrayLiteralExpression:
		// Made as the type it's written into, held by nothing else: its own parts are sites.
		return nil
	case ast.KindConditionalExpression:
		// Either branch is the value: each judged as it is.
		conditional := node.AsConditionalExpression()
		for _, branch := range []*ast.Node{conditional.WhenTrue, conditional.WhenFalse} {
			if found := l.freshOrWidened(branch, l.checker.GetTypeAtLocation(branch), contextual); found != nil {
				return found
			}
		}
		return nil
	}
	visited := map[[2]*checker.Type]bool{}
	if !l.freshValue(node) {
		return l.widened(own, contextual, visited)
	}
	own, contextual = l.withoutUndefined(own), l.withoutUndefined(contextual)
	for _, viewed := range l.containers(contextual) {
		for _, inside := range l.containers(own) {
			if l.sameContainer(inside, viewed) {
				return l.widenedArguments(inside, viewed, false, visited)
			}
		}
	}
	return l.widened(own, contextual, visited)
}

// freshValue reports whether an expression makes a container nothing else holds: a copy (slice,
// filter, map, concat, Array.from) or a new Map, Set or Array.
func (l *lowering) freshValue(node *ast.Node) bool {
	switch node.Kind {
	case ast.KindNewExpression:
		callee := node.AsNewExpression().Expression
		return l.isLibraryGlobal(callee, "Map") || l.isLibraryGlobal(callee, "Set") || l.isLibraryGlobal(callee, "Array")
	case ast.KindCallExpression:
		callee := ast.SkipParentheses(node.AsCallExpression().Expression)
		if callee.Kind != ast.KindPropertyAccessExpression {
			return false
		}
		access := callee.AsPropertyAccessExpression()
		method := access.Name().Text()
		if method == "from" {
			return l.isLibraryGlobal(access.Expression, "Array")
		}
		switch method {
		case "slice", "filter", "map", "concat":
			return l.checker.IsArrayType(l.checker.GetTypeAtLocation(access.Expression)) || l.isLibraryType(l.checker.GetTypeAtLocation(access.Expression), "ReadonlyArray")
		}
	}
	return false
}

// isExpression reports whether a node is one a value can be: anything but a statement, a declaration,
// a name being declared or a type.
func (l *lowering) isExpression(node *ast.Node) bool {
	return ast.IsExpression(node) && !ast.IsPartOfTypeNode(node)
}

// impliedTarget is the type tsc gave what a value with no type written for it goes into, or nil: a
// conditional's (or ??'s, ||'s, &&'s) own type for its branches, an array literal's element type for
// its elements, and a function's inferred result for what it returns.
func (l *lowering) impliedTarget(node *ast.Node) *checker.Type {
	child := node
	for child.Parent != nil && child.Parent.Kind == ast.KindParenthesizedExpression {
		child = child.Parent
	}
	parent := child.Parent
	if parent == nil {
		return nil
	}
	switch parent.Kind {
	case ast.KindConditionalExpression:
		if conditional := parent.AsConditionalExpression(); conditional.WhenTrue == child || conditional.WhenFalse == child {
			return l.checker.GetTypeAtLocation(parent)
		}
	case ast.KindBinaryExpression:
		switch parent.AsBinaryExpression().OperatorToken.Kind {
		case ast.KindQuestionQuestionToken, ast.KindBarBarToken, ast.KindAmpersandAmpersandToken:
			return l.checker.GetTypeAtLocation(parent)
		}
	case ast.KindArrayLiteralExpression:
		literal := l.checker.GetTypeAtLocation(parent)
		if l.checker.IsArrayType(literal) {
			if arguments := l.checker.GetTypeArguments(literal); len(arguments) == 1 {
				return arguments[0]
			}
		}
	case ast.KindReturnStatement, ast.KindArrowFunction:
		if parent.Kind == ast.KindArrowFunction && parent.AsArrowFunction().Body != child {
			return nil
		}
		function := parent
		for function != nil && !ast.IsFunctionLike(function) {
			function = function.Parent
		}
		if function == nil {
			return nil
		}
		return l.checker.GetReturnTypeOfSignature(l.checker.GetSignatureFromDeclaration(function))
	}
	return nil
}

// destructuringTarget is the array pattern a value is assigned into, [a, b] = value, or nil.
func destructuringTarget(node *ast.Node) *ast.Node {
	for node.Parent != nil && node.Parent.Kind == ast.KindParenthesizedExpression {
		node = node.Parent
	}
	if parent := node.Parent; parent != nil && parent.Kind == ast.KindBinaryExpression {
		binary := parent.AsBinaryExpression()
		if binary.OperatorToken.Kind == ast.KindEqualsToken && binary.Right == node && binary.Left.Kind == ast.KindArrayLiteralExpression {
			return binary.Left
		}
	}
	return nil
}

// refuseElementWidening refuses [a, b] = tuple when an element is seen through its name's type as
// a view that can write what the element can't hold: [animals] = [dogs] puts a Dog[] in an
// Animal[]. A value that isn't a tuple is judged whole, as anywhere.
func (l *lowering) refuseElementWidening(node *ast.Node, pattern *ast.Node) error {
	own := l.checker.GetTypeAtLocation(node)
	if !checker.IsTupleType(own) {
		contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone)
		if contextual == nil {
			return nil
		}
		if found := l.widened(own, contextual, map[[2]*checker.Type]bool{}); found != nil {
			return &Refused{Where: l.program.Where(node), What: "a value of type " + l.checker.TypeToString(own) + " seen as " + l.checker.TypeToString(contextual) + ", which can write " + l.checker.TypeToString(found.target) + " where " + l.checker.TypeToString(found.source) + " is read", Fix: "make the wider type readonly (readonly T[], ReadonlyMap, readonly fields), which can't write; or copy the value ([...items], { ...item }) (adamic/invariant-mutable)"}
		}
		return nil
	}
	elements := l.checker.GetTypeArguments(own)
	for index, target := range pattern.AsArrayLiteralExpression().Elements.Nodes {
		if index >= len(elements) || target.Kind == ast.KindOmittedExpression {
			continue
		}
		to := l.checker.GetTypeAtLocation(target)
		if found := l.widened(elements[index], to, map[[2]*checker.Type]bool{}); found != nil {
			return &Refused{Where: l.program.Where(target), What: "a value of type " + l.checker.TypeToString(elements[index]) + " seen as " + l.checker.TypeToString(to) + ", which can write " + l.checker.TypeToString(found.target) + " where " + l.checker.TypeToString(found.source) + " is read", Fix: "make the wider type readonly (readonly T[], ReadonlyMap, readonly fields), which can't write; or copy the value ([...items], { ...item }) (adamic/invariant-mutable)"}
		}
	}
	return nil
}

// genericFunction reports whether an expression is a function with type parameters of its own,
// which tsc instantiates to the type it's written into rather than viewing it through that type.
func (l *lowering) genericFunction(node *ast.Node) bool {
	for _, signature := range l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(node), checker.SignatureKindCall) {
		if len(signature.TypeParameters()) > 0 {
			return true
		}
	}
	return false
}

iteration.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
)

// The symbol slot has a reserved spelling only in IR. Source string fields may not use it.
const iteratorSlot = "__adamic_symbol_iterator"

func (l *lowering) symbolIterator(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	return node.Kind == ast.KindPropertyAccessExpression && node.Name().Text() == "iterator" && l.isLibraryGlobal(node.AsPropertyAccessExpression().Expression, "Symbol")
}

func (l *lowering) methodName(node *ast.Node) (string, bool) {
	name := node.Name()
	if name == nil {
		return "", false
	}
	if ast.IsIdentifier(name) || name.Kind == ast.KindStringLiteral {
		return name.Text(), name.Text() != iteratorSlot
	}
	if name.Kind == ast.KindComputedPropertyName {
		if text, known := constantStringKey(name.AsComputedPropertyName().Expression); known {
			return text, text != iteratorSlot
		}
	}
	if name.Kind == ast.KindComputedPropertyName && l.symbolIterator(name.AsComputedPropertyName().Expression) {
		return iteratorSlot, true
	}
	return "", false
}

func (l *lowering) iteratorMember(proven *checker.Type) *ast.Symbol {
	for _, member := range l.checker.GetPropertiesOfType(l.concrete(proven)) {
		for _, root := range l.checker.GetRootSymbols(member) {
			for _, declaration := range root.Declarations {
				if name, known := l.methodName(declaration); known && name == iteratorSlot && !load.IsLibrary(ast.GetSourceFileOfNode(declaration)) {
					return member
				}
			}
		}
	}
	return nil
}

// Literal methods receive this as an argument, rather than capturing their owner. Their ordinary
// lexical captures still use the existing cycle analysis and reference-counted closure environment.
func (l *lowering) objectMethod(node *ast.Node) (ir.Expression, error) {
	index := len(l.result.Functions)
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "object_method", Closure: true, Receiver: true})
	this := l.iterationLocal("this", ir.Object, index)
	l.noteLocal(this, l.checker.GetTypeAtLocation(node.Parent), node)
	l.closureRecords = append(l.closureRecords, closureRecord{proven: l.checker.GetTypeAtLocation(node), function: index, node: node})
	l.closures = append(l.closures, index)
	err := l.lowerFunction(index, node, this)
	l.closures = l.closures[:len(l.closures)-1]
	if err != nil {
		return nil, err
	}
	return ir.MakeClosure{Function: index}, nil
}

func (l *lowering) iterationLocal(name string, of ir.Type, function int) int {
	local := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: name, Type: of, Function: function})
	return local
}

// memberReceiver rejects erased method origins: a class method, a literal method and an arrow
// field have different calling conventions, which a bare structural interface does not preserve.
func (l *lowering) memberReceiver(where *ast.Node, member *ast.Symbol) (bool, error) {
	if member == nil || member.Flags&ast.SymbolFlagsOptional != 0 {
		return false, l.notYet(where, "an optional iterator method (runtime method presence is not represented)")
	}
	convention := -1
	for _, root := range l.checker.GetRootSymbols(member) {
		for _, declaration := range root.Declarations {
			current := 0
			switch declaration.Kind {
			case ast.KindMethodDeclaration:
				current = 1
			case ast.KindPropertyAssignment, ast.KindShorthandPropertyAssignment, ast.KindPropertyDeclaration:
				if ast.HasSyntacticModifier(declaration, ast.ModifierFlagsAmbient) {
					return false, l.notYet(where, "a declared iterator method with no runtime field")
				}
			default:
				return false, l.notYet(where, "an iterator method whose concrete origin is erased by a structural signature")
			}
			if convention >= 0 && convention != current {
				return false, l.notYet(where, "iterator methods with mixed receiver conventions")
			}
			convention = current
		}
	}
	if convention < 0 {
		return false, l.notYet(where, "an iterator method without a concrete declaration")
	}
	return convention == 1, nil
}

func (l *lowering) memberFunction(where *ast.Node, proven *checker.Type, value ir.Expression, member *ast.Symbol) (ir.Expression, bool, int, error) {
	receiver, err := l.memberReceiver(where, member)
	if err != nil {
		return nil, false, -1, err
	}
	for _, root := range l.checker.GetRootSymbols(member) {
		for _, declaration := range root.Declarations {
			if declaration.Kind == ast.KindMethodDeclaration && declaration.Parent.Kind == ast.KindClassDeclaration {
				if !isClassInstance(l.concrete(proven)) {
					return nil, false, -1, l.notYet(where, "a class iterator method through a structural object view")
				}
				class := l.classes[l.symbol(declaration.Parent.Name())]
				if class == nil {
					return nil, false, -1, l.notYet(where, "an iterator class not declared in this program")
				}
				instance, err := l.instantiate(class, proven, where)
				if err != nil {
					return nil, false, -1, err
				}
				return nil, true, instance.methods[l.methodKey(declaration, instance.class)], nil
			}
		}
	}
	name := member.Name
	for _, root := range l.checker.GetRootSymbols(member) {
		for _, declaration := range root.Declarations {
			if key, known := l.methodName(declaration); known {
				name = key
			}
		}
	}
	return ir.Property{Object: value, Name: name, Of: ir.Closure}, receiver, -1, nil
}

func invokeMember(function ir.Expression, receiver bool, direct int, value ir.Expression, arguments []ir.Expression, returns ir.Type) ir.Expression {
	if receiver {
		arguments = append([]ir.Expression{value}, arguments...)
	}
	if direct >= 0 {
		return ir.Call{Function: direct, Arguments: arguments, Returns: returns}
	}
	return ir.CallClosure{Closure: function, Arguments: arguments, Returns: returns}
}

func (l *lowering) memberResult(where *ast.Node, member *ast.Symbol) (*checker.Type, error) {
	signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeOfSymbol(member), checker.SignatureKindCall)
	if len(signatures) != 1 || len(signatures[0].Parameters()) != 0 {
		return nil, l.notYet(where, "an iterator protocol method with arguments or overloads")
	}
	result := l.concrete(l.checker.GetReturnTypeOfSignature(signatures[0]))
	if of, known := l.representation(result); !known || of != ir.Object || l.includesUndefined(result) {
		return nil, l.notYet(where, "an iterator protocol method that does not return a represented object")
	}
	return result, nil
}

type iterationPlan struct {
	source, iterator, step *checker.Type
	entry, next, close     *ast.Symbol
	element                ir.Type
}

func (l *lowering) planIteration(where *ast.Node) (*iterationPlan, error) {
	source := l.concrete(l.checker.GetTypeAtLocation(where))
	entry := l.iteratorMember(source)
	if entry == nil {
		return nil, nil
	}
	if of, known := l.representation(source); !known || of != ir.Object || l.includesUndefined(source) {
		return nil, l.notYet(where, "a custom iterable without a present object representation")
	}
	if _, err := l.memberReceiver(where, entry); err != nil {
		return nil, err
	}
	iterator, err := l.memberResult(where, entry)
	if err != nil {
		return nil, err
	}
	next := l.checker.GetPropertyOfType(iterator, "next")
	if _, err := l.memberReceiver(where, next); err != nil {
		return nil, err
	}
	step, err := l.memberResult(where, next)
	if err != nil {
		return nil, err
	}
	done := l.checker.GetPropertyOfType(step, "done")
	if done == nil || done.Flags&ast.SymbolFlagsOptional != 0 {
		return nil, l.notYet(where, "an iterator result without a required boolean done field")
	}
	if of, known := l.representation(l.checker.GetTypeOfSymbol(done)); !known || of != ir.Boolean {
		return nil, l.notYet(where, "an iterator result whose done is not a boolean")
	}
	value := l.checker.GetPropertyOfType(step, "value")
	if value == nil || value.Flags&ast.SymbolFlagsOptional != 0 {
		return nil, l.notYet(where, "an iterator result without a represented value field")
	}
	element, known := l.representation(l.checker.GetTypeOfSymbol(value))
	if !known || slotless(element) || element == ir.Weak {
		return nil, l.notYet(where, "an iterator result whose value has no single-slot representation")
	}
	close := l.checker.GetPropertyOfType(iterator, "return")
	if close != nil {
		if _, err := l.memberReceiver(where, close); err != nil {
			return nil, err
		}
		if _, err := l.memberResult(where, close); err != nil {
			return nil, err
		}
	}
	// A view which omits return must not hide a runtime close method. Method signatures themselves
	// are refused above, but a concrete literal can also be viewed as another concrete literal type.
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return nil, err
	}
	// Until protocol calls dispatch virtually, prove that a returned receiver cannot
	// override next/return or introduce a close method hidden by the return annotation.
	if l.iterationFactoryReturnsThis(entry) && l.iteratorReceiverOverrides(modules, iterator, next, close) {
		members := []*ast.Symbol{next}
		if close != nil {
			members = append(members, close)
		}
		presence := close != nil
		if !l.iterationOrigin(where, members, &presence, 0) {
			return nil, &Refused{Where: l.program.Where(where), What: "an iterator factory returning this whose runtime next or return can differ from its declared iterator type (adamic/iterator-receiver-origin)", Fix: "return a separate iterator object with next and return closures; do not erase subclass protocol methods behind the base iterator return type"}
		}
	}
	sourceKnown := l.iterationOrigin(where, []*ast.Symbol{entry}, nil, 0)
	iteratorKnown := sourceKnown && l.iterationFactoryKnown(entry, next, close)
	if isClassInstance(source) && len(l.checker.GetTypeArguments(source)) > 0 && !l.knownIterationClass(where, source, 0) {
		return nil, l.notYet(where, "a generic iterable view without proven native type arguments")
	}
	if isClassInstance(iterator) && len(l.checker.GetTypeArguments(iterator)) > 0 && (!sourceKnown || !l.genericIteratorFactoryKnown(entry, source, iterator)) {
		return nil, l.notYet(where, "a generic iterator view without proven native type arguments")
	}

	var hazard error
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if hazard != nil {
			return true
		}
		if node.Kind == ast.KindObjectLiteralExpression || node.Kind == ast.KindNewExpression {
			shape := l.checker.GetTypeAtLocation(node)
			if l.iterationShapeFits(shape, step) {
				for _, key := range []string{"done", "value"} {
					if field := l.checker.GetPropertyOfType(shape, key); field != nil {
						for _, declaration := range field.Declarations {
							if ast.HasSyntacticModifier(declaration, ast.ModifierFlagsAmbient) {
								hazard = l.notYet(where, "an iterator result with declared fields absent at runtime")
								return true
							}
						}
					}
				}
			}
			if !sourceKnown && l.iterationShapeFits(shape, source) {
				actual := l.iteratorMember(shape)
				if actual == nil || memberConvention(actual) != memberConvention(entry) {
					hazard = l.notYet(where, "an iterable view that erases its method receiver convention")
					return true
				}
			}
			if !iteratorKnown && l.iterationShapeFits(shape, iterator) {
				actual := l.checker.GetPropertyOfType(shape, "next")
				if memberConvention(actual) != memberConvention(next) {
					hazard = l.notYet(where, "an iterator view that erases its method receiver convention")
					return true
				}
				actualClose := l.checker.GetPropertyOfType(shape, "return")
				if close != nil && memberConvention(actualClose) != memberConvention(close) {
					hazard = l.notYet(where, "an iterator view that erases its return receiver convention")
					return true
				}
			}
			if node.Kind == ast.KindObjectLiteralExpression {
				for _, property := range node.AsObjectLiteralExpression().Properties.Nodes {
					if property.Kind == ast.KindSpreadAssignment && (l.iterationShapeFits(shape, iterator) || l.iterationShapeFits(shape, source)) {
						hazard = l.notYet(where, "an iterator built by object spread (own method presence is not proved)")
						return true
					}
				}
			}
			if !iteratorKnown && l.iterationShapeFits(shape, iterator) && (l.checker.GetPropertyOfType(shape, "return") != nil) != (close != nil) {
				hazard = l.notYet(where, "an iterator view that can hide a return method")
				return true
			}
		}
		if node.Kind == ast.KindBinaryExpression && node.AsBinaryExpression().OperatorToken.Kind == ast.KindEqualsToken {
			target := ast.SkipParentheses(node.AsBinaryExpression().Left)
			if target.Kind == ast.KindPropertyAccessExpression {
				access := target.AsPropertyAccessExpression()
				key := access.Name().Text()
				targetType := l.checker.GetTypeAtLocation(access.Expression)
				if (key == "next" || key == "return") && (l.checker.IsTypeAssignableTo(iterator, targetType) || l.checker.IsTypeAssignableTo(targetType, iterator)) {
					hazard = l.notYet(where, "replacing an iterator protocol method at runtime")
					return true
				}
			}
		}
		return node.ForEachChild(visit)
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	if hazard != nil {
		return nil, hazard
	}
	return &iterationPlan{source: source, iterator: iterator, step: step, entry: entry, next: next, close: close, element: element}, nil
}

type iterationState struct {
	plan     *iterationPlan
	iterator ir.Expression
	next     ir.Expression
	receiver bool
	direct   int
	active   int
}

func (l *lowering) startIteration(where *ast.Node, plan *iterationPlan, source ir.Expression) ([]ir.Statement, *iterationState, error) {
	function, receiver, direct, err := l.memberFunction(where, plan.source, source, plan.entry)
	if err != nil {
		return nil, nil, err
	}
	iterator := l.iterationLocal("iterator", ir.Object, l.functionIndex)
	active := l.iterationLocal("iterator_close_needed", ir.Boolean, l.functionIndex)
	read := ir.Read{Local: iterator, Of: ir.Object}
	statements := []ir.Statement{ir.Declare{Local: iterator, Value: invokeMember(function, receiver, direct, source, nil, ir.Object)}, ir.Declare{Local: active, Value: ir.BooleanConstant{Value: false}}}
	next, receiver, direct, err := l.memberFunction(where, plan.iterator, read, plan.next)
	if err != nil {
		return nil, nil, err
	}
	if direct < 0 {
		cached := l.iterationLocal("iterator_next", ir.Closure, l.functionIndex)
		statements = append(statements, ir.Declare{Local: cached, Value: next})
		next = ir.Read{Local: cached, Of: ir.Closure}
	}
	return statements, &iterationState{plan: plan, iterator: read, next: next, receiver: receiver, direct: direct, active: active}, nil
}

func (l *lowering) iterationStep(state *iterationState) ([]ir.Statement, ir.Expression) {
	step := l.iterationLocal("iterator_result", ir.Object, l.functionIndex)
	read := ir.Read{Local: step, Of: ir.Object}
	statements := []ir.Statement{
		ir.Assign{Local: state.active, Value: ir.BooleanConstant{Value: false}},
		ir.Declare{Local: step, Value: invokeMember(state.next, state.receiver, state.direct, state.iterator, nil, ir.Object)},
		ir.If{Condition: ir.Property{Object: read, Name: "done", Of: ir.Boolean}, Then: []ir.Statement{ir.Break{}}},
	}
	value := ir.Property{Object: read, Name: "value", Of: state.plan.element}
	return statements, value
}

// IteratorClose preserves an incoming throw even if return throws. Break and return instead let
// that close failure replace their completion. The active flag excludes exhaustion and next errors.
func (l *lowering) closeIteration(where *ast.Node, state *iterationState, body []ir.Statement) ([]ir.Statement, error) {
	if state.plan.close == nil {
		return body, nil
	}
	function, receiver, direct, err := l.memberFunction(where, state.plan.iterator, state.iterator, state.plan.close)
	if err != nil {
		return nil, err
	}
	close := []ir.Statement{ir.Evaluate{Value: invokeMember(function, receiver, direct, state.iterator, nil, ir.Object)}}
	thrown := l.iterationLocal("iterator_pending_throw", ir.Boolean, l.functionIndex)
	caught := l.iterationLocal("iterator_error", ir.Object, l.functionIndex)
	// Distinct branches need distinct statement identities for flow analysis and tracing.
	cleanup := ir.If{Condition: ir.Read{Local: state.active, Of: ir.Boolean}, Then: []ir.Statement{
		ir.If{Condition: ir.Read{Local: thrown, Of: ir.Boolean}, Then: []ir.Statement{ir.Try{Body: close, HasCatch: true, CatchLocal: -1}}, Else: append([]ir.Statement{}, close...)},
	}}
	guarded := ir.Try{Body: body, HasCatch: true, CatchLocal: caught, Catch: []ir.Statement{ir.Assign{Local: thrown, Value: ir.BooleanConstant{Value: true}}, ir.Throw{Value: ir.Read{Local: caught, Of: ir.Object}}}, HasFinally: true, Finally: []ir.Statement{cleanup}}
	l.tries = append(l.tries, tryRecord{node: where, body: body})
	return []ir.Statement{ir.Declare{Local: thrown, Value: ir.BooleanConstant{Value: false}}, guarded}, nil
}

func (l *lowering) forOfUser(node *ast.Node, plan *iterationPlan, name *ast.Node) ([]ir.Statement, error) {
	source, err := l.expression(node.AsForInOrOfStatement().Expression)
	if err != nil {
		return nil, err
	}
	held := l.iterationLocal("iterable", ir.Object, l.functionIndex)
	read := ir.Read{Local: held, Of: ir.Object}
	setup, state, err := l.startIteration(node, plan, read)
	if err != nil {
		return nil, err
	}
	step, value := l.iterationStep(state)
	if ast.IsIdentifier(name) {
		local, err := l.declareLocal(name)
		if err != nil {
			return nil, err
		}
		if l.result.Locals[local].Type != plan.element {
			return nil, l.notYet(name, "an iteration variable with a different value representation")
		}
		step = append(step, ir.Declare{Local: local, Value: value})
	} else {
		valueType := l.checker.GetTypeOfSymbol(l.checker.GetPropertyOfType(plan.step, "value"))
		heldValue := l.iterationLocal("iteration_value", plan.element, l.functionIndex)
		bound, err := l.destructureFrom(name, valueType, plan.element, heldValue)
		if err != nil {
			return nil, err
		}
		step = append(step, ir.Declare{Local: heldValue, Value: value})
		step = append(step, bound...)
	}
	body, err := l.statement(node.AsForInOrOfStatement().Statement)
	if err != nil {
		return nil, err
	}
	step = append(step, ir.Assign{Local: state.active, Value: ir.BooleanConstant{Value: true}})
	step = append(step, body...)
	loop := ir.Loop{Condition: ir.BooleanConstant{Value: true}, Body: step, Update: []ir.Statement{ir.Assign{Local: state.active, Value: ir.BooleanConstant{Value: false}}}}
	guarded, err := l.closeIteration(node, state, []ir.Statement{loop})
	if err != nil {
		return nil, err
	}
	statements := append([]ir.Statement{ir.Declare{Local: held, Value: source}}, setup...)
	return []ir.Statement{ir.Block{Body: append(statements, guarded...)}}, nil
}

func (l *lowering) userMethodCall(node *ast.Node) (ir.Expression, bool, error) {
	callee := ast.SkipParentheses(node.AsCallExpression().Expression)
	var receiverNode *ast.Node
	var member *ast.Symbol
	switch callee.Kind {
	case ast.KindElementAccessExpression:
		access := callee.AsElementAccessExpression()
		if !l.symbolIterator(access.ArgumentExpression) {
			return nil, false, nil
		}
		receiverNode = access.Expression
		member = l.iteratorMember(l.checker.GetTypeAtLocation(receiverNode))
		if member == nil {
			return nil, true, l.notYet(node, "an explicit Symbol.iterator call on a built-in value")
		}
	case ast.KindPropertyAccessExpression:
		member = l.checker.GetSymbolAtLocation(callee)
		if member == nil || !literalMethod(member) {
			return nil, false, nil
		}
		value, err := l.callClosure(node)
		return value, true, err
	default:
		return nil, false, nil
	}
	value, err := l.expression(receiverNode)
	if err != nil {
		return nil, true, err
	}
	arguments := []ir.Expression{value}
	for _, argument := range node.AsCallExpression().Arguments.Nodes {
		lowered, err := l.expression(argument)
		if err != nil {
			return nil, true, err
		}
		arguments = append(arguments, lowered)
	}
	proven := l.checker.GetTypeAtLocation(node)
	result, known := l.representation(proven)
	void := proven.Flags()&(checker.TypeFlagsVoid|checker.TypeFlagsNever) != 0
	if void {
		result = 0
	}
	if (!known && !void) || slotless(result) {
		return nil, true, l.notYet(node, "a literal method call with an unrepresented result")
	}
	function := len(l.result.Functions)
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "invoke_method", Returns: result})
	parameters := []int{}
	for _, argument := range arguments {
		parameters = append(parameters, l.iterationLocal("argument", argument.Type(), function))
	}
	object := ir.Read{Local: parameters[0], Of: ir.Object}
	method, hasReceiver, direct, err := l.memberFunction(node, l.checker.GetTypeAtLocation(receiverNode), object, member)
	if err != nil {
		return nil, true, err
	}
	passed := []ir.Expression{}
	for index, parameter := range parameters[1:] {
		passed = append(passed, ir.Read{Local: parameter, Of: arguments[index+1].Type()})
	}
	call := invokeMember(method, hasReceiver, direct, object, passed, result)
	body := []ir.Statement{ir.Return{Value: call}}
	if void {
		// A void method still runs with its receiver and arguments, but has no value to return.
		body = []ir.Statement{ir.Evaluate{Value: call}}
	}
	l.result.Functions[function] = ir.Function{Name: "invoke_method", Returns: result, Parameters: parameters, Body: body}
	return ir.Call{Function: function, Arguments: arguments, Returns: result}, true, nil
}

iteration_consume.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// collectIteration keeps stepping and mapping interleaved. Materializing before mapping would
// change side effects and would fail to close the iterator when the mapper throws.
func (l *lowering) collectIteration(where, sourceNode, callbackNode *ast.Node, plan *iterationPlan, element ir.Type) (ir.Expression, error) {
	source, err := l.expression(sourceNode)
	if err != nil {
		return nil, err
	}
	arguments := []ir.Expression{source}
	var callback ir.Expression
	var callbackReturns ir.Type
	callbackCount := 0
	if callbackNode != nil {
		callback, err = l.expression(callbackNode)
		if err != nil {
			return nil, err
		}
		signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(callbackNode), checker.SignatureKindCall)
		if len(signatures) != 1 || len(signatures[0].Parameters()) > 2 {
			return nil, l.notYet(callbackNode, "an Array.from mapper with overloads or more than two parameters")
		}
		callbackCount = len(signatures[0].Parameters())
		callbackReturns, _ = l.representation(l.checker.GetReturnTypeOfSignature(signatures[0]))
		if callbackReturns != element {
			return nil, l.notYet(callbackNode, "an Array.from mapper with a different result representation")
		}
		if callbackCount > 0 {
			parameter, _ := l.representation(l.checker.GetTypeOfSymbol(signatures[0].Parameters()[0]))
			if parameter != plan.element {
				return nil, l.notYet(callbackNode, "an Array.from mapper with a different input representation")
			}
		}
		if callbackCount > 1 {
			parameter, _ := l.representation(l.checker.GetTypeOfSymbol(signatures[0].Parameters()[1]))
			if parameter != ir.Number {
				return nil, l.notYet(callbackNode, "an Array.from mapper with a different index representation")
			}
		}
		arguments = append(arguments, callback)
	} else if element != plan.element {
		return nil, l.notYet(where, "a collected iterator value with a different element representation")
	}
	function := len(l.result.Functions)
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "collect_iterator", Returns: ir.Array})
	outerIndex := l.functionIndex
	l.functionIndex = function
	defer func() { l.functionIndex = outerIndex }()
	held := l.iterationLocal("iterable", ir.Object, function)
	parameters := []int{held}
	if callback != nil {
		mapped := l.iterationLocal("mapper", ir.Closure, function)
		parameters = append(parameters, mapped)
		callback = ir.Read{Local: mapped, Of: ir.Closure}
	}
	setup, state, err := l.startIteration(where, plan, ir.Read{Local: held, Of: ir.Object})
	if err != nil {
		return nil, err
	}
	output := l.iterationLocal("collected", ir.Array, function)
	index := l.iterationLocal("index", ir.Number, function)
	setup = append(setup, ir.Declare{Local: output, Value: ir.ArrayLiteral{Element: element}}, ir.Declare{Local: index, Value: ir.NumberConstant{Value: 0}})
	step, value := l.iterationStep(state)
	if callback != nil {
		callArguments := []ir.Expression{}
		if callbackCount > 0 {
			callArguments = append(callArguments, value)
		} else {
			step = append(step, ir.Evaluate{Value: value})
		}
		if callbackCount > 1 {
			callArguments = append(callArguments, ir.Read{Local: index, Of: ir.Number})
		}
		step = append(step, ir.Assign{Local: state.active, Value: ir.BooleanConstant{Value: true}})
		value = ir.CallClosure{Closure: callback, Arguments: callArguments, Returns: callbackReturns}
	}
	step = append(step, ir.Evaluate{Value: ir.ArrayPush{Array: ir.Read{Local: output, Of: ir.Array}, Value: value, Element: element, Site: l.iterationArrayWriteSite(where)}}, ir.Assign{Local: index, Value: ir.Binary{Operator: ir.Add, Left: ir.Read{Local: index, Of: ir.Number}, Right: ir.NumberConstant{Value: 1}}})
	loop := ir.Loop{Condition: ir.BooleanConstant{Value: true}, Body: step, Update: []ir.Statement{ir.Assign{Local: state.active, Value: ir.BooleanConstant{Value: false}}}}
	body := []ir.Statement{loop}
	if callback != nil {
		body, err = l.closeIteration(where, state, body)
		if err != nil {
			return nil, err
		}
	}
	setup = append(setup, body...)
	setup = append(setup, ir.Return{Value: ir.Read{Local: output, Of: ir.Array}})
	l.result.Functions[function] = ir.Function{Name: "collect_iterator", Returns: ir.Array, Parameters: parameters, Body: setup}
	return ir.Call{Function: function, Arguments: arguments, Returns: ir.Array}, nil
}

func (l *lowering) iteratedType(node *ast.Node) (*iterationPlan, ir.Type, error) {
	if plan, err := l.planIteration(node); err != nil {
		return nil, 0, err
	} else if plan != nil {
		return plan, plan.element, nil
	}
	element, err := l.elementType(node)
	return nil, element, err
}

// Destructuring steps only as far as the pattern asks. Defaults are evaluated after their step,
// and each binding is declared before the next step. Exhaustion is sticky, including across holes.
func (l *lowering) destructureIterator(pattern, sourceNode *ast.Node, plan *iterationPlan) ([]ir.Statement, error) {
	source, err := l.expression(sourceNode)
	if err != nil {
		return nil, err
	}
	held := l.iterationLocal("iterable", ir.Object, l.functionIndex)
	setup, state, err := l.startIteration(pattern, plan, ir.Read{Local: held, Of: ir.Object})
	if err != nil {
		return nil, err
	}
	statements := append([]ir.Statement{ir.Declare{Local: held, Value: source}}, setup...)
	done := l.iterationLocal("iterator_done", ir.Boolean, l.functionIndex)
	statements = append(statements, ir.Declare{Local: done, Value: ir.BooleanConstant{Value: false}})
	for _, binding := range pattern.AsBindingPattern().Elements.Nodes {
		hole := binding.Kind == ast.KindOmittedExpression || binding.Name() == nil
		if !hole && !ast.IsIdentifier(binding.Name()) {
			return nil, l.notYet(binding, "a nested custom iterator destructuring pattern")
		}
		if !hole && binding.AsBindingElement().DotDotDotToken != nil {
			local, err := l.declareLocal(binding.Name())
			if err != nil {
				return nil, err
			}
			element, err := l.elementType(binding.Name())
			if err != nil || element != plan.element {
				return nil, l.notYet(binding, "an iterator rest binding with a different element representation")
			}
			collected := l.iterationLocal("rest_values", ir.Array, l.functionIndex)
			statements = append(statements, ir.Declare{Local: collected, Value: ir.ArrayLiteral{Element: element}})
			step, value := l.iterationStep(state)
			step = append(step, ir.Evaluate{Value: ir.ArrayPush{Array: ir.Read{Local: collected, Of: ir.Array}, Value: value, Element: element, Site: l.writeSite(binding.Name())}})
			statements = append(statements, ir.If{Condition: ir.Unary{Operator: ir.Not, Operand: ir.Read{Local: done, Of: ir.Boolean}}, Then: []ir.Statement{ir.Loop{Condition: ir.BooleanConstant{Value: true}, Body: step}}}, ir.Assign{Local: done, Value: ir.BooleanConstant{Value: true}})
			// The binding stays uninitialized while next runs; only the temporary owns the array.
			statements = append(statements, ir.Declare{Local: local, Value: ir.Read{Local: collected, Of: ir.Array}})
			continue
		}
		stepLocal := l.iterationLocal("iterator_result", ir.Object, l.functionIndex)
		result := ir.Read{Local: stepLocal, Of: ir.Object}
		step := []ir.Statement{ir.Assign{Local: state.active, Value: ir.BooleanConstant{Value: false}}, ir.Declare{Local: stepLocal, Value: invokeMember(state.next, state.receiver, state.direct, state.iterator, nil, ir.Object)}, ir.Assign{Local: done, Value: ir.Property{Object: result, Name: "done", Of: ir.Boolean}}}
		valueLocal := -1
		if !hole {
			valueLocal = l.iterationLocal("destructured_value", plan.element, l.functionIndex)
			statements = append(statements, ir.Declare{Local: valueLocal, Value: zeroValue(plan.element)})
			step = append(step, ir.If{Condition: ir.Unary{Operator: ir.Not, Operand: ir.Read{Local: done, Of: ir.Boolean}}, Then: []ir.Statement{ir.Assign{Local: valueLocal, Value: ir.Property{Object: result, Name: "value", Of: plan.element}}}})
		}
		statements = append(statements, ir.If{Condition: ir.Unary{Operator: ir.Not, Operand: ir.Read{Local: done, Of: ir.Boolean}}, Then: step})
		if hole {
			continue
		}
		var fallback ir.Expression
		if initializer := binding.AsBindingElement().Initializer; initializer != nil {
			fallback, err = l.expression(initializer)
			if err != nil {
				return nil, err
			}
		} else {
			valueType := l.checker.GetTypeOfSymbol(l.checker.GetPropertyOfType(plan.step, "value"))
			if !l.includesUndefined(valueType) {
				return nil, &Refused{Where: l.program.Where(binding), What: "an iterator binding whose type omits undefined on exhaustion", Fix: "give the binding a default, [value = fallback], or make the yielded type include undefined; TypeScript does not account for early iterator exhaustion"}
			}
			fallback = fit(ir.Undefined{}, plan.element)
		}
		local, err := l.declareLocal(binding.Name())
		if err != nil {
			return nil, err
		}
		of := l.result.Locals[local].Type
		value := ir.Expression(ir.Read{Local: valueLocal, Of: plan.element})
		if binding.AsBindingElement().Initializer != nil && l.includesUndefined(l.checker.GetTypeOfSymbol(l.checker.GetPropertyOfType(plan.step, "value"))) {
			value = ir.Coalesce{Value: value, Fallback: fit(fallback, of), Of: of}
		} else {
			value = fit(value, of)
		}
		fallback = fit(fallback, of)
		if value.Type() != of || fallback.Type() != of {
			return nil, l.notYet(binding, "an iterator default with a different binding representation")
		}
		temporary := l.iterationLocal("binding_value", of, l.functionIndex)
		statements = append(statements, ir.Declare{Local: temporary, Value: zeroValue(of)}, ir.Assign{Local: state.active, Value: ir.Unary{Operator: ir.Not, Operand: ir.Read{Local: done, Of: ir.Boolean}}})
		evaluation := []ir.Statement{ir.Assign{Local: temporary, Value: ir.Conditional{Condition: ir.Read{Local: done, Of: ir.Boolean}, WhenTrue: fallback, WhenNot: value}}, ir.Assign{Local: state.active, Value: ir.BooleanConstant{Value: false}}}
		guarded, err := l.closeIteration(binding, state, evaluation)
		if err != nil {
			return nil, err
		}
		statements = append(statements, guarded...)
		statements = append(statements, ir.Declare{Local: local, Value: ir.Read{Local: temporary, Of: of}})
	}
	statements = append(statements, ir.Assign{Local: state.active, Value: ir.Unary{Operator: ir.Not, Operand: ir.Read{Local: done, Of: ir.Boolean}}})
	close, err := l.closeIteration(pattern, state, nil)
	if err != nil {
		return nil, err
	}
	return append(statements, close...), nil
}

// Generated spread collectors have no source-level array receiver. Keep unknown holder types
// conservative for cycle analysis; Array.from has its result type available on the call itself.
func (l *lowering) iterationArrayWriteSite(where *ast.Node) int {
	var holder *checker.Type
	proven := l.concrete(l.checker.GetTypeAtLocation(where))
	if l.checker.IsArrayType(proven) {
		holder = proven
	}
	l.writeSites = append(l.writeSites, writeSite{holder: holder, node: where})
	return len(l.writeSites)
}

iteration_origin.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// A class method is statically called; own literal methods and arrow fields are closures with
// different argument layouts. A structural view must not hide a different layout.
func memberConvention(member *ast.Symbol) *ast.Node {
	if member == nil || len(member.Declarations) == 0 {
		return nil
	}
	declaration := member.Declarations[0]
	if declaration.Kind == ast.KindMethodDeclaration {
		if declaration.Parent.Kind == ast.KindClassDeclaration {
			return declaration.Parent
		}
		return objectMethodConvention
	}
	return arrowMethodConvention
}

var objectMethodConvention = &ast.Node{}
var arrowMethodConvention = &ast.Node{}

// Fresh literal assignability performs excess-property checking. Runtime values do not lose
// their extra fields when viewed structurally, so compare required members individually instead.
func (l *lowering) iterationShapeFits(shape, view *checker.Type) bool {
	for _, expected := range l.checker.GetPropertiesOfType(view) {
		actual := l.checker.GetPropertyOfType(shape, expected.Name)
		if actual == nil {
			if expected.Flags&ast.SymbolFlagsOptional != 0 {
				continue
			}
			return false
		}
		if actual.Flags&ast.SymbolFlagsOptional != 0 && expected.Flags&ast.SymbolFlagsOptional == 0 {
			return false
		}
		if !l.checker.IsTypeAssignableTo(l.checker.GetTypeOfSymbol(actual), l.checker.GetTypeOfSymbol(expected)) {
			return false
		}
	}
	return true
}

// A property typed as an ordinary callback can hide a literal method. Its closure needs a
// receiver argument. Do not read it using the callback convention until that origin is retained.
func (l *lowering) erasedLiteralMethod(node *ast.Node) error {
	access := node.AsPropertyAccessExpression()
	of, known := l.representation(l.checker.GetTypeAtLocation(node))
	if !known || of != ir.Closure {
		return nil
	}
	member := l.checker.GetSymbolAtLocation(node)
	if member != nil && literalMethod(member) {
		return nil
	}
	return l.erasedMethodField(node, l.checker.GetTypeAtLocation(access.Expression), access.Name().Text())
}

func (l *lowering) erasedMethodField(where *ast.Node, view *checker.Type, name string) error {
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return err
	}
	var found error
	var visit ast.Visitor
	visit = func(candidate *ast.Node) bool {
		if found != nil {
			return true
		}
		if candidate.Kind == ast.KindObjectLiteralExpression || candidate.Kind == ast.KindNewExpression {
			shape := l.checker.GetTypeAtLocation(candidate)
			field := l.checker.GetPropertyOfType(shape, name)
			if field != nil && l.iterationShapeFits(shape, view) {
				if literalMethod(field) {
					if isCallee(where) { // Calls carry the runtime closure's receiver convention.
						return candidate.ForEachChild(visit)
					}
					found = l.notYet(where, "a literal method through a view that erases its receiver")
					return true
				}
				for _, root := range l.checker.GetRootSymbols(field) {
					for _, declaration := range root.Declarations {
						if declaration.Kind == ast.KindMethodDeclaration && declaration.Parent.Kind == ast.KindClassDeclaration {
							// Method calls preserve the existing class prototype dispatch. Arrow-field
							// views and destructuring still erase the represented method origin.
							member := l.checker.GetPropertyOfType(l.checker.GetNonNullableType(view), name)
							if isCallee(where) && (isClassInstance(l.checker.GetNonNullableType(view)) || (member != nil && member.Flags&ast.SymbolFlagsMethod != 0)) {
								continue
							}
							found = l.notYet(where, "a class method through a view that erases its prototype origin")
							return true
						}
					}
				}
			}
		}
		return candidate.ForEachChild(visit)
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return found
}

// Known factories pin the actual method origins. Comparing every structurally compatible shape
// would otherwise refuse ordinary Range/Iterator class pairs with overlapping public fields.
func (l *lowering) iterationOrigin(node *ast.Node, members []*ast.Symbol, closePresence *bool, depth int) bool {
	if node == nil || depth > 16 {
		return false
	}
	node = ast.SkipParentheses(node)
	switch node.Kind {
	case ast.KindObjectLiteralExpression, ast.KindNewExpression, ast.KindThisKeyword:
		if node.Kind == ast.KindObjectLiteralExpression {
			for _, property := range node.AsObjectLiteralExpression().Properties.Nodes {
				if property.Kind == ast.KindSpreadAssignment {
					return false
				}
			}
		}
		if node.Kind == ast.KindNewExpression {
			class := l.classes[l.symbol(node.AsNewExpression().Expression)]
			if class == nil {
				return false
			}
			for _, member := range class.Members() {
				if member.Kind == ast.KindConstructor && hasConstructorReturn(member.Body()) {
					return false
				}
			}
		}
		shape := l.checker.GetTypeAtLocation(node)
		for _, expected := range members {
			actual := l.checker.GetPropertyOfType(shape, expected.Name)
			if actual == nil || !l.sameMemberOrigin(actual, expected) {
				return false
			}
		}
		if closePresence != nil && (l.checker.GetPropertyOfType(shape, "return") != nil) != *closePresence {
			return false
		}
		return true
	case ast.KindIdentifier:
		symbol := l.symbol(node)
		if symbol == nil || len(symbol.Declarations) != 1 {
			return false
		}
		declaration := symbol.Declarations[0]
		if declaration.Kind != ast.KindVariableDeclaration || declaration.Parent == nil || declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
			return false
		}
		return l.iterationOrigin(declaration.AsVariableDeclaration().Initializer, members, closePresence, depth+1)
	case ast.KindCallExpression:
		callee := ast.SkipParentheses(node.AsCallExpression().Expression)
		if !ast.IsIdentifier(callee) {
			return false
		}
		symbol := l.symbol(callee)
		if symbol == nil || len(symbol.Declarations) != 1 {
			return false
		}
		body := l.iterationCallableBody(symbol, depth+1)
		return l.iterationReturns(body, members, closePresence, depth+1)
	case ast.KindConditionalExpression:
		expression := node.AsConditionalExpression()
		return l.iterationOrigin(expression.WhenTrue, members, closePresence, depth+1) && l.iterationOrigin(expression.WhenFalse, members, closePresence, depth+1)
	}
	return false
}

func (l *lowering) sameMemberOrigin(actual, expected *ast.Symbol) bool {
	wanted := map[*ast.Node]bool{}
	for _, root := range l.checker.GetRootSymbols(expected) {
		for _, declaration := range root.Declarations {
			wanted[declaration] = true
		}
	}
	count := 0
	for _, root := range l.checker.GetRootSymbols(actual) {
		for _, declaration := range root.Declarations {
			if !wanted[declaration] {
				return false
			}
			count++
		}
	}
	return count > 0
}

func (l *lowering) iterationReturns(body *ast.Node, members []*ast.Symbol, closePresence *bool, depth int) bool {
	if body == nil {
		return false
	}
	if body.Kind != ast.KindBlock {
		return l.iterationOrigin(body, members, closePresence, depth+1)
	}
	found, sound := false, true
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if ast.IsFunctionLike(node) {
			return false
		}
		if node.Kind == ast.KindReturnStatement {
			found = true
			sound = sound && l.iterationOrigin(node.AsReturnStatement().Expression, members, closePresence, depth+1)
			return false
		}
		return node.ForEachChild(visit)
	}
	body.ForEachChild(visit)
	return found && sound
}

func (l *lowering) iterationFactoryKnown(member *ast.Symbol, next, close *ast.Symbol) bool {
	roots := l.checker.GetRootSymbols(member)
	if len(roots) != 1 || len(roots[0].Declarations) != 1 {
		return false
	}
	declaration := roots[0].Declarations[0]
	var body *ast.Node
	switch declaration.Kind {
	case ast.KindMethodDeclaration:
		body = declaration.Body()
	case ast.KindPropertyAssignment:
		initializer := ast.SkipParentheses(declaration.AsPropertyAssignment().Initializer)
		if initializer.Kind == ast.KindArrowFunction {
			body = initializer.Body()
		}
	}
	members := []*ast.Symbol{next}
	if close != nil {
		members = append(members, close)
	}
	presence := close != nil
	return l.iterationReturns(body, members, &presence, 0)
}

func hasConstructorReturn(body *ast.Node) bool {
	if body == nil {
		return false
	}
	found := false
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if ast.IsFunctionLike(node) {
			return false
		}
		if node.Kind == ast.KindReturnStatement {
			found = true
			return true
		}
		return node.ForEachChild(visit)
	}
	body.ForEachChild(visit)
	return found
}

func (l *lowering) iterationCallableBody(symbol *ast.Symbol, depth int) *ast.Node {
	if symbol == nil || len(symbol.Declarations) != 1 || depth > 16 {
		return nil
	}
	declaration := symbol.Declarations[0]
	if declaration.Kind == ast.KindFunctionDeclaration {
		return declaration.Body()
	}
	if declaration.Kind != ast.KindVariableDeclaration || declaration.Parent == nil || declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
		return nil
	}
	initializer := declaration.AsVariableDeclaration().Initializer
	if initializer == nil {
		return nil
	}
	initializer = ast.SkipParentheses(initializer)
	if initializer.Kind == ast.KindArrowFunction {
		return initializer.Body()
	}
	if ast.IsIdentifier(initializer) {
		return l.iterationCallableBody(l.symbol(initializer), depth+1)
	}
	return nil
}

// Generic classes are monomorphized. A readonly structural view can change their arguments
// without changing method declarations, so declaration identity alone is not a sufficient proof.
func (l *lowering) sameIterationClass(actual, expected *checker.Type) bool {
	actual, expected = l.concrete(actual), l.concrete(expected)
	if !isClassInstance(actual) || !isClassInstance(expected) || actual.Symbol() != expected.Symbol() {
		return false
	}
	left, right := l.checker.GetTypeArguments(actual), l.checker.GetTypeArguments(expected)
	if len(left) != len(right) {
		return false
	}
	for index, arg := range left {
		other := right[index]
		if !l.checker.IsTypeAssignableTo(arg, other) || !l.checker.IsTypeAssignableTo(other, arg) {
			return false
		}
		if (isClassInstance(arg) || isClassInstance(other)) && arg.Symbol() != other.Symbol() {
			return false
		}
	}
	return true
}

func (l *lowering) knownIterationClass(node *ast.Node, expected *checker.Type, depth int) bool {
	if node == nil || depth > 16 {
		return false
	}
	node = ast.SkipParentheses(node)
	switch node.Kind {
	case ast.KindNewExpression:
		return l.sameIterationClass(l.checker.GetTypeAtLocation(node), expected)
	case ast.KindIdentifier:
		symbol := l.symbol(node)
		if symbol == nil || len(symbol.Declarations) != 1 {
			return false
		}
		declaration := symbol.Declarations[0]
		if declaration.Kind != ast.KindVariableDeclaration || declaration.Parent == nil || declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
			return false
		}
		return l.knownIterationClass(declaration.AsVariableDeclaration().Initializer, expected, depth+1)
	case ast.KindCallExpression:
		callee := ast.SkipParentheses(node.AsCallExpression().Expression)
		if !ast.IsIdentifier(callee) {
			return false
		}
		return l.iterationReturnsClass(l.iterationCallableBody(l.symbol(callee), depth+1), expected, nil, depth+1)
	case ast.KindConditionalExpression:
		expression := node.AsConditionalExpression()
		return l.knownIterationClass(expression.WhenTrue, expected, depth+1) && l.knownIterationClass(expression.WhenFalse, expected, depth+1)
	}
	return false
}

func (l *lowering) iterationReturnsClass(body *ast.Node, expected, receiver *checker.Type, depth int) bool {
	if body == nil {
		return false
	}
	matches := func(node *ast.Node) bool {
		if node != nil && ast.SkipParentheses(node).Kind == ast.KindThisKeyword {
			return receiver != nil && l.sameIterationClass(receiver, expected)
		}
		return l.knownIterationClass(node, expected, depth+1)
	}
	if body.Kind != ast.KindBlock {
		return matches(body)
	}
	found, sound := false, true
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if ast.IsFunctionLike(node) {
			return false
		}
		if node.Kind == ast.KindReturnStatement {
			found = true
			sound = sound && matches(node.AsReturnStatement().Expression)
			return false
		}
		return node.ForEachChild(visit)
	}
	body.ForEachChild(visit)
	return found && sound
}

func (l *lowering) genericIteratorFactoryKnown(member *ast.Symbol, source, iterator *checker.Type) bool {
	roots := l.checker.GetRootSymbols(member)
	if len(roots) != 1 || len(roots[0].Declarations) != 1 {
		return false
	}
	declaration := roots[0].Declarations[0]
	var body *ast.Node
	if declaration.Kind == ast.KindMethodDeclaration {
		body = declaration.Body()
	}
	return l.iterationReturnsClass(body, iterator, source, 0)
}

// A returned receiver keeps its dynamic subclass, even when the result annotation names
// the base. Follow local aliases too; they do not make this an exact base instance.
func (l *lowering) iterationFactoryReturnsThis(member *ast.Symbol) bool {
	var receiver func(*ast.Node, int) bool
	receiver = func(node *ast.Node, depth int) bool {
		if node == nil || depth > 16 {
			return false
		}
		node = ast.SkipParentheses(node)
		if node.Kind == ast.KindThisKeyword {
			return true
		}
		if ast.IsIdentifier(node) {
			symbol := l.symbol(node)
			if symbol != nil && len(symbol.Declarations) == 1 && symbol.Declarations[0].Kind == ast.KindVariableDeclaration {
				return receiver(symbol.Declarations[0].AsVariableDeclaration().Initializer, depth+1)
			}
		}
		return false
	}
	for _, root := range l.checker.GetRootSymbols(member) {
		for _, declaration := range root.Declarations {
			if declaration.Kind != ast.KindMethodDeclaration || declaration.Body() == nil {
				continue
			}
			found := false
			var visit ast.Visitor
			visit = func(node *ast.Node) bool {
				if ast.IsFunctionLike(node) {
					return false
				}
				if node.Kind == ast.KindReturnStatement && receiver(node.AsReturnStatement().Expression, 0) {
					found = true
					return true
				}
				return node.ForEachChild(visit)
			}
			declaration.Body().ForEachChild(visit)
			if found {
				return true
			}
		}
	}
	return false
}

// Unknown receiver origins matter only when a declared descendant can change the
// protocol. A factory returning a base receiver remains sound in a closed class tree.
func (l *lowering) iteratorReceiverOverrides(modules []*ast.SourceFile, iterator *checker.Type, next, close *ast.Symbol) bool {
	class := l.classNodeFor(iterator)
	if class == nil {
		return false
	}
	changed := false
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if node.Kind == ast.KindClassDeclaration && node.Name() != nil && node != class {
			shape := l.checker.GetTypeAtLocation(node.Name())
			if l.classView(shape, class) != nil {
				actualNext := l.checker.GetPropertyOfType(shape, "next")
				actualClose := l.checker.GetPropertyOfType(shape, "return")
				if actualNext == nil || !l.sameMemberOrigin(actualNext, next) || (actualClose != nil) != (close != nil) || (close != nil && !l.sameMemberOrigin(actualClose, close)) {
					changed = true
					return true
				}
			}
		}
		return node.ForEachChild(visit)
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return changed
}

