package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

func (l *lowering) labeled(node *ast.Node) ([]ir.Statement, error) {
	statement := node.AsLabeledStatement()
	body, err := l.statement(statement.Statement)
	if err != nil {
		return nil, err
	}
	name := statement.Label.Text()
	target := statement.Statement
	for target.Kind == ast.KindLabeledStatement {
		target = target.AsLabeledStatement().Statement
	}
	switch target.Kind {
	case ast.KindForStatement, ast.KindWhileStatement, ast.KindDoStatement, ast.KindForOfStatement, ast.KindForInStatement:
		labelIteration(body, name)
	}
	return []ir.Statement{ir.Labeled{Name: name, Body: body}}, nil
}

// A for's initializer is a block before its loop; consecutive labels share the same iteration.
func labelIteration(body []ir.Statement, name string) bool {
	for index := range body {
		switch statement := body[index].(type) {
		case ir.Loop:
			statement.Labels = append(statement.Labels, name)
			body[index] = statement
			return true
		case ir.ForOf:
			statement.Labels = append(statement.Labels, name)
			body[index] = statement
			return true
		case ir.Block:
			if labelIteration(statement.Body, name) {
				return true
			}
		case ir.Labeled:
			if labelIteration(statement.Body, name) {
				return true
			}
		}
	}
	return false
}

library_array.go:
package lower

import (
	"strconv"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

var libraryArrayMethods = map[string]bool{
	"join": true, "indexOf": true, "includes": true, "lastIndexOf": true,
	"with": true, "flatMap": true, "copyWithin": true, "toSpliced": true, "flat": true,
	"findLast": true, "findLastIndex": true, "toReversed": true, "toSorted": true,
}

// libraryArrayMethod keeps this slice's additions out of the shared method dispatch.
func (l *lowering) libraryArrayMethod(node, receiver *ast.Node, name string) (ir.Expression, bool, error) {
	return l.libraryArrayMethodArguments(node, receiver, name, node.AsCallExpression().Arguments.Nodes)
}

func (l *lowering) libraryArrayMethodArguments(node, receiver *ast.Node, name string, written []*ast.Node) (ir.Expression, bool, error) {
	element, err := l.elementType(receiver)
	if err != nil {
		return nil, true, err
	}
	if name == "join" && element != ir.Array {
		return l.arrayMethod(node, receiver, name)
	}
	array, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	switch name {
	case "join":
		return l.libraryArrayJoin(node, receiver, array)
	case "with":
		return l.libraryArrayWith(node, array, element)
	case "flatMap":
		return l.libraryArrayFlatMap(node, array, element)
	case "toSpliced":
		return l.libraryArraySpliced(node, array, element)
	case "flat":
		return l.libraryArrayFlat(node, receiver, array)
	case "copyWithin":
		return l.libraryArrayCopyWithin(node, array, element)
	case "findLast", "findLastIndex":
		if len(written) != 1 {
			return nil, true, l.notYet(node, name+" without one callback")
		}
		signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(written[0]), checker.SignatureKindCall)
		if len(signatures) == 1 && len(signatures[0].Parameters()) > 3 {
			return nil, true, l.notYet(node, name+" with more than three callback parameters")
		}
		return l.arrayVisit(node, array, element, name)
	case "toReversed":
		if len(written) != 0 {
			return nil, true, l.notYet(node, "toReversed with arguments")
		}
		// Stage 0 arrays are dense. Copying first preserves identity and reference ownership.
		return ir.ArrayReverse{Array: ir.ArraySlice{Array: array}}, true, nil
	case "toSorted":
		if l.includesUndefined(l.checker.GetElementTypeOfArrayType(l.checker.GetTypeAtLocation(receiver))) {
			return nil, true, l.notYet(node, "toSorted on optional elements")
		}
		copy := ir.ArraySlice{Array: array}
		if len(written) == 0 {
			if element != ir.Number && element != ir.Boolean && element != ir.String {
				return nil, true, l.notYet(node, "toSorted without a comparator on these elements")
			}
			if l.includesUndefined(l.checker.GetElementTypeOfArrayType(l.checker.GetTypeAtLocation(receiver))) {
				return nil, true, l.notYet(node, "toSorted without a comparator on optional elements")
			}
			return ir.ArraySort{Array: copy, Element: element, Comparator: l.libraryArrayComparator(element)}, true, nil
		}
		// Reading a function name or making an arrow cannot change the source before the copy.
		// A call producing a comparator could; leave that case refused until operands can be bound.
		callback := ast.SkipParentheses(written[0])
		if len(written) != 1 || (!ast.IsIdentifier(callback) && callback.Kind != ast.KindArrowFunction) {
			return nil, true, l.notYet(node, "toSorted with an effectful comparator expression")
		}
		return l.arraySort(node, copy, element)
	}
	if len(written) < 1 || len(written) > 2 {
		return nil, true, l.notYet(node, name+" with these arguments")
	}
	value, err := l.expression(written[0])
	if err != nil {
		return nil, true, err
	}
	value = fit(value, element)
	if value.Type() != element {
		return nil, true, l.notYet(node, name+" with a value of another type than the elements")
	}
	search := ir.ArraySearch{Array: array, Value: value, Element: element, Includes: name == "includes", Last: name == "lastIndexOf"}
	if len(written) == 2 {
		from, err := l.expression(written[1])
		if err != nil {
			return nil, true, err
		}
		// undefined means 0 when explicitly supplied, including for lastIndexOf.
		if _, absent := from.(ir.Undefined); absent {
			from = ir.NumberConstant{Value: 0}
		}
		if from.Type() != ir.Number {
			return nil, true, l.notYet(node, name+" with a starting index that isn't a number")
		}
		search.From = from
	}
	return search, true, nil
}

// A default comparator is ordinary IR, so both backends and every ownership pass see its work.
// ECMAScript orders by UTF-16 strings even for numbers.
func (l *lowering) libraryArrayComparator(element ir.Type) int {
	function := len(l.result.Functions)
	parameters := []int{len(l.result.Locals), len(l.result.Locals) + 1}
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "left", Type: element, Function: function}, ir.Local{Name: "right", Type: element, Function: function})
	text := func(local int) ir.Expression {
		read := ir.Read{Local: local, Of: element}
		if element == ir.Number {
			return ir.NumberToString{Value: read}
		}
		if element == ir.Boolean {
			return ir.BooleanToString{Value: read}
		}
		return read
	}
	left, right := text(parameters[0]), text(parameters[1])
	result := ir.Conditional{Condition: ir.Binary{Operator: ir.Less, Left: left, Right: right}, WhenTrue: ir.NumberConstant{Value: -1}, WhenNot: ir.Conditional{Condition: ir.Binary{Operator: ir.Greater, Left: left, Right: right}, WhenTrue: ir.NumberConstant{Value: 1}, WhenNot: ir.NumberConstant{Value: 0}}}
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "array_default_compare", Parameters: parameters, Returns: ir.Number, Body: []ir.Statement{ir.Return{Value: result}}})
	return function
}

// Helpers are ordinary functions in the IR. Their operands are evaluated before any copying,
// including an operand that changes the receiver, as JavaScript requires.
type libraryArrayBuilder struct {
	l          *lowering
	function   int
	parameters []int
	arguments  []ir.Expression
	body       []ir.Statement
}

func (l *lowering) libraryArrayBuilder(arguments []ir.Expression) *libraryArrayBuilder {
	b := &libraryArrayBuilder{l: l, function: len(l.result.Functions), arguments: arguments}
	for _, argument := range arguments {
		b.parameters = append(b.parameters, b.local("argument", argument.Type()))
	}
	return b
}
func (b *libraryArrayBuilder) local(name string, of ir.Type) int {
	local := len(b.l.result.Locals)
	b.l.result.Locals = append(b.l.result.Locals, ir.Local{Name: name, Type: of, Function: b.function})
	return local
}
func (b *libraryArrayBuilder) read(local int) ir.Expression {
	return ir.Read{Local: local, Of: b.l.result.Locals[local].Type}
}
func (b *libraryArrayBuilder) declare(name string, value ir.Expression) int {
	local := b.local(name, value.Type())
	b.body = append(b.body, ir.Declare{Local: local, Value: value})
	return local
}
func (b *libraryArrayBuilder) finish(name string, result ir.Expression) ir.Expression {
	b.body = append(b.body, ir.Return{Value: result})
	b.l.result.Functions = append(b.l.result.Functions, ir.Function{Name: name, Parameters: b.parameters, Returns: result.Type(), Body: b.body})
	return ir.Call{Function: b.function, Arguments: b.arguments, Returns: result.Type()}
}

func (l *lowering) libraryArraySpliced(node *ast.Node, array ir.Expression, element ir.Type) (ir.Expression, bool, error) {
	arguments := []ir.Expression{array}
	for index, written := range node.AsCallExpression().Arguments.Nodes {
		value, err := l.expression(written)
		if err != nil {
			return nil, true, err
		}
		if index < 2 {
			if _, undefined := value.(ir.Undefined); undefined {
				value = ir.NumberConstant{Value: 0}
			}
			if value.Type() != ir.Number {
				return nil, true, l.notYet(node, "toSpliced with nonnumeric bounds")
			}
		} else {
			value = fit(value, element)
			if value.Type() != element {
				return nil, true, l.notYet(node, "toSpliced with different element types")
			}
		}
		arguments = append(arguments, value)
	}
	b := l.libraryArrayBuilder(arguments)
	copy := b.declare("copy", ir.ArraySlice{Array: b.read(b.parameters[0])})
	if len(arguments) > 1 {
		splice := ir.ArraySplice{Array: b.read(copy), Start: b.read(b.parameters[1]), Element: element, Site: l.writeSite(node)}
		if len(arguments) > 2 {
			splice.Count = b.read(b.parameters[2])
			for _, parameter := range b.parameters[3:] {
				splice.Items = append(splice.Items, b.read(parameter))
			}
		}
		b.body = append(b.body, ir.Evaluate{Value: splice})
	}
	return b.finish("array_to_spliced", b.read(copy)), true, nil
}

func (l *lowering) libraryArrayFlat(node, receiver *ast.Node, array ir.Expression) (ir.Expression, bool, error) {
	depth := 1
	written := node.AsCallExpression().Arguments.Nodes
	if len(written) > 1 {
		return nil, true, l.notYet(node, "flat with multiple depths")
	}
	if len(written) == 1 {
		literal := ast.SkipParentheses(written[0])
		if literal.Kind != ast.KindNumericLiteral {
			return nil, true, l.notYet(node, "flat with a nonconstant depth")
		}
		number, err := strconv.ParseFloat(literal.Text(), 64)
		if err != nil || number > 32 {
			return nil, true, l.notYet(node, "flat with this depth")
		}
		depth = int(number)
	}
	// Only homogeneous layers of arrays: a mixed scalar/array union needs a runtime array tag.
	layer := l.checker.GetTypeAtLocation(receiver)
	types := []ir.Type{}
	for step := 0; step <= depth; step++ {
		item := l.checker.GetElementTypeOfArrayType(layer)
		of, known := l.kept(item)
		if !known || slotless(of) {
			return nil, true, l.notYet(node, "flat on heterogeneous layers")
		}
		types = append(types, of)
		if of == ir.Array && step < depth && l.includesUndefined(item) {
			return nil, true, l.notYet(node, "flat on optional nested arrays")
		}
		if of != ir.Array || step == depth {
			break
		}
		layer = item
	}
	resultElement, err := l.elementType(node)
	if err != nil {
		return nil, true, err
	}
	if resultElement != types[len(types)-1] {
		return nil, true, l.notYet(node, "flat whose result element type differs from its depth")
	}
	b := l.libraryArrayBuilder([]ir.Expression{array})
	result := b.declare("flattened", ir.ArrayLiteral{Element: resultElement})
	var loop func(ir.Expression, int) ir.Statement
	loop = func(source ir.Expression, level int) ir.Statement {
		local := b.local("element", types[level])
		body := []ir.Statement{ir.Evaluate{Value: ir.ArrayPush{Array: b.read(result), Value: b.read(local), Element: resultElement, Site: l.writeSite(node)}}}
		if level+1 < len(types) {
			body = []ir.Statement{loop(b.read(local), level+1)}
		}
		return ir.ForOf{Iterable: source, Local: local, Element: types[level], Body: body}
	}
	b.body = append(b.body, loop(b.read(b.parameters[0]), 0))
	return b.finish("array_flat", b.read(result)), true, nil
}

func (l *lowering) libraryArrayCopyWithin(node *ast.Node, array ir.Expression, element ir.Type) (ir.Expression, bool, error) {
	written := node.AsCallExpression().Arguments.Nodes
	if len(written) < 1 || len(written) > 3 {
		return nil, true, l.notYet(node, "copyWithin with these arguments")
	}
	arguments := []ir.Expression{array}
	for _, item := range written {
		value, err := l.expression(item)
		if err != nil {
			return nil, true, err
		}
		if value.Type() != ir.Number {
			return nil, true, l.notYet(node, "copyWithin with a nonnumeric bound")
		}
		arguments = append(arguments, value)
	}
	b := l.libraryArrayBuilder(arguments)
	source := b.read(b.parameters[0])
	length := b.declare("length", ir.Length{Array: source})
	zero := ir.NumberConstant{Value: 0}
	add := func(left, right ir.Expression) ir.Expression {
		return ir.Binary{Operator: ir.Add, Left: left, Right: right}
	}
	relative := func(value ir.Expression) ir.Expression {
		integer := ir.Conditional{Condition: ir.NumberCall{Function: "isNaN", Arguments: []ir.Expression{value}}, WhenTrue: zero, WhenNot: ir.MathCall{Function: "trunc", Arguments: []ir.Expression{value}}}
		local := b.declare("integer", integer)
		read := b.read(local)
		return ir.Conditional{Condition: ir.Binary{Operator: ir.Less, Left: read, Right: zero}, WhenTrue: ir.MathCall{Function: "max", Arguments: []ir.Expression{add(b.read(length), read), zero}}, WhenNot: ir.MathCall{Function: "min", Arguments: []ir.Expression{read, b.read(length)}}}
	}
	target := b.declare("target", relative(b.read(b.parameters[1])))
	startValue, endValue := ir.Expression(zero), b.read(length)
	if len(arguments) > 2 {
		startValue = b.read(b.parameters[2])
	}
	if len(arguments) > 3 {
		endValue = b.read(b.parameters[3])
	}
	start := b.declare("start", relative(startValue))
	end := b.declare("end", relative(endValue))
	// Snapshot the source range so overlapping writes have memmove semantics, with references held.
	copy := b.declare("range", ir.ArraySlice{Array: source, Arguments: []ir.Expression{b.read(start), b.read(end)}})
	count := b.declare("count", ir.MathCall{Function: "min", Arguments: []ir.Expression{ir.Length{Array: b.read(copy)}, ir.Binary{Operator: ir.Subtract, Left: b.read(length), Right: b.read(target)}}})
	index := b.declare("index", zero)
	value := ir.Expression(ir.ArrayIndex{Array: b.read(copy), Index: b.read(index), Element: element})
	if value.Type().IsMaybe() && value.Type() != element {
		value = ir.Unwrap{Value: value}
	}
	b.body = append(b.body, ir.Loop{Condition: ir.Binary{Operator: ir.Less, Left: b.read(index), Right: b.read(count)}, Body: []ir.Statement{ir.SetIndex{Array: source, Index: add(b.read(target), b.read(index)), Value: value, Element: element, Site: l.writeSite(node)}}, Update: []ir.Statement{ir.Assign{Local: index, Value: add(b.read(index), ir.NumberConstant{Value: 1})}}})
	return b.finish("array_copy_within", source), true, nil
}

func (l *lowering) libraryArrayWith(node *ast.Node, array ir.Expression, element ir.Type) (ir.Expression, bool, error) {
	written := node.AsCallExpression().Arguments.Nodes
	if len(written) != 2 {
		return nil, true, l.notYet(node, "with without an index and value")
	}
	index, err := l.expression(written[0])
	if err != nil {
		return nil, true, err
	}
	value, err := l.expression(written[1])
	if err != nil {
		return nil, true, err
	}
	value = fit(value, element)
	if index.Type() != ir.Number || value.Type() != element {
		return nil, true, l.notYet(node, "with with incompatible arguments")
	}
	b := l.libraryArrayBuilder([]ir.Expression{array, index, value})
	source, raw := b.read(b.parameters[0]), b.read(b.parameters[1])
	zero := ir.NumberConstant{Value: 0}
	integer := b.declare("integer", ir.Conditional{Condition: ir.NumberCall{Function: "isNaN", Arguments: []ir.Expression{raw}}, WhenTrue: zero, WhenNot: ir.MathCall{Function: "trunc", Arguments: []ir.Expression{raw}}})
	actual := b.declare("actual", ir.Conditional{Condition: ir.Binary{Operator: ir.Less, Left: b.read(integer), Right: zero}, WhenTrue: ir.Binary{Operator: ir.Add, Left: ir.Length{Array: source}, Right: b.read(integer)}, WhenNot: b.read(integer)})
	outside := ir.Binary{Operator: ir.Or, Left: ir.Binary{Operator: ir.Less, Left: b.read(actual), Right: zero}, Right: ir.Binary{Operator: ir.GreaterOrEqual, Left: b.read(actual), Right: ir.Length{Array: source}}}
	errorLocal := b.local("range_error", ir.Object)
	message := ir.Concat{Parts: []ir.Expression{ir.StringConstant{Index: l.constant("Invalid index : ")}, ir.NumberToString{Value: raw}}}
	b.body = append(b.body, ir.If{Condition: outside, Then: []ir.Statement{
		ir.Declare{Local: errorLocal, Value: ir.MakeError{Message: message}},
		ir.SetProperty{Object: b.read(errorLocal), Name: "name", Value: ir.StringConstant{Index: l.constant("RangeError")}, Site: l.libraryArraySyntheticWriteSite(node)},
		ir.Throw{Value: b.read(errorLocal)},
	}})
	copy := b.declare("copy", ir.ArraySlice{Array: source})
	b.body = append(b.body, ir.SetIndex{Array: b.read(copy), Index: b.read(actual), Value: b.read(b.parameters[2]), Element: element, Site: l.writeSite(node)})
	return b.finish("array_with", b.read(copy)), true, nil
}

func (l *lowering) libraryArrayFlatMap(node *ast.Node, array ir.Expression, element ir.Type) (ir.Expression, bool, error) {
	written := node.AsCallExpression().Arguments.Nodes
	if len(written) != 1 {
		return nil, true, l.notYet(node, "flatMap with other than one callback")
	}
	callback, err := l.expression(written[0])
	if err != nil {
		return nil, true, err
	}
	signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(written[0]), checker.SignatureKindCall)
	if callback.Type() != ir.Closure || len(signatures) != 1 || len(signatures[0].Parameters()) > 3 {
		return nil, true, l.notYet(node, "flatMap with this callback")
	}
	returned := l.checker.GetReturnTypeOfSignature(signatures[0])
	resultType, known := l.representation(returned)
	output, err := l.elementType(node)
	if err != nil {
		return nil, true, err
	}
	if !known || (resultType != ir.Array && resultType != output) {
		return nil, true, l.notYet(node, "flatMap with a mixed scalar and array callback result")
	}
	if resultType == ir.Array {
		if l.includesUndefined(returned) {
			return nil, true, l.notYet(node, "flatMap with optional array results")
		}
		inner, known := l.kept(l.checker.GetElementTypeOfArrayType(returned))
		if !known || inner != output {
			return nil, true, l.notYet(node, "flatMap with this callback element type")
		}
	}
	b := l.libraryArrayBuilder([]ir.Expression{array, callback})
	source := b.read(b.parameters[0])
	result := b.declare("mapped", ir.ArrayLiteral{Element: output})
	count := b.declare("count", ir.Length{Array: source})
	index := b.declare("index", ir.NumberConstant{Value: 0})
	input := ir.Expression(ir.ArrayIndex{Array: source, Index: b.read(index), Element: element})
	if input.Type().IsMaybe() && input.Type() != element {
		input = ir.Unwrap{Value: input}
	}
	mapped := b.local("callback_result", resultType)
	callArguments := []ir.Expression{input, b.read(index), source}
	for index, parameter := range signatures[0].Parameters() {
		takes, known := l.representation(l.checker.GetTypeOfSymbol(parameter))
		if !known || slotless(takes) {
			return nil, true, l.notYet(node, "flatMap with this callback parameter type")
		}
		callArguments[index] = fit(callArguments[index], takes)
	}
	call := ir.CallClosure{Closure: b.read(b.parameters[1]), Arguments: callArguments, Returns: resultType}
	body := []ir.Statement{ir.Declare{Local: mapped, Value: call}}
	if resultType == ir.Array {
		item := b.local("element", output)
		body = append(body, ir.ForOf{Iterable: b.read(mapped), Element: output, Local: item, Body: []ir.Statement{ir.Evaluate{Value: ir.ArrayPush{Array: b.read(result), Value: b.read(item), Element: output, Site: l.writeSite(node)}}}})
	} else {
		body = append(body, ir.Evaluate{Value: ir.ArrayPush{Array: b.read(result), Value: b.read(mapped), Element: output, Site: l.writeSite(node)}})
	}
	// An index the callback removed is skipped, as flatMap's HasProperty requires.
	b.body = append(b.body, ir.Loop{Condition: ir.Binary{Operator: ir.Less, Left: b.read(index), Right: b.read(count)}, Body: []ir.Statement{ir.If{Condition: ir.Binary{Operator: ir.Less, Left: b.read(index), Right: ir.Length{Array: source}}, Then: body}}, Update: []ir.Statement{ir.Assign{Local: index, Value: ir.Binary{Operator: ir.Add, Left: b.read(index), Right: ir.NumberConstant{Value: 1}}}}})
	return b.finish("array_flat_map", b.read(result)), true, nil
}

var libraryArrayLengths = map[string]float64{
	"at": 1, "concat": 1, "copyWithin": 2, "entries": 0, "every": 1, "fill": 1,
	"filter": 1, "find": 1, "findIndex": 1, "findLast": 1, "findLastIndex": 1,
	"flat": 0, "flatMap": 1, "forEach": 1, "includes": 1, "indexOf": 1, "join": 1,
	"keys": 0, "lastIndexOf": 1, "map": 1, "pop": 0, "push": 1, "reduce": 1,
	"reduceRight": 1, "reverse": 0, "shift": 0, "slice": 2, "some": 1, "sort": 1,
	"splice": 2, "toLocaleString": 0, "toReversed": 0, "toSorted": 1, "toSpliced": 2,
	"toString": 0, "unshift": 1, "values": 0, "with": 2,
}

// Observing the standard function's metadata never calls it with a lost receiver. Recognition
// includes the library global's identity; an object's method or a shadowed Array is never folded.
func (l *lowering) libraryArrayMethodName(node *ast.Node) string {
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindPropertyAccessExpression {
		return ""
	}
	access := node.AsPropertyAccessExpression()
	if access.QuestionDotToken != nil {
		return ""
	}
	prototype := ast.SkipParentheses(access.Expression)
	if prototype.Kind != ast.KindPropertyAccessExpression || prototype.Name().Text() != "prototype" || prototype.AsPropertyAccessExpression().QuestionDotToken != nil || !l.isLibraryGlobal(prototype.AsPropertyAccessExpression().Expression, "Array") {
		return ""
	}
	name := access.Name().Text()
	if _, known := libraryArrayLengths[name]; !known {
		return ""
	}
	return name
}

func (l *lowering) libraryArrayObservation(node *ast.Node) (ir.Expression, bool) {
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindTypeOfExpression {
		if name := l.libraryArrayMethodName(node.AsTypeOfExpression().Expression); name != "" {
			return ir.StringConstant{Index: l.constant("function")}, true
		}
	}
	if node.Kind == ast.KindPropertyAccessExpression && node.AsPropertyAccessExpression().QuestionDotToken == nil {
		if name := l.libraryArrayMethodName(node.AsPropertyAccessExpression().Expression); name != "" {
			switch node.Name().Text() {
			case "length":
				return ir.NumberConstant{Value: libraryArrayLengths[name]}, true
			case "name":
				return ir.StringConstant{Index: l.constant(name)}, true
			}
		}
	}
	return nil, false
}

func (l *lowering) libraryArrayObservedMethod(node *ast.Node) bool {
	if l.libraryArrayMethodName(node) == "" {
		return false
	}
	for node.Parent != nil && node.Parent.Kind == ast.KindParenthesizedExpression {
		node = node.Parent
	}
	parent := node.Parent
	if parent == nil {
		return false
	}
	if parent.Kind == ast.KindTypeOfExpression {
		return true
	}
	return parent.Kind == ast.KindPropertyAccessExpression && parent.AsPropertyAccessExpression().Expression == node && parent.AsPropertyAccessExpression().QuestionDotToken == nil && (parent.Name().Text() == "length" || parent.Name().Text() == "name")
}

// Direct for...of over a standard array iterator keeps the source alive and reads its length
// each time. Materializing its elements up front would lose writes and pushes in the body.
func (l *lowering) libraryArrayForOf(node *ast.Node) ([]ir.Statement, bool, error) {
	statement := node.AsForInOrOfStatement()
	call := ast.SkipParentheses(statement.Expression)
	if call.Kind != ast.KindCallExpression || len(call.AsCallExpression().Arguments.Nodes) != 0 {
		return nil, false, nil
	}
	callee := ast.SkipParentheses(call.AsCallExpression().Expression)
	if callee.Kind != ast.KindPropertyAccessExpression {
		return nil, false, nil
	}
	access := callee.AsPropertyAccessExpression()
	name := access.Name().Text()
	if name != "entries" && name != "keys" && name != "values" {
		return nil, false, nil
	}
	if receiver, known := l.representation(l.checker.GetTypeAtLocation(access.Expression)); !known || receiver != ir.Array {
		return nil, false, nil
	}
	if err := l.optionalCall(call); err != nil {
		return nil, true, err
	}
	if statement.AwaitModifier != nil {
		return nil, true, l.notYet(node, "for await")
	}
	initializer := statement.Initializer
	if initializer.Kind != ast.KindVariableDeclarationList || initializer.Flags&ast.NodeFlagsBlockScoped == 0 {
		return nil, true, l.notYet(node, "an array iterator loop without const or let")
	}
	declarations := initializer.AsVariableDeclarationList().Declarations.Nodes
	if len(declarations) != 1 {
		return nil, true, l.notYet(node, "an array iterator loop with multiple declarations")
	}
	binding := declarations[0].Name()
	array, err := l.expression(access.Expression)
	if err != nil {
		return nil, true, err
	}
	element, err := l.elementType(access.Expression)
	if err != nil {
		return nil, true, err
	}
	local := func(name string, of ir.Type) int {
		index := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: name, Type: of, Function: l.functionIndex})
		return index
	}
	source, index := local("array_iterator_source", ir.Array), local("array_iterator_index", ir.Number)
	read := func(local int) ir.Expression { return ir.Read{Local: local, Of: l.result.Locals[local].Type} }
	value := ir.Expression(ir.ArrayIndex{Array: read(source), Index: read(index), Element: element})
	if value.Type().IsMaybe() && value.Type() != element {
		value = ir.Unwrap{Value: value}
	}
	body := []ir.Statement{}
	if ast.IsIdentifier(binding) {
		bound, err := l.declareLocal(binding)
		if err != nil {
			return nil, true, err
		}
		given := value
		if name == "keys" {
			given = read(index)
		}
		if name == "entries" {
			given = ir.ObjectLiteral{Tuple: true, Fields: []ir.Field{{Name: "0", Value: read(index)}, {Name: "1", Value: value}}}
		}
		body = append(body, ir.Declare{Local: bound, Value: given})
	} else if name == "entries" && binding.Kind == ast.KindArrayBindingPattern {
		entries := binding.AsBindingPattern().Elements.Nodes
		if len(entries) > 2 {
			return nil, true, l.notYet(node, "destructuring more than two array entry fields")
		}
		for position, bound := range entries {
			if skipped(bound) {
				continue
			}
			item := bound.AsBindingElement()
			if !ast.IsIdentifier(bound.Name()) || item.Initializer != nil || item.DotDotDotToken != nil {
				return nil, true, l.notYet(node, "an array entry binding with a default or rest")
			}
			variable, err := l.declareLocal(bound.Name())
			if err != nil {
				return nil, true, err
			}
			given := value
			if position == 0 {
				given = read(index)
			}
			body = append(body, ir.Declare{Local: variable, Value: given})
		}
	} else {
		return nil, true, l.notYet(node, "destructuring this array iterator")
	}
	inner, err := l.statement(statement.Statement)
	if err != nil {
		return nil, true, err
	}
	body = append(body, inner...)
	loop := ir.Loop{Condition: ir.Binary{Operator: ir.Less, Left: read(index), Right: ir.Length{Array: read(source)}}, Body: body, Update: []ir.Statement{ir.Assign{Local: index, Value: ir.Binary{Operator: ir.Add, Left: read(index), Right: ir.NumberConstant{Value: 1}}}}}
	return []ir.Statement{ir.Block{Body: []ir.Statement{ir.Declare{Local: source, Value: array}, ir.Declare{Local: index, Value: ir.NumberConstant{Value: 0}}, loop}}}, true, nil
}

// A generated Error has no source expression whose checker type names its holder. A nil holder
// keeps the cycle finder conservative if the write is not proven, rather than borrowing an array type.
func (l *lowering) libraryArraySyntheticWriteSite(node *ast.Node) int {
	l.writeSites = append(l.writeSites, writeSite{node: node})
	return len(l.writeSites)
}

// Nested homogeneous arrays stringify with a comma at every inner layer, regardless of the
// separator supplied for the outer join. Optional inner arrays stringify as an empty element.
func (l *lowering) libraryArrayJoin(node, receiver *ast.Node, array ir.Expression) (ir.Expression, bool, error) {
	layer := l.checker.GetTypeAtLocation(receiver)
	depth := 0
	var element ir.Type
	for {
		item := l.checker.GetElementTypeOfArrayType(l.checker.GetNonNullableType(layer))
		of, known := l.kept(item)
		if !known {
			return nil, true, l.notYet(node, "join on heterogeneous nested arrays")
		}
		if of != ir.Array {
			element = of
			break
		}
		depth++
		if depth > 32 {
			return nil, true, l.notYet(node, "join on recursively nested arrays")
		}
		layer = item
	}
	if element != ir.Number && element != ir.MaybeNumber && element != ir.Boolean && element != ir.String {
		return nil, true, l.notYet(node, "join on nested arrays of objects or functions")
	}
	written := node.AsCallExpression().Arguments.Nodes
	separator := ir.Expression(ir.StringConstant{Index: l.constant(",")})
	if len(written) > 1 {
		return nil, true, l.notYet(node, "join with more than one separator")
	}
	if len(written) == 1 {
		value, err := l.expression(written[0])
		if err != nil {
			return nil, true, err
		}
		separator = l.orDefault(written[0], value, ",")
		if separator.Type() != ir.String {
			return nil, true, l.notYet(node, "join with a nonstring separator")
		}
	}
	return ir.ArrayJoin{Array: array, Separator: separator, Element: element, Depth: depth}, true, nil
}

library_array_predicate.go:
package lower

import (
	_ "unsafe"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

func (l *lowering) isArrayPredicateCall(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindCallExpression {
		return false
	}
	call := node.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	return call.QuestionDotToken == nil && len(call.Arguments.Nodes) == 1 && callee.Kind == ast.KindPropertyAccessExpression && callee.AsPropertyAccessExpression().QuestionDotToken == nil && callee.Name().Text() == "isArray" && l.isLibraryGlobal(callee.AsPropertyAccessExpression().Expression, "Array") && l.libraryMember(callee)
}

func (l *lowering) arrayIsArray(node *ast.Node) (ir.Expression, bool, error) {
	if !l.isArrayPredicateCall(node) {
		return nil, false, nil
	}
	argument := node.AsCallExpression().Arguments.Nodes[0]
	if !l.arrayPredicateDomain(l.checker.GetTypeAtLocation(argument)) && !l.exactObject(argument, 0) {
		return nil, true, l.notYet(argument, "Array.isArray on a tuple or an erased object/any/unknown view")
	}
	value, err := l.expression(argument)
	if err != nil {
		return nil, true, err
	}
	return ir.ArrayIsArray{Value: fit(value, ir.Union)}, true, nil
}

// The library's any[] predicate describes the runtime test, not an element
// contract. Only array members already promised by the declared input survive.
func (l *lowering) arrayPredicateMembers(proven *checker.Type, array bool) *checker.Type {
	members := []*checker.Type{}
	var collect func(*checker.Type)
	collect = func(member *checker.Type) {
		member = l.concrete(member)
		if member.Flags()&checker.TypeFlagsUnion != 0 {
			for _, part := range member.Types() {
				collect(part)
			}
			return
		}
		if member.Flags()&checker.TypeFlagsUnknown != 0 {
			if array {
				members = append(members, predicateReadonlyArray(l.checker, member, true))
			} else {
				members = append(members, member)
			}
			return
		}
		if member.Flags()&(checker.TypeFlagsAny|checker.TypeFlagsTypeParameter) != 0 {
			return
		}
		if l.checker.IsArrayType(member) == array {
			members = append(members, member)
		}
	}
	collect(proven)
	return l.checker.GetUnionType(members)
}

// Tuples currently have an object representation. Erased object views can hide
// one too, so the native array brand cannot decide their JavaScript arrayness.
func (l *lowering) arrayPredicateDomain(proven *checker.Type) bool {
	proven = l.concrete(proven)
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range proven.Types() {
			if !l.arrayPredicateDomain(member) {
				return false
			}
		}
		return true
	}
	if proven.Flags()&checker.TypeFlagsUnknown != 0 {
		return true
	}
	if proven.Flags()&(checker.TypeFlagsAny|checker.TypeFlagsTypeParameter|checker.TypeFlagsIntersection) != 0 || checker.IsTupleType(proven) {
		return false
	}
	if l.checker.IsArrayType(proven) {
		return true
	}
	return proven.Flags()&checker.TypeFlagsObject == 0 || isClassInstance(proven) || l.isLibraryType(proven, "Uint8Array", "Int32Array", "Float64Array")
}

// TypeScript's built-in signature is value is any[]. Recover the declared
// array member at a direct, dominating positive test instead of adopting any.
func (l *lowering) arrayPredicateType(node *ast.Node) *checker.Type {
	node = ast.SkipParentheses(node)
	actual := l.checker.GetTypeAtLocation(node)
	if node.Kind != ast.KindIdentifier {
		return actual
	}
	symbol := l.symbol(node)
	if symbol == nil || node.FlowNodeData() == nil {
		return actual
	}
	declared := l.checker.GetTypeOfSymbol(symbol)
	if !l.arrayPredicateDomain(declared) && declared.Flags()&checker.TypeFlagsUnknown == 0 {
		return actual
	}
	flow := node.FlowNodeData().FlowNode
	for steps := 0; flow != nil && steps < 256; steps++ {
		if flow.Flags&(ast.FlowFlagsAssignment|ast.FlowFlagsLabel|ast.FlowFlagsCall) != 0 {
			return actual
		}
		if flow.Flags&ast.FlowFlagsCondition != 0 && flow.Node != nil && l.arrayPredicateFlowCall(flow.Node) {
			call := ast.SkipParentheses(flow.Node).AsCallExpression()
			if l.symbol(ast.SkipParentheses(call.Arguments.Nodes[0])) == symbol {
				return l.arrayPredicateMembers(declared, flow.Flags&ast.FlowFlagsTrueCondition != 0)
			}
		}
		flow = flow.Antecedent
	}
	return actual
}

// Indexed reads and their ?? result retain the recovered element contract,
// including the missing element required by noUncheckedIndexedAccess.
func (l *lowering) arrayPredicateObservedType(node *ast.Node) *checker.Type {
	node = ast.SkipParentheses(node)
	actual := l.checker.GetTypeAtLocation(node)
	if node.Kind == ast.KindIdentifier {
		return l.arrayPredicateType(node)
	}
	if actual.Flags()&checker.TypeFlagsAny == 0 {
		return actual
	}
	switch node.Kind {
	case ast.KindElementAccessExpression:
		array := l.arrayPredicateType(node.AsElementAccessExpression().Expression)
		if l.checker.IsArrayType(array) {
			element := l.checker.GetElementTypeOfArrayType(array)
			if element != nil && element.Flags()&checker.TypeFlagsAny == 0 {
				return l.checker.GetUnionType([]*checker.Type{element, l.checker.GetUndefinedType()})
			}
		}
	case ast.KindBinaryExpression:
		binary := node.AsBinaryExpression()
		if binary.OperatorToken.Kind == ast.KindQuestionQuestionToken {
			left := l.arrayPredicateObservedType(binary.Left)
			if left.Flags()&checker.TypeFlagsAny == 0 {
				return l.checker.GetUnionType([]*checker.Type{l.checker.GetNonNullableType(left), l.checker.GetTypeAtLocation(binary.Right)})
			}
		}
	}
	return actual
}

// The pinned checker owns construction of the readonly array type, just as it
// owns predicate flow facts. This introduces no any element contract.
//
//go:linkname predicateReadonlyArray github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).createArrayTypeEx
func predicateReadonlyArray(receiver *checker.Checker, element *checker.Type, readonly bool) *checker.Type

// A proven wrapper has the same arrayness test as the builtin. Its annotation
// cannot supply element facts missing from the caller's declared union.
func (l *lowering) arrayPredicateFlowCall(node *ast.Node) bool {
	if l.isArrayPredicateCall(node) {
		return true
	}
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindCallExpression {
		return false
	}
	call := node.AsCallExpression()
	if call.QuestionDotToken != nil || len(call.Arguments.Nodes) != 1 {
		return false
	}
	symbol := l.symbol(ast.SkipParentheses(call.Expression))
	if symbol == nil {
		return false
	}
	for _, declaration := range symbol.Declarations {
		if declaration.Kind != ast.KindFunctionDeclaration || len(declaration.Parameters()) != 1 || declaration.Body() == nil || declaration.Type() == nil || declaration.Type().Kind != ast.KindTypePredicate {
			continue
		}
		target := l.checker.GetTypeFromTypeNode(declaration.Type().AsTypePredicateNode().Type)
		if !checker.Checker_isTypeIdenticalTo(l.checker, target, predicateReadonlyArray(l.checker, l.checker.GetUnknownType(), true)) {
			continue
		}
		body := declaration.Body()
		if body.Kind != ast.KindBlock || len(body.AsBlock().Statements.Nodes) != 1 {
			continue
		}
		statement := body.AsBlock().Statements.Nodes[0]
		if statement.Kind != ast.KindReturnStatement || statement.AsReturnStatement().Expression == nil {
			continue
		}
		returned := ast.SkipParentheses(statement.AsReturnStatement().Expression)
		if l.isArrayPredicateCall(returned) && l.symbol(ast.SkipParentheses(returned.AsCallExpression().Arguments.Nodes[0])) == l.symbol(declaration.Parameters()[0].Name()) {
			return true
		}
	}
	return false
}

library_for_in.go:
package lower

import (
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// forIn takes a snapshot of a fixed plain object's actual keys. Shapes cannot gain or lose fields,
// and prototypes cannot be mutated, so this is JavaScript's enumeration throughout the loop.
func (l *lowering) forIn(node *ast.Node) ([]ir.Statement, error) {
	statement := node.AsForInOrOfStatement()
	proven := l.checker.GetTypeAtLocation(statement.Expression)
	if l.checker.IsArrayType(proven) || checker.IsTupleType(proven) {
		return nil, l.notYet(statement.Expression, "for...in over an array (holes and own enumerable properties are not represented; use for...of for elements)")
	}
	// Structural types can hide an array, and synthetic undefined spread fields are not real keys.
	// Require a plain literal origin, including aliases. This deliberately refuses parameters and
	// calls until their possible shapes and property presence can be proved.
	if !l.plainEnumerableObject(statement.Expression, map[*ast.Symbol]bool{}) {
		return nil, l.notYet(statement.Expression, "for...in without a proven fixed plain-object origin (arrays, prototypes and absent synthetic fields cannot be enumerated soundly)")
	}
	object, err := l.expression(statement.Expression)
	if err != nil {
		return nil, err
	}
	if object.Type() != ir.Object {
		return nil, l.notYet(statement.Expression, "for...in over a value that is not a plain object")
	}
	loop := ir.ForOf{Iterable: ir.ObjectKeys{Object: object}, Element: ir.String}
	initializer := statement.Initializer
	var assignment ir.Statement
	if initializer.Kind == ast.KindVariableDeclarationList {
		if initializer.Flags&ast.NodeFlagsBlockScoped == 0 {
			return nil, &Refused{Where: l.program.Where(initializer), What: "var", Fix: "use const or let"}
		}
		declarations := initializer.AsVariableDeclarationList().Declarations.Nodes
		if len(declarations) != 1 || !ast.IsIdentifier(declarations[0].Name()) {
			return nil, l.notYet(initializer, "a for...in binding that is not one plain name")
		}
		loop.Local, err = l.declareLocal(declarations[0].Name())
	} else {
		target := ast.SkipParentheses(initializer)
		local, found := l.local(target)
		if !ast.IsIdentifier(target) || !found || l.result.Locals[local].Type != ir.String {
			return nil, l.notYet(initializer, "a for...in assignment that is not a string variable")
		}
		loop.Local = len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: "key", Type: ir.String, Function: l.functionIndex})
		assignment = ir.Assign{Local: local, Value: ir.Read{Local: loop.Local, Of: ir.String}, Checked: l.checked(local)}
	}
	if err != nil {
		return nil, err
	}
	body, err := l.statement(statement.Statement)
	if err != nil {
		return nil, err
	}
	if assignment != nil {
		loop.Body = append(loop.Body, assignment)
	}
	loop.Body = append(loop.Body, body...)
	return []ir.Statement{loop}, nil
}

func (l *lowering) plainEnumerableObject(node *ast.Node, visiting map[*ast.Symbol]bool) bool {
	node = ast.SkipParentheses(node)
	// Enum objects have a complete fixed shape, including numeric reverse keys.
	if l.enumObject(node) != nil {
		return true
	}
	if node.Kind == ast.KindAsExpression {
		return l.plainEnumerableObject(node.AsAsExpression().Expression, visiting)
	}
	if node.Kind == ast.KindConditionalExpression {
		branch := node.AsConditionalExpression()
		return l.plainEnumerableObject(branch.WhenTrue, visiting) && l.plainEnumerableObject(branch.WhenFalse, visiting)
	}
	if node.Kind == ast.KindObjectLiteralExpression {
		for _, property := range node.AsObjectLiteralExpression().Properties.Nodes {
			switch property.Kind {
			case ast.KindSpreadAssignment:
				source := property.AsSpreadAssignment().Expression
				for _, field := range l.checker.GetPropertiesOfType(l.checker.GetTypeAtLocation(source)) {
					if field.Flags&ast.SymbolFlagsOptional != 0 {
						return false
					}
				}
				if !l.plainEnumerableObject(source, visiting) {
					return false
				}
			case ast.KindPropertyAssignment, ast.KindShorthandPropertyAssignment:
				name := property.Name()
				if name == nil || strings.ContainsRune(name.Text(), 0) || (property.Kind == ast.KindPropertyAssignment && name.Text() == "__proto__") {
					return false
				}
			default:
				return false
			}
		}
		return true
	}
	if !ast.IsIdentifier(node) {
		return false
	}
	// Optional structural fields can be absent in the runtime shape; writing them would add keys.
	for _, field := range l.checker.GetPropertiesOfType(l.checker.GetTypeAtLocation(node)) {
		if field.Flags&ast.SymbolFlagsOptional != 0 {
			return false
		}
	}
	symbol := l.symbol(node)
	if symbol == nil || visiting[symbol] || len(symbol.Declarations) != 1 {
		return false
	}
	declaration := symbol.Declarations[0]
	if declaration.Kind != ast.KindVariableDeclaration || declaration.AsVariableDeclaration().Initializer == nil {
		return false
	}
	visiting[symbol] = true
	defer delete(visiting, symbol)
	if !l.plainEnumerableObject(declaration.AsVariableDeclaration().Initializer, visiting) {
		return false
	}
	// Every assignment must have another proved plain-object origin. An alias may be assigned in
	// another module, but imported bindings are immutable and writes into object fields keep shape.
	safe := true
	var visit ast.Visitor
	visit = func(inner *ast.Node) bool {
		if !safe {
			return true
		}
		if inner.Kind == ast.KindBinaryExpression {
			binary := inner.AsBinaryExpression()
			if ast.IsIdentifier(ast.SkipParentheses(binary.Left)) && l.symbol(ast.SkipParentheses(binary.Left)) == symbol && binary.OperatorToken.Kind == ast.KindEqualsToken {
				safe = l.plainEnumerableObject(binary.Right, visiting)
			}
			if binary.OperatorToken.Kind == ast.KindEqualsToken && !ast.IsIdentifier(ast.SkipParentheses(binary.Left)) {
				var target ast.Visitor
				target = func(part *ast.Node) bool {
					if ast.IsIdentifier(part) && l.symbol(part) == symbol {
						safe = false
					}
					return part.ForEachChild(target)
				}
				if binary.Left.Kind == ast.KindArrayLiteralExpression || binary.Left.Kind == ast.KindObjectLiteralExpression {
					binary.Left.ForEachChild(target)
				}
			}
		}
		return inner.ForEachChild(visit)
	}
	ast.GetSourceFileOfNode(declaration).AsNode().ForEachChild(visit)
	return safe
}

library_function_expressions.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// functionExpression lowers ordinary function expressions and switch declarations with the same
// calling convention and counted captures as arrows. Ordinary
// functions have their own dynamic this; until that convention exists, every use of it is refused.
func (l *lowering) functionExpression(node *ast.Node) (ir.Expression, error) {
	if node.Body() == nil {
		return nil, l.notYet(node, "a function without a body")
	}
	if node.Kind == ast.KindFunctionExpression && node.AsFunctionExpression().AsteriskToken != nil || node.Kind == ast.KindFunctionDeclaration && node.AsFunctionDeclaration().AsteriskToken != nil {
		return nil, l.notYet(node, "a generator function expression")
	}
	if len(node.TypeParameters()) != 0 {
		return nil, l.notYet(node, "a generic function expression")
	}
	for _, parameter := range node.Parameters() {
		if ast.IsIdentifier(parameter.Name()) && parameter.Name().Text() == "this" {
			return nil, l.notYet(parameter, "a function expression with a this parameter (dynamic receivers are not implemented)")
		}
	}
	var invalid error
	var visit ast.Visitor
	visit = func(inner *ast.Node) bool {
		if invalid != nil {
			return true
		}
		// An arrow inherits this; another ordinary function or method owns a different this.
		if ast.IsFunctionLike(inner) && inner.Kind != ast.KindArrowFunction {
			return false
		}
		if inner.Kind == ast.KindThisKeyword && !ast.IsPartOfTypeNode(inner) {
			invalid = &Refused{Where: l.program.Where(inner), What: "this in a function expression", Fix: "dynamic receivers are not implemented; capture a named object, or use an arrow in a method"}
			return true
		}
		return inner.ForEachChild(visit)
	}
	node.Body().ForEachChild(visit)
	if invalid != nil {
		return nil, invalid
	}
	index := len(l.result.Functions)
	function := ir.Function{Name: "function_expression", Closure: true}
	if node.Name() != nil {
		function.Name = node.Name().Text()
	}
	if name := node.Name(); node.Kind == ast.KindFunctionExpression && name != nil {
		function.Name = name.Text()
		if l.locals == nil {
			l.locals = map[*ast.Symbol]int{}
		}
		local := len(l.result.Locals)
		l.locals[l.symbol(name)] = local
		l.result.Locals = append(l.result.Locals, ir.Local{Name: name.Text(), Type: ir.Closure, Function: index})
		l.noteLocal(local, l.checker.GetTypeAtLocation(node), name)
		function.Body = []ir.Statement{ir.Declare{Local: local, Value: ir.ClosureSelf{}}}
	}
	l.result.Functions = append(l.result.Functions, function)
	l.closureRecords = append(l.closureRecords, closureRecord{proven: l.concrete(l.checker.GetTypeAtLocation(node)), function: index, node: node})
	if l.instance != nil {
		l.instance.templates = append(l.instance.templates, template{closure: index, proven: l.checker.GetTypeAtLocation(node), isClosure: true})
	}
	l.closures = append(l.closures, index)
	outerThis := l.this
	l.this = -1
	err := l.lowerFunction(index, node, -1)
	l.this = outerThis
	l.closures = l.closures[:len(l.closures)-1]
	if err != nil {
		return nil, err
	}
	return ir.MakeClosure{Function: index}, nil
}

library_globals.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// These globals have stable identity. Their overloaded call signatures, prototypes and static
// properties are not ordinary closure or object fields, so values currently admit only equality
// and typeof. Calls still use the existing built-in dispatch, which does not read a global value.
func (l *lowering) libraryGlobalValue(node *ast.Node) (ir.Expression, bool, error) {
	for _, name := range []string{"Object", "Array", "String", "Number", "JSON", "Map", "Set"} {
		if !l.isLibraryGlobal(node, name) {
			continue
		}
		parent := node.Parent
		for parent != nil && parent.Kind == ast.KindParenthesizedExpression {
			parent = parent.Parent
		}
		if parent != nil && parent.Kind == ast.KindTypeOfExpression {
			return ir.LibraryGlobal{Name: name}, true, nil
		}
		if parent != nil && parent.Kind == ast.KindBinaryExpression {
			op := parent.AsBinaryExpression().OperatorToken.Kind
			if op == ast.KindEqualsEqualsEqualsToken || op == ast.KindExclamationEqualsEqualsToken {
				return ir.LibraryGlobal{Name: name}, true, nil
			}
		}
		return nil, true, l.notYet(node, name+" as a value outside equality or typeof (overloaded calls and static properties need their own representation)")
	}
	return nil, false, nil
}

library_json_stringify.go:
package lower

import (
	"sort"
	"strconv"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

func (l *lowering) jsonCall(node *ast.Node, name string) (ir.Expression, bool, error) {
	if name == "parse" {
		return nil, true, &Refused{Where: l.program.Where(node), What: "JSON.parse: its result's type can't be proven from the text", Fix: "a checked parse against a declared type is a later design; construct typed values explicitly for now"}
	}
	if name != "stringify" {
		return nil, true, l.notYet(node, "JSON."+name)
	}
	args := node.AsCallExpression().Arguments.Nodes
	if len(args) > 3 || hasSpread(node) {
		return nil, true, l.notYet(node, "JSON.stringify with spread or extra arguments")
	}
	result := ir.JSONStringify{Value: ir.Undefined{}, Schema: &ir.JSONSchema{Kind: "undefined"}}
	var err error
	if len(args) > 0 {
		result.Value, result.Schema, err = l.jsonInput(args[0])
		if err != nil {
			return nil, true, err
		}
	}
	if len(args) > 1 {
		if t := l.checker.GetTypeAtLocation(args[1]); len(l.checker.GetSignaturesOfType(t, checker.SignatureKindCall)) != 0 {
			return nil, true, l.notYet(args[1], "JSON.stringify replacer functions (the callback must have a proven type for every visited value and its holder)")
		}
		result.Replacer, result.ReplacerSchema, err = l.jsonInput(args[1])
		if err != nil {
			return nil, true, err
		}
		k := result.ReplacerSchema.Kind
		if k != "array" && k != "tuple" && k != "null" && k != "undefined" {
			return nil, true, l.notYet(args[1], "JSON.stringify replacer other than a key array, null or undefined")
		}
		// Only scalar keys: objects could run coercion code, which this slice does not invoke.
		if k == "tuple" {
			for _, f := range result.ReplacerSchema.Fields {
				if !jsonScalar(f.Schema) {
					return nil, true, l.notYet(args[1], "JSON.stringify replacer keys with object coercion")
				}
			}
		}
		if k == "array" && !jsonScalar(result.ReplacerSchema.Element) {
			return nil, true, l.notYet(args[1], "JSON.stringify replacer keys with object coercion")
		}
	}
	if len(args) > 2 {
		result.Space, result.SpaceSchema, err = l.jsonInput(args[2])
		if err != nil {
			return nil, true, err
		}
		if !jsonScalar(result.SpaceSchema) {
			return nil, true, l.notYet(args[2], "JSON.stringify space requiring object coercion")
		}
	}
	return result, true, nil
}
func jsonScalar(s *ir.JSONSchema) bool {
	return s.Kind == "number" || s.Kind == "boolean" || s.Kind == "string" || s.Kind == "undefined" || s.Kind == "null" || s.Kind == "union" || s.Kind == "maybe_number" || s.Kind == "maybe_boolean"
}

// Direct literals establish their complete shape, and preserve evaluation order. Anything read
// through an object type is refused: that type can hide additional fields or a toJSON method.
func (l *lowering) jsonInput(node *ast.Node) (ir.Expression, *ir.JSONSchema, error) {
	n := ast.SkipParentheses(node)
	if n.Kind == ast.KindNullKeyword {
		return ir.JSONNull{}, &ir.JSONSchema{Kind: "null"}, nil
	}
	if n.Kind == ast.KindArrayLiteralExpression || n.Kind == ast.KindObjectLiteralExpression {
		literal := ir.ObjectLiteral{Tuple: n.Kind == ast.KindArrayLiteralExpression}
		schema := &ir.JSONSchema{Kind: "object"}
		if literal.Tuple {
			schema.Kind = "tuple"
		}
		add := func(name string, v *ast.Node) error {
			if name == "toJSON" || name == "__proto__" {
				return l.notYet(v, "JSON.stringify a literal with "+name+" semantics")
			}
			for _, f := range literal.Fields {
				if f.Name == name {
					return l.notYet(v, "JSON.stringify duplicate literal keys")
				}
			}
			value, child, err := l.jsonInput(v)
			if err != nil {
				return err
			}
			if value.Type() == ir.MaybeBoolean {
				return l.notYet(v, "JSON.stringify a literal field with a two-word representation")
			}
			schema.Fields = append(schema.Fields, ir.JSONField{Name: l.constant(name), Slot: len(literal.Fields), Schema: child})
			literal.Fields = append(literal.Fields, ir.Field{Name: name, Value: value})
			return nil
		}
		if literal.Tuple {
			for i, v := range n.AsArrayLiteralExpression().Elements.Nodes {
				if v.Kind == ast.KindSpreadElement || v.Kind == ast.KindOmittedExpression {
					return nil, nil, l.notYet(v, "JSON.stringify a spread or hole in a literal")
				}
				if err := add(strconv.Itoa(i), v); err != nil {
					return nil, nil, err
				}
			}
		} else {
			for _, f := range n.AsObjectLiteralExpression().Properties.Nodes {
				if f.Kind != ast.KindPropertyAssignment {
					return nil, nil, l.notYet(f, "JSON.stringify a literal with spread, shorthand or methods")
				}
				key := f.Name()
				if !ast.IsIdentifier(key) && key.Kind != ast.KindStringLiteral && key.Kind != ast.KindNumericLiteral {
					return nil, nil, l.notYet(key, "JSON.stringify computed keys")
				}
				name := key.Text()
				if key.Kind == ast.KindNumericLiteral {
					v, err := strconv.ParseFloat(name, 64)
					if err != nil {
						return nil, nil, l.notYet(key, "JSON.stringify this numeric key")
					}
					name = strconv.FormatFloat(v, 'f', -1, 64)
					if _, ok := jsonIndex(name); !ok {
						return nil, nil, l.notYet(key, "JSON.stringify a numeric key outside the array-index range (spell it as a string)")
					}
				}
				if err := add(name, f.AsPropertyAssignment().Initializer); err != nil {
					return nil, nil, err
				}
			}
			// Integer indexes precede other strings, whose order is their insertion order.
			sort.SliceStable(schema.Fields, func(i, j int) bool {
				a, ai := jsonIndex(l.result.Strings[schema.Fields[i].Name])
				b, bi := jsonIndex(l.result.Strings[schema.Fields[j].Name])
				if ai != bi {
					return ai
				}
				return ai && a < b
			})
		}
		return literal, schema, nil
	}
	schema, err := l.jsonType(node, l.checker.GetTypeAtLocation(node), 0)
	if err != nil {
		return nil, nil, err
	}
	value, err := l.expression(node)
	return value, schema, err
}
func jsonIndex(name string) (uint64, bool) {
	n, err := strconv.ParseUint(name, 10, 32)
	return n, err == nil && n < 4294967295 && strconv.FormatUint(n, 10) == name
}
func (l *lowering) jsonType(node *ast.Node, t *checker.Type, depth int) (*ir.JSONSchema, error) {
	if depth == 0 && l.censusCallReturnsUndefined(node) {
		return &ir.JSONSchema{Kind: "undefined"}, nil
	}
	if depth > 64 {
		return nil, l.notYet(node, "JSON.stringify recursive array types")
	}
	if t.Flags()&checker.TypeFlagsUndefined != 0 {
		return &ir.JSONSchema{Kind: "undefined"}, nil
	}
	if t.Flags()&checker.TypeFlagsNever != 0 {
		return &ir.JSONSchema{Kind: "undefined"}, nil
	}
	of, known := l.representation(t)
	if !known {
		return nil, l.notYet(node, "JSON.stringify a value of type "+l.checker.TypeToString(t))
	}
	kinds := map[ir.Type]string{ir.Number: "number", ir.Boolean: "boolean", ir.String: "string", ir.Map: "map", ir.Closure: "function", ir.MaybeNumber: "maybe_number", ir.MaybeBoolean: "maybe_boolean", ir.Union: "union"}
	if of == ir.Array {
		element := l.checker.GetElementTypeOfArrayType(l.checker.GetNonNullableType(t))
		if element == nil {
			return nil, l.notYet(node, "JSON.stringify an array without a proven element type")
		}
		child, err := l.jsonType(node, element, depth+1)
		return &ir.JSONSchema{Kind: "array", Element: child}, err
	}
	if of == ir.Object || of == ir.Weak {
		return nil, l.notYet(node, "JSON.stringify object references (structural types can hide fields and toJSON; runtime shapes need complete value metadata)")
	}
	if t.Flags()&checker.TypeFlagsUnion != 0 {
		for _, m := range t.Types() {
			child, err := l.jsonType(node, m, depth+1)
			if err != nil {
				return nil, err
			}
			if of == ir.Union && (child.Kind == "array" || child.Kind == "object" || child.Kind == "tuple") {
				return nil, l.notYet(node, "JSON.stringify a union containing containers without runtime element metadata")
			}
		}
	}
	kind, ok := kinds[of]
	if !ok {
		return nil, l.notYet(node, "JSON.stringify this representation")
	}
	return &ir.JSONSchema{Kind: kind}, nil
}

library_map_set.go:
package lower

import (
	"strconv"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// Set operations become ordinary typed functions in the IR. Both backends and the ownership
// analyses then see every read and write, with no opaque runtime callback or hidden allocation.
func (l *lowering) librarySetMethod(node, receiver *ast.Node, name string) (ir.Expression, bool, error) {
	switch name {
	case "union", "intersection", "difference", "symmetricDifference", "isSubsetOf", "isSupersetOf", "isDisjointFrom":
	default:
		return nil, false, nil
	}
	arguments := node.AsCallExpression().Arguments.Nodes
	if len(arguments) != 1 || !l.isSet(arguments[0]) {
		return nil, true, l.notYet(node, name+" with anything but a concrete library Set")
	}
	element, err := l.setElement(receiver)
	if err != nil {
		return nil, true, err
	}
	otherElement, err := l.setElement(arguments[0])
	if err != nil {
		return nil, true, err
	}
	if element != otherElement {
		return nil, true, l.notYet(node, name+" between Sets whose elements have different representations")
	}
	left, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	right, err := l.expression(arguments[0])
	if err != nil {
		return nil, true, err
	}
	index := len(l.result.Functions)
	function := ir.Function{Name: "set_" + name, Returns: ir.Map}
	local := func(name string, of ir.Type) ir.Read {
		id := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: name, Type: of, Function: index})
		return ir.Read{Local: id, Of: of}
	}
	a, b := local("left", ir.Map), local("right", ir.Map)
	function.Parameters = []int{a.Local, b.Local}
	item := local("element", element)
	has := func(set ir.Expression) ir.Expression { return ir.MapHas{Map: set, Key: item, KeyType: element} }
	not := func(value ir.Expression) ir.Expression { return ir.Unary{Operator: ir.Not, Operand: value} }
	walk := func(set ir.Expression, body ...ir.Statement) ir.Statement {
		return ir.ForOf{Iterable: set, MapPart: "keys", Key: element, Value: ir.Number, Local: item.Local, Body: body}
	}
	smaller := ir.Binary{Operator: ir.LessOrEqual, Left: ir.MapSize{Map: a}, Right: ir.MapSize{Map: b}}
	switch name {
	case "isSubsetOf", "isSupersetOf", "isDisjointFrom":
		function.Returns = ir.Boolean
		no := ir.Return{Value: ir.BooleanConstant{Value: false}}
		check := func(source, other ir.Expression, present bool) ir.Statement {
			condition := has(other)
			if !present {
				condition = not(condition)
			}
			return walk(source, ir.If{Condition: condition, Then: []ir.Statement{no}})
		}
		if name == "isSubsetOf" {
			function.Body = []ir.Statement{ir.If{Condition: not(smaller), Then: []ir.Statement{no}}, check(a, b, false)}
		} else if name == "isSupersetOf" {
			function.Body = []ir.Statement{ir.If{Condition: ir.Binary{Operator: ir.Less, Left: ir.MapSize{Map: a}, Right: ir.MapSize{Map: b}}, Then: []ir.Statement{no}}, check(b, a, false)}
		} else {
			function.Body = []ir.Statement{ir.If{Condition: smaller, Then: []ir.Statement{check(a, b, true)}, Else: []ir.Statement{check(b, a, true)}}}
		}
		function.Body = append(function.Body, ir.Return{Value: ir.BooleanConstant{Value: true}})
	default:
		result := local("result", ir.Map)
		// The result is a fresh Set of the call's result type. Record its writes for the cycle proof.
		l.writeSites = append(l.writeSites, writeSite{holder: l.concrete(l.checker.GetTypeAtLocation(node)), node: node})
		site := len(l.writeSites)
		add := ir.Evaluate{Value: ir.SetAdd{Set: result, Value: item, Element: element, Site: site}}
		copy := func(source ir.Expression) ir.Statement { return walk(source, add) }
		selected := func(source, other ir.Expression, present bool) ir.Statement {
			condition := has(other)
			if !present {
				condition = not(condition)
			}
			return walk(source, ir.If{Condition: condition, Then: []ir.Statement{add}})
		}
		function.Body = []ir.Statement{ir.Declare{Local: result.Local, Value: ir.SetNew{Element: element}}}
		switch name {
		case "union":
			function.Body = append(function.Body, copy(a), copy(b))
		case "intersection":
			// The smaller Set supplies the order; ties visit the receiver (ECMA-262).
			function.Body = append(function.Body, ir.If{Condition: smaller, Then: []ir.Statement{selected(a, b, true)}, Else: []ir.Statement{selected(b, a, true)}})
		case "difference":
			function.Body = append(function.Body, selected(a, b, false))
		case "symmetricDifference":
			function.Body = append(function.Body, selected(a, b, false), selected(b, a, false))
		}
		function.Body = append(function.Body, ir.Return{Value: result})
	}
	l.result.Functions = append(l.result.Functions, function)
	return ir.Call{Function: index, Arguments: []ir.Expression{left, right}, Returns: function.Returns}, true, nil
}

func (l *lowering) libraryCollectionIterator(node, receiver *ast.Node, part string) (ir.Expression, bool, error) {
	if len(node.AsCallExpression().Arguments.Nodes) != 0 {
		return nil, true, l.notYet(node, part+" with arguments")
	}
	set := l.isSet(receiver)
	var key, value ir.Type
	var err error
	if set {
		key, err = l.setElement(receiver)
		value = key
	} else {
		key, value, err = l.mapTypes(receiver)
	}
	if err != nil {
		return nil, true, err
	}
	collection, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	return ir.CollectionIterator{Collection: collection, Part: part, Key: key, Value: value, Set: set}, true, nil
}

func (l *lowering) librarySetLiteral(node *ast.Node, element ir.Type) (ir.Expression, bool, error) {
	array := ir.ArrayLiteral{Element: element}
	for _, item := range ast.SkipParentheses(node).AsArrayLiteralExpression().Elements.Nodes {
		if item.Kind == ast.KindSpreadElement || item.Kind == ast.KindOmittedExpression {
			return nil, false, nil
		}
		value, err := l.expression(item)
		if err != nil {
			return nil, true, err
		}
		value = fit(value, element)
		if value.Type() != element {
			return nil, true, l.notYet(item, "a Set literal element held otherwise than the Set's")
		}
		array.Elements = append(array.Elements, value)
	}
	return array, true, nil
}

func (l *lowering) libraryEmptyCollectionArgument(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindNullKeyword {
		return true
	}
	_, local := l.local(node)
	return ast.IsIdentifier(node) && node.Text() == "undefined" && !local
}

// An arrow's this is lexical: thisArg is still evaluated in call order, but cannot bind it.
// Other callbacks stay refused until stage 0 can represent and check their dynamic this parameter.
func (l *lowering) libraryForEachThisArg(node, receiver *ast.Node, set bool) (ir.Expression, bool, error) {
	arguments := node.AsCallExpression().Arguments.Nodes
	if ast.SkipParentheses(arguments[0]).Kind != ast.KindArrowFunction {
		return nil, true, l.notYet(node, "forEach thisArg with a callback other than an arrow")
	}
	var key, value ir.Type
	var err error
	if set {
		key, err = l.setElement(receiver)
		value = key
	} else {
		key, value, err = l.mapTypes(receiver)
	}
	if err != nil {
		return nil, true, err
	}
	collection, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	callback, err := l.expression(arguments[0])
	if err != nil {
		return nil, true, err
	}
	context, err := l.expression(arguments[1])
	if err != nil {
		return nil, true, err
	}
	// Pass the context to an unused parameter, preserving evaluation order, side effects,
	// exceptions and its lifetime across the visit.
	if context.Type() == 0 {
		return nil, true, l.notYet(arguments[1], "forEach thisArg without a value representation")
	}
	values := []ir.Expression{collection, callback, context}
	index := len(l.result.Functions)
	function := ir.Function{Name: "collection_forEach_thisArg"}
	for _, argument := range values {
		id := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: "argument", Type: argument.Type(), Function: index})
		function.Parameters = append(function.Parameters, id)
	}
	// Read the actual arrow's return representation, including an owned result discarded by forEach.
	returns := l.result.Functions[callback.(ir.MakeClosure).Function].Returns
	if slotless(returns) {
		return nil, true, l.notYet(node, "forEach with a callback result held in more than one word")
	}
	function.Body = []ir.Statement{ir.Evaluate{Value: ir.MapForEach{Map: ir.Read{Local: function.Parameters[0], Of: ir.Map}, Callback: ir.Read{Local: function.Parameters[1], Of: ir.Closure}, Key: key, Value: value, Set: set, Returns: returns, CallbackType: int(l.concrete(l.checker.GetTypeAtLocation(arguments[0])).Id())}}}
	l.result.Functions = append(l.result.Functions, function)
	return ir.Call{Function: index, Arguments: values}, true, nil
}

func (l *lowering) libraryLocal(function int, name string, of ir.Type) ir.Read {
	id := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: name, Type: of, Function: function})
	return ir.Read{Local: id, Of: of}
}

// A stored iterator is consumed by calls to next, rather than by snapshotting its collection.
func (l *lowering) libraryIteratorElement(node *ast.Node) (ir.Type, bool) {
	proven := l.checker.GetTypeAtLocation(node)
	if !l.isLibraryType(proven, "MapIterator", "SetIterator") {
		return 0, false
	}
	arguments := l.typeArguments(proven)
	if len(arguments) != 1 {
		return 0, false
	}
	element, known := l.representation(arguments[0])
	// Scalar unions already occupy one tagged reference slot in the iterator.
	return element, known && (!slotless(element) || element == ir.Union && l.writable(arguments[0]))
}

func (l *lowering) libraryIteratorLoop(function int, iterator ir.Expression, item ir.Read, body []ir.Statement) []ir.Statement {
	held := l.libraryLocal(function, "iterator", ir.Object)
	step := l.libraryLocal(function, "step", ir.Object)
	loop := []ir.Statement{
		ir.Declare{Local: step.Local, Value: ir.CallClosure{Closure: ir.Property{Object: held, Name: "next", Of: ir.Closure}, Returns: ir.Object}},
		ir.If{Condition: ir.Property{Object: step, Name: "done", Of: ir.Boolean}, Then: []ir.Statement{ir.Break{}}},
		ir.Declare{Local: item.Local, Value: ir.Property{Object: step, Name: "value", Of: item.Of}},
	}
	loop = append(loop, body...)
	return []ir.Statement{ir.Declare{Local: held.Local, Value: iterator}, ir.Loop{Condition: ir.BooleanConstant{Value: true}, Body: loop}}
}

func (l *lowering) libraryIteratorArray(node *ast.Node, iterator ir.Expression, element ir.Type) ir.Expression {
	index := len(l.result.Functions)
	function := ir.Function{Name: "collection_iterator_array", Returns: ir.Array}
	parameter := l.libraryLocal(index, "input", ir.Object)
	array := l.libraryLocal(index, "values", ir.Array)
	item := l.libraryLocal(index, "element", element)
	function.Parameters = []int{parameter.Local}
	function.Body = []ir.Statement{ir.Declare{Local: array.Local, Value: ir.ArrayLiteral{Element: element}}}
	l.writeSites = append(l.writeSites, writeSite{node: node})
	site := len(l.writeSites)
	function.Body = append(function.Body, l.libraryIteratorLoop(index, parameter, item, []ir.Statement{ir.Evaluate{Value: ir.ArrayPush{Array: array, Value: item, Element: element, Site: site}}})...)
	function.Body = append(function.Body, ir.Return{Value: array})
	l.result.Functions = append(l.result.Functions, function)
	return ir.Call{Function: index, Arguments: []ir.Expression{iterator}, Returns: ir.Array}
}

func (l *lowering) libraryForOfIterator(node *ast.Node, iterator ir.Expression, element ir.Type, name *ast.Node) ([]ir.Statement, error) {
	item := l.libraryLocal(l.functionIndex, "element", element)
	var bindings []ir.Statement
	if ast.IsIdentifier(name) {
		local, err := l.declareLocal(name)
		if err != nil {
			return nil, err
		}
		bindings = append(bindings, ir.Declare{Local: local, Value: item})
	} else {
		if element != ir.Object {
			return nil, l.notYet(name, "destructuring a scalar iterator element")
		}
		for index, binding := range name.AsBindingPattern().Elements.Nodes {
			if skipped(binding) {
				continue
			}
			declared := binding.AsBindingElement()
			if !ast.IsIdentifier(binding.Name()) || declared.Initializer != nil || declared.DotDotDotToken != nil {
				return nil, l.notYet(binding, "an iterator binding that isn't plain")
			}
			local, err := l.declareLocal(binding.Name())
			if err != nil {
				return nil, err
			}
			of := l.result.Locals[local].Type
			if slotless(of) && !(of == ir.Union && l.writable(l.checker.GetTypeAtLocation(binding.Name()))) {
				return nil, l.notYet(binding, "an iterator binding held in more than one word")
			}
			bindings = append(bindings, ir.Declare{Local: local, Value: ir.Property{Object: item, Name: strconv.Itoa(index), Of: of}})
		}
	}
	body, err := l.statement(node.AsForInOrOfStatement().Statement)
	if err != nil {
		return nil, err
	}
	return []ir.Statement{ir.Block{Body: l.libraryIteratorLoop(l.functionIndex, iterator, item, append(bindings, body...))}}, nil
}

// groupBy copies elements into fresh bucket arrays while walking the original input live. Callback
// mutation therefore sees the same array/collection iterator that Node walks, not a snapshot.
func (l *lowering) libraryMapGroupBy(node *ast.Node) (ir.Expression, bool, error) {
	arguments := node.AsCallExpression().Arguments.Nodes
	if len(arguments) != 2 {
		return nil, true, l.notYet(node, "Map.groupBy with other than an iterable and callback")
	}
	key, _, err := l.mapTypes(node)
	if err != nil {
		return nil, true, err
	}
	sourceNode := arguments[0]
	source, err := l.expression(sourceNode)
	if err != nil {
		return nil, true, err
	}
	var element ir.Type
	iterator := false
	switch source.Type() {
	case ir.Array:
		element, err = l.elementType(sourceNode)
	case ir.String:
		element = ir.String
	case ir.Map:
		var k, v ir.Type
		if l.isSet(sourceNode) {
			k, err = l.setElement(sourceNode)
			v = k
			element = k
		} else {
			k, v, err = l.mapTypes(sourceNode)
			element = ir.Object
		}
		part := "entries"
		if l.isSet(sourceNode) {
			part = "keys"
		}
		source = ir.CollectionIterator{Collection: source, Part: part, Key: k, Value: v, Set: l.isSet(sourceNode)}
		iterator = true
	case ir.Object:
		var known bool
		element, known = l.libraryIteratorElement(sourceNode)
		if !known {
			return nil, true, l.notYet(sourceNode, "Map.groupBy over an unsupported iterable")
		}
		iterator = true
	default:
		return nil, true, l.notYet(sourceNode, "Map.groupBy over an unsupported iterable")
	}
	if err != nil {
		return nil, true, err
	}
	if slotless(element) {
		return nil, true, l.notYet(sourceNode, "Map.groupBy elements held in more than one word")
	}
	// The checker must retain the source element's exact type in each bucket; widening a mutable
	// element would expose an alias through the returned arrays. Refuse such inferred widening.
	var sourceType *checker.Type
	proven := l.checker.GetTypeAtLocation(sourceNode)
	if l.checker.IsArrayType(proven) {
		sourceType = l.checker.GetElementTypeOfArrayType(proven)
	}
	if l.isSet(sourceNode) || l.isLibraryType(proven, "MapIterator", "SetIterator") {
		sourceType = l.typeArguments(proven)[0]
	}
	grouped := l.typeArguments(l.checker.GetTypeAtLocation(node))
	if len(grouped) != 2 {
		return nil, true, l.notYet(node, "Map.groupBy without known grouped elements")
	}
	groupedElement := l.checker.GetElementTypeOfArrayType(grouped[1])
	if held, known := l.representation(groupedElement); !known || held != element {
		return nil, true, l.notYet(node, "Map.groupBy grouped elements held otherwise than the input's")
	}
	if l.isLibraryType(proven, "Map", "ReadonlyMap") {
		if !checker.IsTupleType(groupedElement) {
			return nil, true, l.notYet(node, "Map.groupBy widening its Map entries")
		}
		components := l.typeArguments(groupedElement)
		original := l.typeArguments(proven)
		if len(components) != 2 || l.checker.TypeToString(components[0]) != l.checker.TypeToString(original[0]) || l.checker.TypeToString(components[1]) != l.checker.TypeToString(original[1]) {
			return nil, true, l.notYet(node, "Map.groupBy widening its Map entry components")
		}
	}
	if sourceType != nil && l.checker.TypeToString(sourceType) != l.checker.TypeToString(groupedElement) {
		return nil, true, l.notYet(node, "Map.groupBy widening its mutable elements")
	}
	callback, err := l.expression(arguments[1])
	if err != nil {
		return nil, true, err
	}
	if callback.Type() != ir.Closure {
		return nil, true, l.notYet(node, "Map.groupBy without a function callback")
	}
	signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(arguments[1]), checker.SignatureKindCall)
	if len(signatures) != 1 {
		return nil, true, l.notYet(node, "Map.groupBy with an overloaded callback")
	}
	if parameters := signatures[0].Parameters(); len(parameters) > 0 {
		received, known := l.representation(l.checker.GetTypeOfSymbol(parameters[0]))
		if !known || received != element {
			return nil, true, l.notYet(node, "Map.groupBy callback elements held otherwise than the input's")
		}
	}
	returns, known := l.representation(l.checker.GetReturnTypeOfSignature(signatures[0]))
	if !known || returns != key {
		return nil, true, l.notYet(node, "Map.groupBy callback keys held otherwise than the result's")
	}
	index := len(l.result.Functions)
	function := ir.Function{Name: "map_groupBy", Returns: ir.Map}
	input := l.libraryLocal(index, "input", source.Type())
	fn := l.libraryLocal(index, "callback", ir.Closure)
	result := l.libraryLocal(index, "groups", ir.Map)
	position := l.libraryLocal(index, "index", ir.Number)
	item := l.libraryLocal(index, "element", element)
	groupKey := l.libraryLocal(index, "key", key)
	bucket := l.libraryLocal(index, "bucket", ir.Array)
	function.Parameters = []int{input.Local, fn.Local}
	l.writeSites = append(l.writeSites, writeSite{holder: l.concrete(l.checker.GetTypeAtLocation(node)), node: node})
	mapSite := len(l.writeSites)
	l.writeSites = append(l.writeSites, writeSite{holder: grouped[1], node: node})
	arraySite := len(l.writeSites)
	body := []ir.Statement{
		ir.Declare{Local: groupKey.Local, Value: ir.CallClosure{Closure: fn, Arguments: []ir.Expression{item, position}, Returns: key}},
		ir.Assign{Local: position.Local, Value: ir.Binary{Operator: ir.Add, Left: position, Right: ir.NumberConstant{Value: 1}}},
		ir.Declare{Local: bucket.Local, Value: ir.Coalesce{Value: ir.MapGet{Map: result, Key: groupKey, KeyType: key, ValueType: ir.Array}, Fallback: ir.ArrayLiteral{Element: element}, Of: ir.Array}},
		ir.Evaluate{Value: ir.ArrayPush{Array: bucket, Value: item, Element: element, Site: arraySite}},
		ir.Evaluate{Value: ir.MapSet{Map: result, Key: groupKey, Value: bucket, KeyType: key, ValueType: ir.Array, Site: mapSite}},
	}
	function.Body = []ir.Statement{ir.Declare{Local: result.Local, Value: ir.MapNew{Key: key, Value: ir.Array}}, ir.Declare{Local: position.Local, Value: ir.NumberConstant{}}}
	if iterator {
		function.Body = append(function.Body, l.libraryIteratorLoop(index, input, item, body)...)
	} else {
		function.Body = append(function.Body, ir.ForOf{Iterable: input, Element: element, Local: item.Local, Body: body})
	}
	function.Body = append(function.Body, ir.Return{Value: result})
	l.result.Functions = append(l.result.Functions, function)
	return ir.Call{Function: index, Arguments: []ir.Expression{source, callback}, Returns: ir.Map}, true, nil
}

// Copy present numeric elements into packed slots when the Set's inferred or explicit type also
// admits undefined. Reusing the input array would change how its existing aliases read its NaNs.
func (l *lowering) libraryOptionalNumbers(node *ast.Node, source ir.Expression) ir.Expression {
	index := len(l.result.Functions)
	function := ir.Function{Name: "collection_optional_numbers", Returns: ir.Array}
	input := l.libraryLocal(index, "input", ir.Array)
	array := l.libraryLocal(index, "values", ir.Array)
	item := l.libraryLocal(index, "number", ir.Number)
	function.Parameters = []int{input.Local}
	l.writeSites = append(l.writeSites, writeSite{node: node})
	site := len(l.writeSites)
	function.Body = []ir.Statement{
		ir.Declare{Local: array.Local, Value: ir.ArrayLiteral{Element: ir.MaybeNumber}},
		ir.ForOf{Iterable: input, Element: ir.Number, Local: item.Local, Body: []ir.Statement{ir.Evaluate{Value: ir.ArrayPush{Array: array, Value: fit(item, ir.MaybeNumber), Element: ir.MaybeNumber, Site: site}}}},
		ir.Return{Value: array},
	}
	l.result.Functions = append(l.result.Functions, function)
	return ir.Call{Function: index, Arguments: []ir.Expression{source}, Returns: ir.Array}
}

// Collection iterators hold their source strongly, though the public iterator type only names its
// yielded elements. Keep this hidden edge visible to the cycle finder just like a closure capture.
type libraryIteratorCapture struct {
	iterator, collection *checker.Type
}

func (f *cycleFinder) libraryIteratorMade(node *ast.Node) {
	if node.Kind != ast.KindCallExpression {
		return
	}
	callee := ast.SkipParentheses(node.AsCallExpression().Expression)
	if callee.Kind != ast.KindPropertyAccessExpression {
		return
	}
	access := callee.AsPropertyAccessExpression()
	iterator := f.l.checker.GetTypeAtLocation(node)
	collection := f.l.checker.GetTypeAtLocation(access.Expression)
	if f.l.isLibraryType(iterator, "MapIterator", "SetIterator") &&
		f.l.isLibraryType(collection, "Map", "ReadonlyMap", "Set", "ReadonlySet") {
		f.libraryIterators = append(f.libraryIterators, libraryIteratorCapture{iterator, collection})
	}
}

func (f *cycleFinder) libraryIteratorCaptures(proven *checker.Type) []cycleNode {
	var held []cycleNode
	for _, capture := range f.libraryIterators {
		if f.l.checker.IsTypeAssignableTo(capture.iterator, proven) {
			held = append(held, cycleNode{proven: capture.collection})
		}
	}
	return held
}

// Iterator next is inherited in JavaScript. Copying our internal closure slot as an own
// enumerable field would let a copy drive the original iterator, unlike Node.
func (l *lowering) libraryIteratorUnsupportedUse(node *ast.Node) error {
	isIterator := func(source *ast.Node) bool {
		return l.libraryIteratorType(l.checker.GetTypeAtLocation(source))
	}
	if node.Kind == ast.KindObjectLiteralExpression {
		for _, property := range node.AsObjectLiteralExpression().Properties.Nodes {
			if property.Kind == ast.KindSpreadAssignment && isIterator(property.AsSpreadAssignment().Expression) {
				return l.notYet(property, "spreading a Map or Set iterator: next is inherited, not an own enumerable field; use the original iterator or collect its elements into an array")
			}
		}
	}
	if node.Kind == ast.KindCallExpression {
		call := node.AsCallExpression()
		callee := ast.SkipParentheses(call.Expression)
		if callee.Kind == ast.KindPropertyAccessExpression && callee.Name().Text() == "assign" && l.isLibraryGlobal(callee.AsPropertyAccessExpression().Expression, "Object") {
			for index, source := range call.Arguments.Nodes {
				if index == 0 {
					continue
				}
				if isIterator(source) {
					return l.notYet(source, "Object.assign copying a Map or Set iterator: next is inherited, not an own enumerable field; use the original iterator")
				}
			}
		}
	}
	return nil
}

func (l *lowering) libraryIteratorType(proven *checker.Type) bool {
	if proven.Flags()&(checker.TypeFlagsUnion|checker.TypeFlagsIntersection) != 0 {
		for _, member := range proven.Types() {
			if l.libraryIteratorType(member) {
				return true
			}
		}
	}
	return l.isLibraryType(proven, "MapIterator", "SetIterator")
}

library_math_number.go:
package lower

import (
	"math"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// These are the exact binary64 constants V8 exposes, not computations with libm.
var libraryMathConstants = map[string]float64{
	"LN10": 0x1.26bb1bbb55516p+1, "LN2": 0x1.62e42fefa39efp-1,
	"LOG10E": 0x1.bcb7b1526e50ep-2, "LOG2E": 0x1.71547652b82fep+0,
	"SQRT1_2": 0x1.6a09e667f3bcdp-1, "SQRT2": 0x1.6a09e667f3bcdp+0,
}

func (l *lowering) libraryMathNumberProperty(node *ast.Node) (ir.Expression, bool) {
	access := node.AsPropertyAccessExpression()
	if l.isLibraryGlobal(access.Expression, "Math") {
		if value, known := libraryMathConstants[node.Name().Text()]; known {
			return ir.NumberConstant{Value: value}, true
		}
	}
	if l.isLibraryGlobal(access.Expression, "Number") {
		switch node.Name().Text() {
		case "length":
			return ir.NumberConstant{Value: 1}, true
		case "name":
			return ir.StringConstant{Index: l.constant("Number")}, true
		}
	}
	return nil, false
}

func (l *lowering) numberPrototype(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	return node.Kind == ast.KindPropertyAccessExpression && node.Name().Text() == "prototype" && l.isLibraryGlobal(node.AsPropertyAccessExpression().Expression, "Number")
}

// libraryNumber implements primitive ToNumber and delegates represented conversion methods.
// Dynamic object protocols stay explicit rather than guessing away user code.
func (l *lowering) libraryNumber(node *ast.Node) (ir.Expression, error) {
	if ast.SkipParentheses(node).Kind == ast.KindNullKeyword {
		return ir.NumberConstant{}, nil
	}
	value, err := l.expression(node)
	if err != nil {
		return nil, err
	}
	if _, missing := value.(ir.Undefined); missing {
		return ir.NumberConstant{Value: math.NaN()}, nil
	}
	switch value.Type() {
	case ir.Number:
		return value, nil
	case ir.Boolean, ir.String, ir.MaybeNumber, ir.MaybeBoolean:
	case ir.Object, ir.Array:
		return l.censusNumberObject(node, value)
	case ir.Union:
		if !l.writable(l.checker.GetTypeAtLocation(node)) {
			return nil, l.notYet(node, "Number conversion of a union containing objects")
		}
	default:
		return nil, l.notYet(node, "Number conversion of an object")
	}
	return ir.NumberCall{Function: "convert", Arguments: []ir.Expression{value}}, nil
}

func (l *lowering) libraryMathNumberCall(node *ast.Node) (ir.Expression, bool, error) {
	callee := ast.SkipParentheses(node.AsCallExpression().Expression)
	written := node.AsCallExpression().Arguments.Nodes
	if l.isLibraryGlobal(callee, "Number") {
		if len(written) == 0 {
			return ir.NumberConstant{}, true, nil
		}
		if len(written) != 1 || hasSpread(node) {
			return nil, true, l.notYet(node, "Number with spread or extra arguments")
		}
		value, err := l.libraryNumber(written[0])
		return value, true, err
	}
	if callee.Kind != ast.KindPropertyAccessExpression {
		return nil, false, nil
	}
	receiver, name := callee.AsPropertyAccessExpression().Expression, callee.Name().Text()
	if l.isLibraryGlobal(receiver, "Math") && (name == "clz32" || name == "fround" || name == "imul") {
		count := 1
		if name == "imul" {
			count = 2
		}
		if len(written) > count || hasSpread(node) {
			return nil, true, l.notYet(node, "Math."+name+" with spread or extra arguments")
		}
		arguments := []ir.Expression{}
		for _, argument := range written {
			value, err := l.libraryNumber(argument)
			if err != nil {
				return nil, true, err
			}
			arguments = append(arguments, value)
		}
		for len(arguments) < count {
			arguments = append(arguments, ir.NumberConstant{Value: math.NaN()})
		}
		return ir.MathCall{Function: name, Arguments: arguments}, true, nil
	}
	if (l.isLibraryGlobal(receiver, "Number") || l.numberPrototype(receiver)) && name == "hasOwnProperty" {
		if len(written) != 1 {
			return nil, true, l.notYet(node, "Number.hasOwnProperty with other than one key")
		}
		key, err := l.expression(written[0])
		if err != nil {
			return nil, true, err
		}
		if key.Type() != ir.String {
			return nil, true, l.notYet(node, "Number.hasOwnProperty with a non-string key")
		}
		function := "hasOwnProperty"
		if l.numberPrototype(receiver) {
			function = "prototypeHasOwnProperty"
		}
		return ir.NumberCall{Function: function, Arguments: []ir.Expression{key}}, true, nil
	}
	// Number.prototype carries [[NumberData]] +0. Its methods may also be called with a primitive
	// number as this; no prototype object is represented as a plain object with invented fields.
	var value ir.Expression
	if l.numberPrototype(receiver) {
		value = ir.NumberConstant{}
	} else if name == "call" && ast.SkipParentheses(receiver).Kind == ast.KindPropertyAccessExpression {
		method := ast.SkipParentheses(receiver)
		if !l.numberPrototype(method.AsPropertyAccessExpression().Expression) {
			return nil, false, nil
		}
		name = method.Name().Text()
		if len(written) == 0 {
			return nil, true, l.notYet(node, "Number prototype method without a numeric receiver")
		}
		var err error
		if l.numberPrototype(written[0]) {
			value = ir.NumberConstant{}
		} else {
			value, err = l.expression(written[0])
			if err != nil {
				return nil, true, err
			}
			if value.Type() != ir.Number {
				return nil, true, l.notYet(node, "Number prototype method on a non-number receiver")
			}
		}
		written = written[1:]
	} else {
		return nil, false, nil
	}
	if name == "valueOf" && len(written) == 0 {
		return value, true, nil
	}
	if name != "toString" && name != "toFixed" && name != "toExponential" && name != "toPrecision" {
		return nil, true, l.notYet(node, "Number.prototype."+name)
	}
	if len(written) > 1 {
		return nil, true, l.notYet(node, "Number prototype format with extra arguments")
	}
	var argument ir.Expression
	if len(written) == 1 {
		var err error
		argument, err = l.expression(written[0])
		if err != nil {
			return nil, true, err
		}
		if _, missing := argument.(ir.Undefined); missing {
			argument = nil
		} else if argument.Type() != ir.Number {
			return nil, true, l.notYet(node, "Number prototype format with a non-number argument")
		}
	}
	if name == "toFixed" {
		if argument == nil {
			argument = ir.NumberConstant{}
		}
		return ir.ToFixed{Value: value, Digits: argument}, true, nil
	}
	return ir.NumberFormat{Method: name, Value: value, Argument: argument}, true, nil
}

// A .call with an explicit this is bound, even though its method expression isn't the callee.
func (l *lowering) libraryNumberBoundMethod(node *ast.Node) bool {
	if !l.numberPrototype(node.AsPropertyAccessExpression().Expression) {
		return false
	}
	parent := node.Parent
	for parent != nil && parent.Kind == ast.KindParenthesizedExpression {
		parent = parent.Parent
	}
	return parent != nil && parent.Kind == ast.KindPropertyAccessExpression && parent.Name().Text() == "call" && called(parent)
}

library_method_values.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// Intrinsic aliases are specialized at their uses. Their token is deliberately opaque: it may
// only be copied to another const, called with a proven receiver, or used by a supported callback
// adapter. It cannot escape into a slot whose callable ABI would erase the receiver's type.
type libraryMethod struct {
	family, name string
	source       *ast.Node
}

func (l *lowering) libraryMethod(node *ast.Node, seen map[*ast.Symbol]bool) (libraryMethod, bool) {
	node = ast.SkipParentheses(node)
	if ast.IsIdentifier(node) {
		for _, name := range []string{"String", "Number", "parseInt", "parseFloat"} {
			if l.isLibraryGlobal(node, name) {
				return libraryMethod{"global", name, node}, true
			}
		}
		symbol := l.symbol(node)
		if symbol == nil || seen[symbol] || len(symbol.Declarations) != 1 {
			return libraryMethod{}, false
		}
		seen[symbol] = true
		declaration := symbol.Declarations[0]
		if declaration.Kind != ast.KindVariableDeclaration || declaration.Parent == nil || declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
			return libraryMethod{}, false
		}
		initializer := declaration.AsVariableDeclaration().Initializer
		if initializer == nil {
			return libraryMethod{}, false
		}
		return l.libraryMethod(initializer, seen)
	}
	if node.Kind != ast.KindPropertyAccessExpression || !l.libraryMember(node) || len(l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(node), checker.SignatureKindCall)) == 0 {
		return libraryMethod{}, false
	}
	access := node.AsPropertyAccessExpression()
	if access.QuestionDotToken != nil || node.Flags&ast.NodeFlagsOptionalChain != 0 {
		return libraryMethod{}, false
	}
	if l.isLibraryGlobal(access.Expression, "Math") && node.Name().Text() == "random" {
		return libraryMethod{}, false
	}
	receiver := ast.SkipParentheses(access.Expression)
	for _, family := range []string{"Array", "String", "Number", "Object", "Math"} {
		if l.isLibraryGlobal(receiver, family) {
			return libraryMethod{family, node.Name().Text(), node}, true
		}
		if receiver.Kind == ast.KindPropertyAccessExpression && receiver.Name().Text() == "prototype" && l.isLibraryGlobal(receiver.AsPropertyAccessExpression().Expression, family) {
			return libraryMethod{family + ".prototype", node.Name().Text(), node}, true
		}
	}
	return libraryMethod{}, false
}

func constMethodInitializer(node *ast.Node) bool {
	outer := node
	for outer.Parent != nil && outer.Parent.Kind == ast.KindParenthesizedExpression {
		outer = outer.Parent
	}
	parent := outer.Parent
	return parent != nil && parent.Kind == ast.KindVariableDeclaration && parent.AsVariableDeclaration().Initializer == outer && parent.Parent != nil && parent.Parent.Flags&ast.NodeFlagsConst != 0
}

func (l *lowering) libraryMethodReadAllowed(node *ast.Node) bool {
	if _, known := l.libraryMethod(node, map[*ast.Symbol]bool{}); !known {
		return false
	}
	if constMethodInitializer(node) {
		return true
	}
	outer := node
	for outer.Parent != nil && outer.Parent.Kind == ast.KindParenthesizedExpression {
		outer = outer.Parent
	}
	parent := outer.Parent
	if parent != nil && parent.Kind == ast.KindPropertyAccessExpression && (parent.Name().Text() == "call" || parent.Name().Text() == "apply" || parent.Name().Text() == "bind") && called(parent) {
		return true
	}
	return l.libraryMapArgument(node)
}

func (l *lowering) libraryMapArgument(node *ast.Node) bool {
	outer := node
	for outer.Parent != nil && outer.Parent.Kind == ast.KindParenthesizedExpression {
		outer = outer.Parent
	}
	parent := outer.Parent
	if parent == nil || parent.Kind != ast.KindCallExpression {
		return false
	}
	call := parent.AsCallExpression()
	if len(call.Arguments.Nodes) != 1 || call.Arguments.Nodes[0] != outer {
		return false
	}
	callee := ast.SkipParentheses(call.Expression)
	return callee.Kind == ast.KindPropertyAccessExpression && callee.Name().Text() == "map" && l.libraryMember(callee)
}

func (l *lowering) libraryMethodValue(node *ast.Node) (ir.Expression, bool, error) {
	_, known := l.libraryMethod(node, map[*ast.Symbol]bool{})
	if !known {
		return nil, false, nil
	}
	// Ordinary direct calls and existing observations are dispatched elsewhere.
	if ast.IsIdentifier(node) && (l.isLibraryGlobal(node, "String") || l.isLibraryGlobal(node, "Number")) {
		parent := node.Parent
		for parent != nil && parent.Kind == ast.KindParenthesizedExpression {
			parent = parent.Parent
		}
		if parent != nil && parent.Kind == ast.KindBinaryExpression {
			operator := parent.AsBinaryExpression().OperatorToken.Kind
			if operator == ast.KindEqualsEqualsEqualsToken || operator == ast.KindExclamationEqualsEqualsToken {
				return nil, false, nil
			}
		}
	}
	if called(node) {
		return nil, false, nil
	}
	if !constMethodInitializer(node) {
		return nil, true, l.notYet(node, "a library method value outside a const alias, typed call/apply, or supported map callback (its receiver and callable ABI are not proven); wrap the call in an arrow")
	}
	if ast.IsIdentifier(node) && !l.isLibraryGlobal(node, "String") && !l.isLibraryGlobal(node, "Number") && !l.isLibraryGlobal(node, "parseInt") && !l.isLibraryGlobal(node, "parseFloat") {
		return nil, false, nil
	}
	index := len(l.result.Functions)
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "library_method_token", Closure: true, Returns: ir.Number, Body: []ir.Statement{ir.Return{Value: ir.NumberConstant{}}}})
	return ir.MakeClosure{Function: index}, true, nil
}

// sequence returns the last operand while keeping all preceding evaluations and their checks.
func (l *lowering) methodSequence(values []ir.Expression) ir.Expression {
	index := len(l.result.Functions)
	function := ir.Function{Name: "library_method_sequence", Returns: values[len(values)-1].Type()}
	for _, value := range values {
		local := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: "argument", Type: value.Type(), Function: index})
		function.Parameters = append(function.Parameters, local)
	}
	function.Body = []ir.Statement{ir.Return{Value: ir.Read{Local: function.Parameters[len(function.Parameters)-1], Of: function.Returns}}}
	l.result.Functions = append(l.result.Functions, function)
	return ir.Call{Function: index, Arguments: values, Returns: function.Returns}
}

func (l *lowering) methodAliasRead(node *ast.Node) (ir.Expression, error) {
	if !ast.IsIdentifier(ast.SkipParentheses(node)) {
		return nil, nil
	}
	if local, known := l.local(ast.SkipParentheses(node)); known {
		return ir.Read{Local: local, Of: ir.Closure, Checked: l.checked(local)}, nil
	}
	return nil, nil
}

func (l *lowering) libraryMethodCall(node *ast.Node) (ir.Expression, bool, error) {
	call := node.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	target := callee
	mode := "direct"
	if callee.Kind == ast.KindPropertyAccessExpression && (callee.Name().Text() == "call" || callee.Name().Text() == "apply" || callee.Name().Text() == "bind") {
		mode = callee.Name().Text()
		target = callee.AsPropertyAccessExpression().Expression
	}
	method, known := l.libraryMethod(target, map[*ast.Symbol]bool{})
	if !known {
		return nil, false, nil
	}
	// Leave existing immediate primitive prototype calls on their established paths.
	if mode == "call" && method.source == ast.SkipParentheses(target) && (method.family == "String.prototype" || method.family == "Number.prototype") {
		return nil, false, nil
	}
	// Leave the intrinsic's ordinary direct call on the established path.
	if mode == "direct" && !ast.IsIdentifier(target) {
		return nil, false, nil
	}
	if mode == "direct" && method.source == target {
		return nil, false, nil
	}
	if mode == "bind" {
		value, err := l.libraryMethodBind(node, target, method)
		return value, true, err
	}
	if hasSpread(node) {
		return nil, true, l.notYet(node, "spread into a delayed library call (argument arity is not proven)")
	}
	written := call.Arguments.Nodes
	var receiver *ast.Node
	if mode != "direct" {
		if len(written) == 0 {
			return nil, true, l.notYet(node, "a delayed library call without a receiver")
		}
		receiver, written = written[0], written[1:]
	}
	if mode == "apply" {
		if len(written) != 1 || ast.SkipParentheses(written[0]).Kind != ast.KindArrayLiteralExpression {
			return nil, true, l.notYet(node, "apply without a dense argument literal (length, presence and argument representations must be proven)")
		}
		written = ast.SkipParentheses(written[0]).AsArrayLiteralExpression().Elements.Nodes
		for _, argument := range written {
			if argument.Kind == ast.KindSpreadElement || argument.Kind == ast.KindOmittedExpression {
				return nil, true, l.notYet(node, "apply with holes or spread (argument presence is not proven)")
			}
		}
	}
	prefix := []ir.Expression{}
	if alias, err := l.methodAliasRead(target); err != nil {
		return nil, true, err
	} else if alias != nil {
		prefix = append(prefix, alias)
	}
	if method.family == "global" || method.family == "Number" || method.family == "Math" || method.family == "Object" || method.family == "String" {
		if receiver != nil {
			value, err := l.expression(receiver)
			if err != nil {
				return nil, true, err
			}
			if value.Type() == 0 {
				value = fit(value, ir.Object)
			}
			if slotless(value.Type()) {
				return nil, true, l.notYet(receiver, "a delayed static call with this receiver representation")
			}
			prefix = append(prefix, value)
		}
	}
	var value ir.Expression
	var handled bool
	var err error
	switch method.family {
	case "Array.prototype":
		if receiver == nil {
			return nil, true, l.notYet(node, "an unbound Array method call (this is undefined); supply an array to call/apply")
		}
		if l.mayBeUndefined(receiver) {
			return nil, true, l.notYet(receiver, "an Array method receiver that may be undefined")
		}
		if of, _ := l.representation(l.checker.GetTypeAtLocation(receiver)); of != ir.Array {
			return nil, true, l.notYet(receiver, "an Array method receiver whose dense array representation is not proven")
		}
		switch method.name {
		case "indexOf", "includes", "lastIndexOf":
			value, handled, err = l.libraryArrayMethodArguments(node, receiver, method.name, written)
		case "slice", "join", "at", "push", "reverse", "concat", "fill", "splice":
			if ast.SkipParentheses(receiver).Kind == ast.KindNewExpression && method.name == "fill" {
				return nil, true, l.notYet(node, "delayed fill of an array with holes; write the direct filled construction")
			}
			value, handled, err = l.arrayMethodArguments(node, receiver, method.name, written)
		}
	case "String.prototype":
		if receiver == nil || l.mayBeUndefined(receiver) {
			return nil, true, l.notYet(node, "an unbound method read as a value without a proven present string receiver")
		}
		if of, _ := l.representation(l.checker.GetTypeAtLocation(receiver)); of != ir.String {
			return nil, true, l.notYet(receiver, "a String method receiver whose primitive string representation is not proven")
		}
		var text ir.Expression
		text, err = l.expression(receiver)
		if err == nil {
			value, handled, err = l.libraryStringMethod(node, text, method.name, written)
		}
	case "Number.prototype":
		value, err = l.delayedNumberMethod(node, receiver, method.name, written)
		handled = true
	case "Math":
		count, supported := mathFunctions[method.name]
		if !supported || count < 0 || len(written) != count {
			return nil, true, l.notYet(node, "a delayed Math call without a proven fixed argument count")
		}
		arguments := []ir.Expression{}
		for _, argument := range written {
			number, failure := l.expression(argument)
			if failure != nil {
				return nil, true, failure
			}
			if number.Type() != ir.Number {
				return nil, true, l.notYet(argument, "a delayed Math argument that is not a number")
			}
			arguments = append(arguments, number)
		}
		value, handled = ir.MathCall{Function: method.name, Arguments: arguments}, true
	case "String":
		if method.name == "fromCharCode" || method.name == "fromCodePoint" {
			value, handled, err = l.stringFromCodesArguments(node, method.name == "fromCodePoint", written)
		}
	case "Object.prototype":
		if receiver == nil {
			return nil, true, l.notYet(node, "an Object method without a proven receiver")
		}
		if method.name == "toString" {
			value, err = l.objectTagCall(node, receiver, written)
			handled = true
		} else if method.name == "hasOwnProperty" || method.name == "propertyIsEnumerable" || method.name == "isPrototypeOf" {
			value, handled, err = l.objectPrototypeCallArguments(node, receiver, method.name, written)
		}
	case "Number":
		value, handled, err = l.numberCallArguments(node, method.name, written)
	case "Object":
		if method.name == "freeze" || method.name == "assign" {
			return nil, true, l.notYet(node, "delayed Object mutation with an erased result shape; use a direct call")
		}
		value, handled, err = l.objectCallArguments(node, method.name, written)
	case "global":
		switch method.name {
		case "String":
			handled = true
			if len(written) == 1 {
				value, err = l.stringConversion(written[0])
			} else {
				err = l.notYet(node, "delayed String with other than one argument")
			}
		case "Number":
			handled = true
			if len(written) == 1 {
				value, err = l.libraryNumber(written[0])
			} else {
				err = l.notYet(node, "delayed Number with other than one argument")
			}
		case "parseInt", "parseFloat":
			value, handled, err = l.numberCallArguments(node, method.name, written)
		}
	}
	if !handled {
		return nil, true, l.notYet(node, "delayed "+method.family+"."+method.name+" (no adapter proves this receiver and argument ABI); use an arrow")
	}
	if err != nil {
		return nil, true, err
	}
	if contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone); contextual != nil {
		expected, proven := l.representation(contextual)
		if !proven || expected != value.Type() && expected != ir.Maybe(value.Type()) && !(expected == ir.Union && l.writable(contextual) && (value.Type() == ir.String || value.Type() == ir.Number || value.Type() == ir.Boolean || value.Type() == ir.MaybeNumber)) {
			return nil, true, l.notYet(node, "a delayed library result whose contextual representation is not proven")
		}
		if value.Type() == ir.Array && method.family == "Array.prototype" {
			from := l.checker.GetElementTypeOfArrayType(l.checker.GetTypeAtLocation(receiver))
			to := l.checker.GetElementTypeOfArrayType(contextual)
			if from == nil || to == nil || from != to || !l.sameKeeping(from, to, map[[2]*checker.Type]bool{}) {
				return nil, true, l.notYet(node, "a delayed Array result with an erased or different element type; preserve the receiver's exact element type")
			}
		}
	}
	if len(prefix) > 0 {
		if value.Type() == 0 || slotless(value.Type()) {
			return nil, true, l.notYet(node, "a delayed library call returning this representation")
		}
		value = l.methodSequence(append(prefix, value))
	}
	return value, true, nil
}

func (l *lowering) objectTagCall(node, receiver *ast.Node, written []*ast.Node) (ir.Expression, error) {
	if len(written) != 0 || l.mayBeUndefined(receiver) {
		return nil, l.notYet(node, "Object.prototype.toString with arguments or a possibly undefined receiver")
	}
	value, err := l.expression(receiver)
	if err != nil {
		return nil, err
	}
	tag := ""
	if _, null := value.(ir.Null); null {
		return l.methodSequence([]ir.Expression{value, ir.StringConstant{Index: l.constant("[object Null]")}}), nil
	}
	switch value.Type() {
	case ir.Number:
		tag = "Number"
	case ir.Boolean:
		tag = "Boolean"
	case ir.String:
		tag = "String"
	case ir.Array:
		tag = "Array"
	case ir.Map:
		if l.isSet(receiver) {
			tag = "Set"
		} else {
			tag = "Map"
		}
	case ir.Closure:
		tag = "Function"
	case ir.Object:
		if reason := l.prototypeHazard(receiver, "toString"); reason != "" {
			return nil, l.notYet(node, "Object.prototype.toString through a view ("+reason+")")
		}
		tag = "Object"
	default:
		return nil, l.notYet(node, "Object.prototype.toString on this representation")
	}
	return l.methodSequence([]ir.Expression{value, ir.StringConstant{Index: l.constant("[object " + tag + "]")}}), nil
}

func (l *lowering) libraryMapCallback(node, receiver *ast.Node, element ir.Type) (ir.Expression, bool, error) {
	method, known := l.libraryMethod(node, map[*ast.Symbol]bool{})
	if !known {
		return nil, false, nil
	}
	index := len(l.result.Functions)
	function := ir.Function{Name: "library_map_" + method.name, Closure: true}
	reads := []ir.Expression{}
	for _, of := range []ir.Type{element, ir.Number, ir.Array} {
		local := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: "argument", Type: of, Function: index})
		function.Parameters = append(function.Parameters, local)
		reads = append(reads, ir.Read{Local: local, Of: of})
	}
	// Reference-valued optional elements use NULL. String(undefined) is a real string, not an
	// absent result slot, so normalize presence before passing it to the intrinsic adapter.
	sourceElement := l.checker.GetElementTypeOfArrayType(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(receiver)))
	if element == ir.String && sourceElement != nil && l.includesUndefined(sourceElement) {
		reads[0] = ir.Coalesce{Value: reads[0], Fallback: ir.StringConstant{Index: l.constant("undefined")}, Of: ir.String}
	}
	var result ir.Expression
	if method.family == "global" && method.name == "String" {
		switch element {
		case ir.Number:
			result = ir.NumberToString{Value: reads[0]}
		case ir.Boolean:
			result = ir.BooleanToString{Value: reads[0]}
		case ir.String:
			result = reads[0]
		case ir.MaybeNumber:
			result = ir.MaybeToString{Value: reads[0]}
		}
	} else if (method.family == "Number" || method.family == "global") && (method.name == "parseInt" || method.name == "parseFloat") && element == ir.String {
		arguments := []ir.Expression{reads[0]}
		if method.name == "parseInt" {
			arguments = append(arguments, reads[1])
		}
		result = ir.NumberCall{Function: method.name, Arguments: arguments}
	}
	if result == nil {
		return nil, true, l.notYet(node, "a library map callback without a proven primitive adapter (map supplies value, index and array); use an arrow")
	}
	function.Returns = result.Type()
	function.Body = []ir.Statement{ir.Return{Value: result}}
	l.result.Functions = append(l.result.Functions, function)
	value := ir.Expression(ir.MakeClosure{Function: index})
	if alias, err := l.methodAliasRead(node); err != nil {
		return nil, true, err
	} else if alias != nil {
		value = l.methodSequence([]ir.Expression{alias, value})
	}
	return value, true, nil
}

// A bound primitive string cannot form a reference cycle. The ordinary captured parameter cell
// snapshots this once and outlives the factory call, rather than rereading a mutable source name.
func (l *lowering) libraryMethodBind(node, target *ast.Node, method libraryMethod) (ir.Expression, error) {
	written := node.AsCallExpression().Arguments.Nodes
	if method.family != "String.prototype" || len(written) != 1 || hasSpread(node) {
		return nil, l.notYet(node, "bind without a supported captured receiver and fixed argument ABI (only zero-argument String methods are lowered); use an arrow")
	}
	switch method.name {
	case "trim", "trimStart", "trimEnd", "toUpperCase", "toLowerCase", "toString", "valueOf":
	default:
		return nil, l.notYet(node, "bind of a method with optional, required or partial arguments (its argument adapter is not lowered); use an arrow")
	}
	receiver, err := l.expression(written[0])
	if err != nil {
		return nil, err
	}
	if receiver.Type() != ir.String || l.mayBeUndefined(written[0]) {
		return nil, l.notYet(node, "bind without a proven present primitive string receiver")
	}
	maker := len(l.result.Functions)
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "library_bind_factory", Returns: ir.Closure})
	captured := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "bound_receiver", Type: ir.String, Function: maker, Captured: true})
	closure := len(l.result.Functions)
	read := ir.Expression(ir.Read{Local: captured, Of: ir.String})
	result := read
	switch method.name {
	case "trim":
		result = ir.Trim{Value: read}
	case "toString", "valueOf":
	default:
		result = ir.StringCall{Method: method.name, Value: read}
	}
	l.result.Functions = append(l.result.Functions, ir.Function{Name: "library_bound_" + method.name, Closure: true, Environment: []int{captured}, Returns: ir.String, Body: []ir.Statement{ir.Return{Value: result}}})
	l.closureRecords = append(l.closureRecords, closureRecord{proven: l.concrete(l.checker.GetTypeAtLocation(node)), function: closure, node: node})
	l.result.Functions[maker].Parameters = []int{captured}
	l.result.Functions[maker].Body = []ir.Statement{ir.Return{Value: ir.MakeClosure{Function: closure}}}
	value := ir.Expression(ir.Call{Function: maker, Arguments: []ir.Expression{receiver}, Returns: ir.Closure})
	if alias, err := l.methodAliasRead(target); err != nil {
		return nil, err
	} else if alias != nil {
		value = l.methodSequence([]ir.Expression{alias, value})
	}
	return value, nil
}

func (l *lowering) delayedNumberMethod(node, receiver *ast.Node, name string, written []*ast.Node) (ir.Expression, error) {
	if receiver == nil {
		return nil, l.notYet(node, "an unbound Number method without a numeric receiver")
	}
	value, err := l.expression(receiver)
	if err != nil {
		return nil, err
	}
	if value.Type() != ir.Number {
		return nil, l.notYet(receiver, "a Number method receiver without a proven number internal slot")
	}
	if name == "valueOf" && len(written) == 0 {
		return value, nil
	}
	if name != "toString" && name != "toFixed" && name != "toExponential" && name != "toPrecision" {
		return nil, l.notYet(node, "this delayed Number prototype method")
	}
	if len(written) > 1 {
		return nil, l.notYet(node, "a delayed Number format with extra arguments")
	}
	var argument ir.Expression
	if len(written) == 1 {
		argument, err = l.expression(written[0])
		if err != nil {
			return nil, err
		}
		if _, missing := argument.(ir.Undefined); missing {
			argument = nil
		} else if argument.Type() != ir.Number {
			return nil, l.notYet(node, "a delayed Number format argument that is not a number")
		}
	}
	if name == "toFixed" {
		if argument == nil {
			argument = ir.NumberConstant{}
		}
		return ir.ToFixed{Value: value, Digits: argument}, nil
	}
	return ir.NumberFormat{Method: name, Value: value, Argument: argument}, nil
}

// [] has element type never. No invocation occurs, but the callback value is still read, including
// its temporal dead zone check; it is not replaced by an arbitrary guessed element conversion.
func (l *lowering) libraryEmptyMap(node *ast.Node) (ir.Expression, bool, error) {
	call := node.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	if callee.Kind != ast.KindPropertyAccessExpression || callee.Name().Text() != "map" || !l.libraryMember(callee) || len(call.Arguments.Nodes) != 1 {
		return nil, false, nil
	}
	receiver := ast.SkipParentheses(callee.AsPropertyAccessExpression().Expression)
	if receiver.Kind != ast.KindArrayLiteralExpression || len(receiver.AsArrayLiteralExpression().Elements.Nodes) != 0 {
		return nil, false, nil
	}
	method, known := l.libraryMethod(call.Arguments.Nodes[0], map[*ast.Symbol]bool{})
	if !known {
		return nil, false, nil
	}
	var element ir.Type
	if method.family == "global" && method.name == "String" {
		element = ir.String
	}
	if (method.family == "Number" || method.family == "global") && (method.name == "parseInt" || method.name == "parseFloat") {
		element = ir.Number
	}
	if element == 0 {
		return nil, true, l.notYet(node, "an empty map with an unsupported library callback value")
	}
	value := ir.Expression(ir.ArrayLiteral{Element: element})
	if alias, err := l.methodAliasRead(call.Arguments.Nodes[0]); err != nil {
		return nil, true, err
	} else if alias != nil {
		value = l.methodSequence([]ir.Expression{alias, value})
	}
	return value, true, nil
}

library_node.go:
package lower

import (
	"path"
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/load"
)

// Register only members with real lowering and runtime support. Host units add
// their names during init; the default is a named NotYet, never erased code.
var implementedNodeMembers = map[string]bool{"node:console.Console.log": true, "node:console.Console.error": true, "node:console.console": true}

func RegisterNodeLibraryMembers(names ...string) {
	for _, name := range names {
		implementedNodeMembers[name] = true
	}
}

func (l *lowering) nodeLibraryMember(node *ast.Node) string {
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindCallExpression {
		node = ast.SkipParentheses(node.AsCallExpression().Expression)
	}
	if node.Kind == ast.KindNewExpression {
		node = ast.SkipParentheses(node.AsNewExpression().Expression)
	}
	symbol := l.symbol(node)
	if symbol == nil {
		return ""
	}
	for _, declaration := range symbol.Declarations {
		file := ast.GetSourceFileOfNode(declaration)
		if !load.IsNodeLibrary(file) {
			continue
		}
		if declaration.Kind == ast.KindModuleDeclaration {
			return ""
		}
		module := ""
		owners := []string{}
		for parent := declaration.Parent; parent != nil; parent = parent.Parent {
			if (parent.Kind == ast.KindClassDeclaration || parent.Kind == ast.KindInterfaceDeclaration) && parent.Name() != nil {
				owners = append([]string{parent.Name().Text()}, owners...)
			}
			if parent.Kind == ast.KindModuleDeclaration && parent.Name() != nil && parent.Name().Kind == ast.KindStringLiteral {
				module = parent.Name().Text()
				break
			}
		}
		if module == "" {
			module = strings.TrimSuffix(path.Base(file.FileName().AsString()), ".d.ts")
		}
		if !strings.HasPrefix(module, "node:") {
			module = "node:" + module
		}
		return strings.Join(append([]string{module}, append(owners, symbol.Name)...), ".")
	}
	return ""
}

func (l *lowering) nodeLibraryRefusal(node *ast.Node) error {
	if !ast.IsExpressionNode(node) || ast.IsPartOfTypeNode(node) {
		return nil
	}
	name := l.nodeLibraryMember(node)
	if name != "" && !implementedNodeMembers[name] {
		return l.notYet(node, name)
	}
	return nil
}

library_node_buffer.go:
package lower

import (
	"math"
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// The shared loader supplies the pinned @types/node tree. Ambient modules in
// application files are not host declarations, even when their names match.
func nodeBufferModule(symbol *ast.Symbol) string {
	if symbol == nil {
		return ""
	}
	for _, declaration := range symbol.Declarations {
		source := ast.GetSourceFileOfNode(declaration)
		if source == nil || !strings.Contains(strings.ReplaceAll(source.FileName().AsString(), "\\", "/"), "/@types/node/") {
			continue
		}
		for parent := declaration; parent != nil; parent = parent.Parent {
			if parent.Kind == ast.KindModuleDeclaration && parent.Name() != nil && parent.Name().Kind == ast.KindStringLiteral {
				switch name := parent.Name().Text(); name {
				case "node:buffer", "node:crypto":
					return name
				}
			}
		}
	}
	return ""
}
func (l *lowering) nodeBufferSymbol(node *ast.Node, name string) bool {
	symbol := l.symbol(node)
	return symbol != nil && symbol.Name == name && nodeBufferModule(symbol) != ""
}
func (l *lowering) nodeBufferType(proven *checker.Type, name string) bool {
	if proven == nil {
		return false
	}
	symbol := proven.Symbol()
	return symbol != nil && symbol.Name == name && nodeBufferModule(symbol) != ""
}

// Reading a host member as a value must not fall through to ordinary object
// slots. Hash's private runtime layout is not its inherited stream layout.
func (l *lowering) nodeBufferUnsupportedUse(node *ast.Node) error {
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindPropertyAccessExpression {
		access := node.AsPropertyAccessExpression()
		name := node.Name().Text()
		receiver := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(access.Expression))
		switch {
		case l.nodeBufferSymbol(access.Expression, "Buffer"):
			return l.notYet(node, "Buffer."+name+" read as a value")
		case l.nodeBufferType(receiver, "Buffer"):
			if name != "length" {
				return l.notYet(node, "Buffer."+name+" outside the census value reads")
			}
		case l.nodeBufferType(receiver, "Hash"):
			return l.notYet(node, "Hash."+name+" outside the census value reads")
		}
	}
	if node.Kind == ast.KindElementAccessExpression {
		access := node.AsElementAccessExpression()
		member := ast.SkipParentheses(access.ArgumentExpression)
		receiver := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(access.Expression))
		if member.Kind == ast.KindStringLiteral {
			for _, name := range []string{"Buffer", "Hash"} {
				if l.nodeBufferType(receiver, name) || (name == "Buffer" && l.nodeBufferSymbol(access.Expression, name)) {
					return l.notYet(node, name+"."+member.Text()+" accessed through a string index")
				}
			}
		}
	}
	if node.Kind == ast.KindIdentifier || node.Kind == ast.KindPropertyAccessExpression || node.Kind == ast.KindElementAccessExpression {
		symbol := l.symbol(node)
		if module := nodeBufferModule(symbol); module != "" {
			if symbol.Name == "Buffer" && node.Parent != nil && node.Parent.Kind == ast.KindPropertyAccessExpression && node.Parent.Name().Text() == "from" && called(node.Parent) {
				return nil
			}
			return l.notYet(node, module+"."+symbol.Name+" read as a value")
		}
	}
	if node.Kind == ast.KindNewExpression {
		symbol := l.symbol(node.AsNewExpression().Expression)
		if module := nodeBufferModule(symbol); module != "" {
			return l.notYet(node, module+"."+symbol.Name+" outside the host census")
		}
	}
	return nil
}
func (l *lowering) nodeBufferReadArgument(node *ast.Node) bool {
	outer := node
	for outer.Parent != nil && outer.Parent.Kind == ast.KindParenthesizedExpression {
		outer = outer.Parent
	}
	parent := outer.Parent
	if parent == nil || parent.Kind != ast.KindCallExpression {
		return false
	}
	call := parent.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	return len(call.Arguments.Nodes) > 0 && call.Arguments.Nodes[0] == outer && callee.Kind == ast.KindPropertyAccessExpression && callee.Name().Text() == "from" && l.nodeBufferSymbol(callee.AsPropertyAccessExpression().Expression, "Buffer")
}
func (l *lowering) nodeBufferView(from, to *checker.Type) bool {
	for _, name := range []string{"Buffer", "Hash"} {
		if l.nodeBufferType(from, name) != l.nodeBufferType(to, name) {
			return false
		}
	}
	return true
}

func (l *lowering) nodeBufferEncoding(node *ast.Node, fallback int) (int, error) {
	if node == nil {
		return fallback, nil
	}
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindStringLiteral {
		switch node.Text() {
		case "utf8", "utf-8":
			return 0, nil
		case "utf16le", "utf-16le", "ucs2", "ucs-2":
			return 1, nil
		case "base64":
			return 2, nil
		case "hex":
			return 3, nil
		}
	}
	return 0, l.notYet(node, "a Buffer encoding other than a census literal")
}
func (l *lowering) libraryNodeBuffer(node *ast.Node) (ir.Expression, bool, error) {
	call := node.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	args := call.Arguments.Nodes
	operation, encoding, result := "", 0, ir.Array
	var receiver *ast.Node
	if l.nodeBufferSymbol(callee, "createHash") {
		if len(args) != 1 || ast.SkipParentheses(args[0]).Kind != ast.KindStringLiteral || args[0].Text() != "sha256" {
			return nil, true, l.notYet(node, "crypto.createHash outside the census's sha256 algorithm")
		}
		return ir.NodeBufferCall{Function: "hash_new", Returns: ir.Object}, true, nil
	}
	if callee.Kind != ast.KindPropertyAccessExpression {
		if symbol := l.symbol(callee); nodeBufferModule(symbol) != "" {
			return nil, true, l.notYet(node, nodeBufferModule(symbol)+"."+symbol.Name+" outside the host census")
		}
		return nil, false, nil
	}
	access := callee.AsPropertyAccessExpression()
	name := callee.Name().Text()
	switch {
	case l.nodeBufferSymbol(access.Expression, "Buffer"):
		if name != "from" || len(args) < 1 || len(args) > 2 {
			return nil, true, l.notYet(node, "Buffer."+name+" outside from(input, encoding)")
		}
		operation = "buffer_from"
	case l.nodeBufferType(l.checker.GetTypeAtLocation(access.Expression), "Buffer"):
		if name != "toString" || len(args) > 3 {
			return nil, true, l.notYet(node, "Buffer."+name+" outside the host census")
		}
		operation, result, receiver = "buffer_string", ir.String, access.Expression
	case l.nodeBufferType(l.checker.GetTypeAtLocation(access.Expression), "Hash"):
		receiver = access.Expression
		switch name {
		case "update":
			if len(args) < 1 || len(args) > 2 {
				return nil, true, l.notYet(node, "Hash.update with these arguments")
			}
			operation, result = "hash_update", ir.Object
		case "digest":
			if len(args) != 1 || args[0].Kind != ast.KindStringLiteral || args[0].Text() != "hex" {
				return nil, true, l.notYet(node, "Hash.digest outside hex")
			}
			operation, result, args = "hash_digest", ir.String, nil
		default:
			return nil, true, l.notYet(node, "Hash."+name+" outside the host census")
		}
	default:
		if symbol := l.symbol(callee); nodeBufferModule(symbol) != "" {
			return nil, true, l.notYet(node, nodeBufferModule(symbol)+"."+symbol.Name+" outside the host census")
		}
		return nil, false, nil
	}
	var encodingNode *ast.Node
	if operation == "buffer_string" {
		if len(args) > 0 {
			encodingNode = args[0]
		}
	} else if len(args) > 1 {
		encodingNode = args[1]
	}
	var err error
	if encoding, err = l.nodeBufferEncoding(encodingNode, 0); err != nil {
		return nil, true, err
	}
	values := []ir.Expression{}
	if receiver != nil {
		value, err := l.expression(receiver)
		if err != nil {
			return nil, true, err
		}
		values = append(values, value)
	}
	if operation == "buffer_string" {
		for index := 1; index <= 2; index++ {
			value := ir.Expression(ir.NumberConstant{Value: 0})
			if index == 2 {
				value = ir.NumberConstant{Value: math.Inf(1)}
			}
			if len(args) > index {
				value, err = l.expression(args[index])
				if err != nil {
					return nil, true, err
				}
				if value.Type() != ir.Number {
					return nil, true, l.notYet(args[index], "a non-number Buffer byte offset")
				}
			}
			values = append(values, value)
		}
	} else {
		if operation != "hash_digest" {
			value, err := l.expression(args[0])
			if err != nil {
				return nil, true, err
			}
			if operation == "buffer_from" && value.Type() == ir.Array {
				if len(args) != 1 {
					return nil, true, l.notYet(node, "Buffer.from(array) with an encoding")
				}
				element, err := l.elementType(args[0])
				if err != nil {
					return nil, true, err
				}
				if element != ir.Number {
					return nil, true, l.notYet(node, "Buffer.from with non-number elements")
				}
				operation = "buffer_copy"
			} else if value.Type() != ir.String {
				return nil, true, l.notYet(node, "Buffer or Hash input other than a string or numeric array")
			}
			values = append(values, value)
		}
	}
	return ir.NodeBufferCall{Function: operation, Arguments: values, Encoding: encoding, Returns: result}, true, nil
}

library_node_fs_buffer.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/load"
	"strings"
)

// The merged Buffer unit implements these members. Register them with the shared
// declaration guard so byte reads can be consumed by sys.ts's actual BOM decoder.
func init() {
	RegisterNodeLibraryMembers("node:buffer.Buffer", "node:buffer.BufferConstructor.from", "node:buffer.Buffer.toString",
		"node:crypto.createHash", "node:crypto.Hash.update", "node:crypto.Hash.digest")
}

// The readSync generic constraint is ArrayBufferView. Its proven Buffer argument
// is synchronously borrowed as bytes, never exposed as a different object view.
func (l *lowering) nodeFSFileBufferArgument(node *ast.Node) bool {
	outer := node
	for outer.Parent != nil && outer.Parent.Kind == ast.KindParenthesizedExpression {
		outer = outer.Parent
	}
	if outer.Parent == nil || outer.Parent.Kind != ast.KindCallExpression {
		return false
	}
	call := outer.Parent.AsCallExpression()
	if len(call.Arguments.Nodes) < 2 || call.Arguments.Nodes[1] != outer || !l.nodeBufferType(l.checker.GetTypeAtLocation(node), "Buffer") {
		return false
	}
	symbol := l.symbol(ast.SkipParentheses(call.Expression))
	if symbol == nil || (symbol.Name != "readSync" && symbol.Name != "writeFileSync") {
		return false
	}
	if symbol.Name == "readSync" && len(call.Arguments.Nodes) != 5 {
		return false
	}
	if symbol.Name == "writeFileSync" && len(call.Arguments.Nodes) > 3 {
		return false
	}
	for _, declaration := range symbol.Declarations {
		file := ast.GetSourceFileOfNode(declaration)
		if load.IsNodeLibrary(file) && strings.HasSuffix(file.FileName().AsString(), "/fs.d.ts") {
			return true
		}
	}
	return false
}

library_node_fs_file.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
)

// Recognize declarations, including aliased imports, rather than user spellings.
func (l *lowering) nodeFSFile(node *ast.Node) (ir.Expression, bool, error) {
	call := node.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	symbol := l.symbol(callee)
	if symbol == nil || len(symbol.Declarations) == 0 {
		return nil, false, nil
	}
	declaration := symbol.Declarations[0]
	memberName := symbol.Name
	source := ast.GetSourceFileOfNode(declaration)
	if callee.Kind == ast.KindPropertyAccessExpression {
		receiver := callee.AsPropertyAccessExpression().Expression
		if l.isLibraryType(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(receiver)), "Date") {
			if symbol.Name != "getTime" && symbol.Name != "valueOf" {
				return nil, true, l.notYet(node, memberName+": "+"Date methods other than getTime/valueOf in the fs file host")
			}
			if len(call.Arguments.Nodes) != 0 {
				return nil, true, l.notYet(node, memberName+": "+"Date getTime/valueOf with arguments")
			}
			value, err := l.expression(receiver)
			return ir.NodeFSFile{Operation: "date_time", Arguments: []ir.Expression{value}, Of: ir.Number}, true, err
		}
	}
	if !load.IsNodeLibrary(source) {
		return nil, false, nil
	}
	parent := declaration.Parent
	for parent != nil && parent.Kind != ast.KindModuleDeclaration {
		parent = parent.Parent
	}
	if parent == nil || (parent.Name().Text() != "node:fs" && parent.Name().Text() != "fs") {
		return nil, false, nil
	}
	args := []ir.Expression{}
	operation := ""
	of := ir.Number // Void calls are only admitted as discarded statements.
	switch symbol.Name {
	case "isFile", "isDirectory", "isSymbolicLink":
		if declaration.Parent == nil || declaration.Parent.Name() == nil || declaration.Parent.Name().Text() != "StatsBase" {
			return nil, false, nil
		}
		if callee.Kind != ast.KindPropertyAccessExpression || len(call.Arguments.Nodes) != 0 {
			return nil, true, l.notYet(node, memberName+": "+"a detached Stats method")
		}
		receiver, err := l.expression(callee.AsPropertyAccessExpression().Expression)
		if err != nil {
			return nil, true, err
		}
		operation = map[string]string{"isFile": "is_file", "isDirectory": "is_directory", "isSymbolicLink": "is_symbolic_link"}[symbol.Name]
		return ir.NodeFSFile{Operation: operation, Arguments: []ir.Expression{receiver}, Of: ir.Boolean}, true, nil
	case "readFileSync":
		operation, of = "read_file", ir.String
	case "mkdtempSync":
		operation, of = "mkdtemp", ir.String
	case "rmSync":
		operation = "rm"
	case "openSync":
		operation = "open"
	case "readSync":
		if len(call.Arguments.Nodes) != 5 || !l.nodeBufferType(l.checker.GetTypeAtLocation(call.Arguments.Nodes[1]), "Buffer") {
			return nil, true, l.notYet(node, "node:fs.readSync outside the five-argument Buffer overload")
		}
		operation = "read_sync"
	case "writeSync":
		operation = "write"
	case "closeSync":
		operation = "close"
	case "writeFileSync":
		operation = "write_file"
	case "existsSync":
		operation, of = "exists", ir.Boolean
	case "statSync":
		operation, of = "stat", ir.Object
	case "mkdirSync":
		operation, of = "mkdir", ir.String
	case "unlinkSync":
		operation = "unlink"
	case "utimesSync":
		operation = "utimes"
	default:
		return nil, false, nil
	}
	switch operation {
	case "close", "write_file", "unlink", "utimes", "rm":
		outer := node
		for outer.Parent != nil && outer.Parent.Kind == ast.KindParenthesizedExpression {
			outer = outer.Parent
		}
		discarded := outer.Parent != nil && outer.Parent.Kind == ast.KindExpressionStatement
		returned := outer.Parent != nil && outer.Parent.Kind == ast.KindReturnStatement && l.function != nil && l.function.Returns == 0
		if !discarded && !returned {
			return nil, true, l.notYet(node, memberName+": "+"fs void calls used as values")
		}
	}
	for _, argument := range call.Arguments.Nodes {
		value, err := l.expression(argument)
		if err != nil {
			if missing, ok := err.(*NotYet); ok {
				err = l.notYet(node, "node:fs."+memberName+": "+missing.What)
			}
			return nil, true, err
		}
		args = append(args, value)
	}
	// Lower only the proven shapes implemented by this host. Broader declared
	// Node overloads produce NotYet rather than reaching C with a wrong type.
	constant := func(s string) ir.Expression { return ir.StringConstant{Index: l.constant(s)} }
	number := func(n float64) ir.Expression { return ir.NumberConstant{Value: n} }
	option := func(value ir.Expression, name string, fallback ir.Expression) (ir.Expression, error) {
		literal, ok := value.(ir.ObjectLiteral)
		if !ok {
			read, reading := value.(ir.Read)
			if reading {
				for _, argument := range call.Arguments.Nodes {
					if !ast.IsIdentifier(ast.SkipParentheses(argument)) || !(l.exactObject(argument, 0) || l.nodeFSDirectoryStatOptions(argument)) {
						continue
					}
					symbol := l.symbol(ast.SkipParentheses(argument))
					if local, found := l.locals[symbol]; !found || local != read.Local {
						continue
					}
					field := l.checker.GetPropertyOfType(l.checker.GetTypeAtLocation(argument), name)
					if field == nil {
						return fallback, nil
					}
					of, known := l.representation(l.checker.GetTypeOfSymbol(field))
					if !known || of != fallback.Type() || field.Flags&ast.SymbolFlagsOptional != 0 || name == "bigint" || name == "encoding" {
						return nil, l.notYet(node, memberName+": "+"fs options with optional fields, dynamic encoding or bigint")
					}
					return ir.Property{Object: value, Name: name, Of: of}, nil
				}
			}
			return nil, l.notYet(node, memberName+": "+"fs options other than a fixed literal or its plain const binding")
		}
		if literal.Spread != nil {
			return nil, l.notYet(node, memberName+": "+"fs options containing a spread")
		}
		// Splitting a literal into runtime parameters must neither drop effects
		// from unused fields nor reorder the effects of its fields.
		literalValue := func(value ir.Expression) ir.Expression {
			// Nullable option context may box a constant under the union ABI.
			// Only constants are effect-free; every other box keeps the effects refusal.
			if boxed, ok := value.(ir.Box); ok {
				switch boxed.Value.(type) {
				case ir.NumberConstant, ir.BooleanConstant, ir.StringConstant, ir.Undefined, ir.Null:
					return boxed.Value
				}
			}
			if optional, ok := value.(ir.MaybeOf); ok {
				if optional.Value == nil {
					return ir.Undefined{}
				}
				return optional.Value
			}
			return value
		}
		for _, field := range literal.Fields {
			switch literalValue(field.Value).(type) {
			case ir.NumberConstant, ir.BooleanConstant, ir.StringConstant, ir.Undefined, ir.Null:
			default:
				return nil, l.notYet(node, memberName+": "+"fs option literals containing evaluated expressions; bind a plain options object first")
			}
		}
		for _, field := range literal.Fields {
			if field.Name == name {
				value := literalValue(field.Value)
				if _, absent := value.(ir.Undefined); absent {
					return fallback, nil
				}
				return value, nil
			}
		}
		return fallback, nil
	}
	encoding := func(value ir.Expression) error {
		if _, ok := value.(ir.Undefined); ok {
			return nil
		}
		if _, ok := value.(ir.Null); ok {
			return nil
		}
		if text, ok := value.(ir.StringConstant); ok && (l.result.Strings[text.Index] == "utf8" || l.result.Strings[text.Index] == "utf-8") {
			return nil
		}
		return l.notYet(node, memberName+": "+"fs encodings other than constant utf8/utf-8")
	}
	var err error
	switch operation {
	case "mkdtemp":
		if len(args) > 1 {
			enc := args[1]
			if enc.Type() == ir.Object {
				enc, err = option(enc, "encoding", constant("utf8"))
				if err != nil {
					return nil, true, err
				}
			}
			if err = encoding(enc); err != nil {
				return nil, true, err
			}
		}
		if l.checker.GetTypeAtLocation(node).Flags()&checker.TypeFlagsStringLike == 0 {
			return nil, true, l.notYet(node, "node:fs.mkdtempSync outside the string UTF8 result")
		}
		args = args[:1]
	case "rm":
		recursive, force := ir.Expression(ir.BooleanConstant{Value: false}), ir.Expression(ir.BooleanConstant{Value: false})
		if len(args) > 1 {
			recursive, err = option(args[1], "recursive", recursive)
			if err != nil {
				return nil, true, err
			}
			force, err = option(args[1], "force", force)
			if err != nil {
				return nil, true, err
			}
			for _, name := range []string{"maxRetries", "retryDelay"} {
				fallback := number(0)
				if name == "retryDelay" {
					fallback = number(100)
				}
				value, e := option(args[1], name, fallback)
				if e != nil {
					return nil, true, e
				}
				if n, ok := value.(ir.NumberConstant); !ok || n.Value != fallback.(ir.NumberConstant).Value {
					return nil, true, l.notYet(node, "node:fs.rmSync retry options outside the driver defaults")
				}
