		}
		if _, ok := args[2].(ir.Null); ok {
			args[2] = number(438)
		}
		if _, ok := args[2].(ir.Undefined); ok {
			args[2] = number(438)
		}
		if args[2].Type() != ir.Number {
			return nil, true, l.notYet(node, memberName+": "+"fs mode other than a number")
		}
	case "read_sync":
