			}
		}
		args = []ir.Expression{args[0], args[1], flag, mode, flush}
	case "stat":
		throws := ir.Expression(ir.BooleanConstant{Value: true})
		if len(args) > 1 {
			throws, err = option(args[1], "throwIfNoEntry", throws)
			if err != nil {
				return nil, true, err
			}
			bigint, e := option(args[1], "bigint", ir.BooleanConstant{Value: false})
			if e != nil {
				return nil, true, e
			}
			if b, ok := bigint.(ir.BooleanConstant); !ok || b.Value {
				return nil, true, l.notYet(node, memberName+": "+"bigint fs Stats")
			}
		}
		args = []ir.Expression{args[0], throws}
	case "mkdir":
		recursive, mode := ir.Expression(ir.BooleanConstant{Value: false}), number(511)
		if len(args) > 1 {
			value := args[1]
			if _, null := value.(ir.Null); !null {
				if value.Type() == ir.Number {
					mode = value
				} else {
					recursive, err = option(value, "recursive", recursive)
					if err != nil {
						return nil, true, err
					}
					mode, err = option(value, "mode", mode)
					if err != nil {
						return nil, true, err
					}
				}
			}
		}
		args = []ir.Expression{args[0], recursive, mode}
	case "utimes":
		if args[1].Type() == ir.Object && args[2].Type() == ir.Object {
			operation = "utimes_dates"
		} else if args[1].Type() == ir.Object {
			operation = "utimes_atime_date"
		} else if args[2].Type() == ir.Object {
			operation = "utimes_mtime_date"
		}

	}
	// Separate descriptor operations preserve Node's ownership of caller fds.
	if operation == "read_file" && args[0].Type() == ir.Number {
		operation = "read_fd"
	}
	if operation == "read_buffer" && args[0].Type() == ir.Number {
		operation = "read_buffer_fd"
	}
	if operation == "write_buffer" && args[0].Type() == ir.Number {
		operation = "write_buffer_fd"
	}
	if operation == "write_file" && args[0].Type() == ir.Number {
		operation = "write_fd"
	}
	types := map[string][]ir.Type{
		"write_buffer": {ir.String, ir.Array, ir.String, ir.Number, ir.Boolean}, "write_buffer_fd": {ir.Number, ir.Array, ir.String, ir.Number, ir.Boolean},
		"read_sync": {ir.Number, ir.Array, ir.Number, ir.Number, ir.Number}, "read_buffer": {ir.String, ir.String}, "read_buffer_fd": {ir.Number, ir.String},
		"read_file": {ir.String, ir.String}, "read_fd": {ir.Number, ir.String}, "open": {ir.String, ir.String, ir.Number},
		"write": {ir.Number, ir.String, ir.Number}, "close": {ir.Number}, "write_file": {ir.String, ir.String, ir.String, ir.Number, ir.Boolean}, "write_fd": {ir.Number, ir.String, ir.String, ir.Number, ir.Boolean},
		"utimes_dates": {ir.String, ir.Object, ir.Object}, "utimes_atime_date": {ir.String, ir.Object, ir.Number}, "utimes_mtime_date": {ir.String, ir.Number, ir.Object},
		"mkdtemp": {ir.String}, "rm": {ir.String, ir.Boolean, ir.Boolean}, "exists": {ir.String}, "stat": {ir.String, ir.Boolean}, "mkdir": {ir.String, ir.Boolean, ir.Number}, "unlink": {ir.String}, "utimes": {ir.String, ir.Number, ir.Number},
	}
	for i, t := range types[operation] {
		if args[i].Type() != t {
			return nil, true, l.notYet(node, memberName+": "+"fs arguments outside the implemented host signatures")
		}
	}
	return ir.NodeFSFile{Operation: operation, Arguments: args, Of: of}, true, nil
}

func (l *lowering) nodeFSFileDate(node *ast.Node) (ir.Expression, bool, error) {
	created := node.AsNewExpression()
	if !l.isLibraryGlobal(created.Expression, "Date") {
		return nil, false, nil
	}
	if created.Arguments == nil || len(created.Arguments.Nodes) != 1 {
		return nil, true, l.notYet(node, "Date construction other than a numeric timestamp in the fs file host")
	}
	value, err := l.expression(created.Arguments.Nodes[0])
	if err != nil {
		return nil, true, err
	}
	if value.Type() != ir.Number {
		return nil, true, l.notYet(node, "Date construction other than a numeric timestamp in the fs file host")
	}
	return ir.NodeFSFile{Operation: "date_new", Arguments: []ir.Expression{value}, Of: ir.Object}, true, nil
}

// These native intrinsics inspect options synchronously and never write or
// retain them. Borrowing here does not authorize a wider mutable assignment.
func (l *lowering) nodeFSFileReadOnlyArgument(node *ast.Node) bool {
	outer := node
	for outer.Parent != nil && outer.Parent.Kind == ast.KindParenthesizedExpression {
		outer = outer.Parent
	}
	if outer.Parent == nil || outer.Parent.Kind != ast.KindCallExpression {
		return false
	}
	call := outer.Parent.AsCallExpression()
	symbol := l.symbol(ast.SkipParentheses(call.Expression))
	if symbol == nil || len(symbol.Declarations) == 0 {
		return false
	}
	declaration := symbol.Declarations[0]
	if !load.IsNodeLibrary(ast.GetSourceFileOfNode(declaration)) {
		return false
	}
	parent := declaration.Parent
	for parent != nil && parent.Kind != ast.KindModuleDeclaration {
		parent = parent.Parent
	}
	if parent == nil || (parent.Name().Text() != "node:fs" && parent.Name().Text() != "fs") {
		return false
	}
	index := 1
	switch symbol.Name {
	case "statSync", "mkdirSync", "readFileSync", "rmSync", "mkdtempSync":
	case "writeFileSync":
		index = 2
	default:
		return false
	}
	return len(call.Arguments.Nodes) > index && call.Arguments.Nodes[index] == outer
}

func init() {
	RegisterNodeLibraryMembers("node:fs.mkdtempSync", "node:fs.rmSync", "node:fs.readSync", "node:fs.readFileSync", "node:fs.openSync", "node:fs.writeSync", "node:fs.closeSync", "node:fs.writeFileSync", "node:fs.existsSync", "node:fs.statSync", "node:fs.mkdirSync", "node:fs.unlinkSync", "node:fs.utimesSync", "node:fs.StatsBase.isFile", "node:fs.StatsBase.isDirectory", "node:fs.StatsBase.isSymbolicLink", "node:fs.StatsBase.size", "node:fs.StatsBase.mtime", "node:fs.StatsBase.atime", "node:fs.StatsBase.mtimeMs", "node:globals.ErrnoException.code")
}

library_node_fs_file_options.go:
package lower

import "github.com/microsoft/TypeScript/tsc/shim/ast"

// sys.ts binds its fixed stat options with as const. This proves the same exact
// object layout as a plain literal, without permitting annotations or other casts.
func (l *lowering) nodeFSDirectoryStatOptions(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if !ast.IsIdentifier(node) {
		return false
	}
	symbol := l.symbol(node)
	if symbol == nil || len(symbol.Declarations) != 1 {
		return false
	}
	declaration := symbol.Declarations[0]
	if declaration.Kind != ast.KindVariableDeclaration || declaration.Parent == nil || declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
		return false
	}
	variable := declaration.AsVariableDeclaration()
	if variable.Type != nil || variable.Initializer == nil {
		return false
	}
	initializer := ast.SkipParentheses(variable.Initializer)
	if initializer.Kind != ast.KindAsExpression {
		return false
	}
	as := initializer.AsAsExpression()
	return as.Type.Kind == ast.KindTypeReference && ast.IsIdentifier(as.Type.AsTypeReferenceNode().TypeName) &&
		as.Type.AsTypeReferenceNode().TypeName.Text() == "const" && l.exactObject(as.Expression, 0)
}

library_node_host.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// This host slice recognizes library declarations, including import aliases.
// It borrows only strings and does not expose a mutable process object.
func (l *lowering) nodeHost(node *ast.Node) (ir.Expression, bool, error) {
	name := l.nodeLibraryMember(node)
	operation, of := "", ir.String
	switch name {
	case "node:path.join":
		operation = "host_join"
	case "node:os.tmpdir":
		operation = "host_tmpdir"
	case "node:process.Process.cwd", "node:process.cwd":
		operation = "host_cwd"
	case "node:process.Process.chdir", "node:process.chdir":
		operation, of = "host_chdir", ir.Number
	default:
		return nil, false, nil
	}
	call := node.AsCallExpression()
	if operation != "host_join" && len(call.Arguments.Nodes) != map[string]int{"host_tmpdir": 0, "host_cwd": 0, "host_chdir": 1}[operation] {
		return nil, true, l.notYet(node, name+" outside the implemented host signature")
	}
	if operation == "host_chdir" {
		outer := node
		for outer.Parent != nil && outer.Parent.Kind == ast.KindParenthesizedExpression {
			outer = outer.Parent
		}
		discarded := outer.Parent != nil && outer.Parent.Kind == ast.KindExpressionStatement
		returned := outer.Parent != nil && outer.Parent.Kind == ast.KindReturnStatement && l.function != nil && l.function.Returns == 0
		if !discarded && !returned {
			return nil, true, l.notYet(node, name+" used as a value")
		}
	}
	args := []ir.Expression{}
	for _, argument := range call.Arguments.Nodes {
		if argument.Kind == ast.KindSpreadElement {
			return nil, true, l.notYet(argument, name+" with spread arguments")
		}
		value, err := l.expression(argument)
		if err != nil {
			return nil, true, err
		}
		if value.Type() != ir.String {
			return nil, true, l.notYet(argument, name+" with non-string arguments")
		}
		args = append(args, value)
	}
	return ir.NodeFSFile{Operation: operation, Arguments: args, Of: of}, true, nil
}

func init() {
	RegisterNodeLibraryMembers("node:path.join", "node:os.tmpdir", "node:process.Process.cwd", "node:process.Process.chdir", "node:process.cwd", "node:process.chdir", "node:process.process", "node:globals.process")
}

library_object.go:
package lower

import (
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

func (l *lowering) objectCall(node *ast.Node, name string) (ir.Expression, bool, error) {
	return l.objectCallArguments(node, name, node.AsCallExpression().Arguments.Nodes)
}

func (l *lowering) objectCallArguments(node *ast.Node, name string, written []*ast.Node) (ir.Expression, bool, error) {
	refused := func(reason string) (ir.Expression, bool, error) {
		return nil, true, &Refused{Where: l.program.Where(node), What: "Object." + name, Fix: reason}
	}
	switch name {
	case "defineProperty", "defineProperties", "getOwnPropertyDescriptor", "getOwnPropertyDescriptors":
		return refused("property descriptors can change the presence, type or access behavior of fields; Adamic fields have a fixed shape and are plain loads and stores")
	case "getPrototypeOf", "setPrototypeOf", "create":
		return refused("prototypes expose or replace fields outside the declared shape; use a declared object or class with composition")
	case "fromEntries":
		return refused("tsc returns an index-signature object with unproven keys; Adamic fixes object shapes and refuses index signatures; use Map")
	case "groupBy":
		return nil, true, l.notYet(node, "Object.groupBy's partial record with dynamically present keys (use Map and an explicitly typed grouping loop)")
	}
	count := 1
	if name == "is" || name == "hasOwn" {
		count = 2
	}
	if name == "assign" {
		if len(written) < 1 {
			return nil, true, l.notYet(node, "Object.assign without a target")
		}
	} else if len(written) != count {
		return nil, true, l.notYet(node, "Object."+name+" with these arguments")
	}
	if name == "freeze" {
		proven := l.checker.GetTypeAtLocation(written[0])
		if proven.Flags()&(checker.TypeFlagsNumberLike|checker.TypeFlagsBooleanLike|checker.TypeFlagsStringLike|checker.TypeFlagsUndefined) != 0 {
			value, err := l.expression(written[0])
			return value, true, err
		}
	}
	call := ir.ObjectCall{Method: name, Returns: ir.Boolean}
	switch name {
	case "is":
		for _, argument := range written {
			value, err := l.expression(argument)
			if err != nil {
				return nil, true, err
			}
			call.Arguments = append(call.Arguments, fit(value, ir.Union))
		}
	case "isFrozen":
		value, err := l.expression(written[0])
		if err != nil {
			return nil, true, err
		}
		call.Arguments = []ir.Expression{fit(value, ir.Union)}
	case "keys", "values", "entries", "freeze", "hasOwn", "assign":
		// Assignment and freezing retain their existing exact-shape requirement.
		// A plain const's literal initializer proves the complete shape, including field presence.
		shape := ast.SkipParentheses(written[0])
		if shape.Kind == ast.KindAsExpression {
			assertion := shape.AsAsExpression()
			if assertion.Type.Kind == ast.KindTypeReference && assertion.Type.AsTypeReferenceNode().TypeName.Text() == "const" {
				shape = ast.SkipParentheses(assertion.Expression)
			}
		}
		if name == "keys" || name == "values" || name == "entries" {
			if err := l.enumerationDescriptors(node, false); err != nil {
				return nil, true, err
			}
		}
		if name != "keys" && name != "values" && name != "entries" && !l.exactObject(shape, 0) && !(name == "hasOwn" && isClassInstance(l.checker.GetTypeAtLocation(written[0]))) {
			return nil, true, l.notYet(written[0], "Object."+name+" on a shape not proven by a plain literal or its const binding")
		}
		value, err := l.expression(written[0])
		if err != nil {
			return nil, true, err
		}
		if value.Type() != ir.Object || l.includesUndefined(l.checker.GetTypeAtLocation(written[0])) || checker.IsTupleType(l.checker.GetTypeAtLocation(written[0])) {
			return nil, true, l.notYet(written[0], "Object."+name+" on other than a present plain object")
		}
		call.Arguments = []ir.Expression{value}
		switch name {
		case "hasOwn":
			key := ast.SkipParentheses(written[1])
			if key.Kind != ast.KindStringLiteral || !l.hasProperty(written[0], key.Text()) || len(key.Text()) > 0 && key.Text()[0] == '#' {
				return refused("hasOwn requires a string literal naming a declared public field or method; use Map for arbitrary keys")
			}
			keyValue, err := l.expression(key)
			if err != nil {
				return nil, true, err
			}
			call.Arguments = append(call.Arguments, keyValue)
		case "freeze":
			call.Returns = ir.Object
		case "keys":
			call.Returns = ir.Array
		case "values", "entries":
			result := l.checker.GetTypeAtLocation(node)
			// The interface overload may return any. Its destination supplies the
			// contract we must prove or check, never permission to erase it.
			if contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone); contextual != nil && l.checker.IsArrayType(contextual) {
				result = contextual
			}
			arguments := l.checker.GetTypeArguments(result)
			if len(arguments) != 1 {
				return refused("tsc's result must be an array with a proven element type")
			}
			element := arguments[0]
			if name == "entries" {
				pair := l.checker.GetTypeArguments(element)
				if len(pair) != 2 {
					return refused("tsc's entries must have a proven value type")
				}
				element = pair[1]
			}
			call.Element, _ = l.representation(element)
			if call.Element != ir.Number && call.Element != ir.String && call.Element != ir.Boolean {
				return refused("tsc's result must have one homogeneous number, string or boolean value type; any and widened field views are unsound")
			}
			if declaration := l.enumObject(written[0]); declaration != nil {
				fields, err := l.enumFields(declaration)
				if err != nil {
					return nil, true, err
				}
				for _, field := range fields {
					if field.Value.Type() != call.Element {
						return refused("numeric enum reverse mappings add string values; use Object.keys or read members individually")
					}
				}
			}
			for _, field := range l.checker.GetPropertiesOfType(l.checker.GetTypeAtLocation(written[0])) {
				of, known := l.representation(l.checker.GetTypeOfSymbol(field))
				if !known || of != call.Element || field.Flags&ast.SymbolFlagsOptional != 0 {
					return refused("every present field must have tsc's result element representation; optional or heterogeneous fields cannot be read soundly")
				}
			}
			call.Checked = !l.enumerationProven(written[0], element, 0)
			call.ElementName = l.checker.TypeToString(element)
			call.Allowed = l.viewLiterals(element)
			if l.openNumericEnumType(element) {
				call.Allowed = nil
			}
			if call.Checked && !interfaceScalar(element) {
				return nil, true, l.notYet(node, "checked Object enumeration of a non-primitive value contract")
			}
			if call.Checked {
				if err := l.enumerationDescriptors(node, true); err != nil {
					return nil, true, err
				}
			}
			call.Returns = ir.Array
		case "assign":
			if l.checker.GetTypeAtLocation(node).Flags()&(checker.TypeFlagsAny|checker.TypeFlagsUnknown) != 0 {
				return refused("tsc's result is any or unknown, not a proven object type; use one to three typed sources")
			}
			target := l.checker.GetTypeAtLocation(written[0])
			for _, argument := range written[1:] {
				if !l.exactObject(argument, 0) {
					return refused("each source must have its complete shape proven by a literal or const binding; a widened source can hide overwriting fields")
				}
				source := l.checker.GetTypeAtLocation(argument)
				for _, field := range l.checker.GetPropertiesOfType(source) {
					into := l.checker.GetPropertyOfType(target, field.Name)
					if into == nil {
						return nil, true, l.notYet(argument, "Object.assign adding a field to its target's fixed shape")
					}
					fromType, toType := l.checker.GetTypeOfSymbol(field), l.checker.GetTypeOfSymbol(into)
					of, known := l.representation(fromType)
					if !known || (of != ir.Number && of != ir.Boolean && of != ir.String) || !l.enumAssignable(fromType, toType) || !l.enumAssignable(toType, fromType) || !l.checker.IsTypeAssignableTo(fromType, toType) || !l.checker.IsTypeAssignableTo(toType, fromType) {
						return refused("source and target field types must agree in both directions with tsc's intersection result; widening, conflicting fields and reference cycles are refused")
					}
				}
				lowered, err := l.expression(argument)
				if err != nil {
					return nil, true, err
				}
				call.Arguments = append(call.Arguments, lowered)
			}
			call.Returns = ir.Object
		}
	default:
		return nil, true, l.notYet(node, "Object."+name)
	}
	return call, true, nil
}

// exactObject proves there are no hidden fields and no synthetic absent slots. An explicit type
// annotation, alias, spread or call would need a separate proof and is deliberately not guessed.
func (l *lowering) exactObject(node *ast.Node, depth int) bool {
	if depth > 16 {
		return false
	}
	node = ast.SkipParentheses(node)
	if l.enumObject(node) != nil {
		return true
	}
	if node.Kind == ast.KindObjectLiteralExpression {
		for _, field := range node.AsObjectLiteralExpression().Properties.Nodes {
			if field.Kind != ast.KindPropertyAssignment && field.Kind != ast.KindShorthandPropertyAssignment {
				return false
			}
			if field.Name().Kind != ast.KindIdentifier && field.Name().Kind != ast.KindStringLiteral {
				return false
			}
			if strings.ContainsRune(field.Name().Text(), 0) || field.Name().Text() == "__proto__" || len(field.Name().Text()) > 0 && field.Name().Text()[0] == '#' {
				return false
			}
		}
		return true
	}
	if !ast.IsIdentifier(node) {
		return false
	}
	symbol := l.symbol(node)
	if symbol == nil || len(symbol.Declarations) != 1 {
		return false
	}
	declaration := symbol.Declarations[0]
	if declaration.Kind != ast.KindVariableDeclaration {
		return false
	}
	variable := declaration.AsVariableDeclaration()
	if variable.Type != nil || variable.Initializer == nil || declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
		return false
	}
	return l.exactObject(variable.Initializer, depth+1)
}

// objectCanFreeze is conservative across aliases and calls. A try around a write in a program
// that freezes objects is NotYet until library TypeErrors participate in exception cleanup.
func (l *lowering) objectCanFreeze() bool {
	found := false
	walk(l.result.Main, func(node any) bool {
		if call, ok := node.(ir.ObjectCall); ok && call.Method == "freeze" {
			found = true
		}
		return !found
	})
	for _, function := range l.result.Functions {
		walk(function.Body, func(node any) bool {
			if call, ok := node.(ir.ObjectCall); ok && call.Method == "freeze" {
				found = true
			}
			return !found
		})
	}
	return found
}

// objectIntersection represents tsc's intersection of plain object views. Every constituent must
// be a plain, noncallable shape, and every resulting field must have a proven scalar type.
func (l *lowering) objectIntersection(proven *checker.Type) (ir.Type, bool) {
	for _, part := range proven.Types() {
		if part.Flags()&checker.TypeFlagsObject == 0 || l.checker.IsArrayType(part) || checker.IsTupleType(part) || isClassInstance(part) || len(l.checker.GetSignaturesOfType(part, checker.SignatureKindCall)) != 0 {
			return 0, false
		}
	}
	for _, field := range l.checker.GetPropertiesOfType(proven) {
		of, known := l.representation(l.checker.GetTypeOfSymbol(field))
		if !known || (of != ir.Number && of != ir.String && of != ir.Boolean) {
			return 0, false
		}
	}
	return ir.Object, true
}

library_regex_callback_shape.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	regex "github.com/system-inc/adamic/internal/regexp"
	"strings"
)

// Offset and input follow every capture. Prove zero captures from immutable producers,
// rather than assuming the callback's declared parameter types describe the regex.
func (l *lowering) regexCallbackNoCaptures(node *ast.Node, depth int) bool {
	if depth > 32 {
		return false
	}
	node = ast.SkipParentheses(node)
	pattern, flags := "", ""
	switch node.Kind {
	case ast.KindRegularExpressionLiteral:
		text := node.Text()
		end := strings.LastIndex(text, "/")
		if end <= 0 {
			return false
		}
		pattern, flags = text[1:end], text[end+1:]
	case ast.KindIdentifier:
		symbol := l.symbol(node)
		if symbol == nil || len(symbol.Declarations) != 1 {
			return false
		}
		declaration := symbol.Declarations[0]
		if declaration.Kind != ast.KindVariableDeclaration || declaration.Parent.Flags&ast.NodeFlagsConst == 0 || declaration.AsVariableDeclaration().Initializer == nil {
			return false
		}
		return l.regexCallbackNoCaptures(declaration.AsVariableDeclaration().Initializer, depth+1)
	case ast.KindConditionalExpression:
		conditional := node.AsConditionalExpression()
		return l.regexCallbackNoCaptures(conditional.WhenTrue, depth+1) && l.regexCallbackNoCaptures(conditional.WhenFalse, depth+1)
	default:
		return false
	}
	parsed, err := regex.Parse(pattern, flags)
	if err != nil {
		return false
	}
	var present func(regex.Node) bool
	present = func(node regex.Node) bool {
		switch n := node.(type) {
		case *regex.Disjunction:
			for _, alternative := range n.Alternatives {
				for _, term := range alternative.Terms {
					if !present(term) {
						return false
					}
				}
			}
		case *regex.Group:
			return n.Kind != regex.Capturing && present(n.Body)
		case *regex.Quantifier:
			return present(n.Atom)
		}
		return true
	}
	return present(parsed.Body)
}

// The intrinsic supplies a proven argument sequence, rather than lib.d.ts's any[] rest.
// This exemption applies only at the replacement argument, never to a stored function view.
func (l *lowering) regexCallbackIntrinsicView(node *ast.Node) bool {
	child := node
	for child.Parent != nil && child.Parent.Kind == ast.KindParenthesizedExpression {
		child = child.Parent
	}
	if child.Parent == nil || child.Parent.Kind != ast.KindCallExpression {
		return false
	}
	call := child.Parent.AsCallExpression()
	if call.Arguments == nil || len(call.Arguments.Nodes) != 2 || call.Arguments.Nodes[1] != child {
		return false
	}
	callee := ast.SkipParentheses(call.Expression)
	if callee.Kind != ast.KindPropertyAccessExpression {
		return false
	}
	access := callee.AsPropertyAccessExpression()
	if access.Name().Text() != "replace" && access.Name().Text() != "replaceAll" {
		return false
	}
	if l.checker.GetTypeAtLocation(access.Expression).Flags()&checker.TypeFlagsStringLike == 0 || !l.libraryMember(callee) {
		return false
	}
	if !l.isLibraryType(l.checker.GetTypeAtLocation(call.Arguments.Nodes[0]), "RegExp") || !l.regexCallbackNoCaptures(call.Arguments.Nodes[0], 0) {
		return false
	}
	signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(node), checker.SignatureKindCall)
	if len(signatures) != 1 || len(signatures[0].Parameters()) < 2 || len(signatures[0].Parameters()) > 3 {
		return false
	}
	expected := []checker.TypeFlags{checker.TypeFlagsString, checker.TypeFlagsNumber, checker.TypeFlagsString}
	for i, parameter := range signatures[0].Parameters() {
		if l.checker.GetTypeOfSymbol(parameter).Flags() != expected[i] {
			return false
		}
	}
	return l.checker.GetReturnTypeOfSignature(signatures[0]).Flags() == checker.TypeFlagsString
}

library_regexp_replace.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

func (l *lowering) regexReplacement(node *ast.Node, input ir.Expression, arguments []ir.Expression, method string, written *ast.Node) (ir.Expression, bool, error) {
	signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(written), checker.SignatureKindCall)
	if len(signatures) != 1 {
		return nil, true, l.notYet(written, "RegExp replacement with multiple callback signatures")
	}
	signature := signatures[0]
	returned := l.checker.GetReturnTypeOfSignature(signature)
	result, known := l.representation(returned)
	if returned.Flags()&checker.TypeFlagsUndefined != 0 {
		result, known = ir.String, true
	}
	if returned.Flags()&checker.TypeFlagsNull != 0 {
		result, known = ir.Object, true
	}
	if returned.Flags()&(checker.TypeFlagsVoid|checker.TypeFlagsNever) != 0 {
		result, known = 0, true
	}
	if !known || result != 0 && result != ir.String && result != ir.Number && result != ir.Boolean && result != ir.Union && !(result == ir.Object && returned.Flags()&checker.TypeFlagsNull != 0) {
		return nil, true, l.notYet(written, "RegExp replacement callback return conversion")
	}
	if result == ir.Union && !l.writable(l.checker.GetReturnTypeOfSignature(signature)) {
		return nil, true, l.notYet(written, "RegExp replacement callback ToPrimitive")
	}
	replacement := &ir.RegExpReplacement{Returns: result}
	for argument, parameter := range signature.Parameters() {
		proven := l.checker.GetTypeOfSymbol(parameter)
		rest := len(parameter.Declarations) == 1 && parameter.Declarations[0].Kind == ast.KindParameter && parameter.Declarations[0].AsParameterDeclaration().DotDotDotToken != nil
		if rest {
			proven = l.checker.GetElementTypeOfArrayType(proven)
		}
		of, known := l.representation(proven)
		if !known || of != ir.String && of != ir.Number && of != ir.Object && of != ir.Union {
			return nil, true, l.notYet(written, "RegExp replacement callback argument representation")
		}
		for _, member := range l.definedMembers(proven) {
			represented, _ := l.representation(member)
			if represented != ir.Object {
				continue
			}
			for _, field := range l.checker.GetPropertiesOfType(member) {
				fieldType := l.checker.GetTypeOfSymbol(field)
				if l.withoutUndefined(fieldType).Flags()&checker.TypeFlagsString == 0 {
					return nil, true, l.notYet(written, "RegExp replacement named-group field other than string or undefined")
				}
				replacement.Groups = append(replacement.Groups, ir.RegExpReplacementGroup{Argument: argument, Rest: rest, Name: field.Name, Optional: l.includesUndefined(fieldType)})
			}
		}
		kind := l.regexReplacementKind(proven, of)
		if rest {
			replacement.RestKind = kind
			replacement.Rest = of
		} else {
			replacement.Parameters = append(replacement.Parameters, of)
			replacement.Kinds = append(replacement.Kinds, kind)
		}
	}
	return ir.RegExpCall{Value: input, Arguments: arguments, Method: method, Returns: ir.String, Replacement: replacement}, true, nil
}

// The intrinsic does not call through lib.d.ts's any[] signature: its adapter checks actual
// argument kinds before entering the typed closure, including dynamic capture counts.
func (l *lowering) regexReplacementArgument(node *ast.Node) bool {
	outer := node
	for outer.Parent != nil && outer.Parent.Kind == ast.KindParenthesizedExpression {
		outer = outer.Parent
	}
	parent := outer.Parent
	if parent == nil || parent.Kind != ast.KindCallExpression {
		return false
	}
	call := parent.AsCallExpression()
	if len(call.Arguments.Nodes) != 2 || call.Arguments.Nodes[1] != outer {
		return false
	}
	callee := ast.SkipParentheses(call.Expression)
	if callee.Kind != ast.KindPropertyAccessExpression {
		return false
	}
	name := callee.Name().Text()
	receiver, known := l.representation(l.checker.GetTypeAtLocation(callee.AsPropertyAccessExpression().Expression))
	return known && receiver == ir.String && (name == "replace" || name == "replaceAll") && l.isLibraryType(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(call.Arguments.Nodes[0])), "RegExp") && len(l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(node), checker.SignatureKindCall)) == 1
}

// A union argument has a box and a mask of the actual kinds its declared type admits.
func (l *lowering) regexReplacementKind(proven *checker.Type, of ir.Type) int {
	kind := map[ir.Type]int{ir.String: 1, ir.Number: 2, ir.Object: 3}[of]
	if of == ir.Union {
		kind = 64
		for _, member := range l.definedMembers(proven) {
			represented, known := l.representation(member)
			if known {
				switch represented {
				case ir.String:
					kind |= 2
				case ir.Number:
					kind |= 4
				case ir.Object:
					kind |= 8
				}
			}
		}
		if l.includesUndefined(proven) {
			kind |= 1
		}
	} else if l.includesUndefined(proven) {
		kind |= 16
	}
	return kind
}

library_string.go:
package lower

import (
	"math"
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/microsoft/TypeScript/tsc/shim/scanner"
	"github.com/system-inc/adamic/internal/ir"
)

// stringPrototypeMethod recognizes the intrinsic, never a same-named local object.
func (l *lowering) stringPrototypeMethod(node *ast.Node) (string, bool) {
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindPropertyAccessExpression {
		return "", false
	}
	prototype := ast.SkipParentheses(node.AsPropertyAccessExpression().Expression)
	if prototype.Kind != ast.KindPropertyAccessExpression || prototype.Name().Text() != "prototype" || !l.isLibraryGlobal(prototype.AsPropertyAccessExpression().Expression, "String") {
		return "", false
	}
	return node.Name().Text(), true
}

// A typeof observation doesn't detach or call a method. An immediate intrinsic .call supplies this
// explicitly. Neither is the unbound-method hole, and every other method read stays refused.
func (l *lowering) stringMethodObservation(node *ast.Node) bool {
	_, intrinsic := l.stringPrototypeMethod(node)
	if !intrinsic {
		access := node.AsPropertyAccessExpression()
		intrinsic = l.isLibraryGlobal(access.Expression, "String")
	}
	if !intrinsic {
		return false
	}
	if len(l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(node), checker.SignatureKindCall)) == 0 {
		return false
	}
	outer := node
	for outer.Parent != nil && outer.Parent.Kind == ast.KindParenthesizedExpression {
		outer = outer.Parent
	}
	if outer.Parent != nil && outer.Parent.Kind == ast.KindTaggedTemplateExpression && outer.Parent.AsTaggedTemplateExpression().Tag == outer {
		return node.Name().Text() == "raw" && l.isLibraryGlobal(node.AsPropertyAccessExpression().Expression, "String")
	}
	if outer.Parent != nil && outer.Parent.Kind == ast.KindTypeOfExpression {
		return true
	}
	if _, prototype := l.stringPrototypeMethod(node); !prototype {
		return false
	}
	return outer.Parent != nil && outer.Parent.Kind == ast.KindPropertyAccessExpression && outer.Parent.Name().Text() == "call" && called(outer.Parent)
}

func (l *lowering) stringTypeOf(node *ast.Node) (ir.Expression, bool) {
	operand := ast.SkipParentheses(node.AsTypeOfExpression().Expression)
	if l.isLibraryGlobal(operand, "String") {
		return ir.StringConstant{Index: l.constant("function")}, true
	}
	if operand.Kind == ast.KindPropertyAccessExpression && l.stringMethodObservation(operand) {
		return ir.StringConstant{Index: l.constant("function")}, true
	}
	return nil, false
}

func (l *lowering) stringConversion(node *ast.Node) (ir.Expression, error) {
	if ast.SkipParentheses(node).Kind == ast.KindNullKeyword {
		return ir.StringConstant{Index: l.constant("null")}, nil
	}
	value, err := l.expression(node)
	if err != nil {
		return nil, err
	}
	if l.checker.GetTypeAtLocation(node).Flags()&(checker.TypeFlagsVoid|checker.TypeFlagsUndefined) != 0 {
		return ir.Effects{Body: []ir.Statement{ir.Evaluate{Value: value}}, Result: ir.StringConstant{Index: l.constant("undefined")}}, nil
	}
	switch value.Type() {
	case ir.Number:
		return ir.NumberToString{Value: value}, nil
	case ir.Boolean:
		return ir.BooleanToString{Value: value}, nil
	case ir.MaybeNumber, ir.MaybeBoolean:
		return ir.MaybeToString{Value: value}, nil
	case ir.String:
		return l.spelled(node, value), nil
	case ir.Union:
		if l.writable(l.checker.GetTypeAtLocation(node)) || l.dynamicScalarProperty(node) {
			return ir.UnionToString{Value: value}, nil
		}
	}
	if _, missing := value.(ir.Undefined); missing {
		return ir.StringConstant{Index: l.constant("undefined")}, nil
	}
	return nil, l.notYet(node, "String conversion of an object, array, map or function (ToPrimitive is not lowered)")
}

func (l *lowering) libraryString(node *ast.Node) (ir.Expression, bool, error) {
	callee := ast.SkipParentheses(node.AsCallExpression().Expression)
	written := node.AsCallExpression().Arguments.Nodes
	if l.isLibraryGlobal(callee, "String") {
		if len(written) == 0 {
			return ir.StringConstant{Index: l.constant("")}, true, nil
		}
		if len(written) != 1 {
			return nil, true, l.notYet(node, "String with spread or extra arguments")
		}
		value, err := l.stringConversion(written[0])
		return value, true, err
	}
	if callee.Kind != ast.KindPropertyAccessExpression {
		return nil, false, nil
	}
	receiver, name := callee.AsPropertyAccessExpression().Expression, callee.Name().Text()
	if l.isLibraryGlobal(receiver, "String") && name == "raw" {
		value, err := l.stringRaw(node, written)
		return value, true, err
	}
	if name == "call" {
		if method, intrinsic := l.stringPrototypeMethod(receiver); intrinsic {
			if len(written) == 0 {
				return nil, true, l.notYet(node, "String.prototype."+method+".call without a present receiver")
			}
			proven := l.checker.GetTypeAtLocation(written[0])
			if l.mayBeUndefined(written[0]) || proven.Flags()&checker.TypeFlagsNull != 0 {
				return nil, true, l.notYet(node, "String prototype call on null or undefined (its TypeError is not catchable natively yet)")
			}
			if method == "toString" || method == "valueOf" {
				if proven.Flags()&checker.TypeFlagsStringLike == 0 {
					return nil, true, l.notYet(node, "String.prototype."+method+" on a non-string receiver (requires a String internal slot)")
				}
			}
			value, err := l.stringConversion(written[0])
			if err != nil {
				return nil, true, err
			}
			return l.libraryStringMethod(node, value, method, written[1:])
		}
	}
	if of, _ := l.representation(l.checker.GetTypeAtLocation(receiver)); of == ir.String {
		switch name {
		case "charAt", "substring", "substr", "concat", "toString", "valueOf":
			value, err := l.expression(receiver)
			if err != nil {
				return nil, true, err
			}
			return l.libraryStringMethod(node, value, name, written)
		case "localeCompare":
			return nil, true, l.notYet(node, "localeCompare (Node uses locale collation, not ordinal UTF-16 order)")
		}
	}
	return nil, false, nil
}

func (l *lowering) libraryStringMethod(node *ast.Node, value ir.Expression, name string, written []*ast.Node) (ir.Expression, bool, error) {
	if name == "substr" {
		result, err := l.stringSubstr(node, value, written)
		return result, true, err
	}
	if name == "toString" || name == "valueOf" {
		if len(written) != 0 {
			return nil, true, l.notYet(node, name+" with arguments")
		}
		return value, true, nil
	}
	if name == "concat" {
		parts := []ir.Expression{value}
		for _, arg := range written {
			part, err := l.stringConversion(arg)
			if err != nil {
				return nil, true, err
			}
			parts = append(parts, part)
		}
		return ir.Concat{Parts: parts}, true, nil
	}
	shape, known := stringMethods[name]
	if name == "trim" {
		shape.arguments = nil
		shape.optional = 0
		known = true
	}
	if name == "charCodeAt" || name == "charAt" {
		shape.arguments = []ir.Type{ir.Number}
		shape.optional = 1
		known = true
	}
	if name == "substring" {
		shape.arguments = []ir.Type{ir.Number, ir.Number}
		shape.optional = 2
		known = true
	}
	if name == "lastIndexOf" {
		shape.arguments = []ir.Type{ir.String, ir.Number}
		shape.optional = 1
		known = true
	}
	if !known {
		return nil, true, l.notYet(node, "String.prototype."+name+" (no sound lowering for this method yet)")
	}
	if len(written) > len(shape.arguments) || len(written) < len(shape.arguments)-shape.optional {
		return nil, true, l.notYet(node, name+" with these arguments")
	}
	arguments := []ir.Expression{}
	for index, arg := range written {
		lowered, err := l.expression(arg)
		if err != nil {
			return nil, true, err
		}
		if fallback, optional := optionalStrings[name][index]; optional {
			lowered = l.orDefault(arg, lowered, fallback)
		}
		if (name == "slice" || name == "substring" || name == "lastIndexOf") && shape.arguments[index] == ir.Number {
			fallback := ir.NumberConstant{Value: 0}
			if index == 1 {
				fallback.Value = math.Inf(1)
			}
			if _, absent := lowered.(ir.Undefined); absent {
				lowered = fallback
			}
			if lowered.Type() == ir.MaybeNumber {
				lowered = ir.Coalesce{Value: lowered, Fallback: fallback, Of: ir.Number}
			}
		}
		if lowered.Type() != shape.arguments[index] {
			return nil, true, l.notYet(arg, "a "+typeName(lowered.Type())+" argument to "+name)
		}
		arguments = append(arguments, lowered)
	}
	switch name {
	case "lastIndexOf":
		if len(arguments) == 2 {
			// A prefix ending after a complete candidate restricts starts, including the empty search.
			// Bind all operands before reading lengths so effectful receiver and arguments run once.
			b := l.libraryArrayBuilder([]ir.Expression{value, arguments[0], arguments[1]})
			text, search, position := b.read(b.parameters[0]), b.read(b.parameters[1]), b.read(b.parameters[2])
			integer := ir.Conditional{Condition: ir.NumberCall{Function: "isNaN", Arguments: []ir.Expression{position}}, WhenTrue: ir.NumberConstant{Value: math.Inf(1)}, WhenNot: ir.MathCall{Function: "trunc", Arguments: []ir.Expression{position}}}
			start := ir.MathCall{Function: "min", Arguments: []ir.Expression{ir.StringLength{Value: text}, ir.MathCall{Function: "max", Arguments: []ir.Expression{integer, ir.NumberConstant{Value: 0}}}}}
			end := ir.Binary{Operator: ir.Add, Left: start, Right: ir.StringLength{Value: search}}
			prefix := ir.StringCall{Value: text, Method: "slice", Arguments: []ir.Expression{ir.NumberConstant{Value: 0}, end}}
			return b.finish("string_last_index_of_position", ir.StringCall{Value: prefix, Method: "lastIndexOf", Arguments: []ir.Expression{search}}), true, nil
		}
	case "trim":
		return ir.Trim{Value: value}, true, nil
	case "charCodeAt":
		position := ir.Expression(ir.NumberConstant{Value: 0})
		if len(arguments) > 0 {
			position = arguments[0]
		}
		return ir.CharCodeAt{Value: value, Index: position}, true, nil
	case "charAt", "substring":
		return l.stringIndexMethod(value, name, arguments), true, nil
	case "codePointAt":
		if len(arguments) == 0 {
			arguments = append(arguments, ir.NumberConstant{Value: 0})
		}
	case "normalize":
		if len(arguments) == 0 {
			arguments = append(arguments, ir.StringConstant{Index: l.constant("NFC")})
		}
	case "padStart", "padEnd":
		if len(arguments) == 1 {
			arguments = append(arguments, ir.StringConstant{Index: l.constant(" ")})
		}
	}
	return ir.StringCall{Method: name, Value: value, Arguments: arguments}, true, nil
}

// Helpers use the ordinary IR so both backends and ownership analyses see every evaluation. Each
// operand is passed once, before the helper reads it more than once.
func (l *lowering) stringHelper(name string, values []ir.Expression) (int, []ir.Expression) {
	index := len(l.result.Functions)
	function := ir.Function{Name: "library_string_" + name, Returns: ir.String}
	reads := []ir.Expression{}
	for _, value := range values {
		local := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: "argument", Type: value.Type(), Function: index})
		function.Parameters = append(function.Parameters, local)
		reads = append(reads, ir.Read{Local: local, Of: value.Type()})
	}
	l.result.Functions = append(l.result.Functions, function)
	return index, reads
}

func stringInteger(value ir.Expression) ir.Expression {
	return ir.Conditional{Condition: ir.NumberCall{Function: "isNaN", Arguments: []ir.Expression{value}}, WhenTrue: ir.NumberConstant{Value: 0}, WhenNot: ir.MathCall{Function: "trunc", Arguments: []ir.Expression{value}}}
}

func (l *lowering) stringIndexMethod(value ir.Expression, name string, arguments []ir.Expression) ir.Expression {
	values := append([]ir.Expression{value}, arguments...)
	function, reads := l.stringHelper(name, values)
	position := ir.Expression(ir.NumberConstant{Value: 0})
	if len(reads) > 1 {
		position = stringInteger(reads[1])
	}
	var result ir.Expression
	if name == "charAt" {
		result = ir.Coalesce{Value: ir.StringIndex{Value: reads[0], Index: position}, Fallback: ir.StringConstant{Index: l.constant("")}, Of: ir.String}
	} else {
		length := ir.StringLength{Value: reads[0]}
		clamp := func(index ir.Expression) ir.Expression {
			return ir.MathCall{Function: "min", Arguments: []ir.Expression{ir.MathCall{Function: "max", Arguments: []ir.Expression{index, ir.NumberConstant{Value: 0}}}, length}}
		}
		start := clamp(position)
		end := ir.Expression(length)
		if len(reads) > 2 {
			end = clamp(stringInteger(reads[2]))
		}
		result = ir.StringCall{Method: "slice", Value: reads[0], Arguments: []ir.Expression{ir.MathCall{Function: "min", Arguments: []ir.Expression{start, end}}, ir.MathCall{Function: "max", Arguments: []ir.Expression{start, end}}}}
	}
	l.result.Functions[function].Body = []ir.Statement{ir.Return{Value: result}}
	return ir.Call{Function: function, Arguments: values, Returns: ir.String}
}

// String.raw's supported shape has a present raw string array. Index signatures, holes, getters
// and user ToPrimitive methods remain refused. Reading raw occurs after all call arguments, as in JS.
func (l *lowering) stringRaw(node *ast.Node, written []*ast.Node) (ir.Expression, error) {
	if len(written) == 0 {
		return nil, l.notYet(node, "String.raw without a template")
	}
	rawType := l.checker.GetTypeOfPropertyOfType(l.checker.GetTypeAtLocation(written[0]), "raw")
	if rawType == nil || !l.checker.IsArrayType(rawType) || l.includesUndefined(rawType) {
		return nil, l.notYet(node, "String.raw without a present array of strings in raw")
	}
	element := l.checker.GetElementTypeOfArrayType(rawType)
	if element.Flags()&checker.TypeFlagsStringLike == 0 {
		return nil, l.notYet(node, "String.raw with raw elements that are not strings")
	}
	template, err := l.expression(written[0])
	if err != nil {
		return nil, err
	}
	if template.Type() != ir.Object {
		return nil, l.notYet(node, "String.raw with a template that is not an object")
	}
	values := []ir.Expression{template}
	for _, arg := range written[1:] {
		value, err := l.stringConversion(arg)
		if err != nil {
			return nil, err
		}
		values = append(values, value)
	}
	function, reads := l.stringHelper("raw", values)
	local := func(name string, of ir.Type) int {
		index := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: name, Type: of, Function: function})
		return index
	}
	raw, index, text := local("raw", ir.Array), local("index", ir.Number), local("text", ir.String)
	readRaw := ir.Read{Local: raw, Of: ir.Array}
	readIndex := ir.Read{Local: index, Of: ir.Number}
	readText := ir.Read{Local: text, Of: ir.String}
	next := ir.Binary{Operator: ir.Add, Left: readIndex, Right: ir.NumberConstant{Value: 1}}
	length := ir.Length{Array: readRaw}
	body := []ir.Statement{ir.Assign{Local: text, Value: ir.Concat{Parts: []ir.Expression{readText, ir.Coalesce{Value: ir.ArrayIndex{Array: readRaw, Index: readIndex, Element: ir.String}, Fallback: ir.StringConstant{Index: l.constant("undefined")}, Of: ir.String}}}}}
	for sub, value := range reads[1:] {
		body = append(body, ir.If{Condition: ir.Binary{Operator: ir.And, Left: ir.Binary{Operator: ir.Equal, Left: readIndex, Right: ir.NumberConstant{Value: float64(sub)}}, Right: ir.Binary{Operator: ir.Less, Left: next, Right: length}}, Then: []ir.Statement{ir.Assign{Local: text, Value: ir.Concat{Parts: []ir.Expression{readText, value}}}}})
	}
	l.result.Functions[function].Body = []ir.Statement{
		ir.Declare{Local: raw, Value: ir.Property{Object: reads[0], Name: "raw", Of: ir.Array}},
		ir.Declare{Local: index, Value: ir.NumberConstant{Value: 0}}, ir.Declare{Local: text, Value: ir.StringConstant{Index: l.constant("")}},
		ir.Loop{Condition: ir.Binary{Operator: ir.Less, Left: readIndex, Right: length}, Body: body, Update: []ir.Statement{ir.Assign{Local: index, Value: next}}}, ir.Return{Value: readText},
	}
	return ir.Call{Function: function, Arguments: values, Returns: ir.String}, nil
}

// The raw intrinsic only reads its template. Its bundled declaration exposes a mutable raw field,
// but passing the template here cannot write through that wider view. This exemption is confined
// to the intrinsic's first argument; storing the same value through that view still refuses.
func (l *lowering) stringReadOnlyArgument(node *ast.Node) bool {
	outer := node
	for outer.Parent != nil && outer.Parent.Kind == ast.KindParenthesizedExpression {
		outer = outer.Parent
	}
	parent := outer.Parent
	if parent == nil || parent.Kind != ast.KindCallExpression {
		return false
	}
	call := parent.AsCallExpression()
	if len(call.Arguments.Nodes) == 0 || call.Arguments.Nodes[0] != outer {
		return false
	}
	callee := ast.SkipParentheses(call.Expression)
	return callee.Kind == ast.KindPropertyAccessExpression && callee.Name().Text() == "raw" && l.isLibraryGlobal(callee.AsPropertyAccessExpression().Expression, "String")
}

func (l *lowering) refuseStringWidening(node *ast.Node) error {
	if l.stringReadOnlyArgument(node) || l.regexReplacementArgument(node) {
		return nil
	}
	return l.refuseWidening(node)
}

// String.raw as a tag uses the source's raw template text, including invalid cooked escapes.
// ECMAScript normalizes CR and CRLF to LF even in the raw parts.
func (l *lowering) stringRawTemplate(node *ast.Node) (ir.Expression, error) {
	tagged := node.AsTaggedTemplateExpression()
	tag := ast.SkipParentheses(tagged.Tag)
	if tagged.QuestionDotToken != nil || tag.Kind != ast.KindPropertyAccessExpression || tag.Name().Text() != "raw" || !l.isLibraryGlobal(tag.AsPropertyAccessExpression().Expression, "String") {
		return nil, l.notYet(node, "a tagged template other than the intrinsic String.raw")
	}
	raw := func(text string) ir.Expression {
		text = strings.ReplaceAll(strings.ReplaceAll(text, "\r\n", "\n"), "\r", "\n")
		return ir.StringConstant{Index: l.constant(text)}
	}
	template := tagged.Template
	if template.Kind == ast.KindNoSubstitutionTemplateLiteral {
		source := ast.GetSourceFileOfNode(template)
		start := scanner.GetTokenPosOfNode(template, source, false)
		return raw(source.Text()[start+1 : template.End()-1]), nil
	}
	parts := []ir.Expression{raw(template.AsTemplateExpression().Head.RawText())}
	for _, span := range template.AsTemplateExpression().TemplateSpans.Nodes {
		substitution, err := l.stringConversion(span.AsTemplateSpan().Expression)
		if err != nil {
			return nil, err
		}
		parts = append(parts, substitution, raw(span.AsTemplateSpan().Literal.RawText()))
	}
	return ir.Concat{Parts: parts}, nil
}

literal_callable_branch.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
)

// A literal boolean chooses a callable initializer without evaluating the other
// branch. In particular, a dead Date.now value needs no native clock intrinsic.
func (l *lowering) literalCallableBranch(node *ast.Node) *ast.Node {
	if node.Kind != ast.KindConditionalExpression || len(l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(node), checker.SignatureKindCall)) == 0 {
		return nil
	}
	expression := node.AsConditionalExpression()
	switch ast.SkipParentheses(expression.Condition).Kind {
	case ast.KindTrueKeyword:
		return expression.WhenTrue
	case ast.KindFalseKeyword:
		return expression.WhenFalse
	}
	return nil
}

load_time_reads.go:
package lower

import (
	"fmt"
	"sync"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/microsoft/TypeScript/tsc/shim/compiler"
	"github.com/system-inc/cohere/rule_runner"
)

const loadTimeReadRule = "nexus/correctness-no-import-cycle-load-time-read"

type Finding = rule_runner.Finding

type ruleRunner interface {
	RunRule(*compiler.Program, *checker.Checker, []*ast.SourceFile, string) ([]Finding, error)
}
type cohereRuleRunner struct{}

func (cohereRuleRunner) RunRule(program *compiler.Program, typeChecker *checker.Checker, files []*ast.SourceFile, name string) ([]Finding, error) {
	return rule_runner.RunRule(program, typeChecker, files, name)
}

var loadTimeReadRunner ruleRunner = cohereRuleRunner{}
var loadTimeReadLock sync.Mutex

// The rule inventories hazardous cycle reads, but a finding does not reject the
// program. The actual entry's ESM order can prove the provider finished; every
// remaining global read keeps the existing runtime dead-zone check.
func (l *lowering) loadTimeReads(files []*ast.SourceFile) error {
	loadTimeReadLock.Lock()
	defer loadTimeReadLock.Unlock()
	findings, err := loadTimeReadRunner.RunRule(l.program.CompilerProgram(), l.checker, files, loadTimeReadRule)
	if err != nil {
		return fmt.Errorf("lower: import-cycle rule: %w", err)
	}
	l.cycleReadFindings = findings
	l.proveModuleReads(files)
	return nil
}

func (l *lowering) proveModuleReads(files []*ast.SourceFile) {
	l.provenModuleReads = map[*ast.Node]bool{}
	positions := map[*ast.SourceFile]int{}
	for index, file := range files {
		positions[file] = index
	}
	for _, file := range files {
		var visit func(*ast.Node) bool
		visit = func(node *ast.Node) bool {
			if node == nil || ast.IsFunctionLike(node) {
				return false
			}
			switch node.Kind {
			case ast.KindImportDeclaration, ast.KindExportDeclaration:
				return false
			case ast.KindHeritageClause:
				if node.AsHeritageClause().Token == ast.KindExtendsKeyword && ast.IsClassLike(node.Parent) {
					for _, element := range node.AsHeritageClause().Types.Nodes {
						visit(element.AsExpressionWithTypeArguments().Expression)
					}
				}
				return false
			case ast.KindExpressionWithTypeArguments:
				visit(node.AsExpressionWithTypeArguments().Expression)
				return false
			case ast.KindPropertyDeclaration:
				if !ast.HasStaticModifier(node) {
					return false
				}
			}
			if ast.IsTypeNode(node) {
				return false
			}
			if ast.IsIdentifier(node) || ast.IsPropertyAccessExpression(node) {
				symbol := l.checker.GetSymbolAtLocation(node)
				if ast.IsIdentifier(node) && node.Parent != nil && ast.IsShorthandPropertyAssignment(node.Parent) {
					symbol = l.checker.GetShorthandAssignmentValueSymbol(node.Parent)
				}
				if symbol != nil {
					symbol = l.checker.SkipAlias(symbol)
					if symbol != nil && symbol.ValueDeclaration != nil {
						declaration := symbol.ValueDeclaration
						provider := ast.GetSourceFileOfNode(declaration)
						index, present := positions[provider]
						if (declaration.Kind == ast.KindFunctionDeclaration && declaration.Parent != nil && declaration.Parent.Kind == ast.KindSourceFile) || (present && provider != file && index < positions[file]) {
							l.provenModuleReads[node] = true
						}
					}
				}
			}
			node.ForEachChild(visit)
			return false
		}
		visit(file.AsNode())
	}
}

func (l *lowering) checkedModuleRead(node *ast.Node, local int) bool {
	return !l.provenModuleReads[node] && l.checked(local)
}

locals.go:
// Functions and declarations moved unchanged from lower.go.
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"slices"
)

// variables lowers const and let declarations, each to a local of its own.
func (l *lowering) variables(list *ast.Node) ([]ir.Statement, error) {
	if list.Flags&ast.NodeFlagsBlockScoped == 0 && !assertionVarList(list) && !namespaceVariable(list) {
		return nil, &Refused{Where: l.program.Where(list), What: "var", Fix: "use const or let"}
	}
	statements := []ir.Statement{}
	for _, declaration := range list.AsVariableDeclarationList().Declarations.Nodes {
		name := declaration.Name()
		if name.Kind == ast.KindArrayBindingPattern || name.Kind == ast.KindObjectBindingPattern {
			// const [a, b] = tuple, and const { x, y } = object (collections.go).
			destructured, err := l.destructure(name, declaration.AsVariableDeclaration().Initializer)
			if err != nil {
				return nil, err
			}
			for index, statement := range destructured {
				if declared, ok := statement.(ir.Declare); ok && l.result.Locals[declared.Local].NamespaceVar {
					destructured[index] = ir.Assign{Local: declared.Local, Value: declared.Value}
				}
			}
			statements = append(statements, destructured...)
			continue
		}
		if !ast.IsIdentifier(name) {
			return nil, l.notYet(name, "a destructuring declaration")
		}

		if list.Flags&ast.NodeFlagsBlockScoped == 0 && !namespaceVariable(list) {
			if symbol := l.symbol(name); symbol != nil && len(symbol.Declarations) > 1 {
				return nil, &Refused{Where: l.program.Where(declaration), What: "repeated var assertion declarations", Fix: "use one declaration and subsequent assignments"}
			}
		}
		local, err := l.declareLocal(name)
		if err != nil {
			return nil, err
		}
		if list.Flags&ast.NodeFlagsBlockScoped == 0 {
			l.result.Locals[local].Hoisted = true
		}
		if l.result.Locals[local].NamespaceVar && declaration.Initializer() == nil {
			continue // Hoisted storage must not overwrite an earlier assignment.
		}
		if l.uninitializedDeclaration(declaration) {
			l.result.Locals[local].Uninitialized = true
			statements = append(statements, ir.Declare{Local: local, Uninitialized: true})
			continue
		}

		if initializer := declaration.AsVariableDeclaration().Initializer; l.lazyAssertionInitializer(initializer) {
			prefix, present, value, err := l.lazyAssertion(initializer, l.result.Locals[local].Type)
			if err != nil {
				return nil, err
			}
			if known, ok := present.(ir.BooleanConstant); ok && known.Value && len(prefix) == 0 {
				statements = append(statements, ir.Declare{Local: local, Value: value})
				continue
			}
			l.result.Locals[local].Uninitialized = true
			l.result.Locals[local].InitializerExpression = sourceExpression(initializer)
			statements = append(statements, prefix...)
			statements = append(statements, ir.Declare{Local: local, Uninitialized: true}, ir.If{Condition: present, Then: []ir.Statement{ir.Assign{Local: local, Value: value}}})
			continue
		}
		var value ir.Expression
		if initializer := declaration.AsVariableDeclaration().Initializer; initializer != nil {
			if l.initializing == nil {
				l.initializing = map[int]*ast.Node{}
			}
			l.initializing[local] = name
			value, err = l.expression(initializer)
			delete(l.initializing, local)
			if err != nil {
				return nil, err
			}
		} else if !l.result.Locals[local].NamespaceVar && (l.includesUndefined(l.checker.GetTypeAtLocation(name)) || l.evolvingObject(name) != nil) {
			// An optional declaration can be read before assignment. Its first value
			// is undefined, not the backend's unobservable storage placeholder. Namespace
			// var was initialized when hoisted; a later declaration must not reset it.
			value = ir.Undefined{Of: ir.Object}
		}
		if closure, literal := value.(ir.MakeClosure); literal && list.Flags&ast.NodeFlagsConst != 0 {
			l.result.Locals[local].ConstantClosure = closure.Function + 1
		}
		if l.result.Locals[local].NamespaceVar {
			if value != nil {
				statements = append(statements, ir.Assign{Local: local, Value: fit(value, l.result.Locals[local].Type)})
			}
		} else {
			statements = append(statements, l.initializeLocal(local, fit(value, l.result.Locals[local].Type))...)
		}
	}
	return statements, nil
}

// skipped reports whether an element of an array binding pattern is a hole, as in const [, b]: the
// checker's tree has a binding element with no name there.
func skipped(binding *ast.Node) bool {
	return binding.Kind == ast.KindOmittedExpression || binding.Name() == nil
}

// declareLocal makes a new local for a declared name, typed by what the checker proved for it.
func (l *lowering) declareLocal(name *ast.Node) (int, error) {
	symbol := l.symbol(name)
	if symbol == nil {
		return 0, l.notYet(name, "the checker gave a declaration no symbol")
	}
	valueType := ir.Object
	inferred := l.evolvingObject(name)
	if !l.alwaysUndefined[symbol] && !l.caught[symbol] {
		var err error
		if valueType, err = l.typeOf(name); err != nil {
			if inferred == nil {
				return 0, err
			}
			valueType = ir.Object
		}
	}
	if l.locals == nil {
		l.locals = map[*ast.Symbol]int{}
	}
	if local, isDeclared := l.locals[symbol]; isDeclared {
		// A global, registered before anything was lowered.
		return local, nil
	}
	l.locals[symbol] = len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: name.Text(), Type: valueType, Function: l.functionIndex})
	proven := l.checker.GetTypeAtLocation(name)
	if inferred != nil {
		proven = inferred
	}
	l.noteLocal(l.locals[symbol], proven, name)
	return l.locals[symbol], nil
}

// noteAlso keeps another checker type a local has: a this shared by more than one instantiation.
func (l *lowering) noteAlso(local int, proven *checker.Type) {
	if l.localAlso == nil {
		l.localAlso = map[int][]*checker.Type{}
	}
	l.localAlso[local] = append(l.localAlso[local], proven)
}

// noteLocal keeps a local's checker type and declaration for the cycle finder.
func (l *lowering) noteLocal(local int, proven *checker.Type, node *ast.Node) {
	if l.localTypes == nil {
		l.localTypes, l.localNodes = map[int]*checker.Type{}, map[int]*ast.Node{}
	}
	l.localTypes[local], l.localNodes[local] = l.concrete(proven), node
	if l.instance != nil {
		l.instance.templates = append(l.instance.templates, template{local: local, proven: proven})
	}
}

// symbol is what a name refers to, the same whichever file names it: an import resolves to what it
// imports, and an exported declaration to its export symbol, so one declaration is one symbol.
func (l *lowering) symbol(node *ast.Node) *ast.Symbol {
	symbol := l.checker.GetSymbolAtLocation(node)
	if symbol == nil {
		return nil
	}
	if symbol.Flags&ast.SymbolFlagsAlias != 0 {
		symbol = l.checker.GetAliasedSymbol(symbol)
	}
	return l.checker.GetExportSymbolOfSymbol(symbol)
}

// local finds the local an identifier refers to, and notes a capture if it belongs to another
// function.
func (l *lowering) local(identifier *ast.Node) (int, bool) {
	symbol := l.symbol(identifier)
	local, isLocal := l.locals[symbol]
	if isLocal {
		l.touch(local)
		if declared := l.result.Locals[local]; declared.Captured && slotless(declared.Type) && l.unlowerable == nil {
			// A cell holds one adamic_value, and number | undefined needs two words. Lower says so once
			// it's done, since the capture is found here, where nothing can return an error.
			l.unlowerable = l.notYet(identifier, "a "+typeName(declared.Type)+" variable a function value captures")
		}
	}
	return local, isLocal
}

// touch notes that the function being lowered reads or writes a local. One declared in another
// function, and not a global, is captured: it moves into a cell, and every closure being lowered
// between its function and this one carries that cell in its environment.
func (l *lowering) touch(local int) {
	declared := l.result.Locals[local]
	if declared.Ready != 0 {
		l.touch(declared.Ready - 1)
	}
	if declared.Global || declared.Function == l.functionIndex {
		return
	}
	l.result.Locals[local].Captured = true
	if name, isInitializing := l.initializing[local]; isInitializing && l.unlowerable == nil {
		// const f = () => f(): the function value is made before the variable's cell is, so it has
		// nothing to capture yet.
		l.unlowerable = l.notYet(name, "a function value that captures the variable its own initializer declares")
	}
	start := 0
	for position, closure := range l.closures {
		if closure == declared.Function {
			start = position + 1
		}
	}
	for _, closure := range l.closures[start:] {
		function := &l.result.Functions[closure]
		if !slices.Contains(function.Environment, local) {
			function.Environment = append(function.Environment, local)
		}
	}
}

// checked guards switch lexical bindings, captured cells, and globals reached before initialization.
func (l *lowering) checked(local int) bool {
	return l.result.Locals[local].NamespaceState || l.result.Locals[local].Ready != 0 || (l.result.Locals[local].Global && (l.function != nil || l.cyclicModules)) || (l.function != nil && l.result.Locals[local].Preallocated && l.result.Locals[local].Captured)
}

func (l *lowering) constant(value string) int {
	if l.strings == nil {
		l.strings = map[string]int{}
	}
	if index, isKnown := l.strings[value]; isKnown {
		return index
	}
	l.strings[value] = len(l.result.Strings)
	l.result.Strings = append(l.result.Strings, value)
	return l.strings[value]
}

// localRead preserves checker narrowing for both private and qualified singleton reads.
func (l *lowering) localRead(node *ast.Node, local int) (ir.Expression, error) {
	read := ir.Expression(ir.Read{Local: local, Of: l.result.Locals[local].Type, Checked: l.result.Locals[local].NamespaceState || l.checkedModuleRead(node, local), Readiness: sourceExpression(node)})
	if l.result.Locals[local].Type == ir.Union {
		// Where the checker has narrowed it to fewer members held one way, it's read as that.
		parent := node.Parent
		for parent != nil && parent.Kind == ast.KindParenthesizedExpression {
			parent = parent.Parent
		}
		observing := comparedWithUndefined(node) || (parent != nil && parent.Kind == ast.KindTypeOfExpression)
		if narrowed, isKnown := l.representation(l.arrayPredicateObservedType(node)); isKnown && narrowed != ir.Union && !observing {
			// Calls and captured writes can invalidate the checker's narrowing. Check the
			// held member before casting it, with ordinary IR shared by both backends.
			name := "object"
			switch narrowed.Present() {
			case ir.Number:
				name = "number"
			case ir.Boolean:
				name = "boolean"
			case ir.String:
				name = "string"
			case ir.Closure:
				name = "function"
			}
			if name == "object" {
				// typeof cannot distinguish differently held object members.
				declared := l.concrete(l.checker.GetTypeOfSymbol(l.symbol(node)))
				members := []*checker.Type{declared}
				if declared.Flags()&checker.TypeFlagsUnion != 0 {
					members = declared.Types()
				}
				for _, member := range members {
					if held, known := l.representation(member); known && held != narrowed && (held == ir.Object || held == ir.Array || held == ir.Map) {
						return nil, l.notYet(node, "a narrowed union member whose object tag cannot be checked with typeof; keep differently held object kinds in separately typed variables")
					}
				}
			}
			b := l.libraryArrayBuilder([]ir.Expression{read})
			held := b.read(b.parameters[0])
			matches := ir.Expression(ir.Binary{Operator: ir.Equal, Left: ir.TypeOf{Value: held}, Right: ir.StringConstant{Index: l.constant(name)}})
			if narrowed == ir.Array {
				matches = ir.ArrayIsArray{Value: held}
			}
			if l.includesUndefined(l.arrayPredicateObservedType(node)) {
				matches = ir.Binary{Operator: ir.Or, Left: matches, Right: ir.IsUndefined{Value: held}}
			}
			message := "union member where the checker narrowed it away: a call since the narrowing put it back"
			b.body = append(b.body, ir.If{Condition: ir.Unary{Operator: ir.Not, Operand: matches}, Then: []ir.Statement{ir.Panic{Message: ir.StringConstant{Index: l.constant(message)}}}})
			read = b.finish("narrowed_union_member", ir.Narrow{Value: held, To: narrowed})
			l.result.Functions[b.function].CheckedUnionNarrow = true
		}
	}
	if declared := l.result.Locals[local].Type; declared.IsMaybe() {
		// Where the checker has narrowed it to what it holds, it's read as that.
		if narrowed, _ := l.representation(l.checker.GetTypeAtLocation(node)); narrowed == declared.Present() && !l.acceptsUndefined(node) {
			read = ir.Unwrap{Value: read}
		}
	}
	return l.defined(node, read), nil
}

logical_assignment.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

func logicalAssignment(kind ast.Kind) bool {
	return kind == ast.KindBarBarEqualsToken || kind == ast.KindAmpersandAmpersandEqualsToken || kind == ast.KindQuestionQuestionEqualsToken
}

func (l *lowering) logicalAssignment(node *ast.Node) (ir.Expression, error) {
	binary := node.AsBinaryExpression()
	target := ast.SkipParentheses(binary.Left)
	var right ir.Expression
	result, err := l.typeOf(node)
	if err != nil {
		return nil, err
	}
	assignment := ir.LogicalAssignment{Of: result, Operator: "||="}
	if binary.OperatorToken.Kind == ast.KindAmpersandAmpersandEqualsToken {
		assignment.Operator = "&&="
	}
	if binary.OperatorToken.Kind == ast.KindQuestionQuestionEqualsToken {
		assignment.Operator = "??="
	}
	switch target.Kind {
	case ast.KindIdentifier:
		right, err = l.expression(binary.Right)
		if err != nil {
			return nil, err
		}
		local, known := l.local(target)
		if !known || l.caught[l.symbol(target)] || l.alwaysUndefined[l.symbol(target)] {
			return nil, l.notYet(target, "a logical assignment to this binding")
		}
		of := l.result.Locals[local].Type
		l.result.Locals[local].ExpressionAssigned = true
		assignment.Read = ir.Read{Local: local, Of: of, Checked: l.checked(local)}
		assignment.Write = ir.Assign{Local: local, Value: fit(right, of), Checked: l.checked(local)}
	case ast.KindPropertyAccessExpression:
		write, err := l.setProperty(target, binary.Right)
		if err != nil {
			return nil, err
		}
		store, known := write[0].(ir.SetProperty)
		if !known {
			return nil, l.notYet(target, "a logical assignment to an accessor")
		}
		field := l.checker.GetSymbolAtLocation(target.Name())
		if field != nil && accessorSymbol(field) {
			return nil, l.notYet(target, "a logical assignment to an accessor")
		}
		assignment.Write = store
		assignment.Read = ir.Property{Object: store.Object, Name: store.Name, Of: store.Value.Type(), Class: store.Class, Absent: field != nil && field.Flags&ast.SymbolFlagsOptional != 0}
	case ast.KindElementAccessExpression:
		right, err = l.expression(binary.Right)
		if err != nil {
			return nil, err
		}
		access := target.AsElementAccessExpression()
		object, err := l.expression(access.Expression)
		if err != nil {
			return nil, err
		}
		key, err := l.expression(access.ArgumentExpression)
		if err != nil {
			return nil, err
		}
		if object.Type() == ir.Array {
			element, err := l.elementType(access.Expression)
			if err != nil {
				return nil, err
			}
			if key.Type() != ir.Number {
				return nil, l.notYet(target, "an array index that isn't a number")
			}
			assignment.Read = ir.ArrayIndex{Array: object, Index: key, Element: element}
			assignment.Write = ir.SetIndex{Array: object, Index: key, Value: fit(right, element), Element: element, Site: l.writeSite(access.Expression)}
		} else if object.Type() == ir.Object && key.Type() == ir.String {
			of, err := l.typeOf(target)
			if err != nil || slotless(of) {
				return nil, l.notYet(target, "a logical assignment to this computed field")
			}
			names := l.concrete(l.checker.GetTypeAtLocation(access.ArgumentExpression))
			members := []*checker.Type{names}
			if names.Flags()&checker.TypeFlagsUnion != 0 {
				members = names.Types()
			}
			for _, name := range members {
				if name.Flags()&checker.TypeFlagsStringLiteral == 0 {
					return nil, l.notYet(target, "a computed logical assignment key without a finite set of names")
				}
				text, known := name.AsLiteralType().Value().(string)
				if !known {
					return nil, l.notYet(target, "a computed logical assignment key")
				}
				field := l.checker.GetPropertyOfType(l.checker.GetTypeAtLocation(access.Expression), text)
				if field != nil && field.Flags&ast.SymbolFlagsOptional != 0 {
					return nil, l.notYet(target, "writing a possibly absent optional own field")
				}
				if field != nil && accessorSymbol(field) {
					return nil, l.notYet(target, "a logical assignment to an accessor")
				}
				assignment.KeyNames = append(assignment.KeyNames, text)
			}
			assignment.Key = key
			assignment.Read = ir.Property{Object: object, Of: of, Absent: true}
			assignment.Write = ir.SetProperty{Object: object, Value: fit(right, of), Site: l.writeSite(access.Expression)}
		} else {
			return nil, l.notYet(target, "a logical assignment to this member")
		}
	default:
		return nil, l.notYet(target, "a logical assignment to this target")
	}
	return assignment, nil
}

lower.go:
// Package lower turns a checked program into Adamic's IR.
//
// Stage 0 lowers a little and refuses the rest. Every construct it can't lower yet is an error
// naming the construct and where it is, never a skip: a compiler that drops a statement it doesn't
// understand produces a program that looks right and isn't, which is the one thing Adamic must
// never do.
package lower

import (
	"context"
	"fmt"
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
	"path/filepath"
)

// Lower lowers a checked program from one entry, in ESM evaluation order.
func Lower(ctx context.Context, program *load.Program) (*ir.Program, error) {
	files := program.Files()
	if len(files) != 1 {
		return nil, fmt.Errorf("lower: stage 0 compiles a program from one entry file, got %d", len(files))
	}
	entry := files[0]
	// Stage 0 checks single-threaded, so one checker answers for every file.
	typeChecker, release := program.Checker(ctx, entry)
	defer release()

	lowering := &lowering{program: program, checker: typeChecker, result: &ir.Program{}, this: -1, functionIndex: -1}
	// The base name only, so the same program emits the same C on every machine.
	lowering.result.Source = filepath.Base(program.FileName(entry))
	modules, err := lowering.moduleOrder(entry)
	if err != nil {
		return nil, err
	}
	lowering.noteInheritance(modules)
	if err := lowering.enumInitialization(modules); err != nil {
		return nil, err
	}
	lowering.noteAccessorNames(modules)
	lowering.noteOmittedOptionals(modules)
	if err := lowering.namespaceInitialization(modules); err != nil {
		return nil, err
	}
	for _, module := range modules {
		if err := lowering.refuse(module); err != nil {
			return nil, err
		}
	}
	// Link every declaration before lowering any function body, including across back edges.
	var declarations []*ast.Node
	for _, module := range modules {
		declarations = append(declarations, module.Statements.Nodes...)
	}
	if err := lowering.declareModule(declarations); err != nil {
		return nil, err
	}
	for _, module := range modules {
		body, err := lowering.statements(module.Statements.Nodes)
		if err != nil {
			return nil, err
		}
		lowering.result.Main = append(lowering.result.Main, body...)
	}
	if lowering.unlowerable != nil {
		return nil, lowering.unlowerable
	}
	lowering.result.Main = append(lowering.forwarderValues, lowering.result.Main...)
	lowering.finishClassCalls()
	if err := lowering.finishAccessors(); err != nil {
		return nil, err
	}
	if err := lowering.exceptions(); err != nil {
		return nil, err
	}
	if err := lowering.checkAccessorSpreads(); err != nil {
		return nil, err
	}
	if err := lowering.findCycles(modules); err != nil {
		return nil, err
	}
	readiness(lowering.result)
	borrow(lowering.result)
	counters(lowering.result)
	return lowering.result, nil
}

type lowering struct {
	// V2 retains exact logical producer types for union member certification.
	untaggedCallableTargets map[ir.ViewContractID]*checker.Type

	program *load.Program
	checker *checker.Checker
	result  *ir.Program

	// cyclicModules keeps unresolved reads checked throughout a cyclic graph.
	cyclicModules     bool
	provenModuleReads map[*ast.Node]bool
	cycleReadFindings []Finding

	// strings indexes result.Strings, so a constant used twice is stored once.
	strings map[string]int

	// locals maps each variable's symbol to its index in result.Locals.
	locals map[*ast.Symbol]int

	// functions maps each function declaration's symbol to its index in result.Functions.
	functions map[*ast.Symbol]int

	// function is the function being lowered, or nil for the module's top level.
	function *ir.Function

	// this is the local this is in a method or constructor, or -1.
	this int

	// functionIndex is the function being lowered, -1 for the module's top level, and closures the
	// closures being lowered, outermost first, each inside the one before.
	functionIndex int
	closures      []int

	// classes maps each module class's symbol to its declaration, and instances each instantiation
	// already lowered (class.go).
	// omittedOptionals is every optional property some object literal typed by its context leaves out:
	// that object has no slot for it (class.go's absentOptionalWrite).
	omittedOptionals map[*ast.Symbol]bool
	classes          map[*ast.Symbol]*ast.Node
	statics          map[*ast.Symbol]*instance
	staticGlobals    map[*ast.Symbol]int
	instances        map[string]*instance
	derivedAncestors map[*ast.Symbol]bool

	// privateOwners numbers each class that declares a private name, in the order first met, to
	// qualify its private members' names (privateName).
	privateOwners map[*ast.Node]int

	// instance is the class instantiation being lowered, if any.
	instance *instance

	// substitution is what each type parameter stands for in the instantiation being lowered.
	substitution map[*checker.Type]ir.Type

	// unlowerable is the first construct found not lowerable somewhere that can't return an error.
	unlowerable error

	// alwaysUndefined are parameters that only ever receive undefined, whatever the checker calls
	// their type: the first of an Array.from callback's (from.go). Each is a reference that's always
	// missing.
	alwaysUndefined map[*ast.Symbol]bool

	// signed are the functions whose signatures are written and whose bodies aren't lowered yet, by
	// index, each with what its body still needs (signature).
	signed map[int]signed

	// forwarders are the globals holding the function values made for module functions read as values,
	// by the function each forwards to, and forwarderValues the declarations that make them, which run
	// before anything else (functionValue).
	forwarders      map[int]int
	forwarderValues []ir.Statement

	// unsetUntil is where, in the constructor being lowered, its last assignment of a field without an
	// initializer ends: before it, this is only for reading and writing fields (useOfThis).
	unsetUntil int

	// generics maps each generic module function's symbol to its declaration, and genericInstances
	// each instantiation already lowered to its function (generic.go). genericDepth counts the
	// instantiations being lowered inside one another.
	generics              map[*ast.Symbol]*ast.Node
	genericInstances      map[string]int
	classGenericInstances map[string]map[string]int
	genericDepth          int

	// caught are the variables a catch binds, each always an Error; tries are the try statements
	// lowered (exceptions.go).
	caught map[*ast.Symbol]bool
	tries  []tryRecord

	// initializing is the variables whose initializers are being lowered, by where each is declared.
	initializing map[int]*ast.Node

	// For the cycle finder (cycles.go): the checker's type of each local, and where it's declared;
	// every function value made, with its type; and the class type being instantiated, for this.
	localTypes     map[int]*checker.Type
	localAlso      map[int][]*checker.Type
	localNodes     map[int]*ast.Node
	closureRecords []closureRecord
	classType      *checker.Type
	classNode      *ast.Node

	// typeMapper is what the type parameters of the instantiation being lowered, and of those it's
	// inside, stand for; instantiated is every class type an instantiation was made for (instantiate.go).
	typeMapper   *typeMapper
	instantiated []*checker.Type

	// writeSites is every write into a slot lowering made, by its IR node's Site less one (fresh.go).
	writeSites       []writeSite
	accessorCaptures []accessorCapture
	accessorNames    map[string]bool
}

module_namespace.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/load"
)

// An ESM namespace qualification denotes the export's live binding, even through
// re-export barrels. A structural object with the same type is not that binding.
func (l *lowering) moduleNamespace(node *ast.Node) bool {
	symbol := l.symbol(ast.SkipParentheses(node))
	if symbol == nil {
		return false
	}
	for _, declaration := range symbol.Declarations {
		if declaration.Kind == ast.KindSourceFile && !load.IsLibrary(declaration.AsSourceFile()) && !load.IsPrelude(declaration.AsSourceFile()) {
			return true
		}
	}
	return false
}

func (l *lowering) moduleNamespaceRefusal(node *ast.Node) error {
	if l.namespaceValueNode(node) && l.moduleNamespace(node) {
		parent := node.Parent
		if parent == nil || parent.Kind != ast.KindPropertyAccessExpression || parent.Expression() != node {
			return l.notYet(node, "an ESM namespace object used as a value; use qualified live bindings")
		}
	}
	if node.Kind != ast.KindPropertyAccessExpression || !l.moduleNamespace(node.Expression()) {
		return nil
	}
	symbol := l.symbol(node)
	if symbol == nil {
		return nil
	}
	for _, declaration := range symbol.Declarations {
		if ast.IsFunctionLike(declaration) && namespaceOwnThis(declaration) {
			return l.notYet(node, "an ESM namespace function observing its receiver; the module object is not represented")
		}
	}
	return nil
}

modules.go:
// Functions and declarations moved unchanged from lower.go.
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
)

// moduleOrder is the order the program's modules run in, ECMAScript's: each module's imports first,
// depth-first in the order they're written, then the module itself. The prelude's 'adamic' module
// has no body to run. A module already in progress is the cycle back edge and is skipped.
func (l *lowering) moduleOrder(entry *ast.SourceFile) ([]*ast.SourceFile, error) {
	order, cyclic := esmModuleOrder(l.checker, entry)
	l.cyclicModules = cyclic
	if cyclic {
		if err := l.loadTimeReads(order); err != nil {
			return nil, err
		}
	}
	return order, nil
}

// esmModuleOrder is shared with the source-ledger audit so it measures the
// compiler's actual scheduling proof, rather than replaying observed Node order.
func esmModuleOrder(typeChecker *checker.Checker, entry *ast.SourceFile) ([]*ast.SourceFile, bool) {
	order := []*ast.SourceFile{}
	state := map[*ast.SourceFile]int{} // 1 while its imports are being visited, 2 once placed
	cyclic := false
	var visit func(module *ast.SourceFile)
	visit = func(module *ast.SourceFile) {
		switch state[module] {
		case 1:
			cyclic = true
			return
		case 2:
			return
		}
		state[module] = 1
		for _, statement := range module.Statements.Nodes {
			if statement.Kind != ast.KindImportDeclaration && statement.Kind != ast.KindExportDeclaration {
				continue
			}
			if !runtimeModuleStatement(statement) {
				continue
			}
			specifier := statement.ModuleSpecifier()
			if specifier == nil {
				continue
			}
			target := typeChecker.GetSymbolAtLocation(specifier)
			if target == nil || len(target.Declarations) == 0 || target.Declarations[0].Kind != ast.KindSourceFile {
				// 'adamic' is an ambient module in the prelude: nothing to run.
				continue
			}
			imported := target.Declarations[0].AsSourceFile()
			if load.IsPrelude(imported) || load.IsLibrary(imported) {
				continue
			}
			visit(imported)
		}
		state[module] = 2
		order = append(order, module)
	}
	visit(entry)
	return order, cyclic
}

// declareModule registers the module's globals and functions before anything is lowered, so a
// function can call one declared below it and read a global declared below it, as JavaScript
// allows. Every function's signature is written, from the checker, before any body is lowered, so a
// call knows what the function it calls returns wherever that function is declared, and two
// functions can call each other. Then each body is lowered.
func (l *lowering) declareModule(statements []*ast.Node) error {
	statements = namespaceDeclarations(statements)
	declarations := []*ast.Node{}
	for _, statement := range statements {
		switch statement.Kind {
		case ast.KindVariableStatement:
			list := statement.AsVariableStatement().DeclarationList
			if list.Flags&ast.NodeFlagsBlockScoped == 0 && !assertionVarList(list) && !namespaceVariable(list) {
				continue // statements() refuses var where it stands
			}
			for _, declaration := range list.AsVariableDeclarationList().Declarations.Nodes {
				// A module's const [a, b] = tuple, or { x, y } = object, declares globals too, each name
				// its own.
				if declaration.Name().Kind == ast.KindArrayBindingPattern || declaration.Name().Kind == ast.KindObjectBindingPattern {
					for _, binding := range declaration.Name().AsBindingPattern().Elements.Nodes {
						if skipped(binding) || !ast.IsIdentifier(binding.Name()) {
							continue
						}
						local, err := l.declareLocal(binding.Name())
						if err != nil {
							return err
						}
						l.result.Locals[local].Global = true
						l.result.Locals[local].Hoisted = list.Flags&ast.NodeFlagsBlockScoped == 0
						if namespaceVariable(list) && list.Flags&ast.NodeFlagsBlockScoped == 0 {
							l.result.Locals[local].NamespaceVar = true
							l.result.Locals[local].NamespaceState = true
						}
					}
					continue
				}
				if ast.IsIdentifier(declaration.Name()) {
					local, err := l.declareLocal(declaration.Name())
					if err != nil {
						return err
					}
					l.result.Locals[local].Global = true
					l.result.Locals[local].Hoisted = list.Flags&ast.NodeFlagsBlockScoped == 0
					if namespaceVariable(list) {
						l.result.Locals[local].NamespaceVar = list.Flags&ast.NodeFlagsBlockScoped == 0
						l.result.Locals[local].NamespaceState = declaration.Initializer() == nil || l.result.Locals[local].NamespaceVar
					}
				}
			}
		case ast.KindEnumDeclaration:
			if !ast.HasSyntacticModifier(statement, ast.ModifierFlagsConst) {
				local, err := l.enumLocal(statement)
				if err != nil {
					return err
				}
				l.result.Locals[local].Global = true
			}
		case ast.KindClassDeclaration:
			if l.classes == nil {
				l.classes = map[*ast.Symbol]*ast.Node{}
			}
			l.classes[l.symbol(statement.Name())] = statement
			if l.needsStatics(statement) {
				if l.staticGlobals == nil {
					l.staticGlobals = map[*ast.Symbol]int{}
				}
				local, err := l.declareLocal(statement.Name())
				if err != nil {
					return err
				}
				l.result.Locals[local].Global = true
				l.staticStorage(statement)
			}
		case ast.KindFunctionDeclaration:
			if statement.Body() == nil && l.censusImplementation(statement) != nil {
				continue
			}
			if err := l.censusOverloads(statement); err != nil {
				return err
			}
			symbol := l.symbol(statement.Name())
			if len(statement.TypeParameters()) > 0 {
				// A generic function is lowered once per instantiation, where it's called (generic.go).
				if l.generics == nil {
					l.generics = map[*ast.Symbol]*ast.Node{}
				}
				l.generics[symbol] = statement
				continue
			}
			if l.functions == nil {
				l.functions = map[*ast.Symbol]int{}
			}
			l.functions[symbol] = len(l.result.Functions)
			l.result.Functions = append(l.result.Functions, ir.Function{Name: statement.Name().Text()})
			declarations = append(declarations, statement)
		}
	}
	for _, declaration := range declarations {
		if err := l.signature(l.functions[l.symbol(declaration.Name())], declaration, -1); err != nil {
			return err
		}
	}
	for _, statement := range statements {
		if statement.Kind == ast.KindClassDeclaration && l.needsStatics(statement) {
			if _, err := l.staticInstance(statement); err != nil {
				return err
			}
		}
	}
	for _, declaration := range declarations {
		if err := l.functionBody(declaration); err != nil {
			return err
		}
	}
	return nil
}

// Explicit type imports and exports have no ESM evaluation edge. With verbatimModuleSyntax,
// even an empty named import after inline type stripping still evaluates its module.
func runtimeModuleStatement(statement *ast.Node) bool {
	if statement.Kind == ast.KindImportDeclaration {
		clause := statement.AsImportDeclaration().ImportClause
		return clause == nil || !clause.IsTypeOnly()
	}
	return !statement.AsExportDeclaration().IsTypeOnly
}

namespace_callable.go:
package lower

import "github.com/microsoft/TypeScript/tsc/shim/ast"

func (l *lowering) namespaceMergedFunction(node *ast.Node) bool {
	symbol := l.symbol(node)
	if symbol == nil || l.namespaceDeclaration(node) == nil {
		return false
	}
	for _, declaration := range symbol.Declarations {
		if declaration.Kind == ast.KindFunctionDeclaration {
			return true
		}
	}
	return false
}

// A closure represents the callable identity, but has no attached object storage.
// Only uses that cannot observe that omitted container are admitted.
func (l *lowering) callableNamespaceUse(node *ast.Node) bool {
	if called(node) {
		return true
	}
	use := node
	for use.Parent != nil && use.Parent.Kind == ast.KindParenthesizedExpression {
		use = use.Parent
	}
	parent := use.Parent
	if parent == nil {
		return false
	}
	if parent.Kind == ast.KindTypeOfExpression {
		return true
	}
	if parent.Kind == ast.KindPropertyAccessExpression && parent.Expression() == use && l.namespaceMember(parent) {
		return true
	}
	if parent.Kind == ast.KindBinaryExpression {
		binary := parent.AsBinaryExpression()
		if binary.OperatorToken.Kind == ast.KindEqualsEqualsEqualsToken || binary.OperatorToken.Kind == ast.KindExclamationEqualsEqualsToken {
			return l.namespaceFixedFunction(binary.Left) && l.namespaceFixedFunction(binary.Right)
		}
	}
	return false
}

func (l *lowering) namespaceFixedFunction(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindIdentifier && node.Kind != ast.KindPropertyAccessExpression {
		return false
	}
	symbol := l.symbol(node)
	if symbol == nil {
		return false
	}
	for _, declaration := range symbol.Declarations {
		if declaration.Kind == ast.KindFunctionDeclaration && (declaration.Parent.Kind == ast.KindModuleBlock || l.namespaceMergedFunction(node)) {
			return true
		}
	}
	return false
}

func callableNamespaceIntrinsic(name string) bool {
	switch name {
	case "name", "length", "prototype", "caller", "arguments", "call", "apply", "bind", "toString":
		return true
	}
	return false
}

namespace_receiver_scope.go:
package lower

import "github.com/microsoft/TypeScript/tsc/shim/ast"

// Arrows inherit this, but a nested ordinary function, object method or class
// owns a separate receiver. Its body is checked by that construct's lowering.
func namespaceOwnThis(declaration *ast.Node) bool {
	var visit func(*ast.Node) bool
	visit = func(node *ast.Node) bool {
		if node == nil || ast.IsTypeNode(node) {
			return false
		}
		if ast.IsClassLike(node) || ast.IsFunctionLike(node) && node.Kind != ast.KindArrowFunction {
			return false
		}
		if node.Kind == ast.KindThisKeyword {
			return true
		}
		return node.ForEachChild(visit)
	}
	return visit(declaration.Body())
}

namespaces.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

func namespaceStatements(declaration *ast.Node) []*ast.Node {
	body := declaration.AsModuleDeclaration().Body
	if body == nil {
		return nil
	}
	if body.Kind == ast.KindModuleDeclaration {
		return []*ast.Node{body}
	}
	return body.AsModuleBlock().Statements.Nodes
}

func namespaceRuntime(declaration *ast.Node) bool {
	// Ambient declarations describe host values, not executable namespace bodies.
	// The context flag includes nested declarations without their own declare token.
	if declaration.Flags&ast.NodeFlagsAmbient != 0 || ast.HasSyntacticModifier(declaration, ast.ModifierFlagsAmbient) || ast.GetSourceFileOfNode(declaration).IsDeclarationFile {
		return false
	}
	for _, member := range namespaceStatements(declaration) {
		switch member.Kind {
		case ast.KindInterfaceDeclaration, ast.KindTypeAliasDeclaration, ast.KindEmptyStatement:
		case ast.KindModuleDeclaration:
			if namespaceRuntime(member) {
				return true
			}
		default:
			return true
		}
	}
	return false
}

// Flatten scoped declarations, never names: the checker's symbols retain every namespace and
// private binding's identity. The qualified-only subset cannot observe a namespace object.
func namespaceDeclarations(statements []*ast.Node) []*ast.Node {
	result := []*ast.Node{}
	for _, statement := range statements {
		if statement.Kind == ast.KindModuleDeclaration {
			result = append(result, namespaceDeclarations(namespaceStatements(statement))...)
		} else {
			result = append(result, statement)
		}
	}
	return result
}

func (l *lowering) namespaceDeclaration(node *ast.Node) *ast.Node {
	symbol := l.symbol(node)
	if symbol == nil {
		return nil
	}
	for _, declaration := range symbol.Declarations {
		if declaration.Kind == ast.KindModuleDeclaration && ast.IsIdentifier(declaration.Name()) {
			return declaration
		}
	}
	return nil
}

func (l *lowering) namespaceMember(node *ast.Node) bool {
	module := false
	if node.Kind == ast.KindPropertyAccessExpression || node.Kind == ast.KindElementAccessExpression {
		module = l.moduleNamespace(node.Expression())
		if !module && l.namespaceDeclaration(node.Expression()) == nil {
			return false
		}
	}
	symbol := l.symbol(node)
	if symbol == nil {
		return false
	}
	for _, declaration := range symbol.Declarations {
		parent := declaration.Parent
		if declaration.Kind == ast.KindVariableDeclaration {
			parent = parent.Parent.Parent
		}
		if parent != nil && (parent.Kind == ast.KindModuleBlock || module && parent.Kind == ast.KindSourceFile) {
			return true
		}
	}
	return false
}

func (l *lowering) namespaceExpression(node *ast.Node) (ir.Expression, bool, error) {
	if node.Kind != ast.KindPropertyAccessExpression && node.Kind != ast.KindElementAccessExpression || !l.namespaceMember(node) {
		return nil, false, nil
	}
	if node.Kind == ast.KindElementAccessExpression {
		return nil, true, l.notYet(node, "a computed namespace member; use a qualified name")
	}
	if node.AsPropertyAccessExpression().QuestionDotToken != nil || node.Flags&ast.NodeFlagsOptionalChain != 0 {
		return nil, true, l.notYet(node, "an optional namespace read; use a qualified name after initialization")
	}
	if function, found := l.functions[l.symbol(node)]; found {
		value, err := l.functionValue(node, function)
		if err == nil {
			value = l.namespaceReadyValue(node, value)
		}
		return value, true, err
	}
	if local, found := l.local(node); found {
		read, err := l.localRead(node, local)
		if err != nil {
			return nil, true, err
		}
		return l.namespaceReadyValue(node, read), true, nil
	}
	return nil, true, l.notYet(node, "a namespace member without a lowered binding")
}

func (l *lowering) namespaceValueNode(node *ast.Node) bool {
	if parent := node.Parent; parent != nil && parent.Kind == ast.KindPropertyAccessExpression && parent.Name() == node {
		return false
	}
	if !l.isExpression(node) || ast.IsDeclarationName(node) {
		return false
	}
	for parent := node.Parent; parent != nil; parent = parent.Parent {
		if ast.IsTypeNode(parent) || parent.Kind == ast.KindImportDeclaration || parent.Kind == ast.KindExportDeclaration {
			return false
		}
		if ast.IsStatement(parent) {
			break
		}
	}
	return true
}

func (l *lowering) namespaceRefusal(node *ast.Node) error {
	if err := l.moduleNamespaceRefusal(node); err != nil {
		return err
	}
	if node.Kind == ast.KindModuleDeclaration {
		if !ast.IsIdentifier(node.Name()) || ast.HasSyntacticModifier(node, ast.ModifierFlagsAmbient) {
			return l.notYet(node, "an ambient namespace or external module; use named file imports")
		}
		if node.Parent.Kind != ast.KindSourceFile && node.Parent.Kind != ast.KindModuleBlock && node.Parent.Kind != ast.KindModuleDeclaration {
			return l.notYet(node, "a namespace outside module scope")
		}
		symbol := l.symbol(node.Name())
		for _, declaration := range symbol.Declarations {
			if declaration == node || declaration.Kind == ast.KindInterfaceDeclaration || declaration.Kind == ast.KindTypeAliasDeclaration {
				continue
			}
			if declaration.Kind == ast.KindFunctionDeclaration && declaration.Parent == node.Parent {
				if namespaceOwnThis(declaration) {
					return &Refused{Where: l.program.Where(declaration), What: "this in a callable namespace function; qualified and detached calls have different receivers", Fix: "pass the state explicitly"}
				}
				for _, parameter := range declaration.Parameters() {
					if parameter.Name().Text() == "this" {
						return l.notYet(parameter, "an explicit callable-namespace this parameter; pass state explicitly")
					}
				}
				continue
			}
			return l.notYet(node, "a reopened namespace or namespace merged with a runtime value; put the declarations in one namespace or use a module")
		}
		for _, member := range namespaceStatements(node) {
			if l.namespaceMergedFunction(node.Name()) && ast.HasSyntacticModifier(member, ast.ModifierFlagsExport) {
				if member.Kind == ast.KindVariableStatement {
					for _, variable := range member.AsVariableStatement().DeclarationList.AsVariableDeclarationList().Declarations.Nodes {
						if variable.Name() != nil && callableNamespaceIntrinsic(variable.Name().Text()) {
							return l.notYet(variable, "a callable namespace export colliding with a function intrinsic")
						}
					}
				} else if member.Name() != nil && callableNamespaceIntrinsic(member.Name().Text()) {
					return l.notYet(member, "a callable namespace export colliding with a function intrinsic")
				}
			}
			switch member.Kind {
			case ast.KindInterfaceDeclaration, ast.KindTypeAliasDeclaration, ast.KindEmptyStatement, ast.KindModuleDeclaration, ast.KindClassDeclaration, ast.KindEnumDeclaration:
			case ast.KindExpressionStatement, ast.KindBlock, ast.KindIfStatement, ast.KindForStatement, ast.KindWhileStatement, ast.KindDoStatement, ast.KindForOfStatement, ast.KindSwitchStatement:
				// Statement lowering keeps module evaluation order. Calls still pass preflight.
			case ast.KindFunctionDeclaration:
				if namespaceOwnThis(member) {
					return &Refused{Where: l.program.Where(member), What: "this in a namespace function; a qualified call and a detached call have different receivers", Fix: "pass the state as an explicit parameter instead of using this"}
				}
				for _, parameter := range member.Parameters() {
					if parameter.Name().Kind == ast.KindThisKeyword || parameter.Name().Text() == "this" {
						return l.notYet(parameter, "an explicit namespace-function this parameter; pass state explicitly")
					}
				}
			case ast.KindVariableStatement:
				list := member.AsVariableStatement().DeclarationList
				for _, variable := range list.AsVariableDeclarationList().Declarations.Nodes {
					if !ast.IsIdentifier(variable.Name()) && (list.Flags&ast.NodeFlagsBlockScoped != 0 || !namespaceObjectBindings(variable.Name())) {
						return l.notYet(variable, "destructuring inside a namespace; use plain singleton bindings")
					}
				}
			default:
				return l.notYet(member, "an unsupported namespace statement or declaration")
			}
		}
	}
	if node.Kind == ast.KindVariableDeclarationList && node.Flags&ast.NodeFlagsBlockScoped == 0 && !namespaceVariable(node) {
		for parent := node.Parent; parent != nil; parent = parent.Parent {
			if ast.IsFunctionLike(parent) {
				break
			}
			if parent.Kind == ast.KindModuleBlock {
				return l.notYet(node, "var inside namespace control flow; direct singleton var is hoisted, block var is not yet modeled")
			}
		}
	}
	if l.namespaceValueNode(node) && l.namespaceDeclaration(node) != nil {
		parent := node.Parent
		if l.namespaceMergedFunction(node) {
			if l.callableNamespaceUse(node) {
				return nil
			}
			return l.notYet(node, "observing a callable namespace object; only direct calls, fixed qualified members, typeof and canonical function identity are represented")
		}
		if parent == nil || parent.Kind != ast.KindPropertyAccessExpression || parent.AsPropertyAccessExpression().Expression != node {
			return l.notYet(node, "a namespace object used as a value; no runtime container is emitted, so identity, receiver behavior, live export aliases and staged properties are not represented; use qualified members or named module imports")
		}
	}
	if l.isExpression(node) && l.namespaceMember(node) {
		parent := node.Parent
		if parent != nil && parent.Kind == ast.KindBinaryExpression && parent.AsBinaryExpression().Left == node && ast.IsAssignmentOperator(parent.AsBinaryExpression().OperatorToken.Kind) {
			if node.Kind == ast.KindPropertyAccessExpression || node.Kind == ast.KindElementAccessExpression {
				symbol := l.symbol(node)
				mutable := false
				for _, declaration := range symbol.Declarations {
					if declaration.Kind == ast.KindVariableDeclaration && declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
						mutable = true
					}
				}
				if !mutable {
					return l.notYet(node, "replacing a namespace export; exported functions and constants have fixed identity")
				}
			}
		}
	}
	return nil
}

// Follow statically known callees before executing a module statement. An unresolved
// edge keeps namespace reads checked at runtime; it is never proof of no effects.
func (l *lowering) namespaceInitialization(modules []*ast.SourceFile) error {
	initialized := map[*ast.Node]bool{}
	graph := namespaceCallGraph{lowering: l, functions: map[*ast.Node]*namespaceCallNode{}}
	checkCall := func(target *ast.Node) error {
		for declaration, read := range graph.reach(target) {
			if !initialized[declaration] {
				if declaration.Kind == ast.KindEnumDeclaration {
					return l.notYet(read, "reading an enum before its runtime initialization; move the call after the enum declaration")
				}
				return l.notYet(read, "a namespace read before runtime initialization, directly or through a reachable call; move that read or call after the namespace declaration")
			}
		}
		return nil
	}
	var visit func(*ast.Node) error
	visit = func(node *ast.Node) error {
		if node == nil || ast.IsTypeNode(node) || ast.IsFunctionLike(node) {
			return nil
		}
		if branch := l.literalCallableBranch(node); branch != nil {
			return visit(branch)
		}
		if ast.IsClassLike(node) {
			for _, clause := range nodesOf(node.AsClassDeclaration().HeritageClauses) {
				if clause.AsHeritageClause().Token == ast.KindExtendsKeyword {
					for _, element := range clause.AsHeritageClause().Types.Nodes {
						if err := visit(element.AsExpressionWithTypeArguments().Expression); err != nil {
							return err
						}
					}
				}
			}
			// Instance fields and constructor bodies execute at new, not at the
			// declaration. Unknown construction keeps the checks in those bodies.
			for _, member := range node.AsClassDeclaration().Members.Nodes {
				if ast.HasStaticModifier(member) || member.Kind == ast.KindClassStaticBlockDeclaration {
					if err := visit(member); err != nil {
						return err
					}
				}
			}
			return nil
		}
		if node.Kind == ast.KindModuleDeclaration {
			for _, statement := range namespaceStatements(node) {
				if err := visit(statement); err != nil {
					return err
				}
			}
			initialized[node] = true
			return nil
		}
		// The enum object exists while its own member assignments execute.
		if node.Kind == ast.KindEnumDeclaration {
			initialized[node] = true
		}
		if l.namespaceValueNode(node) {
			if declaration := l.namespaceRuntimeEnum(node); declaration != nil && !initialized[declaration] {
				return l.notYet(node, "reading an enum before its runtime initialization; move the call after the enum declaration")
			}
			if declaration := l.namespaceDeclaration(node); declaration != nil && namespaceRuntime(declaration) && !initialized[declaration] {
				return l.notYet(node, "a namespace read before runtime initialization, directly or through a reachable call; move that read or call after the namespace declaration")
			}
		}
		if node.Kind == ast.KindCallExpression || node.Kind == ast.KindNewExpression {
			if target := l.namespaceCallable(node.Expression()); target != nil {
				if err := checkCall(target); err != nil {
					return err
				}
			}
			// Library operations may invoke callbacks. A known callback participates in
			// the same graph; unknown values retain checks in their eventual bodies.
			for _, argument := range node.Arguments() {
				if target := l.namespaceCallable(argument); target != nil {
					if err := checkCall(target); err != nil {
						return err
					}
				}
			}
		}
		var found error
		node.ForEachChild(func(child *ast.Node) bool { found = visit(child); return found != nil })
		if node.Kind == ast.KindEnumDeclaration {
			initialized[node] = true
		}
		return found
	}
	for _, module := range modules {
		for _, statement := range module.Statements.Nodes {
			if err := visit(statement); err != nil {
				return err
			}
		}
	}
	return nil
}

// Mutable aliases, parameters and virtual methods are unresolved edges. Only
// direct functions and immutable initializer chains identify a single body.
func (l *lowering) namespaceCallable(callee *ast.Node) *ast.Node {
	seen := map[*ast.Symbol]bool{}
	for callee != nil {
		callee = ast.SkipParentheses(callee)
		if branch := l.literalCallableBranch(callee); branch != nil {
			callee = branch
			continue
		}
		if callee.Kind == ast.KindArrowFunction || callee.Kind == ast.KindFunctionExpression {
			return callee
		}
		symbol := l.symbol(callee)
		if symbol == nil || seen[symbol] || symbol.ValueDeclaration == nil {
			return nil
		}
		seen[symbol] = true
		declaration := symbol.ValueDeclaration
		switch declaration.Kind {
		case ast.KindClassDeclaration:
			return declaration
		case ast.KindFunctionDeclaration:
			if declaration.Body() != nil {
				return declaration
			}
			return nil
		case ast.KindVariableDeclaration:
			if declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
				return nil
			}
			callee = declaration.Initializer()
		case ast.KindPropertyAssignment:
			if !l.checker.IsReadonlySymbol(symbol) {
				return nil
			}
			callee = declaration.Initializer()
		default:
			return nil
		}
	}
	return nil
}

// A generated boolean starts false before module evaluation and becomes true
// only after the namespace body completes. Checks use ordinary IR and the
// namespace-property TypeError, rather than reading native zero export storage.
func (l *lowering) namespaceReadyLocal(declaration *ast.Node) int {
	symbol := l.symbol(declaration.Name())
	if local, found := l.locals[symbol]; found {
		return local
	}
	if l.locals == nil {
		l.locals = map[*ast.Symbol]int{}
	}
	local := len(l.result.Locals)
	l.locals[symbol] = local
	l.result.Locals = append(l.result.Locals, ir.Local{Name: declaration.Name().Text(), Type: ir.Boolean, Global: true, Function: -1})
	l.forwarderValues = append(l.forwarderValues, ir.Declare{Local: local, Value: ir.BooleanConstant{Value: false}})
	return local
}

func (l *lowering) namespaceReadyReads(node *ast.Node, writing bool) []ir.Expression {
	checks := []ir.Expression{}
	for node != nil && ast.SkipParentheses(node).Kind == ast.KindPropertyAccessExpression {
		node = ast.SkipParentheses(node)
		member := node.Name().Text()
		setting := writing
		writing = false
		node = ast.SkipParentheses(node.Expression())
		if declaration := l.namespaceDeclaration(node); declaration != nil && namespaceRuntime(declaration) {
			b := l.libraryArrayBuilder([]ir.Expression{ir.Read{Local: l.namespaceReadyLocal(declaration), Of: ir.Boolean}})
			message := "TypeError: Cannot read properties of undefined (reading '" + member + "')"
			if setting {
				message = "TypeError: Cannot set properties of undefined (setting '" + member + "')"
			}
			b.body = append(b.body, ir.If{Condition: ir.Unary{Operator: ir.Not, Operand: b.read(b.parameters[0])}, Then: []ir.Statement{ir.Panic{Message: ir.StringConstant{Index: l.constant(message)}}}})
			// The outer container is read first in Outer.Inner.member.
			checks = append([]ir.Expression{b.finish("namespace_ready", ir.BooleanConstant{Value: true})}, checks...)
		}
	}
	return checks
}

func (l *lowering) namespaceReadyValue(node *ast.Node, value ir.Expression) ir.Expression {
	checks := l.namespaceReadyReads(node, false)
	if len(checks) == 0 {
		return value
	}
	b := l.libraryArrayBuilder(append(checks, value))
	return b.finish("namespace_read", b.read(b.parameters[len(checks)]))
}

// Run readiness before evaluating the call. Keep the call itself intact so its
// counted dispatch, spread layout and argument fitting remain at the existing boundary.
func (l *lowering) namespaceReadyCall(node *ast.Node, value ir.Expression) ir.Expression {
	checks := l.namespaceReadyReads(node, false)
	if len(checks) == 0 {
		return value
	}
	body := make([]ir.Statement, 0, len(checks)+1)
	for _, check := range checks {
		body = append(body, ir.Evaluate{Value: check})
	}
	if value.Type() == 0 {
		body = append(body, ir.Evaluate{Value: value})
		value = ir.Undefined{}
	}
	return ir.Effects{Body: body, Result: value}
}

// namespaceVariable identifies direct singleton storage, excluding function-local var.
func namespaceVariable(list *ast.Node) bool {
	return list.Parent != nil && list.Parent.Parent != nil && list.Parent.Parent.Kind == ast.KindModuleBlock
}

func (l *lowering) namespaceBody(node *ast.Node) ([]ir.Statement, error) {
	hoisted := []ir.Statement{}
	seen := map[int]bool{}
	for _, statement := range namespaceStatements(node) {
		if statement.Kind != ast.KindVariableStatement {
			continue
		}
		list := statement.AsVariableStatement().DeclarationList
		if list.Flags&ast.NodeFlagsBlockScoped != 0 {
			continue
		}
		for _, declaration := range list.AsVariableDeclarationList().Declarations.Nodes {
			names := []*ast.Node{declaration.Name()}
			if !ast.IsIdentifier(declaration.Name()) {
				if !namespaceObjectBindings(declaration.Name()) {
					return nil, l.notYet(declaration.Name(), "destructuring inside a namespace; only flat object var bindings are hoisted")
				}
				names = nil
				for _, binding := range declaration.Name().AsBindingPattern().Elements.Nodes {
					names = append(names, binding.Name())
				}
			}
			for _, name := range names {
				local, err := l.declareLocal(name)
				if err != nil {
					return nil, err
				}
				if seen[local] {
					continue
				}
				seen[local] = true
				var value ir.Expression
				if l.includesUndefined(l.checker.GetTypeAtLocation(name)) {
					value = fit(ir.Undefined{Of: l.result.Locals[local].Type}, l.result.Locals[local].Type)
				}
				hoisted = append(hoisted, ir.Declare{Local: local, Value: value})
			}
		}
	}
	body, err := l.statements(namespaceStatements(node))
	if err != nil {
		return nil, err
	}
	if namespaceRuntime(node) {
		body = append(body, ir.Assign{Local: l.namespaceReadyLocal(node), Value: ir.BooleanConstant{Value: true}})
	}
	return append(hoisted, body...), nil
}

// The parser's factory destructuring declares symbols on the renamed identifiers,
// not on the ObjectBindingPattern. Other binding forms retain their own NotYet.
func namespaceObjectBindings(pattern *ast.Node) bool {
	if pattern.Kind != ast.KindObjectBindingPattern {
		return false
	}
	for _, binding := range pattern.AsBindingPattern().Elements.Nodes {
		declared := binding.AsBindingElement()
		if !ast.IsIdentifier(binding.Name()) || declared.Initializer != nil || declared.DotDotDotToken != nil {
			return false
		}
		if declared.PropertyName != nil && !ast.IsIdentifier(declared.PropertyName) && declared.PropertyName.Kind != ast.KindStringLiteral {
			return false
		}
	}
	return true
}

func (l *lowering) namespaceReadyStatements(node *ast.Node, writing bool) []ir.Statement {
	statements := []ir.Statement{}
	for _, check := range l.namespaceReadyReads(node, writing) {
		statements = append(statements, ir.Evaluate{Value: check})
	}
	return statements
}

namespaces_call_graph.go:
package lower

import "github.com/microsoft/TypeScript/tsc/shim/ast"

// Each function body is inspected once. Tarjan's active stack identifies cycles;
// only a complete component receives a cached transitive reach set. Sets contain
// all namespace and regular enum declarations, independent of the current module evaluation point.
type namespaceCallGraph struct {
	lowering  *lowering
	functions map[*ast.Node]*namespaceCallNode
	stack     []*namespaceCallNode
	next      int
	walks     int
}

type namespaceCallNode struct {
	index, low int
	active     bool
	edges      []*namespaceCallNode
	reads      map[*ast.Node]*ast.Node
	reaches    map[*ast.Node]*ast.Node
}

func (g *namespaceCallGraph) reach(function *ast.Node) map[*ast.Node]*ast.Node {
	return g.discover(function).reaches
}

func (g *namespaceCallGraph) discover(function *ast.Node) *namespaceCallNode {
	if cached := g.functions[function]; cached != nil {
		return cached
	}
	g.walks++
	entry := &namespaceCallNode{index: g.next, low: g.next, active: true, reads: map[*ast.Node]*ast.Node{}}
	g.next++
	g.functions[function] = entry
	g.stack = append(g.stack, entry)
	connect := func(target *ast.Node) {
		previous := g.functions[target]
		edge := g.discover(target)
		entry.edges = append(entry.edges, edge)
		if edge.active {
			if previous == nil {
				entry.low = min(entry.low, edge.low)
			} else {
				entry.low = min(entry.low, edge.index)
			}
		}
	}
	var walk func(*ast.Node)
	walk = func(node *ast.Node) {
		if node == nil || ast.IsTypeNode(node) || node != function && ast.IsFunctionLike(node) {
			return
		}
		if branch := g.lowering.literalCallableBranch(node); branch != nil {
			walk(branch)
			return
		}
		if ast.IsClassLike(node) {
			if node == function {
				for _, clause := range nodesOf(node.AsClassDeclaration().HeritageClauses) {
					if clause.AsHeritageClause().Token == ast.KindExtendsKeyword {
						for _, element := range clause.AsHeritageClause().Types.Nodes {
							if base := g.lowering.namespaceCallable(element.AsExpressionWithTypeArguments().Expression); base != nil {
								connect(base)
							}
						}
					}
				}
				// Construction executes instance initializers, parameter defaults and
				// the constructor body. Static members ran at the class declaration.
				for _, member := range node.AsClassDeclaration().Members.Nodes {
					if member.Kind == ast.KindPropertyDeclaration && !ast.HasStaticModifier(member) {
						walk(member.Initializer())
					}
					if member.Kind == ast.KindConstructor {
						for _, parameter := range member.Parameters() {
							walk(parameter.Initializer())
						}
						walk(member.Body())
					}
				}
				return
			}
			for _, clause := range nodesOf(node.AsClassDeclaration().HeritageClauses) {
				if clause.AsHeritageClause().Token == ast.KindExtendsKeyword {
					for _, element := range clause.AsHeritageClause().Types.Nodes {
						walk(element.AsExpressionWithTypeArguments().Expression)
					}
				}
			}
			for _, member := range node.AsClassDeclaration().Members.Nodes {
				if ast.HasStaticModifier(member) || member.Kind == ast.KindClassStaticBlockDeclaration {
					walk(member)
				}
			}
			return
		}
		if g.lowering.namespaceValueNode(node) {
			if declaration := g.lowering.namespaceRuntimeEnum(node); declaration != nil {
				entry.reads[declaration] = node
			}
			if declaration := g.lowering.namespaceDeclaration(node); declaration != nil && namespaceRuntime(declaration) {
				entry.reads[declaration] = node
			}
		}
		if node.Kind == ast.KindCallExpression || node.Kind == ast.KindNewExpression {
			callees := append([]*ast.Node{node.Expression()}, node.Arguments()...)
			for _, callee := range callees {
				if target := g.lowering.namespaceCallable(callee); target != nil {
					connect(target)
				}
			}
		}
		node.ForEachChild(func(child *ast.Node) bool { walk(child); return false })
	}
	walk(function)
	if entry.low == entry.index {
		component := []*namespaceCallNode{}
		for {
			last := g.stack[len(g.stack)-1]
			g.stack = g.stack[:len(g.stack)-1]
			last.active = false
			component = append(component, last)
			if last == entry {
				break
			}
		}
		reaches := map[*ast.Node]*ast.Node{}
		for _, member := range component {
			for declaration, read := range member.reads {
				reaches[declaration] = read
			}
			for _, edge := range member.edges {
				for declaration, read := range edge.reaches {
					reaches[declaration] = read
				}
			}
		}
		for _, member := range component {
			member.reaches = reaches
		}
	}
	return entry
}

// Both module and namespace enums participate in the same initialization graph.
func (l *lowering) namespaceRuntimeEnum(node *ast.Node) *ast.Node {
	declaration := l.enumObject(node)
	if declaration == nil || ast.HasSyntacticModifier(declaration, ast.ModifierFlagsConst) {
		return nil
	}
	return declaration
}

namespaces_returns.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// A scalar singleton assignment returned directly can use statement IR: evaluate the
// right side once, store it, then read the same scalar before returning. No setter or
// reference conversion can make the stored value differ from the expression result.
func (l *lowering) namespaceReturnAssignment(expression *ast.Node) ([]ir.Statement, bool, error) {
	expression = ast.SkipParentheses(expression)
	if expression.Kind != ast.KindBinaryExpression || expression.AsBinaryExpression().OperatorToken.Kind != ast.KindEqualsToken {
		return nil, false, nil
	}
	target := ast.SkipParentheses(expression.AsBinaryExpression().Left)
	local, found := l.local(target)
	if !found || !l.namespaceMember(target) || (!ast.IsIdentifier(target) && target.Kind != ast.KindPropertyAccessExpression) {
		return nil, false, nil
	}
	of := l.result.Locals[local].Type
	if of != ir.Number && of != ir.Boolean {
		return nil, true, l.notYet(expression, "a returned namespace assignment with reference or optional storage; only scalar singleton assignment is proven")
	}
	statements, err := l.assignment(expression)
	if err != nil {
		return nil, true, err
	}
	value, err := l.localRead(target, local)
	if err != nil {
		return nil, true, err
	}
	return append(statements, ir.Return{Value: fit(value, l.function.Returns)}), true, nil
}

narrowed.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// A narrowing outlives a call. The checker narrows undefined out of a variable at a check (if
// (chain !== undefined)) or an assignment, and keeps the narrowing across a call that assigns the
// variable again, since it doesn't look inside the call:
//
//	let chain: Link | undefined = { value: 1 };
//	function drop(): void { chain = undefined; }
//	if (chain !== undefined) { drop(); console.log(`${chain.value}`); }
//
// Node throws a TypeError there, and native read through a null pointer; with a number | undefined,
// Node computed with undefined (NaN) and native printed a number that was never there. So a read
// used as the present type is checked, the same in both backends. Observations and slots that
// accept undefined keep the value as it is.

// narrowedAway reports whether node, a variable or a field, reads a value whose declared type has
// undefined in it while its type here doesn't. Array reads may also be past the current end.
func (l *lowering) narrowedAway(node *ast.Node) bool {
	if node.Kind == ast.KindElementAccessExpression {
		receiver := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(node.AsElementAccessExpression().Expression))
		if l.checker.IsArrayType(receiver) {
			// Even T[] can read undefined after pop, or at an index past its end.
			return !l.includesUndefined(l.checker.GetTypeAtLocation(node))
		}
	}
	at := node
	if node.Kind == ast.KindPropertyAccessExpression {
		at = node.Name()
	}
	symbol := l.checker.GetSymbolAtLocation(at)
	if symbol == nil {
		return false
	}
	declared, here := l.checker.GetTypeOfSymbol(symbol), l.checker.GetTypeAtLocation(node)
	return (l.includesUndefined(declared) && !l.includesUndefined(here)) || (l.includesNull(declared) && !l.includesNull(here))
}

// defined checks a reference the checker narrowed undefined out of. Read through a property next,
// it panics with the TypeError JavaScript throws there, word for word; anywhere else, with Adamic's
// own words, since JavaScript would go on with undefined in a place typed not to hold it.
func (l *lowering) defined(node *ast.Node, value ir.Expression) ir.Expression {
	if !value.Type().IsReference() || value.Type() == ir.Union || !l.narrowedAway(node) || l.acceptsUndefined(node) {
		return value
	}
	null := false
	at := node
	if node.Kind == ast.KindPropertyAccessExpression {
		at = node.Name()
	}
	if symbol := l.checker.GetSymbolAtLocation(at); symbol != nil {
		null = l.includesNull(l.checker.GetTypeOfSymbol(symbol))
	}
	absent := "undefined"
	if null {
		absent = "null"
	}
	message := absent + " where the checker narrowed it away: a call since the narrowing put it back"
	at = node
	for at.Parent != nil && at.Parent.Kind == ast.KindParenthesizedExpression {
		at = at.Parent
	}
	if parent := at.Parent; parent != nil && parent.Kind == ast.KindPropertyAccessExpression && parent.AsPropertyAccessExpression().Expression == at {
		if written := parent.Parent; written != nil && written.Kind == ast.KindBinaryExpression && written.AsBinaryExpression().Left == parent && written.AsBinaryExpression().OperatorToken.Kind == ast.KindEqualsToken {
			// object.name = value: JavaScript evaluates the value first and throws at the write, so
			// the check is the write's own (native checks the object there; JavaScript throws).
			return value
		}
		message = "TypeError: Cannot read properties of " + absent + " (reading '" + parent.Name().Text() + "')"
	}
	if parent := at.Parent; parent != nil && parent.Kind == ast.KindElementAccessExpression && parent.AsElementAccessExpression().Expression == at {
		key := ast.SkipParentheses(parent.AsElementAccessExpression().ArgumentExpression)
		if key.Kind == ast.KindNumericLiteral || key.Kind == ast.KindStringLiteral {
			message = "TypeError: Cannot read properties of " + absent + " (reading '" + key.Text() + "')"
		}
	}
	return ir.Defined{Value: value, Message: message, Null: null}
}

// comparedWithUndefined reports whether node is one side of === or !== with undefined on the other:
// asking whether it's there must see undefined as it is, with no check and no unwrapping.
func comparedWithUndefined(node *ast.Node) bool {
	parent := node.Parent
	for parent != nil && parent.Kind == ast.KindParenthesizedExpression {
		node, parent = parent, parent.Parent
	}
	if parent == nil || parent.Kind != ast.KindBinaryExpression {
		return false
	}
	binary := parent.AsBinaryExpression()
	if operator := binary.OperatorToken.Kind; operator != ast.KindEqualsEqualsEqualsToken && operator != ast.KindExclamationEqualsEqualsToken {
		return false
	}
	other := binary.Right
	if binary.Right == node {
		other = binary.Left
	}
	other = ast.SkipParentheses(other)
	return other.Kind == ast.KindNullKeyword || (other.Kind == ast.KindIdentifier && other.Text() == "undefined")
}

// acceptsUndefined reports when a read is observed as it is, rather than relied on as present.
// Parentheses don't change its use. The contextual type describes the receiving slot, including
// a parameter, return, initializer or assignment that can keep undefined.
func (l *lowering) acceptsUndefined(node *ast.Node) bool {
	if comparedWithUndefined(node) {
		return true
	}
	for node.Parent != nil && node.Parent.Kind == ast.KindParenthesizedExpression {
		node = node.Parent
	}
	if parent := node.Parent; parent != nil {
		switch parent.Kind {
		case ast.KindTypeOfExpression, ast.KindTemplateSpan:
			return true
		case ast.KindBinaryExpression:
			binary := parent.AsBinaryExpression()
			if binary.OperatorToken.Kind == ast.KindQuestionQuestionToken && binary.Left == node {
				return true
			}
		case ast.KindConditionalExpression:
			conditional := parent.AsConditionalExpression()
			if conditional.WhenTrue == node || conditional.WhenFalse == node {
				return l.acceptsUndefined(parent)
			}
		case ast.KindPropertyAccessExpression:
			access := parent.AsPropertyAccessExpression()
			if access.Expression == node && access.QuestionDotToken != nil {
				return true
			}
		case ast.KindElementAccessExpression:
			access := parent.AsElementAccessExpression()
			if access.Expression == node && access.QuestionDotToken != nil {
				return true
			}
		}
	}
	contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone)
	return contextual != nil && l.includesUndefined(contextual)
}

nested_functions.go:
package lower

import (
	"slices"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// nestedDeclarations binds a function body's declarations before any body is lowered.
// Sibling code shares a cell layout, never cells holding sibling closure values.
func (l *lowering) nestedDeclarations(nodes []*ast.Node) ([]ir.Statement, error) {
	if l.function == nil {
		return nil, nil
	}
	declarations := []*ast.Node{}
	for _, node := range nodes {
		if node.Kind != ast.KindFunctionDeclaration {
			continue
		}
		if node.Parent != nil && (node.Parent.Kind == ast.KindCaseClause || node.Parent.Kind == ast.KindDefaultClause) {
			// switchBindings owns the shared case environment and hoists these functions.
			continue
		}
		if node.Parent == nil || node.Parent.Kind != ast.KindBlock || !ast.IsFunctionLike(node.Parent.Parent) {
			return nil, l.notYet(node, "a block-scoped nested function declaration")
		}
		if node.Name() == nil {
			return nil, l.notYet(node, "a generic or unnamed nested function declaration")
		}
		if node.Body() == nil {
			// Overloads describe the implementation, not additional runtime functions.
			// Only skip a signature when this body contains its implementation.
			implemented := false
			for _, candidate := range nodes {
				if candidate.Kind == ast.KindFunctionDeclaration && candidate.Body() != nil && candidate.Name() != nil && l.symbol(candidate.Name()) == l.symbol(node.Name()) {
					implemented = true
					break
				}
			}
			if !implemented {
				return nil, l.notYet(node, "a nested function declaration without an implementation")
			}
			continue
		}
		for _, parameter := range node.Parameters() {
			if ast.IsIdentifier(parameter.Name()) && parameter.Name().Text() == "this" {
				return nil, l.notYet(parameter, "dynamic this in a nested function declaration")
			}
		}
		declarations = append(declarations, node)
	}
	if len(declarations) == 0 {
		return nil, nil
	}
	l.function.NestedFrame = true
	owner := l.functionIndex
	prologue := []ir.Statement{}
	// Captures of a declaration later in the source must already have a cell when
	// the hoisted functions are initialized. Noncaptured bindings emit no cell.
	for _, node := range nodes {
		if node.Kind != ast.KindVariableStatement {
			continue
		}
		for _, declaration := range node.AsVariableStatement().DeclarationList.AsVariableDeclarationList().Declarations.Nodes {
			bound, err := l.preallocateNestedBindings(declaration.Name())
			if err != nil {
				return nil, err
			}
			prologue = append(prologue, bound...)
		}
	}
	functions := []int{}
	bodies := []*ast.Node{}
	for _, node := range declarations {
		local, err := l.declareLocal(node.Name())
		if err != nil {
			return nil, err
		}
		if len(node.TypeParameters()) > 0 {
			if l.generics == nil {
				l.generics = map[*ast.Symbol]*ast.Node{}
			}
			l.generics[l.symbol(node.Name())] = node
			// Negative marks a generic declaration with direct-call instantiations only.
			l.result.Locals[local].NestedFunction = -1
			continue
		}
		index := len(l.result.Functions)
		l.result.Locals[local].NestedFunction = index + 1
		l.result.Functions = append(l.result.Functions, ir.Function{Name: node.Name().Text(), Closure: true, NestedParent: owner + 1})
		l.closureRecords = append(l.closureRecords, closureRecord{proven: l.concrete(l.checker.GetTypeAtLocation(node.Name())), function: index, node: node})
		if l.instance != nil {
			l.instance.templates = append(l.instance.templates, template{closure: index, proven: l.checker.GetTypeAtLocation(node.Name()), isClosure: true})
		}
		functions = append(functions, index)
		bodies = append(bodies, node)
		if err := l.signature(index, node, -1); err != nil {
			return nil, err
		}
		prologue = append(prologue, ir.Declare{Local: local, Value: ir.MakeClosure{Function: index}})
	}
	for position, node := range bodies {
		index := functions[position]
		// Ordinary declarations own their this. Dynamic receivers are not implemented.
		var invalid *ast.Node
		var visit ast.Visitor
		visit = func(inner *ast.Node) bool {
			if ast.IsFunctionLike(inner) && inner.Kind != ast.KindArrowFunction {
				return false
			}
			if inner.Kind == ast.KindThisKeyword && !ast.IsPartOfTypeNode(inner) {
				invalid = inner
				return true
			}
			return inner.ForEachChild(visit)
		}
		node.Body().ForEachChild(visit)
		if invalid != nil {
			return nil, l.notYet(invalid, "dynamic this in a nested function declaration")
		}
		l.closures = append(l.closures, index)
		outerThis := l.this
		l.this = -1
		err := l.lowerFunction(index, node, -1)
		l.this = outerThis
		l.closures = l.closures[:len(l.closures)-1]
		if err != nil {
			return nil, err
		}
	}
	environment := []int{}
	for _, index := range functions {
		for _, local := range l.result.Functions[index].Environment {
			if !slices.Contains(environment, local) {
				environment = append(environment, local)
			}
		}
	}
	for _, index := range functions {
		l.result.Functions[index].Environment = slices.Clone(environment)
	}
	return prologue, nil
}

func (l *lowering) nestedSibling(node *ast.Node) int {
	if !ast.IsIdentifier(node) || l.function == nil {
		return -1
	}
	local, ok := l.locals[l.symbol(node)]
	if !ok {
		return -1
	}
	index := l.result.Locals[local].NestedFunction - 1
	if index < 0 {
		return -1
	}
	parent := l.result.Functions[index].NestedParent
	if l.function.NestedParent != 0 {
		if parent == l.function.NestedParent {
			return index
		}
		return -1
	}
	if !l.function.Closure {
		return -1
	}
	// Forward only through anonymous closures in the same lexical group.
	// Crossing another named group still requires a separate binding strategy.
	boundary := -1
	for position := len(l.closures) - 1; position >= 0; position-- {
		function := l.closures[position]
		if function == parent-1 {
			boundary = position
			break
		}
		if group := l.result.Functions[function].NestedParent; group != 0 {
			if group != parent {
				return -1
			}
			boundary = position
			break
		}
	}
	for _, function := range l.closures[boundary+1:] {
		if forwarded := l.result.Functions[function].ForwardedNestedParent; forwarded != 0 && forwarded != parent {
			return -1
		}
	}
	for _, function := range l.closures[boundary+1:] {
		l.result.Functions[function].ForwardedNestedParent = parent
	}
	// Known slots propagate now; slots discovered by later sibling bodies are
	// added to every forwarding closure when the enclosing frame is completed.
	for _, captured := range l.result.Functions[index].Environment {
		l.touch(captured)
	}
	return index
}

// References use the canonical value cached weakly in the declaring frame.
// Only its cells travel between functions, never a strong sibling closure binding.
func (l *lowering) nestedReference(node *ast.Node) (ir.Expression, bool, error) {
	local, ok := l.locals[l.symbol(node)]
	if !ok || l.result.Locals[local].NestedFunction == 0 {
		return nil, false, nil
	}
	if l.result.Locals[local].NestedFunction < 0 {
		return nil, true, l.notYet(node, "a generic function as a value")
	}
	if l.result.Locals[local].Function != l.functionIndex {
		index := l.result.Locals[local].NestedFunction - 1
		l.nestedReferenceEnvironment(index)
		return ir.MakeClosure{Function: index}, true, nil
	}
	return ir.Read{Local: local, Of: ir.Closure}, true, nil
}

// A destructuring initializer keeps its source evaluation order; only the cells
// for the names it binds are allocated before hoisted closures can capture them.
func (l *lowering) preallocateNestedBindings(name *ast.Node) ([]ir.Statement, error) {
	if ast.IsIdentifier(name) {
		local, err := l.declareLocal(name)
		if err != nil {
			return nil, err
		}
		l.result.Locals[local].Preallocated = true
		return []ir.Statement{ir.Declare{Local: local, Uninitialized: true}}, nil
	}
	if name.Kind != ast.KindArrayBindingPattern && name.Kind != ast.KindObjectBindingPattern {
		return nil, l.notYet(name, "a nested function's enclosing binding pattern")
	}
	statements := []ir.Statement{}
	for _, binding := range name.AsBindingPattern().Elements.Nodes {
		if skipped(binding) {
			continue
		}
		bound, err := l.preallocateNestedBindings(binding.Name())
		if err != nil {
			return nil, err
		}
		statements = append(statements, bound...)
	}
	return statements, nil
}

// finishNestedEnvironment gives a named-declaration frame one allocation site.
// A cell view retains its entire record, so cycle analysis must see all its slots.
func (l *lowering) finishNestedEnvironment(function *ir.Function, owner int) {
	if !function.NestedFrame {
		return
	}
	function.FrameIdentity = l.result.Functions[owner].FrameIdentity
	if function.FrameIdentity > 0 {
		function.Body = append([]ir.Statement{ir.Declare{Local: function.FrameIdentity - 1, Value: ir.NumberConstant{}}}, function.Body...)
	}
	direct := map[int]bool{}
	for _, statement := range function.Body {
		if declaration, ok := statement.(ir.Declare); ok {
			direct[declaration.Local] = true
		}
	}
	for local, binding := range l.result.Locals {
		if binding.Function != owner || !binding.Captured {
			continue
		}
		if !binding.Preallocated && !direct[local] && !slices.Contains(function.Parameters, local) {
			continue
		}
		l.result.Locals[local].EnvironmentCell = true
		l.result.Locals[local].Preallocated = true
		function.FrameEnvironment = append(function.FrameEnvironment, local)
	}
	if len(function.FrameEnvironment) > 0 {
		function.Body = append([]ir.Statement{ir.AllocateEnvironment{Cells: slices.Clone(function.FrameEnvironment)}}, function.Body...)
	}
	for index := range l.result.Functions {
		target := &l.result.Functions[index]
		retains := target.NestedParent == owner+1 || target.ForwardedNestedParent == owner+1 || slices.Contains(target.ReferenceParents, owner+1)
		for _, local := range target.Environment {
			retains = retains || slices.Contains(function.FrameEnvironment, local)
		}
		if !retains {
			continue
		}
		for _, local := range function.FrameEnvironment {
			if !slices.Contains(target.Environment, local) {
				target.Environment = append(target.Environment, local)
			}
		}
	}
	// Preserve equal layouts after adding slots retained by other frame closures.
	environment := []int{}
	for _, target := range l.result.Functions {
		if target.NestedParent != owner+1 {
			continue
		}
		for _, local := range target.Environment {
			if !slices.Contains(environment, local) {
				environment = append(environment, local)
			}
		}
	}
	for index := range l.result.Functions {
		target := &l.result.Functions[index]
		if target.NestedParent == owner+1 {
			target.Environment = slices.Clone(environment)
		} else if target.ForwardedNestedParent == owner+1 || slices.Contains(target.ReferenceParents, owner+1) {
			for _, local := range environment {
				if !slices.Contains(target.Environment, local) {
					target.Environment = append(target.Environment, local)
				}
			}
		}
	}
}

nested_references.go:
package lower

import (
	"slices"

	"github.com/system-inc/adamic/internal/ir"
)

// Carry the entire referenced group through every intervening lexical closure.
// Its layout may grow when a later sibling body is lowered, so completion also
// forwards those cells. The identity cell ensures even capture-free activations
// have distinct canonical function values.
func (l *lowering) nestedReferenceEnvironment(index int) {
	owner := l.result.Functions[index].NestedParent - 1
	if l.result.Functions[owner].FrameIdentity == 0 {
		local := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: "nested_identity", Type: ir.Number, Function: owner, Captured: true, Preallocated: true})
		l.result.Functions[owner].FrameIdentity = local + 1
	}
	l.touch(l.result.Functions[owner].FrameIdentity - 1)
	for _, local := range l.result.Functions[index].Environment {
		l.touch(local)
	}
	start := 0
	for position, closure := range l.closures {
		if closure == owner {
			start = position + 1
		}
	}
	for _, closure := range l.closures[start:] {
		target := &l.result.Functions[closure]
		if !slices.Contains(target.ReferenceParents, owner+1) {
			target.ReferenceParents = append(target.ReferenceParents, owner+1)
		}
	}
}

never_branch.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

func (l *lowering) isNever(node *ast.Node) bool {
	return l.concrete(l.checker.GetTypeAtLocation(node)).Flags()&checker.TypeFlagsNever != 0
}

// A never arm has effects but no value. The typed placeholder exists only to
// satisfy the backend's branch ABI; the proven non-returning arm precedes it.
func (l *lowering) neverValue(node *ast.Node, of ir.Type) (ir.Expression, error) {
	effect, err := l.discardedValue(node)
	if err != nil {
		return nil, err
	}
	var unreachable ir.Expression = fit(ir.Undefined{}, of)
	switch of {
	case ir.Number:
		unreachable = ir.NumberConstant{}
	case ir.Boolean:
		unreachable = ir.BooleanConstant{}
	}
	return ir.Comma{Left: effect, Right: unreachable}, nil
}

func (l *lowering) logicalNever(node *ast.Node) (ir.Expression, error) {
	binary := node.AsBinaryExpression()
	left, err := l.expression(binary.Left)
	if err != nil {
		return nil, err
	}
	of, err := l.typeOf(node)
	if err != nil {
		return nil, err
	}
	right, err := l.neverValue(binary.Right, of)
	if err != nil {
		return nil, err
	}
	return ir.Logical{Left: left, Right: right, Of: of, KeepTruthy: binary.OperatorToken.Kind == ast.KindBarBarToken}, nil
}

func (l *lowering) conditionalNever(node *ast.Node, condition ir.Expression) (ir.Expression, error) {
	conditional := node.AsConditionalExpression()
	of, err := l.typeOf(node)
	if err != nil {
		return nil, err
	}
	branch := func(arm *ast.Node) (ir.Expression, error) {
		if l.isNever(arm) {
			return l.neverValue(arm, of)
		}
		value, err := l.expression(arm)
		if err != nil {
			return nil, err
		}
		return fit(value, of), nil
	}
	whenTrue, err := branch(conditional.WhenTrue)
	if err != nil {
		return nil, err
	}
	whenNot, err := branch(conditional.WhenFalse)
	if err != nil {
		return nil, err
	}
	return ir.Conditional{Condition: condition, WhenTrue: whenTrue, WhenNot: whenNot, Of: of}, nil
}

new_class_value.go:
package lower

import (
	"sort"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// newClassValue dispatches through a kept class constructor, rather than assuming
// that its result type identifies the runtime allocator. Ordinary function-based
// constructors retain their existing unsupported receiver semantics.
func (l *lowering) newClassValue(node *ast.Node) (ir.Expression, bool, error) {
	created := node.AsNewExpression()
	target := l.concrete(l.checker.GetTypeAtLocation(created.Expression))
	if len(l.checker.GetSignaturesOfType(target, checker.SignatureKindConstruct)) != 1 {
		return nil, false, nil
	}
	declarations := []*ast.Node{}
	for _, declaration := range l.classes {
		if ast.HasSyntacticModifier(declaration, ast.ModifierFlagsAbstract|ast.ModifierFlagsAmbient) {
			continue
		}
		if !l.needsStatics(declaration) {
			// Such classes currently have no first-class constructor value.
			continue
		}
		if l.checker.IsTypeAssignableTo(l.checker.GetTypeOfSymbol(l.symbol(declaration.Name())), target) {
			if len(declaration.TypeParameters()) != 0 {
				return nil, true, l.notYet(node, "a generic class constructor value")
			}
			declarations = append(declarations, declaration)
		}
	}
	if len(declarations) == 0 {
		return nil, false, nil
	}
	sort.Slice(declarations, func(i, j int) bool {
		return l.program.Where(declarations[i]) < l.program.Where(declarations[j])
	})
	type candidate struct{ identity, constructor int }
	candidates := []candidate{}
	for _, declaration := range declarations {
		signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeOfSymbol(l.symbol(declaration.Name())), checker.SignatureKindConstruct)
		if len(signatures) != 1 {
			return nil, true, l.notYet(node, "an overloaded class constructor value")
		}
		instance, err := l.instantiate(declaration, l.checker.GetReturnTypeOfSignature(signatures[0]), node)
		if err != nil {
			return nil, true, err
		}
		static, err := l.staticInstance(declaration)
		if err != nil {
			return nil, true, err
		}
		candidates = append(candidates, candidate{identity: static.class, constructor: instance.constructor})
	}
	constructor, err := l.classConstructorValue(created.Expression)
	if err != nil {
		return nil, true, err
	}
	if constructor.Type() != ir.Object {
		return nil, true, l.notYet(node, "a constructor value without class storage")
	}
	arguments := []ir.Expression{constructor}
	for _, argument := range nodesOf(created.Arguments) {
		if argument.Kind == ast.KindSpreadElement {
			return nil, true, l.notYet(argument, "a spread into a constructor value")
		}
		value, err := l.expression(argument)
		if err != nil {
			return nil, true, err
		}
		arguments = append(arguments, value)
	}
	b := l.libraryArrayBuilder(arguments)
	receiver := b.read(b.parameters[0])
	for _, candidate := range candidates {
		function := l.result.Functions[candidate.constructor]
		if len(function.Parameters) != len(arguments)-1 {
			return nil, true, l.notYet(node, "a constructor value with omitted or rest arguments")
		}
		forwarded := []ir.Expression{}
		for index, parameter := range function.Parameters {
			value := fit(b.read(b.parameters[index+1]), l.result.Locals[parameter].Type)
			if value.Type() != l.result.Locals[parameter].Type {
				return nil, true, l.notYet(node, "a constructor value argument with a different native representation")
			}
			forwarded = append(forwarded, value)
		}
		b.body = append(b.body, ir.If{
			Condition: ir.InstanceOf{Value: receiver, Class: candidate.identity, Exact: true},
			Then:      []ir.Statement{ir.Return{Value: ir.Call{Function: candidate.constructor, Arguments: forwarded, Returns: ir.Object}}},
		})
	}
	// Never silently substitute a statically guessed allocator for an unknown value.
	b.body = append(b.body, ir.Panic{Message: ir.StringConstant{Index: l.constant("a constructor value without a registered class allocator")}})
	return b.finish("class_value_new", ir.Undefined{Of: ir.Object}), true, nil
}

// Keep constructor-cache assignment inside the branch that initializes it. The
// existing general assignment lowering supplies checks and ownership. Global
// bindings use a direct helper; closed lexical initializers capture one cache cell.
func (l *lowering) classConstructorValue(node *ast.Node) (ir.Expression, error) {
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindBinaryExpression {
		return l.expression(node)
	}
	binary := node.AsBinaryExpression()
	switch binary.OperatorToken.Kind {
	case ast.KindQuestionQuestionToken, ast.KindBarBarToken:
		left, err := l.classConstructorValue(binary.Left)
		if err != nil {
			return nil, err
		}
		right, err := l.classConstructorValue(binary.Right)
		if err != nil {
			return nil, err
		}
		if left.Type() != ir.Object || right.Type() != ir.Object {
			return nil, l.notYet(node, "a constructor cache without class storage")
		}
		// A constructor object is truthy; its only falsy stored values are nullish.
		return ir.Coalesce{Value: left, Fallback: right, Of: ir.Object}, nil
	case ast.KindEqualsToken:
		target := ast.SkipParentheses(binary.Left)
		if !ast.IsIdentifier(target) {
			return nil, l.notYet(node, "a constructor-cache assignment without a known identifier binding")
		}
		local, known := l.local(target)
		if !known {
			return nil, l.notYet(node, "a constructor-cache assignment without a known identifier binding")
		}
		statements, err := l.assignment(node)
		if err != nil {
			return nil, err
		}
		if l.result.Locals[local].Type != ir.Object {
			return nil, l.notYet(node, "a constructor cache without class storage")
		}
		b := l.libraryArrayBuilder(nil)
		b.body = statements
		if !l.result.Locals[local].Global {
			// This helper captures exactly the cache cell. Require a closed initializer,
			// so no other caller local can be read from the generated closure.
			if len(statements) != 1 {
				return nil, l.notYet(node, "a lexical constructor-cache initializer with additional statements")
			}
			assignment, plain := statements[0].(ir.Assign)
			if !plain || assignment.Local != local {
				return nil, l.notYet(node, "a lexical constructor-cache initializer without a plain assignment")
			}
			closed := false
			switch value := assignment.Value.(type) {
			case ir.Read:
				closed = l.result.Locals[value.Local].Global
			case ir.Call:
				targets := l.result.CallTargets(value)
				closed = len(value.Arguments) == 0 && len(targets) > 0
				for _, target := range targets {
					initializer := l.result.Functions[target]
					closed = closed && !initializer.Closure && len(initializer.Environment) == 0
				}
			}
			if !closed {
				return nil, l.notYet(node, "a lexical constructor-cache initializer needing additional captures")
			}
			l.result.Locals[local].Captured = true
			b.finish("class_constructor_cache", b.read(local))
			function := &l.result.Functions[b.function]
			function.Closure = true
			function.Environment = []int{local}
			return ir.CallClosure{Closure: ir.MakeClosure{Function: b.function}, Returns: ir.Object}, nil
		}
		return b.finish("class_constructor_cache", b.read(local)), nil
	default:
		return l.expression(node)
	}
}

non_null.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/microsoft/TypeScript/tsc/shim/scanner"
	"github.com/system-inc/adamic/internal/ir"
	"strings"
)

// nonNull uses the same nullish test and terminal panic as ?? panic(...).
// Recover presence checks from nullable loads, but keep a checked union narrowing
// in its result representation. Calls may invalidate the original narrowing.
func (l *lowering) nonNull(node *ast.Node) (ir.Expression, error) {
	operand := node.AsNonNullExpression().Expression
	value, err := l.expression(operand)
	if err != nil {
		return nil, err
	}
	return l.nonNullValue(node, value)
}

// nonNullValue also checks an already-held assignment target read.
func (l *lowering) nonNullValue(node *ast.Node, value ir.Expression) (ir.Expression, error) {
	operand := node.AsNonNullExpression().Expression
	var err error
	for {
		switch narrowed := value.(type) {
		case ir.Unwrap:
			value = narrowed.Value
		case ir.Defined:
			value = narrowed.Value
		default:
			// Narrow and narrowing calls retain their representation and checks.
			goto stored
		}
	}
stored:
	weakOperand := false
	if target, ok := value.(ir.WeakTarget); ok {
		// A narrowed Weak may have cleared since the narrowing. This assertion owns
		// the terminal check and its diagnostic, rather than the generic Weak load.
		target.Present = false
		value, weakOperand = target, true
	}
	if property, ok := value.(ir.Property); ok && ast.SkipParentheses(operand).Kind == ast.KindPropertyAccessExpression {
		if symbol := l.checker.GetSymbolAtLocation(ast.SkipParentheses(operand).Name()); symbol != nil {
			if declared, known := l.representation(l.checker.GetTypeOfSymbol(symbol)); known {
				property.Of = declared
				value = property
			}
		}
	}
	of, err := l.typeOf(node)
	flags := l.checker.GetTypeAtLocation(operand).Flags()
	if err != nil && (flags == checker.TypeFlagsUndefined || flags == checker.TypeFlagsNull) {
		of = ir.Object
		if contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone); contextual != nil {
			if representation, known := l.representation(contextual); known {
				of = representation
			}
		}
		if of.IsMaybe() {
			of = of.Present()
		}
		if of == ir.Weak {
			of = ir.Object
		}
		if of == ir.Number || of == ir.Boolean {
			value = ir.MaybeOf{Of: ir.Maybe(of)}
		} else {
			value = ir.Undefined{Of: of}
		}
		err = nil
	}
	if err != nil {
		return nil, err
	}
	// A checked narrowing helper can already return a plain scalar. Its result
	// has no nullish representation and must never receive a pointer test.
	if value.Type() == ir.Number || value.Type() == ir.Boolean {
		l.recordNonNullCheck(node, true)
		return value, nil
	}
	proven := l.checker.GetTypeAtLocation(operand)
	if !weakOperand && !l.includesUndefined(proven) && !l.includesNull(proven) && !l.narrowedAway(ast.SkipParentheses(operand)) && !value.Type().IsMaybe() {
		if value.Type() == ir.Union && of != ir.Union {
			l.recordNonNullCheck(node, true)
			return ir.Narrow{Value: value, To: of}, nil
		}
		l.recordNonNullCheck(node, true)
		return value, nil
	}
	file := ast.GetSourceFileOfNode(node)
	text := file.Text()[scanner.GetTokenPosOfNode(node, file, false):node.End()]
	message := ir.StringConstant{Index: l.constant("non-null assertion failed at " + l.program.Where(node) + ": " + text + " is null or undefined")}
	result := ir.Expression(ir.Coalesce{Value: value, Panic: message, Of: value.Type().Present()})
	if result.Type() == ir.Union && of != ir.Union {
		result = ir.Narrow{Value: result, To: of}
	}
	l.recordNonNullCheck(node, false)
	return result, nil
}

func (l *lowering) checkedAssertionSource(node *ast.Node) bool {
	return strings.HasSuffix(l.program.FileName(ast.GetSourceFileOfNode(node)), ".ts")
}

func (l *lowering) recordNonNullCheck(node *ast.Node, proven bool) {
	counts := &l.result.NonNullChecks
	if proven {
		counts.Proven++
	} else {
		counts.Checked++
	}
	counts.Sites = append(counts.Sites, ir.NonNullCheck{Where: l.program.Where(node), Expression: sourceExpression(node), Proven: proven})
}

object.go:
package lower

import (
	"fmt"
	"math"
	"strconv"
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
)

// objectLiteral lowers { name: value, ... }, and the one spread 0.1 allows: { ...source, fields },
// where every field replaces one the source's type already has.
func (l *lowering) objectLiteral(node *ast.Node) (ir.Expression, error) {
	if literal, handled, err := l.accessorLiteral(node); handled {
		return literal, err
	}
	literal := ir.ObjectLiteral{SpreadReadiness: sourceExpression(node), Record: l.entriesRecordLiteral(node)}
	for index, property := range node.AsObjectLiteralExpression().Properties.Nodes {
		switch property.Kind {
		case ast.KindSpreadAssignment:
			if index != 0 {
				return nil, &Refused{Where: l.program.Where(property), What: "a spread after the first field", Fix: "spread once, first: { ...source, field: value } (adamic/single-spread)"}
			}
			spread, err := l.expression(property.AsSpreadAssignment().Expression)
			if err != nil {
				return nil, err
			}
			if spread.Type() != ir.Object {
				return nil, l.notYet(property, "spreading a "+typeName(spread.Type()))
			}
			literal.NoReuse = l.hasPrivateStorage(l.checker.GetTypeAtLocation(property.AsSpreadAssignment().Expression)) || l.hasAccessorStorage(l.checker.GetTypeAtLocation(property.AsSpreadAssignment().Expression))
			literal.Spread = spread
			literal.SpreadMaybeUndefined = l.includesUndefined(l.checker.GetTypeAtLocation(property.AsSpreadAssignment().Expression))
		case ast.KindMethodDeclaration:
			name, known := l.methodName(property)
			if !known {
				return nil, l.notYet(property, "an unsupported computed method")
			}
			value, err := l.objectMethod(property)
			if err != nil {
				return nil, err
			}
			literal.Fields = append(literal.Fields, ir.Field{Name: name, Value: value})
		case ast.KindPropertyAssignment, ast.KindShorthandPropertyAssignment:
			name := property.Name()
			if (ast.IsIdentifier(name) || name.Kind == ast.KindStringLiteral) && name.Text() == iteratorSlot {
				return nil, l.notYet(property, "a string field with the reserved iterator slot name")
			}
			fieldName, known := l.methodName(property)
			if !known {
				return nil, l.notYet(name, "a computed field name")
			}
			if property.Kind == ast.KindPropertyAssignment && fieldName == "__proto__" {
				return nil, &Refused{Where: l.program.Where(property), What: "__proto__ in an object literal", Fix: "JavaScript changes the prototype instead of making an own field; Adamic objects have fixed shapes and no prototype mutation"}
			}
			if property.Kind == ast.KindPropertyAssignment && l.uninitializedInitializer(property.AsPropertyAssignment().Initializer) {
				declared := l.declaredField(node, fieldName)
				if declared == 0 || declared == ir.MaybeBoolean {
					return nil, l.notYet(property, "an uninitialized object field without a supported declared slot type")
				}
				if literal.Spread != nil && !l.hasProperty(node.AsObjectLiteralExpression().Properties.Nodes[0].AsSpreadAssignment().Expression, fieldName) {
					return nil, l.notYet(property, "a spread that adds a field the source doesn't have")
				}
				value := ir.Expression(zeroValue(declared))
				if declared.IsReference() {
					value = ir.Undefined{Of: declared}
				}
				literal.Fields = append(literal.Fields, ir.Field{Name: fieldName, Value: value, Uninitialized: true})
				continue
			}
			var value ir.Expression
			var err error
			if property.Kind == ast.KindPropertyAssignment {
				value, err = l.expression(property.AsPropertyAssignment().Initializer)
			} else {
				value, err = l.shorthand(property)
			}
			if err != nil {
				return nil, err
			}
			if literal.Spread != nil && !l.hasProperty(node.AsObjectLiteralExpression().Properties.Nodes[0].AsSpreadAssignment().Expression, fieldName) {
				return nil, l.notYet(property, "a spread that adds a field the source doesn't have")
			}
			if declared := l.declaredField(node, fieldName); declared != 0 && !censusFieldSlotless(declared) {
				// Store the value as the member's slot holds it, rather than the initializer's type.
				value = fit(value, declared)
			}
			if censusFieldSlotless(value.Type()) {
				return nil, l.notYet(property, "a field holding "+typeName(value.Type()))
			}
			literal.Fields = append(literal.Fields, ir.Field{Name: fieldName, Value: value})
		default:
			return nil, l.notYet(property, describe(property)+" in an object literal")
		}
	}
	if literal.Record {
		if literal.Spread != nil {
			return nil, l.notYet(node, "a spread into record storage")
		}
		for index := range literal.Fields {
			field := &literal.Fields[index]
			if field.Value.Type() != ir.Number && field.Value.Type() != ir.Boolean && field.Value.Type() != ir.String && field.Value.Type() != ir.Union {
				return nil, l.notYet(node, "record allocation outside scalar storage")
			}
			field.Value = fit(field.Value, ir.Union)
		}
	}
	if literal.SpreadMaybeUndefined {
		empty, err := l.emptySpread(node, literal.Fields)
		if err != nil {
			return nil, err
		}
		literal.Empty = empty
	}
	return literal, nil
}

// emptySpread is the object { ...source, fields } makes when source is undefined: JavaScript's is
// only the literal's own fields, and a read of any other field the source's type has is undefined,
// so each of those is there, undefined. A field that can hold undefined only as a pair (a boolean),
// or that keeps a handle (a Weak), says NotYet.
func (l *lowering) emptySpread(node *ast.Node, own []ir.Field) ([]ir.Field, error) {
	spread := node.AsObjectLiteralExpression().Properties.Nodes[0]
	given := map[string]bool{}
	for _, field := range own {
		given[field.Name] = true
	}
	empty := []ir.Field{}
	source := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(spread.AsSpreadAssignment().Expression))
	for _, property := range l.checker.GetPropertiesOfType(source) {
		if given[property.Name] {
			continue
		}
		fieldType, _ := l.representation(l.checker.GetTypeOfSymbol(property))
		switch fieldType {
		case ir.Number, ir.MaybeNumber:
			empty = append(empty, ir.Field{Name: property.Name, Value: ir.MaybeOf{Of: ir.MaybeNumber}})
		case ir.String, ir.Object, ir.Array, ir.Map, ir.Closure:
			empty = append(empty, ir.Field{Name: property.Name, Value: ir.Undefined{}})
		default:
			return nil, l.notYet(spread, "spreading a value that may be undefined, whose field "+property.Name+" can't be left undefined yet")
		}
	}
	return empty, nil
}

// typeOfSymbol is what's left at runtime of a symbol's declared type, or NotYet at node.
func (l *lowering) typeOfSymbol(node *ast.Node, symbol *ast.Symbol) (ir.Type, error) {
	declared := l.checker.GetTypeOfSymbol(symbol)
	if valueType, isKnown := l.representation(declared); isKnown {
		return valueType, nil
	}
	return 0, l.notYet(node, "a value of type "+l.checker.TypeToString(declared))
}

// declaredField is the representation of a field as the type an object literal is written into
// declares it, or 0 when there is no such type to say.
func (l *lowering) declaredField(literal *ast.Node, name string) ir.Type {
	contextual := l.checker.GetContextualType(literal, checker.ContextFlagsNone)
	if contextual == nil {
		return 0
	}
	if contextual.Flags()&checker.TypeFlagsUnion != 0 {
		// The union's combined property can hold unrelated types. The literal belongs to a
		// member, whose fields are what reads after discriminant narrowing expect.
		made := l.checker.GetTypeAtLocation(literal)
		var shared ir.Type
		for _, member := range contextual.Types() {
			if !l.checker.IsTypeAssignableTo(made, member) {
				continue
			}
			field := l.checker.GetPropertyOfType(member, name)
			if field == nil {
				continue
			}
			declared, _ := l.representation(l.checker.GetTypeOfSymbol(field))
			if shared != 0 && shared != declared {
				return 0
			}
			shared = declared
		}
		return shared
	}
	field := l.checker.GetPropertyOfType(contextual, name)
	if field == nil {
		return 0
	}
	declared, _ := l.representation(l.checker.GetTypeOfSymbol(field))
	return declared
}

// hasProperty reports whether a value's type has a field of that name.
func (l *lowering) hasProperty(node *ast.Node, name string) bool {
	// A source that may be undefined has its fields where it's there.
	for _, property := range l.checker.GetPropertiesOfType(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(node))) {
		if property.Name == name {
			return true
		}
	}
	return false
}

func (l *lowering) arrayLiteral(node *ast.Node) (ir.Expression, error) {
	if tuple := l.tupleType(node); tuple != nil {
		return l.tupleLiteral(node, tuple)
	}
	element, err := l.elementType(node)
	if err != nil {
		return nil, err
	}
	literal := ir.ArrayLiteral{Element: element}
	items := node.AsArrayLiteralExpression().Elements.Nodes
	if contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone); contextual != nil && l.checker.IsArrayType(contextual) {
		declared, known := l.representation(l.checker.GetElementTypeOfArrayType(contextual))
		if !known || declared != element {
			for _, item := range items {
				if item.Kind == ast.KindSpreadElement {
					if plan, err := l.planIteration(item.AsSpreadElement().Expression); err != nil {
						return nil, err
					} else if plan != nil {
						return nil, l.notYet(node, "a custom spread whose element representation differs from its destination")
					}
				}
			}
		}
	}

	if len(items) == 1 && items[0].Kind == ast.KindSpreadElement && !l.checker.IsArrayType(l.checker.GetTypeAtLocation(items[0].AsSpreadElement().Expression)) {
		// [...text] is the text's code points, [...set] its elements, [...map] its entries, and
		// [...map.keys()] and the rest what they give (collections.go).
		spread, given, err := l.iterated(items[0].AsSpreadElement().Expression)
		if err == nil && given != element {
			return nil, l.notYet(node, "a spread whose element representation differs from its destination")
		}
		return spread, err
	}
	spreads := false
	for _, item := range items {
		if item.Kind == ast.KindOmittedExpression {
			return nil, l.notYet(item, describe(item)+" in an array literal")
		}
		spread := item.Kind == ast.KindSpreadElement
		if spread {
			item = item.AsSpreadElement().Expression
		}
		var value ir.Expression
		if spread {
			value, _, err = l.iterated(item)
		} else {
			value, err = l.expression(item)
		}
		if err != nil {
			return nil, err
		}
		if spread {
			if value.Type() != ir.Array {
				return nil, l.notYet(item, "spreading a "+typeName(value.Type())+" among other elements")
			}
			if _, other, err := l.iteratedType(item); err != nil || other != element {
				return nil, l.notYet(item, "spreading an array of other elements")
			}
			spreads = true
		} else {
			// An element of number | undefined is a packed word: a number or undefined is made one.
			value = fit(value, element)
		}
		literal.Elements = append(literal.Elements, value)
		literal.Spread = append(literal.Spread, spread)
	}
	if !spreads {
		literal.Spread = nil
	}
	return literal, nil
}

// elementType is the representation of an array's elements, from the checker's type for the node.
func (l *lowering) elementType(node *ast.Node) (ir.Type, error) {
	arrayType := l.checker.GetNonNullableType(l.concrete(l.arrayPredicateType(node)))
	if l.nodeBufferType(arrayType, "Buffer") {
		return ir.Number, nil
	}
	if l.isLibraryType(arrayType, "RegExpExecArray", "RegExpMatchArray") {
		return ir.String, nil
	}
	if l.isLibraryType(arrayType, "RegExpIndicesArray") {
		return ir.Object, nil
	}
	if literal := ast.SkipParentheses(node); literal.Kind == ast.KindArrayLiteralExpression {
		// A fresh [] has no slots yet. Use the same contextual element path as
		// generic returns; nested literals also have a best-common destination.
		if len(literal.AsArrayLiteralExpression().Elements.Nodes) == 0 {
			contexts := []*checker.Type{l.checker.GetContextualType(literal, checker.ContextFlagsNone)}
			child := literal
			for child.Parent != nil && child.Parent.Kind == ast.KindParenthesizedExpression {
				child = child.Parent
			}
			if parent := child.Parent; parent != nil && parent.Kind == ast.KindArrayLiteralExpression {
				// The checker can leave the inner literal as never[] even when
				// the enclosing array has an explicit union-of-arrays destination.
				contexts = append(contexts, l.literalArrayElement(l.checker.GetContextualType(parent, checker.ContextFlagsNone)))
			}
			contexts = append(contexts, l.impliedTarget(literal))
			for _, contextual := range contexts {
				if element := l.literalArrayElement(contextual); element != nil {
					if held, known := l.kept(element); known && !slotless(held) {
						return held, nil
					}
				}
			}
		} else if contextual := l.checker.GetContextualType(literal, checker.ContextFlagsNone); contextual != nil && l.checker.IsArrayType(contextual) {
			// Keep every proven nonempty contextual element representation, including weak handles.
			if declared, _ := l.representation(l.checker.GetElementTypeOfArrayType(contextual)); declared != 0 && !slotless(declared) {
				arrayType = contextual
			}
		}
	}
	if target := l.weakTarget(arrayType); target != nil {
		// A Weak<Node[]> narrowed to present is the array.
		arrayType = target
	}
	if !l.checker.IsArrayType(arrayType) {
		return 0, l.notYet(node, "a value of type "+l.checker.TypeToString(arrayType)+" where an array goes")
	}
	element := l.checker.GetElementTypeOfArrayType(arrayType)
	if element.Flags()&checker.TypeFlagsUnknown != 0 {
		return 0, l.notYet(node, "an array of unknown with erased element storage (retain its declared element type before reading elements)")
	}
	valueType, isKnown := l.kept(element)
	if !isKnown || (slotless(valueType) && valueType != ir.Union) {
		// An element is one adamic_value, and number | undefined needs two words.
		return 0, l.notYet(node, "an array of "+l.checker.TypeToString(element))
	}
	return valueType, nil
}

// property lowers object.name, array.length, and Math's constants.
func (l *lowering) property(node *ast.Node) (ir.Expression, error) {
	if err := l.staticProperty(node); err != nil {
		return nil, err
	}
	if call, handled, err := l.superAccessor(node, nil); handled {
		return call, err
	}
	access := node.AsPropertyAccessExpression()
	if l.entriesStringIndexed(access.Expression) && l.checker.GetPropertyOfType(l.checker.GetTypeAtLocation(access.Expression), node.Name().Text()) == nil && l.entriesProgramHasRecords() {
		return nil, l.notYet(node, "an indexed record field read without a named declared property")
	}
	name := l.fieldName(node.Name())
	if _, iterator := l.libraryIteratorElement(access.Expression); iterator && name != "next" {
		return nil, l.notYet(node, "a collection iterator property other than next")
	}
	if access.QuestionDotToken == nil && node.Flags&ast.NodeFlagsOptionalChain != 0 {
		// The rest of a chain after a ?., which short-circuits with it.
		return nil, l.notYet(node, "an optional chain longer than one step")
	}
	if value, known := l.libraryMathNumberProperty(node); known {
		return value, nil
	}
	if l.isLibraryGlobal(access.Expression, "Math") {
		switch name {
		case "PI":
			return ir.NumberConstant{Value: 3.141592653589793}, nil
		case "E":
			return ir.NumberConstant{Value: 2.718281828459045}, nil
		case "random":
			return nil, refusedRandom(l, node)
		}
		return nil, l.notYet(node, "Math."+name)
	}
	if l.isLibraryGlobal(access.Expression, "Number") {
		if value, isConstant := numberConstants[name]; isConstant && name != "Infinity" {
			return ir.NumberConstant{Value: value}, nil
		}
		return nil, l.notYet(node, "Number."+name)
	}
	// A library declaration proves a prototype member exists, never an own slot. Keep this
	// guard in lowering too, even when the up-front unbound-method pass has already refused it.
	if l.inheritedLibraryMember(node) && !l.regexRuntimeProperty(access.Expression, name) && name != "length" && name != "size" && !(l.isLibraryType(l.checker.GetTypeAtLocation(access.Expression), "Error") && (name == "name" || name == "message")) {
		return nil, l.prototypeRead(node, name)
	}
	if err := l.erasedLiteralMethod(node); err != nil {
		return nil, err
	}
	if read := l.checker.GetSymbolAtLocation(node.Name()); read != nil && len(read.Declarations) > 0 && read.Declarations[0].Kind == ast.KindMethodDeclaration && !isCallee(node) {
		// A method read off its object, not called: JavaScript loses its this (unbound-method,
		// docs/0.1.md). A plain call never comes here, since callOrMethod lowers it; object?.method()
		// reads it as its call's callee, through the object's methods, and keeps its this.
		object := "object"
		if receiver := ast.SkipParentheses(access.Expression); ast.IsIdentifier(receiver) {
			object = receiver.Text()
		} else if receiver.Kind == ast.KindThisKeyword {
			object = "this"
		}
		return nil, &Refused{
			Where: l.program.Where(node),
			What:  "a method read off its object, which loses its this when called (unbound-method)",
			Fix:   fmt.Sprintf("wrap the call in an arrow function, which keeps its object: (value) => %s.%s(value)", object, name),
		}
	}
	if receiver := l.checker.GetTypeAtLocation(access.Expression); name != "length" && (checker.IsTupleType(receiver) || checker.IsTupleType(l.checker.GetNonNullableType(receiver))) {
		// A tuple is held as an object of its elements, "0", "1", ..., read by index; an array's
		// methods aren't fields of it, and reading them as fields would find nothing. Its length is
		// read below (tupleLength).
		return nil, l.notYet(node, "."+name+" on a tuple")
	}
	object, err := l.expression(access.Expression)
	if err != nil {
		return nil, err
	}
	if object.Type() == ir.Union {
		return l.dynamicProperty(node, object, name)
	}
	if field := l.checker.GetSymbolAtLocation(node.Name()); field != nil && l.checker.GetTypeOfSymbol(field).Flags()&checker.TypeFlagsUnknown != 0 {
		return l.dynamicProperty(node, fit(object, ir.Union), name)
	}
	if object.Type() == ir.Object && l.isLibraryType(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(access.Expression)), "RegExp") {
		switch name {
		case "lastIndex", "source", "flags", "global", "ignoreCase", "multiline", "unicode", "sticky", "hasIndices", "unicodeSets", "dotAll":
		default:
			return nil, l.notYet(node, "a prototype property on a RegExp")
		}
	}
	if object.Type() == ir.Object && l.regexGroups(access.Expression) {
		of, err := l.typeOf(node)
		if err != nil {
			return nil, err
		}
		if of != ir.String && of != ir.Object {
			return nil, l.notYet(node, "a named-group key with an Object-prototype type")
		}
		return ir.RegExpGroup{Object: object, Name: name, Of: of, Optional: access.QuestionDotToken != nil}, nil
	}
	if object.Type() == ir.Object && name == "done" {
		proven := l.checker.GetTypeAtLocation(access.Expression)
		members := []*checker.Type{proven}
		if proven.Flags()&checker.TypeFlagsUnion != 0 {
			members = proven.Types()
		}
		iterator := true
		for _, member := range members {
			iterator = iterator && l.isLibraryType(member, "IteratorYieldResult", "IteratorReturnResult")
		}
		if iterator {
			of, e := l.typeOf(node)
			return ir.RegExpCall{Value: object, Method: "iteratorDone", Returns: of}, e
		}
	}
	object = l.privateStaticReceiver(node.Name(), object, false)
	if access.QuestionDotToken != nil && (object.Type() == ir.Array || object.Type() == ir.String) && name == "length" {
		// words?.length and text?.length: undefined where the array or string is, a number | undefined.
		if object.Type() == ir.Array {
			return ir.Length{Array: object, Optional: true}, nil
		}
		return ir.StringLength{Value: object, Optional: true}, nil
	}
	if object.Type() == ir.Array && name != "length" && l.isLibraryType(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(access.Expression)), "RegExpExecArray", "RegExpMatchArray", "RegExpIndicesArray") {
		of, e := l.typeOf(node)
		if e != nil {
			return nil, e
		}
		switch name {
		case "index", "input", "groups", "indices":
		default:
			return nil, l.notYet(node, "a prototype property on a RegExp result")
		}
		stored := of
		if name == "index" {
			if l.isLibraryType(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(access.Expression)), "RegExpMatchArray") {
				stored = ir.MaybeNumber
			} else {
				stored = ir.Number
			}
		}
		result := ir.Expression(ir.RegExpProperty{Array: object, Name: name, Of: stored, Optional: access.QuestionDotToken != nil})
		if stored == ir.MaybeNumber && of == ir.Number {
			result = ir.Unwrap{Value: result}
		}
		return result, nil
	}
	if access.QuestionDotToken != nil && object.Type() != ir.Object {
		return nil, l.notYet(node, "optional chaining to ."+name+" on a "+typeName(object.Type()))
	}
	switch {
	case object.Type() == ir.Array && name == "length":
		return ir.Length{Array: object}, nil
	case object.Type() == ir.String && name == "length":
		return ir.StringLength{Value: object}, nil
	case object.Type() == ir.Map && name == "size":
		return ir.MapSize{Map: object}, nil
	case object.Type() == ir.Object && name == "length" && checker.IsTupleType(l.checker.GetTypeAtLocation(access.Expression)):
		// A tuple is an object of fields "0", "1" and on, with no length to read; a fixed one's length
		// is its type's, read here when nothing about reading the tuple itself could be seen.
		return l.tupleLength(node, access.Expression)
	case object.Type() == ir.Object:
		if field := l.checker.GetSymbolAtLocation(node.Name()); field != nil {
			if declared, _ := l.representation(l.checker.GetTypeOfSymbol(field)); declared == ir.Weak {
				// The field keeps a handle, whatever the checker narrowed the read to.
				return l.readObjectField(node, ir.Property{Object: object, Name: name, Of: ir.Weak, Optional: access.QuestionDotToken != nil}), nil
			}
		}
		if field := l.checker.GetSymbolAtLocation(node.Name()); field != nil && (accessorSymbol(field) || (l.accessorNames[node.Name().Text()] && !isClassInstance(l.checker.GetTypeAtLocation(access.Expression)) && ast.SkipParentheses(access.Expression).Kind != ast.KindThisKeyword)) {
			declared := l.checker.GetTypeOfSymbol(field)
			observed := l.checker.GetTypeAtLocation(node)
			if !l.classAssignable(declared, observed) {
				return nil, &Refused{Where: l.program.Where(node), What: "a narrowed accessor reread, which can return a different value", Fix: "read the getter into a local once, then narrow and use that local"}
			}
		}
		of, err := l.typeOf(node)
		if err != nil && l.checker.GetTypeAtLocation(node).Flags()&checker.TypeFlagsUndefined != 0 {
			// Narrowed to undefined (just assigned it): read as the field is declared.
			if field := l.checker.GetSymbolAtLocation(node.Name()); field != nil {
				of, err = l.typeOfSymbol(node, field)
			}
		}
		if err != nil {
			return nil, err
		}
		optional := access.QuestionDotToken != nil
		if field := l.checker.GetSymbolAtLocation(node.Name()); field != nil {
			if stored, known := l.representation(l.checker.GetTypeOfSymbol(field)); known && stored == ir.Union && of != ir.Union && !of.IsReference() {
				return nil, l.notYet(node, "a narrowed scalar in a boxed union field")
			}
			if stored, known := l.representation(l.checker.GetTypeOfSymbol(field)); known && stored.IsMaybe() && of == stored.Present() {
				// Read the declared representation before trusting the narrowing. A call or an
				// alias write may have restored undefined, just as for a narrowed variable.
				if censusFieldSlotless(stored) {
					return nil, l.notYet(node, "a narrowed boolean | undefined field; copy the field into a local and narrow that local instead")
				}
				read := l.readObjectField(node, ir.Property{Object: object, Name: name, Of: stored, Optional: optional, Class: l.classOf(node)})
				if l.acceptsUndefined(node) {
					return read, nil
				}
				return ir.Unwrap{Value: read}, nil
			}
		}
		if (of == ir.Union || of.IsMaybe()) && l.entriesProgramHasRecords() {
			return nil, l.notYet(node, "a union or optional field read in a program with record storage")
		}
		if of.IsMaybe() && optional {
			// box?.size is number | undefined because box may be; the field itself is what's stored.
			if field := l.checker.GetSymbolAtLocation(node.Name()); field != nil {
				if stored, isKnown := l.representation(l.checker.GetTypeOfSymbol(field)); isKnown && stored == of.Present() {
					return l.readObjectField(node, ir.Property{Object: object, Name: name, Of: stored, Optional: true, Class: l.classOf(node)}), nil
				}
			}
		}
		if symbol := l.checker.GetSymbolAtLocation(node.Name()); symbol != nil {
			id := l.result.ViewContractTypes[int(l.checker.GetTypeOfSymbol(symbol).Id())]
			if id > 0 && strings.Contains(l.result.ViewContracts[id-1].Unsupported, "views-v3: array element kind") {
				return nil, l.notYet(node, "checked view union arm awaits "+l.result.ViewContracts[id-1].Unsupported)
			}
		}
		if censusFieldSlotless(of) && !l.unionReadCertificate(node, of) {
			return nil, l.notYet(node, "a field of type "+l.checker.TypeToString(l.checker.GetTypeAtLocation(node)))
		}
		if of.IsMaybe() {
			// number | undefined, whether the field holds it or ?. makes it: the packed word, or
			// undefined when the object is.
			return l.readObjectField(node, ir.Property{Object: object, Name: name, Of: of, Optional: optional, Class: l.classOf(node)}), nil
		}
		if optional && !of.IsReference() {
			return nil, l.notYet(node, "?. to a "+typeName(of)+", which would be "+typeName(of)+" | undefined")
		}
		return l.defined(node, l.readObjectField(node, ir.Property{Object: object, Name: name, Of: of, Optional: optional, Class: l.classOf(node)})), nil
	}
	return nil, l.notYet(node, "."+name+" on a "+typeName(object.Type()))
}

// readObjectField keeps an optional own field distinct from optional chaining of its receiver.
// Absence is a read result, never a synthetic own field: hasOwnProperty and object spread still see
// the shape that was actually made. A narrowed number checks the declared optional representation.
func (l *lowering) readObjectField(node *ast.Node, property ir.Property) ir.Expression {
	property.Readiness = sourceExpression(node)
	property.View = sourceExpression(node)
	property.ViewWhere = l.program.Where(node)
	if node.Kind == ast.KindPropertyAccessExpression {
		property.ViewReceiverTypeID = int(l.checker.GetTypeAtLocation(node.AsPropertyAccessExpression().Expression).Id())
	}
	if symbol := l.checker.GetSymbolAtLocation(node.Name()); symbol != nil {
		declared := l.checker.GetTypeOfSymbol(symbol)
		property.ViewTypeID = int(declared.Id())
		property.ViewContract = l.result.ViewContractTypes[property.ViewTypeID]
		property.ViewType = l.checker.TypeToString(declared)
		property.ViewAllowed = l.viewLiterals(declared)
	}
	field := l.checker.GetSymbolAtLocation(node.Name())
	if field != nil {
		for _, declaration := range field.Declarations {
			if declaration.Kind == ast.KindPropertyDeclaration {
				initializer := declaration.AsPropertyDeclaration().Initializer
				if l.lazyAssertionInitializer(initializer) && !l.uninitializedInitializer(initializer) {
					property.Readiness = sourceExpression(initializer)
				}
			}
		}
	}
	if field == nil || field.Flags&ast.SymbolFlagsOptional == 0 {
		return property
	}
	property.Absent = true
	if declared, _ := l.representation(l.checker.GetTypeOfSymbol(field)); declared.IsMaybe() && property.Of == declared.Present() {
		property.Of = declared
		return fit(property, declared.Present())
	}
	return property
}

// hasOwnProperty lowers object.hasOwnProperty(key) when the method is the library's, not a field the
// object declares. The checker puts Object's prototype methods on every object's type. The shape
// holds only the object's own fields, and reading hasOwnProperty as one of them panics: the field
// the checker proved is not there.
func (l *lowering) hasOwnProperty(node *ast.Node, receiver *ast.Node) (ir.Expression, bool, error) {
	return l.hasOwnPropertyArguments(node, receiver, node.AsCallExpression().Arguments.Nodes)
}

func (l *lowering) hasOwnPropertyArguments(node *ast.Node, receiver *ast.Node, arguments []*ast.Node) (ir.Expression, bool, error) {
	callee := ast.SkipParentheses(node.AsCallExpression().Expression)
	symbol := l.checker.GetSymbolAtLocation(callee)
	if symbol == nil || len(symbol.Declarations) == 0 || !load.IsLibrary(ast.GetSourceFileOfNode(symbol.Declarations[0])) {
		return nil, false, nil
	}
	if len(arguments) != 1 {
		return nil, true, l.notYet(node, "hasOwnProperty with other than one argument")
	}
	if keyType, _ := l.representation(l.checker.GetTypeAtLocation(arguments[0])); keyType != ir.String {
		return nil, true, l.notYet(node, "hasOwnProperty with a key that isn't a string")
	}
	// JavaScript's order: the object, then the key.
	object, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	key, err := l.expression(arguments[0])
	if err != nil {
		return nil, true, err
	}
	return ir.HasOwn{Object: object, Key: key}, true, nil
}

// isLibraryGlobal reports whether a node names one of the library's globals, rather than something
// of the program's that happens to share its name.
func (l *lowering) isLibraryGlobal(node *ast.Node, name string) bool {
	node = ast.SkipParentheses(node)
	if !ast.IsIdentifier(node) || node.Text() != name {
		return false
	}
	symbol := l.checker.GetSymbolAtLocation(node)
	return symbol != nil && len(symbol.Declarations) > 0 && load.IsLibrary(ast.GetSourceFileOfNode(symbol.Declarations[0]))
}

// mathFunctions are the Math functions 0.1 has (docs/0.1.md), with how many arguments each takes;
// -1 is any number.
var mathFunctions = map[string]int{
	"abs": 1, "ceil": 1, "floor": 1, "round": 1, "trunc": 1, "sign": 1, "sqrt": 1,
	"pow": 2, "max": -1, "min": -1,
	// V8's fdlibm, ported bit for bit (runtime/ieee754.c), and its hypot (runtime/hypot.c).
	"sin": 1, "cos": 1, "tan": 1, "asin": 1, "acos": 1, "atan": 1, "atan2": 2,
	"sinh": 1, "cosh": 1, "tanh": 1, "asinh": 1, "acosh": 1, "atanh": 1,
	"exp": 1, "expm1": 1, "log": 1, "log1p": 1, "log2": 1, "log10": 1, "cbrt": 1, "hypot": -1,
}

// refusedRandom refuses Math.random for good in 0.1: a program's output would no longer be a function
// of its source, and the oracle compares it with Node's byte for byte (docs/0.1.md).
func refusedRandom(l *lowering, node *ast.Node) error {
	return &Refused{Where: l.program.Where(node), What: "Math.random", Fix: "0.1 programs are deterministic, so the oracle can hold them to Node; compute the values you need, with a generator of your own seeded by a constant"}
}

// builtin lowers a call to Math or a number's toFixed. isBuiltin is false for any other call.
func (l *lowering) builtin(node *ast.Node) (ir.Expression, bool, error) {
	if value, known, err := l.arrayIsArray(node); known {
		return value, known, err
	}
	if l.isOptionalJoin(node) {
		value, err := l.optionalJoin(node)
		return value, true, err
	}
	if value, handled, err := l.libraryNodeBuffer(node); handled {
		return value, true, err
	}
	if value, handled, err := l.userMethodCall(node); handled {
		return value, true, err
	}
	if value, known, err := l.libraryEmptyMap(node); known {
		return value, true, err
	}
	if value, known, err := l.libraryMethodCall(node); known {
		return value, true, err
	}
	if value, known, err := l.libraryMathNumberCall(node); known {
		return value, true, err
	}
	if lowered, isString, err := l.libraryString(node); isString {
		return lowered, true, err
	}
	if value, matched, err := l.regexBuiltin(node); matched {
		return value, true, err
	}
	if value, handled, err := l.objectKeys(node); handled {
		return value, true, err
	}
	if lowered, isInput, err := l.input(node); isInput {
		return lowered, true, err
	}
	callee := ast.SkipParentheses(node.AsCallExpression().Expression)
	// The global parseInt and parseFloat are Number's, the same functions.
	if l.isLibraryGlobal(callee, "parseInt") || l.isLibraryGlobal(callee, "parseFloat") {
		return l.numberCall(node, callee.Text())
	}
	if callee.Kind != ast.KindPropertyAccessExpression {
		return nil, false, nil
	}
	receiver, name := callee.AsPropertyAccessExpression().Expression, callee.Name().Text()
	if l.isLibraryGlobal(receiver, "Object") {
		return l.objectCall(node, name)
	}
	if lowered, handled, err := l.objectPrototypeCall(node, receiver, name); handled {
		return lowered, true, err
	}
	if l.isLibraryGlobal(receiver, "JSON") {
		return l.jsonCall(node, name)
	}
	if l.isLibraryGlobal(receiver, "Number") {
		return l.numberCall(node, name)
	}
	if l.isLibraryGlobal(receiver, "Map") && name == "groupBy" {
		return l.libraryMapGroupBy(node)
	}
	if l.isLibraryGlobal(receiver, "Array") && name == "from" {
		return l.arrayFrom(node)
	}
	if l.isLibraryGlobal(receiver, "String") && (name == "fromCharCode" || name == "fromCodePoint") {
		return l.stringFromCodes(node, name == "fromCodePoint")
	}
	if receiverType, _ := l.representation(l.checker.GetTypeAtLocation(receiver)); receiverType == ir.Number && name == "toString" && len(node.AsCallExpression().Arguments.Nodes) == 0 {
		value, err := l.expression(receiver)
		if err != nil {
			return nil, true, err
		}
		return ir.NumberToString{Value: value}, true, nil
	}
	if receiverType, _ := l.representation(l.checker.GetTypeAtLocation(receiver)); receiverType == ir.Number && (name == "toExponential" || name == "toPrecision" || name == "toString") {
		return l.numberFormat(node, receiver, name)
	}
	isMath := l.isLibraryGlobal(receiver, "Math")
	receiverType, _ := l.representation(l.checker.GetTypeAtLocation(receiver))
	isToFixed := name == "toFixed" && receiverType == ir.Number
	if receiverType == ir.Array && name == "pop" && len(node.AsCallExpression().Arguments.Nodes) == 0 {
		element, err := l.elementType(receiver)
		if err != nil {
			return nil, true, err
		}
		array, err := l.expression(receiver)
		if err != nil {
			return nil, true, err
		}
		return ir.ArrayPop{Array: array, Element: element}, true, nil
	}
	if receiverType == ir.Array && libraryArrayMethods[name] {
		return l.libraryArrayMethod(node, receiver, name)
	}
	if _, isVisit := visits[name]; receiverType == ir.Array && (isVisit || arrayMethods[name]) {
		return l.arrayMethod(node, receiver, name)
	}
	if receiverType == ir.Map && (name == "keys" || name == "values" || name == "entries") {
		return l.libraryCollectionIterator(node, receiver, name)
	}
	if receiverType == ir.Map && l.isSet(receiver) {
		return l.setMethod(node, receiver, name)
	}
	if receiverType == ir.Map && (name == "clear" || name == "forEach") {
		return l.clearOrVisit(node, receiver, name, false)
	}
	if receiverType == ir.Map && (name == "get" || name == "set" || name == "has" || name == "delete") {
		return l.mapMethod(node, receiver, name)
	}
	if receiverType == ir.String && (name == "trim" || name == "charCodeAt") {
		return l.stringMethod(node, receiver, name)
	}
	if _, isKnown := stringMethods[name]; isKnown && receiverType == ir.String {
		return l.stringCall(node, receiver, name)
	}
	if receiverType == ir.Object && checker.IsTupleType(l.checker.GetTypeAtLocation(receiver)) {
		// A tuple is held as an object: called as an object, an array method would be read as a field.
		return nil, true, l.notYet(node, name+" on a tuple (a tuple is held as an object, not an array, so far; write it as an array where it's made)")
	}
	if !isMath && !isToFixed {
		return nil, false, nil
	}
	// JavaScript's order: the receiver, then the arguments.
	var value ir.Expression
	if isToFixed {
		var err error
		if value, err = l.expression(receiver); err != nil {
			return nil, true, err
		}
	}
	if isMath && (name == "max" || name == "min" || name == "hypot") && hasSpread(node) {
		spread, err := l.spreadNumbers(node)
		if err != nil {
			return nil, true, err
		}
		return ir.MathCall{Function: name, Spread: spread}, true, nil
	}
	arguments := []ir.Expression{}
	for _, argument := range node.AsCallExpression().Arguments.Nodes {
		if argument.Kind == ast.KindSpreadElement {
			return nil, true, l.notYet(argument, "a spread argument to "+name)
		}
		lowered, err := l.expression(argument)
		if err != nil {
			return nil, true, err
		}
		if lowered.Type() != ir.Number {
			return nil, true, l.notYet(argument, "a "+typeName(lowered.Type())+" argument to "+name)
		}
		arguments = append(arguments, lowered)
	}
	if isMath {
		count, isKnown := mathFunctions[name]
		if name == "random" {
			return nil, true, refusedRandom(l, node)
		}
		if !isKnown {
			return nil, true, l.notYet(node, "Math."+name)
		}
		if count >= 0 && len(arguments) != count {
			return nil, true, l.notYet(node, "Math."+name+" with other than its arguments")
		}
		return ir.MathCall{Function: name, Arguments: arguments}, true, nil
	}
	if len(arguments) > 1 {
		return nil, true, l.notYet(node, "toFixed with more than one argument")
	}
	digits := ir.Expression(ir.NumberConstant{Value: 0})
	if len(arguments) == 1 {
		digits = arguments[0]
	}
	return ir.ToFixed{Value: value, Digits: digits}, true, nil
}

// numberFormat lowers value.toExponential(digits), value.toPrecision(digits) and
// value.toString(radix), the argument perhaps left out: the receiver first, then the argument, as
// JavaScript evaluates them.
func (l *lowering) numberFormat(node *ast.Node, receiver *ast.Node, name string) (ir.Expression, bool, error) {
	value, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	arguments := node.AsCallExpression().Arguments.Nodes
	if len(arguments) > 1 {
		return nil, true, l.notYet(node, name+" with more than one argument")
	}
	format := ir.NumberFormat{Method: name, Value: value}
	if len(arguments) == 1 {
		argument, err := l.expression(arguments[0])
		if err != nil {
			return nil, true, err
		}
		if argument.Type() != ir.Number {
			return nil, true, l.notYet(arguments[0], "a "+typeName(argument.Type())+" argument to "+name)
		}
		format.Argument = argument
	}
	return format, true, nil
}

// numberFunctions are the functions of Number that 0.1 has (docs/0.1.md), with what each takes; the
// last of parseInt's, the radix, may be left out.
var numberFunctions = map[string][]ir.Type{
	"parseInt": {ir.String, ir.Number}, "parseFloat": {ir.String},
	"isNaN": {ir.Number}, "isFinite": {ir.Number}, "isInteger": {ir.Number}, "isSafeInteger": {ir.Number},
}

// numberCall lowers Number.parseInt, parseFloat, isNaN, isFinite, isInteger and isSafeInteger.
func (l *lowering) numberCall(node *ast.Node, name string) (ir.Expression, bool, error) {
	return l.numberCallArguments(node, name, node.AsCallExpression().Arguments.Nodes)
}

func (l *lowering) numberCallArguments(node *ast.Node, name string, written []*ast.Node) (ir.Expression, bool, error) {
	takes, isKnown := numberFunctions[name]
	if !isKnown {
		return nil, true, l.notYet(node, "Number."+name)
	}
	optional := 0
	if name == "parseInt" {
		optional = 1
	}
	if len(written) > len(takes) || len(written) < len(takes)-optional {
		return nil, true, l.notYet(node, name+" with these arguments")
	}
	arguments := []ir.Expression{}
	for index, argument := range written {
		lowered, err := l.expression(argument)
		if err != nil {
			return nil, true, err
		}
		if lowered.Type() != takes[index] {
			// Number.isNaN('x') is false in JavaScript, and a string there is a mistake 0.1 won't guess at.
			return nil, true, l.notYet(argument, "a "+typeName(lowered.Type())+" argument to "+name)
		}
		arguments = append(arguments, lowered)
	}
	return ir.NumberCall{Function: name, Arguments: arguments}, true, nil
}

// numberConstants are Number's constants, and the globals NaN and Infinity.
var numberConstants = map[string]float64{
	"MAX_SAFE_INTEGER": 9007199254740991, "MIN_SAFE_INTEGER": -9007199254740991,
	"EPSILON": 2.220446049250313e-16, "MAX_VALUE": math.MaxFloat64, "MIN_VALUE": math.SmallestNonzeroFloat64,
	"POSITIVE_INFINITY": math.Inf(1), "NEGATIVE_INFINITY": math.Inf(-1), "NaN": math.NaN(), "Infinity": math.Inf(1),
}

// forOf lowers for (const element of array).
func (l *lowering) forOf(node *ast.Node) ([]ir.Statement, error) {
	if statements, known, err := l.libraryArrayForOf(node); known {
		return statements, err
	}
	statement := node.AsForInOrOfStatement()
	if statement.AwaitModifier != nil {
		return nil, l.notYet(node, "for await")
	}
	initializer := statement.Initializer
	if initializer.Kind != ast.KindVariableDeclarationList || initializer.Flags&ast.NodeFlagsBlockScoped == 0 {
		return nil, l.notYet(initializer, "a for...of that doesn't declare its variable with const or let")
	}
	declarations := initializer.AsVariableDeclarationList().Declarations.Nodes
	if len(declarations) != 1 {
		return nil, l.notYet(initializer, "a for...of declaring more than one variable")
	}
	name := declarations[0].Name()
	if !ast.IsIdentifier(name) && name.Kind != ast.KindArrayBindingPattern {
		return nil, l.notYet(initializer, "a for...of destructuring an object")
	}
	if plan, err := l.planIteration(statement.Expression); err != nil {
		return nil, err
	} else if plan != nil {
		return l.forOfUser(node, plan, name)
	}
	// map.entries(), map.keys() and map.values() are the map itself, iterated for that part.
	iterated, mapPart := statement.Expression, ""
	if call := ast.SkipParentheses(iterated); call.Kind == ast.KindCallExpression {
		if err := l.optionalCall(call); err != nil {
			return nil, err
		}
	}
	if call := ast.SkipParentheses(iterated); call.Kind == ast.KindCallExpression && len(call.AsCallExpression().Arguments.Nodes) == 0 {
		if callee := ast.SkipParentheses(call.AsCallExpression().Expression); callee.Kind == ast.KindPropertyAccessExpression {
			receiver := callee.AsPropertyAccessExpression().Expression
			if receiverType, _ := l.representation(l.checker.GetTypeAtLocation(receiver)); receiverType == ir.Map {
				switch part := callee.Name().Text(); part {
				case "entries", "keys", "values":
					iterated, mapPart = receiver, part
				}
			}
		}
	}
	iterable, err := l.expression(iterated)
	if err != nil {
		return nil, err
	}
	if element, iterator := l.libraryIteratorElement(iterated); iterator {
		return l.libraryForOfIterator(node, iterable, element, name)
	}
	var element ir.Type
	switch iterable.Type() {
	case ir.Array:
		if element, err = l.elementType(statement.Expression); err != nil {
			return nil, err
		}
	case ir.String:
		// A string's elements are its code points, each a string.
		element = ir.String
	case ir.Map:
		if ast.IsIdentifier(name) && (mapPart == "entries" || (mapPart == "" && !l.isSet(iterated))) {
			var key, value ir.Type
			if l.isSet(iterated) {
				key, err = l.setElement(iterated)
				value = key
			} else {
				key, value, err = l.mapTypes(iterated)
			}
			if err != nil {
				return nil, err
			}
			iterator := ir.CollectionIterator{Collection: iterable, Part: "entries", Key: key, Value: value, Set: l.isSet(iterated)}
			return l.libraryForOfIterator(node, iterator, ir.Object, name)
		}
		return l.forOfMap(node, iterable, iterated, mapPart, name)
	case ir.Object:
		if !l.isLibraryType(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(iterated)), "RegExpStringIterator") {
			return nil, l.notYet(iterated, "for...of over an object")
		}
		element = ir.Array
	default:
		return nil, l.notYet(statement.Expression, "for...of over a "+typeName(iterable.Type()))
	}
	lowered := ir.ForOf{Iterable: iterable, Element: element, RegexIterator: iterable.Type() == ir.Object}
	if ast.IsIdentifier(name) {
		if lowered.Local, err = l.declareLocal(name); err != nil {
			return nil, err
		}
		if element == ir.Weak {
			// An array of Weak<Node> narrowed to present (by filter) still holds handles, so the
			// variable holds one too, and each read of it is the target.
			l.result.Locals[lowered.Local].Type = ir.Weak
		}
	} else {
		// for (const [a, b] of pairs): each name reads a field of the tuple, "0", "1", ...
		if element != ir.Object {
			return nil, l.notYet(name, "destructuring a "+typeName(element))
		}
		for index, binding := range name.AsBindingPattern().Elements.Nodes {
			if skipped(binding) {
				continue
			}
			bound := binding.AsBindingElement()
			if !ast.IsIdentifier(binding.Name()) || bound.Initializer != nil || bound.DotDotDotToken != nil {
				return nil, l.notYet(binding, "a destructured name that isn't plain")
			}
			local, err := l.declareLocal(binding.Name())
			if err != nil {
				return nil, err
			}
			if of := l.result.Locals[local].Type; slotless(of) && !(of == ir.Union && l.writable(l.checker.GetTypeAtLocation(binding.Name()))) {
				return nil, l.notYet(binding, "a tuple element of type "+typeName(of))
			}
			lowered.Pattern = append(lowered.Pattern, ir.Binding{Local: local, Field: strconv.Itoa(index)})
		}
	}
	if lowered.Body, err = l.statement(statement.Statement); err != nil {
		return nil, err
	}
	return []ir.Statement{lowered}, nil
}

// forOfMap lowers for...of over a map: for (const [key, value] of map), and over map.keys() or
// map.values() into one name. An entry as one name would be a tuple made each step, which stage 0
// doesn't do yet.
func (l *lowering) forOfMap(node *ast.Node, iterable ir.Expression, iterated *ast.Node, part string, name *ast.Node) ([]ir.Statement, error) {
	if l.isSet(iterated) {
		return l.forOfSet(node, iterable, iterated, part, name)
	}
	key, value, err := l.mapTypes(iterated)
	if err != nil {
		return nil, err
	}
	if part == "" {
		part = "entries"
	}
	lowered := ir.ForOf{Iterable: iterable, MapPart: part, Key: key, Value: value}
	switch {
	case part == "entries" && name.Kind == ast.KindArrayBindingPattern:
		elements := name.AsBindingPattern().Elements.Nodes
		if len(elements) > 2 {
			return nil, l.notYet(name, "destructuring more than a key and a value")
		}
		for index, binding := range elements {
			if skipped(binding) {
				continue
			}
			bound := binding.AsBindingElement()
			if !ast.IsIdentifier(binding.Name()) || bound.Initializer != nil || bound.DotDotDotToken != nil {
				return nil, l.notYet(binding, "a destructured name that isn't plain")
			}
			local, err := l.declareLocal(binding.Name())
			if err != nil {
				return nil, err
			}
			lowered.Pattern = append(lowered.Pattern, ir.Binding{Local: local, Field: strconv.Itoa(index)})
		}
	case part != "entries" && ast.IsIdentifier(name):
		if lowered.Local, err = l.declareLocal(name); err != nil {
			return nil, err
		}
	default:
		return nil, l.notYet(name, "for...of over a map's "+part+" into this name (write [key, value], or iterate keys() or values())")
	}
	if lowered.Body, err = l.statement(node.AsForInOrOfStatement().Statement); err != nil {
		return nil, err
	}
	return []ir.Statement{lowered}, nil
}

// switchStatement preserves ordered case expression evaluation.
func (l *lowering) switchStatement(node *ast.Node) ([]ir.Statement, error) {
	statement := node.AsSwitchStatement()
	if err := l.enumSwitch(node); err != nil {
		return nil, err
	}
	value, err := l.expression(statement.Expression)
	if err != nil {
		return nil, err
	}
	storage, err := l.switchBindings(statement.CaseBlock)
	if err != nil {
		return nil, err
	}
	original := value
	held := -1
	if len(storage) > 0 {
		// The discriminant runs outside the case block's lexical environment.
		held = len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: "switch_value", Type: value.Type(), Function: l.functionIndex})
		value = ir.Read{Local: held, Of: value.Type()}
	}
	lowered := ir.Switch{Value: value}
	groups := []switchGroup{}
	prefix := []ir.Statement{}
	identity := l.enumIdentity(l.checker.GetTypeAtLocation(statement.Expression))
	checkedDefault := l.numericEnum(identity) && l.enumSwitchCovered(node) && !l.enumDefaultUnreachable(node)
	var neverCheck ir.Statement
	if checkedDefault {
		// The unmatched edge is never to the checker, including an implicit default. Hold the
		// scrutinee once so the check names the original value without repeating its effects.
		local := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: "enum_switch_value", Type: value.Type(), Function: l.functionIndex})
		prefix = append(prefix, ir.Declare{Local: local, Value: value})
		value = ir.Read{Local: local, Of: value.Type()}
		lowered.Value = value
		neverCheck = ir.Evaluate{Value: l.enumNeverCheck(statement.Expression, value, identity)}
		lowered.Default = []ir.Statement{neverCheck}
	}
	tests := []ir.Expression{}
	defaultPending := false
	for _, clause := range statement.CaseBlock.AsCaseBlock().Clauses.Nodes {
		isDefault := clause.Kind == ast.KindDefaultClause
		if isDefault && len(tests) == 0 && l.enumDefaultUnreachable(node) && (len(groups) == 0 || switchBodyLeaves(groups[len(groups)-1].body)) {
			continue
		}
		if !isDefault {
			test, err := l.caseLabel(clause.AsCaseOrDefaultClause().Expression)
			if err != nil {
				return nil, err
			}

			if test.Type() != value.Type() {
				return nil, l.notYet(clause, "a case whose type differs from the switch's")
			}
			tests = append(tests, test)
		}
		body, err := l.statements(clause.AsCaseOrDefaultClause().Statements.Nodes)
		if err != nil {
			return nil, err
		}
		defaultPending = defaultPending || isDefault
		if len(body) == 0 {
			// Empty labels enter the next body, including labels on either side of default.
			continue
		}
		groups = append(groups, switchGroup{tests: tests, body: body, isDefault: defaultPending})
		if defaultPending {
			lowered.Default = body
		}
		if len(tests) > 0 {
			// Default is a fallback position, but its grouped tests still compete in source order.
			lowered.Cases = append(lowered.Cases, ir.Case{Tests: tests, Body: body})
		}
		tests = []ir.Expression{}
		defaultPending = false
	}
	if len(tests) > 0 {
		// A trailing empty label matches and leaves the switch without running default.
		lowered.Cases = append(lowered.Cases, ir.Case{Tests: tests})
	}
	if len(tests) > 0 || defaultPending {
		groups = append(groups, switchGroup{tests: tests, isDefault: defaultPending})
	}
	result := []ir.Statement{lowered}
	if checkedDefault {
		result = l.fallthroughSwitch(value, groups, neverCheck)
	} else {
		for index, group := range groups {
			if (group.isDefault && len(group.tests) > 0) || (index+1 < len(groups) && len(group.body) > 0 && !switchBodyLeaves(group.body)) {
				result = l.fallthroughSwitch(value, groups, nil)
				break
			}
		}
	}
	result = append(prefix, result...)
	if held >= 0 {
		body := []ir.Statement{ir.Declare{Local: held, Value: original}}
		body = append(body, storage...)
		body = append(body, result...)
		result = []ir.Statement{ir.Block{Body: body}}
	}
	return result, nil
}

// arrayMethod lowers array.push(value) and array.join(separator).
func (l *lowering) arrayMethod(node *ast.Node, receiver *ast.Node, name string) (ir.Expression, bool, error) {
	return l.arrayMethodArguments(node, receiver, name, node.AsCallExpression().Arguments.Nodes)
}

func (l *lowering) arrayMethodArguments(node *ast.Node, receiver *ast.Node, name string, written []*ast.Node) (ir.Expression, bool, error) {
	if created := ast.SkipParentheses(receiver); name == "fill" && created.Kind == ast.KindNewExpression && l.isLibraryGlobal(created.AsNewExpression().Expression, "Array") {
		return l.newArrayFilled(node, created)
	}
	element, err := l.elementType(receiver)
	if err != nil {
		return nil, true, err
	}
	array, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	if name == "sort" {
		return l.arraySort(node, array, element)
	}
	if name == "map" {
		arguments := written
		if len(arguments) != 1 {
			return nil, true, l.notYet(node, "map with other than one callback")
		}
		callback, known, err := l.libraryMapCallback(arguments[0], receiver, element)
		if !known {
			callback, err = l.expression(arguments[0])
		}
		if err != nil {
			return nil, true, err
		}
		if callback.Type() != ir.Closure {
			return nil, true, l.notYet(arguments[0], "map with a callback that isn't a function")
		}
		result, err := l.elementType(node)
		if err != nil {
			return nil, true, err
		}
		return ir.ArrayMap{Array: array, Callback: callback, Element: element, Result: result, CallbackType: int(l.concrete(l.checker.GetTypeAtLocation(arguments[0])).Id())}, true, nil
	}
	if _, isVisit := visits[name]; isVisit {
		return l.arrayVisit(node, array, element, name)
	}
	if name == "reduce" {
		return l.arrayReduce(node, array, element)
	}
	if name == "concat" && element == ir.Array {
		// TypeScript says grid.concat(row) appends row as one element; JavaScript spreads any array it's
		// given, so the types and the program would disagree.
		return nil, true, l.notYet(node, "concat on an array of arrays")
	}
	arguments := []ir.Expression{}
	for _, argument := range written {
		lowered, err := l.expression(argument)
		if err != nil {
			return nil, true, err
		}
		arguments = append(arguments, lowered)
	}
	if name == "slice" {
		for _, argument := range arguments {
			if argument.Type() != ir.Number {
				return nil, true, l.notYet(node, "slice with an index that isn't a number")
			}
		}
		if len(arguments) > 2 {
			return nil, true, l.notYet(node, "slice with more than two arguments")
		}
		return ir.ArraySlice{Array: array, Arguments: arguments}, true, nil
	}
	if name == "push" {
		if len(arguments) != 1 {
			return nil, true, l.notYet(node, "push with other than one value")
		}
		return ir.ArrayPush{Array: array, Value: fit(arguments[0], element), Element: element, Site: l.writeSite(receiver)}, true, nil
	}
	switch name {
	case "includes", "indexOf":
		if element == ir.Union {
			return nil, true, l.notYet(node, "searching boxed union array elements")
		}
		if len(arguments) != 1 {
			return nil, true, l.notYet(node, name+" with a starting index")
		}
		if arguments[0] = fit(arguments[0], element); arguments[0].Type() != element {
			return nil, true, l.notYet(node, name+" with a value of another type than the elements")
		}
		return ir.ArraySearch{Array: array, Value: arguments[0], Element: element, Includes: name == "includes"}, true, nil
	case "at":
		if len(arguments) != 1 || arguments[0].Type() != ir.Number {
			return nil, true, l.notYet(node, "at with other than one number")
		}
		return ir.ArrayIndex{Array: array, Index: arguments[0], Element: element, Relative: true}, true, nil
	case "reverse":
		return ir.ArrayReverse{Array: array}, true, nil
	case "fill":
		if len(arguments) > 0 {
			arguments[0] = fit(arguments[0], element)
		}
		if len(arguments) == 0 || len(arguments) > 3 || arguments[0].Type() != element {
			return nil, true, l.notYet(node, "fill with other than a value of the elements' type")
		}
		fill := ir.ArrayFill{Array: array, Value: arguments[0], Element: element, Site: l.writeSite(receiver)}
		for index, bound := range arguments[1:] {
			if bound.Type() != ir.Number {
				return nil, true, l.notYet(node, "fill with a bound that isn't a number")
			}
			if index == 0 {
				fill.Start = bound
			} else {
				fill.End = bound
			}
		}
		return fill, true, nil
	case "splice":
		if len(arguments) == 0 || arguments[0].Type() != ir.Number || (len(arguments) > 1 && arguments[1].Type() != ir.Number) {
			return nil, true, l.notYet(node, "splice without a start and a count that are numbers")
		}
		splice := ir.ArraySplice{Array: array, Start: arguments[0], Element: element, Site: l.writeSite(receiver)}
		if len(arguments) > 1 {
			splice.Count = arguments[1]
			for _, item := range arguments[2:] {
				if item = fit(item, element); item.Type() != element {
					return nil, true, l.notYet(node, "splice inserting a value of another type than the elements")
				}
				splice.Items = append(splice.Items, item)
			}
		}
		return splice, true, nil
	case "concat":
		for index, argument := range arguments {
			if argument.Type() != ir.Array {
				return nil, true, l.notYet(node, "concat with a value that isn't an array (JavaScript appends it)")
			}
			if other, err := l.elementType(written[index]); err != nil || other != element {
				return nil, true, l.notYet(node, "concat of arrays of different elements")
			}
		}
		return ir.ArrayConcat{Array: array, Others: arguments}, true, nil
	}
	if element != ir.Number && element != ir.Boolean && element != ir.String && element != ir.MaybeNumber {
		// JavaScript writes an object as "[object Object]", a function as its source, and an array as
		// its own join, flattened; 0.1 has no use for any of that.
		return nil, true, l.notYet(node, "join on an array of objects, arrays, maps or functions")
	}
	separator := ir.Expression(ir.StringConstant{Index: l.constant(",")})
	if len(arguments) == 1 {
		arguments[0] = l.orDefault(written[0], arguments[0], ",")
		if arguments[0].Type() != ir.String {
			return nil, true, l.notYet(node, "join with a separator that isn't a string")
		}
		separator = arguments[0]
	} else if len(arguments) > 1 {
		return nil, true, l.notYet(node, "join with more than one argument")
	}
	return ir.ArrayJoin{Array: array, Separator: separator, Element: element}, true, nil
}

// arrayMethods are the array methods arrayMethod lowers, beside the visits.
var arrayMethods = map[string]bool{
	"push": true, "join": true, "slice": true, "sort": true, "map": true, "reduce": true,
	"includes": true, "indexOf": true, "at": true, "reverse": true, "concat": true, "splice": true,
	"fill": true,
}

// newArrayFilled lowers new Array(length).fill(value). new Array(length) alone is an array of holes,
// which 0.1 can't hold, so it lowers only filled, and filled whole.
func (l *lowering) newArrayFilled(node *ast.Node, created *ast.Node) (ir.Expression, bool, error) {
	element, err := l.elementType(node)
	if err != nil {
		return nil, true, err
	}
	constructed := created.AsNewExpression().Arguments
	filled := node.AsCallExpression().Arguments.Nodes
	if constructed == nil || len(constructed.Nodes) != 1 || len(filled) != 1 {
		return nil, true, l.notYet(node, "new Array filled with other than one length and one value (a part left unfilled is a hole)")
	}
	length, err := l.expression(constructed.Nodes[0])
	if err != nil {
		return nil, true, err
	}
	value, err := l.expression(filled[0])
	if err != nil {
		return nil, true, err
	}
	if value = fit(value, element); length.Type() != ir.Number || value.Type() != element {
		return nil, true, l.notYet(node, "new Array(length).fill(value) with a length that isn't a number or a value of another type")
	}
	return ir.ArrayFill{Length: length, Value: value, Element: element}, true, nil
}

// visits are the array methods that call a function per element and look at what it returns.
var visits = map[string]struct{}{"forEach": {}, "filter": {}, "some": {}, "every": {}, "find": {}, "findIndex": {}}

// arrayVisit lowers forEach, filter, some, every, find and findIndex. All but forEach decide by what
// the callback returns, which 0.1 requires to be a boolean: JavaScript would take any value's
// truthiness there, and 0.1 has none.
func (l *lowering) arrayVisit(node *ast.Node, array ir.Expression, element ir.Type, name string) (ir.Expression, bool, error) {
	arguments := node.AsCallExpression().Arguments.Nodes
	if len(arguments) != 1 {
		return nil, true, l.notYet(node, name+" with other than one callback")
	}
	callback, err := l.expression(arguments[0])
	if err != nil {
		return nil, true, err
	}
	if callback.Type() != ir.Closure {
		return nil, true, l.notYet(arguments[0], name+" with a callback that isn't a function")
	}
	signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(arguments[0]), checker.SignatureKindCall)
	if len(signatures) != 1 {
		return nil, true, l.notYet(arguments[0], name+" with an overloaded callback")
	}
	claim := predicateOfSignature(l.checker, signatures[0])
	if claim != nil && claim.Type() != nil {
		if name == "filter" && element == ir.Union {
			target, known := l.kept(l.concrete(claim.Type()))
			if known && target != element {
				return nil, true, l.notYet(node, "filter predicate element representation conversion from boxed union to "+typeName(target)+"; use a loop with an explicit narrowed copy")
			}
		}
		// An undefined result already fits packed optional-number storage.
		// Heap-backed and boxed sources cannot be reused as that result slot.
		if name == "find" && !(element == ir.MaybeNumber && claim.Type().Flags()&checker.TypeFlagsUndefined != 0) {
			result, err := l.typeOf(node)
			if err != nil || result != ir.Maybe(element) {
				return nil, true, l.notYet(node, "find predicate result representation conversion from "+typeName(ir.Maybe(element))+" to "+l.checker.TypeToString(l.checker.GetTypeAtLocation(node))+"; use a loop with an explicit narrowed result")
			}
		}
	}
	var returns ir.Type
	if result := l.checker.GetReturnTypeOfSignature(signatures[0]); result.Flags()&checker.TypeFlagsVoid == 0 {
		var isKnown bool
		if returns, isKnown = l.representation(result); !isKnown {
			return nil, true, l.notYet(arguments[0], name+" with a callback returning "+l.checker.TypeToString(result))
		}
	}
	if name != "forEach" && returns != ir.Boolean {
		return nil, true, &Refused{Where: l.program.Where(arguments[0]), What: "a " + name + " callback that doesn't return a boolean", Fix: "return a comparison, like word.length > 0: 0.1 has no truthiness"}
	}
	return ir.ArrayVisit{Method: name, Array: array, Callback: callback, Element: element, Returns: returns, CallbackType: int(l.concrete(l.checker.GetTypeAtLocation(arguments[0])).Id())}, true, nil
}

// arrayReduce lowers array.reduce(callback, initial). 0.1 requires the initial value (docs/0.1.md):
// without one, an empty array throws and a one-element array returns it without a call.
func (l *lowering) arrayReduce(node *ast.Node, array ir.Expression, element ir.Type) (ir.Expression, bool, error) {
	arguments := node.AsCallExpression().Arguments.Nodes
	if len(arguments) == 1 {
		return nil, true, &Refused{Where: l.program.Where(node), What: "reduce without an initial value", Fix: "pass one, like reduce((sum, value) => sum + value, 0): without it, an empty array throws"}
	}
	if len(arguments) != 2 {
		return nil, true, l.notYet(node, "reduce with other than a callback and an initial value")
	}
	callback, err := l.expression(arguments[0])
	if err != nil {
		return nil, true, err
	}
	if callback.Type() != ir.Closure {
		return nil, true, l.notYet(arguments[0], "reduce with a callback that isn't a function")
	}
	initial, err := l.expression(arguments[1])
	if err != nil {
		return nil, true, err
	}
	result, err := l.typeOf(node)
	if err != nil {
		return nil, true, err
	}
	initial = fit(initial, result)
	if result != initial.Type() || slotless(result) {
		return nil, true, l.notYet(node, "reduce to a "+l.checker.TypeToString(l.checker.GetTypeAtLocation(node)))
	}
	return ir.ArrayReduce{Array: array, Callback: callback, Initial: initial, Element: element, Result: result, CallbackType: int(l.concrete(l.checker.GetTypeAtLocation(arguments[0])).Id())}, true, nil
}

// mapTypes is a Map's key and value representations. 0.1's maps have string or number keys.
func (l *lowering) mapTypes(node *ast.Node) (ir.Type, ir.Type, error) {
	arguments := l.typeArguments(l.checker.GetTypeAtLocation(node))
	if len(arguments) != 2 {
		return 0, 0, l.notYet(node, "a Map whose key and value types aren't known")
	}
	key, keyKnown := l.representation(arguments[0])
	value, valueKnown := l.kept(arguments[1])
	// never has no inhabitant to store. Empty maps can still be observed through
	// size or a readonly wider view; an unused object slot supplies storage only.
	if arguments[0].Flags()&checker.TypeFlagsNever != 0 {
		key, keyKnown = ir.Object, true
	}
	if arguments[1].Flags()&checker.TypeFlagsNever != 0 {
		value, valueKnown = ir.Object, true
	}
	if !keyKnown || !keyable(key) {
		return 0, 0, l.notYet(node, "a Map whose keys aren't strings, numbers, booleans, objects, arrays, maps or functions")
	}
	// number | undefined is held in a value's one slot packed (native/slots.go).
	if !valueKnown || (slotless(value) && !(value == ir.Union && l.writable(arguments[1]))) {
		return 0, 0, l.notYet(node, "a Map of "+l.checker.TypeToString(arguments[1]))
	}
	return key, value, nil
}

// newExpression lowers new Map(), and new Map([[key, value], ...]) with its pairs written out, which
// is what the array of pairs means.
func (l *lowering) newExpression(node *ast.Node) (ir.Expression, error) {
	if value, found, err := l.nodeFSFileDate(node); found {
		return value, err
	}
	if l.isLibraryGlobal(node.AsNewExpression().Expression, "RegExp") {
		return l.regexConstant(node)
	}
	created := node.AsNewExpression()
	if declaration, isClass := l.classes[l.symbol(ast.SkipParentheses(created.Expression))]; isClass {
		return l.construct(node, declaration)
	}
	if l.isLibraryGlobal(created.Expression, "Set") {
		return l.newSet(node)
	}
	if l.isLibraryGlobal(created.Expression, "Error") {
		return l.newError(node)
	}
	if !l.isLibraryGlobal(created.Expression, "Map") {
		if value, handled, err := l.newClassValue(node); handled {
			return value, err
		}
		return nil, l.notYet(node, "new "+describe(created.Expression))
	}
	key, value, err := l.mapTypes(node)
	if err != nil {
		return nil, err
	}
	lowered := ir.MapNew{Key: key, Value: value}
	if created.Arguments == nil || len(created.Arguments.Nodes) == 0 {
		return lowered, nil
	}
	if len(created.Arguments.Nodes) != 1 {
		return nil, l.notYet(node, "new Map with more than one argument")
	}
	pairs := ast.SkipParentheses(created.Arguments.Nodes[0])
	if l.libraryEmptyCollectionArgument(pairs) {
		return lowered, nil
	}
	if !writtenOut(pairs) {
		// Pairs from anywhere else: an array of them, another Map, its entries() (collections.go).
		return l.newMapFrom(node, pairs, key, value)
	}
	for _, pair := range pairs.AsArrayLiteralExpression().Elements.Nodes {
		pair = ast.SkipParentheses(pair)
		if pair.Kind != ast.KindArrayLiteralExpression || len(pair.AsArrayLiteralExpression().Elements.Nodes) != 2 {
			return nil, l.notYet(pair, "a Map entry that isn't [key, value] written out")
		}
		elements := pair.AsArrayLiteralExpression().Elements.Nodes
		entryKey, err := l.expression(elements[0])
		if err != nil {
			return nil, err
		}
		entryValue, err := l.expression(elements[1])
		if err != nil {
			return nil, err
		}
		// A number, or undefined, where number | undefined goes is made that pair.
		entryKey = fit(entryKey, key)
		entryValue = fit(entryValue, value)
		if entryKey.Type() != key || entryValue.Type() != value {
			return nil, l.notYet(pair, "a Map entry whose key or value is of another type than the Map's")
		}
		lowered.Entries = append(lowered.Entries, [2]ir.Expression{entryKey, entryValue})
	}
	return lowered, nil
}

// writtenOut reports whether a new Map's argument is its pairs written out: an array literal of
// [key, value] literals, each set in order as written.
func writtenOut(pairs *ast.Node) bool {
	if pairs.Kind != ast.KindArrayLiteralExpression {
		return false
	}
	for _, pair := range pairs.AsArrayLiteralExpression().Elements.Nodes {
		pair = ast.SkipParentheses(pair)
		if pair.Kind != ast.KindArrayLiteralExpression || len(pair.AsArrayLiteralExpression().Elements.Nodes) != 2 {
			return false
		}
		for _, element := range pair.AsArrayLiteralExpression().Elements.Nodes {
			if element.Kind == ast.KindSpreadElement || element.Kind == ast.KindOmittedExpression {
				return false
			}
		}
	}
	return true
}

// mapMethod lowers map.get, set, has and delete.
func (l *lowering) mapMethod(node *ast.Node, receiver *ast.Node, name string) (ir.Expression, bool, error) {
	key, value, err := l.mapTypes(receiver)
	if err != nil {
		return nil, true, err
	}
	object, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	arguments := []ir.Expression{}
	for _, argument := range node.AsCallExpression().Arguments.Nodes {
		lowered, err := l.expression(argument)
		if err != nil {
			return nil, true, err
		}
		arguments = append(arguments, lowered)
	}
	if len(arguments) > 0 {
		arguments[0] = fit(arguments[0], key)
	}
	want := 1
	if name == "set" {
		want = 2
	}
	if name == "set" && len(arguments) == 2 {
		arguments[1] = fit(arguments[1], value)
	}
	if len(arguments) != want || arguments[0].Type() != key || (name == "set" && arguments[1].Type() != value) {
		return nil, true, l.notYet(node, "map."+name+" with arguments of other types")
	}
	switch name {
	case "get":
		return ir.MapGet{Map: object, Key: arguments[0], KeyType: key, ValueType: value}, true, nil
	case "set":
		return ir.MapSet{Map: object, Key: arguments[0], Value: arguments[1], KeyType: key, ValueType: value, Site: l.writeSite(receiver)}, true, nil
	case "has":
		return ir.MapHas{Map: object, Key: arguments[0], KeyType: key}, true, nil
	}
	return ir.MapDelete{Map: object, Key: arguments[0], KeyType: key}, true, nil
}

// stringMethod lowers string.trim() and string.charCodeAt(index).
func (l *lowering) stringMethod(node *ast.Node, receiver *ast.Node, name string) (ir.Expression, bool, error) {
	value, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	arguments := node.AsCallExpression().Arguments.Nodes
	if name == "trim" {
		if len(arguments) != 0 {
			return nil, true, l.notYet(node, "trim with arguments")
		}
		return ir.Trim{Value: value}, true, nil
	}
	index := ir.Expression(ir.NumberConstant{Value: 0})
	if len(arguments) > 1 {
		return nil, true, l.notYet(node, "charCodeAt with more than one argument")
	}
	if len(arguments) == 1 {
		if index, err = l.expression(arguments[0]); err != nil {
			return nil, true, err
		}
		if index.Type() != ir.Number {
			return nil, true, l.notYet(node, "charCodeAt with an index that isn't a number")
		}
	}
	return ir.CharCodeAt{Value: value, Index: index}, true, nil
}

// shorthand lowers the value of { value }. The name there is the field's, and asked for its symbol
// the checker gives the field; the variable it reads is a separate question.
func (l *lowering) shorthand(property *ast.Node) (ir.Expression, error) {
	symbol := l.checker.GetShorthandAssignmentValueSymbol(property)
	if symbol != nil && symbol.Flags&ast.SymbolFlagsAlias != 0 {
		symbol = l.checker.GetAliasedSymbol(symbol)
	}
	if symbol != nil {
		symbol = l.checker.GetExportSymbolOfSymbol(symbol)
	}
	local, isLocal := l.locals[symbol]
	if !isLocal {
		if target, isFunction := l.functions[symbol]; isFunction {
			return l.functionValue(property, target)
		}
		return nil, l.notYet(property, "reading "+property.Name().Text())
	}
	l.touch(local)
	of := l.result.Locals[local].Type
	if censusFieldSlotless(of) {
		return nil, l.notYet(property, "a field from a "+typeName(of)+" variable")
	}
	read := ir.Read{Local: local, Of: of, Checked: l.checked(local)}
	if identity := l.enumNeverIdentity(property.Name(), map[*ast.Node]bool{}); identity != nil {
		return l.enumNeverCheck(property.Name(), read, identity), nil
	}
	return read, nil
}

// stringMethods are the string methods stringCall lowers: the types of their arguments, and how many
// may be left out, each filled in with JavaScript's default.
var stringMethods = map[string]struct {
	arguments []ir.Type
	optional  int
}{
	"slice":       {[]ir.Type{ir.Number, ir.Number}, 2},
	"codePointAt": {[]ir.Type{ir.Number}, 1},
	"padStart":    {[]ir.Type{ir.Number, ir.String}, 1},
	"padEnd":      {[]ir.Type{ir.Number, ir.String}, 1},
	"repeat":      {[]ir.Type{ir.Number}, 0},
	"indexOf":     {[]ir.Type{ir.String, ir.Number}, 1},
	"includes":    {[]ir.Type{ir.String, ir.Number}, 1},
	"startsWith":  {[]ir.Type{ir.String}, 0},
	"endsWith":    {[]ir.Type{ir.String}, 0},
	"split":       {[]ir.Type{ir.String}, 0},
	"lastIndexOf": {[]ir.Type{ir.String}, 0},
	"trimStart":   {nil, 0},
	"trimEnd":     {nil, 0},
	"toUpperCase": {nil, 0},
	"toLowerCase": {nil, 0},
	"normalize":   {[]ir.Type{ir.String}, 1},
	"at":          {[]ir.Type{ir.Number}, 0},
	// A pattern that's a string, and a replacement that's a string: a regular expression or a
	// function there isn't a string, and stays not yet.
	"replace":    {[]ir.Type{ir.String, ir.String}, 0},
	"replaceAll": {[]ir.Type{ir.String, ir.String}, 0},
}

func (l *lowering) stringCall(node *ast.Node, receiver *ast.Node, name string) (ir.Expression, bool, error) {
	shape := stringMethods[name]
	value, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	written := node.AsCallExpression().Arguments.Nodes
	if name == "slice" || name == "lastIndexOf" {
		return l.libraryStringMethod(node, value, name, written)
	}
	if len(written) > len(shape.arguments) || len(written) < len(shape.arguments)-shape.optional {
		return nil, true, l.notYet(node, name+" with these arguments")
	}
	arguments := []ir.Expression{}
	for index, argument := range written {
		lowered, err := l.expression(argument)
		if err != nil {
			return nil, true, err
		}
		if fallback, isOptional := optionalStrings[name][index]; isOptional {
			lowered = l.orDefault(argument, lowered, fallback)
		}
		if lowered.Type() != shape.arguments[index] {
			return nil, true, l.notYet(argument, "a "+typeName(lowered.Type())+" argument to "+name)
		}
		arguments = append(arguments, lowered)
	}
	// JavaScript's defaults: codePointAt() is position 0, and padStart's fill is a space. slice's end
	// stays missing, which is different from any number, so the emitter is told how many were given.
	switch {
	case name == "codePointAt" && len(arguments) == 0:
		arguments = append(arguments, ir.NumberConstant{Value: 0})
	case (name == "padStart" || name == "padEnd") && len(arguments) == 1:
		arguments = append(arguments, ir.StringConstant{Index: l.constant(" ")})
	case name == "normalize" && len(arguments) == 0:
		arguments = append(arguments, ir.StringConstant{Index: l.constant("NFC")})
	}
	return ir.StringCall{Method: name, Value: value, Arguments: arguments}, true, nil
}

// arraySort lowers array.sort(comparator). 0.1 requires the comparator (the default sorts numbers as
// strings), and stage 0 takes one of the module's functions by name.
func (l *lowering) arraySort(node *ast.Node, array ir.Expression, element ir.Type) (ir.Expression, bool, error) {
	arguments := node.AsCallExpression().Arguments.Nodes
	if len(arguments) == 0 {
		return nil, true, &Refused{Where: l.program.Where(node), What: "sort without a comparator", Fix: "pass one: the default compares numbers as strings, so [10, 9, 1].sort() is [1, 10, 9]"}
	}
	comparator := ast.SkipParentheses(arguments[0])
	function, isFunction := l.functions[l.symbol(comparator)]
	if !ast.IsIdentifier(comparator) || !isFunction {
		// A function value: an arrow, or a variable holding one.
		callback, err := l.expression(comparator)
		if err != nil {
			return nil, true, err
		}
		signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(comparator), checker.SignatureKindCall)
		if callback.Type() != ir.Closure || len(signatures) != 1 {
			return nil, true, l.notYet(comparator, "a comparator that isn't a function")
		}
		if returns, _ := l.representation(l.checker.GetReturnTypeOfSignature(signatures[0])); returns != ir.Number {
			return nil, true, l.notYet(comparator, "a comparator that doesn't return a number")
		}
		return ir.ArraySort{Array: array, Callback: callback, Element: element, CallbackType: int(l.concrete(l.checker.GetTypeAtLocation(comparator)).Id())}, true, nil
	}
	declared := l.result.Functions[function]
	if declared.Returns != ir.Number || len(declared.Parameters) != 2 || l.result.Locals[declared.Parameters[0]].Type != element || l.result.Locals[declared.Parameters[1]].Type != element {
		return nil, true, l.notYet(comparator, "a comparator that doesn't take two elements and return a number")
	}
	return ir.ArraySort{Array: array, Comparator: function, Element: element}, true, nil
}

// elementAccess lowers array[index], string[index], and tuple[index] with a constant index: the
// tuple's field of that name.
func (l *lowering) elementAccess(node *ast.Node) (ir.Expression, error) {
	access := node.AsElementAccessExpression()
	index := ast.SkipParentheses(access.ArgumentExpression)
	if l.inheritedLibraryMember(node) && !l.regexRuntimeProperty(access.Expression, index.Text()) {
		return nil, l.prototypeRead(node, index.Text())
	}
	optional := access.QuestionDotToken != nil
	if !optional && node.Flags&ast.NodeFlagsOptionalChain != 0 {
		return l.optionalIndexContinuation(node)
	}
	object, err := l.expression(access.Expression)
	if err != nil {
		return nil, err
	}
	if object.Type() == ir.Object && l.regexGroups(access.Expression) {
		if index.Kind != ast.KindStringLiteral {
			return nil, l.notYet(node, "a computed named-group key")
		}
		of, err := l.typeOf(node)
		if err != nil {
			return nil, err
		}
		if of != ir.String && of != ir.Object {
			return nil, l.notYet(node, "a named-group key with an Object-prototype type")
		}
		return ir.RegExpGroup{Object: object, Name: index.Text(), Of: of, Optional: optional}, nil
	}
	if optional && (object.Type() == ir.Array || object.Type() == ir.String || object.Type().IsTypedArray()) {
		return l.optionalIndex(node, object)
	}
	if optional && object.Type() != ir.Object {
		return nil, l.notYet(node, "?.[] on a "+typeName(object.Type()))
	}
	if object.Type() == ir.String {
		position, err := l.expression(access.ArgumentExpression)
		if err != nil {
			return nil, err
		}
		if position.Type() != ir.Number {
			return nil, l.notYet(node, "a string index that isn't a number")
		}
		return ir.StringIndex{Value: object, Index: position}, nil
	}
	if object.Type() == ir.Array {
		element, err := l.elementType(access.Expression)
		if err != nil {
			return nil, err
		}
		position, err := l.expression(access.ArgumentExpression)
		if err != nil {
			return nil, err
		}
		if position.Type() != ir.Number {
			return nil, l.notYet(node, "an array index that isn't a number")
		}
		return l.defined(node, ir.ArrayIndex{Array: object, Index: position, Element: element, Optional: optional}), nil
	}
	if object.Type() == ir.Object {
		if value, handled, err := l.indexedTupleRead(node, object); handled {
			return value, err
		}
	}
	if object.Type() == ir.Object && !optional && !checker.IsTupleType(l.checker.GetTypeAtLocation(access.Expression)) {
		return l.finiteElementRead(node, object)
	}
	// pairs[0]?.[0]: the tuple may be missing, and the read is undefined then (collections.go).
	if optional {
		return l.optionalTupleElement(node, object, index)
	}
	if object.Type() != ir.Object || index.Kind != ast.KindNumericLiteral || !checker.IsTupleType(l.checker.GetTypeAtLocation(access.Expression)) {
		return nil, l.notYet(node, describe(node))
	}
	of, err := l.typeOf(node)
	if elements := l.typeArguments(l.checker.GetTypeAtLocation(access.Expression)); err == nil {
		// What the tuple keeps there, not what the checker narrowed the read to: a Weak keeps a handle.
		if position, convertErr := strconv.Atoi(index.Text()); convertErr == nil && position < len(elements) {
			if declared, isKnown := l.representation(elements[position]); isKnown && declared == ir.Weak {
				of = declared
			}
		}
	}
	if err != nil {
		return nil, err
	}
	if slotless(of) {
		return nil, l.notYet(node, "a tuple element of type "+typeName(of))
	}
	property := ir.Property{Object: object, Name: index.Text(), Of: of}
	receiver := l.checker.GetTypeAtLocation(access.Expression)
	if position, err := strconv.Atoi(index.Text()); err == nil {
		elements := l.typeArguments(receiver)
		if position >= 0 && position < len(elements) {
			property.ViewTypeID = int(elements[position].Id())
			property.ViewContract = l.result.ViewContractTypes[property.ViewTypeID]
			property.ViewReceiverTypeID = int(receiver.Id())
			property.ViewType = l.checker.TypeToString(elements[position])
			property.ViewAllowed = l.viewLiterals(elements[position])
			property.View = sourceExpression(node)
			property.ViewWhere = l.program.Where(node)
		}
	}
	return property, nil
}

// setIndex lowers array[index] = value, as a statement.
func (l *lowering) setIndex(target *ast.Node, valueNode *ast.Node) ([]ir.Statement, error) {
	if body, handled, err := l.entriesRecordWrite(target, valueNode); handled {
		return body, err
	}
	access := target.AsElementAccessExpression()
	array, err := l.expression(access.Expression)
	if err != nil {
		return nil, err
	}
	if array.Type() != ir.Array {
		return nil, l.notYet(target, "assigning an element of a "+typeName(array.Type()))
	}
	element, err := l.elementType(access.Expression)
	if err != nil {
		return nil, err
	}
	index, err := l.expression(access.ArgumentExpression)
	if err != nil {
		return nil, err
	}
	if index.Type() != ir.Number {
		return nil, l.notYet(target, "an array index that isn't a number")
	}
	value, err := l.expression(valueNode)
	if err != nil {
		return nil, err
	}
	if l.nodeBufferType(l.checker.GetTypeAtLocation(access.Expression), "Buffer") {
		if value.Type() != ir.Number {
			return nil, l.notYet(valueNode, "a Buffer write of a non-number")
		}
		return []ir.Statement{ir.Evaluate{Value: ir.NodeBufferCall{Function: "buffer_set", Arguments: []ir.Expression{array, index, value}, Returns: ir.Number}}}, nil
	}
	return []ir.Statement{ir.SetIndex{Array: array, Index: index, Value: fit(value, element), Element: element, Site: l.writeSite(access.Expression)}}, nil
}

// stringFromCodes lowers String.fromCharCode(...) and String.fromCodePoint(...), each argument a
// number, evaluated in order.
func (l *lowering) stringFromCodes(node *ast.Node, codePoints bool) (ir.Expression, bool, error) {
	return l.stringFromCodesArguments(node, codePoints, node.AsCallExpression().Arguments.Nodes)
}

func (l *lowering) stringFromCodesArguments(node *ast.Node, codePoints bool, written []*ast.Node) (ir.Expression, bool, error) {
	lowered := ir.StringFromCodes{CodePoints: codePoints}
	if hasSpread(node) {
		spread, err := l.spreadNumbers(node)
		if err != nil {
			return nil, true, err
		}
		lowered.Spread = spread
		return lowered, true, nil
	}
	for _, argument := range written {
		if argument.Kind == ast.KindSpreadElement {
			return nil, true, l.notYet(argument, "a spread argument to String."+node.AsCallExpression().Expression.Name().Text())
		}
		value, err := l.expression(argument)
		if err != nil {
			return nil, true, err
		}
		if value.Type() != ir.Number {
			return nil, true, l.notYet(argument, "a "+typeName(value.Type())+" argument to String."+node.AsCallExpression().Expression.Name().Text())
		}
		lowered.Codes = append(lowered.Codes, value)
	}
	return lowered, true, nil
}

// tupleType is the tuple type an array literal makes, from the checker or from where it's written
// (return ['a', 1] in a function returning [string, number]), or nil when it makes an array.
func (l *lowering) tupleType(node *ast.Node) *checker.Type {
	// The tuple it's written into first: [5] written into [number, string?] is that tuple, with its
	// second element undefined, though the literal's own type is [number].
	if contextual := l.checker.GetContextualType(node, checker.ContextFlagsNone); contextual != nil && checker.IsTupleType(contextual) && l.everyKnown(l.checker.GetTypeArguments(contextual)) {
		// (Under as const the contextual tuple's elements are any, and the literal's own type says
		// how they're held.)
		return contextual
	}
	if made := l.checker.GetTypeAtLocation(node); checker.IsTupleType(made) {
		return made
	}
	return nil
}

// tupleLiteral lowers [a, b] where it makes a tuple: an object whose fields are named "0", "1", ...,
// as a tuple's elements are read (elementAccess) and destructured (destructure, and for...of), each
// made what its element's type holds. A literal with as many elements as its tuple has is lowered;
// one leaving out an optional element, or spreading, is not yet.
func (l *lowering) tupleLiteral(node *ast.Node, tuple *checker.Type) (ir.Expression, error) {
	items := node.AsArrayLiteralExpression().Elements.Nodes
	elements := l.checker.GetTypeArguments(tuple)
	if len(items) > len(elements) {
		return nil, l.notYet(node, "a tuple literal with more values than its tuple has elements")
	}
	literal := ir.ObjectLiteral{Tuple: true}
	// An optional element left out is undefined, a field of its own, as tuple[index] reads it.
	missing := []ir.Field{}
	for index := len(items); index < len(elements); index++ {
		of, isKnown := l.representation(elements[index])
		if !isKnown || slotless(of) || !l.includesUndefined(elements[index]) || !(of.IsMaybe() || of.IsReference()) {
			return nil, l.notYet(node, "a tuple literal leaving out an element of type "+l.checker.TypeToString(elements[index]))
		}
		missing = append(missing, ir.Field{Name: strconv.Itoa(index), Value: fit(ir.Undefined{}, of)})
	}
	for index, item := range items {
		if item.Kind == ast.KindSpreadElement || item.Kind == ast.KindOmittedExpression {
			return nil, l.notYet(item, describe(item)+" in a tuple literal")
		}
		of, isKnown := l.representation(elements[index])
		if !isKnown || slotless(of) {
			return nil, l.notYet(item, "a tuple element of type "+l.checker.TypeToString(elements[index]))
		}
		value, err := l.expression(item)
		if err != nil {
			return nil, err
		}
		if value = fit(value, of); value.Type() != of {
			if _, isUndefined := value.(ir.Undefined); !isUndefined || !of.IsReference() {
				return nil, l.notYet(item, "a tuple element of another type than its tuple's")
			}
		}
		literal.Fields = append(literal.Fields, ir.Field{Name: strconv.Itoa(index), Value: value})
	}
	literal.Fields = append(literal.Fields, missing...)
	return literal, nil
}

// hasSpread reports whether a call spreads an argument: Math.max(...values).
func hasSpread(call *ast.Node) bool {
	for _, argument := range call.AsCallExpression().Arguments.Nodes {
		if argument.Kind == ast.KindSpreadElement {
			return true
		}
	}
	return false
}

// spreadNumbers lowers a call's arguments, some of them spread, as the array of numbers they spell,
// evaluated in order, as [a, ...values, b] is.
func (l *lowering) spreadNumbers(call *ast.Node) (ir.Expression, error) {
	literal := ir.ArrayLiteral{Element: ir.Number}
	for _, argument := range call.AsCallExpression().Arguments.Nodes {
		spread := argument.Kind == ast.KindSpreadElement
		item := argument
		if spread {
			item = ast.SkipParentheses(argument.AsSpreadElement().Expression)
		}
		if spread && item.Kind == ast.KindArrayLiteralExpression {
			// ...[3, 4] is its elements, each an argument (the checker may type the literal a tuple).
			for _, element := range item.AsArrayLiteralExpression().Elements.Nodes {
				if element.Kind == ast.KindSpreadElement || element.Kind == ast.KindOmittedExpression {
					return nil, l.notYet(element, describe(element)+" in an array spread into a call")
				}
				value, err := l.expression(element)
				if err != nil {
					return nil, err
				}
				if value.Type() != ir.Number {
					return nil, l.notYet(element, "a "+typeName(value.Type())+" argument where numbers go")
				}
				literal.Elements = append(literal.Elements, value)
				literal.Spread = append(literal.Spread, false)
			}
			continue
		}
		value, err := l.expression(item)
		if err != nil {
			return nil, err
		}
		if spread {
			if element, err := l.elementType(item); err != nil || value.Type() != ir.Array || element != ir.Number {
				return nil, l.notYet(argument, "spreading other than an array of numbers into a call")
			}
		} else if value.Type() != ir.Number {
			return nil, l.notYet(argument, "a "+typeName(value.Type())+" argument where numbers go")
		}
		literal.Elements = append(literal.Elements, value)
		literal.Spread = append(literal.Spread, spread)
	}
	return literal, nil
}

// tupleWhereArrayGoes reports whether a value of type value, going where target is expected, carries a
// tuple to where an array is: directly, as an array's elements, as a Map's keys or values, as a field
// of an object, or as a function's result, or the other way round for a function's parameters (a
// function taking arrays called with tuples). A tuple is held as an object of its elements, so array
// code would read it as something it isn't; until a tuple can be one, it's refused there.
func (l *lowering) tupleWhereArrayGoes(value *checker.Type, target *checker.Type, depth int) bool {
	if value == nil || target == nil || value == target || depth > 4 {
		return false
	}
	if target.Flags()&checker.TypeFlagsUnion != 0 {
		// Into a union: fine if any member takes it as it is.
		for _, member := range target.Types() {
			if !l.tupleWhereArrayGoes(value, member, depth+1) {
				return false
			}
		}
		return true
	}
	if value.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range value.Types() {
			if l.tupleWhereArrayGoes(member, target, depth+1) {
				return true
			}
		}
		return false
	}
	valueTuple, targetTuple := checker.IsTupleType(value), checker.IsTupleType(target)
	switch {
	case valueTuple && !targetTuple && l.checker.IsArrayType(target):
		return true
	case valueTuple && targetTuple:
		return l.pairwiseTupleWhereArrayGoes(l.checker.GetTypeArguments(value), l.checker.GetTypeArguments(target), depth)
	case l.checker.IsArrayType(value) && l.checker.IsArrayType(target):
		return l.pairwiseTupleWhereArrayGoes(l.checker.GetTypeArguments(value), l.checker.GetTypeArguments(target), depth)
	case l.isLibraryType(value, "Map", "ReadonlyMap") && l.isLibraryType(target, "Map", "ReadonlyMap"):
		return l.pairwiseTupleWhereArrayGoes(l.checker.GetTypeArguments(value), l.checker.GetTypeArguments(target), depth)
	}
	if value.Flags()&checker.TypeFlagsObject == 0 || target.Flags()&checker.TypeFlagsObject == 0 {
		return false
	}
	valueSignatures := l.checker.GetSignaturesOfType(value, checker.SignatureKindCall)
	targetSignatures := l.checker.GetSignaturesOfType(target, checker.SignatureKindCall)
	if len(valueSignatures) == 1 && len(targetSignatures) == 1 {
		// A function: what it returns goes where the target's result goes, and what the target is
		// called with goes to its parameters.
		if l.tupleWhereArrayGoes(l.checker.GetReturnTypeOfSignature(valueSignatures[0]), l.checker.GetReturnTypeOfSignature(targetSignatures[0]), depth+1) {
			return true
		}
		valueParameters, targetParameters := valueSignatures[0].Parameters(), targetSignatures[0].Parameters()
		if l.censusNeverRestSignature(targetSignatures[0]) {
			targetParameters = nil
		}
		for index := range valueParameters {
			if index < len(targetParameters) && l.tupleWhereArrayGoes(l.checker.GetTypeOfSymbol(targetParameters[index]), l.checker.GetTypeOfSymbol(valueParameters[index]), depth+1) {
				return true
			}
		}
		return false
	}
	for _, field := range l.checker.GetPropertiesOfType(target) {
		if l.tupleWhereArrayGoes(l.checker.GetTypeOfPropertyOfType(value, field.Name), l.checker.GetTypeOfSymbol(field), depth+1) {
			return true
		}
	}
	return false
}

func (l *lowering) pairwiseTupleWhereArrayGoes(values []*checker.Type, targets []*checker.Type, depth int) bool {
	for index := range values {
		if index < len(targets) && l.tupleWhereArrayGoes(values[index], targets[index], depth+1) {
			return true
		}
	}
	return false
}

// updateIndex lowers array[index] op= value. The array and index are held before the element is
// read, and that read is held before the right side runs, exactly once each and in JavaScript's
// order. The final SetIndex uses those same held values even when the right side changes their source.
func (l *lowering) updateIndex(node *ast.Node, target *ast.Node, operator ast.Kind, valueNode *ast.Node) ([]ir.Statement, error) {
	if l.nodeBufferType(l.checker.GetTypeAtLocation(target.AsElementAccessExpression().Expression), "Buffer") {
		return nil, l.notYet(node, "a compound Buffer write outside the census")
	}
	access := target.AsElementAccessExpression()
	array, err := l.expression(access.Expression)
	if err != nil {
		return nil, err
	}
	if array.Type() != ir.Array {
		return nil, l.notYet(target, "assigning an element of a "+typeName(array.Type()))
	}
	element, err := l.elementType(access.Expression)
	if err != nil {
		return nil, err
	}
	if element != ir.Number {
		return nil, l.notYet(target, "updating an array element of type "+typeName(element))
	}
	index, err := l.expression(access.ArgumentExpression)
	if err != nil {
		return nil, err
	}
	if index.Type() != ir.Number {
		return nil, l.notYet(target, "an array index that isn't a number")
	}

	arrayLocal := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "array", Type: ir.Array, Function: l.functionIndex})
	indexLocal := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "index", Type: ir.Number, Function: l.functionIndex})
	currentLocal := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "element", Type: ir.Number, Function: l.functionIndex})
	arrayRead := ir.Read{Local: arrayLocal, Of: ir.Array}
	indexRead := ir.Read{Local: indexLocal, Of: ir.Number}
	current := ir.Unwrap{Value: ir.ArrayIndex{Array: arrayRead, Index: indexRead, Element: ir.Number}}
	right, err := l.expression(valueNode)
	if err != nil {
		return nil, err
	}
	updated, err := l.combine(node, operator, ir.Read{Local: currentLocal, Of: ir.Number}, right)
	if err != nil {
		return nil, err
	}
	return []ir.Statement{ir.Block{Body: []ir.Statement{
		ir.Declare{Local: arrayLocal, Value: array},
		ir.Declare{Local: indexLocal, Value: index},
		ir.Declare{Local: currentLocal, Value: current},
		ir.SetIndex{Array: arrayRead, Index: indexRead, Value: updated, Element: ir.Number, Site: l.writeSite(access.Expression)},
	}}}, nil
}

// isCallee reports whether a property read is the expression a call calls, parentheses aside.
func isCallee(node *ast.Node) bool {
	for node.Parent != nil && node.Parent.Kind == ast.KindParenthesizedExpression {
		node = node.Parent
	}
	return node.Parent != nil && node.Parent.Kind == ast.KindCallExpression && node.Parent.AsCallExpression().Expression == node
}

optional.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// optionalStrings are the optional string parameters of the library methods stage 0 lowers, by
// method and position, with what JavaScript uses when the argument is undefined. These are every one
// in lib.es2024 on a method lowered here (checked against the bundled library's declarations:
// padStart and padEnd's padString, normalize's form, and join's separator, which arrayMethod gives
// its default); localeCompare and the
// toLocale methods take others, and aren't lowered.
var optionalStrings = map[string]map[int]string{
	"padStart":  {1: " "},
	"padEnd":    {1: " "},
	"normalize": {0: "NFC"},
}

// orDefault is an argument to an optional string parameter, as JavaScript reads it: undefined is the
// parameter's default. A string that may be undefined is held as a null reference, which the runtime
// would read as a string, so it's given the default here, where undefined is still visible: undefined
// written out becomes the default itself, and a string | undefined becomes value ?? default.
func (l *lowering) orDefault(node *ast.Node, value ir.Expression, fallback string) ir.Expression {
	if _, isUndefined := value.(ir.Undefined); isUndefined {
		return ir.StringConstant{Index: l.constant(fallback)}
	}
	if value.Type() != ir.String || !l.mayBeUndefined(node) {
		return value
	}
	return ir.Coalesce{Value: value, Fallback: ir.StringConstant{Index: l.constant(fallback)}, Of: ir.String}
}

// mayBeUndefined reports whether the checker's type for a node includes undefined.
func (l *lowering) mayBeUndefined(node *ast.Node) bool {
	proven := l.checker.GetTypeAtLocation(node)
	if proven.Flags()&checker.TypeFlagsUndefined != 0 {
		return true
	}
	return proven.Flags()&checker.TypeFlagsUnion != 0 && l.includesUndefined(proven)
}

optional_indexing.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// Save the base before the guard. The index belongs only to the present arm,
// and the ordinary lookup retains its missing-element representation.
func (l *lowering) optionalIndex(node *ast.Node, base ir.Expression) (ir.Expression, error) {
	function := -1
	if l.function != nil {
		function = l.functionIndex
	}
	local := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "optional_index_base", Type: base.Type(), Function: function, ExpressionAssigned: true})
	read := ir.Read{Local: local, Of: base.Type()}
	value, err := l.optionalIndexValue(node, read)
	if err != nil {
		return nil, err
	}
	of := value.Type()
	return ir.Effects{Body: []ir.Statement{ir.Declare{Local: local, Value: base}}, Result: ir.Conditional{
		Condition: ir.Unary{Operator: ir.Not, Operand: ir.Binary{Operator: ir.Or, Left: ir.IsUndefined{Value: read}, Right: ir.IsNull{Value: read}}},
		WhenTrue:  value, WhenNot: fit(ir.Undefined{}, of), Of: of,
	}}, nil
}

func (l *lowering) optionalIndexValue(node *ast.Node, base ir.Expression) (ir.Expression, error) {
	access := node.AsElementAccessExpression()
	index, err := l.expression(access.ArgumentExpression)
	if err != nil {
		return nil, err
	}
	if index.Type() != ir.Number {
		return nil, l.notYet(node, "an optional index that isn't a number")
	}
	var value ir.Expression
	if base.Type() == ir.String {
		value = ir.StringIndex{Value: base, Index: index}
	} else {
		element := ir.Number
		if !base.Type().IsTypedArray() {
			element, err = l.elementType(access.Expression)
			if err != nil {
				return nil, err
			}
		}
		value = ir.ArrayIndex{Array: base, Index: index, Element: element}
	}
	return value, nil
}

optional_indexing_chain.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// This continuation owns only a?.field[index]. The receiver guard must skip
// the index, while a missing element still reaches a following optional read.
func (l *lowering) optionalIndexContinuation(node *ast.Node) (ir.Expression, error) {
	access := node.AsElementAccessExpression()
	receiver := access.Expression
	// Parentheses terminate a continuous chain; do not skip them here.
	if receiver.Kind != ast.KindPropertyAccessExpression {
		return nil, l.notYet(node, "an optional chain longer than one step")
	}
	field := receiver.AsPropertyAccessExpression()
	if field.QuestionDotToken == nil {
		return nil, l.notYet(node, "an optional chain longer than one step")
	}
	value, err := l.property(receiver)
	if err != nil {
		return nil, err
	}
	property, known := value.(ir.Property)
	if !known || property.Absent || property.Method || property.Of == ir.Weak || !(property.Of == ir.Array || property.Of == ir.String || property.Of.IsTypedArray()) {
		return nil, l.notYet(node, "an indexing continuation without a required array or string field")
	}
	function := -1
	if l.function != nil {
		function = l.functionIndex
	}
	local := len(l.result.Locals)
	base := property.Object
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "optional_index_chain_base", Type: base.Type(), Function: function, ExpressionAssigned: true})
	read := ir.Read{Local: local, Of: base.Type()}
	property.Object, property.Optional = read, false
	indexed, err := l.optionalIndexValue(node, property)
	if err != nil {
		return nil, err
	}
	of := indexed.Type()
	return ir.Effects{Body: []ir.Statement{ir.Declare{Local: local, Value: base}}, Result: ir.Conditional{
		Condition: ir.Unary{Operator: ir.Not, Operand: ir.Binary{Operator: ir.Or, Left: ir.IsUndefined{Value: read}, Right: ir.IsNull{Value: read}}},
		WhenTrue:  indexed, WhenNot: fit(ir.Undefined{}, of), Of: of,
	}}, nil
}

optional_indexing_map.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// A Map lookup guards the receiver, not the library method. The key is
// evaluated only after that guard and the ordinary lookup keeps undefined.
func (l *lowering) optionalMapGet(node *ast.Node) (ir.Expression, bool, error) {
	call := node.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	if call.QuestionDotToken != nil || callee.Kind != ast.KindPropertyAccessExpression {
		return nil, false, nil
	}
	access := callee.AsPropertyAccessExpression()
	if access.QuestionDotToken == nil || access.Name().Text() != "get" || !l.libraryMember(callee) {
		return nil, false, nil
	}
	proven := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(access.Expression))
	if !l.isLibraryType(proven, "Map", "ReadonlyMap") {
		return nil, false, nil
	}
	if len(call.Arguments.Nodes) != 1 || hasSpread(node) {
		return nil, true, l.notYet(node, "an optional Map get with other than one key")
	}
	if l.optionalMapStructuralReceiver(access.Expression) {
		return nil, true, l.notYet(node, "an optional Map get through a structural receiver")
	}

	types := l.typeArguments(proven)
	if len(types) != 2 {
		return nil, true, l.notYet(node, "an optional Map get without key and value types")
	}
	keyType, keyKnown := l.representation(types[0])
	valueType, valueKnown := l.kept(types[1])
	if !keyKnown || !keyable(keyType) || !valueKnown || (slotless(valueType) && !(valueType == ir.Union && l.writable(types[1]))) {
		return nil, true, l.notYet(node, "an optional Map get with unsupported key or value storage")
	}
	base, err := l.expression(access.Expression)
	if err != nil {
		return nil, true, err
	}
	key, err := l.expression(call.Arguments.Nodes[0])
	if err != nil {
		return nil, true, err
	}
	key = fit(key, keyType)
	if base.Type() != ir.Map || key.Type() != keyType {
		return nil, true, l.notYet(node, "an optional Map get with incompatible receiver or key storage")
	}
	function := -1
	if l.function != nil {
		function = l.functionIndex
	}
	local := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "optional_map_base", Type: ir.Map, Function: function, ExpressionAssigned: true})
	read := ir.Read{Local: local, Of: ir.Map}
	value := ir.MapGet{Map: read, Key: key, KeyType: keyType, ValueType: valueType}
	of := value.Type()
	return ir.Effects{Body: []ir.Statement{ir.Declare{Local: local, Value: base}}, Result: ir.Conditional{
		Condition: ir.Unary{Operator: ir.Not, Operand: ir.Binary{Operator: ir.Or, Left: ir.IsUndefined{Value: read}, Right: ir.IsNull{Value: read}}},
		WhenTrue:  value, WhenNot: fit(ir.Undefined{}, of), Of: of,
	}}, true, nil
}

// A library interface alone does not prove the receiver uses native Map storage.
// Keep compatible object literals and constructed custom receivers out of the
// intrinsic path, including ones hidden behind a ReadonlyMap annotation.
func (l *lowering) optionalMapStructuralReceiver(receiver *ast.Node) bool {
	view := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(receiver))
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return true
	}
	hazard := false
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if hazard {
			return true
		}
		if node.Kind == ast.KindObjectLiteralExpression || node.Kind == ast.KindNewExpression {
			shape := l.checker.GetTypeAtLocation(node)
			if l.checker.IsTypeAssignableTo(shape, view) {
				representation, known := l.representation(shape)
				member := l.checker.GetPropertyOfType(shape, "get")
				if !known || representation != ir.Map || member == nil || !l.librarySymbol(member) {
					hazard = true
					return true
				}
			}
		}
		node.ForEachChild(visit)
		return false
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return hazard
}

optional_intrinsic.go:
package lower

import (
	"reflect"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// Receiver-optional, zero-argument library methods need one saved receiver and
// a missing result. An optional function call has a different guard and ABI.
func (l *lowering) optionalIntrinsic(node *ast.Node) (ir.Expression, bool, error) {
	if value, handled, err := l.optionalMapGet(node); handled {
		return value, true, err
	}
	call := node.AsCallExpression()
	if call.QuestionDotToken != nil || len(call.Arguments.Nodes) != 0 {
		return nil, false, nil
	}
	callee := ast.SkipParentheses(call.Expression)
	if callee.Kind != ast.KindPropertyAccessExpression || !l.libraryMember(callee) {
		return nil, false, nil
	}
	access := callee.AsPropertyAccessExpression()
	if access.QuestionDotToken == nil {
		return nil, false, nil
	}
	value, known, err := l.builtin(node)
	if !known || err != nil {
		return nil, known, err
	}
	receiver, err := l.expression(access.Expression)
	if err != nil {
		return nil, true, err
	}
	if !receiver.Type().IsReference() || value.Type() == 0 {
		return nil, true, l.notYet(node, "an optional intrinsic without a reference receiver and a value result")
	}
	of, err := l.typeOf(node)
	if err != nil {
		return nil, true, err
	}
	occurrences := 0
	walk(value, func(node any) bool {
		if expression, ok := node.(ir.Expression); ok && reflect.DeepEqual(expression, receiver) {
			occurrences++
			return false
		}
		return true
	})
	if occurrences != 1 {
		return nil, true, l.notYet(node, "an optional intrinsic without exactly one explicit receiver operand")
	}
	function := -1
	if l.function != nil {
		function = l.functionIndex
	}
	local := len(l.result.Locals)
	read := ir.Read{Local: local, Of: receiver.Type()}
	replaced := false
	var replace func(reflect.Value) reflect.Value
	replace = func(v reflect.Value) reflect.Value {
		if !v.IsValid() {
			return v
		}
		if !replaced && v.CanInterface() {
			if expression, ok := v.Interface().(ir.Expression); ok && reflect.DeepEqual(expression, receiver) {
				replaced = true
				if v.Kind() == reflect.Interface {
					r := reflect.New(v.Type()).Elem()
					r.Set(reflect.ValueOf(read))
					return r
				}
				return reflect.ValueOf(read)
			}
		}
		switch v.Kind() {
		case reflect.Interface:
			if v.IsNil() {
				return v
			}
			r := reflect.New(v.Type()).Elem()
			r.Set(replace(v.Elem()))
			return r
		case reflect.Struct:
			r := reflect.New(v.Type()).Elem()
			for i := 0; i < v.NumField(); i++ {
				r.Field(i).Set(replace(v.Field(i)))
			}
			return r
		case reflect.Slice:
			if v.IsNil() {
				return v
			}
			r := reflect.MakeSlice(v.Type(), v.Len(), v.Len())
			for i := 0; i < v.Len(); i++ {
				r.Index(i).Set(replace(v.Index(i)))
			}
			return r
		}
		return v
	}
	lowered := replace(reflect.ValueOf(value)).Interface().(ir.Expression)
	if !replaced {
		return nil, true, l.notYet(node, "an optional intrinsic whose receiver is not an explicit operand")
	}
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "optional_intrinsic_receiver", Type: receiver.Type(), Function: function, ExpressionAssigned: true})
	return ir.Effects{Body: []ir.Statement{ir.Declare{Local: local, Value: receiver}}, Result: ir.Conditional{
		Condition: ir.Unary{Operator: ir.Not, Operand: ir.IsUndefined{Value: read}},
		WhenTrue:  fit(lowered, of), WhenNot: fit(ir.Undefined{}, of), Of: of,
	}}, true, nil
}

optional_join.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// Only receiver-optional intrinsic join is supported here. Its arguments belong
// inside the present branch, and the receiver must be held before that branch.
func (l *lowering) isOptionalJoin(node *ast.Node) bool {
	call := node.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	if call.QuestionDotToken != nil || callee.Kind != ast.KindPropertyAccessExpression {
		return false
	}
	access := callee.AsPropertyAccessExpression()
	if access.QuestionDotToken == nil || access.Name().Text() != "join" {
		return false
	}
	of, known := l.representation(l.checker.GetTypeAtLocation(access.Expression))
	return known && of == ir.Array && l.libraryMember(callee)
}

func (l *lowering) optionalJoin(node *ast.Node) (ir.Expression, error) {
	receiver := ast.SkipParentheses(node.AsCallExpression().Expression).AsPropertyAccessExpression().Expression
	value, _, err := l.arrayMethod(node, receiver, "join")
	if err != nil {
		return nil, err
	}
	join := value.(ir.ArrayJoin)
	function := -1
	if l.function != nil {
		function = l.functionIndex
	}
	local := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "optional_join_receiver", Type: ir.Array, Function: function, ExpressionAssigned: true})
	read := ir.Read{Local: local, Of: ir.Array}
	array := join.Array
	join.Array = read
	return ir.Effects{Body: []ir.Statement{ir.Declare{Local: local, Value: array}}, Result: ir.Conditional{
		Condition: ir.Truthy{Value: read}, WhenTrue: join, WhenNot: ir.Undefined{}, Of: ir.String,
	}}, nil
}

