optional_widening.go:
package lower

import (
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
)

// optionalWidening names the relation whose optional field could be hidden by a structural view.
// This is independent of mutable invariance: even a readonly optional field can lie on a read.
type optionalWidening struct {
	property       string
	source, target *checker.Type
}

func (l *lowering) optionalWidened(source, target *checker.Type, skip map[string]bool, visited map[[2]*checker.Type]bool) *optionalWidening {
	if source == nil || target == nil {
		return nil
	}
	if weak := l.weakTarget(source); weak != nil {
		source = weak
	}
	if weak := l.weakTarget(target); weak != nil {
		target = weak
	}
	// Only an accepted assignment is a widening. Function rest parameters and checked
	// downcasts can pair unrelated types; those belong to their own relation rules.
	if skip == nil && !l.checker.IsTypeAssignableTo(source, target) {
		return nil
	}
	if source == target || visited[[2]*checker.Type{source, target}] {
		return nil
	}
	visited[[2]*checker.Type{source, target}] = true
	if source.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range source.Types() {
			if found := l.optionalWidened(member, target, skip, visited); found != nil {
				return found
			}
		}
		return nil
	}
	if target.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range target.Types() {
			if l.checker.IsTypeAssignableTo(source, member) {
				if found := l.optionalWidened(source, member, skip, visited); found != nil {
					return found
				}
			}
		}
		return nil
	}
	if source.Flags()&checker.TypeFlagsTypeParameter != 0 {
		return l.optionalWidened(l.checker.GetBaseConstraintOfType(source), target, skip, visited)
	}
	if target.Flags()&checker.TypeFlagsTypeParameter != 0 {
		return l.optionalWidened(source, l.checker.GetBaseConstraintOfType(target), skip, visited)
	}
	if source.Flags()&(checker.TypeFlagsObject|checker.TypeFlagsIntersection) == 0 || target.Flags()&(checker.TypeFlagsObject|checker.TypeFlagsIntersection) == 0 {
		return nil
	}
	// Container elements are views too. Avoid walking library methods, whose generic signatures
	// describe operations rather than value fields.
	if (l.checker.IsArrayType(source) || checker.IsTupleType(source)) && (l.checker.IsArrayType(target) || checker.IsTupleType(target)) {
		sources, targets := l.checker.GetTypeArguments(source), l.checker.GetTypeArguments(target)
		for index, inside := range sources {
			at := index
			if !checker.IsTupleType(target) {
				at = 0
			}
			if at < len(targets) {
				if found := l.optionalWidened(inside, targets[at], nil, visited); found != nil {
					return found
				}
			}
		}
		return nil
	}
	for _, property := range l.checker.GetPropertiesOfType(target) {
		if skip[property.Name] {
			continue
		}
		declared := l.checker.GetPropertyOfType(source, property.Name)
		if declared == nil {
			if property.Flags&ast.SymbolFlagsOptional != 0 && !isClassInstance(source) {
				return &optionalWidening{property: property.Name, source: source, target: target}
			}
			continue
		}
		if found := l.optionalWidened(l.checker.GetTypeOfSymbol(declared), l.checker.GetTypeOfSymbol(property), nil, visited); found != nil {
			return found
		}
	}
	sources := l.checker.GetSignaturesOfType(source, checker.SignatureKindCall)
	targets := l.checker.GetSignaturesOfType(target, checker.SignatureKindCall)
	if len(sources) == 1 && len(targets) == 1 && len(sources[0].TypeParameters()) == 0 && len(targets[0].TypeParameters()) == 0 {
		if found := l.optionalWidened(l.checker.GetReturnTypeOfSignature(sources[0]), l.checker.GetReturnTypeOfSignature(targets[0]), nil, visited); found != nil {
			return found
		}
		takes, gives := sources[0].Parameters(), targets[0].Parameters()
		for index := 0; index < len(takes) && index < len(gives); index++ {
			if found := l.optionalWidened(l.checker.GetTypeOfSymbol(gives[index]), l.checker.GetTypeOfSymbol(takes[index]), nil, visited); found != nil {
				return found
			}
		}
	}
	return nil
}

func (l *lowering) optionalValue(node *ast.Node, target *checker.Type) *optionalWidening {
	node = ast.SkipParentheses(node)
	switch node.Kind {
	case ast.KindObjectLiteralExpression, ast.KindArrayLiteralExpression:
		// The literal's fields, spreads and elements are checked separately at their own sites.
		return nil
	case ast.KindConditionalExpression:
		conditional := node.AsConditionalExpression()
		for _, branch := range []*ast.Node{conditional.WhenTrue, conditional.WhenFalse} {
			if found := l.optionalValue(branch, target); found != nil {
				return found
			}
		}
		return nil
	}
	return l.optionalWidened(l.checker.GetTypeAtLocation(node), target, nil, map[[2]*checker.Type]bool{})
}

// optionalAtSite uses the same relation sites as the other view rules, before lowering.
// A leading spread is not proof of absence: it copies fields hidden by the source's type too.
func (l *lowering) optionalAtSite(node *ast.Node) *optionalWidening {
	if l.nodeFSFileReadOnlyArgument(node) {
		return nil
	}
	// Only argument positions of a directly imported node:* call can use the host exemption.
	if parent := node.Parent; parent != nil && parent.Kind == ast.KindCallExpression && l.optionalNodeHostCall(parent) {
		for index, argument := range parent.AsCallExpression().Arguments.Nodes {
			if argument == node && l.nodeHostConsumesArgument(parent, index) {
				return nil
			}
		}
	}
	var found *optionalWidening
	switch node.Kind {
	case ast.KindAsExpression:
		found = l.optionalValue(node.AsAsExpression().Expression, l.checker.GetTypeAtLocation(node))
	case ast.KindShorthandPropertyAssignment:
		target := l.checker.GetContextualType(node.Parent, checker.ContextFlagsNone)
		if target != nil {
			found = l.optionalValue(node.Name(), l.checker.GetTypeOfPropertyOfType(target, node.Name().Text()))
		}
	case ast.KindSpreadAssignment:
		target := l.checker.GetContextualType(node.Parent, checker.ContextFlagsNone)
		if target == nil {
			return nil
		}
		skip := map[string]bool{}
		after := false
		for _, property := range node.Parent.AsObjectLiteralExpression().Properties.Nodes {
			if property == node {
				after = true
			} else if after && property.Name() != nil {
				skip[property.Name().Text()] = true
			}
		}
		expression := ast.SkipParentheses(node.AsSpreadAssignment().Expression)
		if expression.Kind != ast.KindObjectLiteralExpression {
			found = l.optionalWidened(l.checker.GetTypeAtLocation(expression), target, skip, map[[2]*checker.Type]bool{})
		}
	default:
		if node.Kind == ast.KindParenthesizedExpression || !l.isExpression(node) || l.genericFunction(node) {
			return nil
		}
		var target *checker.Type
		if viewSite(node) {
			target = l.checker.GetContextualType(node, checker.ContextFlagsNone)
		}
		if target == nil {
			target = l.impliedTarget(node)
		}
		if target == nil {
			return nil
		}
		found = l.optionalValue(node, target)
	}
	return found
}

func (l *lowering) refuseOptionalWidening(node *ast.Node) error {
	found := l.optionalAtSite(node)
	if found == nil {
		return nil
	}
	return &Refused{Where: l.program.Where(node),
		What: "optional property " + found.property + " in " + l.checker.TypeToString(found.target) + " absent from structural source " + l.checker.TypeToString(found.source) + ", which can hide fields",
		Fix:  "declare " + found.property + " on the source type, or build a fresh object with known fields (adamic/no-optional-widening)"}
}

// Resolve the import binding rather than trusting the callee's spelling.
func (l *lowering) optionalNodeHostCall(call *ast.Node) bool {
	callee := ast.SkipParentheses(call.AsCallExpression().Expression)
	if callee.Kind == ast.KindPropertyAccessExpression {
		callee = ast.SkipParentheses(callee.AsPropertyAccessExpression().Expression)
	}
	symbol := l.checker.GetSymbolAtLocation(callee)
	if symbol == nil {
		return false
	}
	for _, declaration := range symbol.Declarations {
		for ancestor := declaration; ancestor != nil; ancestor = ancestor.Parent {
			if ancestor.Kind == ast.KindImportDeclaration {
				specifier := ancestor.ModuleSpecifier()
				return specifier != nil && strings.HasPrefix(specifier.Text(), "node:")
			}
		}
	}
	return false
}

parameter_properties.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

func parameterProperty(node *ast.Node) bool {
	return node.Kind == ast.KindParameter && ast.HasSyntacticModifier(node, ast.ModifierFlagsParameterPropertyModifier)
}

// Node's transform declares parameter-property slots before the written fields. The parameters'
// defaults are not field initializers: stores run after defaults, and after super in a derived class.
func classMembersWithParameters(declaration *ast.Node) []*ast.Node {
	members := []*ast.Node{}
	for _, member := range declaration.Members() {
		if member.Kind == ast.KindConstructor {
			for _, parameter := range member.Parameters() {
				if parameterProperty(parameter) {
					members = append(members, parameter)
				}
			}
		}
	}
	return append(members, declaration.Members()...)
}

func (l *lowering) parameterPropertyStores(declaration *ast.Node, this int) ([]ir.Statement, error) {
	statements := []ir.Statement{}
	for _, parameter := range classMembersWithParameters(declaration) {
		if !parameterProperty(parameter) {
			continue
		}
		local, found := l.locals[l.symbol(parameter.Name())]
		if !found {
			return nil, l.notYet(parameter, "a parameter property without a bound parameter")
		}
		of, err := l.typeOf(parameter.Name())
		if err != nil {
			return nil, err
		}
		statements = append(statements, ir.SetProperty{Object: ir.Read{Local: this, Of: ir.Object}, Name: parameter.Name().Text(), Value: fit(ir.Read{Local: local, Of: l.result.Locals[local].Type}, of), Site: l.writeSite(declaration.Name())})
	}
	return statements, nil
}

// The checker permits a default to read a parameter property that has not been copied yet.
// Node reads undefined there. A declared number slot cannot claim that value, so require an
// already initialized written field instead. Calls and deferred captures are checked conservatively.
func (l *lowering) parameterPropertyDefault(declaration, initializer *ast.Node) error {
	hasProperties := false
	available := map[string]bool{}
	for _, member := range classMembersWithParameters(declaration.Parent) {
		hasProperties = hasProperties || parameterProperty(member)
		if member.Kind == ast.KindPropertyDeclaration && member.AsPropertyDeclaration().Initializer != nil && !ast.HasSyntacticModifier(member, ast.ModifierFlagsStatic) {
			available[l.fieldName(member.Name())] = true
		}
	}
	if !hasProperties {
		return nil
	}
	return l.initializerReads(initializer, available)
}

// A derived parameter-property declaration defines its own slot after super, resetting any
// inherited property of the same name before the written field initializers run.
func (l *lowering) parameterPropertyResets(declaration *ast.Node, this int, available map[string]bool) ([]ir.Statement, error) {
	if l.instance.base == nil {
		return nil, nil
	}
	statements := []ir.Statement{}
	for _, parameter := range classMembersWithParameters(declaration) {
		if !parameterProperty(parameter) {
			continue
		}
		delete(available, parameter.Name().Text())
		of, err := l.typeOf(parameter.Name())
		if err != nil {
			return nil, err
		}
		value := zeroValue(of)
		if of.IsReference() {
			value = ir.Undefined{Of: of}
		}
		statements = append(statements, ir.SetProperty{Object: ir.Read{Local: this, Of: ir.Object}, Name: parameter.Name().Text(), Value: value, Site: l.writeSite(declaration.Name())})
	}
	return statements, nil
}

predicates.go:
package lower

import (
	"fmt"
	_ "unsafe"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/microsoft/TypeScript/tsc/shim/scanner"
)

// As in instantiate.go, this calls the pinned checker's own implementation until its shim
// exports it. The annotation is a claimed postcondition, never a flow fact. The flow nodes below contain
// only checks independently trusted by Adamic, not assertion calls or assignments.
//
//go:linkname predicateFlowType github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).getFlowTypeOfReferenceEx
func predicateFlowType(receiver *checker.Checker, reference *ast.Node, declared, initial *checker.Type, container *ast.Node, flow *ast.FlowNode) *checker.Type

type predicateFlowProof struct {
	l          *lowering
	function   *ast.Node
	parameter  *ast.Node
	declared   *checker.Type
	admitted   *checker.Type
	target     *checker.Type
	assertion  bool
	trueTypes  []*checker.Type
	lastReturn *ast.Node
}

type predicateFlowPath struct {
	flow    *ast.FlowNode
	checked bool
}

func (p *predicateFlowProof) refused(node *ast.Node, reason string) error {
	return &Refused{Where: p.l.program.Where(node), What: "a type predicate whose return is not proven (" + reason + ")", Fix: "inline the check where you use it, or return a discriminant comparison on the unmodified parameter (adamic/no-type-predicate)"}
}

func (l *lowering) proveFlowPredicate(node *ast.Node) error {
	if l.censusPredicateMarkerContract(node) {
		return nil
	}
	annotation := node.AsTypePredicateNode()
	function := node.Parent
	if !ast.IsFunctionLike(function) || function.Body() == nil || annotation.ParameterName.Kind != ast.KindIdentifier {
		return (&predicateFlowProof{l: l}).refused(node, "there is no body proving this parameter")
	}
	var parameter *ast.Node
	for _, candidate := range function.Parameters() {
		if ast.IsIdentifier(candidate.Name()) && candidate.Name().Text() == annotation.ParameterName.Text() {
			parameter = candidate
			break
		}
	}
	p := &predicateFlowProof{l: l, function: function, parameter: parameter, assertion: annotation.AssertsModifier != nil}
	if parameter == nil || parameter.AsParameterDeclaration().Initializer != nil || parameter.AsParameterDeclaration().DotDotDotToken != nil {
		return p.refused(node, "the predicate must name an unchanged plain parameter")
	}
	p.declared = l.checker.GetTypeAtLocation(parameter.Name())
	if annotation.Type != nil {
		p.target = l.checker.GetTypeFromTypeNode(annotation.Type)
	} else {
		// asserts cond is accepted only for a boolean parameter, with a proven true postcondition.
		if p.declared.Flags()&checker.TypeFlagsBooleanLike == 0 {
			return p.refused(node, "asserts cond needs a boolean parameter")
		}
		p.target = predicateTrueType(l.checker)
	}
	// A rebinding changes the value being tested, not the caller's argument. Include writes in
	// nested closures, even if the checker happens to retain a narrowing across their calls.
	var changed *ast.Node
	var visit ast.Visitor
	visit = func(current *ast.Node) bool {
		if current.Kind == ast.KindIdentifier && l.checker.GetSymbolAtLocation(current) == l.checker.GetSymbolAtLocation(parameter.Name()) && ast.IsAssignmentTarget(current) {
			changed = current
		}
		current.ForEachChild(visit)
		return false
	}
	function.Body().ForEachChild(visit)
	if changed != nil {
		return p.refused(changed, "the predicate parameter is assigned")
	}
	return p.proveBody(node)
}

func (p *predicateFlowProof) proveBody(node *ast.Node) error {
	function := p.function
	paths := []predicateFlowPath{{flow: &ast.FlowNode{Flags: ast.FlowFlagsStart}}}
	var remaining []predicateFlowPath
	var err error
	if function.Body().Kind == ast.KindBlock {
		remaining, err = p.statement(function.Body(), paths)
	} else {
		err = p.returned(function.Body(), function.Body(), paths)
	}
	if err != nil {
		return err
	}
	for _, path := range remaining {
		if !p.assertion {
			return p.refused(function.Body(), "implicit return is not a proven boolean")
		}
		if err := p.normalReturn(function.Body(), path); err != nil {
			return err
		}
	}
	if !p.assertion && len(p.trueTypes) > 0 && !checker.Checker_isTypeIdenticalTo(p.l.checker, p.l.checker.GetUnionType(p.trueTypes), p.target) {
		return p.refused(p.lastReturn, "the body's true narrowing does not match "+p.l.checker.TypeToString(p.target))
	}
	return nil
}

func (p *predicateFlowProof) narrowed(path predicateFlowPath, initial *checker.Type) *checker.Type {
	if path.flow.Node != nil && p.l.isArrayPredicateCall(path.flow.Node) && p.reference(ast.SkipParentheses(ast.SkipParentheses(path.flow.Node).AsCallExpression().Arguments.Nodes[0])) {
		return p.l.arrayPredicateMembers(initial, path.flow.Flags&ast.FlowFlagsTrueCondition != 0)
	}
	if p.admitted != nil && initial == p.declared {
		initial = p.admitted
	}
	return p.l.concrete(predicateFlowType(p.l.checker, p.parameter.Name(), p.declared, initial, p.function, path.flow))
}

func predicateBranch(path predicateFlowPath, expression *ast.Node, truth bool) predicateFlowPath {
	flags := ast.FlowFlagsFalseCondition
	if truth {
		flags = ast.FlowFlagsTrueCondition
	}
	return predicateFlowPath{flow: &ast.FlowNode{Flags: flags, Node: expression, Antecedent: path.flow}, checked: true}
}

// Immutable scalar arguments carry their admitted value type into the body.
// An object view does not certify its current tag without an actual test.
func (p *predicateFlowProof) admittedValueProof() bool {
	return p.admitted != nil && p.target.Flags()&(checker.TypeFlagsNumberLike|checker.TypeFlagsStringLike|checker.TypeFlagsBooleanLike|checker.TypeFlagsUndefined) != 0
}

func (p *predicateFlowProof) normalReturn(node *ast.Node, path predicateFlowPath) error {
	narrowed := p.narrowed(path, p.declared)
	if (!path.checked && !p.admittedValueProof()) || !checker.Checker_isTypeIdenticalTo(p.l.checker, narrowed, p.target) || p.l.nominalMismatch(narrowed, p.target, map[[2]*checker.Type]bool{}) != nil {
		return p.refused(node, "normal return has not narrowed "+p.parameter.Name().Text()+" to "+p.l.checker.TypeToString(p.target))
	}
	return nil
}

func (p *predicateFlowProof) returned(node, expression *ast.Node, paths []predicateFlowPath) error {
	p.lastReturn = node
	if p.assertion {
		if expression != nil {
			return p.refused(node, "an assertion must return without a value")
		}
		for _, path := range paths {
			if err := p.normalReturn(node, path); err != nil {
				return err
			}
		}
		return nil
	}
	if expression == nil {
		return p.refused(node, "return has no boolean check")
	}
	expression = ast.SkipParentheses(expression)
	literal := expression.Kind == ast.KindTrueKeyword || expression.Kind == ast.KindFalseKeyword
	if !literal && !p.check(expression) {
		return p.refused(node, "return expression is not a trusted check on "+p.parameter.Name().Text())
	}
	for _, path := range paths {
		for _, truth := range []bool{true, false} {
			if literal && truth != (expression.Kind == ast.KindTrueKeyword) {
				continue
			}
			branch := path
			if !literal {
				branch = predicateBranch(path, expression, truth)
			}
			// For a false path, an argument initially in the claimed type must be
			// impossible, as for inferred predicates. That proves the caller's else
			// narrowing independently of the true-return comparison.
			if truth {
				narrowed := p.narrowed(branch, p.declared)
				if (!branch.checked && !p.admittedValueProof()) || !p.l.checker.IsTypeAssignableTo(narrowed, p.target) || p.l.nominalMismatch(narrowed, p.target, map[[2]*checker.Type]bool{}) != nil {
					return p.refused(node, "true return narrows to "+p.l.checker.TypeToString(narrowed)+", not "+p.l.checker.TypeToString(p.target))
				}
				p.trueTypes = append(p.trueTypes, narrowed)
			} else if p.narrowed(branch, p.target).Flags()&checker.TypeFlagsNever == 0 {
				return p.refused(node, "false return can still contain "+p.l.checker.TypeToString(p.target))
			}
		}
	}
	return nil
}

func (p *predicateFlowProof) statement(node *ast.Node, paths []predicateFlowPath) ([]predicateFlowPath, error) {
	if len(paths) == 0 {
		return nil, nil
	}
	if len(paths) > 256 {
		return nil, p.refused(node, "too many return paths to prove")
	}
	switch node.Kind {
	case ast.KindBlock:
		for _, statement := range node.AsBlock().Statements.Nodes {
			var err error
			paths, err = p.statement(statement, paths)
			if err != nil {
				return nil, err
			}
		}
		return paths, nil
	case ast.KindIfStatement:
		statement := node.AsIfStatement()
		if !p.check(statement.Expression) {
			return nil, p.refused(node, "branch is not a trusted parameter check")
		}
		var then, otherwise []predicateFlowPath
		for _, path := range paths {
			then = append(then, predicateBranch(path, statement.Expression, true))
			otherwise = append(otherwise, predicateBranch(path, statement.Expression, false))
		}
		then, err := p.statement(statement.ThenStatement, then)
		if err != nil {
			return nil, err
		}
		if statement.ElseStatement != nil {
			otherwise, err = p.statement(statement.ElseStatement, otherwise)
			if err != nil {
				return nil, err
			}
		}
		return append(then, otherwise...), nil
	case ast.KindReturnStatement:
		return nil, p.returned(node, node.AsReturnStatement().Expression, paths)
	case ast.KindThrowStatement:
		return nil, nil
	case ast.KindEmptyStatement:
		return paths, nil
	case ast.KindExpressionStatement, ast.KindVariableStatement:
		if node.Kind == ast.KindExpressionStatement && p.l.isPanicCall(node.Expression()) {
			return nil, nil
		}
		if predicateEffects(node) {
			// Unknown calls and all writes can invalidate discriminants through an alias. Starting
			// over also prevents the checker from retaining stale readonly-property facts.
			for index := range paths {
				paths[index] = predicateFlowPath{flow: &ast.FlowNode{Flags: ast.FlowFlagsStart}}
			}
		}
		return paths, nil
	default:
		return nil, p.refused(node, fmt.Sprintf("return paths through %s are not verified", node.Kind))
	}
}

// check recognizes only independently trusted narrowing expressions, with no calls, aliases,
// casts or computed property accesses. The checker still decides what each branch proves.
func (p *predicateFlowProof) check(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindPrefixUnaryExpression && node.AsPrefixUnaryExpression().Operator == ast.KindExclamationToken {
		return p.check(node.AsPrefixUnaryExpression().Operand)
	}
	if p.assertion && p.target == predicateTrueType(p.l.checker) && p.reference(node) {
		return true
	}
	if p.l.isArrayPredicateCall(node) {
		return p.reference(ast.SkipParentheses(node.AsCallExpression().Arguments.Nodes[0])) && (p.l.arrayPredicateDomain(p.declared) || p.declared.Flags()&checker.TypeFlagsUnknown != 0)
	}
	if node.Kind != ast.KindBinaryExpression {
		return false
	}
	binary := node.AsBinaryExpression()
	switch binary.OperatorToken.Kind {
	case ast.KindAmpersandAmpersandToken, ast.KindBarBarToken:
		return p.check(binary.Left) && p.check(binary.Right)
	case ast.KindInstanceOfKeyword:
		if !p.reference(ast.SkipParentheses(binary.Left)) || binary.Right.Kind != ast.KindIdentifier {
			return false
		}
		symbol := p.l.checker.GetSymbolAtLocation(binary.Right)
		if symbol != nil && symbol.Flags&ast.SymbolFlagsAlias != 0 {
			symbol = p.l.checker.GetAliasedSymbol(symbol)
		}
		return symbol != nil && symbol.Flags&ast.SymbolFlagsClass != 0
	case ast.KindEqualsEqualsEqualsToken, ast.KindExclamationEqualsEqualsToken:
		return p.checkedValue(binary.Left) && p.literal(binary.Right) || p.checkedValue(binary.Right) && p.literal(binary.Left)
	}
	return false
}

func (p *predicateFlowProof) reference(node *ast.Node) bool {
	return node.Kind == ast.KindIdentifier && p.l.checker.GetSymbolAtLocation(node) == p.l.checker.GetSymbolAtLocation(p.parameter.Name())
}

func (p *predicateFlowProof) checkedValue(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if p.reference(node) {
		return true
	}
	if node.Kind == ast.KindTypeOfExpression {
		return p.reference(ast.SkipParentheses(node.AsTypeOfExpression().Expression))
	}
	return node.Kind == ast.KindPropertyAccessExpression && p.reference(ast.SkipParentheses(node.AsPropertyAccessExpression().Expression)) && node.Flags&ast.NodeFlagsOptionalChain == 0
}

func (p *predicateFlowProof) literal(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	switch node.Kind {
	case ast.KindStringLiteral, ast.KindNumericLiteral, ast.KindNullKeyword, ast.KindTrueKeyword, ast.KindFalseKeyword:
		return true
	case ast.KindIdentifier:
		return node.Text() == "undefined" && p.l.checker.GetSymbolAtLocation(node) == p.l.checker.GetUndefinedSymbol()
	}
	return false
}

func predicateEffects(node *ast.Node) bool {
	switch node.Kind {
	case ast.KindPropertyAccessExpression, ast.KindElementAccessExpression:
		// A property read may dispatch a getter through a structural view.
		return true
	case ast.KindCallExpression, ast.KindNewExpression, ast.KindBinaryExpression:
		if node.Kind != ast.KindBinaryExpression || ast.IsAssignmentOperator(node.AsBinaryExpression().OperatorToken.Kind) {
			return true
		}
	case ast.KindPostfixUnaryExpression, ast.KindFunctionDeclaration, ast.KindFunctionExpression, ast.KindArrowFunction:
		return true
	case ast.KindPrefixUnaryExpression:
		operator := node.AsPrefixUnaryExpression().Operator
		if operator == ast.KindPlusPlusToken || operator == ast.KindMinusMinusToken {
			return true
		}
	}
	return node.ForEachChild(predicateEffects)
}

func predicateTrueType(c *checker.Checker) *checker.Type {
	for _, member := range c.GetBooleanType().Types() {
		if member.AsLiteralType().Value() == true {
			return member
		}
	}
	panic("checker boolean type has no true member")
}

// The flow verifier keeps main's literal and nominal proofs. Body summaries add
// verified helpers and truthiness assertions; tag-only facts use checked views.
func (l *lowering) predicateRefusal(node *ast.Node) error {
	if node.Parent.Kind == ast.KindFunctionDeclaration && node.Parent.Body() == nil && l.censusImplementation(node.Parent) != nil {
		// TODO: .a refusal mode must prove the overload through its implementation
		// here and refuse an over-promising declaration. .ts keeps call-site checks.
		return nil
	}
	if l.predicateParameter(node) != nil {
		return nil
	}
	original := l.proveFlowPredicate(node)
	if original == nil {
		return nil
	}
	proof, err := l.provePredicate(node)
	if err != nil {
		return original
	}
	if proof.TaggedView {
		target := l.checker.GetTypeAtLocation(node.AsTypePredicateNode().Type)
		members := []*checker.Type{target}
		if target.Flags()&checker.TypeFlagsUnion != 0 {
			members = target.Types()
		}
		for _, member := range members {
			for _, property := range l.checker.GetPropertiesOfType(member) {
				if property.Flags&ast.SymbolFlagsOptional != 0 {
					return original
				}
			}
			if _, err := l.view(node, nil, member); err != nil {
				return err
			}
		}
	}
	return nil
}

// A signature on a plain function parameter is an argument contract. The call
// visitor proves the actual function body before admitting any invocation. Live
// contracts also need a closed set of direct callers; an uncalled declaration or
// an escaped function value supplies no producer proof for its callback.
func (l *lowering) predicateParameter(node *ast.Node) *ast.Node {
	signature := node.Parent
	if signature == nil || signature.Kind != ast.KindFunctionType || signature.Parent == nil || signature.Parent.Kind != ast.KindParameter {
		return nil
	}
	parameter := signature.Parent
	if parameter.AsParameterDeclaration().Initializer != nil || parameter.AsParameterDeclaration().DotDotDotToken != nil {
		return nil
	}
	function := parameter.Parent
	if function.Kind == ast.KindFunctionDeclaration && function.Body() == nil {
		implementation := l.censusImplementation(function)
		if implementation == nil {
			return nil
		}
		for index, candidate := range function.Parameters() {
			if candidate == parameter && index < len(implementation.Parameters()) {
				parameter = implementation.Parameters()[index]
				function = implementation
				break
			}
		}
	}
	if !ast.IsFunctionLike(function) || function.Body() == nil {
		return nil
	}
	symbol := l.checker.GetSymbolAtLocation(parameter.Name())
	changed := false
	var visit ast.Visitor
	visit = func(n *ast.Node) bool {
		if n.Kind == ast.KindIdentifier && l.checker.GetSymbolAtLocation(n) == symbol && ast.IsAssignmentTarget(n) {
			changed = true
		}
		n.ForEachChild(visit)
		return false
	}
	function.Body().ForEachChild(visit)
	if changed {
		return nil
	}
	// A bodyless overload's callback predicate is not the implementation's
	// contract when the implementation takes an ordinary boolean callback.
	if signature.Parent != parameter && parameter.Type() != nil && parameter.Type().Kind == ast.KindFunctionType && parameter.Type().Type() != nil && parameter.Type().Type().Kind != ast.KindTypePredicate {
		return parameter
	}
	if !l.predicateCallbackCallers(function, symbol) {
		return nil
	}
	return parameter
}

// Every producer is checked by predicateArguments before annotations are admitted.
// Keep that proof within direct calls, and do not let a callback escape its body.
func (l *lowering) predicateCallbackCallers(function *ast.Node, callback *ast.Symbol) bool {
	if function.Kind != ast.KindFunctionDeclaration || !ast.IsIdentifier(function.Name()) || ast.HasSyntacticModifier(function, ast.ModifierFlagsExport) {
		return false
	}
	owner := l.symbol(function.Name())
	if owner == nil {
		return false
	}
	found, safe := false, true
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if ast.IsIdentifier(node) && !ast.IsPartOfTypeNode(node) && !ast.IsDeclarationName(node) {
			symbol := l.symbol(node)
			if symbol == owner || symbol == callback {
				callee := node
				for callee.Parent != nil && callee.Parent.Kind == ast.KindParenthesizedExpression {
					callee = callee.Parent
				}
				call := callee.Parent
				safe = safe && call != nil && call.Kind == ast.KindCallExpression && call.AsCallExpression().Expression == callee
				if symbol == owner {
					found = true
				}
			}
		}
		node.ForEachChild(visit)
		return false
	}
	for _, file := range l.program.Files() {
		file.AsNode().ForEachChild(visit)
	}
	return found && safe
}

func (l *lowering) predicateArguments(node *ast.Node) error {
	signature := l.checker.GetResolvedSignature(node)
	if signature == nil {
		return nil
	}
	if overload := signature.Declaration(); overload != nil && overload.Kind == ast.KindFunctionDeclaration && overload.Body() == nil && overload.Type() != nil && overload.Type().Kind == ast.KindTypePredicate {
		callee := ast.SkipParentheses(node.AsCallExpression().Expression)
		if callee.Kind != ast.KindIdentifier || l.symbol(callee) != l.symbol(overload.Name()) {
			return l.notYet(node, "an indirect call of a checked predicate overload")
		}
	}
	for index, parameter := range signature.Parameters() {
		if index >= len(node.AsCallExpression().Arguments.Nodes) {
			continue
		}
		var contract *ast.Node
		for _, declaration := range parameter.Declarations {
			if declaration.Kind == ast.KindParameter && declaration.Type() != nil && declaration.Type().Kind == ast.KindFunctionType && declaration.Type().Type() != nil && declaration.Type().Type().Kind == ast.KindTypePredicate {
				contract = declaration.Type().Type()
			}
		}
		if contract == nil {
			continue
		}
		argument := ast.SkipParentheses(node.AsCallExpression().Arguments.Nodes[index])
		implementation := argument
		if argument.Kind == ast.KindIdentifier {
			symbol := l.symbol(argument)
			if symbol != nil {
				for _, declaration := range symbol.Declarations {
					if ast.IsFunctionLike(declaration) && declaration.Body() != nil {
						implementation = declaration
					}
					if declaration.Kind == ast.KindVariableDeclaration && declaration.AsVariableDeclaration().Initializer != nil {
						implementation = ast.SkipParentheses(declaration.AsVariableDeclaration().Initializer)
					}
				}
			}
		}
		failure := func() error {
			file := ast.GetSourceFileOfNode(argument)
			text := file.Text()[scanner.GetTokenPosOfNode(argument, file, false):argument.End()]
			return &Refused{Where: l.program.Where(argument), What: "an unproven predicate argument for parameter " + parameter.Name + " (argument " + fmt.Sprintf("%q", text) + ")", Fix: "pass a named function or arrow whose body proves both predicate branches; return a boolean and narrow at the caller (adamic/no-type-predicate)"}
		}
		if !ast.IsFunctionLike(implementation) || implementation.Body() == nil || (implementation.Type() != nil && implementation.Type().Kind != ast.KindTypePredicate) {
			return failure()
		}
		if argument.Kind == ast.KindIdentifier {
			symbol := l.symbol(argument)
			changed := false
			var writes ast.Visitor
			writes = func(n *ast.Node) bool {
				if n.Kind == ast.KindIdentifier && l.symbol(n) == symbol && ast.IsAssignmentTarget(n) {
					changed = true
				}
				n.ForEachChild(writes)
				return false
			}
			for _, file := range l.program.Files() {
				file.AsNode().ForEachChild(writes)
			}
			if changed {
				return failure()
			}
		}
		wanted := contract.AsTypePredicateNode()
		calls := l.checker.GetSignaturesOfType(l.checker.GetTypeOfSymbol(parameter), checker.SignatureKindCall)
		var target *checker.Type
		if len(calls) == 1 {
			if predicate := predicateOfSignature(l.checker, calls[0]); predicate != nil {
				target = predicate.Type()
			}
		}
		if wanted.Type == nil || target == nil {
			return failure()
		}
		if implementation.Type() == nil {
			if !l.proveInferredPredicate(implementation, target) {
				return failure()
			}
		} else {
			annotation := implementation.Type().AsTypePredicateNode()
			if annotation.Type == nil || !checker.Checker_isTypeIdenticalTo(l.checker, l.checker.GetTypeAtLocation(annotation.Type), target) {
				return failure()
			}
			if err := l.predicateRefusal(implementation.Type()); err != nil {
				return failure()
			}
		}
	}
	return nil
}

// The pinned checker resolves a predicate's target under overload type arguments.
// This recovers the claim to validate; it never supplies a body-proof fact.
//
//go:linkname predicateOfSignature github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).getTypePredicateOfSignature
func predicateOfSignature(receiver *checker.Checker, signature *checker.Signature) *checker.TypePredicate

// Keep reference identity aligned with the pinned checker's flow analysis,
// including dotted/indexed spellings and stable computed indices.
//
//go:linkname predicateMatchingReference github.com/microsoft/TypeScript/tsc/internal/checker.(*Checker).isMatchingReference
func predicateMatchingReference(receiver *checker.Checker, source, target *ast.Node) bool

predicates_proof.go:
package lower

import (
	"fmt"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// A tag proof certifies membership in the tag set only. Admission must preserve
// a checked view for the target's remaining fields; this is not a shape proof.
type predicateProof struct{ TaggedView bool }

type predicateTruth uint8

const (
	predicateTrue   predicateTruth = 1
	predicateFalse  predicateTruth = 2
	predicateEither predicateTruth = 3
)

type predicateVerifier struct {
	l          *lowering
	field      string
	truthiness bool
	cells      []string
	summaries  map[*ast.Node][]predicateTruth
}

type predicatePath struct {
	cell   int
	locals map[*ast.Symbol]predicateTruth
}

func predicateFailure(l *lowering, node *ast.Node, path string) error {
	where := ""
	if node != nil {
		where = l.program.Where(node)
	}
	return &Refused{Where: where, What: "an unproven type predicate", Fix: path + "; return a boolean and narrow at the caller (adamic/no-type-predicate)"}
}

// provePredicate starts with no helper facts. Only independently verified bodies
// become summaries. Iteration terminates when no new body can be discharged;
// cycles and opaque calls never acquire a summary from their annotations.
func (l *lowering) provePredicate(node *ast.Node) (predicateProof, error) {
	proof := predicateProof{}
	if node == nil || node.Kind != ast.KindTypePredicate || node.Parent == nil || !ast.IsFunctionLike(node.Parent) || node.Parent.Body() == nil {
		return proof, predicateFailure(l, node, "no implementation body proves a return path")
	}
	v := &predicateVerifier{l: l, summaries: map[*ast.Node][]predicateTruth{}}
	if node.AsTypePredicateNode().Type == nil {
		if node.AsTypePredicateNode().AssertsModifier != nil {
			return l.proveConditionAssertion(node)
		}
		return proof, predicateFailure(l, node, "an assertion without a target type is not proved")
	}
	target := l.checker.GetTypeAtLocation(node.AsTypePredicateNode().Type)
	if target.Flags()&(checker.TypeFlagsObject|checker.TypeFlagsUnion) != 0 && v.kindTarget(target) {
		v.field = "kind"
		proof.TaggedView = true
	} else if !predicatePrimitiveTarget(target) {
		return proof, predicateFailure(l, node, "the target has an unsupported runtime contract")
	}
	if v.field == "" {
		v.cells = []string{"string", "number", "boolean", "undefined", "object", "function", "symbol", "bigint"}
	} else {
		v.cells = []string{"<other kind>"}
	}
	var declarations []*ast.Node
	var visit ast.Visitor
	visit = func(n *ast.Node) bool {
		if ast.IsFunctionLike(n) && n.Type() != nil && n.Type().Kind == ast.KindTypePredicate && n.Body() != nil {
			declarations = append(declarations, n)
			if v.field != "" {
				v.collectKinds(n)
			}
		}
		n.ForEachChild(visit)
		return false
	}
	for _, file := range l.program.Files() {
		file.AsNode().ForEachChild(visit)
	}
	var last error
	for {
		changed := false
		for _, declaration := range declarations {
			if _, ok := v.summaries[declaration]; ok {
				continue
			}
			summary, err := v.verify(declaration)
			if declaration == node.Parent {
				last = err
			}
			if err == nil {
				v.summaries[declaration] = summary
				changed = true
			}
		}
		if _, ok := v.summaries[node.Parent]; ok {
			return proof, nil
		}
		if !changed {
			break
		}
	}
	if last == nil {
		last = predicateFailure(l, node, "unconverged helper proof")
	}
	return predicateProof{}, last
}

func predicatePrimitiveTarget(t *checker.Type) bool {
	if t.Flags()&checker.TypeFlagsUnion != 0 {
		for _, m := range t.Types() {
			if !predicatePrimitiveTarget(m) {
				return false
			}
		}
		return true
	}
	// Literal refinements need value partitions, not just typeof partitions.
	return t.Flags()&(checker.TypeFlagsString|checker.TypeFlagsNumber|checker.TypeFlagsBoolean|checker.TypeFlagsUndefined) != 0 && t.Flags()&(checker.TypeFlagsLiteral|checker.TypeFlagsAny|checker.TypeFlagsUnknown|checker.TypeFlagsTypeParameter) == 0
}

func (v *predicateVerifier) kindTarget(t *checker.Type) bool {
	if t.Flags()&checker.TypeFlagsUnion != 0 {
		for _, m := range t.Types() {
			if !v.kindTarget(m) {
				return false
			}
		}
		return true
	}
	return t.Flags()&checker.TypeFlagsObject != 0 && !isClassInstance(t) && v.l.fieldLiteral(t, "kind") != nil
}

func predicateLiteral(t *checker.Type) (string, bool) {
	if t.Flags()&(checker.TypeFlagsStringLiteral|checker.TypeFlagsNumberLiteral|checker.TypeFlagsBooleanLiteral) == 0 {
		return "", false
	}
	return fmt.Sprintf("%T:%v", t.AsLiteralType().Value(), t.AsLiteralType().Value()), true
}

func (v *predicateVerifier) addKind(t *checker.Type) {
	key, ok := predicateLiteral(t)
	if !ok {
		return
	}
	for _, cell := range v.cells {
		if cell == key {
			return
		}
	}
	v.cells = append(v.cells, key)
}

func (v *predicateVerifier) collectKinds(declaration *ast.Node) {
	var addTarget func(*checker.Type)
	addTarget = func(t *checker.Type) {
		if t.Flags()&checker.TypeFlagsUnion != 0 {
			for _, m := range t.Types() {
				addTarget(m)
			}
			return
		}
		if literal := v.l.fieldLiteral(t, "kind"); literal != nil {
			v.addKind(literal)
		}
	}
	predicate := declaration.Type().AsTypePredicateNode()
	if predicate.Type != nil {
		addTarget(v.l.checker.GetTypeAtLocation(predicate.Type))
	}
	var visit ast.Visitor
	visit = func(n *ast.Node) bool {
		if n.Kind == ast.KindBinaryExpression {
			b := n.AsBinaryExpression()
			if b.OperatorToken.Kind == ast.KindEqualsEqualsEqualsToken || b.OperatorToken.Kind == ast.KindExclamationEqualsEqualsToken {
				v.addKind(v.l.checker.GetTypeAtLocation(b.Left))
				v.addKind(v.l.checker.GetTypeAtLocation(b.Right))
			}
		}
		n.ForEachChild(visit)
		return false
	}
	declaration.Body().ForEachChild(visit)
}

func (v *predicateVerifier) wanted(t *checker.Type, cell string) (bool, bool) {
	if t.Flags()&checker.TypeFlagsUnion != 0 {
		answer := false
		for _, m := range t.Types() {
			yes, ok := v.wanted(m, cell)
			if !ok {
				return false, false
			}
			answer = answer || yes
		}
		return answer, true
	}
	if v.field != "" {
		if !v.kindTarget(t) {
			return false, false
		}
		key, ok := predicateLiteral(v.l.fieldLiteral(t, v.field))
		return key == cell, ok
	}
	if !predicatePrimitiveTarget(t) {
		return false, false
	}
	kinds := map[string]checker.TypeFlags{"string": checker.TypeFlagsString, "number": checker.TypeFlagsNumber, "boolean": checker.TypeFlagsBoolean, "undefined": checker.TypeFlagsUndefined}
	return t.Flags()&kinds[cell] != 0, true
}

func (v *predicateVerifier) parameter(declaration *ast.Node) *ast.Symbol {
	predicate := declaration.Type().AsTypePredicateNode()
	for _, p := range declaration.Parameters() {
		if ast.IsIdentifier(p.Name()) && p.Name().Text() == predicate.ParameterName.Text() {
			return v.l.checker.GetSymbolAtLocation(p.Name())
		}
	}
	return nil
}

func (v *predicateVerifier) verify(declaration *ast.Node) ([]predicateTruth, error) {
	parameter := v.parameter(declaration)
	if parameter == nil || len(declaration.TypeParameters()) != 0 {
		return nil, predicateFailure(v.l, declaration, "a generic or non-parameter target has no body proof")
	}
	for _, parameter := range declaration.Parameters() {
		declared := parameter.AsParameterDeclaration()
		if declared.Initializer != nil || declared.DotDotDotToken != nil || !ast.IsIdentifier(parameter.Name()) {
			return nil, predicateFailure(v.l, parameter, "parameter initialization may mutate the tested input before this return path")
		}
	}
	predicate := declaration.Type().AsTypePredicateNode()
	if predicate.Type == nil {
		return nil, predicateFailure(v.l, declaration, "an assertion without a target type is not proved")
	}
	target := v.l.checker.GetTypeAtLocation(predicate.Type)
	summary := make([]predicateTruth, len(v.cells))
	for i, cell := range v.cells {
		wanted, ok := v.wanted(target, cell)
		if !ok {
			return nil, predicateFailure(v.l, declaration, "the target has an unsupported runtime contract")
		}
		path := predicatePath{cell: i, locals: map[*ast.Symbol]predicateTruth{}}
		check := func(n *ast.Node, result predicateTruth) error {
			if predicate.AssertsModifier != nil {
				if !wanted {
					return predicateFailure(v.l, n, "normal return does not establish the asserted target")
				}
			} else {
				if result&predicateTrue != 0 && !wanted {
					return predicateFailure(v.l, n, "true return does not establish the target")
				}
				if result&predicateFalse != 0 && wanted {
					return predicateFailure(v.l, n, "false return does not exclude the target")
				}
			}
			summary[i] |= result
			return nil
		}
		body := declaration.Body()
		if body.Kind != ast.KindBlock {
			result, err := v.expression(body, parameter, path)
			if err != nil {
				return nil, err
			}
			if err = check(body, result); err != nil {
				return nil, err
			}
			continue
		}
		paths, err := v.statements(body.AsBlock().Statements.Nodes, parameter, []predicatePath{path}, check)
		if err != nil {
			return nil, err
		}
		if len(paths) > 0 {
			if predicate.AssertsModifier == nil {
				return nil, predicateFailure(v.l, body, "normal return has no boolean result")
			}
			if err = check(body, predicateTrue); err != nil {
				return nil, err
			}
		}
	}
	return summary, nil
}

func predicateNot(t predicateTruth) predicateTruth {
	return (t&predicateTrue)<<1 | (t&predicateFalse)>>1
}
func predicateCombine(a, b predicateTruth, and bool) predicateTruth {
	var result predicateTruth
	for _, x := range []predicateTruth{predicateTrue, predicateFalse} {
		for _, y := range []predicateTruth{predicateTrue, predicateFalse} {
			if a&x == 0 || b&y == 0 {
				continue
			}
			yes := x == predicateTrue || y == predicateTrue
			if and {
				yes = x == predicateTrue && y == predicateTrue
			}
			if yes {
				result |= predicateTrue
			} else {
				result |= predicateFalse
			}
		}
	}
	return result
}

func (v *predicateVerifier) expression(n *ast.Node, parameter *ast.Symbol, path predicatePath) (predicateTruth, error) {
	n = ast.SkipParentheses(n)
	switch n.Kind {
	case ast.KindTrueKeyword:
		return predicateTrue, nil
	case ast.KindFalseKeyword:
		return predicateFalse, nil
	case ast.KindIdentifier:
		if v.truthiness && v.sameParameter(n, parameter) {
			if v.cells[path.cell] == "truthy" {
				return predicateTrue, nil
			}
			return predicateFalse, nil
		}
		if value, ok := path.locals[v.l.checker.GetSymbolAtLocation(n)]; ok {
			return value, nil
		}
		return predicateEither, nil
	case ast.KindPrefixUnaryExpression:
		u := n.AsPrefixUnaryExpression()
		if u.Operator == ast.KindExclamationToken {
			t, err := v.expression(u.Operand, parameter, path)
			return predicateNot(t), err
		}
	case ast.KindBinaryExpression:
		b := n.AsBinaryExpression()
		if ast.IsAssignmentOperator(b.OperatorToken.Kind) {
			return 0, predicateFailure(v.l, n, "mutation invalidates the facts before this return path")
		}
		if b.OperatorToken.Kind == ast.KindAmpersandAmpersandToken || b.OperatorToken.Kind == ast.KindBarBarToken {
			a, err := v.expression(b.Left, parameter, path)
			if err != nil {
				return 0, err
			}
			z, err := v.expression(b.Right, parameter, path)
			if err != nil {
				return 0, err
			}
			return predicateCombine(a, z, b.OperatorToken.Kind == ast.KindAmpersandAmpersandToken), nil
		}
		if b.OperatorToken.Kind == ast.KindEqualsEqualsEqualsToken || b.OperatorToken.Kind == ast.KindExclamationEqualsEqualsToken {
			for _, pair := range [][2]*ast.Node{{b.Left, b.Right}, {b.Right, b.Left}} {
				test := ast.SkipParentheses(pair[0])
				constant := pair[1]
				matched := false
				yes := false
				if v.field == "" && test.Kind == ast.KindTypeOfExpression && v.sameParameter(test.AsTypeOfExpression().Expression, parameter) && constant.Kind == ast.KindStringLiteral {
					matched = true
					yes = v.cells[path.cell] == constant.Text()
				}
				if v.field != "" && test.Kind == ast.KindPropertyAccessExpression && test.Name().Text() == v.field && v.sameParameter(test.AsPropertyAccessExpression().Expression, parameter) {
					key, ok := predicateLiteral(v.l.checker.GetTypeAtLocation(constant))
					if ok && v.constant(constant) {
						matched = true
						yes = v.cells[path.cell] == key
					}
				}
				if matched {
					if b.OperatorToken.Kind == ast.KindExclamationEqualsEqualsToken {
						yes = !yes
					}
					if yes {
						return predicateTrue, nil
					}
					return predicateFalse, nil
				}
			}
		}
		// Pure comparisons outside the known partition provide no narrowing fact.
		if b.OperatorToken.Kind == ast.KindGreaterThanToken || b.OperatorToken.Kind == ast.KindLessThanToken {
			if v.pure(b.Left) && v.pure(b.Right) {
				return predicateEither, nil
			}
		}
	case ast.KindCallExpression:
		call := n.AsCallExpression()
		if len(call.Arguments.Nodes) != 1 || !v.sameParameter(call.Arguments.Nodes[0], parameter) || !ast.IsIdentifier(call.Expression) {
			break
		}
		symbol := v.l.symbol(call.Expression)
		if symbol != nil {
			for _, d := range symbol.Declarations {
				if values, ok := v.summaries[d]; ok {
					// This summary partitions the helper's predicate parameter,
					// not an arbitrary argument with the same caller symbol.
					claim := predicateOfSignature(v.l.checker, v.l.checker.GetSignatureFromDeclaration(d))
					if claim == nil || claim.ParameterIndex() != 0 {
						return 0, predicateFailure(v.l, n, "helper argument 0 does not occupy its predicate parameter; pass the tested value at the helper's predicate parameter index")
					}
					return values[path.cell], nil
				}
			}
		}
		return 0, predicateFailure(v.l, n, "unconverged or opaque helper on this return path")
	}
	return 0, predicateFailure(v.l, n, "opaque test or possible mutation on this return path")
}

func (v *predicateVerifier) sameParameter(n *ast.Node, parameter *ast.Symbol) bool {
	n = ast.SkipParentheses(n)
	return ast.IsIdentifier(n) && v.l.checker.GetSymbolAtLocation(n) == parameter
}

func (v *predicateVerifier) constant(n *ast.Node) bool {
	n = ast.SkipParentheses(n)
	switch n.Kind {
	case ast.KindStringLiteral, ast.KindNumericLiteral, ast.KindTrueKeyword, ast.KindFalseKeyword:
		return true
	case ast.KindPropertyAccessExpression:
		symbol := v.l.checker.GetSymbolAtLocation(n)
		return symbol != nil && (symbol.Flags&ast.SymbolFlagsEnumMember != 0 || v.l.checker.IsReadonlySymbol(symbol))
	}
	return false
}

func (v *predicateVerifier) pure(n *ast.Node) bool {
	n = ast.SkipParentheses(n)
	return n.Kind == ast.KindIdentifier || n.Kind == ast.KindNumericLiteral || n.Kind == ast.KindStringLiteral
}

func copyPredicatePath(path predicatePath) predicatePath {
	copy := predicatePath{cell: path.cell, locals: map[*ast.Symbol]predicateTruth{}}
	for symbol, value := range path.locals {
		copy.locals[symbol] = value
	}
	return copy
}

func (v *predicateVerifier) statements(nodes []*ast.Node, parameter *ast.Symbol, paths []predicatePath, check func(*ast.Node, predicateTruth) error) ([]predicatePath, error) {
	for _, n := range nodes {
		var next []predicatePath
		for _, path := range paths {
			switch n.Kind {
			case ast.KindBlock:
				result, err := v.statements(n.AsBlock().Statements.Nodes, parameter, []predicatePath{path}, check)
				if err != nil {
					return nil, err
				}
				next = append(next, result...)
			case ast.KindReturnStatement:
				result := predicateTrue
				if expression := n.AsReturnStatement().Expression; expression != nil {
					value, err := v.expression(expression, parameter, path)
					if err != nil {
						return nil, err
					}
					result = value
				}
				if err := check(n, result); err != nil {
					return nil, err
				}
			case ast.KindIfStatement:
				branch := n.AsIfStatement()
				condition, err := v.expression(branch.Expression, parameter, path)
				if err != nil {
					return nil, err
				}
				for _, side := range []struct {
					truth predicateTruth
					body  *ast.Node
				}{{predicateTrue, branch.ThenStatement}, {predicateFalse, branch.ElseStatement}} {
					if condition&side.truth == 0 {
						continue
					}
					p := copyPredicatePath(path)
					if side.body != nil && v.neverStatement(side.body, map[*ast.Node]bool{}) {
						continue
					}
					if side.body == nil {
						next = append(next, p)
						continue
					}
					result, err := v.statements([]*ast.Node{side.body}, parameter, []predicatePath{p}, check)
					if err != nil {
						return nil, err
					}
					next = append(next, result...)
				}
			case ast.KindVariableStatement:
				for _, d := range n.AsVariableStatement().DeclarationList.AsVariableDeclarationList().Declarations.Nodes {
					variable := d.AsVariableDeclaration()
					if !ast.IsIdentifier(d.Name()) || variable.Initializer == nil {
						return nil, predicateFailure(v.l, n, "an unproven alias on this return path")
					}
					value, err := v.expression(variable.Initializer, parameter, path)
					if err != nil {
						return nil, err
					}
					path.locals[v.l.checker.GetSymbolAtLocation(d.Name())] = value
				}
				next = append(next, path)
			case ast.KindExpressionStatement:
				expression := n.AsExpressionStatement().Expression
				if v.neverCall(expression, map[*ast.Node]bool{}) {
					continue
				}
				if v.l.isPanicCall(expression) {
					call := expression.AsCallExpression()
					for _, argument := range call.Arguments.Nodes {
						if !v.pure(argument) {
							return nil, predicateFailure(v.l, argument, "opaque panic argument may mutate this path")
						}
					}
					continue
				}
				if v.truthiness && expression.Kind == ast.KindCallExpression {
					return nil, predicateFailure(v.l, n, "a failure helper can return normally on this normal return path")
				}
				_, err := v.expression(expression, parameter, path)
				if err != nil {
					return nil, err
				}
				next = append(next, path)
			default:
				return nil, predicateFailure(v.l, n, "unsupported control flow or mutation on this return path")
			}
		}
		paths = next
	}
	return paths, nil
}

// An assertion on a condition has a truthiness postcondition, not a structural
// target. Partition all possible inputs into truthy and falsy values, rather
// than treating unknown as a boolean or trusting the asserts annotation.
func (l *lowering) proveConditionAssertion(node *ast.Node) (predicateProof, error) {
	declaration := node.Parent
	verifier := &predicateVerifier{l: l, truthiness: true, cells: []string{"truthy", "falsy"}}
	parameter := verifier.parameter(declaration)
	if parameter == nil || len(declaration.TypeParameters()) != 0 {
		return predicateProof{}, predicateFailure(l, node, "a non-parameter assertion has no truthiness proof")
	}
	for _, argument := range declaration.Parameters() {
		declared := argument.AsParameterDeclaration()
		if declared.Initializer != nil || declared.DotDotDotToken != nil || !ast.IsIdentifier(argument.Name()) {
			return predicateProof{}, predicateFailure(l, argument, "parameter initialization may change the asserted input")
		}
	}
	if declaration.Body().Kind != ast.KindBlock {
		return predicateProof{}, predicateFailure(l, node, "an assertion needs a proved normal return path")
	}
	for cell := range verifier.cells {
		check := func(returned *ast.Node, _ predicateTruth) error {
			if verifier.cells[cell] != "truthy" {
				return predicateFailure(l, returned, "normal return does not establish the asserted condition's truthiness")
			}
			return nil
		}
		paths, err := verifier.statements(declaration.Body().AsBlock().Statements.Nodes, parameter, []predicatePath{{cell: cell, locals: map[*ast.Symbol]predicateTruth{}}}, check)
		if err != nil {
			return predicateProof{}, err
		}
		if len(paths) != 0 {
			if err := check(declaration.Body(), predicateTrue); err != nil {
				return predicateProof{}, err
			}
		}
	}
	return predicateProof{}, nil
}

// A never annotation alone is not evidence. Inspect a direct implementation's
// exits; recursive or bodyless failure helpers have no termination summary.
func (v *predicateVerifier) neverCall(node *ast.Node, visiting map[*ast.Node]bool) bool {
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindCallExpression {
		return false
	}
	if v.l.isPanicCall(node) {
		return true
	}
	call := node.AsCallExpression()
	callee := ast.SkipParentheses(call.Expression)
	if !ast.IsIdentifier(callee) && callee.Kind != ast.KindPropertyAccessExpression {
		return false
	}
	symbol := v.l.symbol(callee)
	if symbol == nil {
		return false
	}
	for _, declaration := range symbol.Declarations {
		if !ast.IsFunctionLike(declaration) || declaration.Body() == nil || visiting[declaration] {
			continue
		}
		signature := v.l.checker.GetSignatureFromDeclaration(declaration)
		if signature == nil || v.l.checker.GetReturnTypeOfSignature(signature).Flags()&checker.TypeFlagsNever == 0 {
			continue
		}
		visiting[declaration] = true
		proved := v.neverStatement(declaration.Body(), visiting)
		delete(visiting, declaration)
		if proved {
			return true
		}
	}
	return false
}

func (v *predicateVerifier) neverStatement(node *ast.Node, visiting map[*ast.Node]bool) bool {
	switch node.Kind {
	case ast.KindThrowStatement:
		return true
	case ast.KindExpressionStatement:
		return v.neverCall(node.AsExpressionStatement().Expression, visiting)
	case ast.KindReturnStatement:
		expression := node.AsReturnStatement().Expression
		return expression != nil && v.neverCall(expression, visiting)
	case ast.KindIfStatement:
		branch := node.AsIfStatement()
		return branch.ElseStatement != nil && v.neverStatement(branch.ThenStatement, visiting) && v.neverStatement(branch.ElseStatement, visiting)
	case ast.KindBlock:
		for _, statement := range node.AsBlock().Statements.Nodes {
			if v.neverStatement(statement, visiting) {
				return true
			}
			if predicateNormalExit(statement) {
				return false
			}
		}
	}
	return false
}

// Untreated control flow may escape a block or override a pending throw.
// Ordinary statements before a terminal throw are harmless to non-return,
// even if they mutate state: they are never used as surviving narrowing facts.
func predicateNormalExit(node *ast.Node) bool {
	if ast.IsFunctionLike(node) {
		return false
	}
	switch node.Kind {
	case ast.KindReturnStatement, ast.KindBreakStatement, ast.KindContinueStatement, ast.KindTryStatement:
		return true
	}
	found := false
	node.ForEachChild(func(child *ast.Node) bool {
		if predicateNormalExit(child) {
			found = true
		}
		return found
	})
	return found
}

// Overloads share the implementation's control flow, under their admitted input.
// An annotation is never installed on the implementation as a checker fact.
func (l *lowering) predicateOverloadProven(implementation, overload *ast.Node) bool {
	outer := l.typeMapper
	defer func() { l.typeMapper = outer }()
	sources, targets := []*checker.Type{}, []*checker.Type{}
	for index, parameter := range implementation.TypeParameters() {
		if index >= len(overload.TypeParameters()) {
			return false
		}
		sources = append(sources, l.checker.GetTypeAtLocation(parameter.Name()))
		targets = append(targets, l.checker.GetTypeAtLocation(overload.TypeParameters()[index].Name()))
	}
	if len(sources) > 0 {
		l.typeMapper = newTypeMapper(sources, targets)
	}
	claim := predicateOfSignature(l.checker, l.checker.GetSignatureFromDeclaration(overload))
	if claim == nil || int(claim.ParameterIndex()) >= len(implementation.Parameters()) {
		return false
	}
	index := int(claim.ParameterIndex())
	if index < 0 {
		return false
	}
	parameter := implementation.Parameters()[index]
	if !ast.IsIdentifier(parameter.Name()) || parameter.AsParameterDeclaration().Initializer != nil || parameter.AsParameterDeclaration().DotDotDotToken != nil {
		return false
	}
	admitted, _, rest, err := l.censusOverloadParameter(overload.Parameters(), index)
	if err != nil || rest || admitted == nil {
		return false
	}
	changed := false
	var writes ast.Visitor
	writes = func(node *ast.Node) bool {
		if ast.IsIdentifier(node) && l.symbol(node) == l.symbol(parameter.Name()) && ast.IsAssignmentTarget(node) {
			changed = true
		}
		node.ForEachChild(writes)
		return false
	}
	implementation.Body().ForEachChild(writes)
	if changed {
		return false
	}
	target := claim.Type()
	if target == nil {
		if admitted.Flags()&checker.TypeFlagsBooleanLike == 0 {
			return false
		}
		target = predicateTrueType(l.checker)
	}
	proof := predicateFlowProof{l: l, function: implementation, parameter: parameter, declared: l.checker.GetTypeAtLocation(parameter.Name()), admitted: admitted, target: l.concrete(target), assertion: claim.Kind() == checker.TypePredicateKindAssertsIdentifier}
	return proof.proveBody(overload.Type()) == nil
}

// The existing overload-result seam supplies the call. A small IR wrapper keeps
// argument evaluation and the implementation call single, then checks both
// predicate directions against those arguments before the caller can narrow.
func (l *lowering) predicateOverloadResult(call *ast.CallExpression, value ir.Expression, implementation, overload *ast.Node) (ir.Expression, error) {
	// Until .a refusal mode exists, .a and .ts share the ruled call-site checks.
	directions := l.predicateUseDirections(call)
	proven := l.predicateOverloadProven(implementation, overload)
	l.recordPredicateChecks(call, implementation, overload, directions, proven)
	if proven {
		return value, nil
	}
	if directions == 0 {
		return value, nil
	}
	invoked, ok := value.(ir.Call)
	if !ok {
		return nil, l.notYet(call.AsNode(), "a checked predicate overload on an indirect call")
	}
	resolved := l.checker.GetResolvedSignature(call.AsNode())
	claim := predicateOfSignature(l.checker, resolved)
	if claim == nil {
		return nil, l.notYet(overload, "a predicate overload without a reifiable target")
	}
	assertion := claim.Kind() == checker.TypePredicateKindAssertsIdentifier
	if claim.Type() == nil && !assertion {
		return nil, l.notYet(overload, "a predicate overload without a reifiable target")
	}
	index := int(claim.ParameterIndex())
	if index < 0 || index >= len(invoked.Arguments) {
		return nil, l.notYet(overload, "a predicate overload on a missing argument")
	}
	if (!assertion && invoked.Type() != ir.Boolean) || (assertion && invoked.Type() != 0) {
		return nil, l.notYet(overload, "a checked predicate overload with a non-boolean result")
	}
	ordinal := l.predicateOverloadOrdinal(implementation, overload)
	message := fmt.Sprintf("overload %d of %s result: predicate %s is false", ordinal, implementation.Name().Text(), claim.ParameterName())
	wrapper := len(l.result.Functions)
	l.result.Functions = append(l.result.Functions, ir.Function{Name: fmt.Sprintf("%s_overload_%d_check_%d", implementation.Name().Text(), ordinal, wrapper), Returns: invoked.Type()})
	local := func(name string, of ir.Type) int {
		index := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: name, Type: of, Function: wrapper})
		return index
	}
	arguments := []ir.Expression{}
	for index, argument := range invoked.Arguments {
		// Direct emission contextualizes undefined at the callee parameter.
		// Preserve that representation when passing through wrapper locals.
		if undefined, ok := argument.(ir.Undefined); ok && index < len(l.result.Functions[l.result.CallTargets(invoked)[0]].Parameters) {
			parameter := l.result.Functions[l.result.CallTargets(invoked)[0]].Parameters[index]
			undefined.Of = l.result.Locals[parameter].Type
			argument = undefined
			invoked.Arguments[index] = argument
		}
		parameter := local(fmt.Sprintf("argument_%d", index), argument.Type())
		l.result.Functions[wrapper].Parameters = append(l.result.Functions[wrapper].Parameters, parameter)
		arguments = append(arguments, ir.Read{Local: parameter, Of: argument.Type()})
	}
	checked := invoked
	checked.Arguments = arguments

	result := -1
	body := []ir.Statement{}
	if assertion {
		body = append(body, ir.Evaluate{Value: checked})
	} else {
		result = local("result", ir.Boolean)
		body = append(body, ir.Declare{Local: result, Value: checked})
	}
	source := l.checker.GetTypeOfSymbol(resolved.Parameters()[index])
	if _, undefined := invoked.Arguments[index].(ir.Undefined); undefined {
		source = l.checker.GetTypeAtLocation(call.Arguments.Nodes[index])
	}
	var setup []ir.Statement
	var membership ir.Expression
	var err error
	if claim.Type() == nil {
		membership = censusCondition(arguments[index])
	} else {
		setup, membership, err = l.predicateMembership(overload, arguments[index], source, claim.Type(), local, 0)
	}
	if err != nil {
		return nil, err
	}
	invalid := ir.Expression(ir.Unary{Operator: ir.Not, Operand: membership})
	var returned ir.Expression
	if !assertion {
		returned = ir.Read{Local: result, Of: ir.Boolean}
		invalid = predicateDirectionMismatch(returned, membership, directions)
	}
	checks := append(setup, ir.If{Condition: invalid, Then: []ir.Statement{ir.Panic{Message: ir.StringConstant{Index: l.constant(message)}}}})
	if !assertion && directions != predicateEither {
		observed := returned
		if directions == predicateFalse {
			observed = ir.Unary{Operator: ir.Not, Operand: returned}
		}
		// An erased direction must not execute target field or element reads.
		body = append(body, ir.If{Condition: observed, Then: checks})
	} else {
		body = append(body, checks...)
	}
	body = append(body, ir.Return{Value: returned})
	l.result.Functions[wrapper].Body = body

	return ir.Call{Function: wrapper, Arguments: invoked.Arguments, Returns: invoked.Type()}, nil
}

// Reification is limited to independently checkable contracts. Tagged interfaces
// continue through the shared view checker; untagged/callable contracts are not
// silently equated with a primitive typeof test.
func (l *lowering) predicateMembership(node *ast.Node, value ir.Expression, source, target *checker.Type, local func(string, ir.Type) int, depth int) ([]ir.Statement, ir.Expression, error) {
	target = l.concrete(target)
	source = l.concrete(source)
	if depth > 8 {
		return nil, nil, l.notYet(node, "a recursive predicate overload target")
	}
	equal := func(a, b ir.Expression) ir.Expression { return ir.Binary{Operator: ir.Equal, Left: a, Right: b} }
	isType := func(name string) ir.Expression {
		return equal(ir.TypeOf{Value: value}, ir.StringConstant{Index: l.constant(name)})
	}
	if target.Flags()&checker.TypeFlagsUnion != 0 {
		var setup []ir.Statement
		var result ir.Expression = ir.BooleanConstant{Value: false}
		for _, member := range target.Types() {
			statements, test, err := l.predicateMembership(node, value, source, member, local, depth+1)
			if err != nil {
				return nil, nil, err
			}
			setup = append(setup, statements...)
			result = ir.Binary{Operator: ir.Or, Left: result, Right: test}
		}
		return setup, result, nil
	}
	if target.Flags()&checker.TypeFlagsUndefined != 0 {
		return nil, isType("undefined"), nil
	}
	name := ""
	of := ir.Type(0)
	switch {
	case target.Flags()&checker.TypeFlagsStringLike != 0:
		name = "string"
		of = ir.String
	case target.Flags()&checker.TypeFlagsNumberLike != 0:
		name = "number"
		of = ir.Number
	case target.Flags()&checker.TypeFlagsBooleanLike != 0:
		name = "boolean"
		of = ir.Boolean
	}
	if name != "" {
		test := isType(name)
		if literal, _, ok := l.literalConstant(target); ok {
			narrowed := value
			if value.Type() == ir.Union {
				narrowed = ir.Narrow{Value: value, To: of}
			} else if value.Type().IsMaybe() {
				narrowed = ir.Unwrap{Value: value}
			}
			if narrowed.Type() != of {
				return nil, nil, l.notYet(node, "a predicate overload literal representation")
			}
			test = ir.Binary{Operator: ir.And, Left: test, Right: equal(narrowed, literal)}
		}
		return nil, test, nil
	}
	if l.checker.IsArrayType(target) && (source.Flags()&checker.TypeFlagsUndefined != 0 || value.Type() == ir.Number || value.Type() == ir.String || value.Type() == ir.Boolean) {
		return nil, ir.BooleanConstant{Value: false}, nil
	}
	if l.checker.IsArrayType(target) && value.Type() == ir.Array {
		arraySource := source
		if source.Flags()&checker.TypeFlagsUnion != 0 {
			arraySource = nil
			for _, member := range source.Types() {
				if l.checker.IsArrayType(member) {
					if arraySource != nil {
						return nil, nil, l.notYet(node, "a predicate overload over multiple array representations")
					}
					arraySource = member
				}
			}
		}
		if arraySource == nil || !l.checker.IsArrayType(arraySource) {
			return nil, nil, l.notYet(node, "a predicate overload without a known array representation")
		}
		element := l.checker.GetElementTypeOfArrayType(arraySource)
		// An identical element contract is already admitted on the source array.
		// The overload strengthens only presence, not its element view.
		if checker.Checker_isTypeIdenticalTo(l.checker, l.concrete(element), l.concrete(l.checker.GetElementTypeOfArrayType(target))) {
			return nil, censusCondition(value), nil
		}
		held, known := l.kept(element)
		if !known || slotless(held) {
			return nil, nil, l.notYet(node, "a checked predicate overload array element "+l.checker.TypeToString(element))
		}
		matches := local("array_matches", ir.Boolean)
		counter := local("array_index", ir.Number)
		read := ir.Read{Local: counter, Of: ir.Number}
		statements, test, err := l.predicateMembership(node, ir.ArrayIndex{Array: value, Index: read, Element: held}, element, l.checker.GetElementTypeOfArrayType(target), local, depth+1)
		if err != nil {
			return nil, nil, err
		}
		loopBody := append(statements, ir.If{Condition: ir.Unary{Operator: ir.Not, Operand: test}, Then: []ir.Statement{ir.Assign{Local: matches, Value: ir.BooleanConstant{Value: false}}, ir.Break{}}})
		setup := []ir.Statement{ir.Declare{Local: matches, Value: ir.BooleanConstant{Value: false}}, ir.If{Condition: censusCondition(value), Then: []ir.Statement{ir.Assign{Local: matches, Value: ir.BooleanConstant{Value: true}}, ir.Declare{Local: counter, Value: ir.NumberConstant{Value: 0}}, ir.Loop{Condition: ir.Binary{Operator: ir.Less, Left: read, Right: ir.Length{Array: value}}, Body: loopBody, Update: []ir.Statement{ir.Assign{Local: counter, Value: ir.Binary{Operator: ir.Add, Left: read, Right: ir.NumberConstant{Value: 1}}}}}}}}
		return setup, ir.Read{Local: matches, Of: ir.Boolean}, nil
	}
	if isClassInstance(target) && target.Symbol() != nil {
		for _, declaration := range target.Symbol().Declarations {
			if declaration.Kind != ast.KindClassDeclaration || len(declaration.TypeParameters()) != 0 {
				continue
			}
			if value.Type() != ir.Object && value.Type() != ir.Union {
				return nil, ir.BooleanConstant{Value: false}, nil
			}
			instance, err := l.instantiate(declaration, target, node)
			if err != nil {
				return nil, nil, err
			}
			object := value
			if value.Type() == ir.Union {
				object = ir.Narrow{Value: value, To: ir.Object}
			}
			return nil, ir.Binary{Operator: ir.And, Left: isType("object"), Right: ir.InstanceOf{Value: object, Class: instance.class}}, nil
		}
	}
	if target.Flags()&checker.TypeFlagsObject != 0 && !isClassInstance(target) && value.Type() == ir.Object {
		tag := l.fieldLiteral(target, "kind")
		if tag != nil {
			if _, err := l.view(node, nil, target); err != nil {
				return nil, nil, err
			}
			literal, of, known := l.literalConstant(tag)
			if known {
				return nil, ir.Binary{Operator: ir.And, Left: censusCondition(value), Right: equal(ir.Property{Object: value, Name: "kind", Of: of, View: "predicate argument.kind", ViewType: l.checker.TypeToString(tag)}, literal)}, nil
			}
		}
	}
	return nil, nil, l.notYet(node, "checked predicate overload target "+l.checker.TypeToString(target))
}

// A direction is observable whenever the checker still narrows a value read in
// its flow region. This includes aliases of the boolean result and continuation
// flows after return/throw; lexical then/else scanning would miss those reads.
func (l *lowering) predicateUseDirections(call *ast.CallExpression) predicateTruth {
	claim := predicateOfSignature(l.checker, l.checker.GetResolvedSignature(call.AsNode()))
	if claim == nil || int(claim.ParameterIndex()) < 0 || int(claim.ParameterIndex()) >= len(call.Arguments.Nodes) {
		return predicateEither
	}
	argument := ast.SkipParentheses(call.Arguments.Nodes[claim.ParameterIndex()])
	references := []*ast.Node{argument}
	for container := argument; container.Flags&ast.NodeFlagsOptionalChain != 0; {
		switch container.Kind {
		case ast.KindPropertyAccessExpression:
			container = ast.SkipParentheses(container.AsPropertyAccessExpression().Expression)
		case ast.KindElementAccessExpression:
			container = ast.SkipParentheses(container.AsElementAccessExpression().Expression)
		default:
			container = nil
		}
		if container == nil {
			break
		}
		references = append(references, container)
	}
	var directions predicateTruth
	for _, argument := range references {
		directions |= l.predicateReferenceDirections(call, argument)
	}
	return directions
}

func (l *lowering) predicateReferenceDirections(call *ast.CallExpression, argument *ast.Node) predicateTruth {
	if argument.Kind != ast.KindIdentifier && argument.Kind != ast.KindPropertyAccessExpression && argument.Kind != ast.KindElementAccessExpression && argument.Kind != ast.KindThisKeyword {
		// Temporary values cannot be narrowed by a later reference read.
		return 0
	}
	declared := l.checker.GetTypeAtLocation(argument)
	if argument.Kind == ast.KindIdentifier {
		declared = l.checker.GetTypeOfSymbol(l.symbol(argument))
	}
	var directions predicateTruth
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if l.predicateSameReference(node, argument) && !ast.IsDeclarationName(node) && !predicateWriteOnly(node) && !ast.IsPartOfTypeNode(node) {
			actual := l.checker.GetTypeAtLocation(node)
			if !checker.Checker_isTypeIdenticalTo(l.checker, actual, declared) {
				if flow := node.FlowNodeData(); flow != nil {
					candidates := l.predicateFlowDirections(flow.FlowNode, call.AsNode(), argument, map[*ast.FlowNode]bool{})
					for _, direction := range []predicateTruth{predicateTrue, predicateFalse} {
						if candidates&direction == 0 {
							continue
						}
						without := l.predicateFlowWithout(flow.FlowNode, call.AsNode(), node, direction)
						unclaimed := predicateFlowType(l.checker, node, declared, declared, nil, without)
						if !checker.Checker_isTypeIdenticalTo(l.checker, actual, unclaimed) {
							directions |= direction
						}
					}
				}
			}
		}
		node.ForEachChild(visit)
		return false
	}
	for _, file := range l.program.Files() {
		file.AsNode().ForEachChild(visit)
	}
	return directions
}

func (l *lowering) predicateSameReference(a, b *ast.Node) bool {
	return a != nil && b != nil && predicateMatchingReference(l.checker, b, a)
}

// Follow the checker's existing graph rather than inventing branch regions.
func (l *lowering) predicateFlowDirections(flow *ast.FlowNode, call, reference *ast.Node, seen map[*ast.FlowNode]bool) predicateTruth {
	if flow == nil || seen[flow] {
		return 0
	}
	seen[flow] = true
	// A replacement kills earlier predicate facts for this reference. Compound
	// assignments also read the old narrowed value and must keep those checks.
	if flow.Flags&ast.FlowFlagsAssignment != 0 && l.predicateSameReference(flow.Node, reference) && predicateWriteOnly(flow.Node) {
		return 0
	}
	var result predicateTruth
	if flow.Flags&ast.FlowFlagsCondition != 0 {
		truth := flow.Flags&ast.FlowFlagsTrueCondition != 0
		result |= l.predicateConditionDirection(flow.Node, call, truth, 0)
	}
	if flow.Flags&ast.FlowFlagsCall != 0 && flow.Node == call {
		result |= predicateTrue
	}
	result |= l.predicateFlowDirections(flow.Antecedent, call, reference, seen)
	for list := flow.Antecedents; list != nil; list = list.Next {
		result |= l.predicateFlowDirections(list.Flow, call, reference, seen)
	}
	if flow.Flags&ast.FlowFlagsStart != 0 && flow.Node != nil {
		if outer := flow.Node.FlowNodeData(); outer != nil {
			result |= l.predicateFlowDirections(outer.FlowNode, call, reference, seen)
		}
	}
	return result
}

func (l *lowering) predicateConditionDirection(node, call *ast.Node, truth bool, depth int) predicateTruth {
	if node == nil || depth > 16 {
		return 0
	}
	node = ast.SkipParentheses(node)
	if node == call {
		if truth {
			return predicateTrue
		}
		return predicateFalse
	}
	if node.Kind == ast.KindPrefixUnaryExpression && node.AsPrefixUnaryExpression().Operator == ast.KindExclamationToken {
		return l.predicateConditionDirection(node.AsPrefixUnaryExpression().Operand, call, !truth, depth+1)
	}
	if node.Kind == ast.KindBinaryExpression {
		binary := node.AsBinaryExpression()
		switch binary.OperatorToken.Kind {
		case ast.KindAmpersandAmpersandToken, ast.KindBarBarToken:
			precise := truth == (binary.OperatorToken.Kind == ast.KindAmpersandAmpersandToken)
			if precise {
				return l.predicateConditionDirection(binary.Left, call, truth, depth+1) | l.predicateConditionDirection(binary.Right, call, truth, depth+1)
			}
			return l.predicateConditionDirection(binary.Left, call, true, depth+1) | l.predicateConditionDirection(binary.Left, call, false, depth+1) | l.predicateConditionDirection(binary.Right, call, true, depth+1) | l.predicateConditionDirection(binary.Right, call, false, depth+1)
		case ast.KindEqualsToken:
			return l.predicateConditionDirection(binary.Right, call, truth, depth+1)
		}
	}
	if node.Kind == ast.KindNonNullExpression || node.Kind == ast.KindSatisfiesExpression {
		return l.predicateConditionDirection(node.Expression(), call, truth, depth+1)
	}
	if node.Kind == ast.KindIdentifier {
		if symbol := l.symbol(node); symbol != nil {
			for _, declaration := range symbol.Declarations {
				if declaration.Kind == ast.KindVariableDeclaration && declaration.Parent.Flags&ast.NodeFlagsConst != 0 {
					return l.predicateConditionDirection(declaration.AsVariableDeclaration().Initializer, call, truth, depth+1)
				}
			}
		}
	}
	return 0
}

func (l *lowering) predicateDirectionCount(call *ast.CallExpression, directions predicateTruth) int {
	claim := predicateOfSignature(l.checker, l.checker.GetResolvedSignature(call.AsNode()))
	if claim != nil && claim.Kind() == checker.TypePredicateKindAssertsIdentifier {
		directions &= predicateTrue
	}
	count := 0
	if directions&predicateTrue != 0 {
		count++
	}
	if directions&predicateFalse != 0 {
		count++
	}
	return count
}

func predicateDirectionMismatch(returned, membership ir.Expression, directions predicateTruth) ir.Expression {
	mismatch := ir.Expression(ir.Binary{Operator: ir.NotEqual, Left: returned, Right: membership})
	if directions == predicateTrue {
		return ir.Binary{Operator: ir.And, Left: returned, Right: mismatch}
	}
	if directions == predicateFalse {
		return ir.Binary{Operator: ir.And, Left: ir.Unary{Operator: ir.Not, Operand: returned}, Right: mismatch}
	}
	return mismatch
}

func predicateWriteOnly(node *ast.Node) bool {
	if node == nil || !ast.IsAssignmentTarget(node) {
		return false
	}
	parent := node.Parent
	for parent != nil && parent.Kind == ast.KindParenthesizedExpression {
		parent = parent.Parent
	}
	return parent != nil && parent.Kind == ast.KindBinaryExpression && parent.AsBinaryExpression().OperatorToken.Kind == ast.KindEqualsToken
}

// Recompute the read with this call's directional fact removed. Merely finding
// an ancestor condition would attribute a later, independent guard's narrowing
// to every earlier call, even after their branches have rejoined.
// Fresh flow nodes keep the pinned checker's cache and original graph untouched.
func (l *lowering) predicateFlowWithout(root *ast.FlowNode, call, reference *ast.Node, direction predicateTruth) *ast.FlowNode {
	memo := map[*ast.FlowNode]*ast.FlowNode{}
	var clone func(*ast.FlowNode) *ast.FlowNode
	var list func(*ast.FlowList) *ast.FlowList
	list = func(original *ast.FlowList) *ast.FlowList {
		if original == nil {
			return nil
		}
		return &ast.FlowList{Flow: clone(original.Flow), Next: list(original.Next)}
	}
	clone = func(original *ast.FlowNode) *ast.FlowNode {
		if original == nil {
			return nil
		}
		if previous := memo[original]; previous != nil {
			return previous
		}
		copy := &ast.FlowNode{Flags: original.Flags &^ (ast.FlowFlagsShared | ast.FlowFlagsReferenced), Node: original.Node}
		memo[original] = copy
		remove := original.Flags&ast.FlowFlagsCall != 0 && original.Node == call && direction == predicateTrue
		if original.Flags&ast.FlowFlagsCondition != 0 {
			truth := original.Flags&ast.FlowFlagsTrueCondition != 0
			remove = l.predicateConditionDirection(original.Node, call, truth, 0)&direction != 0
		}
		if remove {
			copy.Flags, copy.Node = ast.FlowFlagsBranchLabel, nil
			copy.Antecedents = &ast.FlowList{Flow: clone(original.Antecedent)}
			return copy
		}
		copy.Antecedent, copy.Antecedents = clone(original.Antecedent), list(original.Antecedents)
		if original.Flags&ast.FlowFlagsStart != 0 && original.Node != nil && original.Node.FlowNodeData() != nil && original.Node.FlowNodeData().FlowNode != nil {
			// Stable identifier captures inherit the container's flow. Reconstruct
			// that edge explicitly, without altering its shared AST flow node.
			if reference.Kind == ast.KindIdentifier || (reference.Kind == ast.KindThisKeyword && ast.IsArrowFunction(original.Node)) {
				copy.Flags, copy.Node = ast.FlowFlagsBranchLabel, nil
				copy.Antecedents = &ast.FlowList{Flow: clone(original.Node.FlowNodeData().FlowNode)}
			}
		}
		if original.Flags&ast.FlowFlagsReduceLabel != 0 {
			data := original.Node.AsFlowReduceLabelData()
			copy.Node = ast.NewFlowReduceLabelData(clone(data.Target), list(data.Antecedents))
		}
		return copy
	}
	return clone(root)
}

func (l *lowering) predicateOverloadOrdinal(implementation, overload *ast.Node) int {
	ordinal := 0
	for _, declaration := range l.symbol(implementation.Name()).Declarations {
		if declaration.Kind == ast.KindFunctionDeclaration && declaration.Body() == nil {
			ordinal++
			if declaration == overload {
				return ordinal
			}
		}
	}
	return ordinal
}

func (l *lowering) recordPredicateChecks(call *ast.CallExpression, implementation, overload *ast.Node, observed predicateTruth, proven bool) {
	counts := &l.result.PredicateChecks
	site := ir.PredicateCallCheck{Where: l.program.Where(call.AsNode()), Function: implementation.Name().Text(), Overload: l.predicateOverloadOrdinal(implementation, overload)}
	for _, direction := range []predicateTruth{predicateTrue, predicateFalse} {
		if l.predicateDirectionCount(call, direction) == 0 {
			continue
		}
		name := "true"
		if direction == predicateFalse {
			name = "false"
		}
		report := ir.PredicateDirectionCheck{Direction: name}
		switch {
		case proven:
			report.Status, report.Reason = "proven", "implementation body proves this direction"
			counts.Proven++
		case observed&direction != 0:
			report.Status, report.Reason = "checked", "a narrowed read consumes this direction"
			counts.Checked++
		default:
			report.Status, report.Reason = "unobservable", "no narrowed read in the "+name+" region"
			counts.Proven++
			counts.Unobservable++
		}
		site.Directions = append(site.Directions, report)
	}
	counts.Sites = append(counts.Sites, site)
}

// Inferred callback predicates are claims too. Independently prove the resolved
// target from their own body; checker inference alone is not admission evidence.
func (l *lowering) proveInferredPredicate(function *ast.Node, target *checker.Type) bool {
	claim := predicateOfSignature(l.checker, l.checker.GetSignatureFromDeclaration(function))
	if claim == nil || claim.Type() == nil || !checker.Checker_isTypeIdenticalTo(l.checker, claim.Type(), target) {
		return false
	}
	index := int(claim.ParameterIndex())
	if index < 0 || index >= len(function.Parameters()) {
		return false
	}
	parameter := function.Parameters()[index]
	if parameter.Name().Kind != ast.KindIdentifier || parameter.AsParameterDeclaration().Initializer != nil || parameter.AsParameterDeclaration().DotDotDotToken != nil {
		return false
	}
	changed := false
	var writes ast.Visitor
	writes = func(node *ast.Node) bool {
		if node.Kind == ast.KindIdentifier && l.symbol(node) == l.symbol(parameter.Name()) && ast.IsAssignmentTarget(node) {
			changed = true
		}
		node.ForEachChild(writes)
		return false
	}
	function.Body().ForEachChild(writes)
	if changed {
		return false
	}
	proof := predicateFlowProof{l: l, function: function, parameter: parameter, declared: l.checker.GetTypeAtLocation(parameter.Name()), target: target}
	return proof.proveBody(function) == nil
}

prelude.go:
// Functions and declarations moved unchanged from lower.go.
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
)

// console lowers console.log and console.error with one string.
func (l *lowering) console(call *ast.Node) (ir.Statement, error) {
	stream, err := l.consoleStream(call.AsCallExpression().Expression)
	if err != nil {
		return nil, err
	}
	arguments := call.AsCallExpression().Arguments.Nodes
	if len(arguments) != 1 {
		// The prelude declares one parameter, so the checker has already refused any other count.
		return nil, l.notYet(call, "console."+call.AsCallExpression().Expression.Name().Text()+" with other than one string argument")
	}
	value, err := l.expression(arguments[0])
	if err != nil {
		return nil, err
	}
	if value.Type() != ir.String {
		return nil, l.notYet(call, "console."+call.AsCallExpression().Expression.Name().Text()+" with a non-string argument")
	}
	return ir.WriteLine{Stream: stream, Value: l.spelled(arguments[0], value)}, nil
}

// isPanicCall reports whether an expression is a call to the prelude's panic, which never returns.
func (l *lowering) isPanicCall(expression *ast.Node) bool {
	expression = ast.SkipParentheses(expression)
	return expression.Kind == ast.KindCallExpression && l.isPreludeFunction(expression.AsCallExpression().Expression, "panic")
}

// isPreludeFunction reports whether a callee is the prelude's function of that name, as imported
// from 'adamic', and not one of the program's that shares the name.
func (l *lowering) isPreludeFunction(callee *ast.Node, name string) bool {
	callee = ast.SkipParentheses(callee)
	if !ast.IsIdentifier(callee) {
		return false
	}
	symbol := l.symbol(callee)
	return symbol != nil && symbol.Name == name && len(symbol.Declarations) > 0 && load.IsPrelude(ast.GetSourceFileOfNode(symbol.Declarations[0]))
}

// isConsole reports whether a callee is a method of the prelude's console.
func (l *lowering) isConsole(callee *ast.Node) bool {
	if callee.Kind != ast.KindPropertyAccessExpression {
		return false
	}
	symbol := l.checker.GetSymbolAtLocation(callee.AsPropertyAccessExpression().Expression)
	return isPreludeConsole(symbol)
}

// consoleStream is the stream a callee writes to, when it is the prelude's console.log or
// console.error. A local named console is someone else's, and isn't lowered as this one.
func (l *lowering) consoleStream(callee *ast.Node) (ir.Stream, error) {
	if callee.Kind != ast.KindPropertyAccessExpression {
		return 0, l.notYet(callee, "a call to "+describe(callee))
	}
	object := callee.AsPropertyAccessExpression().Expression
	symbol := l.checker.GetSymbolAtLocation(object)
	if !isPreludeConsole(symbol) {
		return 0, l.notYet(callee, "a method call")
	}
	switch callee.Name().Text() {
	case "log":
		return ir.Stdout, nil
	case "error":
		return ir.Stderr, nil
	}
	return 0, l.notYet(callee, "console."+callee.Name().Text())
}

// Node's global console declaration merges with the prelude variable. Inspect
// all declarations so source ordering cannot turn the real console into a user one.
func isPreludeConsole(symbol *ast.Symbol) bool {
	if symbol == nil || symbol.Name != "console" {
		return false
	}
	for _, declaration := range symbol.Declarations {
		if load.IsPrelude(ast.GetSourceFileOfNode(declaration)) {
			return true
		}
	}
	return false
}

prototype.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
	"strings"
)

// libraryMember follows the declaration, not the spelling: an own callback named toString is
// still an own field. Every declaration must be from the library to specialize a call.
func (l *lowering) memberSymbol(node *ast.Node) *ast.Symbol {
	symbol := l.checker.GetSymbolAtLocation(node)
	if node.Kind == ast.KindElementAccessExpression {
		access := node.AsElementAccessExpression()
		key := ast.SkipParentheses(access.ArgumentExpression)
		if key.Kind == ast.KindStringLiteral {
			symbol = l.checker.GetPropertyOfType(l.checker.GetTypeAtLocation(access.Expression), key.Text())
		}
	}
	return symbol
}

func (l *lowering) libraryMember(node *ast.Node) bool {
	return l.librarySymbol(l.memberSymbol(node))
}

// A union can combine an own callback with an inherited method. That still cannot be an
// unconditional own-field load: any library root is enough to refuse the read.
func (l *lowering) inheritedLibraryMember(node *ast.Node) bool {
	return l.inheritedLibrarySymbol(l.memberSymbol(node))
}

func (l *lowering) inheritedLibrarySymbol(symbol *ast.Symbol) bool {
	if symbol == nil {
		return false
	}
	for _, root := range l.checker.GetRootSymbols(symbol) {
		for _, declaration := range root.Declarations {
			if load.IsLibrary(ast.GetSourceFileOfNode(declaration)) {
				return true
			}
		}
	}
	return false
}

func (l *lowering) librarySymbol(symbol *ast.Symbol) bool {
	if symbol == nil {
		return false
	}
	roots := l.checker.GetRootSymbols(symbol)
	if len(roots) == 0 {
		return false
	}
	for _, root := range roots {
		if len(root.Declarations) == 0 {
			return false
		}
		for _, declaration := range root.Declarations {
			if !load.IsLibrary(ast.GetSourceFileOfNode(declaration)) {
				return false
			}
		}
	}
	return true
}

func (l *lowering) prototypeRead(node *ast.Node, name string) error {
	if name == "isPrototypeOf" {
		return &Refused{Where: l.program.Where(node), What: "isPrototypeOf", Fix: "Adamic has no observable prototype chain; use instanceof for class identity or an explicit discriminant"}
	}
	return &Refused{Where: l.program.Where(node), What: "inherited library member " + name + " read as an own field", Fix: "prototype members are not stored in an object's shape; call the method on its receiver, or wrap that call in an arrow (unbound-method)"}
}

func (l *lowering) objectPrototypeCall(node, receiver *ast.Node, name string) (ir.Expression, bool, error) {
	return l.objectPrototypeCallArguments(node, receiver, name, node.AsCallExpression().Arguments.Nodes)
}

func (l *lowering) objectPrototypeCallArguments(node, receiver *ast.Node, name string, written []*ast.Node) (ir.Expression, bool, error) {
	callee := ast.SkipParentheses(node.AsCallExpression().Expression)
	if !l.libraryMember(callee) {
		return nil, false, nil
	}
	switch name {
	case "toString", "toLocaleString", "valueOf", "hasOwnProperty", "propertyIsEnumerable", "isPrototypeOf":
	default:
		return nil, false, nil
	}
	if name == "isPrototypeOf" {
		return nil, true, &Refused{Where: l.program.Where(node), What: "isPrototypeOf", Fix: "Adamic has no observable prototype chain; use instanceof for class identity or an explicit discriminant"}
	}
	if name != "valueOf" && l.isLibraryType(l.checker.GetTypeAtLocation(receiver), "Error") {
		return nil, true, l.notYet(node, name+" on Error (its prototype and non-enumerable own descriptors differ from plain objects)")
	}
	of, _ := l.representation(l.checker.GetTypeAtLocation(receiver))
	if l.exactPlainObject(receiver) {
		of = ir.Object
	}
	if of == ir.Object || of == ir.Union {
		if reason := l.prototypeHazard(receiver, name); reason != "" {
			return nil, true, l.notYet(node, name+" through an object view ("+reason+")")
		}
	}
	if name == "toString" && of == ir.Number {
		return nil, false, nil
	} // Number's radix overload.
	if name == "toLocaleString" && of == ir.Number {
		return nil, true, &Refused{Where: l.program.Where(node), What: name + " on a number", Fix: "JavaScript uses locale-sensitive number formatting; use toString for deterministic formatting"}
	}
	if name == "toLocaleString" && of == ir.Array {
		element, err := l.elementType(receiver)
		if err != nil {
			return nil, true, err
		}
		if element != ir.String && element != ir.Boolean {
			return nil, true, &Refused{Where: l.program.Where(node), What: name + " on this array", Fix: "JavaScript formats each element with its own toLocaleString, which may be locale-sensitive or user-defined; use toString for deterministic formatting"}
		}
	}
	if name == "hasOwnProperty" || name == "propertyIsEnumerable" {
		if of != ir.Object {
			return l.nonObjectOwnPropertyArguments(node, receiver, name, of, written)
		}
		if checker.IsTupleType(l.checker.GetTypeAtLocation(receiver)) {
			return nil, true, l.notYet(node, name+" on a tuple (its representation includes absent optional slots and no length descriptor)")
		}
		// Every own field of a plain object or a class instance is enumerable. Methods are on its
		// prototype, absent from its shape, and defineProperty is refused.
		return l.hasOwnPropertyArguments(node, receiver, written)
	}
	if len(written) != 0 {
		return nil, true, l.notYet(node, name+" with arguments")
	}
	if checker.IsTupleType(l.checker.GetTypeAtLocation(receiver)) {
		return nil, true, l.notYet(node, name+" on a tuple (its native representation is not an array)")
	}
	if name == "toLocaleString" {
		toString := l.checker.GetPropertyOfType(l.checker.GetTypeAtLocation(receiver), "toString")
		if toString == nil || len(toString.Declarations) == 0 || !load.IsLibrary(ast.GetSourceFileOfNode(toString.Declarations[0])) {
			return nil, true, l.notYet(node, "toLocaleString delegating to a user-defined toString")
		}
	}
	value, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	if name == "valueOf" {
		if result, _ := l.representation(l.checker.GetTypeAtLocation(node)); result == ir.Union && of == ir.Object {
			return fit(value, result), true, nil
		} else if result != of {
			return nil, true, l.notYet(node, "valueOf whose library result type erases the "+typeName(of)+" representation to Object (keeping or returning that result needs a tagged object view)")
		}
		switch of {
		case ir.Number, ir.Boolean, ir.String, ir.Object, ir.Array, ir.Map, ir.Closure:
			return value, true, nil
		}
	}
	switch of {
	case ir.String:
		return value, true, nil
	case ir.Boolean:
		return ir.BooleanToString{Value: value}, true, nil
	case ir.Array:
		return l.arrayMethodArguments(node, receiver, "join", written)
	case ir.Object, ir.Map:
		tag := "[object Object]"
		if of == ir.Map {
			tag = "[object Map]"
			if l.isSet(receiver) {
				tag = "[object Set]"
			}
		}
		text := ir.StringConstant{Index: l.constant(tag)}
		// Both arms are the same, but the test evaluates the receiver exactly once, preserving its
		// side effects and any narrowed-read check. No field is read to produce the constant tag.
		return ir.Conditional{Condition: ir.IsUndefined{Value: value}, WhenTrue: text, WhenNot: text}, true, nil
	}
	return nil, true, l.notYet(node, name+" on a "+typeName(of)+" (function source text and mixed value dispatch are not represented)")
}

// Structural object views can hide an override, an Error, or an artificial absent-spread slot.
// Until prototype dispatch and presence descriptors exist, refuse any compatible runtime shape
// in the whole program with one of those hazards. This deliberately errs toward refusal.
func (l *lowering) prototypeHazard(receiver *ast.Node, name string) string {
	view := l.concrete(l.checker.GetTypeAtLocation(receiver))
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return "the program's runtime shapes are not known"
	}
	reason := ""
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if reason != "" {
			return true
		}
		if node.Kind == ast.KindObjectLiteralExpression || node.Kind == ast.KindRegularExpressionLiteral || (node.Kind == ast.KindCallExpression && l.isLibraryType(l.checker.GetTypeAtLocation(node), "RegExp", "RegExpStringIterator")) || node.Kind == ast.KindNewExpression || node.Kind == ast.KindArrayLiteralExpression || node.Kind == ast.KindArrowFunction || node.Kind == ast.KindNumericLiteral || node.Kind == ast.KindStringLiteral || node.Kind == ast.KindTrueKeyword || node.Kind == ast.KindFalseKeyword {
			shape := l.checker.GetTypeAtLocation(node)
			if l.checker.IsTypeAssignableTo(shape, view) {
				if l.isLibraryType(shape, "RegExp", "RegExpStringIterator") && !l.exactPlainObject(receiver) {
					// Regex objects have intrinsic prototype behavior and metadata slots. A structural
					// view cannot make those plain-object methods or own-property descriptors.
					reason = "a RegExp or its iterator may be hidden by the view"
					return true
				}
				if representation, known := l.representation(shape); known && representation != ir.Object && !l.exactPlainObject(receiver) {
					reason = "a value with a different native representation may be hidden by the view"
					return true
				}
				if name != "valueOf" && l.isLibraryType(shape, "Error") {
					reason = "an Error may be hidden by the view"
					return true
				}
				member := l.checker.GetPropertyOfType(shape, name)
				if member != nil && !l.librarySymbol(member) {
					reason = "a user-defined " + name + " may be hidden by the view"
					return true
				}
				if name == "toLocaleString" {
					member = l.checker.GetPropertyOfType(shape, "toString")
					if member != nil && !l.librarySymbol(member) {
						reason = "a user-defined toString may be hidden by the view"
						return true
					}
				}
				if name == "hasOwnProperty" || name == "propertyIsEnumerable" {
					for _, field := range l.checker.GetPropertiesOfType(shape) {
						if strings.ContainsRune(field.Name, 0) {
							reason = "a field name contains NUL, which native shape names cannot represent"
							return true
						}
					}
					if node.Kind == ast.KindObjectLiteralExpression {
						for _, property := range node.AsObjectLiteralExpression().Properties.Nodes {
							if property.Kind == ast.KindSpreadAssignment && l.includesUndefined(l.checker.GetTypeAtLocation(property.AsSpreadAssignment().Expression)) {
								reason = "a possibly absent spread has slots without own-property presence descriptors"
								return true
							}
						}
					}
					if node.Kind == ast.KindNewExpression {
						if declaration := l.classes[l.symbol(ast.SkipParentheses(node.AsNewExpression().Expression))]; declaration != nil {
							for _, member := range declaration.Members() {
								if ast.HasSyntacticModifier(member, ast.ModifierFlagsAmbient) {
									reason = "declared class fields have no JavaScript own property"
									return true
								}
								if member.Name() != nil && member.Name().Kind == ast.KindPrivateIdentifier {
									reason = "private class slots are not JavaScript own properties"
									return true
								}
							}
						}
					}
				}
			}
		}
		node.ForEachChild(visit)
		return false
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return reason
}

// An unannotated const made directly from a plain literal has no boxed primitive hidden by a
// structural view. Its shape is fixed; spreads and annotated/widened names need the whole scan.
func (l *lowering) exactPlainObject(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if ast.IsIdentifier(node) {
		symbol := l.checker.GetSymbolAtLocation(node)
		if symbol == nil || len(symbol.Declarations) != 1 {
			return false
		}
		declaration := symbol.Declarations[0]
		if declaration.Kind != ast.KindVariableDeclaration || declaration.AsVariableDeclaration().Type != nil || declaration.Parent == nil || declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
			return false
		}
		node = declaration.AsVariableDeclaration().Initializer
		if node == nil {
			return false
		}
		node = ast.SkipParentheses(node)
	}
	if node.Kind != ast.KindObjectLiteralExpression {
		return false
	}
	for _, field := range node.AsObjectLiteralExpression().Properties.Nodes {
		if field.Kind == ast.KindSpreadAssignment {
			return false
		}
	}
	return true
}

prototype_own.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// nonObjectOwnProperty spells the descriptors of the values whose shape is fixed by the language.
// A generated function keeps the receiver and key in parameters, so each is evaluated once, in
// JavaScript's order, even when the answer is constant. No native representation is read as an object.
func (l *lowering) nonObjectOwnProperty(node, receiver *ast.Node, name string, of ir.Type) (ir.Expression, bool, error) {
	return l.nonObjectOwnPropertyArguments(node, receiver, name, of, node.AsCallExpression().Arguments.Nodes)
}

func (l *lowering) nonObjectOwnPropertyArguments(node, receiver *ast.Node, name string, of ir.Type, arguments []*ast.Node) (ir.Expression, bool, error) {
	functionPrototype := -1
	if of == ir.Closure {
		functionPrototype = l.functionPrototype(receiver, 0)
	}
	switch of {
	case ir.Number, ir.Boolean, ir.String, ir.Array, ir.Map:
	case ir.Closure:
		if name == "hasOwnProperty" && functionPrototype < 0 {
			return nil, true, l.notYet(node, "hasOwnProperty on a function (its prototype property depends on whether it was declared or made as an arrow)")
		}
	default:
		return nil, true, l.notYet(node, name+" on a "+typeName(of)+" (mixed value descriptors are not represented)")
	}
	if len(arguments) != 1 {
		return nil, true, l.notYet(node, name+" with other than one key")
	}
	if keyType, _ := l.representation(l.checker.GetTypeAtLocation(arguments[0])); keyType != ir.String {
		return nil, true, l.notYet(node, name+" with a key that isn't a string")
	}
	value, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	key, err := l.expression(arguments[0])
	if err != nil {
		return nil, true, err
	}
	function := len(l.result.Functions)
	held := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals,
		ir.Local{Name: "receiver", Type: of, Function: function},
		ir.Local{Name: "key", Type: ir.String, Function: function},
	)
	body := []ir.Statement{}
	result := ir.Expression(ir.BooleanConstant{Value: false})
	if of == ir.Closure && name == "hasOwnProperty" {
		readKey := ir.Read{Local: held + 1, Of: ir.String}
		result = ir.Binary{Operator: ir.Or,
			Left:  ir.Binary{Operator: ir.Equal, Left: readKey, Right: ir.StringConstant{Index: l.constant("length")}},
			Right: ir.Binary{Operator: ir.Equal, Left: readKey, Right: ir.StringConstant{Index: l.constant("name")}},
		}
		if functionPrototype == 1 {
			result = ir.Binary{Operator: ir.Or, Left: result, Right: ir.Binary{Operator: ir.Equal, Left: readKey, Right: ir.StringConstant{Index: l.constant("prototype")}}}
		}
	}
	if of == ir.Array || of == ir.String {
		index := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: "index", Type: ir.Number, Function: function})
		readKey := ir.Read{Local: held + 1, Of: ir.String}
		parsed := ir.Read{Local: index, Of: ir.Number}
		readReceiver := ir.Read{Local: held, Of: of}
		length := ir.Expression(ir.StringLength{Value: readReceiver})
		if of == ir.Array {
			length = ir.Length{Array: readReceiver}
		}
		body = append(body, ir.Declare{Local: index, Value: ir.NumberCall{Function: "parseInt", Arguments: []ir.Expression{readKey, ir.NumberConstant{Value: 10}}}})
		// Only a canonical non-negative index is own. parseInt alone would admit '01', '-0', '1x'
		// and fractional text; the round trip rejects those. A NaN fails the comparisons first.
		result = ir.Binary{Operator: ir.And,
			Left: ir.Binary{Operator: ir.And,
				Left:  ir.Binary{Operator: ir.GreaterOrEqual, Left: parsed, Right: ir.NumberConstant{Value: 0}},
				Right: ir.Binary{Operator: ir.Less, Left: parsed, Right: length},
			},
			Right: ir.Binary{Operator: ir.Equal, Left: ir.NumberToString{Value: parsed}, Right: readKey},
		}
		// Both arrays and boxed strings have an own length, which is not enumerable.
		result = ir.Conditional{
			Condition: ir.Binary{Operator: ir.Equal, Left: readKey, Right: ir.StringConstant{Index: l.constant("length")}},
			WhenTrue:  ir.BooleanConstant{Value: name == "hasOwnProperty"}, WhenNot: result,
		}
	}
	body = append(body, ir.Return{Value: result})
	l.result.Functions = append(l.result.Functions, ir.Function{Name: name + "_" + typeName(of), Parameters: []int{held, held + 1}, Returns: ir.Boolean, Body: body})
	return ir.Call{Function: function, Arguments: []ir.Expression{value, key}, Returns: ir.Boolean}, true, nil
}

// A module function has an own, non-enumerable prototype; an arrow has none. A parameter or field
// can hold either, so it needs a runtime origin tag before hasOwnProperty can answer soundly.
func (l *lowering) functionPrototype(node *ast.Node, depth int) int {
	if depth > 16 {
		return -1
	}
	node = ast.SkipParentheses(node)
	if node.Kind == ast.KindArrowFunction {
		return 0
	}
	if !ast.IsIdentifier(node) {
		return -1
	}
	symbol := l.symbol(node)
	if _, found := l.functions[symbol]; found {
		return 1
	}
	if _, found := l.generics[symbol]; found {
		return 1
	}
	if symbol == nil || len(symbol.Declarations) != 1 {
		return -1
	}
	declaration := symbol.Declarations[0]
	if declaration.Kind != ast.KindVariableDeclaration || declaration.Parent == nil || declaration.Parent.Flags&ast.NodeFlagsConst == 0 {
		return -1
	}
	initializer := declaration.AsVariableDeclaration().Initializer
	if initializer == nil {
		return -1
	}
	return l.functionPrototype(initializer, depth+1)
}

proven_relations.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
)

// provenRelation holds satisfies and erased upcasts to the same writable-slot and nominal
// proofs as assignments. Contextual typing may build a fresh literal at the target type;
// values it contains are still checked at their own assignment sites by the refusal walk.
func (l *lowering) provenRelation(where, expression *ast.Node, target *checker.Type) error {
	source := l.checker.GetTypeAtLocation(expression)
	refuse := func(part, fix string) error {
		return &Refused{Where: l.program.Where(where), What: "an unproven relation from " + l.checker.TypeToString(source) + " to " + l.checker.TypeToString(target) + ": " + part, Fix: fix}
	}
	if !l.checker.IsTypeAssignableTo(source, target) && !l.checker.IsTypeAssignableTo(l.checker.GetWidenedType(source), target) {
		return refuse("the source is not assignable to the target", "use a compatible type or narrow the value before using it")
	}
	if found := l.freshOrWidened(expression, source, target); found != nil {
		return l.wideningRefusal(where, source, target, found)
	}
	if field := l.optionalRelationFailure(source, target, expression, map[[2]*checker.Type]bool{}); field != "" {
		return refuse("optional field "+field+" has no proven compatible presence/type", "keep compatible optional fields in both views, or construct an object with explicitly compatible fields (adamic/no-optional-widening)")
	}
	if mismatch := l.nominalMismatch(source, target, map[[2]*checker.Type]bool{}); mismatch != nil {
		return refuse("nominal ancestry for "+l.checker.TypeToString(mismatch), "construct that class or a subclass; use an interface for structural values (adamic/nominal-class)")
	}
	return nil
}

// Optional fields absent from a structural view may exist with an unrelated type at runtime.
// Follow containers, callback arguments/results and nested fields, as the other relation walks do.
func (l *lowering) optionalRelationFailure(from, to *checker.Type, origin *ast.Node, seen map[[2]*checker.Type]bool) string {
	if from == nil || to == nil || from == to || seen[[2]*checker.Type{from, to}] {
		return ""
	}
	seen[[2]*checker.Type{from, to}] = true
	defer delete(seen, [2]*checker.Type{from, to})
	if origin != nil {
		origin = ast.SkipParentheses(origin)
	}
	exact := origin != nil && origin.Kind == ast.KindObjectLiteralExpression
	if exact {
		for _, property := range origin.AsObjectLiteralExpression().Properties.Nodes {
			if property.Kind == ast.KindSpreadAssignment {
				exact = false
			}
		}
	}
	if from.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range from.Types() {
			if field := l.optionalRelationFailure(member, to, origin, seen); field != "" {
				return field
			}
		}
		return ""
	}
	if to.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range to.Types() {
			if l.checker.IsTypeAssignableTo(from, member) {
				if field := l.optionalRelationFailure(from, member, origin, seen); field != "" {
					return field
				}
			}
		}
		return ""
	}
	if from.Flags()&checker.TypeFlagsTypeParameter != 0 {
		return l.optionalRelationFailure(l.checker.GetBaseConstraintOfType(from), to, nil, seen)
	}
	if !l.structured(from) || !l.structured(to) {
		return ""
	}
	fromSignatures := l.checker.GetSignaturesOfType(from, checker.SignatureKindCall)
	toSignatures := l.checker.GetSignaturesOfType(to, checker.SignatureKindCall)
	if len(fromSignatures) > 0 && len(toSignatures) > 0 {
		parameters := toSignatures[0].Parameters()
		if l.censusNeverRestSignature(toSignatures[0]) {
			parameters = nil
		}
		for index, parameter := range parameters {
			if index >= len(fromSignatures[0].Parameters()) {
				break
			}
			if field := l.optionalRelationFailure(l.checker.GetTypeOfSymbol(parameter), l.checker.GetTypeOfSymbol(fromSignatures[0].Parameters()[index]), nil, seen); field != "" {
				return "parameter." + field
			}
		}
		return l.optionalRelationFailure(l.checker.GetReturnTypeOfSignature(fromSignatures[0]), l.checker.GetReturnTypeOfSignature(toSignatures[0]), nil, seen)
	}
	// Class type arguments are invariant even when the class only exposes readonly fields.
	if isClassInstance(to) {
		if declaration := l.classNodeFor(to); declaration != nil {
			if actual := l.classView(from, declaration); actual != nil {
				fromArguments, toArguments := l.checker.GetTypeArguments(actual), l.checker.GetTypeArguments(to)
				for index := 0; index < len(fromArguments) && index < len(toArguments); index++ {
					if field := l.optionalRelationFailure(fromArguments[index], toArguments[index], nil, seen); field != "" {
						return "type argument." + field
					}
					if field := l.optionalRelationFailure(toArguments[index], fromArguments[index], nil, seen); field != "" {
						return "type argument." + field
					}
				}
			}
		}
	}
	fresh := exact || (origin != nil && (origin.Kind == ast.KindArrayLiteralExpression || l.freshValue(origin)))
	for _, target := range l.containers(to) {
		for _, source := range l.containers(from) {
			if !l.sameContainer(source, target) {
				continue
			}
			fromArguments, toArguments := l.checker.GetTypeArguments(source), l.checker.GetTypeArguments(target)
			if origin != nil && origin.Kind == ast.KindArrayLiteralExpression && len(toArguments) == 1 && !checker.IsTupleType(target) {
				for _, element := range origin.AsArrayLiteralExpression().Elements.Nodes {
					if element.Kind == ast.KindSpreadElement {
						if field := l.optionalRelationFailure(l.checker.GetTypeAtLocation(element.AsSpreadElement().Expression), target, nil, seen); field != "" {
							return field
						}
					} else if field := l.optionalRelationFailure(l.checker.GetTypeAtLocation(element), toArguments[0], element, seen); field != "" {
						return "element." + field
					}
				}
				continue
			}
			if checker.IsTupleType(source) && !checker.IsTupleType(target) && len(toArguments) == 1 {
				elements := make([]*checker.Type, len(fromArguments))
				for index := range elements {
					elements[index] = toArguments[0]
				}
				toArguments = elements
			}
			mutable := !fresh && !l.isLibraryType(target, "ReadonlyArray", "ReadonlyMap", "ReadonlySet") && !(checker.IsTupleType(target) && target.TargetTupleType().IsReadonly())
			for index := 0; index < len(fromArguments) && index < len(toArguments); index++ {
				if field := l.optionalRelationFailure(fromArguments[index], toArguments[index], nil, seen); field != "" {
					return "element." + field
				}
				if mutable {
					if field := l.optionalRelationFailure(toArguments[index], fromArguments[index], nil, seen); field != "" {
						return "element." + field
					}
				}
			}
		}
	}
	if len(l.containers(to)) > 0 {
		return ""
	}
	for _, property := range l.checker.GetPropertiesOfType(to) {
		inside := l.checker.GetPropertyOfType(from, property.Name)
		if inside == nil {
			if property.Flags&ast.SymbolFlagsOptional != 0 && !exact {
				return property.Name
			}
			continue
		}
		if field := l.optionalRelationFailure(l.checker.GetTypeOfSymbol(inside), l.checker.GetTypeOfSymbol(property), relationFieldExpression(origin, property.Name), seen); field != "" {
			return property.Name + "." + field
		}
		if !fresh && !l.checker.IsReadonlySymbol(property) && property.Flags&ast.SymbolFlagsMethod == 0 && inside.Flags&ast.SymbolFlagsMethod == 0 {
			if field := l.optionalRelationFailure(l.checker.GetTypeOfSymbol(property), l.checker.GetTypeOfSymbol(inside), nil, seen); field != "" {
				return property.Name + "." + field
			}
		}
	}
	return ""
}

// An explicitly written field may itself be an exact literal. Shorthands and spread fields
// remain structural views, whose runtime fields their types may hide.
func relationFieldExpression(origin *ast.Node, name string) *ast.Node {
	if origin == nil || origin.Kind != ast.KindObjectLiteralExpression {
		return nil
	}
	for _, property := range origin.AsObjectLiteralExpression().Properties.Nodes {
		if property.Kind == ast.KindPropertyAssignment && property.Name().Text() == name {
			return property.AsPropertyAssignment().Initializer
		}
	}
	return nil
}

readiness.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/scanner"
	"github.com/system-inc/adamic/internal/flow"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
	"reflect"
	"slices"
)

func sourceExpression(node *ast.Node) string {
	file := ast.GetSourceFileOfNode(node)
	return file.Text()[scanner.GetTokenPosOfNode(node, file, false):node.End()]
}

// Only direct initializer syntax reserves an uninitialized slot. Assignments, returns,
// and assertions outside initializer positions continue to use the nullish check.
func (l *lowering) uninitializedInitializer(node *ast.Node) bool {
	if node == nil || l.checkedAssertionSource(node) {
		return false
	}
	node = ast.SkipParentheses(node)
	if node.Kind != ast.KindNonNullExpression {
		return false
	}
	operand := ast.SkipParentheses(node.AsNonNullExpression().Expression)
	if operand.Kind == ast.KindNullKeyword {
		return true
	}
	if operand.Kind != ast.KindIdentifier || operand.Text() != "undefined" {
		return false
	}
	symbol := l.symbol(operand)
	if symbol == nil || len(symbol.Declarations) == 0 {
		return true
	}
	return load.IsLibrary(ast.GetSourceFileOfNode(symbol.Declarations[0]))
}

func (l *lowering) uninitializedDeclaration(node *ast.Node) bool {
	switch node.Kind {
	case ast.KindVariableDeclaration:
		return node.AsVariableDeclaration().ExclamationToken != nil || l.uninitializedInitializer(node.AsVariableDeclaration().Initializer)
	case ast.KindPropertyDeclaration:
		return node.PostfixToken() != nil && node.PostfixToken().Kind == ast.KindExclamationToken || l.uninitializedInitializer(node.AsPropertyDeclaration().Initializer)
	}
	return false
}

// readiness uses the existing CFG, including its exceptional edges. Readiness is monotone
// between declarations: an assignment makes the slot ready, and calls cannot unset it.
// Captures and globals participate in this bit analysis even though value SSA excludes them.
func readiness(program *ir.Program) {
	// A record's named fields live in a counted table, not inline slots.
	// Retain their representation checks even through a narrower parameter view.
	if program.CheckedFields == nil {
		program.CheckedFields = map[string]bool{}
	}
	markRecord := func(node any) bool {
		if literal, ok := node.(ir.ObjectLiteral); ok && literal.Record {
			for _, field := range literal.Fields {
				program.CheckedFields[field.Name] = true
			}
		}
		if set, ok := node.(ir.SetProperty); ok && set.Record {
			program.CheckedFields[set.Name] = true
		}
		return true
	}
	walk(program.Main, markRecord)
	for _, function := range program.Functions {
		walk(function.Body, markRecord)
	}
	names := map[string]bool{}
	walk(program.Main, func(node any) bool {
		if value, ok := node.(ir.ObjectLiteral); ok {
			for _, field := range value.Fields {
				if field.Uninitialized {
					names[field.Name] = true
				}
			}
		}
		if value, ok := node.(ir.SetProperty); ok && value.Uninitialized {
			names[value.Name] = true
		}
		return true
	})
	for _, function := range program.Functions {
		walk(function.Body, func(node any) bool {
			if value, ok := node.(ir.ObjectLiteral); ok {
				for _, field := range value.Fields {
					if field.Uninitialized {
						names[field.Name] = true
					}
				}
			}
			if value, ok := node.(ir.SetProperty); ok && value.Uninitialized {
				names[value.Name] = true
			}
			return true
		})
	}
	program.UninitializedFields = names
	marked := len(names) != 0
	for _, local := range program.Locals {
		marked = marked || local.Uninitialized
	}
	if !marked {
		clear := func(body []ir.Statement) []ir.Statement {
			for index, statement := range body {
				body[index] = readinessStatement(statement, program, names, nil, nil)
			}
			return body
		}
		program.Main = clear(program.Main)
		for index := range program.Functions {
			program.Functions[index].Body = clear(program.Functions[index].Body)
		}
		return
	}
	for function := -1; function < len(program.Functions); function++ {
		// The graph's locations still point into the original body, while the local metadata
		// copy lets its existing builder track cells and globals without changing value SSA.
		tracked := *program
		tracked.Locals = slices.Clone(program.Locals)
		for i := range tracked.Locals {
			tracked.Locals[i].Global, tracked.Locals[i].Captured = false, false
		}
		graph := flow.Build(&tracked, function)
		fieldSlots := map[fieldReadiness]int{}
		statements := program.Main
		if function >= 0 {
			statements = program.Functions[function].Body
		}
		walk(statements, func(node any) bool {
			if property, ok := node.(ir.Property); ok && names[property.Name] {
				if local, ok := readinessObject(property.Object); ok {
					key := fieldReadiness{local, property.Name}
					if _, found := fieldSlots[key]; !found {
						fieldSlots[key] = len(program.Locals) + len(fieldSlots)
					}
				}
			}
			return true
		})
		count := len(program.Locals) + len(fieldSlots)
		ins, outs, exceptional := map[flow.BlockId][]bool{}, map[flow.BlockId][]bool{}, map[flow.BlockId][]bool{}
		for _, block := range graph.Blocks {
			ins[block.Id], outs[block.Id], exceptional[block.Id] = make([]bool, count), make([]bool, count), make([]bool, count)
			// Must analysis starts at top away from entry; loops converge by intersection.
			if block.Id != graph.Entry {
				for i := 0; i < count; i++ {
					ins[block.Id][i], outs[block.Id][i], exceptional[block.Id][i] = true, true, true
				}
			}
		}
		entry := make([]bool, count)
		for i, local := range program.Locals {
			entry[i] = !local.Uninitialized
		}
		changed := true
		for changed {
			changed = false
			for _, block := range graph.Blocks {
				state := slices.Clone(entry)
				if block.Id != graph.Entry {
					for i := range state {
						state[i] = true
					}
					for _, pred := range block.Predecessors {
						previous := outs[pred]
						parent, _ := graph.Block(pred)
						if edge, ok := parent.Terminal.(*flow.MayThrow); ok && edge.Handler == block.Id {
							previous = exceptional[pred]
						}
						for i := range state {
							state[i] = state[i] && previous[i]
						}
					}
				}
				if !slices.Equal(ins[block.Id], state) {
					ins[block.Id] = slices.Clone(state)
					changed = true
				}
				beforeLast := slices.Clone(state)
				for _, id := range block.Instructions {
					instruction := graph.Instructions[id]
					if readinessCalls(instruction) {
						for _, slot := range fieldSlots {
							state[slot] = false
						}
					}
					beforeLast = slices.Clone(state)
					readinessWrite(program, graph, instruction, state, fieldSlots)
				}
				if !slices.Equal(outs[block.Id], state) {
					outs[block.Id] = state
					changed = true
				}
				if !slices.Equal(exceptional[block.Id], beforeLast) {
					exceptional[block.Id] = beforeLast
					changed = true
				}
			}
		}
		for _, block := range graph.Blocks {
			state := slices.Clone(ins[block.Id])
			for _, id := range block.Instructions {
				instruction := graph.Instructions[id]
				if readinessCalls(instruction) {
					for _, slot := range fieldSlots {
						state[slot] = false
					}
				}
				if instruction.Part == 0 {
					*instruction.At = readinessStatement(*instruction.At, program, names, state, fieldSlots)
				}
				readinessWrite(program, graph, instruction, state, fieldSlots)
			}
		}
	}
}

func readinessWrite(program *ir.Program, graph *flow.Function, instruction *flow.Instruction, state []bool, fields map[fieldReadiness]int) {
	for _, place := range instruction.Defines {
		local := int(graph.Identifiers[place.Identifier].Declaration) - 1
		ready := true
		if declare, ok := (*instruction.At).(ir.Declare); ok {
			ready = !declare.Uninitialized
		}
		state[local] = ready
		for field, slot := range fields {
			if field.local == local {
				state[slot] = false
			}
		}
	}
	if set, ok := (*instruction.At).(ir.SetProperty); ok {
		if local, ok := readinessObject(set.Object); ok {
			if slot, found := fields[fieldReadiness{local, set.Name}]; found {
				state[slot] = !set.Uninitialized
			}
		}
	}
}

// Transform just this instruction's expressions. Nested statements have their own graph locations.
func readinessStatement(statement ir.Statement, program *ir.Program, fields map[string]bool, ready []bool, fieldSlots map[fieldReadiness]int) ir.Statement {
	var transform func(reflect.Value) reflect.Value
	transform = func(value reflect.Value) reflect.Value {
		if value.Kind() == reflect.Interface {
			if value.IsNil() || ready != nil && value.Type() == statementType {
				return value
			}
			mapped := transform(value.Elem())
			node := mapped.Interface()
			switch expression := node.(type) {
			case ir.Read:
				if program.Locals[expression.Local].Uninitialized && !ready[expression.Local] {
					if expression.Readiness == "" {
						expression.Readiness = program.Locals[expression.Local].Name
					}
					if origin := program.Locals[expression.Local].InitializerExpression; origin != "" {
						expression.Readiness = origin
					}
					expression.Checked = false
				} else {
					expression.Readiness = ""
					if program.Locals[expression.Local].Uninitialized {
						expression.Checked = false
					}
				}
				node = expression
			case ir.ObjectLiteral:
				if expression.Spread != nil && len(fields) > 0 {
					expression.NoReuse = true
					if expression.SpreadReadiness == "" {
						expression.SpreadReadiness = "object spread"
					}
				} else {
					expression.SpreadReadiness = ""
				}
				node = expression
			case ir.Property:
				if !program.CheckedFields[expression.Name] || expression.Method {
					expression.View = ""
					expression.ViewType = ""
					expression.ViewAllowed = nil
					expression.ViewContract = 0
				} else if expression.ViewTypeID != 0 {
					expression.ViewContract = program.ViewContractTypes[expression.ViewTypeID]
				}
				proven := false
				if local, ok := readinessObject(expression.Object); ok {
					if slot, found := fieldSlots[fieldReadiness{local, expression.Name}]; found {
						proven = ready[slot]
					}
				}
				if fields[expression.Name] && !proven {
					if expression.Readiness == "" {
						expression.Readiness = expression.Name
					}
				} else {
					expression.Readiness = ""
				}
				node = expression
			}
			result := reflect.New(value.Type()).Elem()
			result.Set(reflect.ValueOf(node))
			return result
		}
		switch value.Kind() {
		case reflect.Struct:
			result := reflect.New(value.Type()).Elem()
			for i := 0; i < value.NumField(); i++ {
				result.Field(i).Set(transform(value.Field(i)))
			}
			return result
		case reflect.Array:
			result := reflect.New(value.Type()).Elem()
			for i := 0; i < value.Len(); i++ {
				result.Index(i).Set(transform(value.Index(i)))
			}
			return result
		case reflect.Slice:
			if value.IsNil() || ready != nil && value.Type() == reflect.TypeOf([]ir.Statement{}) {
				return value
			}
			result := reflect.MakeSlice(value.Type(), value.Len(), value.Len())
			for i := 0; i < value.Len(); i++ {
				result.Index(i).Set(transform(value.Index(i)))
			}
			return result
		}
		return value
	}
	result := transform(reflect.ValueOf(statement)).Interface().(ir.Statement)
	if assign, ok := result.(ir.Assign); ok && program.Locals[assign.Local].Uninitialized {
		assign.Checked = false
		result = assign
	}
	return result
}

// A field fact belongs to one binding's current object, never just to its field name.
type fieldReadiness struct {
	local int
	name  string
}

func readinessObject(value ir.Expression) (int, bool) {
	switch value := value.(type) {
	case ir.Read:
		return value.Local, true
	case ir.Defined:
		return readinessObject(value.Value)
	case ir.Narrow:
		return readinessObject(value.Value)
	}
	return 0, false
}
func readinessCalls(instruction *flow.Instruction) bool {
	var node any = instruction.Expression
	if node == nil {
		switch statement := (*instruction.At).(type) {
		case ir.SetProperty, ir.SetIndex:
			node = statement
		}
	}
	calls := false
	walk(node, func(node any) bool {
		switch node.(type) {
		case ir.Call, ir.CallClosure, ir.ArrayMap, ir.ArrayVisit, ir.ArrayReduce, ir.ArraySort, ir.ArrayFrom, ir.MapForEach:
			calls = true
		}
		return true
	})
	return calls
}

// assertionInitializer recognizes syntax only; its operand is evaluated at the declaration.
func assertionInitializer(node *ast.Node) bool {
	return node != nil && ast.SkipParentheses(node).Kind == ast.KindNonNullExpression
}

// TypeScript assertions are eager checks, including in storage initializers.
func (l *lowering) lazyAssertionInitializer(node *ast.Node) bool {
	return assertionInitializer(node) && !l.checkedAssertionSource(node)
}

func assertionVarList(list *ast.Node) bool {
	for _, declaration := range list.AsVariableDeclarationList().Declarations.Nodes {
		if !ast.IsIdentifier(declaration.Name()) || !assertionInitializer(declaration.AsVariableDeclaration().Initializer) {
			return false
		}
	}
	return len(list.AsVariableDeclarationList().Declarations.Nodes) > 0
}

// lazyAssertion holds the original representation once and assigns only when present.
func (l *lowering) lazyAssertion(node *ast.Node, to ir.Type) ([]ir.Statement, ir.Expression, ir.Expression, error) {
	operand := ast.SkipParentheses(node).AsNonNullExpression().Expression
	value, err := l.expression(operand)
	if err != nil {
		return nil, nil, nil, err
	}
	for {
		switch narrowed := value.(type) {
		case ir.Unwrap:
			value = narrowed.Value
		case ir.Defined:
			value = narrowed.Value
		case ir.Narrow:
			value = narrowed.Value
		default:
			goto stored
		}
	}
stored:
	if weak, ok := value.(ir.WeakTarget); ok {
		weak.Present = false
		value = weak
	}
	if !value.Type().IsMaybe() && !value.Type().IsReference() {
		return nil, ir.BooleanConstant{Value: true}, fit(value, to), nil
	}
	local := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "assertion_initializer", Type: value.Type(), Function: l.functionIndex})
	read := ir.Read{Local: local, Of: value.Type()}
	present := ir.Expression(ir.BooleanConstant{Value: true})
	if value.Type().IsMaybe() {
		present = ir.Unary{Operator: ir.Not, Operand: ir.IsUndefined{Value: read}}
	} else if value.Type().IsReference() {
		present = ir.Unary{Operator: ir.Not, Operand: ir.Binary{Operator: ir.Or, Left: ir.IsUndefined{Value: read}, Right: ir.IsNull{Value: read}}}
	}
	assigned := fit(read, to)
	if read.Type() == ir.Union && to != ir.Union {
		assigned = ir.Narrow{Value: read, To: to}
	}
	return []ir.Statement{ir.Declare{Local: local, Value: value}}, present, assigned, nil
}

refusals.go:
package lower

import (
	"fmt"
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/microsoft/TypeScript/tsc/shim/scanner"
)

// refusal is one construct Adamic 0.1 doesn't allow (docs/0.1.md, "What's refused in 0.1"), and the
// fix to offer for it.
type refusal struct {
	what string
	fix  string
}

// refusals by syntax kind. Each is checked before lowering, so a program learns it has written
// something 0.1 refuses for good, never that stage 0 hasn't got to it yet.
var refusals = map[ast.Kind]refusal{
	ast.KindNonNullExpression: {"the non-null assertion !", "write ?? panic('why it can't be missing'), or narrow and handle the missing case"},
	ast.KindAwaitExpression:   {"await", "0.1 has no async; it arrives with the concurrency model"},
	ast.KindYieldExpression:   {"yield (generators)", "build an array, or call a function per item"},
	ast.KindDecorator:         {"a decorator", "write the behavior where it applies; 0.1 doesn't rewrite classes at runtime"},
	ast.KindWithStatement:     {"with", "name the object you mean"},
	ast.KindDeleteExpression:  {"delete", "an object's shape is fixed; use a Map for keys that come and go"},
	ast.KindIndexSignature:    {"an index signature", "use a Map, which keeps keys in the order they were added"},
	ast.KindExportAssignment:  {"export default", "export by name: one name for one thing"},
}

// refusedOperators are binary operators 0.1 refuses.
var refusedOperators = map[ast.Kind]refusal{
	ast.KindEqualsEqualsToken:      {"==", "use ===, which doesn't coerce"},
	ast.KindExclamationEqualsToken: {"!=", "use !==, which doesn't coerce"},
}

// refuse walks a module for what 0.1 refuses and returns the first, with where it is and the fix.
func (l *lowering) refuse(module *ast.SourceFile) error {
	// Use the parser's directives, which also recognize the block forms honored by the checker.
	// Text in a string or a prose comment never enters this list.
	if len(module.CommentDirectives) > 0 {
		directive := module.CommentDirectives[0]
		name := "@ts-ignore"
		if directive.Kind == ast.CommentDirectiveKindExpectError {
			name = "@ts-expect-error"
		}
		line, column := scanner.GetLineAndCharacterOfPosition(module, directive.Loc.Pos())
		return &Refused{Where: fmt.Sprintf("%s:%d:%d", l.program.FileName(module), line+1, column+1), What: name + " suppression directive", Fix: "remove it and fix the type error"}
	}
	// File-level checking pragmas are separate from line-suppression directives. Use every
	// parsed pragma, including one overridden by a later pragma, rather than just CheckJsDirective.
	for _, pragma := range module.Pragmas {
		if pragma.Name == "ts-nocheck" || pragma.Name == "ts-check" {
			line, column := scanner.GetLineAndCharacterOfPosition(module, pragma.Pos())
			return &Refused{Where: fmt.Sprintf("%s:%d:%d", l.program.FileName(module), line+1, column+1), What: "@" + pragma.Name + " checking pragma", Fix: "remove it and fix any type errors"}
		}
	}
	// Validate arguments before visiting their annotations, so a failed contract
	// names the actual argument and parameter even for an inline arrow.
	var contractError error
	var contracts ast.Visitor
	contracts = func(node *ast.Node) bool {
		if contractError != nil {
			return true
		}
		if node.Kind == ast.KindCallExpression {
			contractError = l.predicateArguments(node)
		}
		if contractError == nil {
			node.ForEachChild(contracts)
		}
		return contractError != nil
	}
	module.AsNode().ForEachChild(contracts)
	if contractError != nil {
		return contractError
	}
	var found error
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if found != nil {
			return true
		}
		if branch := l.literalCallableBranch(node); branch != nil {
			return visit(branch)
		}
		if node.Kind == ast.KindTypePredicate {
			found = l.predicateRefusal(node)
			return found != nil
		}
		if err := l.enumerationIndexedWriteRefusal(node); err != nil {
			found = err
			return true
		}
		if err := l.enumerationDescriptorRefusal(node); err != nil {
			found = err
			return true
		}
		if err := l.nodeLibraryRefusal(node); err != nil {
			found = err
			return true
		}
		if refused, isRefused := refusals[node.Kind]; isRefused && !(node.Kind == ast.KindIndexSignature && l.enumerationIndexSignature(node)) && (node.Kind != ast.KindNonNullExpression || !l.checkedAssertionSource(node)) {
			found = &Refused{Where: l.program.Where(node), What: refused.what, Fix: refused.fix}
			return true
		}
		if err := l.typedArrayUnsupported(node); err != nil {
			found = err
			return true
		}
		if node.Kind == ast.KindCallExpression {
			if err := l.predicateArguments(node); err != nil {
				found = err
				return true
			}
		}
		if err := l.enumRefusal(node); err != nil {
			found = err
			return true
		}
		checkedCast := false
		if node.Kind == ast.KindAsExpression {
			proof, err := l.castProof(node)
			if err != nil {
				found = err
				return true
			}
			checkedCast = proof.interfaceView || len(proof.allowed) > 0 || len(proof.classes) > 0
		}
		if err := l.namespaceRefusal(node); err != nil {
			found = err
			return true
		}
		if node.Kind == ast.KindBinaryExpression {
			if refused, isRefused := refusedOperators[node.AsBinaryExpression().OperatorToken.Kind]; isRefused {
				found = &Refused{Where: l.program.Where(node.AsBinaryExpression().OperatorToken), What: refused.what, Fix: refused.fix}
				return true
			}
		}
		generator := false
		switch node.Kind {
		case ast.KindFunctionDeclaration:
			generator = node.AsFunctionDeclaration().AsteriskToken != nil
		case ast.KindFunctionExpression:
			generator = node.AsFunctionExpression().AsteriskToken != nil
		case ast.KindMethodDeclaration:
			generator = node.AsMethodDeclaration().AsteriskToken != nil
		}
		if generator {
			found = &Refused{Where: l.program.Where(node), What: "a generator function", Fix: "use an explicit iterator object; suspended frames need ownership and cancellation rules before generators can be compiled without a collector (docs/user-iterators.md)"}
			return true
		}
		if ast.IsFunctionLike(node) && ast.HasSyntacticModifier(node, ast.ModifierFlagsAsync) {
			found = &Refused{Where: l.program.Where(node), What: "an async function", Fix: "0.1 has no async; it arrives with the concurrency model"}
			return true
		}
		if node.Kind == ast.KindIdentifier && node.Text() == "arguments" {
			// JavaScript's arguments object, not a variable the program named arguments.
			if symbol := l.checker.GetSymbolAtLocation(node); symbol != nil && len(symbol.Declarations) == 0 {
				if err := l.argumentsRefusal(node); err != nil {
					found = err
					return true
				}
			}
		}
		if (node.Kind == ast.KindPropertyAccessExpression || node.Kind == ast.KindElementAccessExpression) && !called(node) {
			if err := l.nodeBufferUnsupportedUse(node); err != nil {
				found = err
				return true
			}
		}
		if node.Kind == ast.KindShorthandPropertyAssignment {
			if symbol := l.checker.GetShorthandAssignmentValueSymbol(node); symbol != nil && len(symbol.Declarations) == 1 && symbol.Declarations[0].Kind == ast.KindVariableDeclaration {
				if initializer := symbol.Declarations[0].AsVariableDeclaration().Initializer; initializer != nil {
					if _, known := l.libraryMethod(initializer, map[*ast.Symbol]bool{}); known {
						found = l.notYet(node, "a library method value outside a const alias (an object field erases its receiver and callable ABI); use an arrow")
						return true
					}
				}
			}
		}
		if node.Kind == ast.KindPropertyAccessExpression && !called(node) && !l.libraryNumberBoundMethod(node) && !l.stringMethodObservation(node) && !l.libraryArrayObservedMethod(node) && !l.libraryMethodReadAllowed(node) {
			// A method read as a value loses its object: this is undefined when it's called.
			access := node.AsPropertyAccessExpression()
			if access.Name().Text() == "isPrototypeOf" && l.libraryMember(node) {
				found = l.prototypeRead(node, "isPrototypeOf")
				return true
			}
			// Math.random has its own refusal, called or not.
			isRandom := l.isLibraryGlobal(access.Expression, "Math") && access.Name().Text() == "random"
			if symbol := l.checker.GetSymbolAtLocation(node); symbol != nil && symbol.Flags&ast.SymbolFlagsMethod != 0 && !isRandom {
				object := "its object"
				if ast.IsIdentifier(access.Expression) || access.Expression.Kind == ast.KindThisKeyword {
					object = scannedText(access.Expression)
				}
				parameters := "value"
				if signatures := l.checker.GetSignaturesOfType(l.checker.GetTypeOfSymbol(symbol), checker.SignatureKindCall); len(signatures) > 0 {
					names := []string{}
					for _, parameter := range signatures[0].Parameters() {
						names = append(names, parameter.Name)
					}
					parameters = strings.Join(names, ", ")
				}
				found = &Refused{Where: l.program.Where(node), What: "a method read as a value (" + symbol.Name + " would lose its object, and this with it)", Fix: "call it in an arrow that keeps the object: (" + parameters + ") => " + object + "." + symbol.Name + "(" + parameters + ") (unbound-method)"}
				return true
			}
		}
		if node.Kind == ast.KindClassDeclaration {
			if err := l.checkOverrides(node, l.checker.GetTypeAtLocation(node.Name())); err != nil {
				found = err
				return true
			}
		}
		// Prefer the writable-slot explanation when both a mutable view and nominal ancestry fail.
		// A checked cast relates only members selected by its tag, not excluded source members.
		if !checkedCast {
			if err := l.refuseStringWidening(node); err != nil {
				found = err
				return true
			}
		}
		if err := l.refuseOptionalWidening(node); err != nil {
			found = err
			return true
		}
		if err := l.classViewRefusal(node); err != nil {
			found = err
			return true
		}
		node.ForEachChild(visit)
		return false
	}
	module.AsNode().ForEachChild(visit)
	return found
}

// called reports whether a property access is what a call calls, through any parentheses around it:
// a method called on its object, which keeps it.
func called(node *ast.Node) bool {
	for node.Parent != nil && node.Parent.Kind == ast.KindParenthesizedExpression {
		node = node.Parent
	}
	return node.Parent != nil && node.Parent.Kind == ast.KindCallExpression && node.Parent.AsCallExpression().Expression == node
}

// scannedText is an identifier's name, or this.
func scannedText(node *ast.Node) string {
	if node.Kind == ast.KindThisKeyword {
		return "this"
	}
	return node.Text()
}

regexp.go:
package lower

import (
	"fmt"
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"github.com/system-inc/adamic/internal/load"
	regex "github.com/system-inc/adamic/internal/regexp"
	"strings"
)

func (l *lowering) regexConstant(node *ast.Node) (ir.Expression, error) {
	pattern, flags := "", ""
	var evaluated []ir.Expression
	if node.Kind == ast.KindRegularExpressionLiteral {
		text := node.Text()
		end := strings.LastIndex(text, "/")
		if end <= 0 {
			return nil, l.notYet(node, "a malformed regular expression literal")
		}
		pattern, flags = text[1:end], text[end+1:]
	} else {
		var args []*ast.Node
		if node.Kind == ast.KindNewExpression {
			if node.AsNewExpression().Arguments != nil {
				args = node.AsNewExpression().Arguments.Nodes
			}
		} else {
			args = node.AsCallExpression().Arguments.Nodes
		}
		if len(args) > 2 {
			return nil, l.notYet(node, "RegExp with more than two arguments")
		}
		if len(args) > 0 {
			var ok bool
			pattern, ok = l.constantPattern(args[0], 0)
			if !ok {
				return nil, l.notYet(args[0], "RegExp with a nonconstant pattern")
			}
		}
		if len(args) > 1 {
			var ok bool
			flags, ok = l.constantPattern(args[1], 0)
			if !ok {
				return nil, l.notYet(args[1], "RegExp with nonconstant flags")
			}
		}
		for _, arg := range args {
			value, err := l.expression(arg)
			if err != nil {
				return nil, err
			}
			evaluated = append(evaluated, value)
		}
	}
	program, err := regex.Compile(pattern, flags)
	if err != nil {
		return nil, fmt.Errorf("%s: invalid RegExp: %w", l.program.Where(node), err)
	}
	index := len(l.result.Regexps)
	declarations, err := program.NativeDeclarations(fmt.Sprintf("adamic_regex_%d", index))
	if err != nil {
		return nil, l.notYet(node, err.Error())
	}
	l.result.Regexps = append(l.result.Regexps, ir.RegExpProgram{Pattern: pattern, Flags: flags, Declarations: declarations})
	source := escapeRegexSource(pattern, flags)
	ordered := ""
	for _, flag := range "dgimsuvy" {
		if strings.ContainsRune(flags, flag) {
			ordered += string(flag)
		}
	}
	return ir.RegExpNew{Index: index, Source: l.constant(source), Flags: l.constant(ordered), Arguments: evaluated}, nil
}
func (l *lowering) constantPattern(node *ast.Node, depth int) (string, bool) {
	if depth > 32 {
		return "", false
	}
	node = ast.SkipParentheses(node)
	switch node.Kind {
	case ast.KindStringLiteral, ast.KindNoSubstitutionTemplateLiteral:
		return node.Text(), true
	case ast.KindIdentifier:
		if l.checker.GetTypeAtLocation(node).Flags()&checker.TypeFlagsUndefined != 0 {
			return "", true
		}
		symbol := l.symbol(node)
		if symbol != nil && len(symbol.Declarations) == 1 {
			declaration := symbol.Declarations[0]
			if declaration.Kind == ast.KindVariableDeclaration && declaration.Parent != nil && declaration.Parent.Flags&ast.NodeFlagsConst != 0 && declaration.AsVariableDeclaration().Initializer != nil {
				return l.constantPattern(declaration.AsVariableDeclaration().Initializer, depth+1)
			}
		}
	case ast.KindBinaryExpression:
		b := node.AsBinaryExpression()
		if b.OperatorToken.Kind == ast.KindPlusToken {
			a, ok := l.constantPattern(b.Left, depth+1)
			c, other := l.constantPattern(b.Right, depth+1)
			return joinPatternStrings(a, c), ok && other
		}
	}
	return "", false
}

// joinPatternStrings mirrors adamic_string_put: canonical WTF-8 strings can
// form a new surrogate pair only at the concatenation boundary.
func joinPatternStrings(left, right string) string {
	if len(left) < 3 || len(right) < 3 {
		return left + right
	}
	high, low := left[len(left)-3:], right[:3]
	if high[0] != 0xed || high[1] < 0xa0 || high[1] > 0xaf || high[2] < 0x80 || high[2] > 0xbf ||
		low[0] != 0xed || low[1] < 0xb0 || low[1] > 0xbf || low[2] < 0x80 || low[2] > 0xbf {
		return left + right
	}
	highUnit := rune(0xd000) | rune(high[1]&0x3f)<<6 | rune(high[2]&0x3f)
	lowUnit := rune(0xd000) | rune(low[1]&0x3f)<<6 | rune(low[2]&0x3f)
	point := 0x10000 + ((highUnit - 0xd800) << 10) + (lowUnit - 0xdc00)
	return left[:len(left)-3] + string(point) + right[3:]
}

func (l *lowering) regexBuiltin(node *ast.Node) (ir.Expression, bool, error) {
	callee := ast.SkipParentheses(node.AsCallExpression().Expression)
	if l.isLibraryGlobal(callee, "RegExp") {
		value, err := l.regexConstant(node)
		return value, true, err
	}
	if callee.Kind != ast.KindPropertyAccessExpression {
		return nil, false, nil
	}
	receiver := callee.AsPropertyAccessExpression().Expression
	name := callee.Name().Text()
	proven := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(receiver))
	args := node.AsCallExpression().Arguments.Nodes
	method := name
	result := ir.Type(0)
	switch {
	case l.isLibraryType(proven, "RegExp"):
		if name == "test" {
			result = ir.Boolean
		} else if name == "exec" {
			result = ir.Array
		} else {
			return nil, true, l.notYet(node, "RegExp."+name)
		}
		if len(args) != 1 {
			return nil, true, l.notYet(node, "RegExp."+name+" without exactly one string")
		}
	case l.isLibraryType(proven, "RegExpStringIterator"):
		if name != "next" || len(args) != 0 {
			return nil, true, l.notYet(node, "RegExp iterator."+name)
		}
		method = "next"
		result = ir.Object
	default:
		of, _ := l.representation(proven)
		if of != ir.String || len(args) == 0 || !l.isLibraryType(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(args[0])), "RegExp") {
			return nil, false, nil
		}
		switch name {
		case "match", "split":
			result = ir.Array
		case "matchAll":
			result = ir.Object
		case "search":
			result = ir.Number
		case "replace", "replaceAll":
			result = ir.String
		default:
			return nil, true, l.notYet(node, "String."+name+" with a RegExp")
		}
	}
	value, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	if callee.AsPropertyAccessExpression().QuestionDotToken != nil {
		return nil, true, l.notYet(node, "an optional RegExp call")
	}
	var arguments []ir.Expression
	for _, arg := range args {
		v, e := l.expression(arg)
		if e != nil {
			return nil, true, e
		}
		arguments = append(arguments, v)
	}
	if (name == "exec" || name == "test") && arguments[0].Type() != ir.String {
		return nil, true, l.notYet(node, "RegExp input other than a string")
	}
	if name == "replace" || name == "replaceAll" {
		if len(arguments) == 2 && arguments[1].Type() == ir.Closure {
			return l.regexReplacement(node, value, arguments, name, args[1])
		}
		if len(arguments) != 2 || arguments[1].Type() != ir.String {
			return nil, true, l.notYet(node, "regex replacement other than a string")
		}
	}
	if name == "split" {
		if len(arguments) == 1 {
			arguments = append(arguments, ir.NumberConstant{Value: 4294967295})
		}
		if len(arguments) == 2 {
			if _, undefined := arguments[1].(ir.Undefined); undefined {
				arguments[1] = ir.NumberConstant{Value: 4294967295}
			}
			if arguments[1].Type() == ir.MaybeNumber {
				arguments[1] = ir.Coalesce{Value: arguments[1], Fallback: ir.NumberConstant{Value: 4294967295}, Of: ir.Number}
			}
		}
		if len(arguments) != 2 || arguments[1].Type() != ir.Number {
			return nil, true, l.notYet(node, "regex split limit other than a number")
		}
	}
	return ir.RegExpCall{Value: value, Arguments: arguments, Method: method, Returns: result}, true, nil
}

// EscapeRegExpPattern preserves escapes already present in the pattern.
func escapeRegexSource(pattern, flags string) string {
	if pattern == "" {
		return "(?:)"
	}
	var result strings.Builder
	escaped, sets := false, strings.Contains(flags, "v")
	depth := 0
	// Scan bytes so WTF-8 lone surrogates retain their exact code units.
	for at := 0; at < len(pattern); at++ {
		c := pattern[at]
		escape := ""
		switch c {
		case '\n':
			escape = "n"
		case '\r':
			escape = "r"
		case 0xe2:
			if at+2 < len(pattern) && pattern[at+1] == 0x80 {
				if pattern[at+2] == 0xa8 {
					escape = "u2028"
					at += 2
				}
				if escape == "" && pattern[at+2] == 0xa9 {
					escape = "u2029"
					at += 2
				}
			}
		}
		if escape != "" {
			if !escaped {
				result.WriteByte('\\')
			}
			result.WriteString(escape)
			escaped = false
			continue
		}
		if !escaped {
			if c == '[' && (sets || depth == 0) {
				depth++
			}
			if c == ']' && depth > 0 {
				depth--
			}
		}
		if c == '/' && !escaped && depth == 0 {
			result.WriteByte('\\')
		}
		result.WriteByte(c)
		if c == '\\' {
			escaped = !escaped
		} else {
			escaped = false
		}
	}
	return result.String()
}

func (l *lowering) regexGroups(node *ast.Node) bool {
	proven := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(node))
	for _, info := range l.checker.GetIndexInfosOfType(proven) {
		if declaration := info.Declaration(); declaration != nil {
			file := ast.GetSourceFileOfNode(declaration)
			if load.IsLibrary(file) && strings.Contains(file.AsSourceFile().FileName().AsString(), ".regexp.") {
				return true
			}
		}
	}
	return false
}

func (l *lowering) regexUnsupportedUse(node *ast.Node) error {
	proven := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(node))
	if !l.isLibraryType(proven, "RegExp", "RegExpStringIterator") && !l.regexGroups(node) {
		return nil
	}
	parent := node.Parent
	if parent == nil {
		return nil
	}
	if parent.Kind == ast.KindSpreadAssignment {
		return l.notYet(parent, "spreading a RegExp or its iterator")
	}
	if parent.Kind == ast.KindPropertyAccessExpression && parent.Parent != nil && parent.Parent.Kind == ast.KindBinaryExpression {
		assignment := parent.Parent.AsBinaryExpression()
		if assignment.Left == parent && assignment.OperatorToken.Kind == ast.KindEqualsToken && (parent.Name().Text() != "lastIndex" || l.regexGroups(node)) {
			return l.notYet(parent, "overriding a RegExp or iterator property")
		}
	}
	return nil
}

// These library fields have explicit native storage. Other library members remain inherited
// prototype reads, so recognizing regex metadata must not admit arbitrary own-field loads.
func (l *lowering) regexRuntimeProperty(receiver *ast.Node, name string) bool {
	if l.regexGroups(receiver) {
		// Named-group dictionaries have dynamic own keys; regexGroups lowering checks their value type.
		return true
	}
	proven := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(receiver))
	switch {
	case l.isLibraryType(proven, "RegExp"):
		switch name {
		case "lastIndex", "source", "flags", "global", "ignoreCase", "multiline", "unicode", "sticky", "hasIndices", "unicodeSets", "dotAll":
			return true
		}
	case l.isLibraryType(proven, "RegExpExecArray", "RegExpMatchArray", "RegExpIndicesArray"):
		return name == "index" || name == "input" || name == "groups" || name == "indices"
	}
	if name != "done" && name != "value" {
		return false
	}
	members := []*checker.Type{proven}
	if proven.Flags()&checker.TypeFlagsUnion != 0 {
		members = proven.Types()
	}
	for _, member := range members {
		if !l.isLibraryType(member, "IteratorYieldResult", "IteratorReturnResult") {
			return false
		}
	}
	return true
}

set.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// A Set is held as a Map whose values aren't used (ir.Map), which is what JavaScript's Set is: the
// same insertion order, the same SameValueZero keys, the same rules for what an iteration sees. What
// tells them apart is the checker's type, so every Set operation is found here, by it, before the
// Map ones. Anything Map-shaped asked of a Set (its key and value types) finds one type argument, not
// two, and stops as not yet.

// isSet reports whether a node is one of the library's Sets.
func (l *lowering) isSet(node *ast.Node) bool {
	return l.isLibraryType(l.checker.GetTypeAtLocation(node), "Set", "ReadonlySet")
}

// setElement is the representation of a Set's elements, strings or numbers in 0.2.
func (l *lowering) setElement(node *ast.Node) (ir.Type, error) {
	arguments := l.typeArguments(l.checker.GetTypeAtLocation(node))
	if len(arguments) != 1 {
		return 0, l.notYet(node, "a Set whose element type isn't known")
	}
	element, isKnown := l.representation(arguments[0])
	if !isKnown || !keyable(element) {
		return 0, l.notYet(node, "a Set of "+l.checker.TypeToString(arguments[0])+" (a Set holds strings, numbers, booleans, objects, arrays, maps or functions so far)")
	}
	return element, nil
}

// newSet lowers new Set() and new Set(array).
func (l *lowering) newSet(node *ast.Node) (ir.Expression, error) {
	element, err := l.setElement(node)
	if err != nil {
		return nil, err
	}
	lowered := ir.SetNew{Element: element}
	arguments := node.AsNewExpression().Arguments
	if arguments == nil || len(arguments.Nodes) == 0 {
		return lowered, nil
	}
	if len(arguments.Nodes) != 1 {
		return nil, l.notYet(node, "new Set with more than one argument")
	}
	if ast.SkipParentheses(arguments.Nodes[0]).Kind == ast.KindArrayLiteralExpression {
		if values, known, err := l.librarySetLiteral(arguments.Nodes[0], element); known {
			lowered.Values = values
			return lowered, err
		}
	}
	if l.libraryEmptyCollectionArgument(arguments.Nodes[0]) {
		return lowered, nil
	}
	// From anything iterable: an array, a string's code points, a Set, a Map's entries, or what keys()
	// and values() give (collections.go).
	values, from, err := l.iterated(arguments.Nodes[0])
	if err != nil {
		return nil, err
	}
	if from == ir.Number && element == ir.MaybeNumber {
		values = l.libraryOptionalNumbers(arguments.Nodes[0], values)
		from = element
	}
	if from != element {
		return nil, l.notYet(arguments.Nodes[0], "new Set from elements held otherwise than the Set's")
	}
	lowered.Values = values
	return lowered, nil
}

// setMethod lowers set.add, set.has and set.delete. isBuiltin is false for any other method, which
// is left to be refused as a call stage 0 doesn't know.
func (l *lowering) setMethod(node *ast.Node, receiver *ast.Node, name string) (ir.Expression, bool, error) {
	if lowered, known, err := l.librarySetMethod(node, receiver, name); known {
		return lowered, true, err
	}
	if name == "clear" || name == "forEach" {
		return l.clearOrVisit(node, receiver, name, true)
	}
	if name != "add" && name != "has" && name != "delete" {
		return nil, false, nil
	}
	element, err := l.setElement(receiver)
	if err != nil {
		return nil, true, err
	}
	set, err := l.expression(receiver)
	if err != nil {
		return nil, true, err
	}
	arguments := node.AsCallExpression().Arguments.Nodes
	if len(arguments) != 1 {
		return nil, true, l.notYet(node, "set."+name+" with other than one value")
	}
	value, err := l.expression(arguments[0])
	if err != nil {
		return nil, true, err
	}
	// set.has(undefined), written out, which the checker allows only where the elements may be
	// undefined: a reference's undefined is its null one, which the set holds as any element.
	_, isUndefined := value.(ir.Undefined)
	if !isUndefined || !element.IsReference() {
		if value = fit(value, element); value.Type() != element {
			return nil, true, l.notYet(arguments[0], "set."+name+" with a value of another type than the elements")
		}
	}
	switch name {
	case "add":
		return ir.SetAdd{Set: set, Value: value, Element: element, Site: l.writeSite(receiver)}, true, nil
	case "has":
		return ir.MapHas{Map: set, Key: value, KeyType: element}, true, nil
	}
	return ir.MapDelete{Map: set, Key: value, KeyType: element}, true, nil
}

// forOfSet lowers for (const element of set), and of set.keys() and set.values(), which give the
// same elements. Its steps are a Map's keys.
func (l *lowering) forOfSet(node *ast.Node, iterable ir.Expression, iterated *ast.Node, part string, name *ast.Node) ([]ir.Statement, error) {
	element, err := l.setElement(iterated)
	if err != nil {
		return nil, err
	}
	lowered := ir.ForOf{Iterable: iterable, MapPart: "keys", Key: element, Value: ir.Number}
	// Each entry is [element, element]: the first name bound takes the element, and any other is
	// declared from it, each its own variable.
	var others []ir.Statement
	switch {
	case part == "entries" && name.Kind == ast.KindArrayBindingPattern:
		bound := false
		elements := name.AsBindingPattern().Elements.Nodes
		if len(elements) > 2 {
			return nil, l.notYet(name, "destructuring more than a Set entry's two elements")
		}
		for _, binding := range elements {
			// A hole, [, second], is a binding element with no name.
			if binding.Kind == ast.KindOmittedExpression || binding.Name() == nil {
				continue
			}
			declared := binding.AsBindingElement()
			if !ast.IsIdentifier(binding.Name()) || declared.Initializer != nil || declared.DotDotDotToken != nil {
				return nil, l.notYet(binding, "a destructured name that isn't plain")
			}
			local, err := l.declareLocal(binding.Name())
			if err != nil {
				return nil, err
			}
			if !bound {
				lowered.Local, bound = local, true
				continue
			}
			others = append(others, ir.Declare{Local: local, Value: ir.Read{Local: lowered.Local, Of: element}})
		}
		if !bound {
			return nil, l.notYet(name, "a Set entry destructured into no names")
		}
	case part != "entries" && ast.IsIdentifier(name):
		if lowered.Local, err = l.declareLocal(name); err != nil {
			return nil, err
		}
	default:
		return nil, l.notYet(name, "for...of over a Set's "+part+" into this name")
	}
	body, err := l.statement(node.AsForInOrOfStatement().Statement)
	if err != nil {
		return nil, err
	}
	lowered.Body = append(others, body...)
	return []ir.Statement{lowered}, nil
}

shape_flow.go:
package lower

import (
	"reflect"
	"sort"
	"strconv"

	"github.com/system-inc/adamic/internal/ir"
)

// ReachingAllocations queries the shared graph without selecting graph ownership.
// Unknown frontiers retain checks. Joined assignments, returns and arguments use
// the same edges as the graph-regions analysis.
func (graph *allocationFlowGraph) ReachingAllocations(expression ir.Expression) ir.AllocationSet {
	return graph.reachingAllocations(expression, true, 0)
}

func (graph *allocationFlowGraph) reachingAllocations(expression ir.Expression, project bool, depth int) (result ir.AllocationSet) {
	if read, ok := expression.(ir.Read); ok && project {
		if graph.projectionReads == nil {
			graph.projectionReads = map[int]ir.AllocationSet{}
			graph.projectionBusy = map[int]bool{}
		}
		if cached, ok := graph.projectionReads[read.Local]; ok {
			return cached
		}
		if graph.projectionBusy[read.Local] {
			return ir.AllocationSet{Unknown: true, Reasons: []string{"recursive projection receiver not certified"}}
		}
		graph.projectionBusy[read.Local] = true
		defer func() { delete(graph.projectionBusy, read.Local); graph.projectionReads[read.Local] = result }()
	}
	result = ir.AllocationSet{}
	sites, visited, reasons := map[int]bool{}, map[int]bool{}, map[string]bool{}
	queue := []int{}
	demand := func(node int) {
		if !visited[node] {
			visited[node] = true
			queue = append(queue, node)
		}
	}
	unknown := func(reason string) { result.Unknown = true; reasons[reason] = true }
	var follow func(ir.Expression, int)
	follow = func(value ir.Expression, level int) {
		if project {
			sources, reasons, recognized := graph.projectedSources(value, level)
			if recognized {
				for _, reason := range reasons {
					unknown(reason)
				}
				for _, source := range sources {
					follow(source, level+1)
				}
				return
			}
			switch wrapper := value.(type) {
			case ir.Conditional:
				follow(wrapper.WhenTrue, level)
				follow(wrapper.WhenNot, level)
				return
			case ir.Box:
				follow(wrapper.Value, level)
				return
			case ir.Narrow:
				follow(wrapper.Value, level)
				return
			case ir.Unwrap:
				follow(wrapper.Value, level)
				return
			case ir.CheckedCast:
				follow(wrapper.Value, level)
				return
			}
		}
		graph.follow(value, func(site int) { sites[site] = true }, demand, unknown)
	}
	follow(expression, depth)
	for len(queue) != 0 {
		node := queue[len(queue)-1]
		queue = queue[:len(queue)-1]
		if graph.unknownParameters[node] {
			unknown("parameter may receive untracked or omitted arguments")
		}
		sources := graph.sources[node]
		if len(sources) == 0 {
			unknown("local or result has no tracked producer")
		}
		for _, source := range sources {
			follow(source, depth)
		}
	}
	if len(sites) == 0 {
		unknown("no reaching allocation established")
	}
	for site := range sites {
		result.Sites = append(result.Sites, site)
	}
	for reason := range reasons {
		result.Reasons = append(result.Reasons, reason)
	}
	sort.Ints(result.Sites)
	sort.Strings(result.Reasons)
	return result
}

// rewriteShapeStatements preserves the IR tree's containers and rewrites only
// interface-held nodes, so metadata never becomes an executable expression.
func rewriteShapeStatements(body []ir.Statement, rewrite func(any) any) []ir.Statement {
	var transform func(reflect.Value) reflect.Value
	transform = func(value reflect.Value) reflect.Value {
		switch value.Kind() {
		case reflect.Interface:
			if value.IsNil() {
				return value
			}
			mapped := transform(value.Elem())
			result := reflect.New(value.Type()).Elem()
			result.Set(reflect.ValueOf(rewrite(mapped.Interface())))
			return result
		case reflect.Struct:
			result := reflect.New(value.Type()).Elem()
			for i := 0; i < value.NumField(); i++ {
				result.Field(i).Set(transform(value.Field(i)))
			}
			return result
		case reflect.Slice:
			if value.IsNil() {
				return value
			}
			result := reflect.MakeSlice(value.Type(), value.Len(), value.Len())
			for i := 0; i < value.Len(); i++ {
				result.Index(i).Set(transform(value.Index(i)))
			}
			return result
		default:
			return value
		}
	}
	return transform(reflect.ValueOf(body)).Interface().([]ir.Statement)
}

// Projection is queried only by shape proofs. Graph-regions traversal stays unchanged.
type allocationProjection struct {
	records       map[int]ir.ObjectLiteral
	arrays        map[int]ir.ArrayLiteral
	stores        map[int]map[string][]ir.Expression
	opaque        map[string]bool
	opaqueSources map[string][]ir.Expression
	arrayMutation bool
	opaqueCalls   bool
}

func (graph *allocationFlowGraph) projectionIndex() *allocationProjection {
	if graph.projection != nil {
		return graph.projection
	}
	index := &allocationProjection{records: map[int]ir.ObjectLiteral{}, arrays: map[int]ir.ArrayLiteral{}, stores: map[int]map[string][]ir.Expression{}, opaque: map[string]bool{}, opaqueSources: map[string][]ir.Expression{}}
	graph.projection = index
	stores := []ir.SetProperty{}
	collect := func(node any) bool {
		switch value := node.(type) {
		case ir.ObjectLiteral:
			if len(value.GraphTypes) > 0 {
				index.records[value.GraphTypes[len(value.GraphTypes)-1]] = value
			}
		case ir.ArrayLiteral:
			if len(value.GraphTypes) > 0 {
				index.arrays[value.GraphTypes[len(value.GraphTypes)-1]] = value
			}
		case ir.SetProperty:
			stores = append(stores, value)
		case ir.SetIndex, ir.ArrayPush, ir.ArraySplice, ir.ArrayPop:
			index.arrayMutation = true
		case ir.CallClosure, ir.ObjectCall:
			index.opaqueCalls = true
		}
		return true
	}
	walk(graph.program.Main, collect)
	for _, function := range graph.program.Functions {
		walk(function.Body, collect)
	}
	for _, store := range stores {
		receiver := graph.reachingAllocations(store.Object, false, 0)
		if receiver.Unknown || store.Uninitialized {
			index.opaque[store.Name] = true
			index.opaqueSources[store.Name] = append(index.opaqueSources[store.Name], store.Object, store.Value)
		}
		for _, site := range receiver.Sites {
			if index.stores[site] == nil {
				index.stores[site] = map[string][]ir.Expression{}
			}
			index.stores[site][store.Name] = append(index.stores[site][store.Name], store.Value)
		}
	}
	return index
}

// projectedSources joins initial fields and all visible stores across all paths.
// An opaque receiver can alias any allocation; its field name stays unknown.
func (graph *allocationFlowGraph) projectedSources(expression ir.Expression, depth int) ([]ir.Expression, []string, bool) {
	var receiver ir.Expression
	name := ""
	array := false
	switch value := expression.(type) {
	case ir.Property:
		receiver, name = value.Object, value.Name
	case ir.ArrayIndex:
		receiver = value.Array
		array = true
		key, ok := value.Index.(ir.NumberConstant)
		if !ok || key.Value < 0 || key.Value != float64(int(key.Value)) || value.Relative {
			return nil, []string{"dynamic or relative element key not certified"}, true
		}
		name = strconv.Itoa(int(key.Value))
	default:
		return nil, nil, false
	}
	if depth >= 32 {
		return nil, []string{"recursive projection depth not certified"}, true
	}
	index := graph.projectionIndex()
	sources := []ir.Expression{}
	reasons := []string{}
	if index.opaqueCalls {
		reasons = append(reasons, "opaque call may mutate projected fields")
	}
	if index.opaque[name] {
		reasons = append(reasons, "field store has opaque receiver or clears readiness: "+name)
	}
	if array && index.arrayMutation {
		reasons = append(reasons, "array mutation prevents element certificate")
	}
	bases := graph.reachingAllocations(receiver, true, depth+1)
	reasons = append(reasons, bases.Reasons...)
	for _, site := range bases.Sites {
		found := false
		if literal, ok := index.records[site]; ok {
			if literal.Spread != nil {
				reasons = append(reasons, "spread field projection not certified")
			}
			for _, field := range literal.Fields {
				if field.Name == name {
					sources = append(sources, field.Value)
					found = true
				}
			}
		}
		if literal, ok := index.arrays[site]; ok && array {
			key, _ := strconv.Atoi(name)
			if len(literal.Spread) > 0 {
				reasons = append(reasons, "spread element projection not certified")
			}
			if key < len(literal.Elements) {
				sources = append(sources, literal.Elements[key])
				found = true
			}
		}
		if !found {
			reasons = append(reasons, "projected field absent or allocation not modeled: "+name)
		}
		sources = append(sources, index.stores[site][name]...)
	}
	return sources, reasons, true
}

statements.go:
// Functions and declarations moved unchanged from lower.go.
package lower

import (
	"errors"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// statements lowers a list of statements.
func (l *lowering) statements(nodes []*ast.Node) ([]ir.Statement, error) {
	lowered, err := l.nestedDeclarations(nodes)
	if err != nil {
		return nil, err
	}
	for _, node := range nodes {
		statements, err := l.statement(node)
		if err != nil {
			return nil, err
		}
		lowered = append(lowered, statements...)
	}
	return lowered, nil
}

// statement lowers one statement to none, one or several.
func (l *lowering) statement(node *ast.Node) ([]ir.Statement, error) {
	switch node.Kind {
	case ast.KindModuleDeclaration:
		return l.namespaceBody(node)
	case ast.KindDebuggerStatement:
		// Preserve it for JavaScript; native builds have no attached debugger.
		return []ir.Statement{ir.Debugger{}}, nil
	case ast.KindInterfaceDeclaration, ast.KindTypeAliasDeclaration, ast.KindEmptyStatement:
		// Types erase to nothing, and so does an empty statement.
		return nil, nil
	case ast.KindImportDeclaration:
		// What an import brings in is resolved through the checker at each use, and the module it
		// names runs first (moduleOrder).
		return nil, nil
	case ast.KindExportDeclaration:
		if clause := node.AsExportDeclaration().ExportClause; clause == nil || clause.Kind == ast.KindNamedExports {
			// The checker resolves each live binding, and moduleOrder runs re-export dependencies.
			return nil, nil
		}
		return nil, &Refused{Where: l.program.Where(node), What: "a namespace export", Fix: "export named bindings"}
	case ast.KindExportAssignment:
		return nil, &Refused{Where: l.program.Where(node), What: describe(node), Fix: "export named bindings"}
	case ast.KindFunctionDeclaration:
		if node.Parent != nil && (node.Parent.Kind == ast.KindCaseClause || node.Parent.Kind == ast.KindDefaultClause) {
			// Switch functions are initialized at entry, before dispatch.
			return nil, nil
		}
		if l.function != nil {
			if local, ok := l.locals[l.symbol(node.Name())]; ok && l.result.Locals[local].NestedFunction != 0 {
				return nil, nil
			}
			return nil, l.notYet(node, "a block-scoped nested function declaration")
		}
		// Lowered already, by declareModule.
		return nil, nil
	case ast.KindEnumDeclaration:
		return l.enumDeclaration(node)
	case ast.KindClassDeclaration:
		if l.function != nil {
			return nil, l.notYet(node, "a class inside a function")
		}
		return l.staticDeclaration(node)
	case ast.KindReturnStatement:
		return l.returnStatement(node)
	case ast.KindExpressionStatement:
		return l.expressionStatement(node.AsExpressionStatement().Expression)
	case ast.KindVariableStatement:
		return l.variables(node.AsVariableStatement().DeclarationList)
	case ast.KindBlock:
		body, err := l.statements(node.AsBlock().Statements.Nodes)
		if err != nil {
			return nil, err
		}
		return []ir.Statement{ir.Block{Body: body}}, nil
	case ast.KindIfStatement:
		return l.ifStatement(node)
	case ast.KindForStatement:
		return l.forStatement(node)
	case ast.KindWhileStatement, ast.KindDoStatement:
		return l.whileStatement(node)
	case ast.KindForInStatement:
		return l.forIn(node)
	case ast.KindForOfStatement:
		if body, handled, err := l.typedArrayForOf(node); handled {
			return body, err
		}
		return l.forOf(node)
	case ast.KindSwitchStatement:
		return l.switchStatement(node)
	case ast.KindLabeledStatement:
		return l.labeled(node)
	case ast.KindBreakStatement, ast.KindContinueStatement:
		label := ""
		if node.Label() != nil {
			label = node.Label().Text()
		}
		if node.Kind == ast.KindBreakStatement {
			return []ir.Statement{ir.Break{Label: label}}, nil
		}
		return []ir.Statement{ir.Continue{Label: label}}, nil
	case ast.KindThrowStatement:
		return l.throwStatement(node)
	case ast.KindTryStatement:
		return l.tryStatement(node)
	}
	return nil, l.notYet(node, describe(node))
}

// expressionStatement lowers an expression used as a statement: a console call, an assignment, or
// ++ and --. Any other expression's value would be thrown away, and stage 0 doesn't lower that yet.
func (l *lowering) expressionStatement(expression *ast.Node) ([]ir.Statement, error) {
	expression = ast.SkipParentheses(expression)
	if statements, handled, err := l.conditionalSuper(expression); handled {
		return statements, err
	}
	switch expression.Kind {
	case ast.KindNonNullExpression, ast.KindVoidExpression:
		value, err := l.expression(expression)
		if err != nil {
			return nil, err
		}
		return []ir.Statement{ir.Evaluate{Value: value}}, nil
	case ast.KindCallExpression:
		if ast.SkipParentheses(expression.AsCallExpression().Expression).Kind == ast.KindSuperKeyword {
			return l.superStatement(expression)
		}
		if err := l.optionalCall(expression); err != nil {
			return nil, err
		}
		if l.isConsole(expression.AsCallExpression().Expression) {
			statement, err := l.console(expression)
			if err != nil {
				return nil, err
			}
			return []ir.Statement{statement}, nil
		}
		if l.isPreludeFunction(expression.AsCallExpression().Expression, "panic") {
			arguments := expression.AsCallExpression().Arguments.Nodes
			if len(arguments) != 1 {
				return nil, errors.New("lower: " + l.program.Where(expression) + ": panic takes one argument, and the checker let another count through")
			}
			message, err := l.expression(arguments[0])
			if err != nil {
				return nil, err
			}
			return []ir.Statement{ir.Panic{Message: message}}, nil
		}
		if value, handled, err := l.typedArrayExpression(expression); handled {
			if err != nil {
				return nil, err
			}
			return []ir.Statement{ir.Evaluate{Value: value}}, nil
		}
		// A builtin's result thrown away, like map.set(key, value) or array.push(value).
		if lowered, isBuiltin, err := l.builtin(expression); isBuiltin {
			if err != nil {
				return nil, err
			}
			return []ir.Statement{ir.Evaluate{Value: lowered}}, nil
		}
		// A call for its effects, void or not.
		call, err := l.callOrMethod(expression)
		if err != nil {
			return nil, err
		}
		return []ir.Statement{ir.Evaluate{Value: call}}, nil
	case ast.KindBinaryExpression:
		if expression.AsBinaryExpression().OperatorToken.Kind == ast.KindCommaToken {
			value, err := l.comma(expression)
			if err != nil {
				return nil, err
			}
			return []ir.Statement{ir.Evaluate{Value: value}}, nil
		}
		if logicalAssignment(expression.AsBinaryExpression().OperatorToken.Kind) {
			value, err := l.logicalAssignment(expression)
			if err != nil {
				return nil, err
			}
			return []ir.Statement{ir.Evaluate{Value: value}}, nil
		}
		return l.assignment(expression)
	case ast.KindPrefixUnaryExpression, ast.KindPostfixUnaryExpression:
		return l.increment(expression)
	}
	return nil, l.notYet(expression, describe(expression)+" as a statement")
}

// returnStatement lowers return, with or without a value.
func (l *lowering) returnStatement(node *ast.Node) ([]ir.Statement, error) {
	if l.function == nil {
		return nil, errors.New("lower: " + l.program.Where(node) + ": return outside a function, and the checker let it through")
	}
	expression := node.AsReturnStatement().Expression
	if expression == nil {
		returned := ir.Return{}
		if l.function.Returns != 0 {
			returned.Value = fit(ir.Undefined{}, l.function.Returns)
		}
		return []ir.Statement{returned}, nil
	}
	expression = ast.SkipParentheses(expression)
	if statements, handled, err := l.namespaceReturnAssignment(expression); handled {
		return statements, err
	}
	if expression.Kind == ast.KindBinaryExpression && expression.AsBinaryExpression().OperatorToken.Kind == ast.KindEqualsToken {
		return l.returnAssignment(expression)
	}
	if l.isPanicCall(expression) {
		// return panic('why'): panic never returns, so there is nothing to return, and it is the panic.
		return l.expressionStatement(expression)
	}
	// A generic return specialized to void still evaluates the call before returning.
	if l.function.Returns == 0 && expression.Kind == ast.KindCallExpression && l.concrete(l.checker.GetTypeAtLocation(expression)).Flags()&checker.TypeFlagsVoid != 0 {
		statements, err := l.expressionStatement(expression)
		if err != nil {
			return nil, err
		}
		return append(statements, ir.Return{}), nil
	}
	value, err := l.expression(expression)
	if err != nil {
		return nil, err
	}
	if l.function.Returns == 0 {
		return []ir.Statement{ir.Evaluate{Value: value}, ir.Return{}}, nil
	}
	return []ir.Statement{ir.Return{Value: fit(value, l.function.Returns)}}, nil
}

// returnAssignment preserves the right side's value, assigns once, then returns
// that same value. Reading the target again could observe another write.
func (l *lowering) returnAssignment(node *ast.Node) ([]ir.Statement, error) {
	statements, err := l.assignment(node)
	if err != nil {
		return nil, err
	}
	if len(statements) != 1 {
		return nil, l.notYet(node, "returning a destructuring assignment")
	}
	assignment, ok := statements[0].(ir.Assign)
	if !ok {
		return nil, l.notYet(node, "returning a property or element assignment")
	}
	held := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "assigned", Type: assignment.Value.Type(), Function: l.functionIndex})
	value := assignment.Value
	read := ir.Read{Local: held, Of: value.Type()}
	assignment.Value = read
	return []ir.Statement{ir.Declare{Local: held, Value: value}, assignment, ir.Return{Value: fit(read, l.function.Returns)}}, nil
}

string_substr.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// substr counts UTF-16 units from a relative start, with a length rather than an end.
// A helper receives each operand once in source order before normalization reads it again.
func (l *lowering) stringSubstr(node *ast.Node, value ir.Expression, written []*ast.Node) (ir.Expression, error) {
	if len(written) > 2 {
		return nil, l.notYet(node, "substr with extra arguments")
	}
	values := []ir.Expression{value}
	for _, argument := range written {
		lowered, err := l.expression(argument)
		if err != nil {
			return nil, err
		}
		if _, missing := lowered.(ir.Undefined); missing {
			lowered = fit(lowered, ir.MaybeNumber)
		}
		if lowered.Type() != ir.Number && lowered.Type() != ir.MaybeNumber {
			return nil, l.notYet(argument, "substr with a nonnumeric argument")
		}
		values = append(values, lowered)
	}
	function, reads := l.stringHelper("substr", values)
	length := ir.StringLength{Value: reads[0]}
	zero := ir.NumberConstant{Value: 0}
	argument := func(index int, fallback ir.Expression) ir.Expression {
		if index >= len(reads) {
			return fallback
		}
		value := reads[index]
		if value.Type() == ir.MaybeNumber {
			value = ir.Coalesce{Value: value, Fallback: fallback, Of: ir.Number}
		}
		return stringInteger(value)
	}
	position := argument(1, zero)
	start := ir.Conditional{
		Condition: ir.Binary{Operator: ir.Less, Left: position, Right: zero},
		WhenTrue:  ir.MathCall{Function: "max", Arguments: []ir.Expression{ir.Binary{Operator: ir.Add, Left: length, Right: position}, zero}},
		WhenNot:   ir.MathCall{Function: "min", Arguments: []ir.Expression{position, length}},
	}
	count := ir.MathCall{Function: "min", Arguments: []ir.Expression{
		ir.MathCall{Function: "max", Arguments: []ir.Expression{argument(2, length), zero}},
		ir.Binary{Operator: ir.Subtract, Left: length, Right: start},
	}}
	result := ir.StringCall{Method: "slice", Value: reads[0], Arguments: []ir.Expression{start, ir.Binary{Operator: ir.Add, Left: start, Right: count}}}
	l.result.Functions[function].Body = []ir.Statement{ir.Return{Value: result}}
	return ir.Call{Function: function, Arguments: values, Returns: ir.String}, nil
}

switch.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

type switchGroup struct {
	tests     []ir.Expression
	body      []ir.Statement
	isDefault bool
}

// switchBodyLeaves recognizes bodies that cannot reach a following group. Missing a form only
// selects the general lowering; it never removes a possible fallthrough edge.
func switchBodyLeaves(body []ir.Statement) bool {
	if len(body) == 0 {
		return false
	}
	switch statement := body[len(body)-1].(type) {
	case ir.Break, ir.Continue, ir.Return, ir.Throw, ir.Panic:
		return true
	case ir.Block:
		return switchBodyLeaves(statement.Body)
	case ir.If:
		return switchBodyLeaves(statement.Then) && switchBodyLeaves(statement.Else)
	case ir.Try:
		return (statement.HasFinally && switchBodyLeaves(statement.Finally)) ||
			(switchBodyLeaves(statement.Body) && (!statement.HasCatch || switchBodyLeaves(statement.Catch)))
	}
	return false
}

// fallthroughSwitch first chooses the entry group in source test order, with default only as a
// fallback. The entered body and every later body then run in one breakable switch, until an abrupt
// exit leaves it. Bodies are emitted once, so their locals, ownership and flow points are not cloned.
func (l *lowering) fallthroughSwitch(value ir.Expression, groups []switchGroup, unmatchedCheck ir.Statement) []ir.Statement {
	entry := len(l.result.Locals)
	l.result.Locals = append(l.result.Locals, ir.Local{Name: "switch_entry", Type: ir.Number, Function: l.functionIndex})
	dispatch := ir.Switch{Value: value}
	if unmatchedCheck != nil {
		// An open enum can reach a checker-never default only when no case matched.
		// Falling through from a matched case must still execute the default body.
		dispatch.Default = []ir.Statement{unmatchedCheck}
	}
	bodies := []ir.Statement{}
	for index, group := range groups {
		position := ir.NumberConstant{Value: float64(index)}
		choose := []ir.Statement{ir.Assign{Local: entry, Value: position}}
		if len(group.tests) > 0 {
			dispatch.Cases = append(dispatch.Cases, ir.Case{Tests: group.tests, Body: choose})
		}
		if group.isDefault {
			// Each branch owns its statement addresses, including instrumentation points.
			dispatch.Default = append(dispatch.Default, ir.Assign{Local: entry, Value: position})
		}
		if len(group.body) > 0 {
			bodies = append(bodies, ir.If{
				Condition: ir.Binary{Operator: ir.LessOrEqual, Left: ir.Read{Local: entry, Of: ir.Number}, Right: position},
				Then:      group.body,
			})
		}
	}
	return []ir.Statement{ir.Block{Body: []ir.Statement{
		ir.Declare{Local: entry, Value: ir.NumberConstant{Value: float64(len(groups))}},
		dispatch,
		ir.Switch{Value: ir.BooleanConstant{Value: true}, Default: bodies},
	}}}
}

// labeledBreak resolves the source label to a breakable depth. Dispatch switches introduced by
// fallthrough lowering finish before any source body, so they never change this depth.
func (l *lowering) labeledBreak(node *ast.Node) ([]ir.Statement, error) {
	depth := 0
	for parent := node.Parent; parent != nil; parent = parent.Parent {
		if parent.Kind != ast.KindSwitchStatement && !ast.IsIterationStatement(parent, false) {
			continue
		}
		for label := parent.Parent; label != nil && label.Kind == ast.KindLabeledStatement; label = label.Parent {
			if label.Label().Text() == node.Label().Text() {
				return []ir.Statement{ir.Break{Depth: depth}}, nil
			}
		}
		depth++
	}
	return nil, l.notYet(node, "a break to a label that is not a loop or switch")
}

switch_bindings.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/internal/ir"
)

// initializeLocal runs a lexical declaration. Switch bindings already have storage: writing the
// value initializes them only after the initializer has finished, including any calls it makes.
func (l *lowering) initializeLocal(local int, value ir.Expression) []ir.Statement {
	ready := l.result.Locals[local].Ready
	if ready == 0 {
		return []ir.Statement{ir.Declare{Local: local, Value: value}}
	}
	if value == nil {
		// No initializer still ends the dead zone. Storage already holds its zero representation.
		return []ir.Statement{ir.Assign{Local: ready - 1, Value: ir.BooleanConstant{Value: true}}}
	}
	return []ir.Statement{
		ir.Assign{Local: local, Value: value},
		ir.Assign{Local: ready - 1, Value: ir.BooleanConstant{Value: true}},
	}
}

// switchBindings creates the one lexical environment shared by every case. Every variable's
// storage and readiness cell exists before a function can capture it. Functions are hoisted and
// initialized at entry; let and const remain unready until execution reaches their declarations.
func (l *lowering) switchBindings(block *ast.Node) ([]ir.Statement, error) {
	var storage []ir.Statement
	var functions []*ast.Node
	var bind func(*ast.Node) error
	bind = func(name *ast.Node) error {
		if name.Kind == ast.KindArrayBindingPattern || name.Kind == ast.KindObjectBindingPattern {
			for _, element := range name.AsBindingPattern().Elements.Nodes {
				if !skipped(element) {
					if err := bind(element.Name()); err != nil {
						return err
					}
				}
			}
			return nil
		}
		local, err := l.declareLocal(name)
		if err != nil {
			return err
		}
		ready := len(l.result.Locals)
		l.result.Locals = append(l.result.Locals, ir.Local{Name: name.Text() + "_ready", Type: ir.Boolean, Function: l.functionIndex})
		l.result.Locals[local].Ready = ready + 1
		storage = append(storage, ir.Declare{Local: ready, Value: ir.BooleanConstant{Value: false}}, ir.Declare{Local: local})
		return nil
	}
	for _, clause := range block.AsCaseBlock().Clauses.Nodes {
		for _, statement := range clause.AsCaseOrDefaultClause().Statements.Nodes {
			switch statement.Kind {
			case ast.KindVariableStatement:
				for _, declaration := range statement.AsVariableStatement().DeclarationList.AsVariableDeclarationList().Declarations.Nodes {
					if err := bind(declaration.Name()); err != nil {
						return nil, err
					}
				}
			case ast.KindFunctionDeclaration:
				if err := bind(statement.Name()); err != nil {
					return nil, err
				}
				functions = append(functions, statement)
			}
		}
	}
	for _, declaration := range functions {
		value, err := l.functionExpression(declaration)
		if err != nil {
			return nil, err
		}
		local := l.locals[l.symbol(declaration.Name())]
		storage = append(storage, l.initializeLocal(local, value)...)
	}
	return storage, nil
}

tsgo.go:
package lower

import (
	"fmt"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/system-inc/adamic/bridge/tsgo/spec"
	"github.com/system-inc/adamic/internal/ir"
)

// tsgo lowers direct calls only. Library functions borrow their inputs, mutate no
// Adamic value, and return fresh results. Ordinary IR calls preserve evaluation
// order and reference ownership. The bodies describe those effects for the
// analyses; the opt-in native library renderer supplies their implementation.
func (l *lowering) tsgo(node *ast.Node) (ir.Expression, bool, error) {
	callee := node.AsCallExpression().Expression
	name := ""
	for _, candidate := range []string{"tsgoProgram", "tsgoQuery", "tsgoRelease", "tsgoTypeParts", "tsgoInspect"} {
		if l.isPreludeFunction(callee, candidate) {
			name = candidate
			break
		}
	}
	if name == "" {
		return nil, false, nil
	}
	if !l.program.TSGoEnabled() {
		return nil, true, &Refused{Where: l.program.Where(node), What: "an unlinked typescript-go library call", Fix: "build with --tsgo <checker archive>"}
	}
	arguments := []ir.Expression{}
	for _, argument := range node.AsCallExpression().Arguments.Nodes {
		value, err := l.expression(argument)
		if err != nil {
			return nil, true, err
		}
		arguments = append(arguments, value)
	}
	types := []ir.Type{ir.Number}
	returns := ir.Type(0)
	switch name {
	case "tsgoProgram":
		types, returns = []ir.Type{ir.String, ir.Array}, ir.Number
	case "tsgoInspect":
		types, returns = []ir.Type{ir.Number, ir.String, ir.Number, ir.Number, ir.String, ir.String}, ir.String
	case "tsgoTypeParts":
		types, returns = []ir.Type{ir.Number, ir.String, ir.Number, ir.Number, ir.String}, ir.String
	case "tsgoQuery":
		types, returns = []ir.Type{ir.Number, ir.String, ir.Number}, ir.Object
	}
	if len(arguments) != len(types) {
		return nil, true, fmt.Errorf("lower: %s: invalid %s argument count", l.program.Where(node), name)
	}
	for index, argument := range arguments {
		if argument.Type() != types[index] {
			return nil, true, fmt.Errorf("lower: %s: invalid %s argument type", l.program.Where(node), name)
		}
	}
	function := -1
	for index, declared := range l.result.Functions {
		if declared.Name == spec.Prefix+name {
			function = index
			break
		}
	}
	if function < 0 {
		function = len(l.result.Functions)
		declared := ir.Function{Name: spec.Prefix + name, Returns: returns}
		for index, of := range types {
			local := len(l.result.Locals)
			l.result.Locals = append(l.result.Locals, ir.Local{Name: fmt.Sprintf("argument%d", index), Type: of, Function: function, Borrowed: of.IsReference()})
			declared.Parameters = append(declared.Parameters, local)
		}
		switch name {
		case "tsgoProgram":
			declared.Body = []ir.Statement{ir.Return{Value: ir.NumberConstant{Value: 0}}}
		case "tsgoTypeParts", "tsgoInspect":
			empty := len(l.result.Strings)
			l.result.Strings = append(l.result.Strings, "")
			declared.Body = []ir.Statement{ir.Return{Value: ir.StringConstant{Index: empty}}}
		case "tsgoQuery":
			empty := len(l.result.Strings)
			l.result.Strings = append(l.result.Strings, "")
			declared.Body = []ir.Statement{ir.Return{Value: ir.ObjectLiteral{Fields: []ir.Field{
				{Name: "nodeKind", Value: ir.NumberConstant{Value: 0}},
				{Name: "symbolName", Value: ir.StringConstant{Index: empty}},
				{Name: "type", Value: ir.StringConstant{Index: empty}},
			}}}}
		}
		// Also fail loudly if an opted-in IR is sent to an ordinary backend.
		message := len(l.result.Strings)
		l.result.Strings = append(l.result.Strings, "tsgo requires the native checker library renderer")
		declared.Body = append([]ir.Statement{ir.Panic{Message: ir.StringConstant{Index: message}}}, declared.Body...)
		l.result.Functions = append(l.result.Functions, declared)
	}
	return ir.Call{Function: function, Arguments: arguments, Returns: returns}, true, nil
}

typed_arrays.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

func typedArrayName(kind ir.Type) string {
	switch kind {
	case ir.Uint8Array:
		return "Uint8Array"
	case ir.Int32Array:
		return "Int32Array"
	case ir.Float64Array:
		return "Float64Array"
	}
	return "typed array"
}

func (l *lowering) typedArrayKind(proven *checker.Type) ir.Type {
	for _, kind := range []ir.Type{ir.Uint8Array, ir.Int32Array, ir.Float64Array} {
		if l.isLibraryType(proven, typedArrayName(kind)) {
			return kind
		}
	}
	return 0
}

// Reject unsupported buffer facilities while their library identity is still visible.
func (l *lowering) typedArrayUnsupported(node *ast.Node) error {
	if node.Kind == ast.KindTypeReference {
		proven := l.checker.GetTypeAtLocation(node)
		if l.isLibraryType(proven, "SharedArrayBuffer") {
			return l.notYet(node, "sharing typed arrays across parallel tasks")
		}
		for _, name := range []string{"ArrayBuffer", "DataView", "Int8Array", "Uint8ClampedArray", "Int16Array", "Uint16Array", "Uint32Array", "Float32Array", "BigInt64Array", "BigUint64Array"} {
			if l.isLibraryType(proven, name) {
				return l.notYet(node, "typed array facility "+name)
			}
		}
	}
	if node.Kind == ast.KindNewExpression {
		made := node.AsNewExpression()
		if l.isLibraryGlobal(made.Expression, "SharedArrayBuffer") {
			return l.notYet(node, "sharing typed arrays across parallel tasks")
		}
		if l.isLibraryGlobal(made.Expression, "ArrayBuffer") {
			if made.Arguments != nil && len(made.Arguments.Nodes) > 1 {
				return l.notYet(node, "resizable ArrayBuffer buffers")
			}
			return l.notYet(node, "ArrayBuffer")
		}
		if l.isLibraryGlobal(made.Expression, "DataView") {
			return l.notYet(node, "DataView")
		}
		for _, name := range []string{"Int8Array", "Uint8ClampedArray", "Int16Array", "Uint16Array", "Uint32Array", "Float32Array", "BigInt64Array", "BigUint64Array"} {
			if l.isLibraryGlobal(made.Expression, name) {
				return l.notYet(node, "typed array element type "+name)
			}
		}
	}
	if node.Kind == ast.KindPropertyAccessExpression {
		access := node.AsPropertyAccessExpression()
		if kind := l.typedArrayKind(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(access.Expression))); kind != 0 && access.Name().Text() == "buffer" {
			return l.notYet(node, "constructing a view over another view's buffer")
		}
	}
	return nil
}

func (l *lowering) typedArrayExpression(node *ast.Node) (ir.Expression, bool, error) {
	if err := l.typedArrayUnsupported(node); err != nil {
		return nil, true, err
	}
	switch node.Kind {
	case ast.KindNewExpression:
		made := node.AsNewExpression()
		for _, kind := range []ir.Type{ir.Uint8Array, ir.Int32Array, ir.Float64Array} {
			if !l.isLibraryGlobal(made.Expression, typedArrayName(kind)) {
				continue
			}
			var arguments []*ast.Node
			if made.Arguments != nil {
				arguments = made.Arguments.Nodes
			}
			if len(arguments) > 1 {
				return nil, true, l.notYet(node, "constructing a typed array view over a buffer")
			}
			if len(arguments) == 0 {
				return ir.TypedArrayNew{Of: kind, Source: ir.NumberConstant{Value: 0}}, true, nil
			}
			if literal := ast.SkipParentheses(arguments[0]); literal.Kind == ast.KindArrayLiteralExpression && len(literal.AsArrayLiteralExpression().Elements.Nodes) == 0 {
				return ir.TypedArrayNew{Of: kind, Source: ir.ArrayLiteral{Element: ir.Number}, FromArray: true}, true, nil
			}
			source, err := l.expression(arguments[0])
			if err != nil {
				return nil, true, err
			}
			if source.Type() == ir.Number {
				return ir.TypedArrayNew{Of: kind, Source: source}, true, nil
			}
			if source.Type() != ir.Array {
				return nil, true, l.notYet(node, "constructing a typed array from other than a length or number[]")
			}
			element, err := l.elementType(arguments[0])
			if err != nil {
				return nil, true, err
			}
			if element != ir.Number {
				return nil, true, l.notYet(node, "constructing a typed array from other than number[]")
			}
			return ir.TypedArrayNew{Of: kind, Source: source, FromArray: true}, true, nil
		}
	case ast.KindPropertyAccessExpression:
		access := node.AsPropertyAccessExpression()
		kind := l.typedArrayKind(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(access.Expression)))
		if kind == 0 {
			break
		}
		if access.QuestionDotToken == nil && node.Flags&ast.NodeFlagsOptionalChain != 0 {
			return nil, true, l.notYet(node, "an optional chain longer than one step")
		}
		if access.Name().Text() != "length" {
			return nil, true, l.notYet(node, "typed array member "+access.Name().Text())
		}
		array, err := l.expression(access.Expression)
		if err != nil {
			return nil, true, err
		}
		return ir.Length{Array: array, Optional: access.QuestionDotToken != nil}, true, nil
	case ast.KindElementAccessExpression:
		access := node.AsElementAccessExpression()
		if l.typedArrayKind(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(access.Expression))) == 0 {
			break
		}
		if access.QuestionDotToken == nil && node.Flags&ast.NodeFlagsOptionalChain != 0 {
			value, err := l.optionalIndexContinuation(node)
			return value, true, err
		}
		if access.QuestionDotToken != nil {
			array, err := l.expression(access.Expression)
			if err != nil {
				return nil, true, err
			}
			value, err := l.optionalIndex(node, array)
			return value, true, err
		}
		array, err := l.expression(access.Expression)
		if err != nil {
			return nil, true, err
		}
		index, err := l.expression(access.ArgumentExpression)
		if err != nil {
			return nil, true, err
		}
		if index.Type() != ir.Number {
			return nil, true, l.notYet(node, "a typed array index that isn't a number")
		}
		read := ir.Expression(ir.ArrayIndex{Array: array, Index: index, Element: ir.Number})
		if held, _ := l.representation(l.checker.GetTypeAtLocation(node)); held == ir.Number && !l.acceptsUndefined(node) {
			read = ir.Unwrap{Value: read}
		}
		return read, true, nil
	case ast.KindCallExpression:
		call := node.AsCallExpression()
		callee := ast.SkipParentheses(call.Expression)
		if callee.Kind != ast.KindPropertyAccessExpression {
			break
		}
		receiver := callee.AsPropertyAccessExpression().Expression
		kind := l.typedArrayKind(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(receiver)))
		if kind == 0 {
			break
		}
		if err := l.optionalCall(node); err != nil {
			return nil, true, err
		}
		method := callee.Name().Text()
		args := call.Arguments.Nodes
		switch method {
		case "fill":
			if len(args) < 1 || len(args) > 3 {
				return nil, true, l.notYet(node, "typed array fill argument count")
			}
		case "set":
			if len(args) < 1 || len(args) > 2 {
				return nil, true, l.notYet(node, "typed array set argument count")
			}
		case "subarray":
			if len(args) > 2 {
				return nil, true, l.notYet(node, "typed array subarray argument count")
			}
		default:
			return nil, true, l.notYet(node, "typed array method "+method)
		}
		array, err := l.expression(receiver)
		if err != nil {
			return nil, true, err
		}
		lowered := []ir.Expression{}
		for index, argument := range args {
			value, err := l.expression(argument)
			if err != nil {
				return nil, true, err
			}
			if index == 0 && method == "set" {
				if value.Type() != kind {
					return nil, true, l.notYet(argument, "typed array set from a different element type or a plain array")
				}
			} else if method == "fill" && index == 0 {
				if value.Type() != ir.Number {
					return nil, true, l.notYet(argument, "typed array fill with other than a number")
				}
			} else {
				// Optional numeric arguments may explicitly be undefined, as well as omitted.
				value = fit(value, ir.MaybeNumber)
				if value.Type() != ir.MaybeNumber {
					return nil, true, l.notYet(argument, "a typed array offset that isn't number or undefined")
				}
			}
			lowered = append(lowered, value)
		}
		switch method {
		case "fill":
			return ir.TypedArrayFill{Array: array, Arguments: lowered}, true, nil
		case "set":
			return ir.TypedArraySet{Array: array, Arguments: lowered}, true, nil
		case "subarray":
			return ir.TypedArraySubarray{Array: array, Arguments: lowered}, true, nil
		}
	}
	return nil, false, nil
}

func (l *lowering) typedArrayWrite(target, valueNode *ast.Node) ([]ir.Statement, bool, error) {
	access := target.AsElementAccessExpression()
	if l.typedArrayKind(l.checker.GetTypeAtLocation(access.Expression)) == 0 {
		return nil, false, nil
	}
	array, err := l.expression(access.Expression)
	if err != nil {
		return nil, true, err
	}
	index, err := l.expression(access.ArgumentExpression)
	if err != nil {
		return nil, true, err
	}
	value, err := l.expression(valueNode)
	if err != nil {
		return nil, true, err
	}
	if index.Type() != ir.Number || value.Type() != ir.Number {
		return nil, true, l.notYet(target, "a typed array write with nonnumeric index or value")
	}
	return []ir.Statement{ir.SetIndex{Array: array, Index: index, Value: value, Element: ir.Number, Site: l.writeSite(access.Expression)}}, true, nil
}

func (l *lowering) typedArrayForOf(node *ast.Node) ([]ir.Statement, bool, error) {
	statement := node.AsForInOrOfStatement()
	if l.typedArrayKind(l.checker.GetTypeAtLocation(statement.Expression)) == 0 {
		return nil, false, nil
	}
	initializer := statement.Initializer
	if statement.AwaitModifier != nil {
		return nil, true, l.notYet(node, "for await over a typed array")
	}
	if initializer.Kind != ast.KindVariableDeclarationList || initializer.Flags&ast.NodeFlagsBlockScoped == 0 {
		return nil, true, l.notYet(initializer, "a typed array loop without a const or let declaration")
	}
	declarations := initializer.AsVariableDeclarationList().Declarations.Nodes
	if len(declarations) != 1 || !ast.IsIdentifier(declarations[0].Name()) {
		return nil, true, l.notYet(initializer, "a typed array loop without a plain element name")
	}
	array, err := l.expression(statement.Expression)
	if err != nil {
		return nil, true, err
	}
	local, err := l.declareLocal(declarations[0].Name())
	if err != nil {
		return nil, true, err
	}
	body, err := l.statement(statement.Statement)
	if err != nil {
		return nil, true, err
	}
	return []ir.Statement{ir.ForOf{Iterable: array, Element: ir.Number, Local: local, Body: body}}, true, nil
}

// set's ArrayLike<number> parameter is a library protocol, not a kept object view.
// Its dedicated lowering checks same-kind storage and never passes an object shape.
func (l *lowering) typedArraySetArgument(node *ast.Node) bool {
	for node.Parent != nil && node.Parent.Kind == ast.KindParenthesizedExpression {
		node = node.Parent
	}
	parent := node.Parent
	if parent == nil || parent.Kind != ast.KindCallExpression {
		return false
	}
	callee := ast.SkipParentheses(parent.AsCallExpression().Expression)
	if callee.Kind != ast.KindPropertyAccessExpression || callee.Name().Text() != "set" {
		return false
	}
	return l.typedArrayKind(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(callee.AsPropertyAccessExpression().Expression))) != 0
}

typeof.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
)

// typeOfNull records what a missing pointer means before the checker type is reduced to a
// representation. A declared slot can hold null again after a call, despite a stale narrowing.
func (l *lowering) typeOfNull(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	proven := l.concrete(l.checker.GetTypeAtLocation(node))
	if node.Kind == ast.KindElementAccessExpression {
		receiver := l.checker.GetNonNullableType(l.concrete(l.checker.GetTypeAtLocation(node.AsElementAccessExpression().Expression)))
		if l.checker.IsArrayType(receiver) && l.includesNull(l.checker.GetElementTypeOfArrayType(receiver)) {
			return true
		}
	}
	at := node
	if node.Kind == ast.KindPropertyAccessExpression {
		at = node.Name()
	}
	if node.Kind == ast.KindIdentifier || node.Kind == ast.KindPropertyAccessExpression {
		if symbol := l.checker.GetSymbolAtLocation(at); symbol != nil {
			declared := l.concrete(l.checker.GetTypeOfSymbol(symbol))
			if l.includesNull(declared) {
				proven = declared
			}
		}
	}
	return l.includesNull(proven)
}

unknown.go:
package lower

import (
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

func dynamicObjectType(proven *checker.Type) bool {
	if proven.Flags()&(checker.TypeFlagsUnknown|checker.TypeFlagsNonPrimitive) != 0 {
		return true
	}
	if proven.Flags()&(checker.TypeFlagsIntersection|checker.TypeFlagsUnion) != 0 {
		for _, part := range proven.Types() {
			if dynamicObjectType(part) {
				return true
			}
		}
	}
	return false
}

func (l *lowering) inProperty(node *ast.Node) (ir.Expression, error) {
	binary := node.AsBinaryExpression()
	key := ast.SkipParentheses(binary.Left)
	if key.Kind != ast.KindStringLiteral {
		return nil, l.notYet(key, "in with a key other than a string literal (dynamic key coercion)")
	}
	if strings.ContainsRune(key.Text(), 0) {
		return nil, l.notYet(key, "in with a NUL key (native shape names)")
	}
	// "key" in value narrows a union of object types to the members that declare the key, and any
	// object carrying that key passes, so the narrowed member's fields would be read on trust. The
	// sound use is presence on an unknown or single object type, where reads stay dynamic.
	if right := l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(binary.Right)); right.Flags()&checker.TypeFlagsUnion != 0 {
		objects := 0
		for _, member := range right.Types() {
			if member.Flags()&checker.TypeFlagsObject != 0 {
				objects++
			}
		}
		if objects > 1 {
			return nil, &Refused{Where: l.program.Where(node), What: "in that narrows a union of object types (any object with the key passes)", Fix: "use a discriminant, or a Map"}
		}
	}
	if checker.IsTupleType(l.checker.GetNonNullableType(l.checker.GetTypeAtLocation(binary.Right))) {
		return nil, l.notYet(binary.Right, "in on a tuple (array presence metadata)")
	}
	if key.Text() == "stack" || key.Text() == "cause" || key.Text() == "errno" || key.Text() == "syscall" || key.Text() == "path" {
		return nil, l.notYet(key, "in on an Error internal or optional property (host descriptor metadata)")
	}
	if reason := l.presenceHazard(key.Text()); reason != "" {
		return nil, l.notYet(node, "in when "+reason)
	}
	if l.classes[l.symbol(ast.SkipParentheses(binary.Right))] != nil {
		return nil, l.notYet(binary.Right, "in on a class constructor (static property presence descriptors)")
	}
	object, err := l.expression(binary.Right)
	if err != nil {
		return nil, err
	}
	if object.Type() != ir.Object && object.Type() != ir.Array && object.Type() != ir.Union {
		return nil, l.notYet(binary.Right, "in on this runtime representation")
	}
	return ir.HasProperty{Object: fit(object, ir.Union), Name: key.Text()}, nil
}

func (l *lowering) dynamicProperty(node *ast.Node, object ir.Expression, name string) (ir.Expression, error) {
	if strings.ContainsRune(name, 0) {
		return nil, l.notYet(node, "a dynamic property name containing NUL (native shape names)")
	}
	if l.dynamicReadHazard(name) {
		return nil, l.notYet(node, "a dynamic getter or method read, or a nullable field (runtime dispatch, slot tags and narrowed rereads)")
	}
	// Prototype function values and dynamic array elements need callable and element metadata.
	switch name {
	case "constructor", "__proto__", "toString", "valueOf", "hasOwnProperty", "isPrototypeOf", "propertyIsEnumerable", "toLocaleString", "__defineGetter__", "__defineSetter__", "__lookupGetter__", "__lookupSetter__", "map", "filter", "push", "pop", "slice", "join", "entries", "values", "keys":
		return nil, l.notYet(node, "a dynamic prototype property value (intrinsic identity and ToPrimitive)")
	}
	value := ir.Expression(ir.DynamicProperty{Object: object, Name: name})
	of, err := l.typeOf(node)
	if err != nil {
		return nil, err
	}
	if of != ir.Union {
		value = ir.Narrow{Value: value, To: of}
	}
	return value, nil
}

// A dynamic read can be converted with String only when every program shape's field of that
// name is scalar. This is a conservative closed-program proof, not a promise from unknown.
func (l *lowering) dynamicScalarProperty(node *ast.Node) bool {
	node = ast.SkipParentheses(node)
	if ast.IsIdentifier(node) {
		symbol := l.symbol(node)
		if symbol != nil && len(symbol.Declarations) == 1 && symbol.Declarations[0].Kind == ast.KindVariableDeclaration {
			declaration := symbol.Declarations[0]
			if declaration.Parent.Flags&ast.NodeFlagsConst != 0 && declaration.AsVariableDeclaration().Initializer != nil {
				node = ast.SkipParentheses(declaration.AsVariableDeclaration().Initializer)
			}
		}
	}
	if node.Kind != ast.KindPropertyAccessExpression {
		return false
	}
	name := node.Name().Text()
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return false
	}
	known := true
	var visit ast.Visitor
	visit = func(candidate *ast.Node) bool {
		if candidate.Kind == ast.KindObjectLiteralExpression || candidate.Kind == ast.KindNewExpression || candidate.Kind == ast.KindArrayLiteralExpression {
			if field := l.checker.GetPropertyOfType(l.checker.GetTypeAtLocation(candidate), name); field != nil {
				proven := l.checker.GetTypeOfSymbol(field)
				if !l.writable(proven) {
					known = false
				}
			}
		}
		candidate.ForEachChild(visit)
		return false
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return known
}

// Unknown views must preserve runtime tags. Opaque host objects and tuples have additional
// JavaScript properties their native layouts do not yet describe.
func (l *lowering) unknownView(node *ast.Node, own, contextual *checker.Type) error {
	if !dynamicObjectType(contextual) {
		return nil
	}
	// Library intrinsics lower their arguments with their own schema or operation. Their
	// declaration's unknown parameter does not create an unknown runtime view.
	outer := node
	for outer.Parent != nil && outer.Parent.Kind == ast.KindParenthesizedExpression {
		outer = outer.Parent
	}
	if outer.Parent != nil && outer.Parent.Kind == ast.KindCallExpression {
		callee := outer.Parent.AsCallExpression().Expression
		if l.librarySymbol(l.memberSymbol(callee)) {
			return nil
		}
		if callee.Kind == ast.KindPropertyAccessExpression && callee.Name().Text() == "stringify" && l.isLibraryGlobal(callee.AsPropertyAccessExpression().Expression, "JSON") {
			return nil
		}
	}
	if l.includesNull(own) && own.Flags()&checker.TypeFlagsNull == 0 {
		if held, known := l.representation(own); known && held != ir.Union {
			return l.notYet(node, "a nullable reference viewed as unknown or object (null and undefined slot tags)")
		}
	}
	present := l.checker.GetNonNullableType(own)
	if held, known := l.representation(present); known && held == ir.Closure {
		return l.notYet(node, "a function viewed as unknown or object (dynamic function descriptors)")
	}
	for _, name := range []string{"JSON", "Math", "Reflect"} {
		if l.isLibraryGlobal(ast.SkipParentheses(node), name) {
			return l.notYet(node, "an intrinsic identity viewed as unknown or object (dynamic object descriptors)")
		}
	}
	for _, field := range l.checker.GetPropertiesOfType(present) {
		if l.includesNull(l.checker.GetTypeOfSymbol(field)) {
			return l.notYet(node, "an object with a nullable field viewed as unknown or object (null and undefined slot tags)")
		}
	}
	if checker.IsTupleType(present) {
		return l.notYet(node, "a tuple viewed as unknown or object (array presence metadata)")
	}
	if l.isLibraryType(present, "Map", "ReadonlyMap", "Set", "ReadonlySet", "RegExp", "Date", "Stats", "Hash", "Buffer") {
		return l.notYet(node, "an opaque host or collection value viewed as unknown or object (dynamic property metadata)")
	}
	return nil
}

// A key that could denote a getter or a prototype method cannot yet be read dynamically.
func (l *lowering) dynamicReadHazard(name string) bool {
	if l.accessorNames[name] {
		return true
	}
	for _, declaration := range l.classes {
		for _, member := range declaration.Members() {
			if member.Name() != nil && member.Name().Text() == name && member.Kind != ast.KindPropertyDeclaration {
				return true
			}
		}
	}
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return true
	}
	nullable := false
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if node.Kind == ast.KindObjectLiteralExpression || node.Kind == ast.KindNewExpression {
			if field := l.checker.GetPropertyOfType(l.checker.GetTypeAtLocation(node), name); field != nil && l.includesNull(l.checker.GetTypeOfSymbol(field)) {
				nullable = true
			}
		}
		node.ForEachChild(visit)
		return false
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return nullable
}

// Native absent-spread slots and ambient class fields are storage, not proof of JS presence.
func (l *lowering) presenceHazard(name string) string {
	modules, err := l.moduleOrder(l.program.Files()[0])
	if err != nil {
		return "runtime shapes are not known"
	}
	reason := ""
	var visit ast.Visitor
	visit = func(node *ast.Node) bool {
		if node.Kind == ast.KindObjectLiteralExpression {
			for _, property := range node.AsObjectLiteralExpression().Properties.Nodes {
				if property.Kind == ast.KindSpreadAssignment && l.includesUndefined(l.checker.GetTypeAtLocation(property.AsSpreadAssignment().Expression)) {
					reason = "a possibly absent spread has no property presence descriptors"
				}
			}
		}
		if node.Kind == ast.KindClassDeclaration {
			for _, member := range node.Members() {
				if member.Kind == ast.KindMethodDeclaration && member.Name().Text() == name {
					for _, parameter := range member.Parameters() {
						if held, known := l.representation(l.checker.GetTypeAtLocation(parameter.Name())); known && slotless(held) {
							reason = "a method's presence is not in its native dispatch table"
						}
					}
					for _, signature := range l.checker.GetSignaturesOfType(l.checker.GetTypeAtLocation(member), checker.SignatureKindCall) {
						if held, known := l.representation(l.checker.GetReturnTypeOfSignature(signature)); known && slotless(held) {
							reason = "a method's presence is not in its native dispatch table"
						}
					}
				}
				if member.Name() != nil && member.Name().Text() == name && ast.HasSyntacticModifier(member, ast.ModifierFlagsAmbient) {
					reason = "an ambient class field has no JavaScript own property"
				}
			}
		}
		node.ForEachChild(visit)
		return false
	}
	for _, module := range modules {
		module.AsNode().ForEachChild(visit)
	}
	return reason
}

view_adapters.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

func unavailableViewFamily(family string) viewContractHook {
	return func(l *lowering, node *ast.Node, _ *checker.Type, _ viewContractBuilder) (ir.ViewContractID, error) {
		return 0, l.notYet(node, "a "+family+" checked-view contract")
	}
}

var viewUnionContractHook viewContractHook

func init() { viewUnionContractHook = buildUnionReadContract }

var viewDictionaryContractHook = unavailableViewFamily("dictionary")
var viewIntersectionContractHook = unavailableViewFamily("intersection")

func viewErasureProof(*ir.Program, ir.Property) bool { return false }
func (l *lowering) viewObjectFields(node *ast.Node, target *checker.Type, fields map[string]bool, _ map[*checker.Type]bool, _ bool) error {
	all, err := l.viewSchema(node, target)
	for field := range all {
		fields[field] = true
	}
	return err
}

view_contracts.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"reflect"
)

// Lane 2 registers these adapters from its new files. Until then an unsupported
// family stays NotYet/Refused, rather than silently lowering an incomplete contract.
type viewContractBuilder func(*checker.Type) (ir.ViewContractID, error)
type viewContractHook func(*lowering, *ast.Node, *checker.Type, viewContractBuilder) (ir.ViewContractID, error)

var viewArrayContractHook viewContractHook
var viewCallableContractHook viewContractHook

func (l *lowering) strictViewContract(node *ast.Node, target *checker.Type) (ir.ViewContractID, error) {
	if l.result.ViewContractTypes == nil {
		l.result.ViewContractTypes = map[int]ir.ViewContractID{}
	}
	if id := l.result.ViewContractTypes[int(target.Id())]; id != 0 {
		return id, nil
	}
	if target.Flags()&checker.TypeFlagsUndefined != 0 || l.phantomUndefined(target) {
		id := ir.ViewContractID(len(l.result.ViewContracts) + 1)
		l.result.ViewContracts = append(l.result.ViewContracts, ir.ViewContract{Kind: ir.ViewUndefined, Name: "undefined", Undefined: true, Of: ir.Object})
		l.result.ViewContractTypes[int(target.Id())] = id
		return id, nil
	}
	if target.Flags()&checker.TypeFlagsNull != 0 {
		id := ir.ViewContractID(len(l.result.ViewContracts) + 1)
		l.result.ViewContracts = append(l.result.ViewContracts, ir.ViewContract{Kind: ir.ViewNull, Name: "null", Null: true, Of: ir.Object})
		l.result.ViewContractTypes[int(target.Id())] = id
		return id, nil
	}
	build := func(child *checker.Type) (ir.ViewContractID, error) { return l.viewContract(node, child) }
	if target.Flags()&checker.TypeFlagsObject != 0 && (l.checker.IsArrayType(target) || checker.IsTupleType(target)) {
		if viewArrayContractHook == nil {
			return 0, l.notYet(node, "an array checked-view contract")
		}
		return viewArrayContractHook(l, node, target, build)
	}
	if l.callableViewContract(target) {
		if viewCallableContractHook == nil {
			return 0, &Refused{Where: l.program.Where(node), What: "a checked view with a callable contract", Fix: "prove the callable body rather than asserting its signature"}
		}
		return viewCallableContractHook(l, node, target, build)
	}

	represented := target
	if base := l.phantomBase(target); base != nil {
		represented = base
	}
	of, known := l.representation(represented)
	if !known {
		return 0, l.notYet(node, "checked-view representation for "+l.checker.TypeToString(target))
	}
	contract := ir.ViewContract{Undefined: l.includesUndefined(target), Name: l.checker.TypeToString(target), Of: of}
	if isClassInstance(target) {
		if declaration := l.classNodeFor(target); declaration != nil {
			contract.Nominal = l.program.Where(declaration) + ":" + contract.Name
			contract.NominalBases = l.viewNominalBases(target, map[*checker.Type]bool{})
		}
	}
	if target.Flags()&checker.TypeFlagsUndefined != 0 || l.phantomUndefined(target) {
		contract.Kind = ir.ViewUndefined
	} else if interfaceScalar(represented) && of != ir.Union {
		contract.Kind = ir.ViewScalar
		contract.Allowed = l.viewContractLiterals(represented)
	} else {
		contract.Kind = ir.ViewObject
	}

	id := ir.ViewContractID(len(l.result.ViewContracts) + 1)
	l.result.ViewContracts = append(l.result.ViewContracts, contract)
	l.result.ViewContractTypes[int(target.Id())] = id

	if contract.Kind == ir.ViewObject || (contract.Kind == ir.ViewUnion && of == ir.Object) {
		for _, property := range l.checker.GetPropertiesOfType(target) {
			child, err := build(l.checker.GetTypeOfSymbol(property))
			if err != nil {
				return 0, err
			}

			contract.Fields = append(contract.Fields, ir.ViewFieldContract{Name: property.Name, Contract: child, Optional: property.Flags&ast.SymbolFlagsOptional != 0, Readonly: l.checker.IsReadonlySymbol(property)})
		}
	}

	l.result.ViewContracts[int(id)-1] = contract
	return id, nil
}

func (l *lowering) viewContractLiterals(target *checker.Type) []ir.ViewLiteral {
	// A whole numeric enum admits numbers outside its declared members.
	if l.openNumericEnumType(target) {
		return nil
	}
	if target.Flags()&checker.TypeFlagsUnion != 0 {
		var allowed []ir.ViewLiteral
		for _, member := range target.Types() {
			if member.Flags()&checker.TypeFlagsUndefined != 0 {
				continue
			}
			values := l.viewContractLiterals(member)
			if len(values) == 0 {
				return nil
			}
			allowed = append(allowed, values...)
		}
		return allowed
	}
	flags := target.Flags()
	switch {
	case flags&checker.TypeFlagsStringLiteral != 0:
		value, ok := target.AsLiteralType().Value().(string)
		if ok {
			return []ir.ViewLiteral{{Of: ir.String, String: value}}
		}
	case flags&checker.TypeFlagsNumberLiteral != 0:
		value := reflect.ValueOf(target.AsLiteralType().Value())
		if value.Kind() == reflect.Float64 {
			return []ir.ViewLiteral{{Of: ir.Number, Number: value.Float()}}
		}
	case flags&checker.TypeFlagsBooleanLiteral != 0:
		return []ir.ViewLiteral{{Of: ir.Boolean, Boolean: l.checker.TypeToString(target) == "true"}}
	}
	return nil
}

func (l *lowering) viewNominalBases(target *checker.Type, seen map[*checker.Type]bool) []string {
	if seen[target] {
		return nil
	}
	seen[target] = true
	var names []string
	for _, base := range l.classBases(target) {
		if declaration := l.classNodeFor(base); declaration != nil {
			names = append(names, l.program.Where(declaration)+":"+l.checker.TypeToString(base))
			names = append(names, l.viewNominalBases(base, seen)...)
		}
	}
	return names
}

view_flow.go:
package lower

import (
	"fmt"
	"reflect"

	"github.com/system-inc/adamic/internal/ir"
)

// graphAllocationSites copies the IR tree before assigning unique allocation
// IDs. Pointer and map children must be copied too, so their sites do not depend
// solely on a checker identity. Nil containers preserve their original shape.
func graphAllocationSites(value reflect.Value, next *int) reflect.Value {
	var sites func(reflect.Value) reflect.Value
	sites = func(value reflect.Value) reflect.Value {
		switch value.Kind() {
		case reflect.Interface:
			if value.IsNil() {
				return value
			}
			mapped := sites(value.Elem())
			result := reflect.New(value.Type()).Elem()
			result.Set(mapped)
			return result
		case reflect.Ptr:
			if value.IsNil() {
				return value
			}
			result := reflect.New(value.Type().Elem())
			result.Elem().Set(sites(value.Elem()))
			return result
		case reflect.Map:
			if value.IsNil() {
				return value
			}
			result := reflect.MakeMapWithSize(value.Type(), value.Len())
			entries := value.MapRange()
			for entries.Next() {
				result.SetMapIndex(sites(entries.Key()), sites(entries.Value()))
			}
			return result
		case reflect.Struct:
			result := reflect.New(value.Type()).Elem()
			for i := 0; i < value.NumField(); i++ {
				result.Field(i).Set(sites(value.Field(i)))
			}
			if field := result.FieldByName("GraphTypes"); field.IsValid() && field.Type() == reflect.TypeOf([]int{}) {
				*next--
				field.Set(reflect.ValueOf(append(append([]int{}, field.Interface().([]int)...), *next)))
			}
			return result
		case reflect.Slice:
			if value.IsNil() {
				return value
			}
			result := reflect.MakeSlice(value.Type(), value.Len(), value.Len())
			for i := 0; i < value.Len(); i++ {
				result.Index(i).Set(sites(value.Index(i)))
			}
			return result
		default:
			return value
		}
	}
	return sites(value)
}

// allocationFlowGraph is the shared may-flow graph used by graph regions and
// shape certification. It never changes ownership when queried.
type allocationFlowGraph struct {
	projection        *allocationProjection
	projectionReads   map[int]ir.AllocationSet
	projectionBusy    map[int]bool
	program           *ir.Program
	sources           map[int][]ir.Expression
	unknownParameters map[int]bool
}

func (graph *allocationFlowGraph) resultNode(function int) int {
	return len(graph.program.Locals) + function + 1
}

func newAllocationFlowGraph(program *ir.Program) *allocationFlowGraph {
	graph := &allocationFlowGraph{program: program, sources: map[int][]ir.Expression{}, unknownParameters: map[int]bool{}}
	collect := func(body []ir.Statement, function int) {
		walk(body, func(node any) bool {
			switch value := node.(type) {
			case ir.MakeClosure:
				// Callback invocations are outside the collected call edges.
				for _, parameter := range program.Functions[value.Function].Parameters {
					graph.unknownParameters[parameter+1] = true
				}
			case ir.Declare:
				graph.sources[value.Local+1] = append(graph.sources[value.Local+1], value.Value)
			case ir.Assign:
				graph.sources[value.Local+1] = append(graph.sources[value.Local+1], value.Value)
			case ir.Return:
				if function >= 0 {
					graph.sources[graph.resultNode(function)] = append(graph.sources[graph.resultNode(function)], value.Value)
				}
			case ir.Call:
				for _, target := range program.CallTargets(value) {
					if target < 0 || target >= len(program.Functions) {
						continue
					}
					for i, param := range program.Functions[target].Parameters {
						if i < len(value.Arguments) {
							graph.sources[param+1] = append(graph.sources[param+1], value.Arguments[i])
						} else {
							graph.unknownParameters[param+1] = true
						}
					}
				}
			case ir.CallClosure:
				targets := program.ClosureTargets(value)
				if targets.Unknown {
					// Opaque function values are a documented leak-only frontier.
					break
				}
				for _, target := range targets.Functions {
					for i, param := range program.Functions[target].Parameters {
						if i < len(value.Arguments) {
							graph.sources[param+1] = append(graph.sources[param+1], value.Arguments[i])
						} else {
							graph.unknownParameters[param+1] = true
						}
					}
				}

			}
			return true
		})
	}
	collect(program.Main, -1)
	for i, function := range program.Functions {
		collect(function.Body, i)
	}
	return graph
}

func (graph *allocationFlowGraph) follow(expression ir.Expression, allocation func(int), demand func(int), unknown func(string)) {
	program := graph.program
	follow := func(value ir.Expression) { graph.follow(value, allocation, demand, unknown) }
	if expression == nil {
		unknown("missing expression")
		return
	}
	value := reflect.ValueOf(expression)
	if field := value.FieldByName("GraphTypes"); field.IsValid() {
		ids := field.Interface().([]int)
		if len(ids) == 0 || ids[len(ids)-1] >= 0 {
			unknown("allocation has no site identity")
		} else {
			allocation(ids[len(ids)-1])
		}
		return
	}
	switch value := expression.(type) {
	case ir.Read:
		demand(value.Local + 1)
	case ir.Call:
		if len(program.CallTargets(value)) == 0 {
			unknown("call has no tracked target")
		}
		for _, target := range program.CallTargets(value) {
			demand(graph.resultNode(target))
		}
	case ir.CallClosure:
		targets := program.ClosureTargets(value)
		if targets.Unknown {
			unknown("opaque closure")
			return
		}
		for _, target := range targets.Functions {
			demand(graph.resultNode(target))
		}
	case ir.Conditional:
		follow(value.WhenTrue)
		follow(value.WhenNot)
	case ir.Box:
		follow(value.Value)
	case ir.Narrow:
		follow(value.Value)
	case ir.Unwrap:
		follow(value.Value)
	case ir.CheckedCast:
		follow(value.Value)
	default:
		unknown(fmt.Sprintf("untracked source %T", expression))
	}
}

// assignAllocationSites uses graph regions' numbering for programs without cycle
// seeds too. Existing numbered programs are left unchanged.
func assignAllocationSites(program *ir.Program) {
	numbered := false
	inspect := func(node any) bool {
		value := reflect.ValueOf(node)
		if value.IsValid() && value.Kind() == reflect.Struct {
			if field := value.FieldByName("GraphTypes"); field.IsValid() {
				ids := field.Interface().([]int)
				numbered = numbered || len(ids) > 0 && ids[len(ids)-1] < 0
			}
		}
		return true
	}
	walk(program.Main, inspect)
	for _, function := range program.Functions {
		walk(function.Body, inspect)
	}
	if numbered {
		return
	}
	next := 0
	program.Main = graphAllocationSites(reflect.ValueOf(program.Main), &next).Interface().([]ir.Statement)
	for i := range program.Functions {
		program.Functions[i].Body = graphAllocationSites(reflect.ValueOf(program.Functions[i].Body), &next).Interface().([]ir.Statement)
	}
}

view_interfaces.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
)

// Interface inheritance is a structural contract, never a construction proof.
// Re-enter the data walker with the same memo table so recursive interfaces keep
// checks without expanding their schema indefinitely.
func (l *lowering) viewInterfaceFields(node *ast.Node, target *checker.Type, fields map[string]bool, seen map[*checker.Type]bool) error {
	return l.viewObjectFields(node, target, fields, seen, false)
}

view_lazy.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"strings"
)

// Unsupported contracts are descriptors, never certificates. Their users must
// refuse at a demanded read. Cast admission does not inspect their payloads.
func (l *lowering) viewContract(node *ast.Node, target *checker.Type) (ir.ViewContractID, error) {
	if l.result.ViewContractTypes == nil {
		l.result.ViewContractTypes = map[int]ir.ViewContractID{}
	}
	if id := l.result.ViewContractTypes[int(target.Id())]; id != 0 {
		return id, nil
	}
	family := l.unsupportedViewFamily(target)
	if of, known := l.viewRepresentation(target); target.Flags()&checker.TypeFlagsUnion != 0 && (!interfaceScalar(target) || !known || of == ir.Union) {
		return viewUnionContractHook(l, node, target, func(child *checker.Type) (ir.ViewContractID, error) { return l.viewContract(node, child) })
	}
	if l.checker.IsArrayType(target) || checker.IsTupleType(target) {
		return l.unionAggregateContract(node, target)
	}
	if l.callableViewContract(target) {
		family = "callable"
	}
	if l.checker.IsArrayType(target) {
		family = "array"
	}
	if of, known := l.representation(target); target.Flags()&checker.TypeFlagsUnion != 0 && (!interfaceScalar(target) || !known || of == ir.Union) {
		family = "union"
	}
	if family == "" {
		id, err := l.strictViewContract(node, target)
		if err == nil {
			return id, nil
		}
		family = "representation conversion"
	}
	// A failing family adapter may have reserved its recursive id already.
	id := l.result.ViewContractTypes[int(target.Id())]
	descriptor := ir.ViewContract{Kind: ir.ViewUnknown, Name: l.checker.TypeToString(target), Unsupported: family}
	if id == 0 {
		id = ir.ViewContractID(len(l.result.ViewContracts) + 1)
		l.result.ViewContracts = append(l.result.ViewContracts, descriptor)
		l.result.ViewContractTypes[int(target.Id())] = id
	} else {
		l.result.ViewContracts[id-1] = descriptor
	}
	return id, nil
}

func (l *lowering) unsupportedViewFamily(target *checker.Type) string {
	if l.phantomUndefined(target) || target.Flags()&checker.TypeFlagsUndefined != 0 {
		return ""
	}
	if base := l.phantomBase(target); base != nil && interfaceScalar(base) {
		return ""
	}
	flags := target.Flags()
	switch {
	case flags&checker.TypeFlagsAny != 0:
		return "any"
	case flags&checker.TypeFlagsUnknown != 0:
		return "unknown"
	case flags&checker.TypeFlagsNever != 0:
		return "never"
	case flags&checker.TypeFlagsTypeParameter != 0:
		return "generic"
	case flags&checker.TypeFlagsIntersection != 0:
		return "intersection"
	case flags&checker.TypeFlagsNull != 0:
		return ""
	case flags&checker.TypeFlagsUndefined != 0:
		return "nullish"
	case isClassInstance(target):
		return "nominal class"
	case l.isLibraryType(target, "Map", "ReadonlyMap", "Set", "ReadonlySet"):
		return "collection"
	case checker.IsTupleType(target):
		return "tuple"
	case flags&checker.TypeFlagsObject != 0 && len(l.checker.GetIndexInfosOfType(target)) != 0 && !l.checker.IsArrayType(target):
		return "dictionary"
	}

	return ""
}

// Demand uses the same allocations, joined arguments/results and projected
// stores as shape certification. Unknown is never an empty proof of safety.
func (l *lowering) checkLazyViewReads() error {
	l.certifyUntaggedCallableProducers()
	l.completeUntaggedRecursiveContracts()
	program := l.result
	if len(program.ViewOrigins) == 0 {
		return nil
	}
	assignAllocationSites(program)
	graph := newAllocationFlowGraph(program)
	viewed := map[int]bool{}
	unknown := false
	queue := []int{}
	add := func(set ir.AllocationSet) {
		unknown = unknown || set.Unknown
		for _, site := range set.Sites {
			if !viewed[site] {
				viewed[site] = true
				queue = append(queue, site)
			}
		}
	}
	for _, origin := range program.ViewOrigins {
		add(graph.ReachingAllocations(origin))
	}
	index := graph.projectionIndex()
	for len(queue) != 0 {
		site := queue[len(queue)-1]
		queue = queue[:len(queue)-1]
		if literal, ok := index.records[site]; ok {
			for _, field := range literal.Fields {
				if viewAggregate(field.Value) {
					add(graph.ReachingAllocations(field.Value))
				}
			}
			if literal.Spread != nil {
				add(graph.ReachingAllocations(literal.Spread))
			}
		}
		if literal, ok := index.arrays[site]; ok {
			for _, element := range literal.Elements {
				if viewAggregate(element) {
					add(graph.ReachingAllocations(element))
				}
			}
		}
		for _, values := range index.stores[site] {
			for _, value := range values {
				if viewAggregate(value) {
					add(graph.ReachingAllocations(value))
				}
			}
		}
	}
	// Wider interfaces and instantiated helpers can give the same member a
	// different checker type id. Field-name fallback retains the refusal until
	// the receiver flow proves it cannot receive a viewed allocation.
	unsupportedFields := map[string]string{}
	for _, descriptor := range program.ViewContracts {
		for _, field := range descriptor.Fields {
			if family := program.ViewContracts[field.Contract-1].Unsupported; family != "" {
				unsupportedFields[field.Name] = family
			}
		}
	}
	var refused error
	inspect := func(node any) bool {
		if refused != nil {
			return false
		}
		var receiver ir.Expression
		var typeID, receiverTypeID int
		var field, where string

		switch read := node.(type) {
		case ir.Property:
			if !program.CheckedFields[read.Name] {
				return true
			}
			receiver, typeID, field, where = read.Object, read.ViewTypeID, read.Name, read.ViewWhere
			receiverTypeID = read.ViewReceiverTypeID

		default:
			return true
		}
		contract := program.ViewContractTypes[typeID]
		family := ""
		if contract != 0 {
			family = program.ViewContracts[contract-1].Unsupported
		}
		if receiverContract := program.ViewContractTypes[receiverTypeID]; family == "" && receiverContract != 0 {
			family = program.ViewContracts[receiverContract-1].Unsupported
		}
		if family == "" {
			family = unsupportedFields[field]
		}
		if family == "" {
			return true
		}
		reaches := graph.ReachingAllocations(receiver)
		demanded := unknown || reaches.Unknown
		for _, site := range reaches.Sites {
			demanded = demanded || viewed[site]
		}
		if demanded {
			if strings.Contains(family, "views-v3: array element kind") {
				refused = &NotYet{Where: where, What: "checked view union arm awaits views-v3: array element kind"}
				return false
			}
			refused = &Refused{Where: where, What: "checked view read of field " + field + " with unsupported " + family + " contract", Fix: "prove or implement the " + family + " contract before reading this field"}
		}
		return true
	}
	walk(program.Main, inspect)
	for _, function := range program.Functions {
		walk(function.Body, inspect)
	}
	return refused
}

func viewAggregate(value ir.Expression) bool {
	if value == nil {
		return false
	}
	switch value.Type() {
	case ir.Object, ir.Array, ir.Map, ir.Union, ir.Closure:
		return true
	}
	return false
}

func (l *lowering) lazyReadRefusal(node *ast.Node, field, family string) error {
	return &Refused{Where: l.program.Where(node), What: "checked view read of field " + field + " with unsupported " + family + " contract", Fix: "prove or implement the " + family + " contract before reading this field"}
}

view_objects.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// A read of a structural object checks its own heap kind. Register every descendant
// field too: returning or aliasing that object must not lose the checks on its reads.
// Interface descendants share the same data checks, including inherited fields.

func viewDataType(target *checker.Type) bool {
	if target.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range target.Types() {
			if !viewDataType(member) {
				return false
			}
		}
		return true
	}
	return target.Flags()&checker.TypeFlagsUndefined != 0 || interfaceScalar(target) || target.Flags()&checker.TypeFlagsObject != 0
}

func viewInterfaceType(target *checker.Type) bool {
	if target.ObjectFlags()&checker.ObjectFlagsInterface != 0 {
		return true
	}
	return target.ObjectFlags()&checker.ObjectFlagsReference != 0 && target.Target() != nil && target.Target().ObjectFlags()&checker.ObjectFlagsInterface != 0
}

// An untagged structural cast installs the same checked reads without a tag test.
// Admission preserves nominal identity and the existing writable-slot restrictions.
func (l *lowering) structuralViewCast(node *ast.Node, value ir.Expression, source, target *checker.Type) (ir.Expression, error) {
	if value.Type() != ir.Object || source.Flags()&checker.TypeFlagsObject == 0 || target.Flags()&checker.TypeFlagsObject == 0 || isClassInstance(target) || !l.checker.IsTypeAssignableTo(target, source) {
		return nil, nil
	}
	if len(l.checker.GetIndexInfosOfType(target)) != 0 {
		return nil, l.notYet(node, "a dictionary checked view")
	}
	if err := l.widened(target, source, map[[2]*checker.Type]bool{}); err != nil {
		return nil, l.notYet(node, "a writable-slot checked view requiring source contract certification")
	}
	return l.view(node, value, target)
}

void.go:
package lower

import "github.com/microsoft/TypeScript/tsc/shim/ast"

// A void initializer has no value to keep. Other expressions narrowed to undefined
// still use their declared storage, such as find's number | undefined result.
func voidInitializer(node *ast.Node) bool {
	if node.Kind != ast.KindIdentifier || node.Parent == nil || node.Parent.Kind != ast.KindVariableDeclaration {
		return false
	}
	initializer := node.Parent.AsVariableDeclaration().Initializer
	return initializer != nil && ast.SkipParentheses(initializer).Kind == ast.KindVoidExpression
}

view_unions_primitive_brands.go:
package lower

import (
	"slices"
	"strconv"
	"strings"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// phantomParts separates a primitive from the object views that give it a checker-only name.
// Void is included because tsc's __String deliberately brands undefined through void.
func (l *lowering) phantomParts(proven *checker.Type) (*checker.Type, []*checker.Type) {
	proven = l.concrete(proven)
	if proven.Flags()&checker.TypeFlagsIntersection == 0 {
		return nil, nil
	}
	var primitive *checker.Type
	var objects []*checker.Type
	for _, part := range proven.Types() {
		switch {
		case part.Flags()&(checker.TypeFlagsStringLike|checker.TypeFlagsNumberLike|checker.TypeFlagsBooleanLike|checker.TypeFlagsVoid|checker.TypeFlagsUndefined) != 0:
			if primitive != nil {
				return nil, nil
			}
			primitive = part
		case part.Flags()&checker.TypeFlagsObject != 0:
			objects = append(objects, part)
		default:
			return nil, nil
		}
	}
	if primitive == nil || len(objects) == 0 {
		return nil, nil
	}
	return primitive, objects
}

func (l *lowering) phantomBase(proven *checker.Type) *checker.Type {
	primitive, objects := l.phantomParts(proven)
	if primitive == nil {
		return nil
	}
	for _, object := range objects {
		if len(l.checker.GetSignaturesOfType(object, checker.SignatureKindCall)) != 0 || len(l.checker.GetSignaturesOfType(object, checker.SignatureKindConstruct)) != 0 || len(l.checker.GetIndexInfosOfType(object)) != 0 {
			return nil
		}
		for _, field := range l.checker.GetPropertiesOfType(object) {
			if !phantomField(l.checker.GetTypeOfSymbol(field), field.Flags&ast.SymbolFlagsOptional != 0) || primitiveMember(primitive.Flags(), field.Name) {
				return nil
			}
		}
	}
	return primitive
}

func phantomField(proven *checker.Type, optional bool) bool {
	flags := proven.Flags()
	if flags&checker.TypeFlagsUnion != 0 {
		for _, part := range proven.Types() {
			if !phantomField(part, optional) {
				return false
			}
		}
		return true
	}
	return flags&checker.TypeFlagsVoid != 0 || optional && flags&checker.TypeFlagsUndefined != 0
}

// These inventories are the own names of boxed primitives and their complete prototype chains,
// observed on Node and independently checked in TestPhantomPrimitiveNames. The checker library is
// intentionally smaller than JavaScript's, so its declarations alone cannot prove absence.
var phantomObjectNames = strings.Fields("__defineGetter__ __defineSetter__ __lookupGetter__ __lookupSetter__ __proto__ constructor hasOwnProperty isPrototypeOf propertyIsEnumerable toLocaleString toString valueOf")
var phantomStringNames = strings.Fields("anchor at big blink bold charAt charCodeAt codePointAt concat endsWith fixed fontcolor fontsize includes indexOf isWellFormed italics lastIndexOf length link localeCompare match matchAll normalize padEnd padStart repeat replace replaceAll search slice small split startsWith strike sub substr substring sup toLocaleLowerCase toLocaleUpperCase toLowerCase toUpperCase toWellFormed trim trimEnd trimLeft trimRight trimStart")
var phantomNumberNames = strings.Fields("toExponential toFixed toPrecision")

func primitiveMember(flags checker.TypeFlags, name string) bool {
	if flags&(checker.TypeFlagsVoid|checker.TypeFlagsUndefined) != 0 {
		return false
	}
	if slices.Contains(phantomObjectNames, name) {
		return true
	}
	if flags&checker.TypeFlagsStringLike != 0 {
		if slices.Contains(phantomStringNames, name) {
			return true
		}
		// A string may have any nonnegative integer index below its length. Noncanonical spellings
		// such as 00 and -0 aren't string exotic own properties.
		index, err := strconv.ParseUint(name, 10, 64)
		return err == nil && index < 1<<53 && strconv.FormatUint(index, 10) == name
	}
	return flags&checker.TypeFlagsNumberLike != 0 && slices.Contains(phantomNumberNames, name)
}

func (l *lowering) phantomUndefined(proven *checker.Type) bool {
	if base := l.phantomBase(proven); base != nil {
		return base.Flags()&(checker.TypeFlagsVoid|checker.TypeFlagsUndefined) != 0
	}
	return false
}

// Branding may normalize a read contract without authorizing ordinary branded
// function results or erasure. Those retain the base's separate representation proof.
func (l *lowering) viewRepresentation(target *checker.Type) (ir.Type, bool) {
	if base := l.phantomBase(target); base != nil {
		return l.representation(base)
	}
	if target.Flags()&checker.TypeFlagsUnion != 0 {
		members := make([]*checker.Type, 0, len(target.Types()))
		for _, member := range target.Types() {
			if base := l.phantomBase(member); base != nil {
				member = base
			}
			members = append(members, member)
		}
		return l.representation(l.checker.GetUnionType(members))
	}
	return l.representation(target)
}

view_unions_mixed.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// Lane 1 calls this hook only after wiring member selection at reads.
var viewMixedUnionContractHook viewContractHook = internMixedUnionViewContract

// Intern a complete union graph using the shared member builder. This is not an
// admission hook until lane 1 wires selection and representation conversion.
// Reserve before recursion, but discard every newly reserved id on failure:
// a later lookup must not mistake a partial graph for a complete contract.
func internMixedUnionViewContract(l *lowering, node *ast.Node, target *checker.Type, build viewContractBuilder) (id ir.ViewContractID, err error) {
	if target.Flags()&checker.TypeFlagsUnion == 0 {
		return 0, l.notYet(node, "a mixed union contract for a non-union type")
	}
	of, known := l.viewRepresentation(target)
	if !known {
		return 0, l.notYet(node, "checked union representation for "+l.checker.TypeToString(target))
	}
	if build == nil {
		return 0, l.notYet(node, "a checked union without a recursive member builder")
	}
	if l.result.ViewContractTypes == nil {
		l.result.ViewContractTypes = map[int]ir.ViewContractID{}
	}
	if cached := l.result.ViewContractTypes[int(target.Id())]; cached != 0 {
		return cached, nil
	}
	start := len(l.result.ViewContracts)
	id = ir.ViewContractID(start + 1)
	contract := ir.ViewContract{Kind: ir.ViewUnion, Name: l.checker.TypeToString(target), Of: of}
	l.result.ViewContracts = append(l.result.ViewContracts, contract)
	l.result.ViewContractTypes[int(target.Id())] = id
	defer func() {
		if err == nil {
			return
		}
		l.result.ViewContracts = l.result.ViewContracts[:start]
		for key, value := range l.result.ViewContractTypes {
			if int(value) > start {
				delete(l.result.ViewContractTypes, key)
			}
		}
		id = 0
	}()
	for _, member := range target.Types() {
		var child ir.ViewContractID
		child, err = build(member)
		if err != nil {
			return 0, err
		}
		if child <= 0 || int(child) > len(l.result.ViewContracts) || l.result.ViewContracts[int(child)-1].Kind == ir.ViewUnknown {
			return 0, l.notYet(node, "an unavailable checked union member contract for "+l.checker.TypeToString(member))
		}
		contract.Members = append(contract.Members, child)
	}
	l.result.ViewContracts[int(id)-1] = contract
	return id, nil
}

view_unions_callable_members.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// Union membership admits only fixed scalar signatures until the callable
// adapter supplies stronger proofs. A physical object tag is never that proof.
func (l *lowering) untaggedCallableShape(target *checker.Type) bool {
	signatures := l.checker.GetSignaturesOfType(target, checker.SignatureKindCall)
	if len(signatures) != 1 || len(l.checker.GetSignaturesOfType(target, checker.SignatureKindConstruct)) != 0 {
		return false
	}
	signature := signatures[0]
	if len(signature.TypeParameters()) != 0 || signature.HasRestParameter() {
		return false
	}
	for _, parameter := range signature.Parameters() {
		of, known := l.representation(l.checker.GetTypeOfSymbol(parameter))
		if !known || !(of == ir.Number || of == ir.Boolean || of == ir.String || of == ir.MaybeNumber || of == ir.MaybeBoolean) {
			return false
		}
	}
	result := l.checker.GetReturnTypeOfSignature(signature)
	return interfaceScalar(result) || result.Flags()&checker.TypeFlagsVoid != 0
}

func (l *lowering) prepareUntaggedCallableMember(node *ast.Node, target *checker.Type) (ir.ViewContractID, error) {
	if !l.untaggedCallableShape(target) {
		return 0, l.notYet(node, "an untagged callable member without a fixed scalar signature")
	}
	if l.result.ViewContractTypes == nil {
		l.result.ViewContractTypes = map[int]ir.ViewContractID{}
	}
	id := l.result.ViewContractTypes[int(target.Id())]
	if id == 0 {
		id = ir.ViewContractID(len(l.result.ViewContracts) + 1)
		l.result.ViewContracts = append(l.result.ViewContracts, ir.ViewContract{})
		l.result.ViewContractTypes[int(target.Id())] = id
	}
	signature := l.checker.GetSignaturesOfType(target, checker.SignatureKindCall)[0]
	contract := ir.ViewContract{Kind: ir.ViewCallable, Of: ir.Closure, Name: l.checker.TypeToString(target)}
	for _, parameter := range signature.Parameters() {
		child, err := l.viewContract(node, l.checker.GetTypeOfSymbol(parameter))
		if err != nil {
			return 0, err
		}
		contract.Parameters = append(contract.Parameters, child)
	}
	result := l.checker.GetReturnTypeOfSignature(signature)
	if result.Flags()&checker.TypeFlagsVoid != 0 {
		contract.DiscardResult = true
	} else {
		child, err := l.viewContract(node, result)
		if err != nil {
			return 0, err
		}
		contract.Result = child
	}
	l.result.ViewContracts[id-1] = contract
	if l.untaggedCallableTargets == nil {
		l.untaggedCallableTargets = map[ir.ViewContractID]*checker.Type{}
	}
	l.untaggedCallableTargets[id] = target
	return id, nil
}

// This is descriptor construction, not an array consumer admission.
func (l *lowering) viewArrayElementType(target *checker.Type) *checker.Type {
	if !l.checker.IsArrayType(target) {
		return nil
	}
	return l.checker.GetElementTypeOfArrayType(target)
}

view_unions_untagged.go:
package lower

import (
	"fmt"

	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
)

// UntaggedViewMember retains the selected contract for later checked reads.
// Tags only filter candidates. A successful tag never certifies other fields.
type UntaggedViewMember struct {
	Contract ir.ViewContractID
	Tags     []UntaggedViewTag
}

type UntaggedViewTag struct {
	Field   string
	Allowed []ir.ViewLiteral
}

// UntaggedViewMembers plans an already interned object union at a read. It does
// not admit casts or certify a deferred member. Shared dispatch owns those jobs.
func UntaggedViewMembers(contracts []ir.ViewContract, union ir.ViewContractID) ([]UntaggedViewMember, error) {
	lookup := func(id ir.ViewContractID) (ir.ViewContract, error) {
		if id <= 0 || int(id) > len(contracts) {
			return ir.ViewContract{}, fmt.Errorf("unavailable checked-view contract %d", id)
		}
		return contracts[int(id)-1], nil
	}
	root, err := lookup(union)
	if err != nil {
		return nil, err
	}
	if root.Kind != ir.ViewUnion || len(root.Members) == 0 {
		return nil, fmt.Errorf("%s is not a nonempty object union", root.Name)
	}
	members := make([]UntaggedViewMember, 0, len(root.Members))
	for _, id := range root.Members {
		contract, err := lookup(id)
		if err != nil {
			return nil, err
		}
		if contract.Kind != ir.ViewObject || contract.Of != ir.Object {
			return nil, fmt.Errorf("union member %s needs its owning family adapter", contract.Name)
		}
		member := UntaggedViewMember{Contract: id}
		for _, field := range contract.Fields {
			// An absent optional tag is legal, so it cannot exclude this candidate.
			if field.Optional {
				continue
			}
			tag, err := lookup(field.Contract)
			if err != nil {
				return nil, err
			}
			if tag.Kind != ir.ViewScalar || len(tag.Allowed) == 0 {
				continue
			}
			for _, literal := range tag.Allowed {
				if literal.Of != ir.Number && literal.Of != ir.String && literal.Of != ir.Boolean {
					return nil, fmt.Errorf("unsupported tag contract %s.%s", contract.Name, field.Name)
				}
			}
			member.Tags = append(member.Tags, UntaggedViewTag{Field: field.Name, Allowed: append([]ir.ViewLiteral(nil), tag.Allowed...)})
		}
		members = append(members, member)
	}
	return members, nil
}

// Shared lazy dispatch calls this only for a demanded union read. Tagged
// members defer unread descendants. Field-only membership needs a complete,
// recursive plain-data contract; unavailable adapters remain named obligations.
func (l *lowering) supportsUntaggedRead(root ir.ViewContract) bool {
	seen := map[ir.ViewContractID]bool{}
	var supported func(ir.ViewContractID) bool
	supported = func(id ir.ViewContractID) bool {
		if id <= 0 || int(id) > len(l.result.ViewContracts) {
			return false
		}
		contract := l.result.ViewContracts[id-1]
		if (contract.Unsupported != "" && contract.Unsupported != "untagged object union") || contract.Nominal != "" {
			return false
		}
		if contract.Kind == ir.ViewScalar {
			return contract.Of == ir.Number || contract.Of == ir.String || contract.Of == ir.Boolean || contract.Of == ir.MaybeNumber || contract.Of == ir.MaybeBoolean
		}
		if contract.Kind == ir.ViewCallable {
			return contract.Result != 0 || contract.DiscardResult
		}
		if contract.Kind == ir.ViewUndefined {
			return true
		}
		if seen[id] {
			return true
		}
		seen[id] = true
		defer delete(seen, id)
		if contract.Kind == ir.ViewArray {
			return supported(contract.Element)
		}
		if contract.Kind == ir.ViewUnion {
			if len(contract.Members) == 0 {
				return false
			}
			for _, member := range contract.Members {
				if !supported(member) {
					return false
				}
			}
			return true
		}
		if contract.Kind != ir.ViewObject {
			return false
		}
		tagged := false
		for _, field := range contract.Fields {
			if field.Optional || field.Contract <= 0 || int(field.Contract) > len(l.result.ViewContracts) {
				continue
			}
			child := l.result.ViewContracts[field.Contract-1]
			tagged = tagged || child.Kind == ir.ViewScalar && (len(child.Allowed) != 0 || field.Name == "kind" && (child.Of == ir.Number || child.Of == ir.String || child.Of == ir.Boolean))
		}
		if tagged {
			return true
		}
		for _, field := range contract.Fields {
			if !supported(field.Contract) {
				return false
			}
		}
		return true
	}
	if root.Kind != ir.ViewUnion || root.Of != ir.Object || len(root.Members) == 0 {
		return false
	}
	for _, id := range root.Members {
		if !supported(id) {
			return false
		}
	}
	return true
}

// untaggedArrayElement joins only array members' logical element contracts.
// It never chooses an arbitrary member's physical representation.
func (l *lowering) untaggedArrayElement(target *checker.Type) *checker.Type {
	if element := l.viewArrayElementType(target); element != nil {
		return element
	}
	if target.Flags()&checker.TypeFlagsUnion == 0 {
		return nil
	}
	var elements []*checker.Type
	for _, member := range target.Types() {
		element := l.viewArrayElementType(member)
		if element == nil {
			return nil
		}
		elements = append(elements, element)
	}
	if len(elements) == 0 {
		return nil
	}
	return l.checker.GetUnionType(elements)
}

func (l *lowering) completeUntaggedRecursiveContracts() {
	// Optional array descriptors may be copied while their element is reserved.
	// Only a completed canonical descriptor can supply the missing element.
	for index, contract := range l.result.ViewContracts {
		if contract.Kind == ir.ViewArray && contract.Element == 0 && contract.ObjectPresent > 0 {
			canonical := l.result.ViewContracts[contract.ObjectPresent-1]
			if canonical.Kind == ir.ViewArray && canonical.Element > 0 {
				l.result.ViewContracts[index].Element = canonical.Element
			}
		}
	}

	for index, contract := range l.result.ViewContracts {
		if contract.Unsupported == "untagged object union" && l.supportsUntaggedRead(contract) {
			l.result.ViewContracts[index].Unsupported = ""
		}
	}
}

// Callable union membership uses each producer-certified member signature;
// the checker's synthesized union signature is not an implementation contract.
func (l *lowering) prepareUntaggedCallableUnionRead(node *ast.Node, target *checker.Type) (ir.ViewContractID, error) {
	id := l.result.ViewContractTypes[int(target.Id())]
	if id == 0 {
		id = ir.ViewContractID(len(l.result.ViewContracts) + 1)
		l.result.ViewContracts = append(l.result.ViewContracts, ir.ViewContract{})
		l.result.ViewContractTypes[int(target.Id())] = id
	}
	contract := ir.ViewContract{Kind: ir.ViewUnion, Of: ir.Closure, Name: l.checker.TypeToString(target)}
	for _, member := range target.Types() {
		if !l.callableViewContract(member) {
			return 0, l.notYet(node, "a callable union member without a producer signature")
		}
		child, err := l.prepareUntaggedCallableMember(node, member)
		if err != nil {
			return 0, err
		}
		if l.untaggedCallableTargets == nil {
			l.untaggedCallableTargets = map[ir.ViewContractID]*checker.Type{}
		}
		l.untaggedCallableTargets[child] = member
		l.result.ViewContracts[child-1].Unsupported = ""
		contract.Members = append(contract.Members, child)
	}
	l.result.ViewContracts[id-1] = contract
	return id, nil
}

// Prepare nested callable obligations using lane 5's existing descriptor builder.
// Only represented fixed scalar signatures are certified; errors stay lazy.
func (l *lowering) prepareUntaggedStructuralRead(node *ast.Node, target *checker.Type, seen map[*checker.Type]bool) {
	if target == nil || seen[target] {
		return
	}
	seen[target] = true
	if l.callableViewContract(target) {
		if l.untaggedCallableShape(target) {
			if id, err := l.prepareUntaggedCallableMember(node, target); err == nil {
				l.result.ViewContracts[id-1].Unsupported = ""
			}
		}
		return
	}
	if target.Flags()&checker.TypeFlagsUnion != 0 {
		for _, member := range target.Types() {
			l.prepareUntaggedStructuralRead(node, member, seen)
		}
		return
	}
	if element := l.untaggedArrayElement(target); element != nil {
		l.prepareUntaggedStructuralRead(node, element, seen)
		return
	}
	if target.Flags()&checker.TypeFlagsObject == 0 {
		return
	}
	for _, field := range l.checker.GetPropertiesOfType(target) {
		l.prepareUntaggedStructuralRead(node, l.checker.GetTypeOfSymbol(field), seen)
	}
}

// Reuse closureRecords' checker proof and lane 5's code-identity registry. Exact
// logical identity is conservative: physical Closure/Object tags alone do not
// certify higher-order arguments or object results.
func (l *lowering) certifyUntaggedCallableProducers() {
	for id, target := range l.untaggedCallableTargets {
		contract := &l.result.ViewContracts[id-1]
		contract.ProducerCertified = true
		contract.Functions = nil
		for _, producer := range l.closureRecords {
			if checker.Checker_isTypeIdenticalTo(l.checker, producer.proven, target) {
				contract.Functions = append(contract.Functions, producer.function)
			}
		}
	}
}
func certifiedUntaggedCallableRead(program *ir.Program, id ir.ViewContractID) bool {
	if id <= 0 || int(id) > len(program.ViewContracts) {
		return false
	}
	contract := program.ViewContracts[id-1]
	if contract.Unsupported != "" {
		return false
	}
	if contract.Kind == ir.ViewCallable {
		return contract.ProducerCertified
	}
	if contract.Kind != ir.ViewUnion || contract.Of != ir.Closure || len(contract.Members) == 0 {
		return false
	}
	for _, member := range contract.Members {
		if !certifiedUntaggedCallableRead(program, member) {
			return false
		}
	}
	return true
}

view_unions_dispatch.go:
package lower

import (
	"github.com/microsoft/TypeScript/tsc/shim/ast"
	"github.com/microsoft/TypeScript/tsc/shim/checker"
	"github.com/system-inc/adamic/internal/ir"
	"strconv"
)

// All members are interned before a union can supply a read certificate.
func buildUnionReadContract(l *lowering, node *ast.Node, target *checker.Type, build viewContractBuilder) (ir.ViewContractID, error) {
	if of, known := l.representation(target); known && of == ir.Closure {
		return l.prepareUntaggedCallableUnionRead(node, target)
	}
	l.prepareUntaggedStructuralRead(node, target, map[*checker.Type]bool{})
	id, err := internMixedUnionViewContract(l, node, target, build)
	if err != nil {
		return 0, err
	}
	contract := l.result.ViewContracts[id-1]
	contract.Undefined = l.includesUndefined(target)
	contract.Null = l.includesNull(target)
	for _, member := range contract.Members {
		child := l.result.ViewContracts[member-1]
		if child.Kind == ir.ViewArray {
			contract.Unsupported = "views-v3: array element kind: " + child.Name
		}
	}
	if contract.Of == ir.Object {
		for _, field := range l.checker.GetPropertiesOfType(target) {
			child, err := build(l.checker.GetTypeOfSymbol(field))
			if err != nil {
				return 0, err
			}
			contract.Fields = append(contract.Fields, ir.ViewFieldContract{Name: field.Name, Contract: child, Optional: field.Flags&ast.SymbolFlagsOptional != 0, Readonly: l.checker.IsReadonlySymbol(field)})
		}
		l.result.ViewContracts[id-1] = contract
		if contract.Unsupported == "" && !l.supportsUntaggedRead(contract) {
			contract.Unsupported = "untagged object union"
		}
	}
	l.result.ViewContracts[id-1] = contract
	return id, nil
}

// Union members need an element/position graph even before array consumers
// land. No standalone array consumer or dictionary adapter is registered here.
func (l *lowering) unionAggregateContract(node *ast.Node, target *checker.Type) (ir.ViewContractID, error) {
	if id := l.result.ViewContractTypes[int(target.Id())]; id != 0 {
		return id, nil
	}
	id := ir.ViewContractID(len(l.result.ViewContracts) + 1)
	contract := ir.ViewContract{Name: l.checker.TypeToString(target)}
	l.result.ViewContractTypes[int(target.Id())] = id
	l.result.ViewContracts = append(l.result.ViewContracts, contract)
	if checker.IsTupleType(target) {
		contract.Kind = ir.ViewObject
		contract.Of = ir.Object
		contract.FixedTuple = true
		for position, element := range l.checker.GetTypeArguments(target) {
			child, err := l.viewContract(node, element)
			if err != nil {
				return 0, err
			}
			flags := target.TargetTupleType().ElementFlags()
			if flags[position] != checker.ElementFlagsRequired {
				return 0, l.notYet(node, "a variable tuple checked-view contract")
			}
			contract.Tuple = append(contract.Tuple, child)
			contract.Fields = append(contract.Fields, ir.ViewFieldContract{Name: strconv.Itoa(position), Contract: child, Readonly: target.TargetTupleType().IsReadonly()})
		}
	} else {
		contract.Kind = ir.ViewArray
		contract.Unsupported = "views-v3: array element kind"
		contract.Of = ir.Array
		element := l.viewArrayElementType(target)
		if element == nil {
			return 0, l.notYet(node, "an unavailable array union element")
		}
		child, err := l.viewContract(node, element)
		if err != nil {
			return 0, err
		}
		contract.Element = child
	}
	l.result.ViewContracts[id-1] = contract
	return id, nil
}

// Only registered, complete union reads bypass the pre-existing slot refusal.
// The backend must run that certificate before returning the read value.
func (l *lowering) unionReadCertificate(node *ast.Node, of ir.Type) bool {
	if of != ir.Union {
		return false
	}
	symbol := l.checker.GetSymbolAtLocation(node.Name())
	if symbol == nil {
		return false
	}
	id := l.result.ViewContractTypes[int(l.checker.GetTypeOfSymbol(symbol).Id())]
	if id <= 0 || int(id) > len(l.result.ViewContracts) {
		return false
	}
	contract := l.result.ViewContracts[id-1]
	return contract.Kind == ir.ViewUnion && contract.Unsupported == "" && len(contract.Members) != 0
}
